    ret: Type.TypeId,
};

const HostedCatalogEntry = struct {
    template: names.ProcTemplate,
    external_symbol_name: names.ExternalSymbolNameId,
    dispatch_index: u32,
    order: []const u8,
    target_checked_module_digest: [32]u8,
    def_idx: u32,
};

const HostedProcedureKey = struct {
    checked_module_digest: [32]u8,
    def_idx: u32,
};

const HostedBindingView = struct {
    table: *const checked.HostedBindingTable,
    names: *const names.NameStore,
};

/// Pattern binders are dense IDs allocated by `CheckedBodyStore`. Most
/// short-lived contexts only instantiate types and never bind a pattern, so
/// defer materializing the dense table until the first binding is installed.
const BinderMap = struct {
    allocator: Allocator,
    binder_count: usize,
    locals: ?[]?DraftLocalId = null,
    active_count: usize = 0,

    const Entry = struct {
        binder: checked.PatternBinderId,
        local: DraftLocalId,
    };

    const Iterator = struct {
        locals: []const ?DraftLocalId,
        index: usize = 0,

        fn next(self: *Iterator) ?Entry {
            while (self.index < self.locals.len) {
                const binder_index = self.index;
                self.index += 1;
                if (self.locals[binder_index]) |local| {
                    return .{ .binder = @enumFromInt(@as(u32, @intCast(binder_index))), .local = local };
                }
            }
            return null;
        }
    };

    fn init(allocator: Allocator, binder_count: usize) Allocator.Error!BinderMap {
        return .{ .allocator = allocator, .binder_count = binder_count };
    }

    fn deinit(self: *BinderMap) void {
        if (self.locals) |locals| self.allocator.free(locals);
        self.* = undefined;
    }

    fn index(self: *const BinderMap, binder: checked.PatternBinderId) usize {
        const raw = @intFromEnum(binder);
        if (raw >= self.binder_count) Common.invariant("pattern binder was outside its checked body store");
        return raw;
    }

    fn get(self: *const BinderMap, binder: checked.PatternBinderId) ?DraftLocalId {
        const index_ = self.index(binder);
        const locals = self.locals orelse return null;
        return locals[index_];
    }

    fn put(self: *BinderMap, binder: checked.PatternBinderId, local: DraftLocalId) Allocator.Error!void {
        const index_ = self.index(binder);
        if (self.locals == null) {
            const locals = try self.allocator.alloc(?DraftLocalId, self.binder_count);
            @memset(locals, null);
            self.locals = locals;
        }
        const slot = &self.locals.?[index_];
        if (slot.* == null) self.active_count += 1;
        slot.* = local;
    }

    fn remove(self: *BinderMap, binder: checked.PatternBinderId) bool {
        const index_ = self.index(binder);
        const locals = self.locals orelse return false;
        const slot = &locals[index_];
        if (slot.* == null) return false;
        slot.* = null;
        self.active_count -= 1;
        return true;
    }

    fn contains(self: *const BinderMap, binder: checked.PatternBinderId) bool {
        return self.get(binder) != null;
    }

    fn count(self: *const BinderMap) usize {
        return self.active_count;
    }

    fn iterator(self: *const BinderMap) Iterator {
        return .{ .locals = self.locals orelse &.{} };
    }
};
const TypedBinder = struct {
    binder: checked.PatternBinderId,
    type_digest: names.TypeDigest,
};
const TypedBinders = std.AutoHashMap(TypedBinder, DraftLocalId);
const LexicalBinderEntry = struct {
    kind: u8,
    binder: u32,
    local: u32,
    type_digest: names.TypeDigest,
};
const DraftLocalProcDeclaration = struct {
    module: [32]u8,
    binder: checked.PatternBinderId,
    expr: checked.CheckedExprId,
    context_anchor: ?checked.CheckedStatementId,

    fn address(self: DraftLocalProcDeclaration) DraftLocalProcAddress {
        return .{ .module = self.module, .binder = self.binder, .expr = self.expr };
    }
};
const DraftLocalProcAddress = struct {
    module: [32]u8,
    binder: checked.PatternBinderId,
    expr: checked.CheckedExprId,
};
const LocalProcContext = struct {
    declaration: DraftLocalProcDeclaration,
    lexical_owner: DraftOwner,
    owner_template: names.ProcTemplate,
    base_key: names.TypeDigest,
    /// Stable specialization identity supplied directly when ConstStore
    /// restoration replaces source locals with newly materialized captures.
    /// Ordinary source contexts derive identity from `base_key` and entries.
    restored_specialization_key: ?names.TypeDigest = null,
    entries: []LexicalBinderEntry,
    evidence: EvidenceChain,
};

/// Producer-authored lexical context retained by a ConstStore closure. The
/// checked use supplies the exact local-procedure declaration; this scope
/// supplies the declaration context that existed before the closure body's
/// own arguments were bound.
const RestoredLocalProcScope = struct {
    source_context_digest: names.TypeDigest,
    base_key: names.TypeDigest,
    entries: []const LexicalBinderEntry,
};

const StoredConstFnEvidence = struct {
    nodes: []const check.ConstStore.ConstFnEvidence,
    frames: []const check.ConstStore.ConstFnEvidenceFrame,
    head: ?u32,
};

fn specializationEvidenceView(evidence: StoredConstFnEvidence) specialize.EvidenceView {
    return .{ .nodes = evidence.nodes, .frames = evidence.frames, .head = evidence.head };
}

fn storedConstFnEvidenceEql(left: StoredConstFnEvidence, right: StoredConstFnEvidence) bool {
    if (left.head != right.head or left.nodes.len != right.nodes.len or left.frames.len != right.frames.len) return false;
    for (left.nodes, right.nodes) |left_node, right_node| {
        if (!std.meta.eql(left_node, right_node)) return false;
    }
    for (left.frames, right.frames) |left_frame, right_frame| {
        if (!std.meta.eql(left_frame, right_frame)) return false;
    }
    return true;
}

fn programViewFnEvidence(program: Ast.ProgramView, template: Ast.FnTemplate) StoredConstFnEvidence {
    return .{
        .nodes = program.constFnEvidence(template.const_evidence),
        .frames = program.constFnEvidenceFrames(template.const_evidence_frames),
        .head = template.const_evidence_frame_head,
    };
}

fn retainedFnEvidence(
    fns: []const Ast.Fn,
    evidence: []const check.ConstStore.ConstFnEvidence,
    frames: []const check.ConstStore.ConstFnEvidenceFrame,
    fn_id: Ast.FnId,
) StoredConstFnEvidence {
    const raw_fn = @intFromEnum(fn_id);
    if (raw_fn >= fns.len) Common.invariant("loaded specialization evidence referenced an absent function");
    const template = fns[raw_fn].source;
    const evidence_end = std.math.add(usize, template.const_evidence.start, template.const_evidence.len) catch
        Common.invariant("loaded specialization evidence span overflowed");
    const frames_end = std.math.add(usize, template.const_evidence_frames.start, template.const_evidence_frames.len) catch
        Common.invariant("loaded specialization evidence frame span overflowed");
    if (evidence_end > evidence.len or frames_end > frames.len) {
        Common.invariant("loaded specialization evidence span exceeded its retained section");
    }
    if (template.const_evidence_frame_head) |head| {
        if (head >= template.const_evidence_frames.len) {
            Common.invariant("loaded specialization evidence head exceeded its retained frame span");
        }
    } else if (template.const_evidence_frames.len != 0) {
        Common.invariant("loaded specialization evidence frames had no explicit head");
    }
    return .{
        .nodes = evidence[template.const_evidence.start..evidence_end],
        .frames = frames[template.const_evidence_frames.start..frames_end],
        .head = template.const_evidence_frame_head,
    };
}

/// Pass-local lowering state for one procedure template specialization,
/// keyed by the specialization's function id. Its identity, type views, and
/// status live on the `Ast.SpecRecord` owned by `spec_store`; this entry only
/// remembers which definition receives the body. Every path that reserves a
/// proc-template record in `spec_store` must register its entry here, or the
/// next reuse lookup hits the missing-lowering-state invariant.
const LoweredTemplate = struct {
    def: Ast.DefId,
    spec: Ast.SpecId,
    /// Evidence for the template scheme's dispatch requirements, in enumeration
    /// evidence-param order, supplied by the first requesting edge. Reused
    /// specializations debug-assert later edges agree (evidence is a function
    /// of the monomorphic type, so agreement is an invariant, not a choice).
    evidence: []const SpecEvidence = &.{},
    /// Exact durable topology for the complete lexical evidence chain.
    topology: ?StoredConstFnEvidence = null,
};

const TemplateReservation = struct {
    def: Ast.DefId,
    fn_id: Ast.FnId,
    symbol: Common.Symbol,
};

/// One root body lowered into a shared root batch. Its checked type graph is
/// still instantiated in a fresh scope; only the graph and draft stores are
/// shared so an exact specialization discovered by an earlier root can be
/// reused before another root replays and lowers it.
const PendingRootTemplateBody = struct {
    reservation: TemplateReservation,
    fn_template: Ast.FnTemplate,
    signature_relation: Ast.SignatureRelation,
    root_node: NodeId,
    lowered: LoweredTemplateBody,
};

const RootTemplateBatch = struct {
    graph: *InstGraph,
    draft: *BodyDraftStore,
    pending: std.ArrayList(PendingRootTemplateBody) = .empty,
};

const FinalBodyOutputCounts = struct {
    exprs: usize = 0,
    pats: usize = 0,
    locals: usize = 0,
    typed_locals: usize = 0,
    layout_requests: usize = 0,
    runtime_schema_requests: usize = 0,

    fn fromProgram(program: *const Ast.Program) FinalBodyOutputCounts {
        return .{
            .exprs = program.exprCount(),
            .pats = program.patCount(),
            .locals = program.localCount(),
            .typed_locals = program.typedLocalCount(),
            .layout_requests = program.layoutRequestCount(),
            .runtime_schema_requests = program.runtimeSchemaRequestCount(),
        };
    }

    fn addDelta(self: *FinalBodyOutputCounts, before: FinalBodyOutputCounts, after: FinalBodyOutputCounts) void {
        self.exprs += after.exprs - before.exprs;
        self.pats += after.pats - before.pats;
        self.locals += after.locals - before.locals;
        self.typed_locals += after.typed_locals - before.typed_locals;
        self.layout_requests += after.layout_requests - before.layout_requests;
        self.runtime_schema_requests += after.runtime_schema_requests - before.runtime_schema_requests;
    }
};

fn localFnIdFromSlot(slot: Ast.FnSlot, comptime message: []const u8) Ast.FnId {
    return switch (slot) {
        .local => |fn_id| fn_id,
        .imported => Common.invariant(message),
    };
}

