/// Key for a memoized structural-derivation helper def. `value_ty` is the type
/// being derived over; `result_ty` is the derivation's auxiliary type (the
/// produced Str for inspect, the Bool for equality, the Hasher for hashing).
///
/// These memos are deliberately NOT specialization records in `spec_store`:
/// helper defs have no `FnId` (they are `def_ref` targets, not callable
/// specializations), and their keys are process-local interned type ids with
/// no durable digest, so they cannot participate in cross-shard reuse. The
/// specialization identity story lives entirely in `specialize.SpecBuilder`.
const GeneratedHelperDefAddress = struct {
    value_ty: u32,
    result_ty: u32,
};

/// Exact Monotype inputs for one generated structural encoder helper. These
/// helpers belong to the active body draft: they capture that encoder
/// construction's encoding value and precomputed field names, while their
/// value and state are explicit arguments.
const GeneratedEncoderDefAddress = struct {
    value_ty: u32,
    encoding_ty: u32,
    state_ty: u32,
    result_ty: u32,
};

const GeneratedParserDefAddress = struct {
    value_ty: u32,
    encoding_ty: u32,
    state_ty: u32,
    result_ty: u32,
};

/// Process-local O(1) reuse key for a checker-classified closed direct
/// procedure call. `evidence` is an interned producer identity in `module`;
/// the plan's closed callable type is likewise structurally interned there.
/// The method scope remains part of specialization identity because imported
/// bodies resolve compiler-generated method calls in that scope.
const ClosedDirectCallIdentity = struct {
    callable: CheckedTypeAddress,
    evidence: static_dispatch.EvidenceNodeId,
    method_scope: checked.ModuleId,
};

/// Tracks a memoized structural-derivation helper def (is_eq / inspect /
/// to_hash). `reserved` means the def id is allocated but its body has not yet
/// been filled in (used to break recursion); `ready` means the body is complete.
const GeneratedHelperDefEntry = union(enum) {
    reserved: Ast.DefId,
    ready: Ast.DefId,

    fn id(self: GeneratedHelperDefEntry) Ast.DefId {
        return switch (self) {
            .reserved => |def_id| def_id,
            .ready => |def_id| def_id,
        };
    }
};

const DraftGeneratedHelperDefEntry = union(enum) {
    reserved: DraftDefId,
    ready: DraftDefId,

    fn id(self: DraftGeneratedHelperDefEntry) DraftDefId {
        return switch (self) {
            .reserved => |def_id| def_id,
            .ready => |def_id| def_id,
        };
    }
};

fn templateSpecIdentity(
    template_ref: names.ProcTemplate,
    method_scope: checked.ModuleId,
    source_fn_key: names.TypeDigest,
    evidence_digest: Ast.EvidenceDigest,
    request_fn_ty: Type.TypeId,
    request_fn_ty_digest: names.TypeDigest,
) Ast.SpecIdentity {
    return .{
        .callable = .{ .proc_template = .{
            .module = names.procTemplateModuleDigest(template_ref),
            .proc_base = @intFromEnum(template_ref.proc_base),
            .template = @intFromEnum(template_ref.template),
        } },
        .method_scope = moduleDigestFromId(method_scope),
        .source_fn_ty_digest = source_fn_key,
        .evidence_digest = evidence_digest,
        .request_fn_ty_digest = request_fn_ty_digest,
        .request_fn_ty = request_fn_ty,
    };
}

fn nestedSpecIdentity(
    nested: Ast.NestedFn,
    method_scope: checked.ModuleId,
    source_fn_key: names.TypeDigest,
    evidence_digest: Ast.EvidenceDigest,
    capture_abi_digest: names.TypeDigest,
    request_fn_ty: Type.TypeId,
    request_fn_ty_digest: names.TypeDigest,
) Ast.SpecIdentity {
    var context_hasher = std.crypto.hash.sha2.Sha256.init(.{});
    context_hasher.update("roc.monotype.nested_capture_abi");
    context_hasher.update(&nested.context_fn_key.bytes);
    context_hasher.update(&capture_abi_digest.bytes);
    return .{
        .callable = .{ .nested_site = .{
            .module = names.procTemplateModuleDigest(nested.owner),
            .owner_proc_base = @intFromEnum(nested.owner.proc_base),
            .owner_template = @intFromEnum(nested.owner.template),
            .owner_fn_digest = .{ .bytes = context_hasher.finalResult() },
            .site = @intFromEnum(nested.site),
        } },
        .method_scope = moduleDigestFromId(method_scope),
        .source_fn_ty_digest = source_fn_key,
        .evidence_digest = evidence_digest,
        .request_fn_ty_digest = request_fn_ty_digest,
        .request_fn_ty = request_fn_ty,
    };
}

const Builder = struct {
    allocator: Allocator,
    modules: Common.CheckedModules,
    root_view: checked.ImportedModuleView,
    program: *Ast.Program,
    proc_debug_names: bool,
    specialization_cache: SpecializationCacheControl,
    loaded_specialization_shards: []const LoadedSpecializationShard,
    counters: ?*SpecializationCounters,
    diagnostics: ?*Diagnostics,
    inline_expects: InlineExpectMode,
    static_data_literals: bool,
    target_usize: base.target.TargetUsize,
    timing: ?*Timing,
    symbols: Common.SymbolGen = .{},
    next_instantiation_scope: u64 = 0,
    type_cache: std.AutoHashMap(CheckedTypeAddress, Type.TypeId),
    /// Exact inhabitation answers for sealed Monotype types. These types are
    /// immutable, so the structural walk is needed at most once per TypeId.
    uninhabited_type_cache: collections.DenseMap(Type.TypeId, bool),
    spec_store: specialize.SpecBuilder,
    lowered_templates: collections.DenseMap(Ast.FnId, LoweredTemplate),
    /// Nested-fn specialization records keyed by function id; the durable
    /// identity and status live on the `Ast.SpecRecord`.
    lowered_nested_by_fn: collections.DenseMap(Ast.FnId, Ast.SpecId),
    nested_site_cache: std.AutoHashMap(NestedSiteAddress, names.ProcSiteId),
    const_expr_cache: std.AutoHashMap(ConstExprAddress, Ast.ExprId),
    static_data_ids: std.AutoHashMap(StaticDataUse, Common.StaticDataId),
    /// Static-data uses indexed by `StaticDataId`. Raw Monotype ids
    /// are only a fast exact-key path; exact structural equality below is the
    /// authority for reusing one representation across equivalent
    /// instantiations.
    static_data_uses: std.ArrayList(StaticDataUse),
    static_data_eligibility: std.AutoHashMap(ConstNodeAddress, bool),
    inspect_defs: std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry),
    equality_defs: std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry),
    hash_defs: std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry),
    hosted_catalog: []HostedCatalogEntry = &.{},
    /// Exact `(owner, method)` -> target map over every reachable module's
    /// method registry, for compiler-generated component lookups (structural
    /// derivation internals, inspect/parser/encode helpers, path synthesis).
    /// Built once; keys use the same program-name interning as `typeDef`, so
    /// owners derived from monomorphic type content correlate directly.
    /// Scoped method-target resolutions. The same owner and method pair may
    /// resolve to different targets depending on which module's method-lookup
    /// registry scope applies. Checked modules output the ordered registry
    /// scope; this memo only accelerates repeated exact lookups during the
    /// build and never changes the checked outcome.
    scoped_method_targets: std.AutoHashMapUnmanaged(ScopedMethodDispatch, ScopedMethodResolution) = .{},
    /// Exact checked identity of the compiler-provided `Try` nominal. `Try`
    /// deliberately retains nominal static-dispatch ownership, so it cannot use
    /// `builtin_owner`; structural parser lowering still needs its producer
    /// identity to distinguish optional fields from user nominals that declare
    /// a custom `parser_for` method.
    builtin_try_def: ?Type.TypeDef = null,
    u64_ty: ?Type.TypeId = null,
    bool_ty: ?Type.TypeId = null,
    /// The specialization graph currently being lowered. Template body
    /// requests made anywhere inside that specialization defer to its end,
    /// when its types are final and specialization keys are stable.
    active_graph: ?*InstGraph = null,
    /// Body draft owned by `active_graph`. Nested functions and procedure
    /// bodies that explicitly depend on local lexical evidence append here;
    /// context-free procedure requests retain only their live interfaces and
    /// resolve after this graph seals.
    active_body_draft: ?*BodyDraftStore = null,
    /// The globally reserved root owned by `active_graph`, if that graph is
    /// lowering a procedure body. Its explicit ownership and initial argument
    /// classes classify recursive calls without folding unrelated sibling
    /// requests together.
    active_template_root: ?ActiveTemplateRoot = null,
    final_body_output_allowance: FinalBodyOutputCounts = .{},
    /// Owns every materialized `SpecEvidence` tree; freed wholesale with the
    /// builder.
    evidence_arena: std.heap.ArenaAllocator,

    fn init(allocator: Allocator, modules: Common.CheckedModules, program: *Ast.Program, options: Options) Builder {
        const counters = options.specialization_counters orelse
            if (options.diagnostics) |diagnostics| &diagnostics.specialization else null;
        var spec_store = specialize.SpecBuilder.init(allocator, &program.names, &program.types, &program.specs);
        spec_store.counters = counters;
        return .{
            .allocator = allocator,
            .modules = modules,
            .root_view = checked.importedView(modules.root.module),
            .program = program,
            .proc_debug_names = options.proc_debug_names,
            .specialization_cache = options.specialization_cache,
            .loaded_specialization_shards = options.loaded_specialization_shards,
            .counters = counters,
            .diagnostics = options.diagnostics,
            .inline_expects = options.inline_expects,
            .static_data_literals = options.static_data_literals,
            .target_usize = options.target_usize,
            .timing = options.timing,
            .type_cache = std.AutoHashMap(CheckedTypeAddress, Type.TypeId).init(allocator),
            .uninhabited_type_cache = collections.DenseMap(Type.TypeId, bool).init(allocator),
            .spec_store = spec_store,
            .lowered_templates = collections.DenseMap(Ast.FnId, LoweredTemplate).init(allocator),
            .lowered_nested_by_fn = collections.DenseMap(Ast.FnId, Ast.SpecId).init(allocator),
            .nested_site_cache = std.AutoHashMap(NestedSiteAddress, names.ProcSiteId).init(allocator),
            .const_expr_cache = std.AutoHashMap(ConstExprAddress, Ast.ExprId).init(allocator),
            .static_data_ids = std.AutoHashMap(StaticDataUse, Common.StaticDataId).init(allocator),
            .static_data_uses = .empty,
            .static_data_eligibility = std.AutoHashMap(ConstNodeAddress, bool).init(allocator),
            .inspect_defs = std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry).init(allocator),
            .equality_defs = std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry).init(allocator),
            .hash_defs = std.AutoHashMap(GeneratedHelperDefAddress, GeneratedHelperDefEntry).init(allocator),
            .evidence_arena = std.heap.ArenaAllocator.init(allocator),
        };
    }

    fn loadCandidateSpecializationShards(self: *Builder) Allocator.Error!void {
        if (!self.specialization_cache.read) return;

        for (self.loaded_specialization_shards, 0..) |shard, shard_index| {
            if (shard.shard_id == .local) {
                Common.invariant("loaded Monotype specialization shard used the local shard id");
            }
            for (self.loaded_specialization_shards[0..shard_index]) |prior| {
                if (prior.shard_id == shard.shard_id) {
                    Common.invariant("loaded Monotype specialization shards reused a shard id");
                }
            }
            for (shard.specs) |record| {
                if (record.status != .ready) {
                    Common.invariant("loaded Monotype specialization shard contained an unfinished record");
                }
                const imported = try self.program.addImportedFn(.{
                    .shard = shard.shard_id,
                    .fn_id = record.fn_id,
                });
                const evidence = retainedFnEvidence(
                    shard.fns,
                    shard.const_fn_evidence,
                    shard.const_fn_evidence_frames,
                    record.fn_id,
                );
                _ = try self.spec_store.insertLoadedReady(record, shard.types, imported, specializationEvidenceView(evidence));
            }
        }
    }

    fn importedFnEvidence(self: *Builder, id: Ast.ImportedFnId) StoredConstFnEvidence {
        const imported_fns = self.program.importedFnsView();
        const raw_id = @intFromEnum(id);
        if (raw_id >= imported_fns.len) {
            Common.invariant("imported specialization evidence referenced an absent import");
        }
        const imported = imported_fns[raw_id];
        for (self.loaded_specialization_shards) |shard| {
            if (shard.shard_id != imported.shard) continue;
            return retainedFnEvidence(
                shard.fns,
                shard.const_fn_evidence,
                shard.const_fn_evidence_frames,
                imported.fn_id,
            );
        }
        Common.invariant("imported specialization evidence referenced an absent loaded shard");
    }

    fn importedFnSignatureRelation(self: *Builder, id: Ast.ImportedFnId) Ast.SignatureRelation {
        const imported_fns = self.program.importedFnsView();
        const raw_id = @intFromEnum(id);
        if (raw_id >= imported_fns.len) {
            Common.invariant("imported specialization signature referenced an absent import");
        }
        const imported = imported_fns[raw_id];
        for (self.loaded_specialization_shards) |shard| {
            if (shard.shard_id != imported.shard) continue;
            const raw_fn = @intFromEnum(imported.fn_id);
            if (raw_fn >= shard.fns.len) {
                Common.invariant("imported specialization signature referenced an absent shard function");
            }
            return shard.fns[raw_fn].signature_relation;
        }
        Common.invariant("imported specialization signature referenced an absent loaded shard");
    }

    fn deinit(self: *Builder) void {
        self.scoped_method_targets.deinit(self.allocator);
        self.allocator.free(self.hosted_catalog);
        self.hash_defs.deinit();
        self.equality_defs.deinit();
        self.inspect_defs.deinit();
        self.static_data_eligibility.deinit();
        self.static_data_uses.deinit(self.allocator);
        self.static_data_ids.deinit();
        self.const_expr_cache.deinit();
        self.nested_site_cache.deinit();
        self.lowered_nested_by_fn.deinit();
        self.lowered_templates.deinit();
        self.spec_store.deinit();
        self.uninhabited_type_cache.deinit();
        self.type_cache.deinit();
        self.evidence_arena.deinit();
    }

    fn count(self: *Builder, comptime field: []const u8) void {
        if (self.counters) |counters| {
            @field(counters, field) += 1;
        }
    }

    fn countBy(self: *Builder, comptime field: []const u8, amount: usize) void {
        if (self.counters) |counters| {
            @field(counters, field) += @intCast(amount);
        }
    }

    fn countBodyDiagnostic(self: *Builder, comptime field: []const u8) void {
        if (self.diagnostics) |diagnostics| {
            @field(diagnostics.body, field) += 1;
        }
    }

    fn countBodyDiagnosticBy(self: *Builder, comptime field: []const u8, amount: usize) void {
        if (self.diagnostics) |diagnostics| {
            @field(diagnostics.body, field) += @intCast(amount);
        }
    }

    fn allocateInstantiationScope(self: *Builder) InstantiationScopeId {
        if (self.next_instantiation_scope == std.math.maxInt(u64)) {
            Common.invariant("Monotype instantiation scope identity exhausted");
        }
        const id: InstantiationScopeId = @enumFromInt(self.next_instantiation_scope);
        self.next_instantiation_scope += 1;
        self.countBodyDiagnostic("instantiation_scopes_created");
        return id;
    }

    fn createGraph(self: *Builder) Allocator.Error!*InstGraph {
        const graph = try InstGraph.create(self.allocator, &self.program.types, &self.program.names);
        if (self.diagnostics) |diagnostics| {
            diagnostics.body.graphs_created += 1;
            graph.setDiagnostics(&diagnostics.graph);
        }
        return graph;
    }

    fn specializationTypeDigest(self: *Builder, ty: Type.TypeId) names.TypeDigest {
        if (self.counters != null) {
            self.count("specialization_type_digest_requests");
            var stats: Type.Store.DigestStats = .{};
            const digest = self.program.types.specializationDigestCached(&self.program.names, ty, &stats);
            self.countBy("specialization_type_digest_cache_hits", @intCast(stats.cache_hits));
            self.countBy("specialization_type_digest_cache_misses", @intCast(stats.cache_misses));
            self.countBy("specialization_type_digest_nodes_visited", @intCast(stats.nodes_visited));
            return digest;
        }
        return self.program.types.specializationDigestCached(&self.program.names, ty, null);
    }

    fn sealedCaptureAbiDigest(
        self: *Builder,
        sealer: *GraphTypeFinals,
        capture_nodes: []const NodeId,
    ) Allocator.Error!names.TypeDigest {
        var hasher = std.crypto.hash.sha2.Sha256.init(.{});
        hasher.update("roc.monotype.capture_abi");
        hashU32(&hasher, @intCast(capture_nodes.len));
        for (capture_nodes) |node| {
            const ty = try sealer.sealNode(node);
            const digest = self.program.types.typeDigest(&self.program.names, ty);
            hasher.update(&digest.bytes);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn initHostedCatalog(self: *Builder) Allocator.Error!void {
        var entries = std.ArrayList(HostedCatalogEntry).empty;
        errdefer entries.deinit(self.allocator);

        try self.appendHostedCatalogFromView(&entries, moduleView(self.root_view));
        for (self.modules.imports, 0..) |imported, index| {
            if (self.importModuleAlreadyScanned(imported.key, index)) continue;
            try self.appendHostedCatalogFromView(&entries, moduleView(imported));
        }
        for (self.modules.root.relation_modules, 0..) |relation, index| {
            if (self.relationModuleAlreadyScanned(relation.key, index)) continue;
            try self.appendHostedCatalogFromView(&entries, moduleView(relation));
        }

        if (self.hostedBindingView()) |binding_view| {
            if (entries.items.len != binding_view.table.bindings.len) {
                Common.invariantFmt(
                    "platform hosted binding count {d} disagrees with hosted catalog size {d}",
                    .{ binding_view.table.bindings.len, entries.items.len },
                );
            }

            var entries_by_target = std.AutoHashMap(HostedProcedureKey, usize).init(self.allocator);
            defer entries_by_target.deinit();
            try entries_by_target.ensureTotalCapacity(@intCast(entries.items.len));
            for (entries.items, 0..) |entry, index| {
                entries_by_target.putAssumeCapacityNoClobber(.{
                    .checked_module_digest = entry.target_checked_module_digest,
                    .def_idx = entry.def_idx,
                }, index);
            }

            for (binding_view.table.bindings, 0..) |binding, dispatch_index| {
                const entry_index = entries_by_target.get(.{
                    .checked_module_digest = binding.target_checked_module.bytes,
                    .def_idx = @intFromEnum(binding.target_def),
                }) orelse Common.invariant("hosted function is missing from the checked hosted binding table");
                entries.items[entry_index].dispatch_index = @intCast(dispatch_index);
                entries.items[entry_index].external_symbol_name = try self.program.names.internExternalSymbolName(
                    binding_view.names.externalSymbolNameText(binding.external_symbol_name),
                );
            }

            const DispatchSort = struct {
                pub fn lessThan(_: void, a: HostedCatalogEntry, b: HostedCatalogEntry) bool {
                    return a.dispatch_index < b.dispatch_index;
                }
            };
            std.mem.sort(HostedCatalogEntry, entries.items, {}, DispatchSort.lessThan);
        } else {
            const SortContext = struct {
                pub fn lessThan(_: void, a: HostedCatalogEntry, b: HostedCatalogEntry) bool {
                    return switch (std.mem.order(u8, a.order, b.order)) {
                        .lt => true,
                        .gt => false,
                        .eq => if (a.def_idx != b.def_idx)
                            a.def_idx < b.def_idx
                        else
                            std.mem.order(u8, &a.target_checked_module_digest, &b.target_checked_module_digest) == .lt,
                    };
                }
            };
            std.mem.sort(HostedCatalogEntry, entries.items, {}, SortContext.lessThan);
            for (entries.items, 0..) |*entry, index| {
                entry.dispatch_index = @intCast(index);
            }
        }

        self.hosted_catalog = try entries.toOwnedSlice(self.allocator);
    }

    fn hostedBindingView(self: *Builder) ?HostedBindingView {
        const root = moduleView(self.root_view);
        if (root.module_identity.kind == .platform) {
            return .{ .table = root.hosted_bindings, .names = root.names };
        }
        for (self.modules.imports) |imported| {
            const view = moduleView(imported);
            if (view.module_identity.kind == .platform) {
                return .{ .table = view.hosted_bindings, .names = view.names };
            }
        }
        for (self.modules.root.relation_modules) |relation| {
            const view = moduleView(relation);
            if (view.module_identity.kind == .platform) {
                return .{ .table = view.hosted_bindings, .names = view.names };
            }
        }
        return null;
    }

    fn appendHostedCatalogFromView(self: *Builder, entries: *std.ArrayList(HostedCatalogEntry), view: ModuleView) Allocator.Error!void {
        for (view.hosted_procs.procs) |proc| {
            try entries.append(self.allocator, .{
                .template = proc.template,
                .external_symbol_name = try self.program.names.internExternalSymbolName(view.names.externalSymbolNameText(proc.external_symbol_name)),
                .dispatch_index = 0,
                .order = proc.orderKey(view.hosted_procs),
                .target_checked_module_digest = view.key.bytes,
                .def_idx = @intFromEnum(proc.def_idx),
            });
        }
    }

    fn hostedFn(self: *Builder, template: names.ProcTemplate) Ast.HostedFn {
        for (self.hosted_catalog) |entry| {
            if (!names.procedureTemplateRefEql(entry.template, template)) continue;
            return .{
                .template = template,
                .external_symbol_name = entry.external_symbol_name,
                .dispatch_index = entry.dispatch_index,
            };
        }
        Common.invariant("hosted procedure template was not output in the hosted catalog");
    }

    /// Whether an extern boundary may be emitted at `emitted_fn_ty`: the host
    /// ABI (design.md "Host Symbol ABI") admits the hosted declaration's own
    /// checked type, lowered here as `declared_fn_ty`, and nothing else.
    ///
    /// The comparison is the authoritative structural one, not a type digest. A
    /// digest encodes a cycle by the position it closes at, so a recursive
    /// nominal reached through differently shared nodes digests differently
    /// while describing one runtime type—and a hosted argument is exactly
    /// where that happens, since the declared lowering and the request build
    /// their graphs separately. test/fx/host_boxed_fn_boundary.roc passes a
    /// recursive nominal to a hosted function and covers that case.
    ///
    /// A hosted declaration written with type variables is a scheme rather than
    /// one type, and the host's single C signature covers every instantiation
    /// because each variable position is a pointer at runtime. For those, the
    /// declaration's variable slots accept whatever the request instantiated
    /// them to, while every position the declaration made concrete is still
    /// compared exactly.
    fn hostedExternMatchesDeclaredAbi(
        self: *Builder,
        declared_fn_ty: Type.TypeId,
        emitted_fn_ty: Type.TypeId,
        mode: Type.TypeMatchMode,
    ) Allocator.Error!bool {
        return try self.program.types.typeMatches(&self.program.names, declared_fn_ty, emitted_fn_ty, mode);
    }

    /// The match mode a hosted declaration's own checked type calls for.
    fn hostedDeclaredAbiMatchMode(
        self: *Builder,
        view: ModuleView,
        declared_checked_fn_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeMatchMode {
        return if (try self.hostedDeclarationIsGeneric(view, declared_checked_fn_ty))
            .declared_variable_slots_match_any
        else
            .exact;
    }

    /// Whether a hosted declaration's checked type still contains type
    /// variables. A variable that carries a numeric or row default is not one:
    /// it lowers to the same concrete type for every use, so the declaration is
    /// concrete there.
    fn hostedDeclarationIsGeneric(
        self: *Builder,
        view: ModuleView,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        return try self.checkedTypeHasVariable(view, checked_ty, &seen);
    }

    fn checkedTypeHasVariable(
        self: *Builder,
        view: ModuleView,
        checked_ty: checked.CheckedTypeId,
        seen: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        if ((try seen.getOrPut(checked_ty)).found_existing) return false;
        switch (checkedPayload(view, checked_ty)) {
            .flex, .rigid => |variable| {
                return variable.numeric_default_phase == null and variable.row_default == null;
            },
            .pending, .err, .empty_record, .empty_tag_union => return false,
            .alias => |alias| {
                if (try self.checkedTypeSliceHasVariable(view, alias.args, seen)) return true;
                return try self.checkedTypeHasVariable(view, alias.backing, seen);
            },
            // A nominal's runtime shape follows from its declaration and its
            // arguments, so the arguments carry every variable a use can fill.
            .nominal => |nominal| return try self.checkedTypeSliceHasVariable(view, nominal.args, seen),
            .record => |record| {
                for (record.fields) |field| {
                    if (try self.checkedTypeHasVariable(view, field.ty, seen)) return true;
                }
                return try self.checkedTypeHasVariable(view, record.ext, seen);
            },
            .record_unbound => |fields| {
                for (fields) |field| {
                    if (try self.checkedTypeHasVariable(view, field.ty, seen)) return true;
                }
                return false;
            },
            .tuple => |items| return try self.checkedTypeSliceHasVariable(view, items, seen),
            .tag_union => |tag_union| {
                for (tag_union.tags) |tag| {
                    if (try self.checkedTypeSliceHasVariable(view, tag.argsSlice(view.types), seen)) return true;
                }
                return try self.checkedTypeHasVariable(view, tag_union.ext, seen);
            },
            .function => |fn_ty| {
                if (try self.checkedTypeSliceHasVariable(view, fn_ty.args, seen)) return true;
                return try self.checkedTypeHasVariable(view, fn_ty.ret, seen);
            },
        }
    }

    fn checkedTypeSliceHasVariable(
        self: *Builder,
        view: ModuleView,
        types: []const checked.CheckedTypeId,
        seen: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        for (types) |ty| {
            if (try self.checkedTypeHasVariable(view, ty, seen)) return true;
        }
        return false;
    }

    /// Stop the build unless this hosted specialization emits its extern at
    /// the declared host ABI type.
    ///
    /// The host was compiled against the declared signature. An extern emitted
    /// at any other type reads the host's return value at a layout the host
    /// never wrote—the app sees `Err` where the host returned `Ok`—and
    /// nothing downstream can tell that apart from a genuine `Err`. So this is
    /// a producer-side stop, in release builds as well as debug ones: whatever
    /// upstream stage widened, narrowed, or re-represented the request, its
    /// output never reaches codegen.
    fn requireHostedExternAtDeclaredAbi(
        self: *Builder,
        view: ModuleView,
        template: names.ProcTemplate,
        declared_checked_fn_ty: checked.CheckedTypeId,
        declared_fn_ty: Type.TypeId,
        emitted_fn_ty: Type.TypeId,
    ) Allocator.Error!void {
        const mode = try self.hostedDeclaredAbiMatchMode(view, declared_checked_fn_ty);
        if (try self.hostedExternMatchesDeclaredAbi(declared_fn_ty, emitted_fn_ty, mode)) return;
        var message_buf: [hosted_extern_abi_message_max]u8 = undefined;
        Common.compilerBug(hostedExternAbiViolationMessage(
            &message_buf,
            self.program.names.externalSymbolNameText(self.hostedFn(template).external_symbol_name),
            self.program.types.typeDigest(&self.program.names, declared_fn_ty),
            self.program.types.typeDigest(&self.program.names, emitted_fn_ty),
        ));
    }

    fn typeName(self: *Builder, view: ModuleView, id: names.TypeNameId) Allocator.Error!names.TypeNameId {
        return self.program.names.internTypeName(view.names.typeNameText(id));
    }

    fn moduleIdentity(self: *Builder, view: ModuleView, id: names.ModuleIdentityId) Allocator.Error!names.ModuleIdentityId {
        return self.program.names.internModuleIdentity(view.names.moduleIdentityBytes(id));
    }

    fn recordFieldName(self: *Builder, view: ModuleView, id: names.RecordFieldNameId) Allocator.Error!names.RecordFieldNameId {
        return self.program.names.internRecordFieldLabel(view.names.recordFieldLabelText(id));
    }

    fn tagName(self: *Builder, view: ModuleView, id: names.TagNameId) Allocator.Error!names.TagNameId {
        return self.program.names.internTagLabel(view.names.tagLabelText(id));
    }

    fn hostedTryAdapterCapability(
        self: *Builder,
        view: ModuleView,
        checked_capability: ?checked.HostedTryAdapterCapability,
    ) Allocator.Error!?HostedTryAdapterCapability {
        const capability = checked_capability orelse return null;
        return .{
            .def = try self.typeDef(
                view,
                capability.nominal.module,
                capability.nominal.type_name,
                capability.nominal.source_decl,
            ),
            .ok_tag = try self.tagName(view, capability.ok_tag),
            .err_tag = try self.tagName(view, capability.err_tag),
            .ok_type_arg_index = capability.ok_type_arg_index,
            .err_type_arg_index = capability.err_type_arg_index,
        };
    }

    fn typeDef(
        self: *Builder,
        view: ModuleView,
        origin_module: names.ModuleIdentityId,
        type_name: names.TypeNameId,
        source_decl: ?u32,
    ) Allocator.Error!Type.TypeDef {
        return .{
            .module = try self.moduleIdentity(view, origin_module),
            .type_name = try self.typeName(view, type_name),
            .source_decl = source_decl,
        };
    }

    fn declaredModuleForAlias(_: *Builder, _: ModuleView, alias: checked.CheckedAliasType) names.CheckedModuleDigest {
        return moduleDigestFromId(alias.owner_module);
    }

    fn declaredModuleForNominal(_: *Builder, _: ModuleView, nominal: checked.CheckedNominalType) names.CheckedModuleDigest {
        return moduleDigestFromId(nominal.owner_module);
    }

    fn lowerRoot(self: *Builder, request: checked.RootRequest) Allocator.Error!void {
        const def = if (request.procedure_binding) |binding|
            try self.lowerProcedureBindingRoot(request, binding)
        else if (request.procedure_template) |template|
            try self.lowerTemplate(template, moduleView(self.root_view), request.checked_type, request.root_evidence, null)
        else if (request.procedure_use) |procedure|
            try self.lowerProcedureUseRoot(request, procedure)
        else
            Common.invariant("root request reached Monotype without a checked procedure template or procedure source");
        try self.appendRuntimeSchemaRequestsForDef(def);
        try self.program.addRoot(.{ .def = def, .request = request });
    }

    /// Lower adjacent checked template roots into one graph and draft. Every
    /// root receives a fresh `BodyContext` (and therefore a fresh checked-type
    /// instantiation scope), but graph-local specialization identities remain
    /// visible across roots. Equivalent callee requests can consequently reuse
    /// the first deferred request before either graph sealing or body lowering.
    fn lowerTemplateRootBatch(self: *Builder, requests: []const checked.RootRequest) Allocator.Error!void {
        if (requests.len == 0) return;

        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const graph = try self.createGraph();
        defer graph.destroy();
        var body_draft = BodyDraftStore.init(self.allocator);
        defer body_draft.deinit();
        var batch = RootTemplateBatch{ .graph = graph, .draft = &body_draft };
        defer batch.pending.deinit(self.allocator);
        const defs = try self.allocator.alloc(Ast.DefId, requests.len);
        defer self.allocator.free(defs);
        graph_setup_timing_scope.end();

        const draft_guard = FinalBodyOutputGuard.begin(self);
        for (requests, 0..) |request, index| {
            const template = request.procedure_template orelse
                Common.invariant("procedure-template root batch contained another root kind");
            defs[index] = try self.lowerTemplate(
                template,
                moduleView(self.root_view),
                request.checked_type,
                request.root_evidence,
                &batch,
            );
        }
        const draft_end = draft_guard.end(self);

        const root_nodes = try self.allocator.alloc(NodeId, batch.pending.items.len);
        defer self.allocator.free(root_nodes);
        for (batch.pending.items, 0..) |pending, index| root_nodes[index] = pending.root_node;

        const sealed = try self.sealActiveBodyDraft(
            graph,
            &body_draft,
            draft_guard,
            draft_end,
            null,
            root_nodes,
            null,
            null,
            null,
        );
        defer sealed.deinit(self.allocator);

        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        if (sealed.root_tys.len != batch.pending.items.len) {
            Common.invariant("root template batch sealing returned the wrong number of root types");
        }
        for (batch.pending.items, sealed.root_tys) |pending, final_fn_ty| {
            try self.finishReservedTemplateBody(pending, sealed.ids, final_fn_ty);
        }
        for (requests, defs) |request, def| {
            try self.appendRuntimeSchemaRequestsForDef(def);
            try self.program.addRoot(.{ .def = def, .request = request });
        }
    }

    fn lowerLayoutRequest(self: *Builder, checked_ty: checked.CheckedTypeId) Allocator.Error!void {
        const ty = try self.lowerType(moduleView(self.root_view), checked_ty);
        try self.program.addLayoutRequest(.{
            .checked_type = checked_ty,
            .ty = ty,
        });
        try self.appendRuntimeSchemaRequestsForType(ty);
    }

    fn lowerStaticDataRequest(self: *Builder, request: Common.StaticDataRequest) Allocator.Error!void {
        const type_view = moduleView(self.root_view);
        const ret_ty = try self.lowerType(type_view, request.checked_type);
        const const_node = self.constNode(request.const_locator, request.node);
        const body = try self.restoreConstNodeAtTypeWithStaticRoot(const_node.module, type_view, const_node.id, ret_ty, request.const_locator);
        const def = try self.program.addDef(.{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .args = Ast.Span(Ast.TypedLocal).empty(),
            .body = .{ .roc = body },
            .ret = ret_ty,
        });
        try self.program.addLayoutRequest(.{
            .checked_type = request.checked_type,
            .ty = ret_ty,
            .def = def,
            .const_locator = request.const_locator,
        });
        try self.appendRuntimeSchemaRequestsForType(ret_ty);
    }

    fn appendRuntimeSchemaRequestsForDef(self: *Builder, def: Ast.DefId) Allocator.Error!void {
        const fn_ = self.program.getDef(def);
        const args = self.program.typedLocalSpan(fn_.args);
        for (0..GuardedList.borrowLen(args)) |index| {
            const arg = GuardedList.at(args, index);
            try self.appendRuntimeSchemaRequestsForType(arg.ty);
        }
        try self.appendRuntimeSchemaRequestsForType(fn_.ret);
    }

    fn appendRuntimeSchemaRequestsForType(self: *Builder, ty: Type.TypeId) Allocator.Error!void {
        var active = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer active.deinit();
        try self.appendRuntimeSchemaRequestsForTypeInner(ty, &active);
    }

    fn appendRuntimeSchemaRequestsForTypeInner(
        self: *Builder,
        ty: Type.TypeId,
        active: *collections.DenseMap(Type.TypeId, void),
    ) Allocator.Error!void {
        if (active.contains(ty)) return;
        try active.put(ty, {});

        switch (self.program.types.get(ty)) {
            .named => |named| {
                const args = self.program.types.span(named.args);
                for (0..GuardedList.borrowLen(args)) |index| {
                    const arg = GuardedList.at(args, index);
                    try self.appendRuntimeSchemaRequestsForTypeInner(arg, active);
                }
                const backing = named.backing orelse return;
                if (backing.use == .inspectable and self.runtimeSchemaBackedByRecordOrTagUnion(backing.ty)) {
                    try self.appendRuntimeSchemaRequest(.{ .def = named.def, .ty = ty });
                }
                try self.appendRuntimeSchemaRequestsForTypeInner(backing.ty, active);
            },
            .record => |fields| {
                const field_span = self.program.types.fieldSpan(fields);
                for (0..GuardedList.borrowLen(field_span)) |index| {
                    const field = GuardedList.at(field_span, index);
                    try self.appendRuntimeSchemaRequestsForTypeInner(field.ty, active);
                }
            },
            .tuple => |items| {
                const item_span = self.program.types.span(items);
                for (0..GuardedList.borrowLen(item_span)) |index| {
                    const item = GuardedList.at(item_span, index);
                    try self.appendRuntimeSchemaRequestsForTypeInner(item, active);
                }
            },
            .tag_union => |tags| {
                const tag_span = self.program.types.tagSpan(tags);
                for (0..GuardedList.borrowLen(tag_span)) |tag_index| {
                    const tag = GuardedList.at(tag_span, tag_index);
                    const payload_span = self.program.types.span(tag.payloads);
                    for (0..GuardedList.borrowLen(payload_span)) |payload_index| {
                        const payload = GuardedList.at(payload_span, payload_index);
                        try self.appendRuntimeSchemaRequestsForTypeInner(payload, active);
                    }
                }
            },
            .list,
            .box,
            => |elem| try self.appendRuntimeSchemaRequestsForTypeInner(elem, active),
            .func => |func| {
                const args = self.program.types.span(func.args);
                for (0..GuardedList.borrowLen(args)) |index| {
                    const arg = GuardedList.at(args, index);
                    try self.appendRuntimeSchemaRequestsForTypeInner(arg, active);
                }
                try self.appendRuntimeSchemaRequestsForTypeInner(func.ret, active);
            },
            .primitive,
            .erased,
            .zst,
            => {},
        }
    }

    fn runtimeSchemaBackedByRecordOrTagUnion(self: *Builder, ty: Type.TypeId) bool {
        return switch (self.program.types.get(ty)) {
            .record,
            .tag_union,
            => true,
            .named => |named| if (named.backing) |backing|
                backing.use == .inspectable and self.runtimeSchemaBackedByRecordOrTagUnion(backing.ty)
            else
                false,
            .primitive, .tuple, .list, .box, .func, .erased, .zst => false,
        };
    }

    fn appendRuntimeSchemaRequest(self: *Builder, request: Ast.RuntimeSchemaRequest) Allocator.Error!void {
        for (self.program.runtimeSchemaRequestsView()) |existing| {
            if (existing.def.module == request.def.module and existing.def.type_name == request.def.type_name) {
                return;
            }
        }
        try self.program.addRuntimeSchemaRequest(request);
    }

    fn lowerProcedureUseRoot(
        self: *Builder,
        request: checked.RootRequest,
        procedure: checked.ProcedureUseTemplate,
    ) Allocator.Error!Ast.DefId {
        const view = moduleView(self.root_view);
        const callable_eval = self.callableEvalForProcedureUse(procedure);
        const template_ref = if (callable_eval) |use| blk: {
            const raw = @intFromEnum(use.template);
            if (raw >= use.view.callable_eval_templates.templates.len) {
                Common.invariant("callable eval procedure use referenced a missing checked template");
            }
            const template = use.view.callable_eval_templates.templates[raw];
            const wrapper = use.view.entry_wrappers.lookupByRoot(template.root) orelse
                Common.invariant("callable eval procedure use root had no checked entry wrapper");
            break :blk wrapper.template;
        } else self.templateRefForProcedureUse(procedure);
        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &body_draft);
        defer ctx.deinit();

        const root_node = try ctx.instNode(request.checked_type);
        const initial_fn = try graph.functionNodes(root_node);
        const args = try self.allocator.alloc(DraftTypedLocal, initial_fn.args.len);
        defer self.allocator.free(args);
        const arg_exprs = try self.allocator.alloc(DraftExprId, initial_fn.args.len);
        defer self.allocator.free(arg_exprs);

        for (initial_fn.args, 0..) |arg_node, index| {
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            const local = try ctx.addLocalWithBinderCell(self.symbols.fresh(), arg_cell, null);
            args[index] = .{ .local = local, .ty = arg_cell };
            arg_exprs[index] = try ctx.addExprWithTypeCell(arg_cell, .{ .local = local });
        }
        graph_setup_timing_scope.end();

        const draft = FinalBodyOutputGuard.begin(self);
        var body_timing_scope = ProcedureTimingScope.begin(self.timing, .body_lowering);
        defer body_timing_scope.end();
        const body, const ret_cell = if (callable_eval) |use| blk: {
            const callee = try ctx.lowerCallableEvalBindingValueAtNode(
                use.view,
                use.template,
                root_node,
                &.{},
            );
            const completed_fn = try graph.functionNodes(root_node);
            const completed_ret = DraftTypeCell.fromGraphNode(completed_fn.ret);
            break :blk .{
                try ctx.addExprWithTypeCell(completed_ret, .{
                    .call_value = .{
                        .callee = callee,
                        .args = try body_draft.addExprSpan(arg_exprs),
                    },
                }),
                completed_ret,
            };
        } else blk: {
            const callee, const completed_fn = dispatch: {
                var dispatch_timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
                defer dispatch_timing_scope.end();
                const selected = try ctx.draftFnSlotForProcedureUseAtNode(
                    procedure,
                    request.checked_type,
                    procedure.source_fn_ty_template,
                    root_node,
                    &.{},
                    request.root_evidence,
                );
                const callee_fn_node = try ctx.draftFnSlotTypeNode(selected, root_node);
                try relateFunctionRequestInterface(graph, root_node, callee_fn_node);
                break :dispatch .{ selected, try graph.functionNodes(root_node) };
            };
            const completed_ret = DraftTypeCell.fromGraphNode(completed_fn.ret);
            break :blk .{
                try ctx.addExprWithTypeCell(completed_ret, .{
                    .call_proc = .{
                        .callee = draftProcCalleeForSlot(callee),
                        .args = try body_draft.addExprSpan(arg_exprs),
                    },
                }),
                completed_ret,
            };
        };
        const root_def = try body_draft.reserveDef(.root);
        body_draft.setDef(root_def, .{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .args = try body_draft.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = ret_cell,
        });
        body_timing_scope.end();
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(
            graph,
            &body_draft,
            draft,
            draft_end,
            root_node,
            &.{},
            null,
            root_def,
            null,
        );
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        return sealed.root_def orelse Common.invariant("procedure use root did not commit its wrapper definition");
    }

    fn lowerProcedureBindingRoot(
        self: *Builder,
        request: checked.RootRequest,
        binding_id: checked.TopLevelProcedureBindingId,
    ) Allocator.Error!Ast.DefId {
        const view = moduleView(self.root_view);
        const fn_ty = try self.lowerType(view, request.checked_type);
        const fn_data = self.functionShape(fn_ty, "procedure binding root had a non-function checked type");
        const arg_tys = self.program.types.span(fn_data.args);
        const args = try self.allocator.alloc(Ast.TypedLocal, arg_tys.len);
        defer self.allocator.free(args);
        const arg_exprs = try self.allocator.alloc(Ast.ExprId, arg_tys.len);
        defer self.allocator.free(arg_exprs);

        for (0..GuardedList.borrowLen(arg_tys)) |i| {
            const arg_ty = GuardedList.at(arg_tys, i);
            const local = try self.program.addLocal(self.symbols.fresh(), arg_ty);
            args[i] = .{ .local = local, .ty = arg_ty };
            arg_exprs[i] = try self.program.addExpr(.{ .ty = arg_ty, .data = .{ .local = local } });
        }

        const binding = view.top_level_procedure_bindings.get(binding_id);
        const body = switch (binding.body) {
            .direct_template => blk: {
                const source_fn_ty = schemeRoot(view, binding.source_scheme, "procedure binding source scheme was not output");
                const fn_template = self.fnDefForProcedureBindingBody(
                    view,
                    binding.body,
                    source_fn_ty,
                    view.types.rootKey(source_fn_ty),
                    fn_ty,
                );
                const callee = try self.lowerFnTemplateCallTarget(view, fn_template, &.{});
                break :blk try self.program.addExpr(.{
                    .ty = fn_data.ret,
                    .data = .{ .call_proc = .{
                        .callee = Ast.procCalleeForSlot(callee),
                        .args = try self.program.addExprSpan(arg_exprs),
                    } },
                });
            },
            .callable_eval_template => blk: {
                const callee = try self.lowerProcedureBindingValue(view, binding, fn_ty);
                break :blk try self.program.addExpr(.{
                    .ty = fn_data.ret,
                    .data = .{ .call_value = .{
                        .callee = callee,
                        .args = try self.program.addExprSpan(arg_exprs),
                    } },
                });
            },
        };

        return try self.program.addDef(.{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .args = try self.program.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = fn_data.ret,
        });
    }

    fn lowerProcedureBindingValue(
        self: *Builder,
        view: ModuleView,
        binding: checked.TopLevelProcedureBinding,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        return switch (binding.body) {
            .direct_template => blk: {
                const source_fn_ty = schemeRoot(view, binding.source_scheme, "procedure binding source scheme was not output");
                const fn_template = self.fnDefForProcedureBindingBody(
                    view,
                    binding.body,
                    source_fn_ty,
                    view.types.rootKey(source_fn_ty),
                    mono_fn_ty,
                );
                const fn_id = try self.lowerFnTemplateDef(view, fn_template, &.{});
                break :blk try self.program.addExpr(.{
                    .ty = self.program.fnSource(fn_id).mono_fn_ty,
                    .data = .{ .fn_def = .{ .fn_id = fn_id } },
                });
            },
            .callable_eval_template => |template_id| try self.lowerCallableEvalBindingValue(view, template_id, mono_fn_ty),
        };
    }

    fn lowerCallableEvalBindingValue(
        self: *Builder,
        view: ModuleView,
        template_id: checked.CallableEvalTemplateId,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const raw = @intFromEnum(template_id);
        if (raw >= view.callable_eval_templates.templates.len) {
            Common.invariant("callable eval binding referenced a missing checked template");
        }
        const template = view.callable_eval_templates.templates[raw];
        const root = view.compile_time_roots.root(template.root);
        return switch (root.payload) {
            .fn_value => |fn_id| try self.restoreConstFnExpr(view, fn_id, mono_fn_ty, null),
            .const_node => |node| try self.restoreConstNodeAtType(view, view, node, mono_fn_ty),
            .pending => try self.lowerPendingCallableEvalBindingValue(view, template, root, mono_fn_ty),
            .expect => Common.invariant("callable eval binding root output an expect payload"),
        };
    }

    const CallableEvalUse = struct {
        view: ModuleView,
        template: checked.CallableEvalTemplateId,
    };

    fn callableEvalForProcedureUse(self: *Builder, proc: checked.ProcedureUseTemplate) ?CallableEvalUse {
        return switch (proc.binding) {
            .top_level => |top_level| blk: {
                const view = self.moduleForId(checked.topLevelProcedureModuleId(top_level));
                const binding = view.top_level_procedure_bindings.get(top_level.binding);
                break :blk switch (binding.body) {
                    .direct_template => null,
                    .callable_eval_template => |template| .{ .view = view, .template = template },
                };
            },
            .imported => |imported| blk: {
                const view = self.moduleForId(checked.importedProcedureModuleId(imported));
                for (view.exported_procedure_bindings.bindings) |binding| {
                    if (binding.binding.def != imported.def or binding.binding.pattern != imported.pattern) continue;
                    break :blk switch (binding.body) {
                        .direct_template => null,
                        .callable_eval_template => |template| .{ .view = view, .template = template },
                    };
                }
                Common.invariant("imported procedure binding was not exported by its checked module");
            },
            .hosted => null,
            .platform_required => |required| blk: {
                const view = self.moduleForId(checked.requiredProcedureModuleId(required));
                const binding = view.top_level_procedure_bindings.get(required.procedure_binding);
                break :blk switch (binding.body) {
                    .direct_template => null,
                    .callable_eval_template => |template| .{ .view = view, .template = template },
                };
            },
        };
    }

    fn lowerPendingCallableEvalBindingValue(
        self: *Builder,
        view: ModuleView,
        template: checked.CallableEvalTemplate,
        root: checked.CompileTimeRoot,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const wrapper = view.entry_wrappers.lookupByRoot(template.root) orelse
            Common.invariant("callable eval template root had no checked entry wrapper");

        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var body_ctx = try BodyContext.init(self.allocator, self, view, wrapper.template, graph, &body_draft);
        defer body_ctx.deinit();
        graph_setup_timing_scope.end();

        const draft = FinalBodyOutputGuard.begin(self);
        var body_timing_scope = ProcedureTimingScope.begin(self.timing, .body_lowering);
        defer body_timing_scope.end();
        const lowered = try body_ctx.lowerPendingCallableEvalBindingValue(
            view,
            template,
            root,
            mono_fn_ty,
        );
        body_timing_scope.end();
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        return sealed.ids.expr(lowered);
    }

    fn lowerTemplate(
        self: *Builder,
        template_ref: names.ProcTemplate,
        source_ty_view: ModuleView,
        source_fn_ty: checked.CheckedTypeId,
        root_evidence: ?checked.CheckedEvidenceSpan,
        root_batch: ?*RootTemplateBatch,
    ) Allocator.Error!Ast.DefId {
        const fn_ty = try self.lowerContextFreeSpecializationType(
            source_ty_view,
            template_ref,
            source_fn_ty,
        );
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const fn_template = self.fnDefForTemplate(
            view,
            template_ref,
            source_fn_ty,
            source_ty_view.types.rootKey(source_fn_ty),
            fn_ty,
        );
        const evidence = if (root_evidence) |evidence_ref| blk: {
            var timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
            defer timing_scope.end();
            break :blk try self.materializeRootProcedureEvidence(fn_template, evidence_ref);
        } else &.{};
        return try self.lowerTemplateWithMono(
            template_ref,
            view,
            source_fn_ty,
            source_ty_view.types.rootKey(source_fn_ty),
            fn_ty,
            evidence,
            .independent_roots,
            .count,
            null,
            null,
            root_batch,
        );
    }

    /// Retain the exact dispatch vector selected for a specialization so a
    /// compile-time function value can restore that vector without resolving
    /// its requirements again.
    fn constFnEvidence(self: *Builder, evidence: EvidenceChain) Allocator.Error!StoredConstFnEvidence {
        var nodes = std.ArrayList(check.ConstStore.ConstFnEvidence).empty;
        defer nodes.deinit(self.allocator);
        var chain = std.ArrayList(*const EvidenceChain).empty;
        defer chain.deinit(self.allocator);
        var current: ?*const EvidenceChain = &evidence;
        while (current) |frame| : (current = frame.parent) {
            try chain.append(self.allocator, frame);
        }
        var frames = std.ArrayList(check.ConstStore.ConstFnEvidenceFrame).empty;
        defer frames.deinit(self.allocator);
        var index = chain.items.len;
        var parent: ?u32 = null;
        while (index > 0) {
            index -= 1;
            const frame = chain.items[index];
            const roots_start: u32 = @intCast(nodes.items.len);
            try self.appendConstFnEvidence(&nodes, frame.vector);
            const scope: check.ConstStore.ConstFnEvidenceScope = switch (frame.scope.lexical) {
                .root => .root,
                .generalized => |scope_id| .{ .generalized = @intFromEnum(scope_id) },
            };
            try frames.append(self.allocator, check.ConstStore.ConstFnEvidenceFrame.init(
                scope,
                parent,
                roots_start,
                @intCast(frame.vector.len),
            ));
            parent = @intCast(frames.items.len - 1);
        }
        return .{
            .nodes = try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidence, nodes.items),
            .frames = try self.evidence_arena.allocator().dupe(check.ConstStore.ConstFnEvidenceFrame, frames.items),
            .head = parent,
        };
    }

    fn appendConstFnEvidence(
        self: *Builder,
        nodes: *std.ArrayList(check.ConstStore.ConstFnEvidence),
        evidence: []const SpecEvidence,
    ) Allocator.Error!void {
        for (evidence) |entry| switch (entry) {
            .target => |target| {
                const target_index = nodes.items.len;
                try nodes.append(self.allocator, undefined);
                const nested: check.ConstStore.ConstFnNestedEvidence = switch (target.nested) {
                    .synthesize => .from_callable,
                    .resolved => |resolved| blk: {
                        const nested_start = nodes.items.len;
                        try self.appendConstFnEvidence(nodes, resolved);
                        break :blk .{ .resolved = .{
                            .count = @intCast(resolved.len),
                            .subtree_len = @intCast(nodes.items.len - nested_start),
                        } };
                    },
                };
                nodes.items[target_index] = .{ .target = .{
                    .view = .{ .bytes = target.view.key.bytes },
                    .method = target.target,
                    .instantiation = if (target.instantiation) |instantiation| .{
                        .view = .{ .bytes = instantiation.view.key.bytes },
                        .callable_ty = instantiation.callable_ty,
                    } else null,
                    .nested = nested,
                } };
            },
            .structural => |kind| try nodes.append(self.allocator, .{ .structural = kind }),
            .unreachable_value => try nodes.append(self.allocator, .unreachable_value),
            .checked_error => try nodes.append(self.allocator, .checked_error),
        };
    }

    fn completeRootTemplateEvidence(
        self: *Builder,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        partial: []const SpecEvidence,
    ) Allocator.Error![]const SpecEvidence {
        return self.completeRootTemplateEvidenceForPurpose(
            view,
            template_ref,
            template,
            partial,
            .body_lowering,
        );
    }

    fn completeRootTemplateEvidenceForPurpose(
        self: *Builder,
        view: ModuleView,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        partial: []const SpecEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
        defer timing_scope.end();

        const graph = try self.createGraph();
        defer graph.destroy();
        var draft = BodyDraftStore.init(self.allocator);
        defer draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &draft);
        defer ctx.deinit();
        ctx.evidence = rootEvidence(template_ref, partial);
        return (try ctx.rootEdgeEvidenceForPurpose(view, template, purpose)) orelse
            Common.invariant("procedure specialization did not receive its complete checked evidence vector");
    }

    fn lowerTemplateWithMono(
        self: *Builder,
        template_ref: names.ProcTemplate,
        method_scope: ModuleView,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        fn_ty: Type.TypeId,
        evidence: []const SpecEvidence,
        signature_relation: Ast.SignatureRelation,
        request_accounting: TemplateRequestAccounting,
        precomputed_request_digest: ?names.TypeDigest,
        retained_topology: ?EvidenceChain,
        root_batch: ?*RootTemplateBatch,
    ) Allocator.Error!Ast.DefId {
        var lookup_timing_scope = ProcedureTimingScope.begin(self.timing, .lookup_reservation);
        defer lookup_timing_scope.end();

        if (request_accounting == .count) self.count("template_requests");
        const lower_fn_ty = fn_ty;
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        if (evidence.len > template.evidence_params.len) {
            Common.invariant("procedure specialization received more evidence than its checked requirements");
        }
        const spec_evidence = if (evidence.len == template.evidence_params.len)
            evidence
        else
            try self.completeRootTemplateEvidence(view, template_ref, template, evidence);
        const source_topology: ?EvidenceChain = if (retained_topology) |topology|
            topology
        else
            rootEvidence(template_ref, spec_evidence);
        const identity_topology = source_topology orelse rootEvidence(template_ref, spec_evidence);
        const identity_evidence = try self.constFnEvidence(identity_topology);
        const evidence_digest = Ast.fnEvidenceDigest(identity_evidence.nodes, identity_evidence.frames, identity_evidence.head);
        const stored_source_topology = if (source_topology != null) identity_evidence else null;
        const request_digest = precomputed_request_digest orelse self.specializationTypeDigest(fn_ty);
        if (try self.spec_store.findLocal(
            templateSpecIdentity(template_ref, method_scope.key, source_fn_key, evidence_digest, fn_ty, request_digest),
            specializationEvidenceView(identity_evidence),
        )) |hit| {
            if (request_accounting == .count) self.count("template_hits");
            const existing = self.lowered_templates.get(hit.fn_id) orelse
                Common.invariant("Monotype specialization index found a local template missing from lowering state");
            if (!specEvidenceVectorEql(existing.evidence, spec_evidence)) {
                Common.invariant("Monotype specialization cache hit disagreed on dispatch evidence");
            }
            if (stored_source_topology) |requested| {
                const existing_topology = existing.topology orelse
                    Common.invariant("Monotype specialization cache hit had no explicit evidence topology");
                if (!storedConstFnEvidenceEql(existing_topology, requested)) {
                    Common.invariant("Monotype specialization cache hit disagreed on lexical evidence topology");
                }
            }
            switch (hit.status) {
                .ready,
                .lowering,
                => {
                    self.promoteFnSignatureRelation(hit.fn_id, signature_relation);
                    return existing.def;
                },
                .reserved => Common.invariant("Monotype procedure specialization reached lowering with a reserved record"),
            }
        } else {
            if (request_accounting == .count) self.count("template_misses");
        }

        var fn_template = self.fnDefForTemplate(view, template_ref, source_fn_ty, source_fn_key, lower_fn_ty);
        fn_template.evidence_digest = evidence_digest;
        if (stored_source_topology) |stored_evidence| {
            fn_template.const_evidence = try self.program.addConstFnEvidence(stored_evidence.nodes);
            fn_template.const_evidence_frames = try self.program.addConstFnEvidenceFrames(stored_evidence.frames);
            fn_template.const_evidence_frame_head = stored_evidence.head;
        }

        const reservation: TemplateReservation = blk: {
            const symbol = self.symbols.fresh();
            try self.registerProcDebugNameForTemplate(symbol, view, template_ref);
            const fn_id = try self.program.addFn(fn_template);
            self.promoteFnSignatureRelation(fn_id, signature_relation);
            // The definition fills once its body lowers; a recursive request
            // that reuses this entry meanwhile reads the requested template,
            // which is the same specialization by construction.
            const def_id = try self.program.addDef(.{
                .symbol = symbol,
                .fn_def = fn_template,
                .fn_id = fn_id,
                .args = Ast.Span(Ast.TypedLocal).empty(),
                .body = .hosted,
                .ret = self.functionShape(lower_fn_ty, "procedure template root type was not a function").ret,
            });
            const spec = try self.addTemplateSpecRecord(
                template_ref,
                method_scope.key,
                source_fn_key,
                identity_evidence,
                lower_fn_ty,
                request_digest,
                fn_id,
                .lowering,
            );
            try self.lowered_templates.put(fn_id, .{
                .def = def_id,
                .spec = spec,
                .evidence = spec_evidence,
                .topology = stored_source_topology,
            });
            break :blk .{
                .def = def_id,
                .fn_id = fn_id,
                .symbol = symbol,
            };
        };

        switch (template.target) {
            .hosted => {
                var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
                defer completion_timing_scope.end();

                // The host is compiled against the declared hosted signature,
                // so that exact type is the only one the extern boundary may
                // use. A use site can still widen a (closed) tag-union row in
                // the result through ordinary unification (e.g. `?` re-wraps
                // the hosted error into the caller's wider error union); such
                // requests get a generated Roc adapter that calls the
                // declared-type boundary and re-tags the result, instead of a
                // hosted spec whose layout would not match the host ABI.
                // `requireHostedExternAtDeclaredAbi` below holds the boundary
                // for every other request shape.
                const declared_source_fn_ty = template.checked_fn_root;
                const declared_source_fn_key = view.types.rootKey(declared_source_fn_ty);
                const declared_mono_fn_ty = try self.lowerType(view, declared_source_fn_ty);
                var hosted_fn_template = self.fnDefForTemplate(
                    view,
                    template_ref,
                    declared_source_fn_ty,
                    declared_source_fn_key,
                    lower_fn_ty,
                );
                hosted_fn_template.evidence_digest = fn_template.evidence_digest;
                hosted_fn_template.const_evidence = fn_template.const_evidence;
                hosted_fn_template.const_evidence_frames = fn_template.const_evidence_frames;
                hosted_fn_template.const_evidence_frame_head = fn_template.const_evidence_frame_head;
                const fn_data = self.functionShape(lower_fn_ty, "hosted procedure template root type was not a function");
                const args = try self.typedLocalsForArgs(self.program.types.span(fn_data.args));
                const hosted_try = try self.hostedTryAdapterCapability(view, template.hosted_try_adapter);
                if (try self.hostedTryAdapterSourceType(hosted_try, declared_mono_fn_ty, lower_fn_ty)) |adapter_source_fn_ty| {
                    const source_def = try self.lowerTemplateWithMono(
                        template_ref,
                        method_scope,
                        declared_source_fn_ty,
                        declared_source_fn_key,
                        adapter_source_fn_ty,
                        &.{},
                        signature_relation,
                        .count,
                        null,
                        null,
                        null,
                    );
                    const adapter_template = Ast.FnTemplate{
                        .fn_def = .{ .checked_generated = template_ref },
                        .source_fn_ty = source_fn_ty,
                        .source_fn_key = source_fn_key,
                        .mono_fn_ty = lower_fn_ty,
                        .evidence_digest = fn_template.evidence_digest,
                        .const_evidence = fn_template.const_evidence,
                        .const_evidence_frames = fn_template.const_evidence_frames,
                        .const_evidence_frame_head = fn_template.const_evidence_frame_head,
                    };
                    const body = try self.hostedTryAdapterBody(
                        hosted_try.?,
                        args,
                        self.defFnId(source_def),
                        adapter_source_fn_ty,
                        lower_fn_ty,
                    );
                    self.program.setDef(reservation.def, .{
                        .symbol = reservation.symbol,
                        .fn_def = adapter_template,
                        .fn_id = reservation.fn_id,
                        .args = args,
                        .body = .{ .roc = body },
                        .ret = fn_data.ret,
                    });
                    self.program.setFnSource(reservation.fn_id, adapter_template);
                    try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
                    return reservation.def;
                }
                try self.requireHostedExternAtDeclaredAbi(
                    view,
                    template_ref,
                    declared_source_fn_ty,
                    declared_mono_fn_ty,
                    lower_fn_ty,
                );
                self.program.setDef(reservation.def, .{
                    .symbol = reservation.symbol,
                    .fn_def = hosted_fn_template,
                    .fn_id = reservation.fn_id,
                    .args = args,
                    .body = .hosted,
                    .ret = fn_data.ret,
                });
                self.program.setFnSource(reservation.fn_id, hosted_fn_template);
                try self.markTemplateReady(reservation.fn_id, lower_fn_ty);
                return reservation.def;
            },
            .roc,
            .intrinsic,
            .entry,
            .comptime_only,
            => {},
        }

        if (root_batch) |batch| {
            const pending = try self.lowerReservedTemplateBodyIntoDraft(
                batch.graph,
                batch.draft,
                reservation,
                fn_template,
                template_ref,
                view,
                method_scope,
                template,
                source_fn_key,
                lower_fn_ty,
                spec_evidence,
                retained_topology,
                signature_relation,
            );
            try batch.pending.append(self.allocator, pending);
            return reservation.def;
        }

        const graph = try self.createGraph();
        defer graph.destroy();
        var body_draft_storage = BodyDraftStore.init(self.allocator);
        defer body_draft_storage.deinit();
        const body_draft = &body_draft_storage;
        const draft = FinalBodyOutputGuard.begin(self);
        const pending = try self.lowerReservedTemplateBodyIntoDraft(
            graph,
            body_draft,
            reservation,
            fn_template,
            template_ref,
            view,
            method_scope,
            template,
            source_fn_key,
            lower_fn_ty,
            spec_evidence,
            retained_topology,
            signature_relation,
        );
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(
            graph,
            body_draft,
            draft,
            draft_end,
            pending.root_node,
            &.{},
            null,
            null,
            null,
        );
        defer sealed.deinit(self.allocator);
        var completion_timing_scope = ProcedureTimingScope.begin(self.timing, .completion);
        defer completion_timing_scope.end();
        try self.finishReservedTemplateBody(pending, sealed.ids, sealed.root_ty.?);
        return reservation.def;
    }

    fn lowerReservedTemplateBodyIntoDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        reservation: TemplateReservation,
        fn_template: Ast.FnTemplate,
        template_ref: names.ProcTemplate,
        view: ModuleView,
        method_scope: ModuleView,
        template: checked.CheckedProcedureTemplate,
        source_fn_key: names.TypeDigest,
        lower_fn_ty: Type.TypeId,
        spec_evidence: []const SpecEvidence,
        retained_topology: ?EvidenceChain,
        signature_relation: Ast.SignatureRelation,
    ) Allocator.Error!PendingRootTemplateBody {
        var graph_setup_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
        defer graph_setup_timing_scope.end();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        const saved_template_root = self.active_template_root;
        self.active_graph = graph;
        self.active_body_draft = body_draft;
        defer self.active_graph = saved_graph;
        defer self.active_body_draft = saved_body_draft;
        defer self.active_template_root = saved_template_root;

        var body_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            view,
            method_scope,
            template_ref,
            graph,
            body_draft,
        );
        body_ctx.evidence = retained_topology orelse rootEvidence(template_ref, spec_evidence);
        const lowered_template = self.lowered_templates.getPtr(reservation.fn_id) orelse
            Common.invariant("procedure specialization lost its evidence record before body lowering");
        lowered_template.evidence = body_ctx.evidence.vector;
        defer body_ctx.deinit();

        const root_node = try body_ctx.relateCheckedFunctionToMono(template.checked_fn_root, lower_fn_ty);
        self.active_template_root = .{
            .graph = graph,
            .family = DraftTemplateFamilyAddress.init(template_ref, method_scope.key, source_fn_key),
            .evidence = body_ctx.evidence.vector,
            .request_fn_node = root_node,
            .initial_request_arg_classes = try graph.snapshotFunctionArgumentClasses(root_node),
            .fn_id = reservation.fn_id,
        };
        const root_owner = try body_draft.enterOwner(.{ .reserved_fn = reservation.fn_id });
        defer root_owner.leave();
        graph_setup_timing_scope.end();

        // The durable request remains an immutable snapshot. The body keeps
        // the related request node until the shared draft's single final seal
        // creates the solved function type.
        {
            var dispatch_timing_scope = ProcedureTimingScope.begin(self.timing, .dispatch_evidence);
            defer dispatch_timing_scope.end();
            try body_ctx.instantiateTemplateDispatchRelations(template, null);
        }
        body_ctx.owner_context_fn_key = source_fn_key;
        body_ctx.current_fn_key = source_fn_key;
        const lowered = try body_ctx.lowerTemplateBodyAtNode(template_ref, template, root_node);
        const completed_root = blk: {
            var relations_timing_scope = ProcedureTimingScope.begin(self.timing, .body_graph_setup);
            defer relations_timing_scope.end();
            break :blk switch (signature_relation) {
                .exact_graph => root_node,
                .independent_roots => try body_ctx.completedFunctionNodeForLoweredRet(
                    root_node,
                    lowered.ret,
                    body_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
                ),
            };
        };
        return .{
            .reservation = reservation,
            .fn_template = fn_template,
            .signature_relation = signature_relation,
            .root_node = completed_root,
            .lowered = lowered,
        };
    }

    fn finishReservedTemplateBody(
        self: *Builder,
        pending: PendingRootTemplateBody,
        body_ids: FinalIdOffsets,
        final_fn_ty: Type.TypeId,
    ) Allocator.Error!void {
        // The definition records the body's solved view of the root type.
        // Call sites embed the requested type, which digests identically
        // because digests are alias-transparent and a solved request
        // determines every interface slot; root-class call sites adopt this
        // recorded template directly.
        var def_template = pending.fn_template;
        def_template.mono_fn_ty = switch (pending.signature_relation) {
            // An exact signature keeps the producer-authored request type. The
            // independently solved body may seal to an equal, distinct TypeId.
            .exact_graph => pending.fn_template.mono_fn_ty,
            .independent_roots => final_fn_ty,
        };
        self.program.setFnSource(pending.reservation.fn_id, def_template);
        const sealed_fn_data = self.functionShape(final_fn_ty, "checked procedure template root type was not a function");
        self.program.setDef(pending.reservation.def, .{
            .symbol = pending.reservation.symbol,
            .fn_def = def_template,
            .fn_id = pending.reservation.fn_id,
            .args = body_ids.typedLocalSpan(pending.lowered.args),
            .body = .{ .roc = body_ids.expr(pending.lowered.body) },
            .ret = sealed_fn_data.ret,
        });
        try self.markTemplateReady(pending.reservation.fn_id, final_fn_ty);
    }

    fn lowerDraftTemplateFromContext(
        self: *Builder,
        source_ctx: *BodyContext,
        template_ref: names.ProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        raw_request_fn_node: NodeId,
        partial_evidence: []const SpecEvidence,
        evidence_mode: DraftRequestEvidenceMode,
        signature_relation: Ast.SignatureRelation,
    ) Allocator.Error!DraftFnSlot {
        self.count("template_requests");
        const request_fn_node = try source_ctx.graph.functionRequestRoot(raw_request_fn_node);
        const view = self.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = view.templates.get(template_ref.template);
        if (partial_evidence.len > template.evidence_params.len) {
            Common.invariant("draft procedure specialization received more evidence than its checked requirements");
        }
        const evidence = if (partial_evidence.len == template.evidence_params.len)
            partial_evidence
        else
            try self.completeRootTemplateEvidence(view, template_ref, template, partial_evidence);
        const family = DraftTemplateFamilyAddress.init(template_ref, source_ctx.method_scope.key, source_fn_key);

        // The globally reserved root is the active ancestor of recursive calls
        // in its own specialization graph. Reuse that exact function instead
        // of deferring a sibling body: doing so keeps recursion within one
        // Monotype instantiation context and lets recursive representation
        // evidence (notably forced-dynamic iterator flow) reach the root before
        // its single seal.
        if (self.active_template_root) |active_root| {
            if (active_root.graph == source_ctx.graph and
                active_root.family.sameRecursiveCallable(family) and
                specEvidenceVectorEql(active_root.evidence, evidence))
            {
                const exact_interface = source_ctx.graph.sameFunctionInterface(
                    active_root.request_fn_node,
                    request_fn_node,
                );
                const active_recursive_edge = source_ctx.draft.ownerDescendsFromReservedFn(
                    source_ctx.draft.current_owner,
                    active_root.fn_id,
                );
                const partial_recursive_allowed = active_recursive_edge and switch (evidence_mode) {
                    .resolved => true,
                    .synthesized => try draftRequestOverlapsInitialArgumentClass(
                        source_ctx.graph,
                        active_root.initial_request_arg_classes,
                        request_fn_node,
                    ),
                };
                if (exact_interface or partial_recursive_allowed) {
                    if (active_recursive_edge) {
                        try source_ctx.graph.unifyRecursiveFunctionInterface(
                            active_root.request_fn_node,
                            active_root.initial_request_arg_classes,
                            request_fn_node,
                        );
                    } else {
                        try source_ctx.graph.unify(active_root.request_fn_node, request_fn_node);
                    }
                    if (!source_ctx.graph.sameFunctionInterface(active_root.request_fn_node, request_fn_node)) {
                        Common.invariant("recursive root request did not join its complete function interface");
                    }
                    self.promoteFnSignatureRelation(active_root.fn_id, signature_relation);
                    self.count("template_hits");
                    return .{ .local = .{ .final = active_root.fn_id } };
                }
            }
        }

        const stored_evidence = try self.constFnEvidence(rootEvidence(template_ref, evidence));
        const evidence_digest = Ast.fnEvidenceDigest(stored_evidence.nodes, stored_evidence.frames, stored_evidence.head);
        const structural_lexical_dependent = template.target != .hosted and
            source_ctx.local_proc_contexts.count() != 0 and
            specEvidenceContainsStructural(evidence);
        const lexical_context_key: ?names.TypeDigest = if (structural_lexical_dependent)
            try source_ctx.codecLexicalContextKey()
        else
            null;
        const local_evidence_owner = specEvidenceLocalOwner(source_ctx.draft, evidence);
        const local_context_dependent = local_evidence_owner != null or structural_lexical_dependent;
        const lexical_owner = local_evidence_owner orelse if (structural_lexical_dependent)
            source_ctx.draft.current_owner
        else
            null;

        // Draft specialization identity stays graph-native for the entire
        // relation-production phase. Even a currently resolved request can
        // still be joined by later body/evidence relations, so it must not be
        // promoted to a durable TypeId before the single final seal.
        var selection = DraftOpenCandidateSelection{};
        const resolved_request_ty: ?Type.TypeId = if (try source_ctx.graph.typeIsResolved(request_fn_node))
            try source_ctx.activeTypeFromNode(request_fn_node)
        else if (try source_ctx.graph.typeIsSpecializationDefaultable(request_fn_node))
            try source_ctx.graph.specializationTypeViewForNode(request_fn_node)
        else
            null;
        // Closed requests—and requests whose only open cells have the explicit
        // required field-kind default—key on an immutable structural view, so
        // a repeat skips the graph-native recursive lookup below. The latter
        // view does not mutate the live request; a hit joins the live
        // interfaces below.
        const resolved_lookup_address: ?DraftTemplateLookupAddress = if (resolved_request_ty) |request_fn_ty| .{
            .family = family,
            .evidence_digest = evidence_digest.bytes,
            .request_kind = 0,
            .request_fn_key = self.specializationTypeDigest(request_fn_ty).bytes,
        } else null;
        if (resolved_lookup_address) |address| {
            if (source_ctx.draft.template_spec_lookup.get(address)) |candidates| {
                for (candidates.items) |raw_spec| {
                    const spec = &source_ctx.draft.template_specs.items[raw_spec];
                    if (!specEvidenceVectorEql(spec.evidence, evidence)) continue;
                    if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                    if (!try source_ctx.graph.typeIsSpecializationDefaultable(spec.request_fn_node)) continue;
                    const spec_fn_ty = try source_ctx.graph.specializationTypeViewForNode(spec.request_fn_node);
                    if (!try self.program.types.typeEql(&self.program.names, spec_fn_ty, resolved_request_ty.?)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (selection.selected() == null) {
            var seen_specs = std.AutoHashMap(u32, void).init(self.allocator);
            defer seen_specs.deinit();
            var interface = try source_ctx.graph.functionInterfaceIterator(request_fn_node);
            while (interface.next()) |interface_node| {
                var aliases = source_ctx.graph.classMemberIterator(interface_node);
                while (aliases.next()) |member| {
                    const lookup_address = DraftTemplateLookupAddress{
                        .family = family,
                        .evidence_digest = evidence_digest.bytes,
                        .request_kind = 1,
                        .request_fn_key = draftOpenRequestKey(member),
                    };
                    if (source_ctx.draft.template_spec_lookup.get(lookup_address)) |candidates| {
                        for (candidates.items) |raw_spec| {
                            const seen = try seen_specs.getOrPut(raw_spec);
                            if (seen.found_existing) continue;
                            const spec = &source_ctx.draft.template_specs.items[raw_spec];
                            if (!specEvidenceVectorEql(spec.evidence, evidence)) continue;
                            if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                            const exact_interface = source_ctx.graph.sameFunctionInterface(spec.request_fn_node, request_fn_node);
                            const active_recursive_edge = source_ctx.draft.ownerDescendsFromDraftFn(
                                source_ctx.draft.current_owner,
                                spec.fn_id,
                            );
                            // Synthesized component calls can share ubiquitous
                            // result cells such as Bool across unrelated
                            // component types; require an argument-class
                            // anchor before treating a partial match as
                            // recursion.
                            const partial_recursive_allowed = active_recursive_edge and switch (evidence_mode) {
                                .resolved => true,
                                .synthesized => try draftRequestOverlapsInitialArgumentClass(
                                    source_ctx.graph,
                                    spec.initial_request_arg_classes,
                                    request_fn_node,
                                ),
                            };
                            if (!draftOpenCandidateQualifies(
                                spec.state,
                                exact_interface,
                                active_recursive_edge,
                                partial_recursive_allowed,
                            )) continue;
                            if (!selection.add(raw_spec, exact_interface)) {
                                Common.invariant("draft template request matched more than one partial active recursive specialization");
                            }
                        }
                    }
                }
            }
            // Independently instantiated calls do not necessarily share graph
            // cells with the specialization currently being lowered. Once both
            // requests are closed or defaultable only by the declared required
            // field-kind rule, exact structural type equality proves that they
            // are the same specialization request. This scan retains graph-
            // interface identity for active recursive and partially overlapping
            // requests.
            if (resolved_request_ty) |request_fn_ty| {
                for (source_ctx.draft.template_specs.items, 0..) |*spec, raw_spec_usize| {
                    const raw_spec: u32 = @intCast(raw_spec_usize);
                    if (!names.procedureTemplateRefEql(spec.template_ref, template_ref)) continue;
                    // The checked source root selects the template body, but it is
                    // not part of a resolved specialization's identity. Recursive
                    // calls can reach the same template through a different checked
                    // root; exact interface, evidence, and lexical context prove
                    // that they refer to the same active specialization.
                    if (!specEvidenceVectorEql(spec.evidence, evidence)) continue;
                    if (!optionalTypeDigestEql(spec.lexical_context_key, lexical_context_key)) continue;
                    if (!try source_ctx.graph.typeIsSpecializationDefaultable(spec.request_fn_node)) continue;
                    const spec_fn_ty = try source_ctx.graph.specializationTypeViewForNode(spec.request_fn_node);
                    if (!try self.program.types.typeEql(&self.program.names, spec_fn_ty, request_fn_ty)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (selection.selected()) |raw_spec| {
            // A lowering specialization reached through an explicitly shared
            // interface class is a recursive edge. Fresh checked variables in
            // its new body instance are not joined until that edge is related,
            // so join the complete request before returning the in-progress
            // definition. Completed specializations reach here through exact
            // resolved identity, never through a partial interface overlap.
            const spec = &source_ctx.draft.template_specs.items[raw_spec];
            self.count("template_hits");
            const request_owner = source_ctx.draft.current_owner;
            const candidate_owner = source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].parent_owner;
            switch (request_owner) {
                .reserved_fn => |requesting_root| switch (candidate_owner) {
                    .reserved_fn => |candidate_root| if (requesting_root != candidate_root) {
                        self.countBodyDiagnostic("cross_root_template_reuses");
                    },
                    .root, .draft_fn => {},
                },
                .root, .draft_fn => {},
            }
            const active_recursive_edge = spec.state == .lowering and
                source_ctx.draft.ownerDescendsFromDraftFn(source_ctx.draft.current_owner, spec.fn_id);
            if (active_recursive_edge) {
                try source_ctx.graph.unifyRecursiveFunctionInterface(
                    spec.request_fn_node,
                    spec.initial_request_arg_classes,
                    request_fn_node,
                );
            } else {
                try source_ctx.graph.unify(spec.request_fn_node, request_fn_node);
            }
            if (!source_ctx.graph.sameFunctionInterface(spec.request_fn_node, request_fn_node)) {
                Common.invariant("recursive draft template request did not join its complete function interface");
            }
            if (signature_relation == .exact_graph) {
                source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation = .exact_graph;
            }
            if (spec.state != .deferred and !runtimeDemandGuardFrameSetsEql(
                spec.runtime_demand_guard_frames,
                try source_ctx.runtimeDemandGuardFrameAddresses(),
            )) {
                try source_ctx.draft.template_spec_reuses.append(self.allocator, .{
                    .spec = raw_spec,
                    .prefix_proof = try source_ctx.currentRuntimeImpossibilityProof(null),
                });
            }
            if (resolved_lookup_address) |address| {
                try registerTemplateSpecLookup(source_ctx.draft, self.allocator, address, raw_spec);
            }
            return .{ .local = .{ .draft = spec.fn_id } };
        }
        const is_local = moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template_ref).bytes);
        const fn_def: Ast.FnDef = switch (template.target) {
            .hosted => if (is_local)
                .{ .local_hosted = self.hostedFn(template_ref) }
            else
                .{ .imported_hosted = self.hostedFn(template_ref) },
            .roc, .intrinsic, .entry, .comptime_only => if (is_local)
                .{ .local_template = template_ref }
            else
                .{ .imported_template = template_ref },
        };
        const symbol = self.symbols.fresh();
        const fn_id = try source_ctx.draft.addFn(.{
            .source = .{
                .fn_def = fn_def,
                .source_fn_ty = source_fn_ty,
                .source_fn_key = source_fn_key,
                .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
                .evidence_digest = evidence_digest,
                .const_evidence = try self.program.addConstFnEvidence(stored_evidence.nodes),
                .const_evidence_frames = try self.program.addConstFnEvidenceFrames(stored_evidence.frames),
                .const_evidence_frame_head = stored_evidence.head,
            },
            .signature_relation = signature_relation,
        });
        self.count("template_misses");
        if (local_context_dependent and template.target == .hosted) {
            Common.invariant("hosted template specialization depended on a local procedure context");
        }
        if (local_context_dependent) {
            self.countBodyDiagnostic("caller_owned_template_bodies_lowered");
        } else {
            self.countBodyDiagnostic("deferred_template_requests");
        }
        const spec_index = source_ctx.draft.template_specs.items.len;
        const lexical = if (local_context_dependent)
            try source_ctx.captureCodecLexicalContext()
        else
            null;
        var lexical_needs_cleanup = lexical != null;
        errdefer if (lexical_needs_cleanup) {
            if (lexical) |captured| {
                self.allocator.free(captured.binders);
                self.allocator.free(captured.local_procs);
            }
        };
        const demand_boundary: u32 = @intCast(source_ctx.draft.runtime_value_demands.items.len);
        try source_ctx.draft.template_specs.append(self.allocator, .{
            .state = if (local_context_dependent) .lowering else .deferred,
            .template_ref = template_ref,
            .method_scope = source_ctx.method_scope.key,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .request_fn_node = request_fn_node,
            .initial_request_arg_classes = try source_ctx.graph.snapshotFunctionArgumentClasses(request_fn_node),
            .evidence = evidence,
            .runtime_demand_guard_frames = try source_ctx.runtimeDemandGuardFrameAddresses(),
            .demand_start = demand_boundary,
            .demand_end = demand_boundary,
            .demand_frame_floor = source_ctx.runtime_demand_guard_frames,
            .requires_local = local_context_dependent,
            .local_context_dependent = local_context_dependent,
            .lexical_owner = lexical_owner,
            .lexical = lexical,
            .lexical_context_key = lexical_context_key,
            .fn_id = fn_id,
        });
        try source_ctx.draft.template_spec_by_fn.put(fn_id, @intCast(spec_index));
        lexical_needs_cleanup = false;
        var indexed_nodes = collections.DenseMap(NodeId, void).init(self.allocator);
        defer indexed_nodes.deinit();
        var spec_interface = try source_ctx.graph.functionInterfaceIterator(request_fn_node);
        while (spec_interface.next()) |interface_node| {
            const indexed = try indexed_nodes.getOrPut(interface_node);
            if (indexed.found_existing) continue;
            const lookup_address = DraftTemplateLookupAddress{
                .family = family,
                .evidence_digest = evidence_digest.bytes,
                .request_kind = 1,
                .request_fn_key = draftOpenRequestKey(interface_node),
            };
            const lookup_entry = try source_ctx.draft.template_spec_lookup.getOrPut(lookup_address);
            if (!lookup_entry.found_existing) lookup_entry.value_ptr.* = .empty;
            try lookup_entry.value_ptr.append(self.allocator, @intCast(spec_index));
        }
        if (resolved_lookup_address) |address| {
            try registerTemplateSpecLookup(source_ctx.draft, self.allocator, address, @intCast(spec_index));
        }
        const owner_scope = try source_ctx.draft.enterOwner(.{ .draft_fn = fn_id });
        defer owner_scope.leave();
        try self.registerDraftProcDebugNameForTemplate(source_ctx.draft, symbol, view, template_ref);

        var body_ctx = try BodyContext.initWithMethodScope(self.allocator, self, view, source_ctx.method_scope, template_ref, source_ctx.graph, source_ctx.draft);
        body_ctx.evidence = rootEvidence(template_ref, evidence);
        body_ctx.runtime_demand_guard_frames = source_ctx.runtime_demand_guard_frames;
        body_ctx.frozen_sealed_emission = source_ctx.frozen_sealed_emission;
        body_ctx.frozen_type_finals = source_ctx.frozen_type_finals;
        body_ctx.frozen_codec_calls = source_ctx.frozen_codec_calls;
        defer body_ctx.deinit();
        if (lexical) |captured| try body_ctx.restoreCodecLexicalContext(captured);
        const root_node = try body_ctx.instNode(template.checked_fn_root);
        if (!local_context_dependent and
            signature_relation == .independent_roots and
            template.target != .hosted)
        {
            const public_request = source_ctx.graph.requestSourceInterface(request_fn_node) orelse request_fn_node;
            try constrainDeferredTemplateTypeArguments(source_ctx.graph, root_node, public_request);
        } else {
            if (template.target == .hosted) {
                try relateHostedFunctionRequestInterface(
                    source_ctx.graph,
                    try self.hostedTryAdapterCapability(view, template.hosted_try_adapter),
                    root_node,
                    request_fn_node,
                );
            } else if (try source_ctx.graph.containsGeneratedPrivate(request_fn_node)) {
                if (source_ctx.graph.requestSourceInterface(request_fn_node)) |source_fn_node| {
                    try relateFunctionRequestInterface(source_ctx.graph, root_node, source_fn_node);
                }
                try relateFunctionRequestInterface(source_ctx.graph, root_node, request_fn_node);
            } else {
                try source_ctx.graph.unify(root_node, request_fn_node);
            }
        }
        if (!local_context_dependent and template.target != .hosted) {
            try relateFunctionRequestInterface(source_ctx.graph, root_node, request_fn_node);
        }
        try body_ctx.instantiateTemplateDispatchRelations(template, null);
        try body_ctx.applyCheckedTemplateInterfaceRelations(template, root_node);
        if (!local_context_dependent) {
            return .{ .local = .{ .draft = fn_id } };
        }
        if (template.target == .hosted) {
            Common.invariant("hosted template specialization depended on a local procedure context");
        }
        body_ctx.owner_context_fn_key = source_fn_key;
        body_ctx.current_fn_key = source_fn_key;
        // A generated-private request is the exact runtime interface owned by
        // this specialization. The checked root remains the public interface
        // used to instantiate dispatch relations, but lowering the body
        // against it would discard the producer-supplied private backing from
        // parameters and returns.
        const body_fn_node = if (try source_ctx.graph.containsGeneratedPrivate(request_fn_node))
            request_fn_node
        else
            root_node;
        const lowered = try body_ctx.lowerTemplateBodyAtNode(template_ref, template, body_fn_node);
        const completed_fn_node = try body_ctx.completedFunctionNodeForLoweredRet(
            body_fn_node,
            lowered.ret,
            body_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
        );
        const completed_fn_ret = (try source_ctx.graph.functionNodes(completed_fn_node)).ret;
        const completed_ret_cell = DraftTypeCell.fromGraphNode(completed_fn_ret);

        var completed_template = source_ctx.draft.fns.items[@intFromEnum(fn_id)].source;
        completed_template.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_fn_node);
        _ = try source_ctx.draft.addNestedDef(.{
            .symbol = symbol,
            .fn_def = completed_template,
            .fn_id = .{ .draft = fn_id },
            .args = lowered.args,
            .body = lowered.body,
            .ret = completed_ret_cell,
        });
        source_ctx.draft.fns.items[@intFromEnum(fn_id)].source = completed_template;
        source_ctx.draft.template_specs.items[spec_index].request_fn_node = completed_fn_node;
        try registerTemplateSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            family,
            evidence_digest.bytes,
            completed_fn_node,
            @intCast(spec_index),
        );
        source_ctx.draft.template_specs.items[spec_index].state = .lowered;
        source_ctx.draft.template_specs.items[spec_index].demand_end =
            @intCast(source_ctx.draft.runtime_value_demands.items.len);
        return .{ .local = .{ .draft = fn_id } };
    }

    fn markTemplateReady(self: *Builder, fn_id: Ast.FnId, fn_ty: Type.TypeId) Allocator.Error!void {
        const entry = self.lowered_templates.get(fn_id) orelse
            Common.invariant("lowered procedure template definition disappeared before completion");
        try self.spec_store.markReady(entry.spec, fn_ty, self.specializationTypeDigest(fn_ty));
    }

    fn typedLocalsForArgs(self: *Builder, arg_tys: anytype) Allocator.Error!Ast.Span(Ast.TypedLocal) {
        const args = try self.allocator.alloc(Ast.TypedLocal, GuardedList.borrowLen(arg_tys));
        defer self.allocator.free(args);
        for (0..GuardedList.borrowLen(arg_tys)) |index| {
            const arg_ty = GuardedList.at(arg_tys, index);
            args[index] = .{
                .local = try self.program.addLocal(self.symbols.fresh(), arg_ty),
                .ty = arg_ty,
            };
        }
        return try self.program.addTypedLocalSpan(args);
    }

    fn fnDefForTemplate(
        self: *Builder,
        view: ModuleView,
        template: names.ProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        const fn_def: Ast.FnDef = switch (view.templates.get(template.template).target) {
            .hosted => if (moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template).bytes))
                .{ .local_hosted = self.hostedFn(template) }
            else
                .{ .imported_hosted = self.hostedFn(template) },
            .roc,
            .intrinsic,
            .entry,
            .comptime_only,
            => if (moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template).bytes))
                .{ .local_template = template }
            else
                .{ .imported_template = template },
        };

        return .{
            .fn_def = fn_def,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .mono_fn_ty = mono_fn_ty,
        };
    }

    fn addTemplateSpecRecord(
        self: *Builder,
        template_ref: names.ProcTemplate,
        method_scope: checked.ModuleId,
        source_fn_key: names.TypeDigest,
        evidence: StoredConstFnEvidence,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
        fn_id: Ast.FnId,
        status: Ast.SpecStatus,
    ) Allocator.Error!Ast.SpecId {
        const evidence_digest = Ast.fnEvidenceDigest(evidence.nodes, evidence.frames, evidence.head);
        return try self.addSpecRecord(
            templateSpecIdentity(template_ref, method_scope, source_fn_key, evidence_digest, request_fn_ty, request_fn_ty_digest),
            evidence,
            fn_id,
            status,
        );
    }

    fn addNestedSpecRecord(
        self: *Builder,
        nested: Ast.NestedFn,
        method_scope: checked.ModuleId,
        source_fn_key: names.TypeDigest,
        evidence: StoredConstFnEvidence,
        capture_abi_digest: names.TypeDigest,
        request_fn_ty: Type.TypeId,
        request_fn_ty_digest: names.TypeDigest,
        fn_id: Ast.FnId,
    ) Allocator.Error!Ast.SpecId {
        const evidence_digest = Ast.fnEvidenceDigest(evidence.nodes, evidence.frames, evidence.head);
        return try self.addSpecRecord(
            nestedSpecIdentity(nested, method_scope, source_fn_key, evidence_digest, capture_abi_digest, request_fn_ty, request_fn_ty_digest),
            evidence,
            fn_id,
            .lowering,
        );
    }

    fn addSpecRecord(
        self: *Builder,
        identity: Ast.SpecIdentity,
        evidence: StoredConstFnEvidence,
        fn_id: Ast.FnId,
        status: Ast.SpecStatus,
    ) Allocator.Error!Ast.SpecId {
        const reserved = try self.spec_store.reserve(identity, specializationEvidenceView(evidence), fn_id);
        if (!reserved.created) Common.invariant("Monotype specialization record already existed before lowering registered it");
        const spec = reserved.spec orelse Common.invariant("fresh Monotype specialization record resolved to an imported target");
        switch (status) {
            .reserved => {},
            .lowering => self.spec_store.markLowering(spec),
            .ready => Common.invariant("fresh Monotype specialization record cannot be created ready"),
        }
        return spec;
    }

    fn registerProcDebugNameForTemplate(
        self: *Builder,
        symbol: Common.Symbol,
        view: ModuleView,
        template: names.ProcTemplate,
    ) Allocator.Error!void {
        if (!self.proc_debug_names) return;
        const proc_base = view.names.procBase(template.proc_base);
        const export_name = proc_base.export_name orelse return;
        const name = try self.program.names.internExportName(view.names.exportNameText(export_name));
        try self.program.setProcDebugName(symbol, name);
    }

    fn registerDraftProcDebugNameForTemplate(
        self: *Builder,
        draft: *BodyDraftStore,
        symbol: Common.Symbol,
        view: ModuleView,
        template: names.ProcTemplate,
    ) Allocator.Error!void {
        if (!self.proc_debug_names) return;
        const proc_base = view.names.procBase(template.proc_base);
        const export_name = proc_base.export_name orelse return;
        const name = try self.program.names.internExportName(view.names.exportNameText(export_name));
        try draft.proc_debug_names.append(self.allocator, .{ .symbol = symbol, .name = name });
    }

    fn fnDefForProcedureBindingBody(
        self: *Builder,
        view: ModuleView,
        body: checked.ProcedureBindingBody,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        return switch (body) {
            .direct_template => |direct| self.fnDefForCallableTemplate(view, direct.template, source_fn_ty, source_fn_key, mono_fn_ty),
            .callable_eval_template => Common.invariant("callable eval template must be restored through ConstStore before Monotype lowering"),
        };
    }

    fn fnDefForCallableTemplate(
        self: *Builder,
        view: ModuleView,
        template: names.CallableProcTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        mono_fn_ty: Type.TypeId,
    ) Ast.FnTemplate {
        return switch (template) {
            .checked => |checked_template| self.fnDefForTemplate(view, checked_template, source_fn_ty, source_fn_key, mono_fn_ty),
            .lifted,
            .synthetic,
            => Common.invariant("checked procedure binding referenced a post-check function template"),
        };
    }

    /// Materialize a context-free Monotype request through the same explicit
    /// instantiation/freeze boundary as an ordinary requested specialization.
    /// A generalized checked field kind can therefore default for this one
    /// root without entering `type_cache` as a context-free required layout
    /// that would poison a later optional specialization.
    fn lowerContextFreeSpecializationType(
        self: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeId {
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, owner_template, graph, &body_draft);
        defer ctx.deinit();
        const node = try ctx.instNode(checked_ty);
        try graph.freezeRelations();
        return try graph.sealNode(node);
    }

    fn lowerType(self: *Builder, view: ModuleView, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        const address = checkedTypeAddress(view, checked_ty);
        if (self.type_cache.get(address)) |cached| return cached;

        const raw = @intFromEnum(checked_ty);
        if (raw >= view.types.payloadCount()) Common.invariant("checked type id outside checked type store");

        const Context = struct {
            builder: *Builder,
            address: CheckedTypeAddress,
            view: ModuleView,
            checked_ty: checked.CheckedTypeId,

            fn fill(context: @This(), reserved: Type.TypeId) Allocator.Error!Type.Content {
                try context.builder.type_cache.put(context.address, reserved);
                return try context.builder.lowerTypePayload(context.view, context.checked_ty, context.view.types.payload(context.checked_ty));
            }
        };
        return try self.program.types.addRecursive(Context{
            .builder = self,
            .address = address,
            .view = view,
            .checked_ty = checked_ty,
        }, Context.fill);
    }

    fn lowerTypePayload(self: *Builder, view: ModuleView, checked_ty: checked.CheckedTypeId, payload: checked.CheckedTypePayload) Allocator.Error!Type.Content {
        return switch (payload) {
            .pending => Common.invariant("pending checked type reached Monotype lowering"),
            .err => Common.invariant("erroneous checked type reached Monotype lowering"),
            .flex => |variable| lowerCheckedTypeVariable(variable),
            .rigid => |variable| lowerCheckedTypeVariable(variable),
            .empty_record => .{ .record = .empty() },
            .empty_tag_union => .{ .tag_union = .empty() },
            .record_unbound => |fields| try self.lowerRecordFields(view, fields),
            .record => |record| try self.lowerRecordRow(view, record.fields, record.ext),
            .tuple => |items| blk: {
                const lowered = try self.lowerTypeSlice(view, items);
                defer self.allocator.free(lowered);
                break :blk .{ .tuple = try self.program.types.addSpan(lowered) };
            },
            .tag_union => |tag_union| try self.lowerTagUnionRow(view, tag_union.tags, tag_union.ext),
            .function => |fn_ty| blk: {
                const args = try self.lowerTypeSlice(view, fn_ty.args);
                defer self.allocator.free(args);
                break :blk .{ .func = .{
                    .args = try self.program.types.addSpan(args),
                    .ret = try self.lowerType(view, fn_ty.ret),
                } };
            },
            .alias => |alias| blk: {
                const args = try self.lowerTypeSlice(view, alias.args);
                defer self.allocator.free(args);
                break :blk .{ .named = .{
                    .named_type = .{ .module = self.declaredModuleForAlias(view, alias), .ty = checked_ty },
                    .def = try self.typeDef(view, alias.origin_module, alias.name, alias.source_decl),
                    .kind = .alias,
                    .args = try self.program.types.addSpan(args),
                    .backing = .{
                        .ty = try self.lowerType(view, alias.backing),
                        .use = .inspectable,
                    },
                } };
            },
            .nominal => |nominal| blk: {
                switch (nominal.representation) {
                    .builtin => |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                        .primitive => |primitive| break :blk .{ .primitive = primitive },
                        .bool_tag_union => {},
                        .list => {
                            if (nominal.args.len != 1) Common.invariant("checked List nominal must have exactly one type argument");
                            break :blk .{ .list = try self.lowerType(view, nominal.args[0]) };
                        },
                        .box => {
                            if (nominal.args.len != 1) Common.invariant("checked Box nominal must have exactly one type argument");
                            break :blk .{ .box = try self.lowerType(view, nominal.args[0]) };
                        },
                        .try_nominal,
                        .iterator,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .dict,
                        .set,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                    },
                    .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => {},
                }

                const args = try self.lowerTypeSlice(view, nominal.args);
                defer self.allocator.free(args);
                const backing_use: Type.BackingUse = if (nominal.is_opaque) .runtime_layout_only else .inspectable;
                const def = try self.typeDef(view, nominal.origin_module, nominal.name, nominal.source_decl);
                self.noteBuiltinTryDef(nominal.builtin, def);
                break :blk .{ .named = .{
                    .named_type = .{ .module = self.declaredModuleForNominal(view, nominal), .ty = checked_ty },
                    .def = def,
                    .kind = if (nominal.is_opaque) .@"opaque" else .nominal,
                    .builtin_owner = builtinOwner(nominal.builtin),
                    .args = try self.program.types.addSpan(args),
                    .backing = switch (nominal.representation) {
                        .opaque_without_backing => null,
                        .builtin, .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability => .{
                            .ty = try self.lowerNominalBackingType(view, nominal, args),
                            .use = backing_use,
                        },
                    },
                    .declared_order = try self.declaredOrderForNominal(view, nominal),
                } };
            },
        };
    }

    fn lowerCheckedTypeVariable(variable: checked.CheckedTypeVariable) Type.Content {
        if (variable.numeric_default_phase) |phase| {
            const target = checked.literal_defaulting.defaultTargetForPhase(phase) orelse
                Common.invariant("checking-finalized numeric variable reached Monotype unresolved");
            return switch (target) {
                .dec => .{ .primitive = .dec },
                .str => .{ .primitive = .str },
            };
        }
        if (variable.row_default) |row_default| {
            return switch (row_default) {
                .empty_record => .{ .record = .empty() },
                .empty_tag_union => .{ .tag_union = .empty() },
            };
        }
        return .{ .tag_union = .empty() };
    }

    fn namedBackingType(self: *Builder, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.program.types.get(ty)) {
            .named => |named| if (named.backing) |backing| backing.ty else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    const NominalConstructionLayer = struct {
        named: Type.TypeId,
        backing: Type.TypeId,
    };

    /// The nominal construction layer of `ty`: the nominal or opaque named
    /// type reached after unwrapping transparent alias layers, paired with
    /// its declared backing type. Constructor expressions and patterns
    /// (tags, records, tuples) created at such a type must be typed at the
    /// backing and wrapped in an explicit `.nominal` node per layer, so that
    /// "the value is `.nominal`-wrapped" holds exactly when the type is
    /// nominal, independent of whether the source construction was written
    /// qualified. Returns null when `ty` is structural, an alias of a
    /// structural type, or a named type whose backing is not present.
    fn nominalConstructionLayer(self: *Builder, ty: Type.TypeId) ?NominalConstructionLayer {
        var current = ty;
        while (true) {
            switch (self.program.types.get(current)) {
                .named => |named| {
                    const backing = named.backing orelse return null;
                    switch (named.kind) {
                        .alias => current = backing.ty,
                        .nominal, .@"opaque" => return .{ .named = current, .backing = backing.ty },
                    }
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
            }
        }
    }

    fn shapeContent(self: *Builder, ty: Type.TypeId) Type.Content {
        var current = ty;
        while (true) {
            switch (self.program.types.get(current)) {
                .named => |named| if (named.backing) |backing| {
                    current = backing.ty;
                    continue;
                } else {
                    return self.program.types.get(current);
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return self.program.types.get(current),
            }
        }
    }

    fn typeHasBuiltinOwner(self: *Builder, ty: Type.TypeId, owner: static_dispatch.BuiltinOwner) bool {
        return switch (methodOwnerFromType(&self.program.types, ty) orelse return false) {
            .builtin => |actual| actual == owner,
            .nominal => false,
        };
    }

    fn typeIsBuiltinJsonEncoding(self: *Builder, ty: Type.TypeId) bool {
        return switch (self.program.types.get(ty)) {
            .named => |named| blk: {
                if (self.typeDefIsBuiltinJsonEncoding(named.def)) break :blk true;
                if (named.kind == .alias) {
                    if (named.backing) |backing| break :blk self.typeIsBuiltinJsonEncoding(backing.ty);
                }
                break :blk false;
            },
            _ => false,
        };
    }

    fn typeDefIsBuiltinJsonEncoding(self: *Builder, def: Type.TypeDef) bool {
        const type_name = self.program.names.typeNameText(def.type_name);
        if (!Ident.textEql(type_name, "JsonEncoding") and !Ident.textEql(type_name, "Builtin.Encoding.JsonEncoding")) return false;
        return self.moduleIdentityIsBuiltin(def.module);
    }

    fn moduleIdentityIsBuiltin(self: *Builder, module: names.ModuleIdentityId) bool {
        const origin_hash = self.program.names.moduleIdentityBytes(module);
        if (self.moduleViewHasBuiltinIdentity(moduleView(self.root_view), origin_hash)) return true;
        for (self.modules.imports) |imported| {
            if (self.moduleViewHasBuiltinIdentity(moduleView(imported), origin_hash)) return true;
        }
        for (self.modules.root.relation_modules) |relation| {
            if (self.moduleViewHasBuiltinIdentity(moduleView(relation), origin_hash)) return true;
        }
        return false;
    }

    fn moduleViewHasBuiltinIdentity(_: *Builder, view: ModuleView, origin_hash: *const [32]u8) bool {
        return view.module_env.module_role == .builtin and moduleViewIdentityMatches(view, origin_hash);
    }

    fn recordFieldByTextOptional(self: *Builder, ty: Type.TypeId, text: []const u8) ?Type.Field {
        const fields = switch (self.shapeContent(ty)) {
            .record => |span| self.program.types.fieldSpan(span),
            .zst => return null,
            _ => return null,
        };
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (Ident.textEql(self.program.names.recordFieldLabelText(field.name), text)) return field;
        }
        return null;
    }

    fn generatedFieldNamesBackingInfo(self: *Builder, fields_ty: Type.TypeId) bool {
        if (!self.typeHasBuiltinOwner(fields_ty, .fields)) return false;
        const backing_ty = self.namedBackingType(fields_ty) orelse return false;
        const items_field = self.recordFieldByTextOptional(backing_ty, "items") orelse return false;
        const shortest_field = self.recordFieldByTextOptional(backing_ty, "shortest_name") orelse return false;
        const longest_field = self.recordFieldByTextOptional(backing_ty, "longest_name") orelse return false;
        if (!self.typeHasBuiltinOwner(shortest_field.ty, .u64)) return false;
        if (!self.typeHasBuiltinOwner(longest_field.ty, .u64)) return false;
        _ = switch (self.shapeContent(items_field.ty)) {
            .record, .zst => {},
            _ => return false,
        };
        return true;
    }

    fn generatedParseTagUnionSpecBackingInfo(self: *Builder, spec_ty: Type.TypeId) bool {
        if (!self.typeHasBuiltinOwner(spec_ty, .parse_tag_union_spec)) return false;
        const backing_ty = self.namedBackingType(spec_ty) orelse return false;
        return switch (self.shapeContent(backing_ty)) {
            .record => |span| self.program.types.fieldSpan(span).len != 0,
            .zst => false,
            _ => return false,
        };
    }

    fn functionShape(self: *Builder, ty: Type.TypeId, comptime message: []const u8) FunctionShape {
        return switch (self.shapeContent(ty)) {
            .func => |func| .{ .args = func.args, .ret = func.ret },
            .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => Common.invariant(message),
        };
    }

    fn tupleItemSpan(self: *Builder, ty: Type.TypeId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .tuple => |items| items,
            .primitive, .named, .record, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("tuple pattern had a non-tuple checked type"),
        };
    }

    fn recordFieldsSpan(self: *Builder, ty: Type.TypeId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .record => |fields| fields,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record pattern had a non-record checked type"),
        };
    }

    fn tagPayloadSpan(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.Span {
        return switch (self.shapeContent(ty)) {
            .tag_union => |tags| {
                const tag_span = self.program.types.tagSpan(tags);
                for (0..GuardedList.borrowLen(tag_span)) |index| {
                    const tag = GuardedList.at(tag_span, index);
                    if (self.program.names.tagLabelTextEql(tag.name, name)) return tag.payloads;
                }
                Common.invariant("tag pattern was absent from checked tag-union type");
            },
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag pattern had a non-tag-union checked type"),
        };
    }

    fn lowerNominalBackingType(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        mono_args: []const Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, .{
            .proc_base = undefined, // type-only context; type lowering does not read the owner template
            .template = undefined, // type-only context; type lowering does not read the owner template
        }, graph, &body_draft);
        defer ctx.deinit();
        if (nominal.args.len != mono_args.len) {
            Common.invariant("checked nominal type argument arity differed from monotype named argument arity");
        }
        for (nominal.args, mono_args) |checked_arg, mono_arg| {
            try ctx.constrainTypeToMono(checked_arg, mono_arg);
        }
        const source = ctx.nominalInstantiationSource(nominal) orelse {
            Common.invariant("nominal backing type lowering could not resolve a declaration-backed nominal");
        };
        const arg_nodes = try graph.arena().alloc(NodeId, mono_args.len);
        for (mono_args, 0..) |mono_arg, index| {
            arg_nodes[index] = try graph.importMono(mono_arg);
        }
        const backing_node = try ctx.instNominalDeclarationBackingNode(source, arg_nodes);
        try graph.freezeRelations();
        const backing = try graph.sealNode(backing_node);
        return try self.structuralBackingForNominal(view, nominal, mono_args, backing);
    }

    fn structuralBackingForNominal(
        self: *Builder,
        view: ModuleView,
        nominal: checked.CheckedNominalType,
        mono_args: []const Type.TypeId,
        backing: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const owner_def = try self.typeDef(view, nominal.origin_module, nominal.name, nominal.source_decl);
        var seen = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen.deinit();
        var current = backing;
        while (true) {
            if (seen.contains(current)) return current;
            try seen.put(current, {});
            switch (self.program.types.get(current)) {
                .named => |named| {
                    if (named.kind != .alias and (!sameTypeDef(named.def, owner_def) or !self.sameNominalArgs(named.args, mono_args))) {
                        return current;
                    }
                    const next = named.backing orelse return current;
                    current = next.ty;
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return current,
            }
        }
    }

    fn sameNominalArgs(self: *Builder, actual_span: Type.Span, expected: []const Type.TypeId) bool {
        const actual = self.program.types.span(actual_span);
        if (actual.len != expected.len) return false;
        for (expected, 0..) |expected_ty, index| {
            const actual_ty = GuardedList.at(actual, index);
            if (actual_ty == expected_ty) continue;
            const actual_digest = self.program.types.specializationDigest(&self.program.names, actual_ty);
            const expected_digest = self.program.types.specializationDigest(&self.program.names, expected_ty);
            if (!std.mem.eql(u8, actual_digest.bytes[0..], expected_digest.bytes[0..])) return false;
        }
        return true;
    }

    fn tupleItemTypes(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        return self.program.types.span(self.tupleItemSpan(ty));
    }

    fn recordField(self: *Builder, ty: Type.TypeId, name: names.RecordFieldNameId) Type.Field {
        const fields = self.program.types.fieldSpan(self.recordFieldsSpan(ty));
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (self.program.names.recordFieldLabelTextEql(field.name, name)) return field;
        }
        Common.invariant("record pattern field was absent from checked record type");
    }

    fn recordFieldType(self: *Builder, ty: Type.TypeId, name: names.RecordFieldNameId) Type.TypeId {
        return self.recordField(ty, name).ty;
    }

    fn tagPayloadTypes(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.StoreSpanBorrow(Type.TypeId, "spans") {
        return self.program.types.span(self.tagPayloadSpan(ty, name));
    }

    /// The closed structural tagged slot of an optional field:
    /// `[#Missing, #Present(payload)]`. Tag variants normalize to sorted label
    /// order, so `#Missing` is variant 0 (no payload) and `#Present` is
    /// variant 1—the discriminant contract every consumer (construction,
    /// `.?` runtime tests, layout, glue) shares.
    fn optionalSlotType(self: *Builder, payload_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        const missing = try self.program.names.internTagLabel(optional_slot_missing_tag);
        const present = try self.program.names.internTagLabel(optional_slot_present_tag);
        const tags = [_]Type.Tag{
            .{ .name = missing, .checked_name = missing, .payloads = Type.Span.empty() },
            .{ .name = present, .checked_name = present, .payloads = try self.program.types.addSpan(&[_]Type.TypeId{payload_ty}) },
        };
        return try self.program.types.add(.{ .tag_union = try self.program.types.addTagVariants(&self.program.names, &tags) });
    }

    /// The tags and payload type of an optional field's Monotype tagged slot.
    fn optionalSlotInfo(self: *Builder, slot_ty: Type.TypeId) Allocator.Error!OptionalSlotInfo {
        const missing_name = try self.program.names.internTagLabel(optional_slot_missing_tag);
        const present_name = try self.program.names.internTagLabel(optional_slot_present_tag);
        const missing_tag = self.tagByNameOrNull(slot_ty, missing_name) orelse
            Common.invariant("optional field slot type had no Missing tag");
        const present_tag = self.tagByNameOrNull(slot_ty, present_name) orelse
            Common.invariant("optional field slot type had no Present tag");
        if (self.program.types.span(missing_tag.payloads).len != 0) {
            Common.invariant("optional field slot Missing tag unexpectedly had payloads");
        }
        const present_payloads = self.program.types.span(present_tag.payloads);
        if (present_payloads.len != 1) {
            Common.invariant("optional field slot Present tag must carry exactly one payload");
        }
        return .{
            .payload_ty = GuardedList.at(present_payloads, 0),
            .missing_tag = missing_tag,
            .present_tag = present_tag,
        };
    }

    /// Recognize the compiler-reserved optional-slot encoding when only a
    /// completed Monotype is available (design.md "Field Kinds").
    fn optionalFieldSlot(self: *Builder, slot_ty: Type.TypeId) ?OptionalSlotInfo {
        const tags = switch (self.program.types.get(slot_ty)) {
            .tag_union => |span_| self.program.types.tagSpan(span_),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
        };
        if (tags.len != 2) return null;
        // Tag normalization gives #Missing index 0 and #Present index 1.
        const missing_tag = GuardedList.at(tags, 0);
        const present_tag = GuardedList.at(tags, 1);
        if (!std.mem.eql(u8, self.program.names.tagLabelText(missing_tag.name), optional_slot_missing_tag)) return null;
        if (!std.mem.eql(u8, self.program.names.tagLabelText(present_tag.name), optional_slot_present_tag)) return null;
        if (self.program.types.span(missing_tag.payloads).len != 0) return null;
        const present_payloads = self.program.types.span(present_tag.payloads);
        if (present_payloads.len != 1) return null;
        return .{
            .payload_ty = GuardedList.at(present_payloads, 0),
            .missing_tag = missing_tag,
            .present_tag = present_tag,
        };
    }

    fn lowerRecordFields(self: *Builder, view: ModuleView, fields: []const checked.CheckedRecordField) Allocator.Error!Type.Content {
        const lowered = try self.allocator.alloc(Type.Field, fields.len);
        defer self.allocator.free(lowered);
        for (fields, 0..) |field, i| {
            const value_ty = try self.lowerType(view, field.ty);
            lowered[i] = .{
                .name = try self.recordFieldName(view, field.name),
                .ty = switch (field.kind.tag) {
                    .required, .defaulted => value_ty,
                    .optional => try self.optionalSlotType(value_ty),
                    .undetermined => Common.invariant("undetermined checked field kind reached direct record lowering"),
                    .err => Common.invariant("poisoned checked field kind reached direct record lowering"),
                },
                .value_ty = if (field.kind.tag == .optional) value_ty else null,
                .default = try self.monoFieldDefault(view, field),
            };
        }
        return .{ .record = try self.program.types.addRecordFields(&self.program.names, lowered) };
    }

    /// Translate a checked `??` identity into the Monotype name store.
    fn monoFieldDefault(self: *Builder, view: ModuleView, field: checked.CheckedRecordField) Allocator.Error!?Type.FieldDefault {
        const default = field.kind.defaultIdentity() orelse return null;
        const origin_module = default.origin() orelse Common.invariant("defaulted checked field carried no default origin module");
        return .{
            .module = try self.program.names.internModuleIdentity(view.names.moduleIdentityBytes(origin_module)),
            .expr_node = default.expr_node,
        };
    }

    fn lowerRecordRow(
        self: *Builder,
        view: ModuleView,
        head: []const checked.CheckedRecordField,
        ext: checked.CheckedTypeId,
    ) Allocator.Error!Type.Content {
        var fields = std.ArrayList(Type.Field).empty;
        defer fields.deinit(self.allocator);
        try self.appendRecordFields(view, &fields, head);

        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();

        var current = ext;
        while (true) {
            if (seen.contains(current)) break;
            try seen.put(current, {});

            const payload = checkedPayload(view, current);
            switch (payload) {
                .alias => |alias| current = alias.backing,
                .empty_record => break,
                .flex, .rigid => |variable| {
                    if (variable.row_default == .empty_record) break;
                    Common.invariant("open non-record checked row reached Monotype record lowering");
                },
                .record_unbound => |tail_fields| {
                    try self.appendRecordFields(view, &fields, tail_fields);
                    break;
                },
                .record => |record| {
                    try self.appendRecordFields(view, &fields, record.fields);
                    current = record.ext;
                },
                .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => Common.invariant("open or non-record checked row reached Monotype record lowering"),
            }
        }

        return .{ .record = try self.program.types.addRecordFields(&self.program.names, fields.items) };
    }

    fn appendRecordFields(
        self: *Builder,
        view: ModuleView,
        out: *std.ArrayList(Type.Field),
        fields: []const checked.CheckedRecordField,
    ) Allocator.Error!void {
        for (fields) |field| {
            const value_ty = try self.lowerType(view, field.ty);
            try out.append(self.allocator, .{
                .name = try self.recordFieldName(view, field.name),
                .ty = switch (field.kind.tag) {
                    .required, .defaulted => value_ty,
                    .optional => try self.optionalSlotType(value_ty),
                    .undetermined => Common.invariant("undetermined checked field kind reached direct record-row lowering"),
                    .err => Common.invariant("poisoned checked field kind reached direct record-row lowering"),
                },
                .value_ty = if (field.kind.tag == .optional) value_ty else null,
                .default = try self.monoFieldDefault(view, field),
            });
        }
    }

    fn lowerTagUnionRow(
        self: *Builder,
        view: ModuleView,
        head: []const checked.CheckedTag,
        ext: checked.CheckedTypeId,
    ) Allocator.Error!Type.Content {
        var tags = std.ArrayList(Type.Tag).empty;
        defer tags.deinit(self.allocator);
        try self.appendTags(view, &tags, head);

        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();

        var current = ext;
        while (true) {
            if (seen.contains(current)) break;
            try seen.put(current, {});

            const payload = checkedPayload(view, current);
            switch (payload) {
                .alias => |alias| current = alias.backing,
                .empty_tag_union => break,
                .flex, .rigid => |variable| {
                    if (variable.row_default == .empty_tag_union) break;
                    Common.invariant("open non-tag checked row reached Monotype tag-union lowering");
                },
                .tag_union => |tag_union| {
                    try self.appendTags(view, &tags, tag_union.tags);
                    current = tag_union.ext;
                },
                .pending, .err, .record, .record_unbound, .tuple, .nominal, .function, .empty_record => Common.invariant("open or non-tag checked row reached Monotype tag-union lowering"),
            }
        }

        return .{ .tag_union = try self.program.types.addTagVariants(&self.program.names, tags.items) };
    }

    fn appendTags(
        self: *Builder,
        view: ModuleView,
        out: *std.ArrayList(Type.Tag),
        tags: []const checked.CheckedTag,
    ) Allocator.Error!void {
        for (tags) |tag| {
            const payloads = try self.lowerTypeSlice(view, tag.argsSlice(view.types));
            defer self.allocator.free(payloads);
            const tag_name = try self.tagName(view, tag.name);
            try out.append(self.allocator, .{
                .name = tag_name,
                .checked_name = tag_name,
                .payloads = try self.program.types.addSpan(payloads),
            });
        }
    }

    fn lowerTypeSlice(self: *Builder, view: ModuleView, checked_tys: []const checked.CheckedTypeId) Allocator.Error![]Type.TypeId {
        const out = try self.allocator.alloc(Type.TypeId, checked_tys.len);
        errdefer self.allocator.free(out);
        for (checked_tys, 0..) |ty, i| {
            out[i] = try self.lowerType(view, ty);
        }
        return out;
    }

    fn moduleForDigest(self: *Builder, module_digest: names.CheckedModuleDigest) ModuleView {
        if (moduleBytesEqual(module_digest.bytes, self.root_view.key.bytes)) return moduleView(self.root_view);
        for (self.modules.imports) |imported| {
            if (moduleBytesEqual(module_digest.bytes, imported.key.bytes)) return moduleView(imported);
        }
        for (self.modules.root.relation_modules) |relation| {
            if (moduleBytesEqual(module_digest.bytes, relation.key.bytes)) return moduleView(relation);
        }
        Common.invariant("procedure template referenced a checked module that is not in the lowering input");
    }

    /// The module view whose content identity matches `origin_hash`, or null
    /// (used to resolve a defaulted field's declaring module—design.md
    /// "Defaulted Fields").
    fn moduleForIdentityHash(self: *Builder, origin_hash: *const [32]u8) ?ModuleView {
        const root = moduleView(self.root_view);
        if (moduleViewIdentityMatches(root, origin_hash)) return root;
        for (self.modules.imports) |imported| {
            const view = moduleView(imported);
            if (moduleViewIdentityMatches(view, origin_hash)) return view;
        }
        for (self.modules.root.relation_modules) |relation| {
            const view = moduleView(relation);
            if (moduleViewIdentityMatches(view, origin_hash)) return view;
        }
        return null;
    }

    fn moduleForId(self: *Builder, module_id: checked.ModuleId) ModuleView {
        if (moduleBytesEqual(module_id.bytes, self.root_view.key.bytes)) return moduleView(self.root_view);
        for (self.modules.imports) |imported| {
            if (moduleBytesEqual(module_id.bytes, imported.key.bytes)) return moduleView(imported);
        }
        for (self.modules.root.relation_modules) |relation| {
            if (moduleBytesEqual(module_id.bytes, relation.key.bytes)) return moduleView(relation);
        }
        Common.invariant("procedure binding referenced a checked module that is not in the lowering input");
    }

    const NominalDeclLookup = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
        /// Unnamed padding field types (declared order), in `view`'s store. For a
        /// box-payload capability this is the *instance's* substituted padding, so
        /// type-parameterized padding reserves its instantiated size; for a direct
        /// declaration it is the declaration's own padding types.
        padding_field_tys: []const checked.CheckedTypeId,
    };

    /// Resolves a nominal's checked declaration across every representation that
    /// has one, for reading declared field order. The box-payload representation
    /// is the common case for record nominals (assigned while the checked module
    /// data is built), so it must be handled, not just `*_declaration`.
    fn nominalDeclarationFor(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) ?NominalDeclLookup {
        return switch (nominal.representation) {
            .local_declaration => |id| blk: {
                const decl = view.types.nominalDeclarationById(id);
                break :blk .{ .view = view, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(view.types) };
            },
            .imported_declaration => |imported| blk: {
                const sv = self.moduleForId(checked.importedNominalDeclarationModuleId(imported));
                const decl = sv.types.nominalDeclarationById(imported.declaration);
                break :blk .{ .view = sv, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(sv.types) };
            },
            .local_box_payload_capability => |cap| blk: {
                const capability = view.interface_capabilities.boxPayloadCapability(cap.capability);
                const decl = view.types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{ .view = view, .declaration = decl, .padding_field_tys = capability.paddingFieldTys(view.interface_capabilities) };
            },
            .imported_box_payload_capability => |cap| blk: {
                const sv = self.moduleForId(checked.importedBoxPayloadCapabilityModuleId(cap));
                const capability = sv.interface_capabilities.boxPayloadCapability(cap.capability);
                const decl = sv.types.nominalDeclaration(capability.nominal) orelse break :blk null;
                break :blk .{ .view = sv, .declaration = decl, .padding_field_tys = capability.paddingFieldTys(sv.interface_capabilities) };
            },
            .builtin => blk: {
                const source_view = self.moduleForId(nominal.owner_module);
                const source_decl = nominal.source_decl orelse break :blk null;
                for (source_view.types.nominal_declarations) |decl| {
                    if (decl.source_statement != source_decl) continue;
                    break :blk .{ .view = source_view, .declaration = decl, .padding_field_tys = decl.paddingFieldTypes(source_view.types) };
                }
                break :blk null;
            },
            .opaque_without_backing => null,
        };
    }

    /// Builds the declared-field-order span for a nominal/opaque record backing
    /// from its source declaration (the declaration backing preserves source
    /// order, unlike the lexicographically-sorted lowered row). Returns the empty
    /// span for non-record backings or encodings that intentionally have no
    /// declaration backing. The span feeds layout selection only; the lowered
    /// row stays lexicographic.
    fn declaredOrderForNominal(self: *Builder, view: ModuleView, nominal: checked.CheckedNominalType) Allocator.Error!Type.Span {
        if (nominal.declared_fields.len != 0) {
            return try self.lowerCheckedDeclaredOrder(view, nominal.declared_fields, view, nominal.padding_field_types);
        }
        const lookup = self.nominalDeclarationFor(view, nominal) orelse {
            if (!nominalHasDeclarationBacking(nominal)) return Type.Span.empty();
            Common.invariant("declaration-backed nominal reached Monotype lowering without declaration data");
        };
        const declared_fields = lookup.declaration.declaredFields(lookup.view.types);
        if (declared_fields.len != 0) {
            return try self.lowerCheckedDeclaredOrder(
                lookup.view,
                declared_fields,
                lookup.view,
                lookup.padding_field_tys,
            );
        }
        const fields = lookup.declaration.declaredRecordFields(lookup.view.types);
        if (fields.len == 0) return Type.Span.empty();
        // Unnamed fields are layout padding; their resolved checked types ride on
        // the declaration in declared order and are pulled sequentially as each
        // unnamed field is encountered while walking the declared field rows.
        // Padding types come from the lookup, which for an instantiated nominal
        // (box-payload capability) carries the *instance's* substituted padding
        // types—so a type-parameterized padding field (`_ : a`) reserves the
        // instantiated size, exactly like a named field of the same type.
        const padding_types = lookup.padding_field_tys;
        const padding_view = lookup.view;
        var padding_cursor: usize = 0;
        const entries = try self.allocator.alloc(Type.DeclaredField, fields.len);
        defer self.allocator.free(entries);
        for (fields, 0..) |field, i| {
            switch (field) {
                .named => |label| entries[i] = .{ .named = try self.recordFieldName(lookup.view, label) },
                .padding => {
                    if (padding_cursor >= padding_types.len) {
                        Common.invariant("nominal declaration had more unnamed fields than recorded padding types");
                    }
                    const checked_ty = padding_types[padding_cursor];
                    padding_cursor += 1;
                    entries[i] = .{ .padding = try self.lowerType(padding_view, checked_ty) };
                },
            }
        }
        return try self.program.types.addDeclaredFields(entries);
    }

    fn lowerCheckedDeclaredOrder(
        self: *Builder,
        field_view: ModuleView,
        fields: []const checked.CheckedDeclaredField,
        padding_view: ModuleView,
        padding_types: []const checked.CheckedTypeId,
    ) Allocator.Error!Type.Span {
        const entries = try self.allocator.alloc(Type.DeclaredField, fields.len);
        defer self.allocator.free(entries);
        for (fields, 0..) |field, i| {
            entries[i] = switch (field) {
                .named => |name| .{ .named = try self.recordFieldName(field_view, name) },
                .padding => |index| blk: {
                    const raw_index: usize = @intCast(index);
                    if (raw_index >= padding_types.len) {
                        Common.invariant("nominal declaration declared-order padding index was out of range");
                    }
                    break :blk .{ .padding = try self.lowerType(padding_view, padding_types[raw_index]) };
                },
            };
        }
        return try self.program.types.addDeclaredFields(entries);
    }

    fn constNode(self: *Builder, const_locator: checked.ConstLocator, node: ?checked.ConstNodeId) ConstNode {
        const view = self.moduleForId(checked.constModuleId(const_locator));
        if (node) |id| return .{ .module = view, .id = id };
        const template = view.const_templates.get(const_locator);
        return switch (template.state) {
            .stored_const => |stored| .{ .module = view, .id = stored.node },
            .reserved,
            .eval_template,
            => Common.invariant("static data request const was not stored before Monotype lowering"),
        };
    }

    fn staticDataValue(
        self: *Builder,
        const_locator: checked.ConstLocator,
        node: ?checked.ConstNodeId,
        checked_type: checked.CheckedTypeId,
        type_cell: DraftTypeCell,
    ) Allocator.Error!Common.StaticDataId {
        const const_node = self.constNode(const_locator, node);
        const use = StaticDataUse{
            .module = const_node.module.key,
            .node = const_node.id,
            .checked_type = checked_type,
            .type_cell = type_cell,
        };
        if (self.static_data_ids.get(use)) |existing| return existing;

        // Structural dedup can only compare committed types; graph cells keep
        // identity comparison until final sealing commits them.
        if (use.type_cell == .sealed) {
            for (self.static_data_uses.items, 0..) |existing, index| {
                if (!moduleBytesEqual(existing.module.bytes, use.module.bytes) or
                    existing.node != use.node or
                    existing.checked_type != use.checked_type)
                {
                    continue;
                }
                const existing_ty = switch (existing.type_cell) {
                    .sealed => |ty| ty,
                    .graph_node => continue,
                };
                if (!try self.program.types.typeEql(&self.program.names, existing_ty, use.type_cell.sealed)) continue;

                const id: Common.StaticDataId = @enumFromInt(@as(u32, @intCast(index)));
                try self.static_data_ids.put(use, id);
                return id;
            }
        }

        const id = try self.program.addStaticDataValue(.{
            .const_locator = const_locator,
            .node = node,
            .checked_type = checked_type,
        });
        if (@intFromEnum(id) != self.static_data_uses.items.len) {
            Common.invariant("Monotype static-data use index diverged from program id");
        }
        try self.static_data_uses.append(self.allocator, use);
        try self.static_data_ids.put(use, id);
        return id;
    }

    const BareFnCandidate = enum {
        disallow,
        allow,
    };

    fn constNodeMayUseStaticDataCandidate(self: *Builder, view: ModuleView, node: checked.ConstNodeId, bare_fn: BareFnCandidate) bool {
        return self.constValueMayUseStaticDataCandidate(view, view.const_store.get(node), bare_fn);
    }

    fn constNodeHasStableStaticDataRepresentation(
        self: *Builder,
        view: ModuleView,
        node: checked.ConstNodeId,
    ) Allocator.Error!bool {
        const address = ConstNodeAddress{ .module = view.key, .node = node };
        if (self.static_data_eligibility.get(address)) |stable| return stable;

        const stable = switch (view.const_store.get(node)) {
            .pending => Common.invariant("pending ConstStore node reached static data eligibility"),
            .fn_value => false,
            .zst,
            .scalar,
            .str,
            .crash,
            => true,
            .box => |child| try self.constNodeHasStableStaticDataRepresentation(view, child),
            .list => |list| switch (list) {
                .scalar_bytes => true,
                .nodes => |children| blk: {
                    for (children) |child| {
                        if (!try self.constNodeHasStableStaticDataRepresentation(view, child)) break :blk false;
                    }
                    break :blk true;
                },
            },
            .tuple,
            .record,
            => |children| blk: {
                for (children) |child| {
                    if (!try self.constNodeHasStableStaticDataRepresentation(view, child)) break :blk false;
                }
                break :blk true;
            },
            .tag => |tag| blk: {
                for (tag.payloads) |child| {
                    if (!try self.constNodeHasStableStaticDataRepresentation(view, child)) break :blk false;
                }
                break :blk true;
            },
            .nominal => |nominal| try self.constNodeHasStableStaticDataRepresentation(view, nominal.backing),
        };
        try self.static_data_eligibility.put(address, stable);
        return stable;
    }

    fn constValueMayUseStaticDataCandidate(self: *Builder, view: ModuleView, value: checked.ConstValue, bare_fn: BareFnCandidate) bool {
        return switch (value) {
            .pending => Common.invariant("pending ConstStore node reached static data selection"),
            .zst,
            .scalar,
            .crash,
            => false,
            .str => |str| self.constStrNeedsStaticData(view, str),
            .fn_value => bare_fn == .allow,
            .list => |list| switch (list) {
                .nodes => |items| items.len != 0,
                .scalar_bytes => |scalar_bytes| scalar_bytes.len != 0,
            },
            .box => true,
            .tuple,
            .record,
            .tag,
            => true,
            .nominal => |nominal| self.constValueMayUseStaticDataCandidate(view, view.const_store.get(nominal.backing), .allow),
        };
    }

    fn constStrNeedsStaticData(self: *Builder, view: ModuleView, str: check.ConstStore.ConstStr) bool {
        const str_bytes = view.const_store.strBytes(str);
        const backing = view.const_store.blobData(str.data);
        const roc_str_size = self.target_usize.size() * 3;
        return backing.len >= roc_str_size or str_bytes.len >= roc_str_size;
    }

    fn lookupMethodTarget(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_view: ModuleView,
        method: names.MethodNameId,
    ) Allocator.Error!?MethodLookup {
        return try self.lookupMethodTargetByName(scope, owner, method_view.names.methodNameText(method));
    }

    fn lookupMethodTargetByName(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) Allocator.Error!?MethodLookup {
        const method = try self.program.names.internMethodName(method_name);
        const address = ScopedMethodDispatch.init(scope.key, owner, method);
        if (self.scoped_method_targets.get(address)) |resolution| {
            return switch (resolution) {
                .missing => null,
                .target => |target| target,
            };
        }

        const resolution: ScopedMethodResolution = if (self.findMethodTargetByName(scope, owner, method_name)) |target|
            .{ .target = target }
        else
            .missing;

        try self.scoped_method_targets.put(self.allocator, address, resolution);
        return switch (resolution) {
            .missing => null,
            .target => |target| target,
        };
    }

    fn findMethodTargetByName(
        self: *Builder,
        scope: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
    ) ?MethodLookup {
        if (self.methodTargetInView(scope, owner, method_name, true)) |target| return target;
        for (scope.method_lookup_scope) |module_id| {
            const candidate = self.moduleForId(module_id);
            if (self.methodTargetInView(candidate, owner, method_name, false)) |target| return target;
        }
        return null;
    }

    fn methodTargetInView(
        self: *Builder,
        view: ModuleView,
        owner: static_dispatch.MethodOwner,
        method_name: []const u8,
        allow_local_proc: bool,
    ) ?MethodLookup {
        const view_owner = static_dispatch.methodOwnerInImportedStore(&self.program.names, view.names, owner) orelse return null;
        const view_method = view.names.lookupMethodName(method_name) orelse return null;
        const target = view.method_registry.lookup(.{ .owner = view_owner, .method = view_method }) orelse return null;
        if (!allow_local_proc and target.kind == .local_proc) return null;
        return .{ .view = view, .target = target };
    }

    fn noteBuiltinTryDef(
        self: *Builder,
        builtin: ?checked.CheckedBuiltinNominal,
        def: Type.TypeDef,
    ) void {
        if (builtin == null or builtin.? != .try_) return;
        if (self.builtin_try_def) |existing| {
            if (!sameTypeDef(existing, def)) {
                Common.invariant("checked modules disagreed on the builtin Try definition identity");
            }
        } else {
            self.builtin_try_def = def;
        }
    }

    fn isBuiltinTryDef(self: *const Builder, def: Type.TypeDef) bool {
        const expected = self.builtin_try_def orelse return false;
        return sameTypeDef(expected, def);
    }

    fn importModuleAlreadyScanned(self: *Builder, module_id: checked.ModuleId, import_index: usize) bool {
        if (moduleBytesEqual(module_id.bytes, self.root_view.key.bytes)) return true;
        for (self.modules.imports[0..import_index]) |imported| {
            if (moduleBytesEqual(module_id.bytes, imported.key.bytes)) return true;
        }
        return false;
    }

    fn relationModuleAlreadyScanned(self: *Builder, module_id: checked.ModuleId, relation_index: usize) bool {
        if (moduleBytesEqual(module_id.bytes, self.root_view.key.bytes)) return true;
        for (self.modules.imports) |imported| {
            if (moduleBytesEqual(module_id.bytes, imported.key.bytes)) return true;
        }
        for (self.modules.root.relation_modules[0..relation_index]) |relation| {
            if (moduleBytesEqual(module_id.bytes, relation.key.bytes)) return true;
        }
        return false;
    }

    fn templateRefForProcedureUse(
        self: *Builder,
        proc: checked.ProcedureUseTemplate,
    ) names.ProcTemplate {
        return switch (proc.binding) {
            .top_level => |top_level| blk: {
                const view = self.moduleForId(checked.topLevelProcedureModuleId(top_level));
                const binding = view.top_level_procedure_bindings.get(top_level.binding);
                break :blk switch (binding.body) {
                    .direct_template => |direct| switch (direct.template) {
                        .checked => |template| template,
                        .lifted => Common.invariant("lifted direct target reached Monotype procedure use"),
                        .synthetic => Common.invariant("synthetic direct target reached Monotype procedure use"),
                    },
                    .callable_eval_template => Common.invariant("callable-eval template reached Monotype procedure use"),
                };
            },
            .imported => |imported| blk: {
                const view = self.moduleForId(checked.importedProcedureModuleId(imported));
                for (view.exported_procedure_bindings.bindings) |binding| {
                    if (binding.binding.def == imported.def and binding.binding.pattern == imported.pattern) {
                        break :blk switch (binding.body) {
                            .direct_template => |direct| switch (direct.template) {
                                .checked => |template| template,
                                .lifted => Common.invariant("imported lifted target reached Monotype procedure use"),
                                .synthetic => Common.invariant("imported synthetic target reached Monotype procedure use"),
                            },
                            .callable_eval_template => Common.invariant("imported callable-eval template reached Monotype procedure use"),
                        };
                    }
                }
                Common.invariant("imported procedure binding was not exported by its checked module");
            },
            .hosted => |hosted| hosted.template,
            .platform_required => |required| blk: {
                const view = self.moduleForId(checked.requiredProcedureModuleId(required));
                const binding = view.top_level_procedure_bindings.get(required.procedure_binding);
                break :blk switch (binding.body) {
                    .direct_template => |direct| switch (direct.template) {
                        .checked => |template| template,
                        .lifted => Common.invariant("platform lifted target reached Monotype procedure use"),
                        .synthetic => Common.invariant("platform synthetic target reached Monotype procedure use"),
                    },
                    .callable_eval_template => Common.invariant("platform callable-eval template reached Monotype procedure use"),
                };
            },
        };
    }

    fn materializeRootProcedureEvidence(
        self: *Builder,
        fn_template: Ast.FnTemplate,
        evidence_span: checked.CheckedEvidenceSpan,
    ) Allocator.Error![]const SpecEvidence {
        const template_ref = switch (fn_template.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| template,
            .local_hosted,
            .imported_hosted,
            => |hosted| hosted.template,
            .nested,
            .parser_runtime,
            .encoder_for_runtime,
            => Common.invariant("root procedure evidence referenced a non-checked procedure template"),
        };
        return try self.materializeCheckedProcedureEvidence(template_ref, evidence_span);
    }

    fn materializeCheckedProcedureEvidence(
        self: *Builder,
        template_ref: names.ProcTemplate,
        evidence_span: checked.CheckedEvidenceSpan,
    ) Allocator.Error![]const SpecEvidence {
        const view = self.moduleForId(evidence_span.checked_module);
        if (!moduleBytesEqual(view.key.bytes, names.procTemplateModuleDigest(template_ref).bytes)) {
            Common.invariant("root procedure evidence and procedure template belonged to different checked modules");
        }
        const start: usize = evidence_span.span.start;
        const len: usize = evidence_span.span.len;
        if (start > view.static_dispatch_plans.evidence_refs.len or
            len > view.static_dispatch_plans.evidence_refs.len - start)
        {
            Common.invariant("root procedure evidence range was outside its checked module");
        }

        const graph = try self.createGraph();
        defer graph.destroy();
        var draft = BodyDraftStore.init(self.allocator);
        defer draft.deinit();
        var ctx = try BodyContext.init(self.allocator, self, view, template_ref, graph, &draft);
        defer ctx.deinit();
        ctx.evidence = rootEvidence(template_ref, &.{});
        return try ctx.materializeEvidence(view.static_dispatch_plans.evidence_refs[start .. start + len]);
    }

    /// Lower (or defer) a procedure template body and return the Monotype
    /// function id the call site should embed. Inside a specialization the
    /// request reserves an id and defers the body; outside one (root and
    /// wrapper paths, whose types come from the builder-global cache without
    /// body evidence), the body lowers now.
    fn lowerFnTemplateCallTarget(self: *Builder, method_scope: ModuleView, fn_template: Ast.FnTemplate, evidence: []const SpecEvidence) Allocator.Error!Ast.FnSlot {
        const template_ref = switch (fn_template.fn_def) {
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| template,
            .parser_runtime,
            .encoder_for_runtime,
            => Common.invariant("generated serialization runtime function must be restored through ConstStore runtime restore"),
            .local_hosted,
            .imported_hosted,
            => |hosted| hosted.template,
            .nested => Common.invariant("nested function specialization must be lowered through nested function lowering"),
        };
        if (self.active_graph != null) {
            Common.invariant("final function-template lowering was called during an active body draft");
        }
        const def = try self.lowerTemplateWithMono(
            template_ref,
            method_scope,
            fn_template.source_fn_ty,
            fn_template.source_fn_key,
            fn_template.mono_fn_ty,
            evidence,
            .independent_roots,
            .count,
            null,
            null,
            null,
        );
        return .{ .local = self.defFnId(def) };
    }

    fn lowerFnTemplateDef(self: *Builder, method_scope: ModuleView, fn_template: Ast.FnTemplate, evidence: []const SpecEvidence) Allocator.Error!Ast.FnId {
        return localFnIdFromSlot(
            try self.lowerFnTemplateCallTarget(method_scope, fn_template, evidence),
            "Monotype function value lowering requires a local function definition",
        );
    }

    fn lowerRestoredConstFnTemplate(
        self: *Builder,
        fn_template: Ast.FnTemplate,
        fn_value: check.ConstStore.ConstFn,
    ) Allocator.Error!Ast.FnId {
        switch (fn_template.fn_def) {
            .nested => {
                const fn_view = self.moduleForConstFnDef(fn_template.fn_def);
                const graph = try self.createGraph();
                defer graph.destroy();
                const saved_graph = self.active_graph;
                const saved_body_draft = self.active_body_draft;
                self.active_graph = graph;
                defer self.active_graph = saved_graph;
                var body_draft = BodyDraftStore.init(self.allocator);
                self.active_body_draft = &body_draft;
                defer self.active_body_draft = saved_body_draft;
                defer body_draft.deinit();
                var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, templateForConstFnDef(fn_value.fn_def), graph, &body_draft);
                defer fn_ctx.deinit();
                fn_ctx.evidence = try fn_ctx.materializeConstFnEvidence(fn_value);
                try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
                const draft = FinalBodyOutputGuard.begin(self);
                const request_fn_node = try graph.importMono(fn_template.mono_fn_ty);
                const nested = switch (fn_template.fn_def) {
                    .nested => |value| value,
                    .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => unreachable,
                };
                fn_ctx.current_fn_key = nested.context_fn_key;
                const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, nested.context_fn_key);
                defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
                const fn_target = try self.lowerDraftNestedFromContext(
                    &fn_ctx,
                    checkedLambdaExprIdForConstFn(fn_view, fn_template.fn_def),
                    nested,
                    fn_template.source_fn_ty,
                    fn_template.source_fn_key,
                    request_fn_node,
                    &.{},
                    fn_ctx.evidence,
                    null,
                    .exact_graph,
                );
                const draft_fn = switch (fn_target) {
                    .draft => |id| id,
                    .final => Common.invariant("closed restored nested function resolved before draft commit"),
                };
                const draft_end = draft.end(self);
                const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, request_fn_node, &.{}, null, null, draft_fn);
                defer sealed.deinit(self.allocator);
                return sealed.root_fn orelse Common.invariant("closed restored nested function did not resolve its final id");
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => {
                const fn_view = self.moduleForConstFnDef(fn_template.fn_def);
                const graph = try self.createGraph();
                defer graph.destroy();
                var body_draft = BodyDraftStore.init(self.allocator);
                defer body_draft.deinit();
                var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, templateForConstFnDef(fn_value.fn_def), graph, &body_draft);
                defer fn_ctx.deinit();
                const retained = try fn_ctx.materializeConstFnEvidence(fn_value);
                const template_ref = switch (fn_template.fn_def) {
                    .local_template, .imported_template, .checked_generated => |template| template,
                    .local_hosted, .imported_hosted => |hosted| hosted.template,
                    .nested, .parser_runtime, .encoder_for_runtime => Common.invariant("non-nested restored function did not reference a procedure template"),
                };
                const def = try self.lowerTemplateWithMono(
                    template_ref,
                    fn_view,
                    fn_template.source_fn_ty,
                    fn_template.source_fn_key,
                    fn_template.mono_fn_ty,
                    retained.vector,
                    .independent_roots,
                    .count,
                    null,
                    retained,
                    null,
                );
                return self.defFnId(def);
            },
        }
    }

    fn defFnId(self: *Builder, def: Ast.DefId) Ast.FnId {
        return self.program.getDef(def).fn_id orelse
            Common.invariant("Monotype procedure template definition had no function id");
    }

    fn promoteFnSignatureRelation(
        self: *Builder,
        fn_id: Ast.FnId,
        requested: Ast.SignatureRelation,
    ) void {
        if (requested != .exact_graph) return;
        var fn_ = self.program.getFn(fn_id);
        if (fn_.signature_relation == .exact_graph) return;
        fn_.signature_relation = .exact_graph;
        self.program.setFn(fn_id, fn_);
    }

    fn nestedFnForExpr(
        self: *Builder,
        view: ModuleView,
        owner: names.ProcTemplate,
        expr_id: checked.CheckedExprId,
        context_fn_key: names.TypeDigest,
        local_proc_context_digest: ?names.TypeDigest,
    ) Allocator.Error!Ast.NestedFn {
        const address = NestedSiteAddress.from(view.key, owner, expr_id);
        const site = if (self.nested_site_cache.get(address)) |cached|
            cached
        else blk: {
            for (view.nested_proc_sites.sites) |candidate| {
                if (candidate.checked_expr == null or candidate.checked_expr.? != expr_id) continue;
                if (!names.procedureTemplateRefEql(candidate.owner_template, owner)) continue;
                try self.nested_site_cache.put(address, candidate.site);
                break :blk candidate.site;
            }
            Common.invariant("nested function expression reached Monotype without a checked nested function site");
        };
        return .{
            .owner = owner,
            .site = site,
            .context_fn_key = context_fn_key,
            .local_proc_context_digest = local_proc_context_digest,
        };
    }

    fn lowerDraftNestedFromContext(
        self: *Builder,
        source_ctx: *BodyContext,
        expr_id: checked.CheckedExprId,
        nested: Ast.NestedFn,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        raw_request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
        requested_evidence: EvidenceChain,
        owned_scope: ?checked.DispatchScopeId,
        signature_relation: Ast.SignatureRelation,
    ) Allocator.Error!DraftFnTarget {
        self.count("nested_requests");
        const request_fn_node = try source_ctx.graph.functionRequestRoot(raw_request_fn_node);
        const family = DraftNestedFamilyAddress.init(nested, source_ctx.method_scope.key, source_fn_key);
        const stored_evidence = try self.constFnEvidence(requested_evidence);
        const evidence_digest = Ast.fnEvidenceDigest(stored_evidence.nodes, stored_evidence.frames, stored_evidence.head);
        const resolved_request_ty: ?Type.TypeId = if (try source_ctx.graph.typeIsResolved(request_fn_node))
            try source_ctx.activeTypeFromNode(request_fn_node)
        else
            null;
        const resolved_lookup_address: ?DraftNestedLookupAddress = if (resolved_request_ty) |request_fn_ty| .{
            .family = family,
            .evidence_digest = evidence_digest.bytes,
            .request_kind = 0,
            .request_fn_key = self.specializationTypeDigest(request_fn_ty).bytes,
        } else null;
        const open_request_shape: ?solve.OpenFunctionInterfaceShape = if (resolved_request_ty == null)
            try source_ctx.graph.openFunctionInterfaceShape(request_fn_node)
        else
            null;
        const open_shape_lookup_address: ?DraftNestedLookupAddress = if (open_request_shape) |shape| .{
            .family = family,
            .evidence_digest = evidence_digest.bytes,
            .request_kind = 2,
            .request_fn_key = shape.digest.bytes,
        } else null;
        // Nested draft requests use the same graph-native identity discipline
        // as template requests; no resolved node becomes a durable cache key
        // before the graph freezes.
        var seen_specs = std.AutoHashMap(u32, void).init(self.allocator);
        defer seen_specs.deinit();
        var selection = DraftOpenCandidateSelection{};
        if (resolved_lookup_address) |address| {
            if (source_ctx.draft.nested_spec_lookup.get(address)) |candidates| {
                for (candidates.items) |raw_spec| {
                    const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                    if (signature_relation == .exact_graph and
                        source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation != .exact_graph)
                    {
                        continue;
                    }
                    if (!evidenceChainEql(spec.evidence, requested_evidence)) continue;
                    if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                    if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                    const spec_fn_ty = spec.request_fn_ty orelse continue;
                    if (!try self.program.types.typeEql(&self.program.names, spec_fn_ty, resolved_request_ty.?)) continue;
                    if (!selection.add(raw_spec, true)) unreachable;
                }
            }
        }
        if (selection.selected() == null) {
            if (open_shape_lookup_address) |address| {
                if (source_ctx.draft.nested_spec_lookup.get(address)) |candidates| {
                    for (candidates.items) |raw_spec| {
                        const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                        if (spec.state != .lowered) continue;
                        if (spec.request_fn_ty != null) continue;
                        if (!evidenceChainEql(spec.evidence, requested_evidence)) continue;
                        if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                        if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                        if (signature_relation == .exact_graph and
                            source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation != .exact_graph)
                        {
                            continue;
                        }
                        const spec_shape = spec.open_request_shape orelse continue;
                        if (!std.mem.eql(u8, spec_shape, open_request_shape.?.bytes)) continue;
                        if (!selection.add(raw_spec, true)) unreachable;
                    }
                }
            }
        }
        var interface = try source_ctx.graph.functionInterfaceIterator(request_fn_node);
        if (selection.selected() == null) {
            while (interface.next()) |interface_node| {
                var aliases = source_ctx.graph.classMemberIterator(interface_node);
                while (aliases.next()) |member| {
                    const lookup_address = DraftNestedLookupAddress{
                        .family = family,
                        .evidence_digest = evidence_digest.bytes,
                        .request_kind = 1,
                        .request_fn_key = draftOpenRequestKey(member),
                    };
                    if (source_ctx.draft.nested_spec_lookup.get(lookup_address)) |candidates| {
                        for (candidates.items) |raw_spec| {
                            const seen = try seen_specs.getOrPut(raw_spec);
                            if (seen.found_existing) continue;
                            const spec = &source_ctx.draft.nested_specs.items[raw_spec];
                            if (spec.request_fn_ty != null) continue;
                            if (!evidenceChainEql(spec.evidence, requested_evidence)) continue;
                            if (!draftCaptureEntryGuardsMatch(source_ctx.graph, spec.capture_entry_guards, capture_entry_guards)) continue;
                            if (!std.meta.eql(spec.lexical_owner, source_ctx.draft.current_owner)) continue;
                            if (signature_relation == .exact_graph and
                                source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation != .exact_graph)
                            {
                                continue;
                            }
                            const spec_fn_node = try draftNestedSpecRequestNode(source_ctx.draft, source_ctx.graph, spec);
                            const exact_interface = source_ctx.graph.sameFunctionInterface(spec_fn_node, request_fn_node);
                            const active_recursive_edge = source_ctx.draft.ownerDescendsFromDraftFn(
                                source_ctx.draft.current_owner,
                                spec.fn_id,
                            );
                            if (!draftOpenCandidateQualifies(
                                spec.state,
                                exact_interface,
                                active_recursive_edge,
                                true,
                            )) continue;
                            if (!selection.add(raw_spec, exact_interface)) {
                                Common.invariant("draft nested request matched more than one partial active recursive specialization");
                            }
                        }
                    }
                }
            }
        }
        if (selection.selected() == null) {
            for (source_ctx.draft.nested_specs.items, 0..) |*spec, raw_spec_usize| {
                if (signature_relation == .exact_graph and
                    source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation != .exact_graph)
                {
                    continue;
                }
                if (!try draftNestedActiveRecursiveCandidate(
                    source_ctx.graph,
                    spec,
                    family,
                    capture_entry_guards,
                    requested_evidence,
                    source_ctx.draft.current_owner,
                )) continue;
                const raw_spec: u32 = @intCast(raw_spec_usize);
                if (!selection.add(raw_spec, false)) {
                    Common.invariant("draft nested request matched more than one active recursive specialization");
                }
            }
        }
        if (selection.selected() == null) {
            var capture_anchor: ?u32 = null;
            for (source_ctx.draft.nested_specs.items, 0..) |*spec, raw_spec_usize| {
                if (signature_relation == .exact_graph and
                    source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation != .exact_graph)
                {
                    continue;
                }
                if (!try draftNestedCaptureAnchoredRecursiveCandidate(
                    source_ctx.graph,
                    spec,
                    family,
                    request_fn_node,
                    capture_entry_guards,
                    requested_evidence,
                )) continue;
                const raw_spec: u32 = @intCast(raw_spec_usize);
                if (capture_anchor) |anchor_raw| {
                    const anchor = &source_ctx.draft.nested_specs.items[anchor_raw];
                    const candidate_request = try source_ctx.graph.functionNodes(spec.request_fn_node);
                    try source_ctx.graph.markRecursiveValueSlot(candidate_request.ret);
                    try source_ctx.graph.unify(anchor.request_fn_node, spec.request_fn_node);
                } else {
                    capture_anchor = raw_spec;
                }
            }
            if (capture_anchor) |raw_spec| {
                if (!selection.add(raw_spec, false)) unreachable;
            }
        }
        if (selection.selected()) |raw_spec| {
            self.count("nested_hits");
            // As for template requests, a partially overlapping in-progress
            // nested request is an explicit recursive edge. Relate its fresh
            // checked cells before reusing the in-progress definition.
            const spec = &source_ctx.draft.nested_specs.items[raw_spec];
            const active_recursive_edge = spec.state == .lowering and
                (source_ctx.draft.ownerDescendsFromDraftFn(source_ctx.draft.current_owner, spec.fn_id) or
                    try draftNestedActiveRecursiveCandidate(
                        source_ctx.graph,
                        spec,
                        family,
                        capture_entry_guards,
                        requested_evidence,
                        source_ctx.draft.current_owner,
                    ));
            if (try draftNestedCaptureAnchoredRecursiveCandidate(
                source_ctx.graph,
                spec,
                family,
                request_fn_node,
                capture_entry_guards,
                requested_evidence,
            )) {
                const request = try source_ctx.graph.functionNodes(request_fn_node);
                try source_ctx.graph.markRecursiveValueSlot(request.ret);
            }
            if (active_recursive_edge) {
                try source_ctx.graph.unifyRecursiveFunctionInterface(
                    spec.request_fn_node,
                    spec.initial_request_arg_classes,
                    request_fn_node,
                );
                if (!source_ctx.graph.sameFunctionInterface(spec.request_fn_node, request_fn_node)) {
                    Common.invariant("recursive draft nested request did not join its complete function interface");
                }
            } else {
                const spec_fn_node = try draftNestedSpecRequestNode(source_ctx.draft, source_ctx.graph, spec);
                try source_ctx.graph.unify(spec_fn_node, request_fn_node);
                if (!source_ctx.graph.sameFunctionInterface(spec_fn_node, request_fn_node)) {
                    Common.invariant("draft nested request did not join its complete function interface");
                }
            }
            if (signature_relation == .exact_graph) {
                source_ctx.draft.fns.items[@intFromEnum(spec.fn_id)].signature_relation = .exact_graph;
            }
            for (spec.capture_entry_guards, capture_entry_guards) |stored, requested| {
                if (!source_ctx.graph.sameClass(stored, requested)) {
                    Common.invariant("recursive draft nested request changed its ordered capture entry cells");
                }
            }
            if (!runtimeDemandGuardFrameSetsEql(
                spec.runtime_demand_guard_frames,
                try source_ctx.runtimeDemandGuardFrameAddresses(),
            )) {
                try source_ctx.draft.nested_spec_reuses.append(self.allocator, .{
                    .spec = raw_spec,
                    .prefix_proof = try source_ctx.currentRuntimeImpossibilityProof(null),
                });
            }
            return .{ .draft = spec.fn_id };
        }
        self.count("nested_misses");

        const fn_id = try source_ctx.draft.addFn(.{ .source = .{
            .fn_def = .{ .nested = nested },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
            .evidence_digest = evidence_digest,
            .const_evidence = try self.program.addConstFnEvidence(stored_evidence.nodes),
            .const_evidence_frames = try self.program.addConstFnEvidenceFrames(stored_evidence.frames),
            .const_evidence_frame_head = stored_evidence.head,
        }, .signature_relation = signature_relation });
        const symbol = self.symbols.fresh();
        const spec_index = source_ctx.draft.nested_specs.items.len;
        try source_ctx.draft.nested_specs.append(self.allocator, .{
            .state = .lowering,
            .nested = nested,
            .method_scope = source_ctx.method_scope.key,
            .expr_id = expr_id,
            .source_fn_ty = source_fn_ty,
            .source_fn_key = source_fn_key,
            .request_fn_node = request_fn_node,
            .initial_request_arg_classes = try source_ctx.graph.snapshotFunctionArgumentClasses(request_fn_node),
            .request_fn_ty = null,
            .evidence = requested_evidence,
            .runtime_demand_guard_frames = try source_ctx.runtimeDemandGuardFrameAddresses(),
            .demand_start = @intCast(source_ctx.draft.runtime_value_demands.items.len),
            .demand_frame_floor = source_ctx.runtime_demand_guard_frames,
            .capture_entry_guards = try source_ctx.graph.arena().dupe(NodeId, capture_entry_guards),
            .lexical_owner = source_ctx.draft.current_owner,
            .requires_local = evidenceChainRequiresLocalContext(requested_evidence),
            .local_context_dependent = evidenceChainRequiresLocalContext(requested_evidence),
            .symbol = symbol,
            .fn_id = fn_id,
            .open_request_shape = if (open_request_shape) |shape| shape.bytes else null,
        });
        var indexed_nodes = collections.DenseMap(NodeId, void).init(self.allocator);
        defer indexed_nodes.deinit();
        var spec_interface = try source_ctx.graph.functionInterfaceIterator(request_fn_node);
        while (spec_interface.next()) |interface_node| {
            const indexed = try indexed_nodes.getOrPut(interface_node);
            if (indexed.found_existing) continue;
            const lookup_address = DraftNestedLookupAddress{
                .family = family,
                .evidence_digest = evidence_digest.bytes,
                .request_kind = 1,
                .request_fn_key = draftOpenRequestKey(interface_node),
            };
            const lookup_entry = try source_ctx.draft.nested_spec_lookup.getOrPut(lookup_address);
            if (!lookup_entry.found_existing) lookup_entry.value_ptr.* = .empty;
            try lookup_entry.value_ptr.append(self.allocator, @intCast(spec_index));
        }
        if (open_shape_lookup_address) |address| {
            try registerNestedSpecLookup(source_ctx.draft, self.allocator, address, @intCast(spec_index));
        }

        const owner_scope = try source_ctx.draft.enterOwner(.{ .draft_fn = fn_id });
        defer owner_scope.leave();

        var nested_ctx = try source_ctx.nestedInstantiationContext(source_fn_key);
        nested_ctx.evidence = requested_evidence;
        defer nested_ctx.deinit();
        const root_node = try nested_ctx.instNode(source_fn_ty);
        if (owned_scope) |scope| {
            try nested_ctx.graph.unify(root_node, try nested_ctx.lowerExprTypeNode(expr_id));
            try nested_ctx.instantiateTemplateDispatchRelations(
                nested_ctx.view.templates.get(nested_ctx.owner_template.template),
                scope,
            );
        }
        const request_contains_generated_private = try nested_ctx.graph.containsGeneratedPrivate(request_fn_node);
        if (request_contains_generated_private) {
            if (nested_ctx.graph.requestSourceInterface(request_fn_node)) |source_fn_node| {
                try relateFunctionRequestInterface(nested_ctx.graph, root_node, source_fn_node);
            }
        }
        try relateFunctionRequestInterface(nested_ctx.graph, root_node, request_fn_node);
        const body_fn_node = request_fn_node;
        const lowered = try nested_ctx.lowerNestedFunctionAtNode(expr_id, body_fn_node, capture_entry_guards);
        const completed_fn_node = try nested_ctx.completedFunctionNodeForLoweredRet(
            body_fn_node,
            lowered.ret,
            nested_ctx.exprCarriesFunctionDefinitionEvidence(lowered.body),
        );
        const completed_fn_ret = (try nested_ctx.graph.functionNodes(completed_fn_node)).ret;
        const completed_ret_cell = DraftTypeCell.fromGraphNode(completed_fn_ret);
        var nested_fn_template = source_ctx.draft.fns.items[@intFromEnum(fn_id)].source;
        nested_fn_template.mono_fn_ty = DraftTypeCell.fromGraphNode(completed_fn_node);
        _ = try source_ctx.draft.addNestedDef(.{
            .symbol = symbol,
            .fn_def = nested_fn_template,
            .fn_id = .{ .draft = fn_id },
            .args = lowered.args,
            .body = lowered.body,
            .ret = completed_ret_cell,
        });
        source_ctx.draft.fns.items[@intFromEnum(fn_id)].source = nested_fn_template;
        source_ctx.draft.nested_specs.items[spec_index].request_fn_node = completed_fn_node;
        if (try source_ctx.graph.typeIsResolved(completed_fn_node)) {
            const completed_fn_ty = try source_ctx.activeTypeFromNode(completed_fn_node);
            source_ctx.draft.nested_specs.items[spec_index].request_fn_ty = completed_fn_ty;
            try registerNestedSpecLookup(source_ctx.draft, self.allocator, .{
                .family = family,
                .evidence_digest = evidence_digest.bytes,
                .request_kind = 0,
                .request_fn_key = self.specializationTypeDigest(completed_fn_ty).bytes,
            }, @intCast(spec_index));
        }
        try registerNestedSpecInterfaceLookups(
            source_ctx.draft,
            self.allocator,
            source_ctx.graph,
            family,
            evidence_digest.bytes,
            completed_fn_node,
            @intCast(spec_index),
        );
        source_ctx.draft.nested_specs.items[spec_index].state = .lowered;
        source_ctx.draft.nested_specs.items[spec_index].demand_end =
            @intCast(source_ctx.draft.runtime_value_demands.items.len);
        return .{ .draft = fn_id };
    }

    fn markNestedFnReady(self: *Builder, fn_id: Ast.FnId, fn_ty: Type.TypeId) Allocator.Error!void {
        const spec = self.lowered_nested_by_fn.get(fn_id) orelse
            Common.invariant("lowered nested function disappeared before completion");
        try self.spec_store.markReady(spec, fn_ty, self.specializationTypeDigest(fn_ty));
    }

    const ActiveBodyDraftSeal = struct {
        ids: FinalIdOffsets,
        root_ty: ?Type.TypeId,
        root_tys: []Type.TypeId,
        extra_ty: ?Type.TypeId,
        root_def: ?Ast.DefId,
        root_fn: ?Ast.FnId,
        core_maps: *DraftCoreMaps,

        fn deinit(self: ActiveBodyDraftSeal, allocator: Allocator) void {
            allocator.free(self.root_tys);
            self.core_maps.deinit(allocator);
            allocator.destroy(self.core_maps);
        }
    };

    const DraftCommitMap = struct {
        ids: FinalIdOffsets,
        core_maps: ?*DraftCoreMaps,
        emit_fns: []bool,
        emit_defs: []bool,
        emit_nested_defs: []bool,

        fn deinit(self: DraftCommitMap, allocator: Allocator) void {
            if (self.core_maps) |maps| {
                maps.deinit(allocator);
                allocator.destroy(maps);
            }
            allocator.free(self.ids.fn_slots);
            allocator.free(self.ids.def_ids);
            allocator.free(self.emit_fns);
            allocator.free(self.emit_defs);
            allocator.free(self.emit_nested_defs);
        }
    };

    const DraftCoreMaps = struct {
        values: [draft_core_kind_count][]u32,

        fn deinit(self: *DraftCoreMaps, allocator: Allocator) void {
            for (self.values) |map| allocator.free(map);
        }

        fn retained(self: *const DraftCoreMaps, kind: DraftCoreKind, index: usize) bool {
            return self.values[@intFromEnum(kind)][index] != std.math.maxInt(u32);
        }
    };

    fn draftCoreBases(self: *Builder) DraftCoreLengths {
        var bases: DraftCoreLengths = @splat(0);
        bases[@intFromEnum(DraftCoreKind.source_files)] = @intCast(self.program.sourceFileCount());
        bases[@intFromEnum(DraftCoreKind.string_literals)] = @intCast(self.program.stringLiteralCount());
        bases[@intFromEnum(DraftCoreKind.comptime_sites)] = @intCast(self.program.comptimeSiteCount());
        bases[@intFromEnum(DraftCoreKind.expr_ids)] = @intCast(self.program.exprIdCount());
        bases[@intFromEnum(DraftCoreKind.pat_ids)] = @intCast(self.program.patIdCount());
        bases[@intFromEnum(DraftCoreKind.stmt_ids)] = @intCast(self.program.stmtIdCount());
        bases[@intFromEnum(DraftCoreKind.field_exprs)] = @intCast(self.program.fieldExprCount());
        bases[@intFromEnum(DraftCoreKind.fn_def_captures)] = @intCast(self.program.fnDefCaptureCount());
        bases[@intFromEnum(DraftCoreKind.record_destructs)] = @intCast(self.program.recordDestructCount());
        bases[@intFromEnum(DraftCoreKind.str_pattern_steps)] = @intCast(self.program.strPatternStepCount());
        bases[@intFromEnum(DraftCoreKind.branches)] = @intCast(self.program.branchCount());
        bases[@intFromEnum(DraftCoreKind.if_branches)] = @intCast(self.program.ifBranchCount());
        bases[@intFromEnum(DraftCoreKind.locals)] = @intCast(self.program.localCount());
        bases[@intFromEnum(DraftCoreKind.typed_locals)] = @intCast(self.program.typedLocalCount());
        bases[@intFromEnum(DraftCoreKind.pats)] = @intCast(self.program.patCount());
        bases[@intFromEnum(DraftCoreKind.exprs)] = @intCast(self.program.exprCount());
        bases[@intFromEnum(DraftCoreKind.stmts)] = @intCast(self.program.stmtCount());
        bases[@intFromEnum(DraftCoreKind.roots)] = @intCast(self.program.roots.len());
        bases[@intFromEnum(DraftCoreKind.layout_requests)] = @intCast(self.program.layoutRequestCount());
        bases[@intFromEnum(DraftCoreKind.runtime_schema_requests)] = @intCast(self.program.runtimeSchemaRequestCount());
        return bases;
    }

    fn buildDraftCoreMaps(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        emit_fns: []const bool,
    ) Allocator.Error!*DraftCoreMaps {
        const maps = try self.allocator.create(DraftCoreMaps);
        errdefer self.allocator.destroy(maps);
        const lengths = body_draft.coreLengths();
        var initialized: usize = 0;
        errdefer for (maps.values[0..initialized]) |map| self.allocator.free(map);
        for (0..draft_core_kind_count) |raw_kind| {
            maps.values[raw_kind] = try self.allocator.alloc(u32, lengths[raw_kind]);
            @memset(maps.values[raw_kind], std.math.maxInt(u32));
            initialized += 1;
        }

        var next = self.draftCoreBases();
        for (body_draft.owner_runs.items) |owner_run| {
            const retain = draftOwnerRetained(owner_run.owner, emit_fns);
            for (0..draft_core_kind_count) |raw_kind| {
                const kind: DraftCoreKind = @enumFromInt(raw_kind);
                const retain_kind = retain or kind == .source_files;
                if (!retain_kind) continue;
                var index = owner_run.starts[raw_kind];
                while (index < owner_run.ends[raw_kind]) : (index += 1) {
                    maps.values[raw_kind][index] = next[raw_kind];
                    next[raw_kind] += 1;
                }
            }
        }
        return maps;
    }

    fn draftSpecIdentityEql(self: *Builder, left: Ast.SpecIdentity, right: Ast.SpecIdentity) Allocator.Error!bool {
        if (!std.meta.eql(left.callable, right.callable)) return false;
        if (!std.mem.eql(u8, left.method_scope.bytes[0..], right.method_scope.bytes[0..])) return false;
        if (!std.mem.eql(u8, left.source_fn_ty_digest.bytes[0..], right.source_fn_ty_digest.bytes[0..])) return false;
        if (!std.meta.eql(left.evidence_digest, right.evidence_digest)) return false;
        if (!std.mem.eql(u8, left.request_fn_ty_digest.bytes[0..], right.request_fn_ty_digest.bytes[0..])) return false;
        return try self.program.types.typeEql(&self.program.names, left.request_fn_ty, right.request_fn_ty);
    }

    /// Phase A for deferred expressions. Const bodies and equality-owned
    /// methods may produce graph relations or append more deferred work, so
    /// keep walking both dynamic queues until every equality plan is complete
    /// and another pass discovers no new owned call demand.
    fn prepareDraftDeferredExprs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
    ) Allocator.Error!void {
        var const_index: usize = 0;
        while (true) {
            while (const_index < body_draft.deferred_const_uses.items.len) {
                const boundary_index = const_index;
                const_index += 1;
                try self.finalizeDraftConstUse(body_draft, graph, boundary_index);
            }

            var added_method_call = false;
            var equality_index: usize = 0;
            while (equality_index < body_draft.deferred_structural_eqs.items.len) : (equality_index += 1) {
                if (try self.prepareDraftStructuralEq(body_draft, graph, equality_index)) {
                    added_method_call = true;
                }
            }

            var added_inspect_method = false;
            var inspect_index: usize = 0;
            while (inspect_index < body_draft.deferred_inspects.items.len) : (inspect_index += 1) {
                const boundary = body_draft.deferred_inspects.items[inspect_index];
                if (try self.prepareDraftInspectMethods(body_draft, graph, boundary)) {
                    added_inspect_method = true;
                }
            }

            var added_codec_call = false;
            var codec_index: usize = 0;
            while (codec_index < body_draft.deferred_structural_serializations.items.len) : (codec_index += 1) {
                if (try self.prepareDraftStructuralSerialization(
                    body_draft,
                    graph,
                    body_draft.deferred_structural_serializations.items[codec_index],
                )) added_codec_call = true;
            }

            var added_intrinsic_call = false;
            var intrinsic_index: usize = 0;
            while (intrinsic_index < body_draft.deferred_callsite_intrinsics.items.len) : (intrinsic_index += 1) {
                if (try self.prepareDraftCallsiteIntrinsic(
                    body_draft,
                    graph,
                    body_draft.deferred_callsite_intrinsics.items[intrinsic_index],
                )) added_intrinsic_call = true;
            }

            if (const_index < body_draft.deferred_const_uses.items.len) continue;
            if (!added_method_call and !added_inspect_method and !added_codec_call and !added_intrinsic_call) break;
        }
        try self.resolveDraftConstUseReservations(body_draft);

        for (body_draft.deferred_const_uses.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred const reservation was not filled before body sealing");
            }
        }
        for (body_draft.deferred_structural_eqs.items) |boundary| {
            if (!boundary.emission_plan_ready) {
                Common.invariant("deferred structural equality had no prepared emission plan");
            }
        }
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data != .pending_deferred) {
                Common.invariant("deferred structural serialization reservation was filled before final graph sealing");
            }
        }
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data != .pending_deferred) {
                Common.invariant("deferred call-site intrinsic reservation was filled before final graph sealing");
            }
        }
    }

    fn finalizeDraftConstUse(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary_index: usize,
    ) Allocator.Error!void {
        const boundary = body_draft.deferred_const_uses.items[boundary_index];
        if (boundary.restored_source != null) {
            Common.invariant("deferred const reservation was expanded more than once");
        }
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.program.current_loc;
        defer self.program.current_loc = saved_loc;
        const saved_region = self.program.current_region;
        defer self.program.current_region = saved_region;
        self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
        self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        try ctx.inheritActiveConstBindingId(boundary.active_const_binding);
        ctx.evidence = boundary.context_evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        const restored = switch (boundary.provenance) {
            .declared => try ctx.restoreConstUseAtNode(
                boundary.const_use,
                boundary.request_node,
                boundary.use_evidence,
            ),
            .hoisted => |entry| blk: {
                const previous_restore_evidence = ctx.restore_evidence;
                defer ctx.restore_evidence = previous_restore_evidence;
                ctx.restore_evidence = rootEvidence(ctx.owner_template, boundary.use_evidence);
                break :blk try ctx.restoredHoistedConstAtNode(entry, boundary.witness_node);
            },
        };
        const restored_expr = body_draft.exprs.items[@intFromEnum(restored)];
        const restored_node = try restored_expr.ty.toGraphNode(graph);
        try relateRequestComponent(graph, boundary.witness_node, restored_node);
        try relateRequestComponent(graph, boundary.request_node, boundary.witness_node);
        const restored_proof = body_draft.expr_impossibility_proofs.items[@intFromEnum(restored)];
        body_draft.impossibility_proofs.items[@intFromEnum(boundary.proof_reservation)] =
            if (restored_proof) |proof| .{ .forward = proof } else .never;
        body_draft.deferred_const_uses.items[boundary_index].restored_source = restored;
    }

    const DraftReservationState = enum { unseen, visiting, resolved };

    /// Const restoration can explicitly produce another deferred const use or
    /// a stable active-binding reservation. Record those exact dependencies,
    /// then resolve every one-edge chain in linear time. A recursive backedge
    /// is not a dependency edge here: materializing the active binding replaces
    /// its reservation with an explicit recursive let before this pass.
    /// Expression source metadata travels with the restored payload so hoisted
    /// diagnostics keep the original checked expression provenance rather than
    /// the const use site's location. The proof reservation is stable from the
    /// original producer and was filled during expansion.
    fn resolveDraftConstUseReservations(
        self: *Builder,
        body_draft: *BodyDraftStore,
    ) Allocator.Error!void {
        const expr_count = body_draft.exprs.items.len;
        const sources = try self.allocator.alloc(?DraftExprId, expr_count);
        defer self.allocator.free(sources);
        @memset(sources, null);

        const states = try self.allocator.alloc(DraftReservationState, expr_count);
        defer self.allocator.free(states);
        @memset(states, .unseen);

        const stack = try self.allocator.alloc(DraftExprId, expr_count);
        defer self.allocator.free(stack);

        for (body_draft.deferred_const_uses.items) |boundary| {
            const restored = boundary.restored_source orelse
                Common.invariant("deferred const reservation had no explicit restored source");
            const reservation_index = @intFromEnum(boundary.expr);
            if (body_draft.exprs.items[reservation_index].data != .pending_deferred) {
                Common.invariant("deferred const reservation was filled more than once");
            }
            if (body_draft.expr_impossibility_proofs.items[reservation_index] != boundary.proof_reservation) {
                Common.invariant("deferred const reservation lost its stable impossibility proof");
            }
            if (sources[reservation_index] != null) {
                Common.invariant("deferred const reservation had more than one dependency");
            }
            sources[reservation_index] = restored;
        }

        for (body_draft.active_const_bindings.items) |active| {
            const reservation_index = @intFromEnum(active.reservation);
            if (body_draft.exprs.items[reservation_index].data != .pending_deferred) continue;
            const restored = active.restored_source orelse
                Common.invariant("active const reservation had no explicit restored source");
            if (sources[reservation_index] != null) {
                Common.invariant("active const reservation had more than one dependency");
            }
            sources[reservation_index] = restored;
        }

        for (body_draft.deferred_const_uses.items) |boundary| {
            try resolveDraftReservationChain(body_draft, sources, states, stack, boundary.expr);
        }
        for (body_draft.active_const_bindings.items) |active| {
            try resolveDraftReservationChain(body_draft, sources, states, stack, active.reservation);
        }
    }

    fn resolveDraftReservationChain(
        body_draft: *BodyDraftStore,
        sources: []const ?DraftExprId,
        states: []DraftReservationState,
        stack: []DraftExprId,
        start: DraftExprId,
    ) Allocator.Error!void {
        var depth: usize = 0;
        var cursor = start;
        while (body_draft.exprs.items[@intFromEnum(cursor)].data == .pending_deferred) {
            const cursor_index = @intFromEnum(cursor);
            switch (states[cursor_index]) {
                .unseen => {
                    states[cursor_index] = .visiting;
                    stack[depth] = cursor;
                    depth += 1;
                    cursor = sources[cursor_index] orelse
                        Common.invariant("pending const reservation had no explicit dependency");
                },
                .visiting => Common.invariant("deferred const reservation dependencies formed a cycle"),
                .resolved => Common.invariant("resolved const reservation remained pending"),
            }
        }

        while (depth > 0) {
            depth -= 1;
            const reservation = stack[depth];
            const reservation_index = @intFromEnum(reservation);
            const restored = sources[reservation_index] orelse
                Common.invariant("pending const reservation lost its explicit dependency");
            const restored_index = @intFromEnum(restored);
            const restored_expr = body_draft.exprs.items[restored_index];
            if (restored_expr.data == .pending_deferred) {
                Common.invariant("deferred const dependency was not resolved before its consumer");
            }
            body_draft.exprs.items[reservation_index] = restored_expr;
            body_draft.expr_locs.items[reservation_index] = body_draft.expr_locs.items[restored_index];
            body_draft.expr_regions.items[reservation_index] = body_draft.expr_regions.items[restored_index];
            states[reservation_index] = .resolved;
        }
    }

    fn prepareDraftStructuralEq(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary_index: usize,
    ) Allocator.Error!bool {
        const boundary = body_draft.deferred_structural_eqs.items[boundary_index];
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.program.current_loc;
        defer self.program.current_loc = saved_loc;
        const saved_region = self.program.current_region;
        defer self.program.current_region = saved_region;
        self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
        self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        var added_method_call = false;
        try ctx.prepareStructuralEqNode(
            boundary_index,
            boundary.mode,
            boundary.operand_node,
            boundary.ret_ty,
            &seen,
            &added_method_call,
        );
        body_draft.deferred_structural_eqs.items[boundary_index].emission_plan_ready = true;
        return added_method_call;
    }

    fn prepareDraftInspectMethods(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredInspect,
    ) Allocator.Error!bool {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);
        if (try ctx.deferredInspectHasProvenUninhabitedValueGuard(boundary)) return false;

        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        return try ctx.prepareInspectMethodsAtNode(boundary.value_node, boundary.ret_ty, &seen);
    }

    fn prepareDraftStructuralSerialization(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredStructuralSerialization,
    ) Allocator.Error!bool {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        const kind: CodecKind = switch (boundary.plan.result_mode) {
            .parser_for => .parser,
            .encoder_for => .encoder,
            .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-codec result mode reached deferred codec preparation"),
        };
        return try ctx.prepareStructuralCodecCallsAtNode(
            boundary.expr,
            kind,
            boundary.shape_node,
            boundary.callable_node,
        );
    }

    /// Relation production for a deferred call-site intrinsic. Only
    /// `parse_tag_union` generates parser bodies whose format method calls
    /// and error-row tags must exist as graph relations before the freeze;
    /// the FieldNames/Field intrinsics only reshape already-related values.
    /// The intrinsic's callable is `(spec, options) -> Try({value, rest}, e)`;
    /// a synthetic `(encoding) -> (state) -> Try` constructor node over the
    /// options' own component cells lets the structural-parser preparation
    /// helpers run unchanged.
    fn prepareDraftCallsiteIntrinsic(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        boundary: DraftDeferredCallsiteIntrinsic,
    ) Allocator.Error!bool {
        if (boundary.intrinsic != .parse_tag_union) return false;
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        const callable = try graph.functionNodes(boundary.callable_node);
        const constructor_node = try ctx.parseTagUnionSyntheticBoundary(callable, callable.ret);
        const result = try ctx.graphParserResultNodes(callable.ret);

        return try ctx.prepareParseTagUnionPayloadCodecCalls(
            boundary.expr,
            result.value,
            result.err,
            constructor_node,
        );
    }

    /// Phase B for deferred equality. The graph is frozen and `sealer` is the
    /// one final materializer shared with all subsequent body sealing.
    fn emitDraftDeferredStructuralEqs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        for (body_draft.deferred_structural_eqs.items, 0..) |boundary, boundary_index| {
            if (!boundary.emission_plan_ready) {
                Common.invariant("deferred structural equality had no prepared emission plan");
            }
            try self.emitDraftStructuralEq(body_draft, graph, sealer, boundary_index, boundary);
        }
        for (body_draft.deferred_structural_eqs.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred structural equality emission plan did not fill its reservation");
            }
        }
    }

    /// Structural parser and encoder generation depends on the dispatcher's
    /// complete closed shape. Checked row defaults remain live graph evidence
    /// until this phase, so generation consumes the same final snapshot used
    /// by every other draft type instead of forcing an eager callable view.
    fn emitDraftDeferredStructuralSerializations(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        const runtime_demand_count = body_draft.runtime_value_demands.items.len;
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.program.current_loc;
            defer self.program.current_loc = saved_loc;
            const saved_region = self.program.current_region;
            defer self.program.current_region = saved_region;
            self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
            self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

            var ctx = try BodyContext.initWithMethodScope(
                self.allocator,
                self,
                boundary.view,
                boundary.method_scope,
                boundary.owner_template,
                graph,
                body_draft,
            );
            defer ctx.deinit();
            ctx.evidence = boundary.evidence;
            ctx.current_fn_key = boundary.current_fn_key;
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_sealed_emission = true;
            ctx.frozen_type_finals = sealer;

            var frozen_codec_calls = try ctx.sealedPreparedCodecCallsForBoundary(boundary.expr, sealer);
            defer frozen_codec_calls.deinit(self.allocator);
            ctx.frozen_codec_calls = &frozen_codec_calls;

            const callable_ty = try sealer.sealNode(boundary.callable_node);
            const callable = self.functionShape(callable_ty, "deferred structural serialization callable was not a function");
            const shape_ty = try sealer.sealNode(boundary.shape_node);
            const pre_lowered = [_]BodyContext.PreLoweredOperand{.{ .index = 0, .expr = boundary.encoding }};
            const lowered = switch (boundary.plan.result_mode) {
                .parser_for => try ctx.lowerStructuralParser(boundary.plan, callable_ty, callable.ret, &ctx, &pre_lowered, shape_ty),
                .encoder_for => try ctx.lowerStructuralEncoderFor(boundary.plan, callable_ty, callable.ret, &ctx, &pre_lowered, shape_ty),
                .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-serialization dispatch reached deferred structural serialization emission"),
            };
            const lowered_expr = body_draft.exprs.items[@intFromEnum(lowered)];
            const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
            if (!try self.program.types.typeEql(&self.program.names, callable.ret, lowered_ty)) {
                Common.invariant("deferred structural serialization changed its sealed result type");
            }
            body_draft.exprs.items[@intFromEnum(boundary.expr)] = lowered_expr;
            body_draft.expr_impossibility_proofs.items[@intFromEnum(boundary.expr)] =
                body_draft.expr_impossibility_proofs.items[@intFromEnum(lowered)];
        }
        for (body_draft.deferred_structural_serializations.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred structural serialization did not fill its reservation");
            }
        }
        if (body_draft.runtime_value_demands.items.len != runtime_demand_count) {
            Common.invariant("sealed structural serialization emission produced a new checked runtime-value demand");
        }
    }

    /// Deferred parse intrinsics consume the closed snapshot produced by
    /// final graph sealing: their callable request nodes carried live row
    /// defaults during body lowering, and only the sealer may decide the
    /// final rows those intrinsic bodies are generated over.
    fn emitDraftDeferredCallsiteIntrinsics(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.program.current_loc;
            defer self.program.current_loc = saved_loc;
            const saved_region = self.program.current_region;
            defer self.program.current_region = saved_region;
            self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
            self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

            var ctx = try BodyContext.initWithMethodScope(
                self.allocator,
                self,
                boundary.view,
                boundary.method_scope,
                boundary.owner_template,
                graph,
                body_draft,
            );
            defer ctx.deinit();
            ctx.evidence = boundary.evidence;
            ctx.current_fn_key = boundary.current_fn_key;
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_sealed_emission = true;
            ctx.frozen_type_finals = sealer;

            var frozen_codec_calls = try ctx.sealedPreparedCodecCallsForBoundary(boundary.expr, sealer);
            defer frozen_codec_calls.deinit(self.allocator);
            ctx.frozen_codec_calls = &frozen_codec_calls;

            const callable = try graph.functionNodes(boundary.callable_node);
            var checked_arg_storage: [checked.IntrinsicId.max_callsite_arity]checked.CheckedExprId = undefined;
            const checked_args = ctx.checkedCallsiteIntrinsicArgs(
                boundary.intrinsic,
                boundary.operands,
                &checked_arg_storage,
            );
            const lowered = try ctx.lowerCallsiteIntrinsicBodyAtCallable(
                boundary.intrinsic,
                boundary.checked_expr_id,
                boundary.source_fn_ty,
                checked_args,
                callable,
                null,
                if (boundary.pre_lowered_args) |span| ctx.exprSpan(span) else null,
            );
            var lowered_expr = body_draft.exprs.items[@intFromEnum(lowered)];
            const reserved_cell = body_draft.exprs.items[@intFromEnum(boundary.expr)].ty;
            const reserved_ty = try reserved_cell.seal(graph, sealer);
            const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
            if (!try self.program.types.typeEql(&self.program.names, reserved_ty, lowered_ty)) {
                Common.invariant("deferred call-site intrinsic changed its sealed result type");
            }
            lowered_expr.ty = reserved_cell;
            body_draft.exprs.items[@intFromEnum(boundary.expr)] = lowered_expr;
            body_draft.expr_impossibility_proofs.items[@intFromEnum(boundary.expr)] =
                body_draft.expr_impossibility_proofs.items[@intFromEnum(lowered)];
        }
        for (body_draft.deferred_callsite_intrinsics.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred call-site intrinsic did not fill its reservation");
            }
        }
    }

    /// Deferred inspect-only expressions consume the one closed snapshot
    /// produced by final graph sealing. They do not participate in relation
    /// production: the runtime value and result were already lowered, and the
    /// sealed value type only determines the generated renderer body.
    fn emitDraftDeferredInspects(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        var prepared_methods = collections.DenseMap(Type.TypeId, DraftFnSlot).init(self.allocator);
        defer prepared_methods.deinit();
        for (body_draft.prepared_inspect_methods.items) |prepared| {
            const value_ty = try sealer.sealNode(prepared.value_node);
            const entry = try prepared_methods.getOrPut(value_ty);
            if (entry.found_existing) {
                if (!std.meta.eql(entry.value_ptr.*, prepared.callee)) {
                    Common.invariant("one sealed inspect type had multiple prepared method callees");
                }
            } else {
                entry.value_ptr.* = prepared.callee;
            }
        }
        var impossibility_evaluator = try FrozenRuntimeImpossibilityProofEvaluator.init(self.allocator, graph, body_draft);
        defer impossibility_evaluator.deinit(self.allocator);
        for (body_draft.deferred_inspects.items) |boundary| {
            const owner_scope = try body_draft.enterOwner(boundary.owner);
            defer owner_scope.leave();

            const saved_loc = self.program.current_loc;
            defer self.program.current_loc = saved_loc;
            const saved_region = self.program.current_region;
            defer self.program.current_region = saved_region;
            self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
            self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

            var ctx = try BodyContext.initWithMethodScope(
                self.allocator,
                self,
                boundary.view,
                boundary.method_scope,
                boundary.owner_template,
                graph,
                body_draft,
            );
            defer ctx.deinit();
            ctx.evidence = boundary.evidence;
            ctx.current_fn_key = boundary.current_fn_key;
            try ctx.restoreCodecLexicalContext(boundary.lexical);
            ctx.frozen_inspect_method_calls = &prepared_methods;

            const lowered = if (try graph.finalizesAsUninhabited(boundary.value_node) and
                try impossibility_evaluator.holds(boundary.impossibility_proof))
                try ctx.zeroBranchMatchAtTypeCell(boundary.value, .{ .sealed = boundary.ret_ty })
            else blk: {
                const value_ty = try sealer.sealNode(boundary.value_node);
                break :blk try ctx.inspectCall(boundary.value, value_ty, boundary.ret_ty);
            };
            const lowered_expr = body_draft.exprs.items[@intFromEnum(lowered)];
            body_draft.exprs.items[@intFromEnum(boundary.expr)] = lowered_expr;
        }
        for (body_draft.deferred_inspects.items) |boundary| {
            if (body_draft.exprs.items[@intFromEnum(boundary.expr)].data == .pending_deferred) {
                Common.invariant("deferred inspect emission did not fill its reservation");
            }
        }
    }

    fn emitDraftStructuralEq(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        boundary_index: usize,
        boundary: DraftDeferredStructuralEq,
    ) Allocator.Error!void {
        const owner_scope = try body_draft.enterOwner(boundary.owner);
        defer owner_scope.leave();

        const saved_loc = self.program.current_loc;
        defer self.program.current_loc = saved_loc;
        const saved_region = self.program.current_region;
        defer self.program.current_region = saved_region;
        self.program.current_loc = body_draft.expr_locs.items[@intFromEnum(boundary.expr)];
        self.program.current_region = body_draft.expr_regions.items[@intFromEnum(boundary.expr)];

        var ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self,
            boundary.view,
            boundary.method_scope,
            boundary.owner_template,
            graph,
            body_draft,
        );
        defer ctx.deinit();
        ctx.evidence = boundary.evidence;
        ctx.current_fn_key = boundary.current_fn_key;
        try ctx.restoreCodecLexicalContext(boundary.lexical);

        var method_calls = collections.DenseMap(Type.TypeId, DraftFnSlot).init(self.allocator);
        defer method_calls.deinit();
        for (body_draft.structural_eq_method_calls.items) |planned| {
            if (planned.boundary != boundary_index) continue;
            const component_ty = try sealer.sealNode(planned.node);
            const entry = try method_calls.getOrPut(component_ty);
            if (entry.found_existing) {
                if (!std.meta.eql(entry.value_ptr.*, planned.callee)) {
                    Common.invariant("deferred structural equality plan assigned two callees to one component type");
                }
            } else {
                entry.value_ptr.* = planned.callee;
            }
        }
        ctx.frozen_equality_method_calls = &method_calls;

        const operand_ty = try sealer.sealNode(boundary.operand_node);
        const lowered = switch (boundary.mode) {
            .equality => |eq| try ctx.lowerStructuralEqFromOperands(
                operand_ty,
                boundary.lhs,
                boundary.rhs,
                eq.negated,
                boundary.ret_ty,
            ),
            .hash => try ctx.lowerHashExpr(
                operand_ty,
                boundary.lhs,
                boundary.rhs,
                boundary.ret_ty,
            ),
        };
        const lowered_expr = body_draft.exprs.items[@intFromEnum(lowered)];
        const lowered_ty = try lowered_expr.ty.seal(graph, sealer);
        if (!try self.program.types.typeEql(&self.program.names, boundary.ret_ty, lowered_ty)) {
            Common.invariant("deferred structural equality changed its sealed result type");
        }
        body_draft.exprs.items[@intFromEnum(boundary.expr)] = lowered_expr;
    }

    /// Resolve context-free procedure requests only after their caller's graph
    /// has frozen. The sealed callable interface is the complete specialization
    /// key; a missing body is lowered by `lowerTemplateWithMono` in a fresh
    /// graph owned by that specialization. No callee body is ever reconstructed
    /// from, or lowered into, the caller's graph.
    fn resolveDeferredTemplateSpecs(
        self: *Builder,
        body_draft: *BodyDraftStore,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        for (body_draft.template_specs.items) |*spec| {
            if (spec.state != .deferred) continue;

            const fn_ty = try sealer.sealNode(spec.request_fn_node);
            const draft_fn = &body_draft.fns.items[@intFromEnum(spec.fn_id)];
            draft_fn.source.mono_fn_ty = .{ .sealed = fn_ty };

            const requested_evidence = StoredConstFnEvidence{
                .nodes = self.program.constFnEvidence(draft_fn.source.const_evidence),
                .frames = self.program.constFnEvidenceFrames(draft_fn.source.const_evidence_frames),
                .head = draft_fn.source.const_evidence_frame_head,
            };
            const request_digest = self.specializationTypeDigest(fn_ty);
            const identity = templateSpecIdentity(
                spec.template_ref,
                spec.method_scope,
                spec.source_fn_key,
                draft_fn.source.evidence_digest,
                fn_ty,
                request_digest,
            );

            var found_local = false;
            const loaded_slot: ?Ast.FnSlot = if (spec.requires_local)
                null
            else if (try self.spec_store.find(identity, specializationEvidenceView(requested_evidence))) |hit|
                switch (hit) {
                    // `lowerTemplateWithMono` owns the validation and recursive
                    // state handling for local specializations.
                    .local => blk: {
                        found_local = true;
                        break :blk null;
                    },
                    .loaded => |imported| blk: {
                        if (draft_fn.signature_relation == .exact_graph and
                            self.importedFnSignatureRelation(imported) != .exact_graph)
                        {
                            break :blk null;
                        }
                        if (!storedConstFnEvidenceEql(self.importedFnEvidence(imported), requested_evidence)) {
                            Common.invariant("loaded procedure specialization disagreed on dispatch evidence topology");
                        }
                        break :blk Ast.FnSlot{ .imported = imported };
                    },
                }
            else
                null;

            if (found_local or loaded_slot != null) {
                self.countBodyDiagnostic("deferred_template_reuses");
            } else {
                self.countBodyDiagnostic("deferred_template_bodies_lowered");
            }
            spec.resolved_slot = loaded_slot orelse blk: {
                const def = try self.lowerTemplateWithMono(
                    spec.template_ref,
                    self.moduleForId(spec.method_scope),
                    spec.source_fn_ty,
                    spec.source_fn_key,
                    fn_ty,
                    spec.evidence,
                    draft_fn.signature_relation,
                    .already_counted,
                    request_digest,
                    null,
                    null,
                );
                break :blk .{ .local = self.defFnId(def) };
            };
            spec.state = .resolved;
        }
    }

    fn buildDraftCommitMap(
        self: *Builder,
        body_draft: *BodyDraftStore,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        base_ids: FinalIdOffsets,
    ) Allocator.Error!DraftCommitMap {
        var ids = base_ids;
        const fn_slots = try self.allocator.alloc(?Ast.FnSlot, body_draft.fns.items.len);
        errdefer self.allocator.free(fn_slots);
        @memset(fn_slots, null);
        const def_ids = try self.allocator.alloc(?Ast.DefId, body_draft.defs.items.len);
        errdefer self.allocator.free(def_ids);
        const emit_fns = try self.allocator.alloc(bool, body_draft.fns.items.len);
        errdefer self.allocator.free(emit_fns);
        const emit_defs = try self.allocator.alloc(bool, body_draft.defs.items.len);
        errdefer self.allocator.free(emit_defs);
        const emit_nested_defs = try self.allocator.alloc(bool, body_draft.nested_defs.items.len);
        errdefer self.allocator.free(emit_nested_defs);
        const identities = try self.allocator.alloc(?Ast.SpecIdentity, body_draft.fns.items.len);
        defer self.allocator.free(identities);
        @memset(identities, null);
        const allow_imported = try self.allocator.alloc(bool, body_draft.fns.items.len);
        defer self.allocator.free(allow_imported);
        @memset(allow_imported, false);
        const allow_identity_merge = try self.allocator.alloc(bool, body_draft.fns.items.len);
        defer self.allocator.free(allow_identity_merge);
        @memset(allow_identity_merge, true);

        for (body_draft.nested_specs.items) |*spec| {
            spec.capture_abi_digest = try self.sealedCaptureAbiDigest(sealer, spec.capture_entry_guards);
        }

        var next_fn: u32 = @intCast(self.program.fnCount());
        for (body_draft.fns.items, 0..) |fn_, raw_index| {
            const draft_id: DraftFnId = @enumFromInt(@as(u32, @intCast(raw_index)));
            const template_spec: ?*const DraftTemplateSpec = for (body_draft.template_specs.items) |*spec| {
                if (spec.fn_id == draft_id) break spec;
            } else null;
            if (template_spec) |spec| {
                if (spec.state == .resolved) {
                    fn_slots[raw_index] = spec.resolved_slot orelse
                        Common.invariant("resolved draft template demand had no specialization slot");
                    emit_fns[raw_index] = false;
                    continue;
                }
            }

            const sealed_template = try BodyDraftStore.sealFnTemplate(graph, sealer, fn_.source);
            const fn_ty = sealed_template.mono_fn_ty;
            const digest = self.specializationTypeDigest(fn_ty);
            const requested_evidence = StoredConstFnEvidence{
                .nodes = self.program.constFnEvidence(sealed_template.const_evidence),
                .frames = self.program.constFnEvidenceFrames(sealed_template.const_evidence_frames),
                .head = sealed_template.const_evidence_frame_head,
            };
            var identity: ?Ast.SpecIdentity = null;
            var lexical_owner: ?DraftOwner = null;
            if (template_spec) |spec| {
                if (!spec.local_context_dependent) {
                    identity = templateSpecIdentity(spec.template_ref, spec.method_scope, spec.source_fn_key, sealed_template.evidence_digest, fn_ty, digest);
                }
                lexical_owner = spec.lexical_owner;
                allow_imported[raw_index] = !spec.requires_local;
                allow_identity_merge[raw_index] = !spec.requires_local;
            }
            if (identity == null) {
                for (body_draft.nested_specs.items) |spec| {
                    if (spec.fn_id == draft_id) {
                        if (!spec.local_context_dependent) {
                            identity = nestedSpecIdentity(
                                spec.nested,
                                spec.method_scope,
                                spec.source_fn_key,
                                sealed_template.evidence_digest,
                                spec.capture_abi_digest orelse Common.invariant("nested specialization identity omitted its sealed capture ABI"),
                                fn_ty,
                                digest,
                            );
                        }
                        lexical_owner = spec.lexical_owner;
                        allow_identity_merge[raw_index] = !spec.requires_local;
                        break;
                    }
                }
            }
            identities[raw_index] = identity;

            if (lexical_owner) |owner| switch (owner) {
                .root, .reserved_fn => {},
                .draft_fn => |parent| {
                    const parent_raw = @intFromEnum(parent);
                    if (parent_raw >= raw_index) {
                        Common.invariant("nested draft function did not follow its explicit lexical owner");
                    }
                    if (!emit_fns[parent_raw]) {
                        emit_fns[raw_index] = false;
                        if (template_spec != null) {
                            self.countBodyDiagnostic("lowered_template_bodies_discarded");
                        } else {
                            self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                        }
                        continue;
                    }
                },
            };

            if (identity) |wanted| {
                var prior: usize = 0;
                while (prior < raw_index) : (prior += 1) {
                    if (fn_slots[prior] == null) continue;
                    if (!allow_identity_merge[raw_index] or !allow_identity_merge[prior]) continue;
                    if (identities[prior]) |existing| {
                        if (try self.draftSpecIdentityEql(existing, wanted)) {
                            const prior_template = body_draft.fns.items[prior].source;
                            const prior_evidence = StoredConstFnEvidence{
                                .nodes = self.program.constFnEvidence(prior_template.const_evidence),
                                .frames = self.program.constFnEvidenceFrames(prior_template.const_evidence_frames),
                                .head = prior_template.const_evidence_frame_head,
                            };
                            if (!storedConstFnEvidenceEql(prior_evidence, requested_evidence)) continue;
                            fn_slots[raw_index] = fn_slots[prior];
                            emit_fns[raw_index] = false;
                            if (template_spec != null) {
                                self.countBodyDiagnostic("lowered_template_bodies_discarded");
                            } else {
                                self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                            }
                            break;
                        }
                    }
                } else {
                    const committed: ?specialize.LookupResult = if (!allow_identity_merge[raw_index])
                        null
                    else if (allow_imported[raw_index])
                        try self.spec_store.find(wanted, specializationEvidenceView(requested_evidence))
                    else if (try self.spec_store.findLocal(wanted, specializationEvidenceView(requested_evidence))) |hit|
                        .{ .local = hit }
                    else
                        null;
                    if (committed) |hit| {
                        const committed_evidence = switch (hit) {
                            .local => |local| programViewFnEvidence(self.program.view(), self.program.fnSource(local.fn_id)),
                            .loaded => |imported| self.importedFnEvidence(imported),
                        };
                        if (!storedConstFnEvidenceEql(committed_evidence, requested_evidence)) {
                            Common.invariant("committed specialization cache hit disagreed on dispatch evidence topology");
                        }
                        fn_slots[raw_index] = hit.target();
                        emit_fns[raw_index] = false;
                        if (template_spec != null) {
                            self.countBodyDiagnostic("lowered_template_bodies_discarded");
                        } else {
                            self.countBodyDiagnostic("lowered_nested_bodies_discarded");
                        }
                    } else {
                        fn_slots[raw_index] = .{ .local = @enumFromInt(next_fn) };
                        next_fn += 1;
                        emit_fns[raw_index] = true;
                    }
                }
            } else {
                fn_slots[raw_index] = .{ .local = @enumFromInt(next_fn) };
                next_fn += 1;
                emit_fns[raw_index] = true;
            }
        }

        var next_def: u32 = @intCast(self.program.defCount());
        for (body_draft.defs.items, body_draft.def_owners.items, 0..) |_, owner, raw_index| {
            if (!draftOwnerRetained(owner, emit_fns)) {
                def_ids[raw_index] = null;
                emit_defs[raw_index] = false;
                continue;
            }
            def_ids[raw_index] = @enumFromInt(next_def);
            next_def += 1;
            emit_defs[raw_index] = true;
        }

        for (body_draft.nested_defs.items, 0..) |def, index| {
            emit_nested_defs[index] = switch (def.fn_id) {
                .final => true,
                .draft => |draft_fn| emit_fns[@intFromEnum(draft_fn)],
            };
        }
        const core_maps = try self.buildDraftCoreMaps(body_draft, emit_fns);
        errdefer {
            core_maps.deinit(self.allocator);
            self.allocator.destroy(core_maps);
        }
        ids.fn_slots = fn_slots;
        ids.def_ids = def_ids;
        ids.core_id_mode = .{ .remapped = core_maps };
        return .{
            .ids = ids,
            .core_maps = core_maps,
            .emit_fns = emit_fns,
            .emit_defs = emit_defs,
            .emit_nested_defs = emit_nested_defs,
        };
    }

    fn sealActiveBodyDraft(
        self: *Builder,
        graph: *InstGraph,
        body_draft: *BodyDraftStore,
        final_guard: FinalBodyOutputGuard,
        final_end: FinalBodyOutputGuard.End,
        root_node: ?NodeId,
        root_nodes: []const NodeId,
        extra_ty: ?Type.TypeId,
        root_def: ?DraftDefId,
        root_fn: ?DraftFnId,
    ) Allocator.Error!ActiveBodyDraftSeal {
        var timing_scope = ProcedureTimingScope.begin(self.timing, .body_finalization);
        defer timing_scope.end();

        final_guard.assertNoFinalBodyOutput(final_end);
        if (body_draft.active_callable_eval_bindings.items.len != 0) {
            Common.invariant("unfinished callable eval binding reached Monotype body sealing");
        }
        try self.prepareDraftDeferredExprs(body_draft, graph);
        try graph.finalizeGeneratedIteratorRepresentations();
        try graph.finalizeGeneratedIteratorIdentities();
        try graph.freezeRelations();
        var impossibility_evaluator = try FrozenRuntimeImpossibilityProofEvaluator.init(self.allocator, graph, body_draft);
        defer impossibility_evaluator.deinit(self.allocator);
        for (body_draft.runtime_value_demands.items) |demand| {
            if (graph.finalizesAsClosedEmptyTagUnion(demand.node)) {
                if (try impossibility_evaluator.holds(demand.impossibility_proof)) continue;
                Common.invariant("runtime-value demand finalized as a closed empty tag-union type");
            }
        }
        try verifySpecReuseDemands(body_draft, graph, &impossibility_evaluator);
        var sealer = GraphTypeFinals.init(graph);
        defer sealer.deinit();
        try self.emitDraftDeferredStructuralSerializations(body_draft, graph, &sealer);
        try self.emitDraftDeferredCallsiteIntrinsics(body_draft, graph, &sealer);
        try self.emitDraftDeferredStructuralEqs(body_draft, graph, &sealer);
        try self.emitDraftDeferredInspects(body_draft, graph, &sealer);
        const sealed_root = if (root_node) |node| try sealer.sealNode(node) else null;
        if (sealed_root) |ty| try graph.assertTypeHasNoActiveSnapshots(ty);
        const sealed_roots = try self.allocator.alloc(Type.TypeId, root_nodes.len);
        errdefer self.allocator.free(sealed_roots);
        for (root_nodes, sealed_roots) |node, *ty| {
            ty.* = try sealer.sealNode(node);
            try graph.assertTypeHasNoActiveSnapshots(ty.*);
        }
        try body_draft.finishOwnerRuns();
        try self.resolveDeferredTemplateSpecs(body_draft, &sealer);
        var commit_map = try self.buildDraftCommitMap(
            body_draft,
            graph,
            &sealer,
            BodyDraftStore.finalIdOffsets(self.program),
        );
        defer commit_map.deinit(self.allocator);
        const body_ids = commit_map.ids;
        const output_before = FinalBodyOutputCounts.fromProgram(self.program);
        try body_draft.sealCoreIntoProgramWithMap(
            self.program,
            graph,
            &sealer,
            body_ids,
            commit_map.emit_fns,
            commit_map.emit_defs,
            commit_map.emit_nested_defs,
        );
        self.final_body_output_allowance.addDelta(output_before, FinalBodyOutputCounts.fromProgram(self.program));
        const sealed_extra = if (extra_ty) |ty| blk: {
            const sealed = try sealer.sealType(ty);
            try graph.assertTypeHasNoActiveSnapshots(sealed);
            break :blk sealed;
        } else null;
        try self.markDraftNestedReady(body_draft, body_ids);
        verifyDraftTemplateSpecsResolved(body_draft);
        try self.finalizeDraftNestedSpecs(body_draft, body_ids);
        var returned_ids = body_ids;
        returned_ids.fn_slots = &.{};
        returned_ids.def_ids = &.{};
        const retained_core_maps = commit_map.core_maps orelse
            Common.invariant("body draft commit map lost its core remapping before handoff");
        commit_map.core_maps = null;
        return .{
            .ids = returned_ids,
            .root_ty = sealed_root,
            .root_tys = sealed_roots,
            .extra_ty = sealed_extra,
            .root_def = if (root_def) |draft_def| body_ids.def(draft_def) else null,
            .root_fn = if (root_fn) |draft_fn| switch (body_ids.fnSlot(draft_fn)) {
                .local => |local| local,
                .imported => null,
            } else null,
            .core_maps = retained_core_maps,
        };
    }

    fn markDraftNestedReady(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        ids: FinalIdOffsets,
    ) Allocator.Error!void {
        for (body_draft.nested_defs.items) |def| {
            switch (def.fn_id) {
                .draft => continue,
                .final => {},
            }
            const fn_id = ids.fnTarget(def.fn_id);
            const fn_template = self.program.getFn(fn_id).source;
            switch (fn_template.fn_def) {
                .nested => {},
                .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("nested draft definition did not reference a nested function"),
            }
            try self.markNestedFnReady(fn_id, fn_template.mono_fn_ty);
        }
    }

    fn finalizeDraftNestedSpecs(
        self: *Builder,
        body_draft: *const BodyDraftStore,
        ids: FinalIdOffsets,
    ) Allocator.Error!void {
        for (body_draft.nested_specs.items) |spec| {
            if (spec.state != .lowered) {
                Common.invariant("draft nested specialization reached commit before its body lowered");
            }
            if (spec.local_context_dependent) continue;
            if (!ids.hasFnSlot(spec.fn_id)) continue;
            const fn_id = ids.fn_(spec.fn_id);
            const fn_ty = self.program.fnSource(fn_id).mono_fn_ty;
            const digest = self.specializationTypeDigest(fn_ty);
            const fn_template = self.program.fnSource(fn_id);
            const evidence = programViewFnEvidence(self.program.view(), fn_template);
            const capture_abi_digest = spec.capture_abi_digest orelse
                Common.invariant("nested specialization finalized without its sealed capture ABI");
            if (try self.spec_store.findLocal(
                nestedSpecIdentity(spec.nested, spec.method_scope, spec.source_fn_key, fn_template.evidence_digest, capture_abi_digest, fn_ty, digest),
                specializationEvidenceView(evidence),
            )) |_| continue;
            const spec_id = try self.addNestedSpecRecord(
                spec.nested,
                spec.method_scope,
                spec.source_fn_key,
                evidence,
                capture_abi_digest,
                fn_ty,
                digest,
                fn_id,
            );
            try self.lowered_nested_by_fn.put(fn_id, spec_id);
            try self.markNestedFnReady(fn_id, fn_ty);
        }
    }

    fn verifyDraftTemplateSpecsResolved(body_draft: *const BodyDraftStore) void {
        for (body_draft.template_specs.items) |spec| {
            switch (spec.state) {
                .resolved => {},
                .lowered => if (!spec.local_context_dependent)
                    Common.invariant("context-free procedure body was lowered into its caller's draft"),
                .deferred => Common.invariant("deferred template specialization reached commit before resolution"),
                .lowering => Common.invariant("caller-owned template specialization reached commit before its body lowered"),
            }
        }
    }

    fn moduleForConstFnDef(self: *Builder, fn_def: anytype) ModuleView {
        return switch (fn_def) {
            .nested => |nested| self.moduleForDigest(names.procTemplateModuleDigest(nested.owner)),
            .parser_runtime => |runtime| self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner)),
            .encoder_for_runtime => |runtime| self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner)),
            .local_template,
            .imported_template,
            .checked_generated,
            => |template| self.moduleForDigest(names.procTemplateModuleDigest(template)),
            .local_hosted,
            .imported_hosted,
            => |hosted| self.moduleForDigest(names.procTemplateModuleDigest(hostedTemplate(hosted))),
        };
    }

    fn constFnTemplateToMono(self: *Builder, fn_value: anytype, mono_fn_ty: Type.TypeId) Allocator.Error!Ast.FnTemplate {
        return .{
            .fn_def = try self.constFnDefToMono(fn_value.fn_def),
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = mono_fn_ty,
            .const_evidence = try self.program.addConstFnEvidence(fn_value.evidence),
            .const_evidence_frames = try self.program.addConstFnEvidenceFrames(fn_value.evidence_frames),
            .const_evidence_frame_head = fn_value.evidence_frame_head,
        };
    }

    fn restoredConstFnTemplateToMono(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        mono_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.FnTemplate {
        var template = try self.constFnTemplateToMono(fn_value, mono_fn_ty);
        if (fn_value.captures.len == 0) return template;

        switch (template.fn_def) {
            .nested => |nested| {
                template.fn_def = .{ .nested = .{
                    .owner = nested.owner,
                    .site = nested.site,
                    .context_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key),
                    .local_proc_context_digest = nested.local_proc_context_digest,
                } };
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        }
        return template;
    }

    fn constFnDefToMono(self: *Builder, fn_def: anytype) Allocator.Error!Ast.FnDef {
        return switch (fn_def) {
            .local_template => |template| .{ .local_template = template },
            .imported_template => |template| .{ .imported_template = template },
            .nested => |nested| .{ .nested = .{
                .owner = nested.owner,
                .site = nested.site,
                .context_fn_key = nested.context_fn_key,
                .local_proc_context_digest = nested.local_proc_context_digest,
            } },
            .local_hosted => |template| .{ .local_hosted = self.hostedFn(template) },
            .imported_hosted => |template| .{ .imported_hosted = self.hostedFn(template) },
            .checked_generated => |template| .{ .checked_generated = template },
            .parser_runtime => |runtime| .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .encoder_for_runtime => |runtime| .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
        };
    }

    const RestoredConstSourceCapture = struct {
        binder: checked.PatternBinderId,
        previous: ?DraftLocalId,
        previous_typed: ?DraftLocalId,
        local: DraftLocalId,
        ty: Type.TypeId,
        value: DraftExprId,
    };

    fn bindConstSourceCaptures(
        self: *Builder,
        fn_ctx: *BodyContext,
        store_view: ModuleView,
        fn_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!std.ArrayList(RestoredConstSourceCapture) {
        var capture_count: usize = 0;
        for (fn_value.captures) |capture| {
            if (capture.id.isCanonical()) capture_count += 1;
        }

        var out = std.ArrayList(RestoredConstSourceCapture).empty;
        errdefer self.releaseConstSourceCaptures(fn_ctx, &out);
        try out.ensureTotalCapacity(self.allocator, capture_count);

        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            const binder = capture.id.binder();
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const local = try fn_ctx.addFreshLocalWithBinder(self.symbols.fresh(), lowered_ty, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            out.appendAssumeCapacity(.{
                .binder = binder,
                .previous = previous,
                .previous_typed = previous_typed,
                .local = local,
                .ty = lowered_ty,
                .value = undefined,
            });
        }

        var out_index: usize = 0;
        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            out.items[out_index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, out.items[out_index].ty, const_locator, checkedBinderType(fn_view, capture.id.binder()), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, out.items[out_index].ty);
            out_index += 1;
        }

        return out;
    }

    fn releaseConstSourceCaptures(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: *std.ArrayList(RestoredConstSourceCapture),
    ) void {
        var index = captures.items.len;
        while (index > 0) {
            index -= 1;
            const capture = captures.items[index];
            fn_ctx.restoreTypedBinder(capture.binder, capture.ty, capture.previous_typed);
            if (capture.previous) |previous| {
                fn_ctx.binders.put(capture.binder, previous) catch |err| switch (err) {
                    error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                };
            } else {
                _ = fn_ctx.binders.remove(capture.binder);
            }
        }
        captures.deinit(self.allocator);
    }

    fn wrapConstSourceCaptureLets(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: []const RestoredConstSourceCapture,
        expr: DraftExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const order = try self.captureLetOrder(fn_ctx, captures);
        defer self.allocator.free(order);

        var result = expr;
        var index = order.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[order[index]];
            result = try fn_ctx.wrapLet(capture.local, capture.ty, capture.value, result, ty);
        }
        return result;
    }

    fn wrapConstSourceCaptureLetsAtTypeCell(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: []const RestoredConstSourceCapture,
        expr: DraftExprId,
        ty: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const order = try self.captureLetOrder(fn_ctx, captures);
        defer self.allocator.free(order);

        var result = expr;
        var index = order.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[order[index]];
            result = try fn_ctx.wrapLetAtTypeCell(
                capture.local,
                try fn_ctx.draftTypeCell(capture.ty),
                capture.value,
                result,
                ty,
            );
        }
        return result;
    }

    fn captureLetOrder(self: *Builder, fn_ctx: *BodyContext, captures: anytype) Allocator.Error![]usize {
        const len = captures.len;
        const order = try self.allocator.alloc(usize, len);
        errdefer self.allocator.free(order);
        const visiting = try self.allocator.alloc(bool, len);
        defer self.allocator.free(visiting);
        const visited = try self.allocator.alloc(bool, len);
        defer self.allocator.free(visited);
        @memset(visiting, false);
        @memset(visited, false);

        var order_count: usize = 0;
        for (0..len) |index| {
            try self.appendCaptureLetOrder(fn_ctx, captures, index, visiting, visited, order, &order_count);
        }
        return order;
    }

    fn appendCaptureLetOrder(
        self: *Builder,
        fn_ctx: *BodyContext,
        captures: anytype,
        index: usize,
        visiting: []bool,
        visited: []bool,
        order: []usize,
        order_count: *usize,
    ) Allocator.Error!void {
        if (visited[index]) return;
        if (visiting[index]) {
            Common.invariant("ConstStore capture values formed a recursive value dependency");
        }
        visiting[index] = true;
        for (captures, 0..) |capture, dep_index| {
            if (dep_index == index) continue;
            if (try fn_ctx.exprDependsOnFreeLocal(captures[index].value, capture.local)) {
                try self.appendCaptureLetOrder(fn_ctx, captures, dep_index, visiting, visited, order, order_count);
            }
        }
        visiting[index] = false;
        visited[index] = true;
        order[order_count.*] = index;
        order_count.* += 1;
    }

    fn exprDependsOnFreeLocal(
        self: *Builder,
        expr: Ast.ExprId,
        target: Ast.LocalId,
    ) Allocator.Error!bool {
        var bound = collections.DenseMap(Ast.LocalId, void).init(self.allocator);
        defer bound.deinit();
        var active_fns = collections.DenseMap(Ast.FnId, void).init(self.allocator);
        defer active_fns.deinit();
        return try self.exprDependsOnFreeLocalInner(expr, target, &bound, &active_fns);
    }

    fn exprDependsOnFreeLocalInner(
        self: *Builder,
        expr_id: Ast.ExprId,
        target: Ast.LocalId,
        bound: *collections.DenseMap(Ast.LocalId, void),
        active_fns: *collections.DenseMap(Ast.FnId, void),
    ) Allocator.Error!bool {
        const expr = self.program.getExpr(expr_id);
        switch (expr.data) {
            .local => |local| return self.localDependsOnTarget(local, target, bound),
            .@"unreachable",
            .unit,
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .uninitialized,
            .crash,
            .comptime_exhaustiveness_failed,
            .def_ref,
            => return false,
            .fn_ref => |fn_ref| {
                for (self.program.captureOperandSpan(fn_ref.captures)) |operand| {
                    if (try self.exprDependsOnFreeLocalInner(operand.value, target, bound, active_fns)) return true;
                }
                return false;
            },
            .uninitialized_payload => |payload| return self.localDependsOnTarget(payload.condition, target, bound),
            .list,
            .tuple,
            => |items| {
                for (self.program.exprSpan(items)) |child| {
                    if (try self.exprDependsOnFreeLocalInner(child, target, bound, active_fns)) return true;
                }
                return false;
            },
            .record => |fields| {
                for (self.program.fieldExprSpan(fields)) |field| {
                    if (try self.exprDependsOnFreeLocalInner(field.value, target, bound, active_fns)) return true;
                }
                return false;
            },
            .tag => |tag| {
                for (self.program.exprSpan(tag.payloads)) |payload| {
                    if (try self.exprDependsOnFreeLocalInner(payload, target, bound, active_fns)) return true;
                }
                return false;
            },
            .static_data_candidate => |candidate| return try self.exprDependsOnFreeLocalInner(candidate.runtime_expr, target, bound, active_fns),
            .nominal,
            .dbg,
            .expect,
            => |child| return try self.exprDependsOnFreeLocalInner(child, target, bound, active_fns),
            .return_ => |ret| return try self.exprDependsOnFreeLocalInner(ret.value, target, bound, active_fns),
            .expect_err => |expect_err| return try self.exprDependsOnFreeLocalInner(expect_err.msg, target, bound, active_fns),
            .comptime_branch_taken => |taken| return try self.exprDependsOnFreeLocalInner(taken.body, target, bound, active_fns),
            .let_ => |let_| {
                if (try self.exprDependsOnFreeLocalInner(let_.value, target, bound, active_fns)) return true;
                var added = std.ArrayList(Ast.LocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindPatLocals(let_.bind, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(let_.rest, target, bound, active_fns);
            },
            .lambda => |lambda| {
                var added = std.ArrayList(Ast.LocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindTypedLocalLocals(lambda.args, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(lambda.body, target, bound, active_fns);
            },
            .fn_def => |fn_def| {
                const captures = self.program.fnDefCaptureSpan(fn_def.captures);
                if (captures.len == 0) return try self.fnDependsOnFreeLocal(fn_def.fn_id, target, bound, active_fns);
                for (captures) |capture| {
                    if (try self.exprDependsOnFreeLocalInner(capture.value, target, bound, active_fns)) return true;
                }
                return false;
            },
            .call_value => |call| {
                if (try self.exprDependsOnFreeLocalInner(call.callee, target, bound, active_fns)) return true;
                for (self.program.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound, active_fns)) return true;
                }
                return false;
            },
            .call_proc => |call| {
                switch (call.callee) {
                    .func => |fn_id| if (try self.fnDependsOnFreeLocal(fn_id, target, bound, active_fns)) return true,
                    .lifted => {},
                }
                for (self.program.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound, active_fns)) return true;
                }
                for (self.program.captureOperandSpan(call.captures)) |operand| {
                    if (try self.exprDependsOnFreeLocalInner(operand.value, target, bound, active_fns)) return true;
                }
                return false;
            },
            .low_level => |call| {
                for (self.program.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound, active_fns)) return true;
                }
                return false;
            },
            .field_access => |field| return try self.exprDependsOnFreeLocalInner(field.receiver, target, bound, active_fns),
            .tuple_access => |access| return try self.exprDependsOnFreeLocalInner(access.tuple, target, bound, active_fns),
            .structural_eq => |eq| {
                if (try self.exprDependsOnFreeLocalInner(eq.lhs, target, bound, active_fns)) return true;
                return try self.exprDependsOnFreeLocalInner(eq.rhs, target, bound, active_fns);
            },
            .structural_hash => |hash| {
                if (try self.exprDependsOnFreeLocalInner(hash.value, target, bound, active_fns)) return true;
                return try self.exprDependsOnFreeLocalInner(hash.hasher, target, bound, active_fns);
            },
            .match_ => |match| {
                if (try self.exprDependsOnFreeLocalInner(match.scrutinee, target, bound, active_fns)) return true;
                for (self.program.branchSpan(match.branches)) |branch| {
                    var added = std.ArrayList(Ast.LocalId).empty;
                    defer added.deinit(self.allocator);
                    try self.bindPatLocals(branch.pat, bound, &added);
                    defer removeBoundLocals(bound, added.items);
                    for (self.program.stmtSpan(branch.bindings)) |stmt| {
                        if (try self.stmtDependsOnFreeLocal(stmt, target, bound, active_fns, &added)) return true;
                    }
                    if (branch.guard) |guard| {
                        if (try self.exprDependsOnFreeLocalInner(guard, target, bound, active_fns)) return true;
                    }
                    if (try self.exprDependsOnFreeLocalInner(branch.body, target, bound, active_fns)) return true;
                }
                return false;
            },
            .if_ => |if_| {
                for (self.program.ifBranchSpan(if_.branches)) |branch| {
                    if (try self.exprDependsOnFreeLocalInner(branch.cond, target, bound, active_fns)) return true;
                    if (try self.exprDependsOnFreeLocalInner(branch.body, target, bound, active_fns)) return true;
                }
                return try self.exprDependsOnFreeLocalInner(if_.final_else, target, bound, active_fns);
            },
            .if_initialized_payload => |payload| {
                if (try self.exprDependsOnFreeLocalInner(payload.cond, target, bound, active_fns)) return true;
                if (self.localDependsOnTarget(payload.payload, target, bound)) return true;
                if (try self.exprDependsOnFreeLocalInner(payload.initialized, target, bound, active_fns)) return true;
                return try self.exprDependsOnFreeLocalInner(payload.uninitialized, target, bound, active_fns);
            },
            .try_sequence => |sequence| {
                if (try self.exprDependsOnFreeLocalInner(sequence.try_expr, target, bound, active_fns)) return true;
                try bound.put(sequence.ok_local, {});
                defer _ = bound.remove(sequence.ok_local);
                return try self.exprDependsOnFreeLocalInner(sequence.ok_body, target, bound, active_fns);
            },
            .try_record_sequence => |sequence| {
                if (try self.exprDependsOnFreeLocalInner(sequence.try_expr, target, bound, active_fns)) return true;
                try bound.put(sequence.value_local, {});
                try bound.put(sequence.rest_local, {});
                defer _ = bound.remove(sequence.rest_local);
                defer _ = bound.remove(sequence.value_local);
                return try self.exprDependsOnFreeLocalInner(sequence.ok_body, target, bound, active_fns);
            },
            .block => |block| {
                var added = std.ArrayList(Ast.LocalId).empty;
                defer added.deinit(self.allocator);
                defer removeBoundLocals(bound, added.items);
                for (self.program.stmtSpan(block.statements)) |stmt| {
                    if (try self.stmtDependsOnFreeLocal(stmt, target, bound, active_fns, &added)) return true;
                }
                return try self.exprDependsOnFreeLocalInner(block.final_expr, target, bound, active_fns);
            },
            .loop_ => |loop| {
                for (self.program.exprSpan(loop.initial_values)) |initial| {
                    if (try self.exprDependsOnFreeLocalInner(initial, target, bound, active_fns)) return true;
                }
                var added = std.ArrayList(Ast.LocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindTypedLocalLocals(loop.params, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(loop.body, target, bound, active_fns);
            },
            .break_ => |maybe| if (maybe) |value|
                return try self.exprDependsOnFreeLocalInner(value, target, bound, active_fns)
            else
                return false,
            .continue_ => |continue_| {
                for (self.program.exprSpan(continue_.values)) |value| {
                    if (try self.exprDependsOnFreeLocalInner(value, target, bound, active_fns)) return true;
                }
                return false;
            },
        }
    }

    fn localDependsOnTarget(
        self: *Builder,
        local: Ast.LocalId,
        target: Ast.LocalId,
        bound: *collections.DenseMap(Ast.LocalId, void),
    ) bool {
        if (!self.sameLocalIdentity(local, target)) return false;
        return !self.boundContainsLocalIdentity(bound, local);
    }

    fn boundContainsLocalIdentity(
        self: *Builder,
        bound: *collections.DenseMap(Ast.LocalId, void),
        local: Ast.LocalId,
    ) bool {
        if (bound.contains(local)) return true;
        const local_data = self.program.getLocal(local);
        const binder = local_data.binder orelse return false;
        var iter = bound.keyIterator();
        while (iter.next()) |active| {
            const active_data = self.program.getLocal(active.*);
            if (active_data.binder == null or active_data.binder.? != binder) continue;
            if (self.sameMonotype(active_data.ty, local_data.ty)) return true;
        }
        return false;
    }

    fn sameLocalIdentity(self: *Builder, lhs: Ast.LocalId, rhs: Ast.LocalId) bool {
        if (lhs == rhs) return true;
        const lhs_data = self.program.getLocal(lhs);
        const rhs_data = self.program.getLocal(rhs);
        if (lhs_data.binder == null or rhs_data.binder == null or lhs_data.binder.? != rhs_data.binder.?) {
            return false;
        }
        return self.sameMonotype(lhs_data.ty, rhs_data.ty);
    }

    fn sameMonotype(self: *Builder, lhs: Type.TypeId, rhs: Type.TypeId) bool {
        if (lhs == rhs) return true;
        const lhs_digest = self.program.types.typeDigest(&self.program.names, lhs);
        const rhs_digest = self.program.types.typeDigest(&self.program.names, rhs);
        return std.mem.eql(u8, lhs_digest.bytes[0..], rhs_digest.bytes[0..]);
    }

    fn stmtDependsOnFreeLocal(
        self: *Builder,
        stmt_id: Ast.StmtId,
        target: Ast.LocalId,
        bound: *collections.DenseMap(Ast.LocalId, void),
        active_fns: *collections.DenseMap(Ast.FnId, void),
        added: *std.ArrayList(Ast.LocalId),
    ) Allocator.Error!bool {
        const stmt = self.program.getStmt(stmt_id);
        switch (stmt) {
            .uninitialized => |pat| {
                try self.bindPatLocals(pat, bound, added);
                return false;
            },
            .let_ => |let_| {
                if (let_.recursive) {
                    try self.bindPatLocals(let_.pat, bound, added);
                    return try self.exprDependsOnFreeLocalInner(let_.value, target, bound, active_fns);
                } else {
                    if (try self.exprDependsOnFreeLocalInner(let_.value, target, bound, active_fns)) return true;
                    try self.bindPatLocals(let_.pat, bound, added);
                    return false;
                }
            },
            .expr,
            .expect,
            .dbg,
            => |expr| return try self.exprDependsOnFreeLocalInner(expr, target, bound, active_fns),
            .return_ => |ret| return try self.exprDependsOnFreeLocalInner(ret.value, target, bound, active_fns),
            .crash => return false,
        }
    }

    fn fnDependsOnFreeLocal(
        self: *Builder,
        fn_id: Ast.FnId,
        target: Ast.LocalId,
        caller_bound: *collections.DenseMap(Ast.LocalId, void),
        active_fns: *collections.DenseMap(Ast.FnId, void),
    ) Allocator.Error!bool {
        if (active_fns.contains(fn_id)) return false;
        try active_fns.put(fn_id, {});
        defer _ = active_fns.remove(fn_id);

        for (self.program.defsView()) |def| {
            if (def.fn_id == null or def.fn_id.? != fn_id) continue;
            return try self.fnBodyDependsOnFreeLocal(def.args, def.body, target, caller_bound, active_fns);
        }
        for (self.program.nestedDefsView()) |def| {
            if (def.fn_id != fn_id) continue;
            return try self.fnBodyDependsOnFreeLocal(def.args, .{ .roc = def.body }, target, caller_bound, active_fns);
        }
        return false;
    }

    fn fnBodyDependsOnFreeLocal(
        self: *Builder,
        args: Ast.Span(Ast.TypedLocal),
        body: Ast.FnBody,
        target: Ast.LocalId,
        caller_bound: *collections.DenseMap(Ast.LocalId, void),
        active_fns: *collections.DenseMap(Ast.FnId, void),
    ) Allocator.Error!bool {
        var bound = try caller_bound.clone();
        defer bound.deinit();
        var added = std.ArrayList(Ast.LocalId).empty;
        defer added.deinit(self.allocator);
        try self.bindTypedLocalLocals(args, &bound, &added);
        switch (body) {
            .roc => |expr| return try self.exprDependsOnFreeLocalInner(expr, target, &bound, active_fns),
            .hosted => return false,
        }
    }

    fn bindTypedLocalLocals(
        self: *Builder,
        span: Ast.Span(Ast.TypedLocal),
        bound: *collections.DenseMap(Ast.LocalId, void),
        added: *std.ArrayList(Ast.LocalId),
    ) Allocator.Error!void {
        for (self.program.typedLocalSpan(span)) |local| {
            try bound.put(local.local, {});
            try added.append(self.allocator, local.local);
        }
    }

    fn bindPatLocals(
        self: *Builder,
        pat_id: Ast.PatId,
        bound: *collections.DenseMap(Ast.LocalId, void),
        added: *std.ArrayList(Ast.LocalId),
    ) Allocator.Error!void {
        const pat = self.program.getPat(pat_id);
        switch (pat.data) {
            .bind => |local| {
                try bound.put(local, {});
                try added.append(self.allocator, local);
            },
            .wildcard,
            .int_lit,
            .dec_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .str_lit,
            => {},
            .as => |as| {
                try self.bindPatLocals(as.pattern, bound, added);
                try bound.put(as.local, {});
                try added.append(self.allocator, as.local);
            },
            .record => |fields| {
                for (self.program.recordDestructSpan(fields)) |field| {
                    try self.bindPatLocals(field.pattern, bound, added);
                }
            },
            .tuple => |items| {
                for (self.program.patSpan(items)) |child| try self.bindPatLocals(child, bound, added);
            },
            .list => |list| {
                for (self.program.patSpan(list.patterns)) |child| try self.bindPatLocals(child, bound, added);
                if (list.rest) |rest| if (rest.pattern) |rest_pat| try self.bindPatLocals(rest_pat, bound, added);
            },
            .tag => |tag| {
                for (self.program.patSpan(tag.payloads)) |payload| try self.bindPatLocals(payload, bound, added);
            },
            .nominal => |backing| try self.bindPatLocals(backing, bound, added),
            .str_pattern => |str| {
                for (self.program.strPatternStepSpan(str.steps)) |step| {
                    if (step.capture) |capture| try self.bindPatLocals(capture, bound, added);
                }
            },
        }
    }

    fn removeBoundLocals(
        bound: *collections.DenseMap(Ast.LocalId, void),
        locals: []const Ast.LocalId,
    ) void {
        var index = locals.len;
        while (index > 0) {
            index -= 1;
            _ = bound.remove(locals[index]);
        }
    }

    fn restoreConstFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const raw = @intFromEnum(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@enumFromInt(raw));
        if (fn_value.fn_def == .parser_runtime) {
            return try self.restoreConstParserRuntimeFnExpr(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.fn_def == .encoder_for_runtime) {
            return try self.restoreConstEncoderForRuntimeFnExpr(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.captures.len == 0) {
            const template = try self.restoredConstFnTemplateToMono(store_view, fn_id, fn_value, ty);
            const mono_fn_id = try self.lowerRestoredConstFnTemplate(template, fn_value);
            return try self.program.addExpr(.{
                .ty = self.program.fnSource(mono_fn_id).mono_fn_ty,
                .data = .{ .fn_def = .{ .fn_id = mono_fn_id } },
            });
        }

        const fn_view = self.moduleForConstFnDef(fn_value.fn_def);
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, ownerTemplateForConstFnDef(fn_value.fn_def), graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.evidence = try fn_ctx.materializeConstFnEvidence(fn_value);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (fn_value.fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        try fn_ctx.constrainTypeToMono(fn_value.source_fn_ty, ty);
        const draft = FinalBodyOutputGuard.begin(self);

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);
        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        var initialized: usize = 0;
        errdefer {
            while (initialized > 0) {
                initialized -= 1;
                if (captures[initialized].previous) |previous| {
                    fn_ctx.restoreTypedBinder(captures[initialized].binder, captures[initialized].ty, captures[initialized].previous_typed);
                    fn_ctx.binders.put(captures[initialized].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    fn_ctx.restoreTypedBinder(captures[initialized].binder, captures[initialized].ty, captures[initialized].previous_typed);
                    _ = fn_ctx.binders.remove(captures[initialized].binder);
                }
            }
            self.allocator.free(captures);
        }
        defer self.allocator.free(captures);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_cell = try fn_ctx.draftTypeCell(lowered_ty);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, captures[index].ty, const_locator, checkedBinderType(fn_view, constCaptureBinder(capture.id)), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, captures[index].ty);
        }
        const template = try self.constFnTemplateToMono(fn_value, ty);
        const nested = switch (template.fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
        defer {
            var index = initialized;
            while (index > 0) {
                index -= 1;
                fn_ctx.restoreTypedBinder(captures[index].binder, captures[index].ty, captures[index].previous_typed);
                if (captures[index].previous) |previous| {
                    fn_ctx.binders.put(captures[index].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    _ = fn_ctx.binders.remove(captures[index].binder);
                }
            }
        }

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        const request_fn_node = try fn_ctx.activeNodeFromType(ty);
        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node|
            node.* = try fn_ctx.activeNodeFromType(capture.ty);
        if (lambda_expr.data != .lambda) Common.invariant("stored capturing function did not reference a checked lambda");
        const restored_fn = try self.lowerDraftNestedFromContext(
            &fn_ctx,
            lambda_expr_id,
            nested,
            template.source_fn_ty,
            template.source_fn_key,
            request_fn_node,
            capture_entry_guards,
            fn_ctx.evidence,
            null,
            .exact_graph,
        );

        defer self.allocator.free(capture_values);
        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .local = capture.local, .value = capture.value };
        }

        const expr = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(expr);
    }

    fn restoreConstParserRuntimeFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const runtime = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant("non-parser function reached parser runtime restore"),
        };
        const fn_view = self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;

        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, runtime.owner, graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.bindConstSourceCaptures(&fn_ctx, store_view, fn_view, fn_value, static_data_const_locator);
        defer self.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.functionShape(callable_mono_ty, "stored parser constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored parser constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored parser constructor result type differed from restored function type");

        const runtime_fn = self.functionShape(ty, "stored parser runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 1) Common.invariant("stored parser runtime function had an unexpected arity");

        const draft = FinalBodyOutputGuard.begin(self);
        const shape_ty = try fn_ctx.resolvedCheckedTypeView(plan.dispatcher_ty);
        const state_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[0]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[0]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, parserEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, parserEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try fn_ctx.buildParserRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, str_ty);

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(&.{runtime_arg_tys[0]}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerParseResultFromState(
                shape_ty,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[0],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try self.program.addFn(.{
            .fn_def = .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var parser_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = draftFinalFn(runtime_fn_id),
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = runtime_arg_tys[0] },
            }),
            .body = parsed,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, parser_expr, ty);
        }
        if (encoding_let) |let_| {
            parser_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, parser_expr, ty);
        }
        parser_expr = try self.wrapConstSourceCaptureLets(&fn_ctx, source_captures.items, parser_expr, ty);

        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(parser_expr);
    }

    fn restoreConstEncoderForRuntimeFnExpr(
        self: *Builder,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const runtime = switch (fn_value.fn_def) {
            .encoder_for_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant("non-encoder_for function reached encoder_for runtime restore"),
        };
        const fn_view = self.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));
        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;

        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var fn_ctx = try BodyContext.init(self.allocator, self, fn_view, runtime.owner, graph, &body_draft);
        defer fn_ctx.deinit();
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.bindConstSourceCaptures(&fn_ctx, store_view, fn_view, fn_value, static_data_const_locator);
        defer self.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.functionShape(callable_mono_ty, "stored encoder_for constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored encoder_for constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored encoder_for constructor result type differed from restored function type");

        const runtime_fn = self.functionShape(ty, "stored encoder_for runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 2) Common.invariant("stored encoder_for runtime function had an unexpected arity");

        const draft = FinalBodyOutputGuard.begin(self);
        const shape_ty = try fn_ctx.resolvedCheckedTypeView(plan.dispatcher_ty);
        const value_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[0]);
        const value_expr = try fn_ctx.localExpr(value_local, runtime_arg_tys[0]);
        const state_local = try fn_ctx.addLocal(self.symbols.fresh(), runtime_arg_tys[1]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[1]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, encoderForEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, encoderForEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try fn_ctx.buildEncodeRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, arg_tys[0], str_ty);

        const saved_encoder_source_fn_ty = fn_ctx.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = fn_ctx.generated_encoder_source_expr;
        const saved_encoder_lambda_index = fn_ctx.generated_encoder_lambda_index;
        fn_ctx.generated_encoder_source_fn_ty = fn_value.source_fn_ty;
        fn_ctx.generated_encoder_source_expr = runtime.expr;
        fn_ctx.generated_encoder_lambda_index = 0;
        defer {
            fn_ctx.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            fn_ctx.generated_encoder_source_expr = saved_encoder_source_expr;
            fn_ctx.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(runtime_arg_tys, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerEncodeShapeToState(
                shape_ty,
                value_expr,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[1],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try self.program.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var encoder_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = draftFinalFn(runtime_fn_id),
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = runtime_arg_tys[0] },
                .{ .local = state_local, .ty = runtime_arg_tys[1] },
            }),
            .body = encoded,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, encoder_expr, ty);
        }
        if (encoding_let) |let_| {
            encoder_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, encoder_expr, ty);
        }
        encoder_expr = try self.wrapConstSourceCaptureLets(&fn_ctx, source_captures.items, encoder_expr, ty);

        const draft_end = draft.end(self);
        const sealed = try self.sealActiveBodyDraft(graph, &body_draft, draft, draft_end, null, &.{}, null, null, null);
        defer sealed.deinit(self.allocator);
        return sealed.ids.expr(encoder_expr);
    }

    fn restoreConstNode(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!Ast.ExprId {
        return try self.restoreConstNodeAtType(store_view, type_view, node, try self.lowerType(type_view, checked_ty));
    }

    fn restoreConstNodeAtType(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, null);
    }

    fn restoreConstNodeAtTypeWithStaticRoot(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprId {
        const address = ConstExprAddress{
            .store_module_bytes = store_view.key.bytes,
            .type_module_bytes = type_view.key.bytes,
            .node = @intFromEnum(node),
            .mono_ty = @intFromEnum(ty),
        };
        if (static_data_const_locator == null) {
            if (self.const_expr_cache.get(address)) |existing| return existing;
        }

        const value = store_view.const_store.get(node);
        switch (value) {
            .fn_value => |fn_id| {
                const expr = try self.restoreConstFnExpr(store_view, fn_id, ty, static_data_const_locator);
                if (static_data_const_locator == null) try self.const_expr_cache.put(address, expr);
                return expr;
            },
            .tag, .record, .tuple => if (self.nominalConstructionLayer(ty)) |layer| {
                const backing_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, layer.backing, static_data_const_locator);
                const expr = try self.program.addExpr(.{ .ty = layer.named, .data = .{ .nominal = backing_expr } });
                if (static_data_const_locator == null) try self.const_expr_cache.put(address, expr);
                return expr;
            },
            .nominal => |nominal| if (self.nominalConstructionLayer(ty)) |layer| {
                const backing_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, nominal.backing, layer.backing, static_data_const_locator);
                const expr = try self.program.addExpr(.{ .ty = layer.named, .data = .{ .nominal = backing_expr } });
                if (static_data_const_locator == null) try self.const_expr_cache.put(address, expr);
                return expr;
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash => {},
        }
        const data = try self.restoreConstData(store_view, type_view, value, ty, static_data_const_locator);
        const expr = try self.program.addExpr(.{ .ty = ty, .data = data });
        if (static_data_const_locator == null) try self.const_expr_cache.put(address, expr);
        return expr;
    }

    fn restoreConstData(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        value: checked.ConstValue,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprData {
        return switch (value) {
            .pending => Common.invariant("pending ConstStore node reached Monotype restore"),
            .zst => .unit,
            .scalar => |scalar| restoreScalar(scalar),
            .str => |str| .{ .str_lit = try self.program.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .crash => |str| .{ .crash = try self.program.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .list => |list| try self.restoreConstListData(store_view, type_view, ty, list, static_data_const_locator),
            .box => |payload| blk: {
                const child = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, payload, self.constBoxPayloadType(ty), static_data_const_locator);
                break :blk .{ .low_level = .{
                    .op = .box_box,
                    .args = try self.program.addExprSpan(&.{child}),
                } };
            },
            .tuple => |items| .{ .tuple = try self.restoreConstTuple(store_view, type_view, ty, items, static_data_const_locator) },
            .record => |items| .{ .record = try self.restoreConstRecord(store_view, type_view, ty, items, static_data_const_locator) },
            .tag => |tag| .{ .tag = .{
                .name = try self.program.names.internTagLabel(tag.tag_name),
                .payloads = try self.restoreConstTagPayloads(store_view, type_view, ty, tag, static_data_const_locator),
            } },
            .nominal => |nominal| .{ .nominal = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, nominal.backing, self.namedBackingType(ty) orelse ty, static_data_const_locator) },
            .fn_value => Common.invariant("ConstStore function value must be restored as an expression"),
        };
    }

    fn restoreConstList(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.Span(Ast.ExprId) {
        const elem_ty = self.constListElemType(ty);
        const lowered = try self.allocator.alloc(Ast.ExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, elem_ty, static_data_const_locator);
        }
        return try self.program.addExprSpan(lowered);
    }

    fn restoreConstListData(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        list: checked.ConstList,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.ExprData {
        return switch (list) {
            .nodes => |items| .{ .list = try self.restoreConstList(store_view, type_view, ty, items, static_data_const_locator) },
            .scalar_bytes => |scalar_bytes| .{ .bytes_lit = .{
                .literal = try self.program.addStringView(
                    store_view.const_store.blobData(scalar_bytes.bytes.data),
                    scalar_bytes.bytes.offset,
                    scalar_bytes.bytes.len,
                ),
                .len = scalar_bytes.len,
                .element = scalar_bytes.element,
            } },
        };
    }

    fn restoreConstTuple(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.Span(Ast.ExprId) {
        const item_span = self.tupleItemSpan(ty);
        const item_count: usize = @intCast(item_span.len);
        if (item_count != items.len) Common.invariant("ConstStore tuple length differs from checked type");
        const lowered = try self.allocator.alloc(Ast.ExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            const item_tys = self.program.types.span(item_span);
            const item_ty = GuardedList.at(item_tys, index);
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, item_ty, static_data_const_locator);
        }
        return try self.program.addExprSpan(lowered);
    }

    fn restoreConstRecord(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.Span(Ast.FieldExpr) {
        const field_span = self.recordFieldsSpan(ty);
        const field_count: usize = @intCast(field_span.len);
        if (field_count != items.len) Common.invariant("ConstStore record length differs from checked type");
        const lowered = try self.allocator.alloc(Ast.FieldExpr, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            const fields = self.program.types.fieldSpan(field_span);
            const field = GuardedList.at(fields, index);
            lowered[index] = .{
                .name = field.name,
                .value = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, field.ty, static_data_const_locator),
            };
        }
        return try self.program.addFieldExprSpan(lowered);
    }

    fn restoreConstTagPayloads(
        self: *Builder,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        tag: anytype,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!Ast.Span(Ast.ExprId) {
        const mono_tag_name = try self.program.names.internTagLabel(tag.tag_name);
        const payload_span = self.tagPayloadSpan(ty, mono_tag_name);
        const payload_count: usize = @intCast(payload_span.len);
        if (payload_count != tag.payloads.len) Common.invariant("ConstStore tag payload count differs from checked type");
        const lowered = try self.allocator.alloc(Ast.ExprId, tag.payloads.len);
        defer self.allocator.free(lowered);
        for (tag.payloads, 0..) |payload, index| {
            const payload_tys = self.program.types.span(payload_span);
            const payload_ty = GuardedList.at(payload_tys, index);
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, payload, payload_ty, static_data_const_locator);
        }
        return try self.program.addExprSpan(lowered);
    }

    fn constListElemType(self: *Builder, ty: Type.TypeId) Type.TypeId {
        return switch (self.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("ConstStore list restored with a non-list monotype"),
        };
    }

    fn constBoxPayloadType(self: *Builder, ty: Type.TypeId) Type.TypeId {
        return switch (self.shapeContent(ty)) {
            .box => |payload| payload,
            .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => Common.invariant("ConstStore box restored with a non-box monotype"),
        };
    }

    fn constRecordFields(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Field, "fields") {
        return self.program.types.fieldSpan(self.recordFieldsSpan(ty));
    }

    fn inspectCall(self: *Builder, value: Ast.ExprId, value_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        if (try self.typeIsProvenUninhabited(value_ty)) {
            return try self.uninhabitedInspect(value, str_ty);
        }

        const def_id = try self.inspectDefForType(value_ty, str_ty);
        const fn_ty = try self.oneArgFnType(value_ty, str_ty);
        const callee = try self.program.addExpr(.{
            .ty = fn_ty,
            .data = .{ .def_ref = def_id },
        });
        const args = [_]Ast.ExprId{value};
        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .call_value = .{
                .callee = callee,
                .args = try self.program.addExprSpan(&args),
            } },
        });
    }

    fn uninhabitedInspect(self: *Builder, value: Ast.ExprId, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .match_ = .{
                .scrutinee = value,
                .branches = try self.program.addBranchSpan(&.{}),
            } },
        });
    }

    fn inspectDefForType(self: *Builder, value_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!Ast.DefId {
        const address = GeneratedHelperDefAddress{
            .value_ty = @intFromEnum(value_ty),
            .result_ty = @intFromEnum(str_ty),
        };
        if (self.inspect_defs.get(address)) |entry| return entry.id();

        const def_id = try self.program.addDef(undefined);
        try self.inspect_defs.put(address, .{ .reserved = def_id });

        const arg_local = try self.program.addLocal(self.symbols.fresh(), value_ty);
        const arg_expr = try self.localExpr(arg_local, value_ty);
        const body = try self.inspectBody(arg_expr, value_ty, value_ty, str_ty);

        const args = try self.program.addTypedLocalSpan(&.{.{ .local = arg_local, .ty = value_ty }});
        self.program.setDef(def_id, .{
            .symbol = self.symbols.fresh(),
            .fn_def = null,
            .args = args,
            .body = .{ .roc = body },
            .ret = str_ty,
        });
        try self.inspect_defs.put(address, .{ .ready = def_id });
        return def_id;
    }

    fn inspectBody(
        self: *Builder,
        value: Ast.ExprId,
        value_ty: Type.TypeId,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        return switch (self.program.types.get(shape_ty)) {
            .primitive => |primitive| try self.primitiveInspect(value, primitive, str_ty),
            .named => |named| blk: {
                if (named.builtin_owner) |owner| {
                    switch (owner) {
                        .list => break :blk try self.inspectList(value, self.singleTypeArg(named.args, "List"), str_ty),
                        .box => {},
                        _ => {},
                    }
                }
                if (try self.toInspectCall(value, value_ty, str_ty)) |method_call| break :blk method_call;
                const backing = named.backing orelse Common.invariant("Str.inspect reached opaque named type without checked inspect authority");
                if (backing.use != .inspectable) {
                    break :blk try self.stringExpr("<opaque>", str_ty);
                }
                break :blk try self.inspectBody(value, value_ty, backing.ty, str_ty);
            },
            .record => |fields| try self.inspectRecord(value, self.program.types.fieldSpan(fields), str_ty),
            .tuple => |items| try self.inspectTuple(value, self.program.types.span(items), str_ty),
            .tag_union => |tags| try self.inspectTagUnion(value, value_ty, self.program.types.tagSpan(tags), str_ty),
            .list => |elem_ty| try self.inspectList(value, elem_ty, str_ty),
            .func, .erased => try self.stringExpr("<function>", str_ty),
            .zst => try self.stringExpr("{}", str_ty),
            .box => |elem_ty| blk: {
                const unboxed = try self.lowLevelExpr(.box_unbox, &.{value}, elem_ty);
                var out = try self.stringExpr("Box(", str_ty);
                out = try self.concatExpr(out, try self.inspectCall(unboxed, elem_ty, str_ty), str_ty);
                break :blk try self.concatExpr(out, try self.stringExpr(")", str_ty), str_ty);
            },
        };
    }

    fn toInspectCall(self: *Builder, value: Ast.ExprId, value_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!?Ast.ExprId {
        const owner = methodOwnerFromType(&self.program.types, value_ty) orelse return null;
        const lookup = self.lookupMethodTargetByName(owner, "to_inspect") orelse return null;
        const procedure = switch (lookup.target.kind) {
            .procedure => |procedure| procedure,
            .structural, .local_proc => return null,
        };
        const template = procedure.template;

        const graph = try self.createGraph();
        defer graph.destroy();
        const saved_graph = self.active_graph;
        const saved_body_draft = self.active_body_draft;
        self.active_graph = graph;
        defer self.active_graph = saved_graph;
        var body_draft = BodyDraftStore.init(self.allocator);
        self.active_body_draft = &body_draft;
        defer self.active_body_draft = saved_body_draft;
        defer body_draft.deinit();
        var target_ctx = try BodyContext.initWithMethodScope(self.allocator, self, lookup.view, moduleView(self.root_view), template, graph, &body_draft);
        defer target_ctx.deinit();
        const callable_node = try target_ctx.instantiateTargetCallNodeFromMonoArgs(lookup.target.callable_ty, &.{value_ty}, str_ty);
        try graph.freezeRelations();
        const callable_mono_ty = try graph.sealNode(callable_node);
        const callee_def = try self.lowerTemplateWithMono(
            template,
            moduleView(self.root_view),
            lookup.target.callable_ty,
            lookup.view.types.rootKey(lookup.target.callable_ty),
            callable_mono_ty,
            &.{},
            .independent_roots,
            .count,
            null,
            null,
            null,
        );

        const args = [_]Ast.ExprId{value};
        const call = try self.program.addExpr(.{ .ty = str_ty, .data = .{ .call_proc = .{
            .callee = Ast.localProcCallee(self.defFnId(callee_def)),
            .args = try self.program.addExprSpan(&args),
        } } });
        return call;
    }

    fn primitiveInspect(self: *Builder, value: Ast.ExprId, primitive: Type.Primitive, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        const args = [_]Ast.ExprId{value};
        return try self.lowLevelExpr(primitiveInspectLowLevelOp(primitive), &args, str_ty);
    }

    fn inspectTuple(self: *Builder, value: Ast.ExprId, items: anytype, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        if (items.len == 0) return try self.stringExpr("()", str_ty);
        const stable_items = try GuardedList.dupe(self.allocator, Type.TypeId, items);
        defer self.allocator.free(stable_items);

        var out = try self.stringExpr("(", str_ty);
        for (stable_items, 0..) |item_ty, i| {
            if (i != 0) out = try self.concatExpr(out, try self.stringExpr(", ", str_ty), str_ty);
            const item = try self.program.addExpr(.{
                .ty = item_ty,
                .data = .{ .tuple_access = .{ .tuple = value, .elem_index = @intCast(i) } },
            });
            out = try self.concatExpr(out, try self.inspectCall(item, item_ty, str_ty), str_ty);
        }
        return try self.concatExpr(out, try self.stringExpr(")", str_ty), str_ty);
    }

    fn inspectRecord(self: *Builder, value: Ast.ExprId, fields: anytype, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        if (fields.len == 0) return try self.stringExpr("{}", str_ty);
        const stable_fields = try GuardedList.dupe(self.allocator, Type.Field, fields);
        defer self.allocator.free(stable_fields);

        var out = try self.stringExpr("{ ", str_ty);
        for (stable_fields, 0..) |field, i| {
            if (i != 0) out = try self.concatExpr(out, try self.stringExpr(", ", str_ty), str_ty);
            out = try self.concatExpr(out, try self.stringExpr(self.program.names.recordFieldLabelText(field.name), str_ty), str_ty);
            out = try self.concatExpr(out, try self.stringExpr(": ", str_ty), str_ty);
            const field_value = try self.program.addExpr(.{
                .ty = field.ty,
                .data = .{ .field_access = .{
                    .receiver = value,
                    .segments = try self.program.addFieldAccessSegmentSpan(&.{.{ .field = field.name }}),
                } },
            });
            out = try self.concatExpr(out, try self.inspectFieldSlot(field_value, field.ty, str_ty), str_ty);
        }
        return try self.concatExpr(out, try self.stringExpr(" }", str_ty), str_ty);
    }

    /// Render one record field's slot. An inline (required/defaulted) slot
    /// renders as the value itself. An optional field's tagged slot never
    /// leaks its #Missing/#Present encoding: a present slot renders its
    /// payload exactly as a required field's value would, and a missing
    /// slot renders the literal `<missing>` marker.
    fn inspectFieldSlot(self: *Builder, slot_value: Ast.ExprId, slot_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        const slot = self.optionalFieldSlot(slot_ty) orelse
            return try self.inspectCall(slot_value, slot_ty, str_ty);

        const payload_local = try self.program.addLocal(self.symbols.fresh(), slot.payload_ty);
        const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
        const present_pat = try self.program.addPat(.{ .ty = slot_ty, .data = .{ .tag = .{
            .name = slot.present_tag.name,
            .payloads = try self.program.addPatSpan(&.{payload_pat}),
        } } });
        const present_body = try self.inspectCall(
            try self.localExpr(payload_local, slot.payload_ty),
            slot.payload_ty,
            str_ty,
        );

        const missing_pat = try self.program.addPat(.{ .ty = slot_ty, .data = .{ .tag = .{
            .name = slot.missing_tag.name,
            .payloads = try self.program.addPatSpan(&.{}),
        } } });
        const missing_body = try self.stringExpr(optional_field_missing_render, str_ty);

        const branches = [_]Ast.Branch{
            .{ .pat = present_pat, .body = present_body },
            .{ .pat = missing_pat, .body = missing_body },
        };
        return try self.program.addExpr(.{ .ty = str_ty, .data = .{ .match_ = .{
            .scrutinee = slot_value,
            .branches = try self.program.addBranchSpan(&branches),
        } } });
    }

    fn typeIsProvenUninhabited(self: *Builder, ty: Type.TypeId) Allocator.Error!bool {
        if (self.uninhabited_type_cache.get(ty)) |cached| return cached;
        var visiting = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer visiting.deinit();
        const result = try self.typeIsProvenUninhabitedInner(ty, &visiting);
        try self.uninhabited_type_cache.put(ty, result);
        return result;
    }

    fn typeIsProvenUninhabitedInner(
        self: *Builder,
        ty: Type.TypeId,
        visiting: *collections.DenseMap(Type.TypeId, void),
    ) Allocator.Error!bool {
        const entry = try visiting.getOrPut(ty);
        if (entry.found_existing) return false;
        defer _ = visiting.remove(ty);
        return switch (self.program.types.get(ty)) {
            .named => |named| if (named.backing) |backing|
                if (backing.use == .inspectable)
                    self.typeIsProvenUninhabitedInner(backing.ty, visiting)
                else
                    false
            else
                false,
            .box => |payload| self.typeIsProvenUninhabitedInner(payload, visiting),
            .tuple => |items| blk: {
                const borrowed = self.program.types.span(items);
                for (0..GuardedList.borrowLen(borrowed)) |index| {
                    const item = GuardedList.at(borrowed, index);
                    if (try self.typeIsProvenUninhabitedInner(item, visiting)) break :blk true;
                }
                break :blk false;
            },
            .record => |fields| blk: {
                const borrowed = self.program.types.fieldSpan(fields);
                for (0..GuardedList.borrowLen(borrowed)) |index| {
                    const field = GuardedList.at(borrowed, index);
                    if (try self.typeIsProvenUninhabitedInner(field.ty, visiting)) break :blk true;
                }
                break :blk false;
            },
            .tag_union => |tags| blk: {
                const borrowed_tags = self.program.types.tagSpan(tags);
                for (0..GuardedList.borrowLen(borrowed_tags)) |tag_index| {
                    const tag = GuardedList.at(borrowed_tags, tag_index);
                    var tag_is_inhabited = true;
                    const borrowed_payloads = self.program.types.span(tag.payloads);
                    for (0..GuardedList.borrowLen(borrowed_payloads)) |payload_index| {
                        const payload = GuardedList.at(borrowed_payloads, payload_index);
                        if (try self.typeIsProvenUninhabitedInner(payload, visiting)) {
                            tag_is_inhabited = false;
                            break;
                        }
                    }
                    if (tag_is_inhabited) break :blk false;
                }
                break :blk true;
            },
            .primitive, .list, .func, .erased, .zst => false,
        };
    }

    fn inspectTagUnion(self: *Builder, value: Ast.ExprId, value_ty: Type.TypeId, tags: anytype, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        if (tags.len == 0) {
            return try self.uninhabitedInspect(value, str_ty);
        }
        const stable_tags = try GuardedList.dupe(self.allocator, Type.Tag, tags);
        defer self.allocator.free(stable_tags);

        var branches = std.ArrayList(Ast.Branch).empty;
        defer branches.deinit(self.allocator);

        for (stable_tags) |tag| {
            const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.program.types.span(tag.payloads));
            defer self.allocator.free(payload_tys);
            var tag_is_uninhabited = false;
            for (payload_tys) |payload_ty| {
                if (try self.typeIsProvenUninhabited(payload_ty)) {
                    tag_is_uninhabited = true;
                    break;
                }
            }
            if (tag_is_uninhabited) continue;
            const payload_pats = try self.allocator.alloc(Ast.PatId, payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(Ast.ExprId, payload_tys.len);
            defer self.allocator.free(payload_exprs);

            for (payload_tys, 0..) |payload_ty, payload_i| {
                const local = try self.program.addLocal(self.symbols.fresh(), payload_ty);
                payload_pats[payload_i] = try self.program.addPat(.{ .ty = payload_ty, .data = .{ .bind = local } });
                payload_exprs[payload_i] = try self.localExpr(local, payload_ty);
            }

            const pat = try self.program.addPat(.{
                .ty = value_ty,
                .data = .{ .tag = .{
                    .name = tag.name,
                    .payloads = try self.program.addPatSpan(payload_pats),
                } },
            });
            try branches.append(self.allocator, .{
                .pat = pat,
                .body = try self.inspectTagBody(tag.name, payload_exprs, payload_tys, str_ty),
            });
        }
        if (branches.items.len == 0) return try self.uninhabitedInspect(value, str_ty);

        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .match_ = .{
                .scrutinee = value,
                .branches = try self.program.addBranchSpan(branches.items),
            } },
        });
    }

    fn inspectTagBody(
        self: *Builder,
        name: names.TagNameId,
        payload_exprs: []const Ast.ExprId,
        payload_tys: []const Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        var out = try self.stringExpr(self.program.names.tagLabelText(name), str_ty);
        if (payload_exprs.len == 0) return out;
        out = try self.concatExpr(out, try self.stringExpr("(", str_ty), str_ty);
        for (payload_exprs, payload_tys, 0..) |payload_expr, payload_ty, i| {
            if (i != 0) out = try self.concatExpr(out, try self.stringExpr(", ", str_ty), str_ty);
            out = try self.concatExpr(out, try self.inspectCall(payload_expr, payload_ty, str_ty), str_ty);
        }
        return try self.concatExpr(out, try self.stringExpr(")", str_ty), str_ty);
    }

    fn inspectList(self: *Builder, value: Ast.ExprId, elem_ty: Type.TypeId, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        if (try self.typeIsProvenUninhabited(elem_ty)) return try self.stringExpr("[]", str_ty);
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);

        const len_local = try self.program.addLocal(self.symbols.fresh(), u64_ty);
        const len_pat = try self.bindPat(len_local, u64_ty);
        const len_value = try self.lowLevelExpr(.list_len, &.{value}, u64_ty);
        const len_expr = try self.localExpr(len_local, u64_ty);

        const index_local = try self.program.addLocal(self.symbols.fresh(), u64_ty);
        const out_local = try self.program.addLocal(self.symbols.fresh(), str_ty);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const out_expr = try self.localExpr(out_local, str_ty);

        const done_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, len_expr }, bool_ty);
        const finish = try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .break_ = try self.concatExpr(out_expr, try self.stringExpr("]", str_ty), str_ty) },
        });
        const step = try self.inspectListStep(value, elem_ty, str_ty, index_local, out_local);
        const body = try self.ifExpr(done_cond, finish, step, str_ty);

        const params = [_]Ast.TypedLocal{
            .{ .local = index_local, .ty = u64_ty },
            .{ .local = out_local, .ty = str_ty },
        };
        const initial_values = [_]Ast.ExprId{
            try self.intLiteralExpr(0, u64_ty),
            try self.stringExpr("[", str_ty),
        };
        const loop = try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .loop_ = .{
                .params = try self.program.addTypedLocalSpan(&params),
                .initial_values = try self.program.addExprSpan(&initial_values),
                .body = body,
            } },
        });
        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .let_ = .{
                .bind = len_pat,
                .value = len_value,
                .rest = loop,
            } },
        });
    }

    fn inspectListStep(
        self: *Builder,
        list_value: Ast.ExprId,
        elem_ty: Type.TypeId,
        str_ty: Type.TypeId,
        index_local: Ast.LocalId,
        out_local: Ast.LocalId,
    ) Allocator.Error!Ast.ExprId {
        const u64_ty = try self.primitiveType(.u64);
        const bool_ty = try self.primitiveType(.bool);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const out_expr = try self.localExpr(out_local, str_ty);

        const first_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, try self.intLiteralExpr(0, u64_ty) }, bool_ty);
        const sep = try self.ifExpr(first_cond, try self.stringExpr("", str_ty), try self.stringExpr(", ", str_ty), str_ty);
        const elem = try self.lowLevelExpr(.list_get_unsafe, &.{ list_value, index_expr }, elem_ty);
        const elem_str = try self.inspectCall(elem, elem_ty, str_ty);
        const with_sep = try self.concatExpr(out_expr, sep, str_ty);
        const next_out = try self.concatExpr(with_sep, elem_str, str_ty);
        const next_index = try self.lowLevelExpr(.num_plus, &.{ index_expr, try self.intLiteralExpr(1, u64_ty) }, u64_ty);
        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .continue_ = .{ .values = try self.program.addExprSpan(&.{ next_index, next_out }) } },
        });
    }

    fn primitiveType(self: *Builder, primitive: Type.Primitive) Allocator.Error!Type.TypeId {
        return switch (primitive) {
            .u64 => blk: {
                if (self.u64_ty) |ty| break :blk ty;
                const ty = try self.program.types.add(.{ .primitive = .u64 });
                self.u64_ty = ty;
                break :blk ty;
            },
            .bool => blk: {
                if (self.bool_ty) |ty| break :blk ty;
                const ty = try self.program.types.add(.{ .primitive = .bool });
                self.bool_ty = ty;
                break :blk ty;
            },
            .str, .u8, .i8, .u16, .i16, .u32, .i32, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => try self.program.types.add(.{ .primitive = primitive }),
        };
    }

    fn functionTypeFromMonoArgs(self: *Builder, arg_tys: []const Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        if (self.active_graph != null) {
            Common.invariant("active Monotype body lowering must build function types through BodyContext graph-node helpers");
        }
        return try self.closedFunctionType(arg_tys, ret_ty);
    }

    /// Intern a function from children that have already been sealed. This is
    /// used during draft finalization, where the active graph remains present
    /// but the supplied TypeIds are durable rather than active snapshots.
    fn closedFunctionType(self: *Builder, arg_tys: []const Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.program.types.add(.{ .func = .{
            .args = try self.program.types.addSpan(arg_tys),
            .ret = ret_ty,
        } });
    }

    fn oneArgFnType(self: *Builder, arg_ty: Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.functionTypeFromMonoArgs(&.{arg_ty}, ret_ty);
    }

    fn singleTypeArg(self: *Builder, span: Type.Span, comptime owner: []const u8) Type.TypeId {
        const args = self.program.types.span(span);
        if (args.len != 1) Common.invariant(owner ++ " type reached Monotype inspect lowering without one type argument");
        return GuardedList.at(args, 0);
    }

    fn localExpr(self: *Builder, local: Ast.LocalId, ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{ .ty = ty, .data = .{ .local = local } });
    }

    fn bindPat(self: *Builder, local: Ast.LocalId, ty: Type.TypeId) Allocator.Error!Ast.PatId {
        return try self.program.addPat(.{ .ty = ty, .data = .{ .bind = local } });
    }

    fn stringExpr(self: *Builder, text: []const u8, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{
            .ty = str_ty,
            .data = .{ .str_lit = try self.program.addStringLiteral(text) },
        });
    }

    fn intLiteralExpr(self: *Builder, value: u64, ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{
            .ty = ty,
            .data = .{ .int_lit = unsignedIntLiteral(value) },
        });
    }

    fn lowLevelExpr(self: *Builder, op: can.CIR.Expr.LowLevel, args: []const Ast.ExprId, ret_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.program.addExpr(.{
            .ty = ret_ty,
            .data = .{ .low_level = .{
                .op = op,
                .args = try self.program.addExprSpan(args),
            } },
        });
    }

    fn concatExpr(self: *Builder, left: Ast.ExprId, right: Ast.ExprId, str_ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        return try self.lowLevelExpr(.str_concat, &.{ left, right }, str_ty);
    }

    fn ifExpr(self: *Builder, cond: Ast.ExprId, then_expr: Ast.ExprId, else_expr: Ast.ExprId, ty: Type.TypeId) Allocator.Error!Ast.ExprId {
        const branches = [_]Ast.IfBranch{.{ .cond = cond, .body = then_expr }};
        return try self.program.addExpr(.{
            .ty = ty,
            .data = .{ .if_ = .{
                .branches = try self.program.addIfBranchSpan(&branches),
                .final_else = else_expr,
            } },
        });
    }

    const HostedTryInfo = struct {
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
        ok_tag: Type.Tag,
        err_tag: Type.Tag,
    };

    /// Reserved labels for the optional-slot encoding; see design.md "Field
    /// Kinds". Sorting fixes Missing at index 0 and Present at index 1.
    const optional_slot_missing_tag = "#Missing";
    const optional_slot_present_tag = "#Present";

    /// `Str.inspect`'s non-value marker for a missing optional field.
    const optional_field_missing_render = "<missing>";

    const OptionalSlotInfo = struct {
        payload_ty: Type.TypeId,
        missing_tag: Type.Tag,
        present_tag: Type.Tag,
    };

    /// Return the exact direct-hosted source type required when a request
    /// widens the declared `Try` error-label set. The source keeps every
    /// requested representation choice (arguments, Ok payload, and error
    /// payloads) but contains only the declared error labels, so the generated
    /// Roc adapter performs one explicit row injection and no representation
    /// conversion.
    fn hostedTryAdapterSourceType(
        self: *Builder,
        capability: ?HostedTryAdapterCapability,
        declared_fn_ty: Type.TypeId,
        requested_fn_ty: Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const hosted_try = capability orelse return null;
        if (self.sameMonoType(declared_fn_ty, requested_fn_ty)) return null;
        const declared = self.functionShape(declared_fn_ty, "hosted declared type was not a function");
        const requested = self.functionShape(requested_fn_ty, "hosted requested type was not a function");
        if (self.sameMonoType(declared.ret, requested.ret)) return null;

        const declared_try = self.hostedTryInfoOrNull(hosted_try, declared.ret) orelse return null;
        const requested_try = self.hostedTryInfoOrNull(hosted_try, requested.ret) orelse return null;

        const declared_args = self.program.types.span(declared.args);
        const requested_args = self.program.types.span(requested.args);
        if (declared_args.len != requested_args.len) {
            Common.invariant("hosted function use changed arity from the declared ABI");
        }

        const declared_err_tags = self.tagUnionTags(declared_try.err_ty);
        const requested_err_tags = self.tagUnionTags(requested_try.err_ty);
        if (requested_err_tags.len < declared_err_tags.len) {
            Common.invariant("hosted Try request removed a declared error label");
        }
        const narrowed_tags = try self.allocator.alloc(Type.Tag, declared_err_tags.len);
        defer self.allocator.free(narrowed_tags);
        for (0..declared_err_tags.len) |index| {
            const declared_tag = GuardedList.at(declared_err_tags, index);
            const requested_tag = self.tagByNameOrNull(requested_try.err_ty, declared_tag.name) orelse
                Common.invariant("hosted Try request removed a declared error label");
            const declared_payloads = self.program.types.span(declared_tag.payloads);
            const requested_payloads = self.program.types.span(requested_tag.payloads);
            if (declared_payloads.len != requested_payloads.len) {
                Common.invariant("hosted Try request changed a declared error payload arity");
            }
            narrowed_tags[index] = requested_tag;
        }
        if (requested_err_tags.len == declared_err_tags.len) return null;

        const narrowed_err_ty = try self.program.types.add(.{
            .tag_union = try self.program.types.addTagVariants(&self.program.names, narrowed_tags),
        });
        const narrowed_try_ty = try self.hostedTryTypeLike(hosted_try, requested.ret, requested_try.ok_ty, narrowed_err_ty);
        const source_args = try GuardedList.dupe(self.allocator, Type.TypeId, requested_args);
        defer self.allocator.free(source_args);
        return try self.closedFunctionType(source_args, narrowed_try_ty);
    }

    fn hostedTryAdapterBody(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        args: Ast.Span(Ast.TypedLocal),
        source_fn: Ast.FnId,
        source_fn_ty: Type.TypeId,
        target_fn_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        const source = self.functionShape(source_fn_ty, "hosted source adapter type was not a function");
        const target = self.functionShape(target_fn_ty, "hosted target adapter type was not a function");
        const source_args = self.program.types.span(source.args);
        const target_args = self.program.types.span(target.args);
        const adapter_args = self.program.typedLocalSpan(args);
        if (source_args.len != target_args.len or source_args.len != GuardedList.borrowLen(adapter_args)) {
            Common.invariant("hosted Try adapter arity differed from its function types");
        }

        const call_args = try self.allocator.alloc(Ast.ExprId, GuardedList.borrowLen(adapter_args));
        defer self.allocator.free(call_args);
        for (0..GuardedList.borrowLen(adapter_args)) |index| {
            const arg = GuardedList.at(adapter_args, index);
            const source_arg_ty = GuardedList.at(source_args, index);
            const target_arg_ty = GuardedList.at(target_args, index);
            if (!self.sameMonoType(arg.ty, source_arg_ty) or !self.sameMonoType(arg.ty, target_arg_ty)) {
                Common.invariant("hosted Try adapter argument type differed from source or target function type");
            }
            call_args[index] = try self.localExpr(arg.local, arg.ty);
        }

        const source_call = try self.program.addExpr(.{
            .ty = source.ret,
            .data = .{ .call_proc = .{
                .callee = Ast.localProcCallee(source_fn),
                .args = try self.program.addExprSpan(call_args),
            } },
        });
        return try self.hostedTryReturnInjectionExpr(capability, source_call, source.ret, target.ret);
    }

    fn hostedTryReturnInjectionExpr(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        source_expr: Ast.ExprId,
        source_try_ty: Type.TypeId,
        target_try_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        if (self.sameMonoType(source_try_ty, target_try_ty)) return source_expr;

        const source_info = self.hostedTryInfo(capability, source_try_ty);
        const target_info = self.hostedTryInfo(capability, target_try_ty);
        if (!self.sameMonoType(source_info.ok_ty, target_info.ok_ty)) {
            Common.invariant("Try adapter changed Ok type");
        }
        if (!self.errorRowIsIncludedIn(source_info.err_ty, target_info.err_ty)) {
            Common.invariant("Try adapter error row was not included in target row");
        }

        const ok_local = try self.program.addLocal(self.symbols.fresh(), source_info.ok_ty);
        const ok_payload_pat = try self.bindPat(ok_local, source_info.ok_ty);
        const ok_pat = try self.program.addPat(.{ .ty = source_try_ty, .data = .{ .tag = .{
            .name = source_info.ok_tag.name,
            .payloads = try self.program.addPatSpan(&[_]Ast.PatId{ok_payload_pat}),
        } } });
        const ok_value = try self.localExpr(ok_local, source_info.ok_ty);
        const ok_body = try self.hostedTryOkExpr(capability, target_try_ty, ok_value);

        const err_local = try self.program.addLocal(self.symbols.fresh(), source_info.err_ty);
        const err_payload_pat = try self.bindPat(err_local, source_info.err_ty);
        const err_pat = try self.program.addPat(.{ .ty = source_try_ty, .data = .{ .tag = .{
            .name = source_info.err_tag.name,
            .payloads = try self.program.addPatSpan(&[_]Ast.PatId{err_payload_pat}),
        } } });
        const err_value = try self.localExpr(err_local, source_info.err_ty);
        const injected_err = try self.errorRowInjectionExpr(err_value, source_info.err_ty, target_info.err_ty);
        const err_body = try self.hostedTryErrExpr(capability, target_try_ty, injected_err);

        const branches = [_]Ast.Branch{
            .{ .pat = ok_pat, .body = ok_body },
            .{ .pat = err_pat, .body = err_body },
        };
        return try self.program.addExpr(.{ .ty = target_try_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.program.addBranchSpan(&branches),
        } } });
    }

    fn errorRowInjectionExpr(
        self: *Builder,
        source_expr: Ast.ExprId,
        source_err_ty: Type.TypeId,
        target_err_ty: Type.TypeId,
    ) Allocator.Error!Ast.ExprId {
        if (self.sameMonoType(source_err_ty, target_err_ty)) return source_expr;

        const source_tags = self.tagUnionTags(source_err_ty);
        if (source_tags.len == 0) {
            return try self.program.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
                .scrutinee = source_expr,
                .branches = Ast.Span(Ast.Branch).empty(),
            } } });
        }

        const branches = try self.allocator.alloc(Ast.Branch, source_tags.len);
        defer self.allocator.free(branches);
        for (0..source_tags.len) |index| {
            const source_tag = GuardedList.at(source_tags, index);
            const source_payload_tys = self.program.types.span(source_tag.payloads);
            const target_tag = self.tagByName(target_err_ty, source_tag.name);
            const target_payload_tys = self.program.types.span(target_tag.payloads);
            if (source_payload_tys.len != target_payload_tys.len) {
                Common.invariant("Try adapter error tag payload arity differed in target row");
            }

            const payload_pats = try self.allocator.alloc(Ast.PatId, source_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(Ast.ExprId, source_payload_tys.len);
            defer self.allocator.free(payload_exprs);
            for (0..source_payload_tys.len) |payload_index| {
                const source_payload_ty = GuardedList.at(source_payload_tys, payload_index);
                const target_payload_ty = GuardedList.at(target_payload_tys, payload_index);
                if (!self.sameMonoType(source_payload_ty, target_payload_ty)) {
                    Common.invariant("Try adapter error tag payload type differed in target row");
                }
                const local = try self.program.addLocal(self.symbols.fresh(), source_payload_ty);
                payload_pats[payload_index] = try self.bindPat(local, source_payload_ty);
                payload_exprs[payload_index] = try self.localExpr(local, source_payload_ty);
            }

            const pat = try self.program.addPat(.{ .ty = source_err_ty, .data = .{ .tag = .{
                .name = source_tag.name,
                .payloads = try self.program.addPatSpan(payload_pats),
            } } });
            const body = try self.tagValueExpr(target_err_ty, target_tag, payload_exprs);
            branches[index] = .{ .pat = pat, .body = body };
        }

        return try self.program.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.program.addBranchSpan(branches),
        } } });
    }

    fn hostedTryOkExpr(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId, value_expr: Ast.ExprId) Allocator.Error!Ast.ExprId {
        const info = self.hostedTryInfo(capability, try_ty);
        return try self.tagValueExpr(try_ty, info.ok_tag, &[_]Ast.ExprId{value_expr});
    }

    fn hostedTryErrExpr(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId, err_expr: Ast.ExprId) Allocator.Error!Ast.ExprId {
        const info = self.hostedTryInfo(capability, try_ty);
        return try self.tagValueExpr(try_ty, info.err_tag, &[_]Ast.ExprId{err_expr});
    }

    fn tagValueExpr(
        self: *Builder,
        ty: Type.TypeId,
        tag: Type.Tag,
        payloads: []const Ast.ExprId,
    ) Allocator.Error!Ast.ExprId {
        const backing_ty = self.nominalExprBackingType(ty) orelse ty;
        const tag_expr = try self.program.addExpr(.{
            .ty = backing_ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = try self.program.addExprSpan(payloads),
            } },
        });
        if (self.nominalExprBackingType(ty) != null) {
            return try self.program.addExpr(.{ .ty = ty, .data = .{ .nominal = tag_expr } });
        }
        return tag_expr;
    }

    fn hostedTryInfo(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId) HostedTryInfo {
        return self.hostedTryInfoOrNull(capability, try_ty) orelse
            Common.invariant("hosted Try capability did not match its Monotype result");
    }

    fn hostedTryInfoOrNull(self: *Builder, capability: HostedTryAdapterCapability, try_ty: Type.TypeId) ?HostedTryInfo {
        const named = switch (self.program.types.get(try_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        if (!sameTypeDef(named.def, capability.def)) return null;
        if (capability.ok_type_arg_index >= self.program.types.span(named.args).len or
            capability.err_type_arg_index >= self.program.types.span(named.args).len)
        {
            Common.invariant("hosted Try capability referenced a missing Monotype type argument");
        }
        const backing_ty = named.backing orelse Common.invariant("hosted Try nominal had no backing");
        const ok_tag = self.tagByNameOrNull(backing_ty.ty, capability.ok_tag) orelse
            Common.invariant("hosted Try backing omitted its capability-recorded Ok tag");
        const err_tag = self.tagByNameOrNull(backing_ty.ty, capability.err_tag) orelse
            Common.invariant("hosted Try backing omitted its capability-recorded Err tag");
        const ok_payloads = self.program.types.span(ok_tag.payloads);
        const err_payloads = self.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) {
            Common.invariant("hosted Try capability tags did not have one payload each");
        }
        const args = self.program.types.span(named.args);
        const ok_ty = GuardedList.at(args, capability.ok_type_arg_index);
        const err_ty = GuardedList.at(args, capability.err_type_arg_index);
        if (!self.sameMonoType(ok_ty, GuardedList.at(ok_payloads, 0)) or
            !self.sameMonoType(err_ty, GuardedList.at(err_payloads, 0)))
        {
            Common.invariant("hosted Try capability payload mapping disagreed with its nominal arguments");
        }
        return .{
            .ok_ty = ok_ty,
            .err_ty = err_ty,
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn hostedTryTypeLike(
        self: *Builder,
        capability: HostedTryAdapterCapability,
        template_try_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const template = switch (self.program.types.get(template_try_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("Try template type was not named"),
        };
        if (!sameTypeDef(template.def, capability.def)) {
            Common.invariant("hosted Try capability did not match the adapter template nominal");
        }
        const template_backing = template.backing orelse
            Common.invariant("Try template type had no backing");
        const template_tags = switch (self.shapeContent(template_backing.ty)) {
            .tag_union => |span| self.program.types.tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("Try template backing type was not a tag union"),
        };
        const tags = try self.allocator.alloc(Type.Tag, template_tags.len);
        defer self.allocator.free(tags);
        var found_ok = false;
        var found_err = false;
        for (0..template_tags.len) |index| {
            const tag = GuardedList.at(template_tags, index);
            const payload_ty = if (tag.name == capability.ok_tag) blk: {
                found_ok = true;
                break :blk ok_ty;
            } else if (tag.name == capability.err_tag) blk: {
                found_err = true;
                break :blk err_ty;
            } else Common.invariant("hosted Try backing contained a tag absent from its capability");
            tags[index] = .{
                .name = tag.name,
                .checked_name = tag.checked_name,
                .payloads = try self.program.types.addSpan(&.{payload_ty}),
            };
        }
        if (!found_ok or !found_err) {
            Common.invariant("Try backing type did not contain Ok and Err tags");
        }
        const backing_ty = try self.program.types.add(.{
            .tag_union = try self.program.types.addTagVariants(&self.program.names, tags),
        });
        const template_args = self.program.types.span(template.args);
        if (capability.ok_type_arg_index >= template_args.len or capability.err_type_arg_index >= template_args.len) {
            Common.invariant("hosted Try capability referenced a missing template type argument");
        }
        const args = try GuardedList.dupe(self.allocator, Type.TypeId, template_args);
        defer self.allocator.free(args);
        args[capability.ok_type_arg_index] = ok_ty;
        args[capability.err_type_arg_index] = err_ty;
        return try self.program.types.add(.{ .named = .{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.program.types.addSpan(args),
            .backing = .{
                .ty = backing_ty,
                .use = template_backing.use,
                .authority = template_backing.authority,
            },
            .declared_order = template.declared_order,
        } });
    }

    fn errorRowIsIncludedIn(self: *Builder, source_err_ty: Type.TypeId, target_err_ty: Type.TypeId) bool {
        if (self.sameMonoType(source_err_ty, target_err_ty)) return true;
        const source_tags = self.tagUnionTags(source_err_ty);
        for (0..source_tags.len) |index| {
            const source_tag = GuardedList.at(source_tags, index);
            const target_tag = self.tagByNameOrNull(target_err_ty, source_tag.name) orelse return false;
            const source_payloads = self.program.types.span(source_tag.payloads);
            const target_payloads = self.program.types.span(target_tag.payloads);
            if (source_payloads.len != target_payloads.len) return false;
            for (0..source_payloads.len) |payload_index| {
                const source_payload = GuardedList.at(source_payloads, payload_index);
                const target_payload = GuardedList.at(target_payloads, payload_index);
                if (!self.sameMonoType(source_payload, target_payload)) return false;
            }
        }
        return true;
    }

    fn tagByName(self: *Builder, ty: Type.TypeId, name: names.TagNameId) Type.Tag {
        return self.tagByNameOrNull(ty, name) orelse Common.invariant("tag operation referenced tag absent from Monotype type");
    }

    fn tagByNameOrNull(self: *Builder, ty: Type.TypeId, name: names.TagNameId) ?Type.Tag {
        const tags = self.tagUnionTags(ty);
        for (0..tags.len) |index| {
            const tag = GuardedList.at(tags, index);
            if (tag.name == name) return tag;
        }
        return null;
    }

    fn tagUnionTags(self: *Builder, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Tag, "tags") {
        return switch (self.shapeContent(ty)) {
            .tag_union => |tags| self.program.types.tagSpan(tags),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("tag operation expected tag-union type"),
        };
    }

    fn nominalExprBackingType(self: *Builder, ty: Type.TypeId) ?Type.TypeId {
        return switch (self.program.types.get(ty)) {
            .named => |named| if (named.kind != .alias) blk: {
                const backing = named.backing orelse break :blk null;
                break :blk backing.ty;
            } else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn sameMonoType(self: *Builder, a: Type.TypeId, b: Type.TypeId) bool {
        if (a == b) return true;
        const a_digest = self.program.types.typeDigest(&self.program.names, a);
        const b_digest = self.program.types.typeDigest(&self.program.names, b);
        return std.mem.eql(u8, a_digest.bytes[0..], b_digest.bytes[0..]);
    }
};

const LoweredTemplateBody = struct {
    args: DraftSpan(DraftTypedLocal),
    body: DraftExprId,
    ret: DraftTypeCell,
};

const DraftTypeCell = union(enum) {
    graph_node: NodeId,
    sealed: Type.TypeId,

    fn fromGraphNode(node: NodeId) DraftTypeCell {
        return .{ .graph_node = node };
    }

    fn fromActiveType(graph: ?*InstGraph, ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        if (graph) |active_graph| {
            if (active_graph.activeSnapshotNode(ty)) |node| {
                return .{ .graph_node = node };
            }
        }
        return DraftTypeCell.fromSealed(ty);
    }

    fn fromSealed(ty: Type.TypeId) DraftTypeCell {
        return .{ .sealed = ty };
    }

    fn seal(self: DraftTypeCell, graph: *InstGraph, sealer: *GraphTypeFinals) Allocator.Error!Type.TypeId {
        return switch (self) {
            .graph_node => |node| blk: {
                const sealed = try sealer.sealNode(node);
                try graph.assertTypeHasNoActiveSnapshots(sealed);
                break :blk sealed;
            },
            .sealed => |ty| blk: {
                const sealed = try sealer.sealType(ty);
                try graph.assertTypeHasNoActiveSnapshots(sealed);
                break :blk sealed;
            },
        };
    }

    fn toGraphNode(self: DraftTypeCell, graph: *InstGraph) Allocator.Error!NodeId {
        return switch (self) {
            .graph_node => |graph_node| graph_node,
            .sealed => |ty| try graph.importMono(ty),
        };
    }

    fn sealedHasActiveSnapshots(self: DraftTypeCell, graph: *InstGraph) Allocator.Error!bool {
        return switch (self) {
            .graph_node => false,
            .sealed => |ty| try graph.typeHasActiveSnapshots(ty),
        };
    }
};

