const DraftSpecState = enum {
    /// The caller owns only this specialization's live request interface. Its
    /// body is lowered later in the procedure's own instantiation graph.
    deferred,
    /// A specialization body is currently being lowered in the active graph.
    /// This is used for lexical-context-dependent procedures and nested functions.
    lowering,
    /// A caller-owned specialization body finished lowering into this draft.
    lowered,
    /// A deferred request was resolved through the global specialization
    /// store after its request interface sealed.
    resolved,
};

fn runtimeDemandGuardFrameSetsEql(
    left: []const RuntimeDemandGuardFrameAddress,
    right: []const RuntimeDemandGuardFrameAddress,
) bool {
    for (left) |left_frame| {
        for (right) |right_frame| {
            if (std.meta.eql(left_frame, right_frame)) break;
        } else return false;
    }
    for (right) |right_frame| {
        for (left) |left_frame| {
            if (std.meta.eql(left_frame, right_frame)) break;
        } else return false;
    }
    return true;
}

fn draftOpenCandidateQualifies(
    state: DraftSpecState,
    exact_interface: bool,
    active_recursive_edge: bool,
    partial_recursive_allowed: bool,
) bool {
    return exact_interface or (state == .lowering and active_recursive_edge and partial_recursive_allowed);
}

fn draftRequestOverlapsInitialArgumentClass(
    graph: *InstGraph,
    initial_arg_classes: []const ArgumentClassSnapshot,
    request_fn_node: NodeId,
) Allocator.Error!bool {
    const request = try graph.functionNodes(request_fn_node);
    if (initial_arg_classes.len != request.args.len) {
        Common.invariant("draft recursive request changed function argument arity");
    }
    for (initial_arg_classes, request.args) |initial_class, request_arg| {
        for (initial_class.members) |member| {
            if (graph.sameClass(member, request_arg)) return true;
        }
    }
    return false;
}

fn draftCaptureEntryGuardsMatch(
    graph: *InstGraph,
    stored_guards: []const NodeId,
    requested_guards: []const NodeId,
) bool {
    if (stored_guards.len != requested_guards.len) return false;
    for (stored_guards, requested_guards) |stored, requested| {
        if (!graph.sameClass(stored, requested)) return false;
    }
    return true;
}

fn draftNestedActiveRecursiveCandidate(
    graph: *InstGraph,
    spec: *const DraftNestedSpec,
    family: DraftNestedFamilyAddress,
    capture_entry_guards: []const NodeId,
    requested_evidence: EvidenceChain,
    current_owner: DraftOwner,
) Allocator.Error!bool {
    if (spec.state != .lowering) return false;
    if (spec.request_fn_ty != null) return false;
    if (!std.meta.eql(DraftNestedFamilyAddress.init(spec.nested, spec.method_scope, spec.source_fn_key), family)) return false;
    if (!evidenceChainEql(spec.evidence, requested_evidence)) return false;
    if (!draftCaptureEntryGuardsMatch(graph, spec.capture_entry_guards, capture_entry_guards)) return false;
    if (!std.meta.eql(spec.lexical_owner, current_owner)) return false;
    return true;
}

fn draftNestedCaptureAnchoredRecursiveCandidate(
    graph: *InstGraph,
    spec: *const DraftNestedSpec,
    family: DraftNestedFamilyAddress,
    request_fn_node: NodeId,
    capture_entry_guards: []const NodeId,
    requested_evidence: EvidenceChain,
) Allocator.Error!bool {
    if (spec.state != .lowering) return false;
    if (spec.request_fn_ty != null) return false;
    if (capture_entry_guards.len == 0) return false;
    if (!std.meta.eql(DraftNestedFamilyAddress.init(spec.nested, spec.method_scope, spec.source_fn_key), family)) return false;
    if (!evidenceChainEql(spec.evidence, requested_evidence)) return false;
    if (!draftCaptureEntryGuardsMatch(graph, spec.capture_entry_guards, capture_entry_guards)) return false;

    const request = try graph.functionNodes(request_fn_node);
    if (request.args.len != 0) return false;
    const spec_request = try graph.functionNodes(spec.request_fn_node);
    if (spec_request.args.len != 0) return false;
    return true;
}

fn registerTemplateSpecLookup(
    draft: *BodyDraftStore,
    allocator: Allocator,
    address: DraftTemplateLookupAddress,
    raw_spec: u32,
) Allocator.Error!void {
    const entry = try draft.template_spec_lookup.getOrPut(address);
    if (!entry.found_existing) entry.value_ptr.* = .empty;
    for (entry.value_ptr.items) |existing| if (existing == raw_spec) return;
    try entry.value_ptr.append(allocator, raw_spec);
}

fn registerTemplateSpecInterfaceLookups(
    draft: *BodyDraftStore,
    allocator: Allocator,
    graph: *InstGraph,
    family: DraftTemplateFamilyAddress,
    evidence_digest: [32]u8,
    request_fn_node: NodeId,
    raw_spec: u32,
) Allocator.Error!void {
    var indexed_nodes = collections.DenseMap(NodeId, void).init(allocator);
    defer indexed_nodes.deinit();
    var spec_interface = try graph.functionInterfaceIterator(request_fn_node);
    while (spec_interface.next()) |interface_node| {
        const indexed = try indexed_nodes.getOrPut(interface_node);
        if (indexed.found_existing) continue;
        try registerTemplateSpecLookup(draft, allocator, .{
            .family = family,
            .evidence_digest = evidence_digest,
            .request_kind = 1,
            .request_fn_key = draftOpenRequestKey(interface_node),
        }, raw_spec);
    }
}

fn draftNestedSpecRequestNode(
    draft: *BodyDraftStore,
    graph: *InstGraph,
    spec: *const DraftNestedSpec,
) Allocator.Error!NodeId {
    return switch (spec.state) {
        .lowered => try draft.fns.items[@intFromEnum(spec.fn_id)].source.mono_fn_ty.toGraphNode(graph),
        .deferred, .lowering, .resolved => spec.request_fn_node,
    };
}

fn registerNestedSpecLookup(
    draft: *BodyDraftStore,
    allocator: Allocator,
    address: DraftNestedLookupAddress,
    raw_spec: u32,
) Allocator.Error!void {
    const entry = try draft.nested_spec_lookup.getOrPut(address);
    if (!entry.found_existing) entry.value_ptr.* = .empty;
    for (entry.value_ptr.items) |existing| if (existing == raw_spec) return;
    try entry.value_ptr.append(allocator, raw_spec);
}

fn registerNestedSpecInterfaceLookups(
    draft: *BodyDraftStore,
    allocator: Allocator,
    graph: *InstGraph,
    family: DraftNestedFamilyAddress,
    evidence_digest: [32]u8,
    request_fn_node: NodeId,
    raw_spec: u32,
) Allocator.Error!void {
    var indexed_nodes = collections.DenseMap(NodeId, void).init(allocator);
    defer indexed_nodes.deinit();
    var spec_interface = try graph.functionInterfaceIterator(request_fn_node);
    while (spec_interface.next()) |interface_node| {
        const indexed = try indexed_nodes.getOrPut(interface_node);
        if (indexed.found_existing) continue;
        try registerNestedSpecLookup(draft, allocator, .{
            .family = family,
            .evidence_digest = evidence_digest,
            .request_kind = 1,
            .request_fn_key = draftOpenRequestKey(interface_node),
        }, raw_spec);
    }
}

/// Re-verify a reused specialization's runtime-value demands under each
/// reusing guard context. The creating context is checked demand-by-demand at
/// seal; a reuse from a different context must independently exempt every
/// demand that finalized as a closed empty tag union, with the reusing
/// context's proof standing in for the creation context's inherited frames.
fn verifySpecReuseDemands(
    body_draft: *const BodyDraftStore,
    graph: *InstGraph,
    evaluator: *FrozenRuntimeImpossibilityProofEvaluator,
) Allocator.Error!void {
    for (body_draft.template_spec_reuses.items) |reuse| {
        const spec = body_draft.template_specs.items[reuse.spec];
        try verifyReusedDemandRange(body_draft, graph, evaluator, reuse, spec.demand_start, spec.demand_end, spec.demand_frame_floor);
    }
    for (body_draft.nested_spec_reuses.items) |reuse| {
        const spec = body_draft.nested_specs.items[reuse.spec];
        try verifyReusedDemandRange(body_draft, graph, evaluator, reuse, spec.demand_start, spec.demand_end, spec.demand_frame_floor);
    }
}

fn verifyReusedDemandRange(
    body_draft: *const BodyDraftStore,
    graph: *InstGraph,
    evaluator: *FrozenRuntimeImpossibilityProofEvaluator,
    reuse: DraftSpecReuse,
    start: u32,
    end: u32,
    frame_floor: RuntimeDemandGuardFrameStack,
) Allocator.Error!void {
    if (start > end or end > body_draft.runtime_value_demands.items.len) {
        Common.invariant("reused specialization demand range was out of bounds");
    }
    demand_loop: for (body_draft.runtime_value_demands.items[start..end]) |demand| {
        if (!graph.finalizesAsClosedEmptyTagUnion(demand.node)) continue;
        // The creation context's certification covers the one emitted body:
        // statement-position guard frames are not monotonic across call sites
        // in one block, so a reusing context can legitimately lack a frame
        // (e.g. a call lowered before the DraftStmt whose result proves later
        // DraftStmt nodes unreachable) without the demand needing runtime code.
        if (try evaluator.holds(demand.impossibility_proof)) continue;
        if (try evaluator.holds(reuse.prefix_proof)) continue;
        if (try evaluator.holds(demand.local_proof)) continue;
        if (demand.frames.depth < frame_floor.depth) {
            Common.invariant("reused specialization demand lost its inherited guard frame prefix");
        }
        var demand_frames = demand.frames;
        while (demand_frames.depth > frame_floor.depth) {
            const frame_id = demand_frames.head orelse
                Common.invariant("non-empty runtime-demand guard stack had no head frame");
            const frame = runtimeDemandGuardFrame(body_draft, frame_id);
            if (try evaluator.holds(frame.proof)) continue :demand_loop;
            demand_frames = .{ .head = frame.parent, .depth = demand_frames.depth - 1 };
        }
        if (demand_frames.head != frame_floor.head) {
            Common.invariant("reused specialization demand did not inherit its recorded guard frame prefix");
        }
        Common.invariant("runtime-value demand finalized as a closed empty tag-union type under a reusing guard context");
    }
}

/// Active graph relations can make independently created draft requests share
/// one complete function interface. Exact matches therefore converge on the
/// earliest recorded specialization, matching final draft commit order. A
/// partial match is an active recursive edge and must remain unique.
const DraftOpenCandidateSelection = struct {
    exact: ?u32 = null,
    partial: ?u32 = null,

    fn add(self: *DraftOpenCandidateSelection, raw_spec: u32, exact_interface: bool) bool {
        if (exact_interface) {
            if (self.exact == null or raw_spec < self.exact.?) self.exact = raw_spec;
            return true;
        }
        if (self.partial) |existing| {
            if (existing != raw_spec) return false;
        } else {
            self.partial = raw_spec;
        }
        return true;
    }

    fn selected(self: DraftOpenCandidateSelection) ?u32 {
        return self.exact orelse self.partial;
    }
};

const DraftTemplateFamilyAddress = struct {
    module: [32]u8,
    proc_base: u32,
    template: u32,
    method_scope: [32]u8,
    source_fn_key: [32]u8,

    fn init(template_ref: names.ProcTemplate, method_scope: checked.ModuleId, source_fn_key: names.TypeDigest) DraftTemplateFamilyAddress {
        return .{
            .module = names.procTemplateModuleDigest(template_ref).bytes,
            .proc_base = @intFromEnum(template_ref.proc_base),
            .template = @intFromEnum(template_ref.template),
            .method_scope = method_scope.bytes,
            .source_fn_key = source_fn_key.bytes,
        };
    }

    /// Recursive references may instantiate the same checked procedure
    /// template through a different checked root. Declaration and method scope
    /// identify the active body; the complete live function interface decides
    /// whether the reference belongs to that specialization.
    fn sameRecursiveCallable(self: DraftTemplateFamilyAddress, other: DraftTemplateFamilyAddress) bool {
        return std.mem.eql(u8, self.module[0..], other.module[0..]) and
            self.proc_base == other.proc_base and
            self.template == other.template and
            std.mem.eql(u8, self.method_scope[0..], other.method_scope[0..]);
    }
};

/// One globally reserved procedure specialization while its body is lowering
/// in the specialization's own instantiation graph. Recursive references use
/// this live root rather than creating a deferred sibling specialization.
const ActiveTemplateRoot = struct {
    graph: *InstGraph,
    family: DraftTemplateFamilyAddress,
    evidence: []const SpecEvidence,
    request_fn_node: NodeId,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    fn_id: Ast.FnId,
};

const DraftNestedFamilyAddress = struct {
    module: [32]u8,
    owner_proc_base: u32,
    owner_template: u32,
    owner_fn_key: [32]u8,
    site: u32,
    method_scope: [32]u8,
    source_fn_key: [32]u8,

    fn init(nested: Ast.NestedFn, method_scope: checked.ModuleId, source_fn_key: names.TypeDigest) DraftNestedFamilyAddress {
        return .{
            .module = names.procTemplateModuleDigest(nested.owner).bytes,
            .owner_proc_base = @intFromEnum(nested.owner.proc_base),
            .owner_template = @intFromEnum(nested.owner.template),
            .owner_fn_key = nested.context_fn_key.bytes,
            .site = @intFromEnum(nested.site),
            .method_scope = method_scope.bytes,
            .source_fn_key = source_fn_key.bytes,
        };
    }
};

const DraftTemplateLookupAddress = struct {
    family: DraftTemplateFamilyAddress,
    evidence_digest: [32]u8,
    request_kind: u8,
    request_fn_key: [32]u8,
};

const DraftNestedLookupAddress = struct {
    family: DraftNestedFamilyAddress,
    evidence_digest: [32]u8,
    request_kind: u8,
    request_fn_key: [32]u8,
};

fn draftOpenRequestKey(node: NodeId) [32]u8 {
    var bytes = [_]u8{0} ** 32;
    std.mem.writeInt(u32, bytes[0..@sizeOf(u32)], @intFromEnum(node), .little);
    return bytes;
}

const DraftTemplateSpec = struct {
    state: DraftSpecState,
    template_ref: names.ProcTemplate,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch embedded in this specialization's body.
    method_scope: checked.ModuleId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    request_fn_node: NodeId,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    evidence: []const SpecEvidence,
    runtime_demand_guard_frames: []const RuntimeDemandGuardFrameAddress,
    /// Runtime-value demands recorded while this specialization's body (and
    /// any explicitly lexical-context-dependent procedure bodies it owns)
    /// lowered, re-verified at seal for every reusing guard context.
    demand_start: u32 = 0,
    demand_end: u32 = 0,
    /// Guard frames inherited from the requesting context at body start; a
    /// demand's ancestors below this snapshot belong to the reused-away
    /// context.
    demand_frame_floor: RuntimeDemandGuardFrameStack = .{},
    requires_local: bool = false,
    local_context_dependent: bool = false,
    lexical_owner: ?DraftOwner = null,
    lexical: ?DraftCodecLexicalContext = null,
    lexical_context_key: ?names.TypeDigest = null,
    fn_id: DraftFnId,
    resolved_slot: ?Ast.FnSlot = null,
};

const DraftConstUseProvenance = union(enum) {
    declared,
    hoisted: checked.HoistedConstEntry,
};

const DraftDeferredConstUse = struct {
    view: ModuleView,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch inside the deferred emission, captured at deferral time.
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    /// Checked-public request interface owned by the use site.
    request_node: NodeId,
    /// Exact producer-owned runtime representation stored with the const.
    witness_node: NodeId,
    const_use: checked.ConstUseTemplate,
    /// Explicit checker-owned origin for selecting the restoration path.
    provenance: DraftConstUseProvenance,
    context_evidence: EvidenceChain,
    use_evidence: []const SpecEvidence,
    current_fn_key: names.TypeDigest,
    /// Durable ancestry of constant expansions active at the use site. The
    /// deferred expansion must restore this chain so a delayed recursive edge
    /// resolves to its already-reserved local.
    active_const_binding: ?ActiveConstBindingId,
    lexical: DraftCodecLexicalContext,
    /// Stable proof node stored with the reservation expression. Parents
    /// may reference it before const restoration expands this boundary.
    proof_reservation: RuntimeImpossibilityProofId,
    /// Explicit expression produced by expansion. Reservation data is copied
    /// only after the complete deferred-const dependency graph is known.
    restored_source: ?DraftExprId = null,
};

/// A pending compile-time callable root currently being expanded into the
