/// One call-site intrinsic whose callable request still carried unresolved
/// component cells at body-lowering time (e.g. a `FieldName(shape)` whose
/// shape row stays widenable until final sealing). The reservation keeps the
/// callable's result node live; emission lowers the intrinsic body under the
/// frozen final-type sealer.
const CheckedIntrinsicOperands = union(enum) {
    direct_call: []const checked.CheckedExprId,
    dispatch: []const static_dispatch.StaticDispatchOperand,
};

const DraftDeferredCallsiteIntrinsic = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    intrinsic: checked.IntrinsicId,
    checked_expr_id: checked.CheckedExprId,
    source_fn_ty: checked.CheckedTypeId,
    operands: CheckedIntrinsicOperands,
    pre_lowered_args: ?DraftSpan(DraftExprId),
    callable_node: NodeId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
};

const DraftCodecLocalProcContext = struct {
    declaration: DraftLocalProcAddress,
    context: DraftLocalProcContextId,
};

const DraftCodecLexicalContext = struct {
    view: [32]u8,
    binders: []const LexicalBinderEntry,
    local_procs: []const DraftCodecLocalProcContext,
};

const CodecKind = enum {
    parser,
    encoder,
};

const CodecCallPurpose = enum {
    format,
    custom,
};

const PreparedCodecCallId = enum(u32) { _ };

/// One exact codec request prepared while the specialization graph still
/// accepts relations. The callable node owns every checked/private component;
/// ordinary procedure targets use the same deferred specialization slot as
/// every other call in the compiler.
const DraftPreparedCodecCall = struct {
    boundary_expr: DraftExprId,
    kind: CodecKind,
    purpose: CodecCallPurpose = .format,
    shape_node: NodeId,
    lookup: MethodLookup,
    callable_node: NodeId,
    callee: DraftFnSlot,
};

const FrozenPreparedCodecCall = struct {
    kind: CodecKind,
    purpose: CodecCallPurpose,
    shape_ty: Type.TypeId,
    lookup: MethodLookup,
    callable_ty: Type.TypeId,
    callee: DraftFnSlot,
};

const CustomCodecCallAddress = struct {
    kind: CodecKind,
    shape_ty: Type.TypeId,
};

const FrozenPreparedCodecCalls = struct {
    calls: []FrozenPreparedCodecCall,
    custom_call_ids: std.AutoHashMap(CustomCodecCallAddress, PreparedCodecCallId),

    fn init(allocator: Allocator, calls: []FrozenPreparedCodecCall) Allocator.Error!FrozenPreparedCodecCalls {
        errdefer allocator.free(calls);
        var custom_call_ids = std.AutoHashMap(CustomCodecCallAddress, PreparedCodecCallId).init(allocator);
        errdefer custom_call_ids.deinit();

        for (calls, 0..) |call, index| {
            if (call.purpose != .custom) continue;
            if (index > std.math.maxInt(u32)) Common.invariant("prepared codec call index exceeded its identity range");
            const entry = try custom_call_ids.getOrPut(.{ .kind = call.kind, .shape_ty = call.shape_ty });
            if (entry.found_existing) Common.invariant("frozen codec plan had multiple custom calls for one shape");
            entry.value_ptr.* = @enumFromInt(index);
        }

        return .{ .calls = calls, .custom_call_ids = custom_call_ids };
    }

    fn deinit(self: *FrozenPreparedCodecCalls, allocator: Allocator) void {
        self.custom_call_ids.deinit();
        allocator.free(self.calls);
    }

    fn customCall(
        self: *const FrozenPreparedCodecCalls,
        kind: CodecKind,
        shape_ty: Type.TypeId,
    ) ?*const FrozenPreparedCodecCall {
        const id = self.custom_call_ids.get(.{ .kind = kind, .shape_ty = shape_ty }) orelse return null;
        const index = @intFromEnum(id);
        if (index >= self.calls.len) Common.invariant("prepared codec call identity was outside its frozen plan");
        return &self.calls[index];
    }
};

const DraftDeferredInspect = struct {
    view: ModuleView,
    method_scope: ModuleView,
    owner_template: names.ProcTemplate,
    owner: DraftOwner,
    expr: DraftExprId,
    value: DraftExprId,
    value_node: NodeId,
    ret_ty: Type.TypeId,
    evidence: EvidenceChain,
    current_fn_key: names.TypeDigest,
    lexical: DraftCodecLexicalContext,
    /// Exact pass-local proof that the inspect body cannot be reached.
    impossibility_proof: ?RuntimeImpossibilityProofId,
};

const DraftPreparedInspectMethod = struct {
    value_node: NodeId,
    callee: DraftFnSlot,
};

const RuntimeImpossibilityProofId = enum(u32) { _ };

const RuntimeImpossibilityProof = union(enum) {
    node: NodeId,
    never,
    always,
    pending,
    forward: RuntimeImpossibilityProofId,
    any: DraftSpan(RuntimeImpossibilityProofId),
    all: DraftSpan(RuntimeImpossibilityProofId),
};

const DraftRuntimeValueDemand = struct {
    node: NodeId,
    /// Exemption proof under the demand's creation context: the full guard
    /// frame stack (inherited and body-internal) plus the local parts.
    impossibility_proof: ?RuntimeImpossibilityProofId,
    /// The exact guard frame stack at record time. A specialization reused
    /// from a different guard context re-verifies its demands at seal against
    /// the reusing context, substituting that context for the persistent stack
    /// below the owning specialization's inherited-frame floor.
    frames: RuntimeDemandGuardFrameStack,
    /// Context-independent exemption parts: function entry guards and the
    /// expression's own proof.
    local_proof: ?RuntimeImpossibilityProofId,
};

const RuntimeDemandGuardFrameKind = enum {
    match_branch,
    pattern_success,
    iterator_one,
    statement_success,
};

const RuntimeDemandGuardFrameAddress = struct {
    module: [32]u8,
    owner_module: [32]u8,
    owner_proc_base: u32,
    owner_template: u32,
    pattern: u32,
    kind: RuntimeDemandGuardFrameKind,
};

const RuntimeDemandGuardFrameId = enum(u32) { _ };

/// An immutable snapshot of the active runtime-demand guards. Every push adds
/// one parent-linked node to `BodyDraftStore.runtime_demand_guard_frames`, so
/// saving, restoring, and inheriting a stack is a fixed-size value copy.
const RuntimeDemandGuardFrameStack = struct {
    head: ?RuntimeDemandGuardFrameId = null,
    depth: u32 = 0,
};

const RuntimeDemandGuardFrame = struct {
    parent: ?RuntimeDemandGuardFrameId,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
};

fn runtimeDemandGuardFrame(
    draft: *const BodyDraftStore,
    id: RuntimeDemandGuardFrameId,
) *const RuntimeDemandGuardFrame {
    const index = @intFromEnum(id);
    if (index >= draft.runtime_demand_guard_frames.items.len) {
        Common.invariant("runtime-demand guard frame ID was outside the draft frame store");
    }
    return &draft.runtime_demand_guard_frames.items[index];
}

fn runtimeDemandGuardFrameStackContains(
    draft: *const BodyDraftStore,
    stack: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
) bool {
    var current = stack.head;
    while (current) |id| {
        const frame = runtimeDemandGuardFrame(draft, id);
        if (std.meta.eql(frame.address, address)) return true;
        current = frame.parent;
    }
    return false;
}

fn pushRuntimeDemandGuardFrame(
    draft: *BodyDraftStore,
    existing: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
) Allocator.Error!RuntimeDemandGuardFrameStack {
    const id: RuntimeDemandGuardFrameId = @enumFromInt(draft.runtime_demand_guard_frames.items.len);
    try draft.runtime_demand_guard_frames.append(draft.allocator, .{
        .parent = existing.head,
        .address = address,
        .proof = proof,
    });
    return .{ .head = id, .depth = existing.depth + 1 };
}

fn addRuntimeDemandGuardFrame(
    draft: *BodyDraftStore,
    existing: RuntimeDemandGuardFrameStack,
    address: RuntimeDemandGuardFrameAddress,
    proof: RuntimeImpossibilityProofId,
) Allocator.Error!RuntimeDemandGuardFrameStack {
    if (runtimeDemandGuardFrameStackContains(draft, existing, address)) return existing;
    return try pushRuntimeDemandGuardFrame(draft, existing, address, proof);
}

const FrozenRuntimeImpossibilityProofEvaluator = struct {
    graph: *InstGraph,
    draft: *const BodyDraftStore,
    memo: []?bool,
    active: []bool,

    fn init(
        allocator: Allocator,
        graph: *InstGraph,
        draft: *const BodyDraftStore,
    ) Allocator.Error!FrozenRuntimeImpossibilityProofEvaluator {
        const memo = try allocator.alloc(?bool, draft.impossibility_proofs.items.len);
        errdefer allocator.free(memo);
        @memset(memo, null);
        const active = try allocator.alloc(bool, draft.impossibility_proofs.items.len);
        @memset(active, false);
        return .{ .graph = graph, .draft = draft, .memo = memo, .active = active };
    }

    fn deinit(self: *FrozenRuntimeImpossibilityProofEvaluator, allocator: Allocator) void {
        allocator.free(self.active);
        allocator.free(self.memo);
    }

    fn proofSpan(self: *const FrozenRuntimeImpossibilityProofEvaluator, span: DraftSpan(RuntimeImpossibilityProofId)) []const RuntimeImpossibilityProofId {
        if (span.start > self.draft.impossibility_proof_ids.items.len or
            span.len > self.draft.impossibility_proof_ids.items.len - span.start)
        {
            Common.invariant("runtime impossibility proof span was outside the frozen draft proof store");
        }
        return self.draft.impossibility_proof_ids.items[span.start..][0..span.len];
    }

    fn holds(self: *FrozenRuntimeImpossibilityProofEvaluator, maybe_proof: ?RuntimeImpossibilityProofId) Allocator.Error!bool {
        return if (maybe_proof) |proof| try self.holdsInner(proof) else false;
    }

    fn holdsInner(self: *FrozenRuntimeImpossibilityProofEvaluator, proof_id: RuntimeImpossibilityProofId) Allocator.Error!bool {
        const index = @intFromEnum(proof_id);
        if (index >= self.draft.impossibility_proofs.items.len) {
            Common.invariant("runtime impossibility proof referenced a missing proof node");
        }
        if (self.memo[index]) |result| return result;
        if (self.active[index]) Common.invariant("runtime impossibility proof graph contained a cycle");
        self.active[index] = true;
        defer self.active[index] = false;
        const result = switch (self.draft.impossibility_proofs.items[index]) {
            .node => |node| try self.graph.finalizesAsUninhabited(node),
            .never => false,
            .always => true,
            .pending => Common.invariant("runtime impossibility proof reservation was not filled before graph sealing"),
            .forward => |child| try self.holdsInner(child),
            .any => |span| blk: {
                for (self.proofSpan(span)) |child| if (try self.holdsInner(child)) break :blk true;
                break :blk false;
            },
            .all => |span| blk: {
                for (self.proofSpan(span)) |child| if (!try self.holdsInner(child)) break :blk false;
                break :blk true;
            },
        };
        self.memo[index] = result;
        return result;
    }
};

const DraftStructuralEqMethodCall = struct {
    boundary: u32,
    node: NodeId,
    callee: DraftFnSlot,
};

const DraftNestedSpec = struct {
    state: DraftSpecState,
    nested: Ast.NestedFn,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch embedded in this specialization's body.
    method_scope: checked.ModuleId,
    expr_id: checked.CheckedExprId,
    source_fn_ty: checked.CheckedTypeId,
    source_fn_key: names.TypeDigest,
    request_fn_node: NodeId,
    initial_request_arg_classes: []const ArgumentClassSnapshot,
    request_fn_ty: ?Type.TypeId,
    evidence: EvidenceChain,
    runtime_demand_guard_frames: []const RuntimeDemandGuardFrameAddress,
    demand_start: u32 = 0,
    demand_end: u32 = 0,
    demand_frame_floor: RuntimeDemandGuardFrameStack = .{},
    capture_entry_guards: []const NodeId,
    capture_abi_digest: ?names.TypeDigest = null,
    lexical_owner: DraftOwner,
    requires_local: bool,
    local_context_dependent: bool,
    symbol: Common.Symbol,
    fn_id: DraftFnId,
    /// Exact alpha-normalized shape of the unresolved request before this nested
    /// body contributed its relations. This graph-local snapshot is the collision
    /// authority and never becomes durable specialization identity.
    open_request_shape: ?[]const u8 = null,
};

/// One reuse of a completed (or actively lowering) draft specialization from a
/// guard context that differs from the one it was created under. At seal, the
/// specialization's recorded demands are re-verified with `prefix_proof`
/// standing in for the creation context's inherited guard frames.
const DraftSpecReuse = struct {
    spec: u32,
    prefix_proof: ?RuntimeImpossibilityProofId,
};

const DraftRoot = struct {
    def: DraftDefId,
    request: checked.RootRequest,
};

const DraftLayoutRequest = struct {
    checked_type: checked.CheckedTypeId,
    ty: DraftTypeCell,
    def: ?DraftDefId = null,
    const_locator: ?checked.ConstLocator = null,
};

const DraftRuntimeSchemaRequest = struct {
    def: Type.TypeDef,
    ty: DraftTypeCell,
};

const DraftDeclaredField = union(enum(u8)) {
    named: names.RecordFieldNameId,
    padding: DraftTypeCell,
};

const DraftComptimeSite = struct {
    kind: Ast.ComptimeSiteKind,
    region: base.Region,
    checked_site: ?checked.CheckedExhaustivenessSiteId = null,
    branch_regions: DraftSpan(base.Region) = .empty(),
};

const DraftStringLiteral = struct {
    backing: DraftSpan(u8),
    offset: u32,
    len: u32,
};

const DraftPackedListLiteral = struct {
    literal: DraftStringLiteralId,
    len: u32,
    element: check.ConstStore.ConstPackedScalar,
};

const DraftOwner = union(enum(u8)) {
    root,
    draft_fn: DraftFnId,
    reserved_fn: Ast.FnId,
};

fn draftOwnerRetained(owner: DraftOwner, emit_fns: []const bool) bool {
    return switch (owner) {
        .root, .reserved_fn => true,
        .draft_fn => |fn_id| emit_fns[@intFromEnum(fn_id)],
    };
}

const DraftCoreKind = enum(u8) {
    source_files,
    string_literals,
    comptime_sites,
    branch_regions,
    expr_ids,
    pat_ids,
    stmt_ids,
    field_exprs,
    fn_def_captures,
    record_destructs,
    str_pattern_steps,
    branches,
    if_branches,
    locals,
    typed_locals,
    pats,
    exprs,
    stmts,
    proc_debug_names,
    roots,
    layout_requests,
    runtime_schema_requests,
};

const draft_core_kind_count = @typeInfo(DraftCoreKind).@"enum".fields.len;
const DraftCoreLengths = [draft_core_kind_count]u32;

const DraftOwnerRun = struct {
    owner: DraftOwner,
    starts: DraftCoreLengths,
    ends: DraftCoreLengths,
};

const CheckedStringLiteralAddress = struct {
    module_bytes: [32]u8,
    literal: checked.CheckedStringLiteralId,
    owner: DraftOwner,
};

const StaticDataCandidateAddress = struct {
    static_data: Common.StaticDataId,
    owner: DraftOwner,
};

const BodyDraftStore = struct {
    allocator: Allocator,
    fns: std.ArrayList(DraftFn),
    defs: std.ArrayList(DraftDef),
    def_owners: std.ArrayList(DraftOwner),
    nested_defs: std.ArrayList(DraftNestedDef),
    template_specs: std.ArrayList(DraftTemplateSpec),
    template_spec_by_fn: collections.DenseMap(DraftFnId, u32),
    template_spec_lookup: std.AutoHashMap(DraftTemplateLookupAddress, std.ArrayList(u32)),
    /// Exact checked identities bypass the general graph/digest lookup after
    /// the first closed direct call in this draft.
    closed_direct_specializations: std.AutoHashMap(ClosedDirectCallIdentity, ClosedDirectDraftSpecialization),
    active_callable_eval_bindings: std.ArrayList(ActiveCallableEvalBinding),
    active_const_node_bindings: std.ArrayList(ActiveConstNodeBinding),
    active_const_node_binding_indices: std.AutoHashMap(ActiveConstNodeAddress, u32),
    materialized_const_nodes: std.ArrayList(MaterializedConstNode),
    materialized_const_node_indices: std.AutoHashMap(MaterializedConstNodeAddress, u32),
    active_const_bindings: std.ArrayList(ActiveConstBinding),
    deferred_const_uses: std.ArrayList(DraftDeferredConstUse),
    deferred_structural_eqs: std.ArrayList(DraftDeferredStructuralEq),
    deferred_structural_serializations: std.ArrayList(DraftDeferredStructuralSerialization),
    deferred_callsite_intrinsics: std.ArrayList(DraftDeferredCallsiteIntrinsic),
    prepared_codec_calls: std.ArrayList(DraftPreparedCodecCall),
    local_proc_contexts: std.ArrayList(LocalProcContext),
    deferred_inspects: std.ArrayList(DraftDeferredInspect),
    prepared_inspect_methods: std.ArrayList(DraftPreparedInspectMethod),
    structural_eq_method_calls: std.ArrayList(DraftStructuralEqMethodCall),
    runtime_value_demands: std.ArrayList(DraftRuntimeValueDemand),
    runtime_demand_guard_frames: std.ArrayList(RuntimeDemandGuardFrame),
    template_spec_reuses: std.ArrayList(DraftSpecReuse),
    nested_spec_reuses: std.ArrayList(DraftSpecReuse),
    impossibility_proofs: std.ArrayList(RuntimeImpossibilityProof),
    impossibility_proof_ids: std.ArrayList(RuntimeImpossibilityProofId),
    expr_impossibility_proofs: std.ArrayList(?RuntimeImpossibilityProofId),
    pat_impossibility_proofs: std.ArrayList(?RuntimeImpossibilityProofId),
    stmt_impossibility_proofs: std.ArrayList(?RuntimeImpossibilityProofId),
    nested_specs: std.ArrayList(DraftNestedSpec),
    nested_spec_lookup: std.AutoHashMap(DraftNestedLookupAddress, std.ArrayList(u32)),
    exprs: std.ArrayList(DraftExpr),
    pats: std.ArrayList(DraftPat),
    stmts: std.ArrayList(DraftStmt),
    locals: std.ArrayList(DraftLocal),
    expr_ids: std.ArrayList(DraftExprId),
    pat_ids: std.ArrayList(DraftPatId),
    typed_locals: std.ArrayList(DraftTypedLocal),
    stmt_ids: std.ArrayList(DraftStmtId),
    field_exprs: std.ArrayList(DraftFieldExpr),
    field_access_segments: std.ArrayList(DraftFieldAccessSegment),
    fn_def_captures: std.ArrayList(DraftFnDefCapture),
    record_destructs: std.ArrayList(DraftRecordDestruct),
    str_pattern_steps: std.ArrayList(DraftStrPatternStep),
    declared_fields: std.ArrayList(DraftDeclaredField),
    branches: std.ArrayList(DraftBranch),
    if_branches: std.ArrayList(DraftIfBranch),
    string_literals: std.ArrayList(DraftStringLiteral),
    string_bytes: std.ArrayList(u8),
    /// Checked literal identities are immutable and shared by lowering
    /// contexts that write content owned by the same retained body.
    checked_string_literals: std.AutoHashMap(CheckedStringLiteralAddress, DraftStringLiteralId),
    proc_debug_names: std.ArrayList(Ast.ProcDebugName),
    roots: std.ArrayList(DraftRoot),
    layout_requests: std.ArrayList(DraftLayoutRequest),
    runtime_schema_requests: std.ArrayList(DraftRuntimeSchemaRequest),
    comptime_sites: std.ArrayList(DraftComptimeSite),
    branch_regions: std.ArrayList(base.Region),
    source_files: std.ArrayList(DraftSpan(u8)),
    source_file_ids: std.AutoHashMap(u32, u32),
    local_names: std.ArrayList(DraftSpan(u8)),
    source_text_bytes: std.ArrayList(u8),
    expr_locs: std.ArrayList(base.SourceLoc),
    expr_regions: std.ArrayList(base.Region),
    stmt_locs: std.ArrayList(base.SourceLoc),
    stmt_regions: std.ArrayList(base.Region),
    current_owner: DraftOwner,
    owner_starts: DraftCoreLengths,
    owner_runs: std.ArrayList(DraftOwnerRun),
    /// Closed static-data candidates are shared by child lowering contexts
    /// only within the body that owns their explicit runtime expression.
    static_data_candidate_exprs: std.AutoHashMap(StaticDataCandidateAddress, DraftExprId),

    fn init(allocator: Allocator) BodyDraftStore {
        return .{
            .allocator = allocator,
            .fns = .empty,
            .defs = .empty,
            .def_owners = .empty,
            .nested_defs = .empty,
            .template_specs = .empty,
            .template_spec_by_fn = collections.DenseMap(DraftFnId, u32).init(allocator),
            .template_spec_lookup = std.AutoHashMap(DraftTemplateLookupAddress, std.ArrayList(u32)).init(allocator),
            .closed_direct_specializations = std.AutoHashMap(ClosedDirectCallIdentity, ClosedDirectDraftSpecialization).init(allocator),
            .active_callable_eval_bindings = .empty,
            .active_const_node_bindings = .empty,
            .active_const_node_binding_indices = std.AutoHashMap(ActiveConstNodeAddress, u32).init(allocator),
            .materialized_const_nodes = .empty,
            .materialized_const_node_indices = std.AutoHashMap(MaterializedConstNodeAddress, u32).init(allocator),
            .active_const_bindings = .empty,
            .deferred_const_uses = .empty,
            .deferred_structural_eqs = .empty,
            .deferred_structural_serializations = .empty,
            .deferred_callsite_intrinsics = .empty,
            .prepared_codec_calls = .empty,
            .local_proc_contexts = .empty,
            .deferred_inspects = .empty,
            .prepared_inspect_methods = .empty,
            .structural_eq_method_calls = .empty,
            .runtime_value_demands = .empty,
            .runtime_demand_guard_frames = .empty,
            .template_spec_reuses = .empty,
            .nested_spec_reuses = .empty,
            .impossibility_proofs = .empty,
            .impossibility_proof_ids = .empty,
            .expr_impossibility_proofs = .empty,
            .pat_impossibility_proofs = .empty,
            .stmt_impossibility_proofs = .empty,
            .nested_specs = .empty,
            .nested_spec_lookup = std.AutoHashMap(DraftNestedLookupAddress, std.ArrayList(u32)).init(allocator),
            .exprs = .empty,
            .pats = .empty,
            .stmts = .empty,
            .locals = .empty,
            .expr_ids = .empty,
            .pat_ids = .empty,
            .typed_locals = .empty,
            .stmt_ids = .empty,
            .field_exprs = .empty,
            .field_access_segments = .empty,
            .fn_def_captures = .empty,
            .record_destructs = .empty,
            .str_pattern_steps = .empty,
            .declared_fields = .empty,
            .branches = .empty,
            .if_branches = .empty,
            .string_literals = .empty,
            .string_bytes = .empty,
            .checked_string_literals = std.AutoHashMap(CheckedStringLiteralAddress, DraftStringLiteralId).init(allocator),
            .proc_debug_names = .empty,
            .roots = .empty,
            .layout_requests = .empty,
            .runtime_schema_requests = .empty,
            .comptime_sites = .empty,
            .branch_regions = .empty,
            .source_files = .empty,
            .source_file_ids = std.AutoHashMap(u32, u32).init(allocator),
            .local_names = .empty,
            .source_text_bytes = .empty,
            .expr_locs = .empty,
            .expr_regions = .empty,
            .stmt_locs = .empty,
            .stmt_regions = .empty,
            .current_owner = .root,
            .owner_starts = @splat(0),
            .owner_runs = .empty,
            .static_data_candidate_exprs = std.AutoHashMap(StaticDataCandidateAddress, DraftExprId).init(allocator),
        };
    }

    fn deinit(self: *BodyDraftStore) void {
        for (self.template_specs.items) |spec| {
            if (spec.lexical) |lexical| {
                self.allocator.free(lexical.binders);
                self.allocator.free(lexical.local_procs);
            }
        }
        for (self.deferred_const_uses.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_structural_eqs.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_structural_serializations.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_callsite_intrinsics.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.deferred_inspects.items) |boundary| {
            self.allocator.free(boundary.lexical.binders);
            self.allocator.free(boundary.lexical.local_procs);
        }
        for (self.local_proc_contexts.items) |context| self.allocator.free(context.entries);
        self.local_proc_contexts.deinit(self.allocator);
        var template_lookup_lists = self.template_spec_lookup.valueIterator();
        while (template_lookup_lists.next()) |list| list.deinit(self.allocator);
        self.template_spec_lookup.deinit();
        self.closed_direct_specializations.deinit();
        self.template_spec_by_fn.deinit();
        var nested_lookup_lists = self.nested_spec_lookup.valueIterator();
        while (nested_lookup_lists.next()) |list| list.deinit(self.allocator);
        self.nested_spec_lookup.deinit();
        self.owner_runs.deinit(self.allocator);
        self.stmt_impossibility_proofs.deinit(self.allocator);
        self.pat_impossibility_proofs.deinit(self.allocator);
        self.expr_impossibility_proofs.deinit(self.allocator);
        self.impossibility_proof_ids.deinit(self.allocator);
        self.impossibility_proofs.deinit(self.allocator);
        self.static_data_candidate_exprs.deinit();
        self.stmt_regions.deinit(self.allocator);
        self.stmt_locs.deinit(self.allocator);
        self.expr_regions.deinit(self.allocator);
        self.expr_locs.deinit(self.allocator);
        self.source_text_bytes.deinit(self.allocator);
        self.local_names.deinit(self.allocator);
        self.source_file_ids.deinit();
        self.source_files.deinit(self.allocator);
        self.branch_regions.deinit(self.allocator);
        self.comptime_sites.deinit(self.allocator);
        self.runtime_schema_requests.deinit(self.allocator);
        self.layout_requests.deinit(self.allocator);
        self.roots.deinit(self.allocator);
        self.proc_debug_names.deinit(self.allocator);
        self.runtime_value_demands.deinit(self.allocator);
        self.runtime_demand_guard_frames.deinit(self.allocator);
        self.template_spec_reuses.deinit(self.allocator);
        self.nested_spec_reuses.deinit(self.allocator);
        self.structural_eq_method_calls.deinit(self.allocator);
        self.prepared_inspect_methods.deinit(self.allocator);
        self.deferred_inspects.deinit(self.allocator);
        self.deferred_structural_serializations.deinit(self.allocator);
        self.deferred_callsite_intrinsics.deinit(self.allocator);
        self.prepared_codec_calls.deinit(self.allocator);
        self.deferred_structural_eqs.deinit(self.allocator);
        self.deferred_const_uses.deinit(self.allocator);
        self.active_callable_eval_bindings.deinit(self.allocator);
        self.active_const_node_bindings.deinit(self.allocator);
        self.active_const_node_binding_indices.deinit();
        self.materialized_const_nodes.deinit(self.allocator);
        self.materialized_const_node_indices.deinit();
        self.active_const_bindings.deinit(self.allocator);
        self.checked_string_literals.deinit();
        self.string_bytes.deinit(self.allocator);
        self.string_literals.deinit(self.allocator);
        self.if_branches.deinit(self.allocator);
        self.branches.deinit(self.allocator);
        self.declared_fields.deinit(self.allocator);
        self.str_pattern_steps.deinit(self.allocator);
        self.record_destructs.deinit(self.allocator);
        self.fn_def_captures.deinit(self.allocator);
        self.field_access_segments.deinit(self.allocator);
        self.field_exprs.deinit(self.allocator);
        self.stmt_ids.deinit(self.allocator);
        self.typed_locals.deinit(self.allocator);
        self.pat_ids.deinit(self.allocator);
        self.expr_ids.deinit(self.allocator);
        self.locals.deinit(self.allocator);
        self.stmts.deinit(self.allocator);
        self.pats.deinit(self.allocator);
        self.exprs.deinit(self.allocator);
        self.nested_defs.deinit(self.allocator);
        self.template_specs.deinit(self.allocator);
        self.nested_specs.deinit(self.allocator);
        self.def_owners.deinit(self.allocator);
        self.defs.deinit(self.allocator);
        self.fns.deinit(self.allocator);
    }

    const OwnerScope = struct {
        draft: *BodyDraftStore,
        previous: DraftOwner,

        fn leave(self: OwnerScope) void {
            self.draft.switchOwner(self.previous) catch |err| switch (err) {
                error.OutOfMemory => Common.invariant("restoring body draft owner could not record its completed ownership run"),
            };
        }
    };

    fn enterOwner(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!OwnerScope {
        const previous = self.current_owner;
        try self.switchOwner(owner);
        return .{ .draft = self, .previous = previous };
    }

    fn switchOwner(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!void {
        if (std.meta.eql(self.current_owner, owner)) return;
        try self.closeOwnerRun();
        self.current_owner = owner;
        self.owner_starts = self.coreLengths();
    }

    fn finishOwnerRuns(self: *BodyDraftStore) Allocator.Error!void {
        try self.closeOwnerRun();
        self.owner_starts = self.coreLengths();
    }

    fn closeOwnerRun(self: *BodyDraftStore) Allocator.Error!void {
        const ends = self.coreLengths();
        if (std.mem.eql(u32, self.owner_starts[0..], ends[0..])) return;
        try self.owner_runs.append(self.allocator, .{
            .owner = self.current_owner,
            .starts = self.owner_starts,
            .ends = ends,
        });
    }

    fn coreLengths(self: *const BodyDraftStore) DraftCoreLengths {
        var lengths: DraftCoreLengths = undefined;
        lengths[@intFromEnum(DraftCoreKind.source_files)] = @intCast(self.source_files.items.len);
        lengths[@intFromEnum(DraftCoreKind.string_literals)] = @intCast(self.string_literals.items.len);
        lengths[@intFromEnum(DraftCoreKind.comptime_sites)] = @intCast(self.comptime_sites.items.len);
        lengths[@intFromEnum(DraftCoreKind.branch_regions)] = @intCast(self.branch_regions.items.len);
        lengths[@intFromEnum(DraftCoreKind.expr_ids)] = @intCast(self.expr_ids.items.len);
        lengths[@intFromEnum(DraftCoreKind.pat_ids)] = @intCast(self.pat_ids.items.len);
        lengths[@intFromEnum(DraftCoreKind.stmt_ids)] = @intCast(self.stmt_ids.items.len);
        lengths[@intFromEnum(DraftCoreKind.field_exprs)] = @intCast(self.field_exprs.items.len);
        lengths[@intFromEnum(DraftCoreKind.fn_def_captures)] = @intCast(self.fn_def_captures.items.len);
        lengths[@intFromEnum(DraftCoreKind.record_destructs)] = @intCast(self.record_destructs.items.len);
        lengths[@intFromEnum(DraftCoreKind.str_pattern_steps)] = @intCast(self.str_pattern_steps.items.len);
        lengths[@intFromEnum(DraftCoreKind.branches)] = @intCast(self.branches.items.len);
        lengths[@intFromEnum(DraftCoreKind.if_branches)] = @intCast(self.if_branches.items.len);
        lengths[@intFromEnum(DraftCoreKind.locals)] = @intCast(self.locals.items.len);
        lengths[@intFromEnum(DraftCoreKind.typed_locals)] = @intCast(self.typed_locals.items.len);
        lengths[@intFromEnum(DraftCoreKind.pats)] = @intCast(self.pats.items.len);
        lengths[@intFromEnum(DraftCoreKind.exprs)] = @intCast(self.exprs.items.len);
        lengths[@intFromEnum(DraftCoreKind.stmts)] = @intCast(self.stmts.items.len);
        lengths[@intFromEnum(DraftCoreKind.proc_debug_names)] = @intCast(self.proc_debug_names.items.len);
        lengths[@intFromEnum(DraftCoreKind.roots)] = @intCast(self.roots.items.len);
        lengths[@intFromEnum(DraftCoreKind.layout_requests)] = @intCast(self.layout_requests.items.len);
        lengths[@intFromEnum(DraftCoreKind.runtime_schema_requests)] = @intCast(self.runtime_schema_requests.items.len);
        return lengths;
    }

    fn ownerForCore(self: *const BodyDraftStore, kind: DraftCoreKind, index: usize) DraftOwner {
        const raw_kind = @intFromEnum(kind);
        for (self.owner_runs.items) |owner_run| {
            if (index >= owner_run.starts[raw_kind] and index < owner_run.ends[raw_kind]) return owner_run.owner;
        }
        Common.invariant("body draft core item had no explicit owner");
    }

    fn currentOwnerOwnsCore(self: *const BodyDraftStore, kind: DraftCoreKind, index: usize) bool {
        const raw_kind = @intFromEnum(kind);
        if (index >= self.owner_starts[raw_kind]) return true;
        return std.meta.eql(self.ownerForCore(kind, index), self.current_owner);
    }

    fn addExpr(self: *BodyDraftStore, expr: DraftExpr) Allocator.Error!DraftExprId {
        const id: DraftExprId = @enumFromInt(@as(u32, @intCast(self.exprs.items.len)));
        try self.exprs.append(self.allocator, expr);
        try self.expr_impossibility_proofs.append(self.allocator, null);
        try self.expr_locs.append(self.allocator, base.SourceLoc.none);
        try self.expr_regions.append(self.allocator, base.Region.zero());
        return id;
    }

    fn addExprWithSource(
        self: *BodyDraftStore,
        expr: DraftExpr,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!DraftExprId {
        const id = try self.addExpr(expr);
        self.expr_locs.items[@intFromEnum(id)] = loc;
        self.expr_regions.items[@intFromEnum(id)] = region;
        return id;
    }

    fn addFn(self: *BodyDraftStore, fn_: DraftFn) Allocator.Error!DraftFnId {
        const id: DraftFnId = @enumFromInt(@as(u32, @intCast(self.fns.items.len)));
        var stored = fn_;
        stored.parent_owner = self.current_owner;
        try self.fns.append(self.allocator, stored);
        return id;
    }

    /// Return whether `owner` is currently lowering inside `ancestor`'s body.
    /// Draft function parents are recorded at creation, so a partial interface
    /// match can only be classified as recursion through an explicit active
    /// ownership path rather than inferred from shared type-graph cells.
    fn ownerDescendsFromDraftFn(self: *const BodyDraftStore, owner: DraftOwner, ancestor: DraftFnId) bool {
        var cursor = owner;
        var remaining = self.fns.items.len + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (cursor) {
                .root, .reserved_fn => return false,
                .draft_fn => |fn_id| {
                    if (fn_id == ancestor) return true;
                    const raw = @intFromEnum(fn_id);
                    if (raw >= self.fns.items.len) {
                        Common.invariant("draft owner ancestry referenced an unknown function");
                    }
                    cursor = self.fns.items[raw].parent_owner;
                },
            }
        }
        Common.invariant("draft function ownership ancestry contained a cycle");
    }

    /// Return whether `owner` is lowering inside a globally reserved root.
    /// Draft children retain their parent owner, so mutually recursive paths
    /// through local procedures remain explicit rather than being inferred
    /// from coincidentally shared graph cells.
    fn ownerDescendsFromReservedFn(self: *const BodyDraftStore, owner: DraftOwner, ancestor: Ast.FnId) bool {
        var cursor = owner;
        var remaining = self.fns.items.len + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (cursor) {
                .root => return false,
                .reserved_fn => |fn_id| return fn_id == ancestor,
                .draft_fn => |fn_id| {
                    const raw = @intFromEnum(fn_id);
                    if (raw >= self.fns.items.len) {
                        Common.invariant("draft owner ancestry referenced an unknown function");
                    }
                    cursor = self.fns.items[raw].parent_owner;
                },
            }
        }
        Common.invariant("draft function ownership ancestry contained a cycle");
    }

    fn reserveDef(self: *BodyDraftStore, owner: DraftOwner) Allocator.Error!DraftDefId {
        const id: DraftDefId = @enumFromInt(@as(u32, @intCast(self.defs.items.len)));
        try self.defs.append(self.allocator, undefined);
        errdefer _ = self.defs.pop();
        try self.def_owners.append(self.allocator, owner);
        return id;
    }

    fn setDef(self: *BodyDraftStore, id: DraftDefId, def: DraftDef) void {
        const owner = self.def_owners.items[@intFromEnum(id)];
        if (def.fn_id) |fn_id| switch (fn_id) {
            .draft => |draft_fn| if (!std.meta.eql(owner, DraftOwner{ .draft_fn = draft_fn })) {
                Common.invariant("draft definition target disagreed with its explicit owner");
            },
            .final => |final_fn| if (!std.meta.eql(owner, DraftOwner{ .reserved_fn = final_fn })) {
                Common.invariant("final definition target disagreed with its explicit owner");
            },
        };
        self.defs.items[@intFromEnum(id)] = def;
    }

    fn addNestedDef(self: *BodyDraftStore, def: DraftNestedDef) Allocator.Error!DraftNestedDefId {
        const id: DraftNestedDefId = @enumFromInt(@as(u32, @intCast(self.nested_defs.items.len)));
        try self.nested_defs.append(self.allocator, def);
        return id;
    }

    fn addPat(self: *BodyDraftStore, pat: DraftPat) Allocator.Error!DraftPatId {
        const id: DraftPatId = @enumFromInt(@as(u32, @intCast(self.pats.items.len)));
        try self.pats.append(self.allocator, pat);
        try self.pat_impossibility_proofs.append(self.allocator, null);
        return id;
    }

    fn addStmt(self: *BodyDraftStore, stmt: DraftStmt) Allocator.Error!DraftStmtId {
        const id: DraftStmtId = @enumFromInt(@as(u32, @intCast(self.stmts.items.len)));
        try self.stmts.append(self.allocator, stmt);
        try self.stmt_impossibility_proofs.append(self.allocator, null);
        try self.stmt_locs.append(self.allocator, base.SourceLoc.none);
        try self.stmt_regions.append(self.allocator, base.Region.zero());
        return id;
    }

    fn addStmtWithSource(
        self: *BodyDraftStore,
        stmt: DraftStmt,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!DraftStmtId {
        const id = try self.addStmt(stmt);
        self.stmt_locs.items[@intFromEnum(id)] = loc;
        self.stmt_regions.items[@intFromEnum(id)] = region;
        return id;
    }

    fn addLocal(
        self: *BodyDraftStore,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: ?checked.PatternBinderId,
        inherited_capture_id: ?checked.CaptureId,
    ) Allocator.Error!DraftLocalId {
        const id: DraftLocalId = @enumFromInt(@as(u32, @intCast(self.locals.items.len)));
        const checked_capture_id = if (binder) |b| checked.CaptureId.fromBinder(b) else null;
        const capture_id = if (binder != null) blk: {
            if (inherited_capture_id) |inherited| break :blk inherited;
            const index = @intFromEnum(id);
            if (index > checked.CaptureId.max_generated_index) {
                Common.invariant("Monotype body had too many locals for provisional capture identity");
            }
            break :blk checked.CaptureId.generatedLift(index);
        } else null;
        try self.locals.append(self.allocator, .{
            .id = id,
            .symbol = symbol,
            .ty = ty,
            .binder = binder,
            .capture_id = capture_id,
            .checked_capture_id = checked_capture_id,
        });
        try self.local_names.append(self.allocator, .empty());
        return id;
    }

    fn addExprSpan(self: *BodyDraftStore, ids: []const DraftExprId) Allocator.Error!DraftSpan(DraftExprId) {
        const start: u32 = @intCast(self.expr_ids.items.len);
        try self.expr_ids.appendSlice(self.allocator, ids);
        return .{ .start = start, .len = @intCast(ids.len) };
    }

    const ReservedExprSpan = struct {
        span: DraftSpan(DraftExprId),
    };

    /// Reserve the final flat-pool range so callers can lower directly into
    /// its destination instead of allocating a temporary slice and copying it.
    fn reserveExprSpan(self: *BodyDraftStore, len: usize) Allocator.Error!ReservedExprSpan {
        const start: u32 = @intCast(self.expr_ids.items.len);
        _ = try self.expr_ids.addManyAsSlice(self.allocator, len);
        return .{
            .span = .{ .start = start, .len = @intCast(len) },
        };
    }

    fn setReservedExprSpanItem(
        self: *BodyDraftStore,
        reserved: ReservedExprSpan,
        index: usize,
        expr: DraftExprId,
    ) void {
        if (index >= reserved.span.len) Common.invariant("reserved expression span write was out of bounds");
        self.expr_ids.items[reserved.span.start + index] = expr;
    }

    fn addPatSpan(self: *BodyDraftStore, ids: []const DraftPatId) Allocator.Error!DraftSpan(DraftPatId) {
        const start: u32 = @intCast(self.pat_ids.items.len);
        try self.pat_ids.appendSlice(self.allocator, ids);
        return .{ .start = start, .len = @intCast(ids.len) };
    }

    fn addTypedLocalSpan(self: *BodyDraftStore, values: []const DraftTypedLocal) Allocator.Error!DraftSpan(DraftTypedLocal) {
        const start: u32 = @intCast(self.typed_locals.items.len);
        try self.typed_locals.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addStmtSpan(self: *BodyDraftStore, ids: []const DraftStmtId) Allocator.Error!DraftSpan(DraftStmtId) {
        const start: u32 = @intCast(self.stmt_ids.items.len);
        try self.stmt_ids.appendSlice(self.allocator, ids);
        return .{ .start = start, .len = @intCast(ids.len) };
    }

    fn addFieldExprSpan(self: *BodyDraftStore, values: []const DraftFieldExpr) Allocator.Error!DraftSpan(DraftFieldExpr) {
        const start: u32 = @intCast(self.field_exprs.items.len);
        try self.field_exprs.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addFieldAccessSegmentSpan(
        self: *BodyDraftStore,
        values: []const DraftFieldAccessSegment,
    ) Allocator.Error!DraftSpan(DraftFieldAccessSegment) {
        if (values.len == 0) Common.invariant("draft field access segment span must be nonempty");
        const start: u32 = @intCast(self.field_access_segments.items.len);
        try self.field_access_segments.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addFnDefCaptureSpan(self: *BodyDraftStore, values: []const DraftFnDefCapture) Allocator.Error!DraftSpan(DraftFnDefCapture) {
        const start: u32 = @intCast(self.fn_def_captures.items.len);
        try self.fn_def_captures.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addRecordDestructSpan(self: *BodyDraftStore, values: []const DraftRecordDestruct) Allocator.Error!DraftSpan(DraftRecordDestruct) {
        const start: u32 = @intCast(self.record_destructs.items.len);
        try self.record_destructs.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addBranchSpan(self: *BodyDraftStore, values: []const DraftBranch) Allocator.Error!DraftSpan(DraftBranch) {
        const start: u32 = @intCast(self.branches.items.len);
        try self.branches.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addIfBranchSpan(self: *BodyDraftStore, values: []const DraftIfBranch) Allocator.Error!DraftSpan(DraftIfBranch) {
        const start: u32 = @intCast(self.if_branches.items.len);
        try self.if_branches.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addStrPatternStepSpan(self: *BodyDraftStore, values: []const DraftStrPatternStep) Allocator.Error!DraftSpan(DraftStrPatternStep) {
        const start: u32 = @intCast(self.str_pattern_steps.items.len);
        try self.str_pattern_steps.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addDeclaredFieldSpan(self: *BodyDraftStore, values: []const DraftDeclaredField) Allocator.Error!DraftSpan(DraftDeclaredField) {
        const start: u32 = @intCast(self.declared_fields.items.len);
        try self.declared_fields.appendSlice(self.allocator, values);
        return .{ .start = start, .len = @intCast(values.len) };
    }

    fn addStringBytes(self: *BodyDraftStore, bytes: []const u8) Allocator.Error!DraftSpan(u8) {
        const start: u32 = @intCast(self.string_bytes.items.len);
        try self.string_bytes.appendSlice(self.allocator, bytes);
        return .{ .start = start, .len = @intCast(bytes.len) };
    }

    fn addStringLiteral(self: *BodyDraftStore, text: []const u8) Allocator.Error!DraftStringLiteralId {
        return try self.addStringView(text, 0, @intCast(text.len));
    }

    fn addCheckedStringLiteral(
        self: *BodyDraftStore,
        checked_module_bytes: [32]u8,
        literal: checked.CheckedStringLiteralId,
        text: []const u8,
    ) Allocator.Error!DraftStringLiteralId {
        const address: CheckedStringLiteralAddress = .{
            .module_bytes = checked_module_bytes,
            .literal = literal,
            .owner = self.current_owner,
        };
        if (self.checked_string_literals.get(address)) |existing| return existing;
        const lowered = try self.addStringLiteral(text);
        try self.checked_string_literals.put(address, lowered);
        return lowered;
    }

    fn addStringView(self: *BodyDraftStore, backing: []const u8, offset: u32, len: u32) Allocator.Error!DraftStringLiteralId {
        const offset_usize: usize = offset;
        const len_usize: usize = len;
        if (offset_usize > backing.len or len_usize > backing.len - offset_usize) {
            Common.invariant("body draft string literal view exceeded backing bytes");
        }
        const id: DraftStringLiteralId = @enumFromInt(@as(u32, @intCast(self.string_literals.items.len)));
        const backing_span = try self.addStringBytes(backing);
        try self.string_literals.append(self.allocator, .{
            .backing = backing_span,
            .offset = offset,
            .len = len,
        });
        return id;
    }

    fn addBranchRegionSpan(self: *BodyDraftStore, regions: []const base.Region) Allocator.Error!DraftSpan(base.Region) {
        const start: u32 = @intCast(self.branch_regions.items.len);
        try self.branch_regions.appendSlice(self.allocator, regions);
        return .{ .start = start, .len = @intCast(regions.len) };
    }

    fn addComptimeSite(
        self: *BodyDraftStore,
        kind: Ast.ComptimeSiteKind,
        region: base.Region,
        checked_site: ?checked.CheckedExhaustivenessSiteId,
        branch_regions: []const base.Region,
    ) Allocator.Error!DraftComptimeSiteId {
        const id: DraftComptimeSiteId = @enumFromInt(@as(u32, @intCast(self.comptime_sites.items.len)));
        const branch_region_span = try self.addBranchRegionSpan(branch_regions);
        try self.comptime_sites.append(self.allocator, .{
            .kind = kind,
            .region = region,
            .checked_site = checked_site,
            .branch_regions = branch_region_span,
        });
        return id;
    }

    fn addSourceText(self: *BodyDraftStore, text: []const u8) Allocator.Error!DraftSpan(u8) {
        const start: u32 = @intCast(self.source_text_bytes.items.len);
        try self.source_text_bytes.appendSlice(self.allocator, text);
        return .{ .start = start, .len = @intCast(text.len) };
    }

    fn addSourceFile(self: *BodyDraftStore, name: []const u8) Allocator.Error!u32 {
        const id: u32 = @intCast(self.source_files.items.len);
        const text = try self.addSourceText(name);
        try self.source_files.append(self.allocator, text);
        return id;
    }

    fn sourceFileIdFor(self: *BodyDraftStore, module_idx: u32, name: []const u8) Allocator.Error!u32 {
        const gop = try self.source_file_ids.getOrPut(module_idx);
        if (!gop.found_existing) {
            gop.value_ptr.* = try self.addSourceFile(name);
        }
        return gop.value_ptr.*;
    }

    fn setLocalName(self: *BodyDraftStore, id: DraftLocalId, name: []const u8) Allocator.Error!void {
        if (name.len == 0) return;
        self.local_names.items[@intFromEnum(id)] = try self.addSourceText(name);
    }

    fn setLocalCaptureId(self: *BodyDraftStore, id: DraftLocalId, capture_id: u32) void {
        const checked_id = checked.CaptureId.generatedCheck(capture_id);
        self.locals.items[@intFromEnum(id)].capture_id = checked_id;
        self.locals.items[@intFromEnum(id)].checked_capture_id = checked_id;
    }

    fn setLocalType(self: *BodyDraftStore, id: DraftLocalId, ty: DraftTypeCell) void {
        self.locals.items[@intFromEnum(id)].ty = ty;
        for (self.typed_locals.items) |*typed_local| {
            if (typed_local.local == id) {
                typed_local.ty = ty;
            }
        }
    }

    fn finalIdOffsets(program: *const Ast.Program) FinalIdOffsets {
        return .{
            .fn_start = @intCast(program.fnCount()),
            .def_start = @intCast(program.defCount()),
            .nested_def_start = @intCast(program.nestedDefCount()),
            .expr_start = @intCast(program.exprCount()),
            .pat_start = @intCast(program.patCount()),
            .stmt_start = @intCast(program.stmtCount()),
            .local_start = @intCast(program.localCount()),
            .string_literal_start = @intCast(program.stringLiteralCount()),
            .comptime_site_start = @intCast(program.comptimeSiteCount()),
            .expr_ids_start = @intCast(program.exprIdCount()),
            .pat_ids_start = @intCast(program.patIdCount()),
            .typed_locals_start = @intCast(program.typedLocalCount()),
            .stmt_ids_start = @intCast(program.stmtIdCount()),
            .field_expr_start = @intCast(program.fieldExprCount()),
            .field_access_segment_start = @intCast(program.fieldAccessSegmentCount()),
            .fn_def_capture_start = @intCast(program.fnDefCaptureCount()),
            .record_destruct_start = @intCast(program.recordDestructCount()),
            .str_pattern_step_start = @intCast(program.strPatternStepCount()),
            .branch_start = @intCast(program.branchCount()),
            .if_branch_start = @intCast(program.ifBranchCount()),
            .source_file_start = @intCast(program.sourceFileCount()),
            .core_id_mode = .identity,
        };
    }

    fn sealCoreIntoProgram(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!void {
        return try self.sealCoreIntoProgramWithMap(
            program,
            graph,
            sealer,
            BodyDraftStore.finalIdOffsets(program),
            null,
            null,
            null,
        );
    }

    fn sealCoreIntoProgramWithMap(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        ids: FinalIdOffsets,
        emit_fns: ?[]const bool,
        emit_defs: ?[]const bool,
        emit_nested_defs: ?[]const bool,
    ) Allocator.Error!void {
        for (self.source_files.items, 0..) |span, index| {
            if (!ids.retained(.source_files, index)) continue;
            _ = try program.addSourceFile(self.sourceText(span));
        }

        for (self.string_literals.items, 0..) |literal, index| {
            if (!ids.retained(.string_literals, index)) continue;
            const id = try program.addStringView(self.stringBytes(literal.backing), literal.offset, literal.len);
            if (@intFromEnum(id) != ids.core(.string_literals, @intCast(index), ids.string_literal_start)) {
                Common.invariant("Monotype body draft string literal id did not append contiguously");
            }
        }

        for (self.comptime_sites.items, 0..) |site, index| {
            if (!ids.retained(.comptime_sites, index)) continue;
            const id = try program.addComptimeSite(site.kind, site.region, site.checked_site, self.branchRegions(site.branch_regions));
            if (@intFromEnum(id) != ids.core(.comptime_sites, @intCast(index), ids.comptime_site_start)) {
                Common.invariant("Monotype body draft compile-time site id did not append contiguously");
            }
        }

        try program.expr_ids.ensureUnusedCapacity(program.allocator, self.expr_ids.items.len);
        for (self.expr_ids.items, 0..) |id, index| if (ids.retained(.expr_ids, index)) program.expr_ids.appendAssumeCapacity(ids.expr(id));

        try program.pat_ids.ensureUnusedCapacity(program.allocator, self.pat_ids.items.len);
        for (self.pat_ids.items, 0..) |id, index| if (ids.retained(.pat_ids, index)) program.pat_ids.appendAssumeCapacity(ids.pat(id));

        try program.stmt_ids.ensureUnusedCapacity(program.allocator, self.stmt_ids.items.len);
        for (self.stmt_ids.items, 0..) |id, index| if (ids.retained(.stmt_ids, index)) program.stmt_ids.appendAssumeCapacity(ids.stmt(id));

        try program.field_exprs.ensureUnusedCapacity(program.allocator, self.field_exprs.items.len);
        for (self.field_exprs.items, 0..) |field, index| {
            if (!ids.retained(.field_exprs, index)) continue;
            program.field_exprs.appendAssumeCapacity(.{
                .name = field.name,
                .value = ids.expr(field.value),
            });
        }

        try program.field_access_segments.ensureUnusedCapacity(program.allocator, self.field_access_segments.items.len);
        for (self.field_access_segments.items) |segment| {
            program.field_access_segments.appendAssumeCapacity(.{ .field = segment.field });
        }

        try program.fn_def_captures.ensureUnusedCapacity(program.allocator, self.fn_def_captures.items.len);
        for (self.fn_def_captures.items, 0..) |capture, index| {
            if (!ids.retained(.fn_def_captures, index)) continue;
            if (!ids.retained(.locals, @intFromEnum(capture.local))) {
                std.debug.panic(
                    "postcheck invariant violated: retained function capture owned by {any} referenced local owned by {any}",
                    .{ self.ownerForCore(.fn_def_captures, index), self.ownerForCore(.locals, @intFromEnum(capture.local)) },
                );
            }
            program.fn_def_captures.appendAssumeCapacity(.{
                .local = ids.local(capture.local),
                .value = ids.expr(capture.value),
            });
        }

        try program.record_destructs.ensureUnusedCapacity(program.allocator, self.record_destructs.items.len);
        for (self.record_destructs.items, 0..) |field, index| {
            if (!ids.retained(.record_destructs, index)) continue;
            program.record_destructs.appendAssumeCapacity(.{
                .name = field.name,
                .pattern = ids.pat(field.pattern),
            });
        }

        try program.str_pattern_steps.ensureUnusedCapacity(program.allocator, self.str_pattern_steps.items.len);
        for (self.str_pattern_steps.items, 0..) |step, index| {
            if (!ids.retained(.str_pattern_steps, index)) continue;
            program.str_pattern_steps.appendAssumeCapacity(.{
                .capture = if (step.capture) |capture| ids.pat(capture) else null,
                .delimiter = ids.stringLiteral(step.delimiter),
            });
        }

        try program.branches.ensureUnusedCapacity(program.allocator, self.branches.items.len);
        for (self.branches.items, 0..) |branch, index| {
            if (!ids.retained(.branches, index)) continue;
            program.branches.appendAssumeCapacity(.{
                .pat = ids.pat(branch.pat),
                .bindings = ids.stmtSpan(branch.bindings),
                .guard = if (branch.guard) |guard| ids.expr(guard) else null,
                .body = ids.expr(branch.body),
            });
        }

        try program.if_branches.ensureUnusedCapacity(program.allocator, self.if_branches.items.len);
        for (self.if_branches.items, 0..) |branch, index| {
            if (!ids.retained(.if_branches, index)) continue;
            program.if_branches.appendAssumeCapacity(.{
                .cond = ids.expr(branch.cond),
                .body = ids.expr(branch.body),
            });
        }

        try program.locals.ensureUnusedCapacity(program.allocator, self.locals.items.len);
        try program.local_names.ensureUnusedCapacity(program.allocator, self.locals.items.len);
        // This commit is one Monotype materialization. Checked capture
        // identities identify aliases within it, while separate commits get
        // separate durable ids even when they instantiate the same binder.
        var durable_capture_ids = collections.DenseMap(checked.CaptureId, checked.CaptureId).init(program.allocator);
        defer durable_capture_ids.deinit();
        for (self.locals.items, 0..) |local, index| {
            if (!ids.retained(.locals, index)) continue;
            const expected = ids.local(@enumFromInt(@as(u32, @intCast(index))));
            const sealed_ty = try local.ty.seal(graph, sealer);
            const durable_capture_id = if (local.capture_id) |provisional| blk: {
                const final_index = @intFromEnum(expected);
                if (final_index > checked.CaptureId.max_generated_index) {
                    Common.invariant("Monotype program had too many locals for durable capture identity");
                }
                const entry = try durable_capture_ids.getOrPut(provisional);
                if (!entry.found_existing) entry.value_ptr.* = checked.CaptureId.generatedLift(final_index);
                break :blk entry.value_ptr.*;
            } else null;
            program.locals.appendAssumeCapacity(.{
                .id = expected,
                .symbol = local.symbol,
                .ty = sealed_ty,
                .binder = local.binder,
                .capture_id = durable_capture_id,
                .checked_capture_id = local.checked_capture_id,
            });
            const local_name = self.sourceText(self.local_names.items[index]);
            program.local_names.appendAssumeCapacity(if (local_name.len == 0) "" else try program.allocator.dupe(u8, local_name));
        }

        try program.typed_locals.ensureUnusedCapacity(program.allocator, self.typed_locals.items.len);
        for (self.typed_locals.items, 0..) |typed, index| {
            if (!ids.retained(.typed_locals, index)) continue;
            program.typed_locals.appendAssumeCapacity(.{
                .local = ids.local(typed.local),
                .ty = try typed.ty.seal(graph, sealer),
            });
        }

        try program.pats.ensureUnusedCapacity(program.allocator, self.pats.items.len);
        for (self.pats.items, 0..) |pat, index| {
            if (!ids.retained(.pats, index)) continue;
            program.pats.appendAssumeCapacity(.{
                .ty = try pat.ty.seal(graph, sealer),
                .data = BodyDraftStore.sealCorePatData(ids, pat.data),
            });
        }

        var retained_expr_count: usize = 0;
        for (self.exprs.items, 0..) |_, index| {
            if (ids.retained(.exprs, index)) retained_expr_count += 1;
        }
        const nominal_backing_expr_start: u32 = @intCast(program.exprCount() + retained_expr_count);
        var nominal_backing_exprs = std.ArrayList(PendingSealedExpr).empty;
        defer nominal_backing_exprs.deinit(program.allocator);

        try program.exprs.ensureUnusedCapacity(program.allocator, retained_expr_count);
        try program.expr_locs.ensureUnusedCapacity(program.allocator, retained_expr_count);
        try program.expr_regions.ensureUnusedCapacity(program.allocator, retained_expr_count);
        for (self.exprs.items, 0..) |expr, index| {
            if (!ids.retained(.exprs, index)) continue;
            const sealed_ty = try expr.ty.seal(graph, sealer);
            const sealed_data = try self.sealCoreExprData(program, ids, graph, sealer, expr.data);
            const loc = ids.sourceLoc(self.expr_locs.items[index]);
            const region = self.expr_regions.items[index];
            const sealed_expr = try BodyDraftStore.sealConstructorExprWithNominalBackings(
                program,
                &nominal_backing_exprs,
                nominal_backing_expr_start,
                sealed_ty,
                sealed_data,
                loc,
                region,
            );
            program.exprs.appendAssumeCapacity(.{
                .ty = sealed_expr.ty,
                .data = sealed_expr.data,
            });
            program.expr_locs.appendAssumeCapacity(loc);
            program.expr_regions.appendAssumeCapacity(region);
        }
        for (nominal_backing_exprs.items) |pending| {
            try program.exprs.append(program.allocator, pending.expr);
            try program.expr_locs.append(program.allocator, pending.loc);
            try program.expr_regions.append(program.allocator, pending.region);
        }

        try program.stmts.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        try program.stmt_locs.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        try program.stmt_regions.ensureUnusedCapacity(program.allocator, self.stmts.items.len);
        for (self.stmts.items, 0..) |stmt, index| {
            if (!ids.retained(.stmts, index)) continue;
            program.stmts.appendAssumeCapacity(try BodyDraftStore.sealCoreStmt(ids, graph, sealer, stmt));
            program.stmt_locs.appendAssumeCapacity(ids.sourceLoc(self.stmt_locs.items[index]));
            program.stmt_regions.appendAssumeCapacity(self.stmt_regions.items[index]);
        }

        try program.fns.ensureUnusedCapacity(program.allocator, self.fns.items.len);
        for (self.fns.items, 0..) |fn_, index| {
            if (emit_fns) |emit| if (!emit[index]) continue;
            program.fns.appendAssumeCapacity(.{
                .source = try BodyDraftStore.sealFnTemplate(graph, sealer, fn_.source),
                .signature_relation = fn_.signature_relation,
            });
        }

        try program.defs.ensureUnusedCapacity(program.allocator, self.defs.items.len);
        for (self.defs.items, 0..) |def, index| {
            if (emit_defs) |emit| if (!emit[index]) continue;
            const sealed_fn_def = if (def.fn_def) |template| try BodyDraftStore.sealFnTemplate(graph, sealer, template) else null;
            const sealed_fn_id = if (def.fn_id) |fn_id| ids.fnTarget(fn_id) else null;
            if (sealed_fn_def) |template| {
                if (sealed_fn_id) |fn_id| {
                    program.setFnSource(fn_id, template);
                }
            }
            program.defs.appendAssumeCapacity(.{
                .symbol = def.symbol,
                .fn_def = sealed_fn_def,
                .fn_id = sealed_fn_id,
                .args = ids.typedLocalSpan(def.args),
                .body = ids.fnBody(def.body),
                .ret = try def.ret.seal(graph, sealer),
            });
        }

        try program.nested_defs.ensureUnusedCapacity(program.allocator, self.nested_defs.items.len);
        for (self.nested_defs.items, 0..) |def, index| {
            if (emit_nested_defs) |emit| if (!emit[index]) continue;
            const sealed_fn_def = try BodyDraftStore.sealFnTemplate(graph, sealer, def.fn_def);
            const sealed_fn_id = ids.fnTarget(def.fn_id);
            program.setFnSource(sealed_fn_id, sealed_fn_def);
            program.nested_defs.appendAssumeCapacity(.{
                .symbol = def.symbol,
                .fn_def = sealed_fn_def,
                .fn_id = sealed_fn_id,
                .args = ids.typedLocalSpan(def.args),
                .body = ids.expr(def.body),
                .ret = try def.ret.seal(graph, sealer),
            });
        }

        for (self.proc_debug_names.items, 0..) |debug_name, index| {
            if (!ids.retained(.proc_debug_names, index)) continue;
            try program.setProcDebugName(debug_name.symbol, debug_name.name);
        }

        try program.roots.ensureUnusedCapacity(program.allocator, self.roots.items.len);
        for (self.roots.items, 0..) |root, index| {
            if (!ids.retained(.roots, index)) continue;
            program.roots.appendAssumeCapacity(.{
                .def = ids.def(root.def),
                .request = root.request,
            });
        }

        try program.layout_requests.ensureUnusedCapacity(program.allocator, self.layout_requests.items.len);
        for (self.layout_requests.items, 0..) |request, index| {
            if (!ids.retained(.layout_requests, index)) continue;
            program.layout_requests.appendAssumeCapacity(.{
                .checked_type = request.checked_type,
                .ty = try request.ty.seal(graph, sealer),
                .def = if (request.def) |def_id| ids.def(def_id) else null,
                .const_locator = request.const_locator,
            });
        }

        try program.runtime_schema_requests.ensureUnusedCapacity(program.allocator, self.runtime_schema_requests.items.len);
        for (self.runtime_schema_requests.items, 0..) |request, index| {
            if (!ids.retained(.runtime_schema_requests, index)) continue;
            program.runtime_schema_requests.appendAssumeCapacity(.{
                .def = request.def,
                .ty = try request.ty.seal(graph, sealer),
            });
        }
    }

    fn sourceText(self: *const BodyDraftStore, span: DraftSpan(u8)) []const u8 {
        if (span.start > self.source_text_bytes.items.len or span.len > self.source_text_bytes.items.len - span.start) {
            Common.invariant("Monotype body draft source text span was out of bounds");
        }
        return self.source_text_bytes.items[span.start..][0..span.len];
    }

    fn stringBytes(self: *const BodyDraftStore, span: DraftSpan(u8)) []const u8 {
        if (span.start > self.string_bytes.items.len or span.len > self.string_bytes.items.len - span.start) {
            Common.invariant("Monotype body draft string byte span was out of bounds");
        }
        return self.string_bytes.items[span.start..][0..span.len];
    }

    fn branchRegions(self: *const BodyDraftStore, span: DraftSpan(base.Region)) []const base.Region {
        if (span.start > self.branch_regions.items.len or span.len > self.branch_regions.items.len - span.start) {
            Common.invariant("Monotype body draft branch-region span was out of bounds");
        }
        return self.branch_regions.items[span.start..][0..span.len];
    }

    fn sealFnTemplate(
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        template: DraftFnTemplate,
    ) Allocator.Error!Ast.FnTemplate {
        return .{
            .fn_def = template.fn_def,
            .source_fn_ty = template.source_fn_ty,
            .source_fn_key = template.source_fn_key,
            .mono_fn_ty = try template.mono_fn_ty.seal(graph, sealer),
            .evidence_digest = template.evidence_digest,
            .const_evidence = template.const_evidence,
            .const_evidence_frames = template.const_evidence_frames,
            .const_evidence_frame_head = template.const_evidence_frame_head,
        };
    }

    fn sealCorePatData(ids: FinalIdOffsets, data: DraftPatData) Ast.PatData {
        return switch (data) {
            .bind => |local| .{ .bind = ids.local(local) },
            .wildcard => .wildcard,
            .as => |as| .{ .as = .{
                .pattern = ids.pat(as.pattern),
                .local = ids.local(as.local),
            } },
            .record => |span| .{ .record = ids.recordDestructSpan(span) },
            .tuple => |span| .{ .tuple = ids.patSpan(span) },
            .list => |list| .{ .list = .{
                .patterns = ids.patSpan(list.patterns),
                .rest = if (list.rest) |rest| .{
                    .index = rest.index,
                    .pattern = if (rest.pattern) |pattern| ids.pat(pattern) else null,
                } else null,
            } },
            .tag => |tag| .{ .tag = .{
                .name = tag.name,
                .payloads = ids.patSpan(tag.payloads),
            } },
            .nominal => |pat| .{ .nominal = ids.pat(pat) },
            .int_lit => |value| .{ .int_lit = value },
            .dec_lit => |value| .{ .dec_lit = value },
            .frac_f32_lit => |value| .{ .frac_f32_lit = value },
            .frac_f64_lit => |value| .{ .frac_f64_lit = value },
            .str_lit => |literal| .{ .str_lit = ids.stringLiteral(literal) },
            .str_pattern => |pattern| .{ .str_pattern = .{
                .prefix = ids.stringLiteral(pattern.prefix),
                .steps = ids.strPatternStepSpan(pattern.steps),
                .end = pattern.end,
            } },
        };
    }

    fn sealCoreReturn(ids: FinalIdOffsets, graph: *InstGraph, sealer: *GraphTypeFinals, ret: DraftReturn) Allocator.Error!Ast.Return {
        return .{
            .value = ids.expr(ret.value),
            .target = try ret.target.seal(graph, sealer),
        };
    }

    fn sealedNominalConstructionLayer(program: *const Ast.Program, ty: Type.TypeId) ?SealedNominalConstructionLayer {
        var current = ty;
        while (true) {
            switch (program.types.get(current)) {
                .named => |named| {
                    const backing = named.backing orelse return null;
                    switch (named.kind) {
                        .alias => current = backing.ty,
                        .nominal, .@"opaque" => return .{ .named = current, .backing = backing.ty },
                    }
                },
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
            }
        }
    }

    fn sealConstructorExprWithNominalBackings(
        program: *Ast.Program,
        pending: *std.ArrayList(PendingSealedExpr),
        pending_start: u32,
        ty: Type.TypeId,
        data: Ast.ExprData,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!Ast.Expr {
        return switch (data) {
            .tag, .record, .tuple => try BodyDraftStore.sealConstructorExprWithNominalBackingsInner(
                program,
                pending,
                pending_start,
                ty,
                data,
                loc,
                region,
            ),
            .local,
            .unit,
            .@"unreachable",
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .static_data_candidate,
            .list,
            .record_update,
            .nominal,
            .let_,
            .lambda,
            .def_ref,
            .fn_def,
            .fn_ref,
            .call_value,
            .call_proc,
            .low_level,
            .field_access,
            .tuple_access,
            .structural_eq,
            .structural_hash,
            .match_,
            .if_,
            .uninitialized,
            .uninitialized_payload,
            .if_initialized_payload,
            .try_sequence,
            .try_record_sequence,
            .block,
            .loop_,
            .break_,
            .continue_,
            .join_point,
            .jump,
            .return_,
            .crash,
            .comptime_branch_taken,
            .comptime_exhaustiveness_failed,
            .dbg,
            .expect_err,
            .expect,
            => .{ .ty = ty, .data = data },
        };
    }

    fn sealConstructorExprWithNominalBackingsInner(
        program: *Ast.Program,
        pending: *std.ArrayList(PendingSealedExpr),
        pending_start: u32,
        ty: Type.TypeId,
        data: Ast.ExprData,
        loc: base.SourceLoc,
        region: base.Region,
    ) Allocator.Error!Ast.Expr {
        const layer = BodyDraftStore.sealedNominalConstructionLayer(program, ty) orelse
            return .{ .ty = ty, .data = data };
        const backing_expr = try BodyDraftStore.sealConstructorExprWithNominalBackingsInner(
            program,
            pending,
            pending_start,
            layer.backing,
            data,
            loc,
            region,
        );
        const backing_id: Ast.ExprId = @enumFromInt(pending_start + @as(u32, @intCast(pending.items.len)));
        try pending.append(program.allocator, .{
            .expr = backing_expr,
            .loc = loc,
            .region = region,
        });
        return .{ .ty = layer.named, .data = .{ .nominal = backing_id } };
    }

    fn sealCallCaptureOperandSpan(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        ids: FinalIdOffsets,
        span: DraftSpan(DraftExprId),
    ) Allocator.Error!Ast.Span(Ast.CaptureOperand) {
        if (span.len == 0) return Ast.Span(Ast.CaptureOperand).empty();
        if (span.start > self.expr_ids.items.len or span.len > self.expr_ids.items.len - span.start) {
            Common.invariant("Monotype body draft call capture span was out of bounds");
        }

        const operands = try program.allocator.alloc(Ast.CaptureOperand, span.len);
        defer program.allocator.free(operands);

        for (self.expr_ids.items[span.start..][0..span.len], operands) |draft_value, *operand| {
            const raw_expr = @intFromEnum(draft_value);
            if (raw_expr >= self.exprs.items.len) {
                Common.invariant("Monotype direct-call capture referenced an unknown expression");
            }
            const draft_local = switch (self.exprs.items[raw_expr].data) {
                .local => |local| local,
                .unit,
                .pending_deferred,
                .@"unreachable",
                .int_lit,
                .frac_f32_lit,
                .frac_f64_lit,
                .dec_lit,
                .str_lit,
                .bytes_lit,
                .static_data_candidate,
                .list,
                .tuple,
                .record,
                .record_update,
                .tag,
                .nominal,
                .let_,
                .lambda,
                .def_ref,
                .fn_def,
                .fn_ref,
                .call_value,
                .call_proc,
                .low_level,
                .field_access,
                .tuple_access,
                .structural_eq,
                .structural_hash,
                .match_,
                .if_,
                .uninitialized,
                .uninitialized_payload,
                .if_initialized_payload,
                .try_sequence,
                .try_record_sequence,
                .block,
                .loop_,
                .break_,
                .continue_,
                .return_,
                .crash,
                .comptime_branch_taken,
                .comptime_exhaustiveness_failed,
                .dbg,
                .expect_err,
                .expect,
                => Common.invariant("Monotype direct-call capture operand was not a local expression"),
            };
            const local = program.getLocal(ids.local(draft_local));
            const id = local.checked_capture_id orelse local.capture_id orelse
                Common.invariant("Monotype direct-call capture local had no capture identity");
            operand.* = .{
                .id = id,
                .value = ids.expr(draft_value),
            };
        }

        return try program.addCaptureOperandSpan(operands);
    }

    fn sealCoreExprData(
        self: *const BodyDraftStore,
        program: *Ast.Program,
        ids: FinalIdOffsets,
        graph: *InstGraph,
        sealer: *GraphTypeFinals,
        data: DraftExprData,
    ) Allocator.Error!Ast.ExprData {
        return switch (data) {
            .local => |local| .{ .local = ids.local(local) },
            .unit => .unit,
            .int_lit => |value| .{ .int_lit = value },
            .frac_f32_lit => |value| .{ .frac_f32_lit = value },
            .frac_f64_lit => |value| .{ .frac_f64_lit = value },
            .dec_lit => |value| .{ .dec_lit = value },
            .str_lit => |literal| .{ .str_lit = ids.stringLiteral(literal) },
            .bytes_lit => |literal| .{ .bytes_lit = .{
                .literal = ids.stringLiteral(literal.literal),
                .len = literal.len,
                .element = literal.element,
            } },
            .static_data_candidate => |candidate| .{ .static_data_candidate = .{
                .static_data = candidate.static_data,
                .runtime_expr = ids.expr(candidate.runtime_expr),
            } },
            .list => |span| .{ .list = ids.exprSpan(span) },
            .tuple => |span| .{ .tuple = ids.exprSpan(span) },
            .record => |span| .{ .record = ids.fieldExprSpan(span) },
            .record_update => |update| .{ .record_update = .{
                .base = ids.expr(update.base),
                .fields = ids.fieldExprSpan(update.fields),
            } },
            .tag => |tag| .{ .tag = .{
                .name = tag.name,
                .payloads = ids.exprSpan(tag.payloads),
            } },
            .nominal => |expr| .{ .nominal = ids.expr(expr) },
            .let_ => |let_| .{ .let_ = .{
                .bind = ids.pat(let_.bind),
                .value = ids.expr(let_.value),
                .rest = ids.expr(let_.rest),
                .comptime_site = if (let_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .lambda => |lambda| .{ .lambda = .{
                .fn_id = ids.fnTarget(lambda.fn_id),
                .args = ids.typedLocalSpan(lambda.args),
                .body = ids.expr(lambda.body),
            } },
            .def_ref => |def| .{ .def_ref = ids.defTarget(def) },
            .fn_def => |fn_def| .{ .fn_def = .{
                .fn_id = ids.fnTarget(fn_def.fn_id),
                .captures = ids.fnDefCaptureSpan(fn_def.captures),
            } },
            .fn_ref => |fn_ref| .{ .fn_ref = fn_ref },
            .call_value => |call| .{ .call_value = .{
                .callee = ids.expr(call.callee),
                .args = ids.exprSpan(call.args),
            } },
            .call_proc => |call| .{ .call_proc = .{
                .callee = ids.procCallee(call.callee),
                .args = ids.exprSpan(call.args),
                .iterator_procedure = call.iterator_procedure,
                .captures = try self.sealCallCaptureOperandSpan(program, ids, call.captures),
                .is_cold = call.is_cold,
            } },
            .low_level => |call| .{ .low_level = .{
                .op = call.op,
                .args = ids.exprSpan(call.args),
            } },
            .field_access => |access| .{ .field_access = .{
                .receiver = ids.expr(access.receiver),
                .segments = ids.fieldAccessSegmentSpan(access.segments),
            } },
            .tuple_access => |access| .{ .tuple_access = .{
                .tuple = ids.expr(access.tuple),
                .elem_index = access.elem_index,
            } },
            .structural_eq => |eq| .{ .structural_eq = .{
                .lhs = ids.expr(eq.lhs),
                .rhs = ids.expr(eq.rhs),
                .negated = eq.negated,
            } },
            .structural_hash => |hash| .{ .structural_hash = .{
                .value = ids.expr(hash.value),
                .hasher = ids.expr(hash.hasher),
            } },
            .match_ => |match_| .{ .match_ = .{
                .scrutinee = ids.expr(match_.scrutinee),
                .branches = ids.branchSpan(match_.branches),
                .comptime_site = if (match_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .if_ => |if_| .{ .if_ = .{
                .branches = ids.ifBranchSpan(if_.branches),
                .final_else = ids.expr(if_.final_else),
            } },
            .pending_deferred => Common.invariant("pending deferred expression reached Monotype body sealing"),
            .@"unreachable" => .@"unreachable",
            .uninitialized => .uninitialized,
            .uninitialized_payload => |payload| .{ .uninitialized_payload = .{
                .condition = ids.local(payload.condition),
                .mask = payload.mask,
            } },
            .if_initialized_payload => |payload| .{ .if_initialized_payload = .{
                .cond = ids.expr(payload.cond),
                .cond_mask = payload.cond_mask,
                .payload = ids.local(payload.payload),
                .uninitialized_is_cold = payload.uninitialized_is_cold,
                .initialized = ids.expr(payload.initialized),
                .uninitialized = ids.expr(payload.uninitialized),
            } },
            .try_sequence => |try_| .{ .try_sequence = .{
                .try_expr = ids.expr(try_.try_expr),
                .ok_local = ids.local(try_.ok_local),
                .err_is_cold = try_.err_is_cold,
                .ok_body = ids.expr(try_.ok_body),
            } },
            .try_record_sequence => |try_| .{ .try_record_sequence = .{
                .try_expr = ids.expr(try_.try_expr),
                .value_local = ids.local(try_.value_local),
                .value_field = try_.value_field,
                .rest_local = ids.local(try_.rest_local),
                .rest_field = try_.rest_field,
                .err_is_cold = try_.err_is_cold,
                .ok_body = ids.expr(try_.ok_body),
            } },
            .block => |block| .{ .block = .{
                .statements = self.stmtSpan(ids, block.statements),
                .final_expr = ids.expr(block.final_expr),
            } },
            .loop_ => |loop| .{ .loop_ = .{
                .params = ids.typedLocalSpan(loop.params),
                .initial_values = ids.exprSpan(loop.initial_values),
                .body = ids.expr(loop.body),
            } },
            .break_ => |break_| .{ .break_ = if (break_) |expr| ids.expr(expr) else null },
            .continue_ => |continue_| .{ .continue_ = .{
                .values = ids.exprSpan(continue_.values),
            } },
            .return_ => |ret| .{ .return_ = try BodyDraftStore.sealCoreReturn(ids, graph, sealer, ret) },
            .crash => |literal| .{ .crash = ids.stringLiteral(literal) },
            .comptime_branch_taken => |taken| .{ .comptime_branch_taken = .{
                .site = ids.comptimeSite(taken.site),
                .branch_index = taken.branch_index,
                .body = ids.expr(taken.body),
            } },
            .comptime_exhaustiveness_failed => |site| .{ .comptime_exhaustiveness_failed = ids.comptimeSite(site) },
            .dbg => |expr| .{ .dbg = ids.expr(expr) },
            .expect_err => |expect_err| .{ .expect_err = .{
                .msg = ids.expr(expect_err.msg),
                .region = expect_err.region,
            } },
            .expect => |expr| .{ .expect = ids.expr(expr) },
        };
    }

    fn sealCoreStmt(ids: FinalIdOffsets, graph: *InstGraph, sealer: *GraphTypeFinals, stmt: DraftStmt) Allocator.Error!Ast.Stmt {
        return switch (stmt) {
            .uninitialized => |pat| .{ .uninitialized = ids.pat(pat) },
            .let_ => |let_| .{ .let_ = .{
                .pat = ids.pat(let_.pat),
                .value = ids.expr(let_.value),
                .recursive = let_.recursive,
                .comptime_site = if (let_.comptime_site) |site| ids.comptimeSite(site) else null,
            } },
            .expr => |expr| .{ .expr = ids.expr(expr) },
            .expect => |expr| .{ .expect = ids.expr(expr) },
            .dbg => |expr| .{ .dbg = ids.expr(expr) },
            .return_ => |ret| .{ .return_ = try BodyDraftStore.sealCoreReturn(ids, graph, sealer, ret) },
            .crash => |literal| .{ .crash = ids.stringLiteral(literal) },
        };
    }

    fn stmtSpan(_: *const BodyDraftStore, ids: FinalIdOffsets, span: DraftSpan(DraftStmtId)) Ast.Span(Ast.StmtId) {
        return ids.stmtSpan(span);
    }
};

const FinalIdOffsets = struct {
    const CoreIdMode = union(enum) {
        identity,
        remapped: *const Builder.DraftCoreMaps,
    };

    fn_start: u32,
    def_start: u32,
    nested_def_start: u32,
    expr_start: u32,
    pat_start: u32,
    stmt_start: u32,
    local_start: u32,
    string_literal_start: u32,
    comptime_site_start: u32,
    expr_ids_start: u32,
    pat_ids_start: u32,
    typed_locals_start: u32,
    stmt_ids_start: u32,
    field_expr_start: u32,
    field_access_segment_start: u32,
    fn_def_capture_start: u32,
    record_destruct_start: u32,
    str_pattern_step_start: u32,
    branch_start: u32,
    if_branch_start: u32,
    source_file_start: u32,
    fn_slots: []const ?Ast.FnSlot = &.{},
    def_ids: []const ?Ast.DefId = &.{},
    core_id_mode: CoreIdMode,

    fn core(self: FinalIdOffsets, kind: DraftCoreKind, raw: u32, identity_start: u32) u32 {
        return switch (self.core_id_mode) {
            .identity => identity_start + raw,
            .remapped => |maps| blk: {
                const mapped = maps.values[@intFromEnum(kind)][raw];
                if (mapped == std.math.maxInt(u32)) {
                    Common.invariant("retained body draft content referenced suppressed owned content");
                }
                break :blk mapped;
            },
        };
    }

    fn retained(self: FinalIdOffsets, kind: DraftCoreKind, index: usize) bool {
        return switch (self.core_id_mode) {
            .identity => true,
            .remapped => |maps| maps.retained(kind, index),
        };
    }

    fn coreSpanStart(self: FinalIdOffsets, kind: DraftCoreKind, start: u32, len: u32, identity_start: u32) u32 {
        if (len == 0) return 0;
        const mapped_start = self.core(kind, start, identity_start);
        var offset: u32 = 1;
        while (offset < len) : (offset += 1) {
            if (self.core(kind, start + offset, identity_start) != mapped_start + offset) {
                Common.invariant("retained body draft span was not one contiguous ownership range");
            }
        }
        return mapped_start;
    }

    fn fn_(self: FinalIdOffsets, id: DraftFnId) Ast.FnId {
        if (self.fn_slots.len != 0) return switch (self.fn_slots[@intFromEnum(id)] orelse
            Common.invariant("unreachable draft function required a final function id")) {
            .local => |fn_id| fn_id,
            .imported => Common.invariant("draft function required a local id after converging to an imported specialization"),
        };
        return @enumFromInt(self.fn_start + @intFromEnum(id));
    }

    fn fnSlot(self: FinalIdOffsets, id: DraftFnId) Ast.FnSlot {
        if (self.fn_slots.len != 0) return self.fn_slots[@intFromEnum(id)] orelse
            Common.invariant("unreachable draft function required a final function slot");
        return .{ .local = @enumFromInt(self.fn_start + @intFromEnum(id)) };
    }

    fn hasFnSlot(self: FinalIdOffsets, id: DraftFnId) bool {
        return self.fn_slots.len == 0 or self.fn_slots[@intFromEnum(id)] != null;
    }

    fn fnTarget(self: FinalIdOffsets, id: DraftFnTarget) Ast.FnId {
        return switch (id) {
            .draft => |draft| self.fn_(draft),
            .final => |final| final,
        };
    }

    fn def(self: FinalIdOffsets, id: DraftDefId) Ast.DefId {
        if (self.def_ids.len != 0) return self.def_ids[@intFromEnum(id)] orelse
            Common.invariant("draft definition required a local id after its function converged to an imported specialization");
        return @enumFromInt(self.def_start + @intFromEnum(id));
    }

    fn defTarget(self: FinalIdOffsets, id: DraftDefTarget) Ast.DefId {
        return switch (id) {
            .draft => |draft| self.def(draft),
            .final => |final| final,
        };
    }

    fn expr(self: FinalIdOffsets, id: DraftExprId) Ast.ExprId {
        return @enumFromInt(self.core(.exprs, @intFromEnum(id), self.expr_start));
    }

    fn pat(self: FinalIdOffsets, id: DraftPatId) Ast.PatId {
        return @enumFromInt(self.core(.pats, @intFromEnum(id), self.pat_start));
    }

    fn stmt(self: FinalIdOffsets, id: DraftStmtId) Ast.StmtId {
        return @enumFromInt(self.core(.stmts, @intFromEnum(id), self.stmt_start));
    }

    fn local(self: FinalIdOffsets, id: DraftLocalId) Ast.LocalId {
        return @enumFromInt(self.core(.locals, @intFromEnum(id), self.local_start));
    }

    fn stringLiteral(self: FinalIdOffsets, id: DraftStringLiteralId) Ast.StringLiteralId {
        return @enumFromInt(self.core(.string_literals, @intFromEnum(id), self.string_literal_start));
    }

    fn comptimeSite(self: FinalIdOffsets, id: DraftComptimeSiteId) Ast.ComptimeSiteId {
        return @enumFromInt(self.core(.comptime_sites, @intFromEnum(id), self.comptime_site_start));
    }

    fn exprSpan(self: FinalIdOffsets, span: DraftSpan(DraftExprId)) Ast.Span(Ast.ExprId) {
        return .{ .start = self.coreSpanStart(.expr_ids, span.start, span.len, self.expr_ids_start), .len = span.len };
    }

    fn patSpan(self: FinalIdOffsets, span: DraftSpan(DraftPatId)) Ast.Span(Ast.PatId) {
        return .{ .start = self.coreSpanStart(.pat_ids, span.start, span.len, self.pat_ids_start), .len = span.len };
    }

    fn typedLocalSpan(self: FinalIdOffsets, span: DraftSpan(DraftTypedLocal)) Ast.Span(Ast.TypedLocal) {
        return .{ .start = self.coreSpanStart(.typed_locals, span.start, span.len, self.typed_locals_start), .len = span.len };
    }

    fn stmtSpan(self: FinalIdOffsets, span: DraftSpan(DraftStmtId)) Ast.Span(Ast.StmtId) {
        return .{ .start = self.coreSpanStart(.stmt_ids, span.start, span.len, self.stmt_ids_start), .len = span.len };
    }

    fn fieldExprSpan(self: FinalIdOffsets, span: DraftSpan(DraftFieldExpr)) Ast.Span(Ast.FieldExpr) {
        return .{ .start = self.coreSpanStart(.field_exprs, span.start, span.len, self.field_expr_start), .len = span.len };
    }

    fn fieldAccessSegmentSpan(
        self: FinalIdOffsets,
        span: DraftSpan(DraftFieldAccessSegment),
    ) Ast.Span(Ast.FieldAccessSegment) {
        return .{ .start = self.field_access_segment_start + span.start, .len = span.len };
    }

    fn fnDefCaptureSpan(self: FinalIdOffsets, span: DraftSpan(DraftFnDefCapture)) Ast.Span(Ast.FnDefCapture) {
        return .{ .start = self.coreSpanStart(.fn_def_captures, span.start, span.len, self.fn_def_capture_start), .len = span.len };
    }

    fn recordDestructSpan(self: FinalIdOffsets, span: DraftSpan(DraftRecordDestruct)) Ast.Span(Ast.RecordDestruct) {
        return .{ .start = self.coreSpanStart(.record_destructs, span.start, span.len, self.record_destruct_start), .len = span.len };
    }

    fn strPatternStepSpan(self: FinalIdOffsets, span: DraftSpan(DraftStrPatternStep)) Ast.Span(Ast.StrPatternStep) {
        return .{ .start = self.coreSpanStart(.str_pattern_steps, span.start, span.len, self.str_pattern_step_start), .len = span.len };
    }

    fn branchSpan(self: FinalIdOffsets, span: DraftSpan(DraftBranch)) Ast.Span(Ast.Branch) {
        return .{ .start = self.coreSpanStart(.branches, span.start, span.len, self.branch_start), .len = span.len };
    }

    fn ifBranchSpan(self: FinalIdOffsets, span: DraftSpan(DraftIfBranch)) Ast.Span(Ast.IfBranch) {
        return .{ .start = self.coreSpanStart(.if_branches, span.start, span.len, self.if_branch_start), .len = span.len };
    }

    fn fnBody(self: FinalIdOffsets, body: DraftFnBody) Ast.FnBody {
        return switch (body) {
            .roc => |body_expr| .{ .roc = self.expr(body_expr) },
            .hosted => .hosted,
        };
    }

    fn procCallee(self: FinalIdOffsets, callee: DraftProcCallee) Ast.ProcCallee {
        return switch (callee) {
            .func => |slot| .{ .func = switch (slot) {
                .local => |fn_id| switch (fn_id) {
                    .draft => |draft| self.fnSlot(draft),
                    .final => |final| .{ .local = final },
                },
                .imported => |imported| .{ .imported = imported },
            } },
            .lifted => |lifted| .{ .lifted = lifted },
        };
    }

    fn sourceLoc(self: FinalIdOffsets, loc: base.SourceLoc) base.SourceLoc {
        if (loc.file == base.SourceLoc.no_file) return loc;
        return .{
            .file = self.core(.source_files, loc.file, self.source_file_start),
            .line = loc.line,
            .column = loc.column,
        };
    }
};

const FinalBodyOutputGuard = struct {
    start: FinalBodyOutputCounts,
    allowance_start: FinalBodyOutputCounts,

    const End = struct {
        counts: FinalBodyOutputCounts,
        allowance: FinalBodyOutputCounts,
    };

    fn begin(builder: *Builder) FinalBodyOutputGuard {
        return .{
            .start = FinalBodyOutputCounts.fromProgram(builder.program),
            .allowance_start = builder.final_body_output_allowance,
        };
    }

    fn end(_: FinalBodyOutputGuard, builder: *Builder) End {
        return .{
            .counts = FinalBodyOutputCounts.fromProgram(builder.program),
            .allowance = builder.final_body_output_allowance,
        };
    }

    fn assertNoFinalBodyOutput(self: FinalBodyOutputGuard, end_: End) void {
        if (end_.counts.exprs - self.start.exprs != end_.allowance.exprs - self.allowance_start.exprs) {
            Common.invariant("active Monotype lowering wrote final expressions instead of BodyDraftStore expressions");
        }
        if (end_.counts.pats - self.start.pats != end_.allowance.pats - self.allowance_start.pats) {
            Common.invariant("active Monotype lowering wrote final patterns instead of BodyDraftStore patterns");
        }
        if (end_.counts.locals - self.start.locals != end_.allowance.locals - self.allowance_start.locals) {
            Common.invariant("active Monotype lowering wrote final locals instead of BodyDraftStore locals");
        }
        if (end_.counts.typed_locals - self.start.typed_locals != end_.allowance.typed_locals - self.allowance_start.typed_locals) {
            Common.invariant("active Monotype lowering wrote final typed locals instead of BodyDraftStore typed locals");
        }
        if (end_.counts.layout_requests - self.start.layout_requests != end_.allowance.layout_requests - self.allowance_start.layout_requests) {
            Common.invariant("active Monotype lowering wrote final layout requests instead of BodyDraftStore layout requests");
        }
        if (end_.counts.runtime_schema_requests - self.start.runtime_schema_requests != end_.allowance.runtime_schema_requests - self.allowance_start.runtime_schema_requests) {
            Common.invariant("active Monotype lowering wrote final runtime schema requests instead of BodyDraftStore runtime schema requests");
        }
    }
};

fn appendRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    proof: RuntimeImpossibilityProof,
) Allocator.Error!RuntimeImpossibilityProofId {
    const id: RuntimeImpossibilityProofId = @enumFromInt(@as(u32, @intCast(draft.impossibility_proofs.items.len)));
    try draft.impossibility_proofs.append(allocator, proof);
    return id;
}

fn anyRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    candidates: []const ?RuntimeImpossibilityProofId,
) Allocator.Error!?RuntimeImpossibilityProofId {
    var active_count: usize = 0;
    var sole: RuntimeImpossibilityProofId = undefined;
    for (candidates) |candidate| if (candidate) |id| switch (draft.impossibility_proofs.items[@intFromEnum(id)]) {
        // `any(false, x) == x`. False proofs are represented canonically as
        // null outside the proof store, so never retain an explicit `.never`
        // leaf in a composite proof.
        .never => {},
        // `any(true, x) == true`; the remaining operands cannot affect the
        // result.
        .always => return id,
        .node, .pending, .forward, .any, .all => {
            sole = id;
            active_count += 1;
        },
    };
    return switch (active_count) {
        0 => null,
        1 => sole,
        else => blk: {
            const start: u32 = @intCast(draft.impossibility_proof_ids.items.len);
            const ids = try draft.impossibility_proof_ids.addManyAsSlice(allocator, active_count);
            var index: usize = 0;
            for (candidates) |candidate| if (candidate) |id| switch (draft.impossibility_proofs.items[@intFromEnum(id)]) {
                .never => {},
                .always => unreachable,
                .node, .pending, .forward, .any, .all => {
                    ids[index] = id;
                    index += 1;
                },
            };
            break :blk try appendRuntimeImpossibilityProof(draft, allocator, .{
                .any = .{ .start = start, .len = @intCast(active_count) },
            });
        },
    };
}

fn allRuntimeImpossibilityProof(
    draft: *BodyDraftStore,
    allocator: Allocator,
    candidates: []const ?RuntimeImpossibilityProofId,
) Allocator.Error!?RuntimeImpossibilityProofId {
    var active_count: usize = 0;
    var sole: RuntimeImpossibilityProofId = undefined;
    for (candidates) |candidate| {
        const id = candidate orelse return null;
        switch (draft.impossibility_proofs.items[@intFromEnum(id)]) {
            // `all(false, x) == false`, represented canonically as null.
            .never => return null,
            // `all(true, x) == x`.
            .always => {},
            .node, .pending, .forward, .any, .all => {
                sole = id;
                active_count += 1;
            },
        }
    }
    return switch (active_count) {
        0 => try appendRuntimeImpossibilityProof(draft, allocator, .always),
        1 => sole,
        else => blk: {
            const start: u32 = @intCast(draft.impossibility_proof_ids.items.len);
            const ids = try draft.impossibility_proof_ids.addManyAsSlice(allocator, active_count);
            var index: usize = 0;
            for (candidates) |candidate| {
                const id = candidate orelse unreachable;
                switch (draft.impossibility_proofs.items[@intFromEnum(id)]) {
                    .never => unreachable,
                    .always => {},
                    .node, .pending, .forward, .any, .all => {
                        ids[index] = id;
                        index += 1;
                    },
                }
            }
            break :blk try appendRuntimeImpossibilityProof(draft, allocator, .{
                .all = .{ .start = start, .len = @intCast(active_count) },
            });
        },
    };
}

const BinderRestore = struct {
    binder: checked.PatternBinderId,
    previous: ?DraftLocalId,
};

const CollectedListPattern = struct {
    local: DraftLocalId,
    ty: Type.TypeId,
    patterns: []const checked.CheckedPatternId,
    rest: ?checked.CheckedListRestPattern,
};

const ActiveReturnTarget = struct {
    lambda: checked.CheckedExprId,
    cell: DraftTypeCell,
};

const ActiveConstBindingId = enum(u32) { _ };

const ActiveConstBinding = struct {
    parent: ?ActiveConstBindingId,
    const_use: checked.ConstLocator,
    binder: checked.PatternBinderId,
    local: DraftLocalId,
    cell: DraftTypeCell,
    owner: DraftOwner,
    reservation: DraftExprId,
    restored_source: ?DraftExprId = null,
    used: bool = false,
    wrapped: bool = false,
};

const ActiveConstBindingScope = struct {
    active: ActiveConstBindingId = undefined,
    previous_active: ?ActiveConstBindingId = null,
    binder: checked.PatternBinderId = undefined,
    previous_local: ?DraftLocalId = null,
    bound_in_current_view: bool = false,
    entered: bool = false,
};

const InterfaceReplayStatus = enum { expanding, ready };

const InterfaceReplayAddress = struct {
    family: DraftTemplateFamilyAddress,
    evidence_digest: [32]u8,
    provisional_digest: [32]u8,
};

const InterfaceReplayEntry = struct {
    evidence: StoredConstFnEvidence,
    provisional_ty: Type.TypeId,
    representative: NodeId,
    duplicates: std.ArrayList(NodeId) = .empty,
    status: InterfaceReplayStatus = .expanding,
};

const InterfaceReplayState = struct {
    entries: std.ArrayList(InterfaceReplayEntry),
    buckets: std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)),

    fn init(allocator: Allocator) InterfaceReplayState {
        return .{
            .entries = .empty,
            .buckets = std.AutoHashMap(InterfaceReplayAddress, std.ArrayList(u32)).init(allocator),
        };
    }

    fn deinit(self: *InterfaceReplayState, allocator: Allocator) void {
        for (self.entries.items) |*entry| entry.duplicates.deinit(allocator);
        self.entries.deinit(allocator);
        var buckets = self.buckets.valueIterator();
        while (buckets.next()) |bucket| bucket.deinit(allocator);
        self.buckets.deinit();
    }
};

const InstantiationScopeId = enum(u64) { _ };

const InstantiatedFieldKind = struct {
    id: FieldKindId,
    slot: NodeId,
    value: NodeId,
};

/// The complete mutable state for one checked-type instantiation scope. Body
/// lowering state remains on `BodyContext`; operations that only need a fresh
/// type instantiation can swap this small state without constructing another
/// body context.
const TypeInstantiationContext = struct {
    allocator: Allocator,
    id: InstantiationScopeId,
    module_bytes: [32]u8,
    node_map: collections.DenseMap(checked.CheckedTypeId, NodeId),
    field_kind_map: collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind),
    /// Innermost-last stack of nominal-instance instantiation scopes; see
    /// instNominalBackingNode.
    decl_scopes: std.ArrayList(*collections.DenseMap(checked.CheckedTypeId, NodeId)) = .empty,
    field_kind_decl_scopes: std.ArrayList(*collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind)) = .empty,

    fn init(
        allocator: Allocator,
        id: InstantiationScopeId,
        module_bytes: [32]u8,
    ) TypeInstantiationContext {
        return .{
            .allocator = allocator,
            .id = id,
            .module_bytes = module_bytes,
            .node_map = collections.DenseMap(checked.CheckedTypeId, NodeId).init(allocator),
            .field_kind_map = collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind).init(allocator),
        };
    }

    fn deinit(self: *TypeInstantiationContext) void {
        self.decl_scopes.deinit(self.allocator);
        self.field_kind_decl_scopes.deinit(self.allocator);
        self.node_map.deinit();
        self.field_kind_map.deinit();
    }
};

const BodyContext = struct {
    allocator: Allocator,
    builder: *Builder,
    /// Checked module whose ordered registry scope governs generated method
    /// dispatch in this specialization. This can differ from `view` when an
    /// imported template is specialized for a caller's concrete types.
    method_scope: ModuleView,
    view: ModuleView,
    /// Source-file identity for `view`, resolved once when this body context is
    /// created instead of through the draft hash table for every source node.
    source_file_id: ?u32,
    owner_template: names.ProcTemplate,
    owner_context_fn_key: names.TypeDigest,
    current_fn_key: names.TypeDigest,
    comptime_exhaustiveness_context: ExhaustivenessContext.Context,
    generated_encoder_source_fn_ty: ?checked.CheckedTypeId,
    generated_encoder_source_expr: ?checked.CheckedExprId,
    generated_encoder_lambda_index: u64,
    binders: BinderMap,
    typed_binders: TypedBinders,
    local_proc_contexts: std.AutoHashMap(DraftLocalProcAddress, DraftLocalProcContextId),
    restored_local_proc_scope: ?RestoredLocalProcScope = null,
    /// This specialization's type solver, shared by every instantiation
    /// context created while lowering the same specialization.
    graph: *InstGraph,
    /// Reusable recursion-path scratch for exact graph inhabitation walks.
    /// Node IDs are dense, and each walk unsets on exit, so this replaces a
    /// fresh visitation hash table per query.
    inhabitation_visiting: std.bit_set.DynamicBitSetUnmanaged,
    /// Draft body output owned by this specialization graph.
    draft: *BodyDraftStore,
    /// Checked-type cache and declaration-scope stack for this exact
    /// instantiation identity. Separate contexts give every checked graph a
    /// fresh relation-production identity.
    instantiation: TypeInstantiationContext,
    loop_contexts: std.ArrayList(LoopContext),
    /// Literal sub-patterns on non-builtin number types collected while
    /// lowering a match branch's pattern; each becomes an equality condition
    /// on the branch comparing the bound value against the literal's
    /// `from_numeral`-converted constant.
    pattern_literal_guards: std.ArrayList(PatternLiteralGuard),
    /// Pending user-binder preludes from translated optional-field destructs
    /// (see `OptionalDestructBind`), drained by the same owners that drain
    /// `pattern_literal_guards`.
    optional_destruct_binds: std.ArrayList(OptionalDestructBind) = .empty,
    /// Frozen-at-creation reachability topology attached to runtime demands
    /// emitted while lowering one match branch. The root plus explicit
    /// constructor payload/element cells prove when that branch cannot run.
    runtime_demand_guard_frames: RuntimeDemandGuardFrameStack = .{},
    /// Exact argument nodes of the function body currently being lowered.
    /// If any argument finalizes as uninhabited, the body is unreachable.
    /// This callee-owned proof is separate from call-chain frame identity.
    function_entry_demand_guards: []const NodeId = &.{},
    /// Exact return cell owned by the active checked lambda specialization.
    /// Source `return` expressions must consume this cell rather than create a
    /// new instantiation of the lambda's checked return type.
    current_return_target: ?ActiveReturnTarget = null,
    /// Match lowering can pre-register binder locals with graph type cells so
    /// branch bodies contribute constraints before the scrutinee is sealed.
    /// The subsequent pattern pass must attach those exact locals to the
    /// emitted patterns instead of allocating replacements.
    reuse_pre_registered_pattern_binders: bool = false,
    /// Match branches have their own complete pattern engine. Other callers
    /// must route recursive materialization through the shell/plan lowering.
    allow_recursive_pattern_lowering_for_match: bool = false,
    /// Structural equality types currently being expanded in this context.
    /// Seeing the same type again is a real recursive edge, which lowers to a
    /// reserved generated equality helper instead of recursively expanding AST.
    equality_expansion_stack: collections.DenseMap(Type.TypeId, void),
    /// Structural hash types currently being expanded in this context.
    /// Seeing the same type again is a real recursive edge, which lowers to a
    /// reserved generated hash helper instead of recursively expanding AST.
    hash_expansion_stack: collections.DenseMap(Type.TypeId, void),
    inspect_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    equality_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    hash_defs: std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry),
    encoder_defs: std.AutoHashMap(GeneratedEncoderDefAddress, DraftGeneratedHelperDefEntry),
    parser_defs: std.AutoHashMap(GeneratedParserDefAddress, DraftGeneratedHelperDefEntry),
    /// Frozen Phase-B lookup from each sealed equality component with an exact
    /// method to the procedure slot reserved while relations were still being
    /// produced.
    frozen_equality_method_calls: ?*const collections.DenseMap(Type.TypeId, DraftFnSlot) = null,
    /// Frozen Phase-B lookup from a sealed inspected nominal type to the
    /// attached `to_inspect` slot reserved while relations were still open.
    frozen_inspect_method_calls: ?*const collections.DenseMap(Type.TypeId, DraftFnSlot) = null,
    /// Exact custom parser/encoder callees prepared before the graph froze.
    /// Phase-B structural serialization may consume these sealed requests but
    /// may not instantiate or lower another checked callable.
    frozen_codec_calls: ?*const FrozenPreparedCodecCalls = null,
    /// Final structural serialization emission consumes only durable types and
    /// exact prepared call identities instead of reconstructing checked requests.
    frozen_sealed_emission: bool = false,
    /// The one finalizer that owns Phase-B materialization for this frozen
    /// graph. Checked defaults are applied here, never by an eager consumer.
    frozen_type_finals: ?*GraphTypeFinals = null,
    /// Source region to use while inlining a compile-time const eval template.
    /// The template body can be lowered from a lookup site, but diagnostics
    /// must point at the original const root.
    source_region_override: ?base.Region = null,
    /// The specific compile-time entry root currently being lowered. Hoisted
    /// constants only count as "own" roots for this exact entry, not for every
    /// specialization of the same procedure template. Module-qualified because
    /// the root id travels through template requests into other modules'
    /// body contexts, where the same integer names an unrelated root.
    current_entry_root: ?EntryRoot = null,
    /// Generated local for the top-level constant root currently being
    /// restored. Recursive references to that exact checked const identity
    /// consume this local so the restored value becomes an explicit recursive
    /// binding instead of an unbounded chain of deferred const expansions.
    active_const_binding: ?ActiveConstBindingId = null,
    /// Evidence for the current callable's dispatch requirements (innermost
    /// vector plus lexical parents for nested local functions). Body contexts
    /// created for the same specialization (dispatch call contexts, nested
    /// non-generalized closures) share the owning specialization's chain.
    evidence: EvidenceChain,
    /// While restoring a constant's stored value at a use site, the evidence
    /// vector that use supplied for the constant's own requirements. Closures
    /// restored from the constant lower their bodies against this chain
    /// (their plans' `constraint(k)` refs index the constant's scheme).
    restore_evidence: EvidenceChain,
    /// Exact dispatch sites whose constraint evidence resolves to a checked
    /// error or unreachable value in this specialization. Monotype emits a
    /// runtime crash instead of returning a value from each such dispatch.
    /// CheckedModule dependency propagation turns these dispatch crash bits into
    /// the complete expression and statement divergence columns consumed below.
    specialization_dispatch_crashes: ?[]bool = null,
    owns_specialization_dispatch_crashes: bool = false,
    specialization_dispatch_divergence: ?checked.DispatchDivergence = null,
    borrowed_specialization_dispatch_divergence: ?*const checked.DispatchDivergence = null,
    /// While recursively restoring a stored constant, the concrete type of the
    /// whole restored value. Nested stored closures use this to instantiate the
    /// owner callable's return when synthesizing the constant scheme's evidence.
    const PatternLiteralGuard = struct {
        local: DraftLocalId,
        ty: Type.TypeId,
        check: union(enum) {
            /// Compare against the literal's `from_numeral`/`from_quote`
            /// conversion result.
            conversion: checked.CheckedExprId,
            /// The literal's value is unrepresentable at the scrutinee's
            /// concrete type, so the branch can never match (checking reports
            /// these; an I8 can never equal 300).
            never,
        },
    };

    /// A user binder deferred while an optional destructure is translated
    /// from checked Try space into runtime slot space.
    const OptionalDestructBind = struct {
        /// The user binder's local (registered at the Try / error node).
        binder_local: DraftLocalId,
        value: union(enum) {
            /// Materialize the bound slot as a one-segment `.?` result.
            slot_to_try: struct {
                slot_local: DraftLocalId,
                slot_node: NodeId,
                try_node: NodeId,
            },
            /// Bind the constant error represented by the payload-less Missing slot.
            missing_err: struct {
                err_node: NodeId,
            },
        },
    };

    const ParserPrecomputedRecord = struct {
        renamed_field_locals: []DraftLocalId,
        renamed_field_values: []DraftExprId,
        renamed_field_lengths: ?[]u32,
        renamed_field_texts: ?[][]const u8,
    };

    const ParserPrecomputedCapture = struct {
        local: DraftLocalId,
        value: DraftExprId,
    };

    const ParserPrecomputedPlan = struct {
        allocator: Allocator,
        records: std.AutoHashMap(names.TypeDigest, ParserPrecomputedRecord),
        captures: std.ArrayList(ParserPrecomputedCapture),
        next_capture_id: usize,

        fn init(allocator: Allocator) ParserPrecomputedPlan {
            return .{
                .allocator = allocator,
                .records = std.AutoHashMap(names.TypeDigest, ParserPrecomputedRecord).init(allocator),
                .captures = .empty,
                .next_capture_id = 1,
            };
        }

        fn deinit(self: *ParserPrecomputedPlan) void {
            var records = self.records.valueIterator();
            while (records.next()) |record| {
                self.allocator.free(record.renamed_field_locals);
                self.allocator.free(record.renamed_field_values);
                if (record.renamed_field_lengths) |lengths| self.allocator.free(lengths);
                if (record.renamed_field_texts) |texts| self.allocator.free(texts);
            }
            self.records.deinit();
            self.captures.deinit(self.allocator);
        }
    };

    const SerializationPlanKind = enum { parser, encoder };

    const SerializationHelperPlan = struct {
        plan: ParserPrecomputedPlan,
        args: []BodyTypedLocal,

        fn deinit(self: *SerializationHelperPlan, allocator: Allocator) void {
            allocator.free(self.args);
            self.plan.deinit();
        }
    };

    const SerializationPlanInputs = struct {
        locals: std.ArrayList(DraftLocalId) = .empty,
        record_keys: std.AutoHashMap(names.TypeDigest, void),
        seen_types: collections.DenseMap(Type.TypeId, void),
        seen_locals: collections.DenseMap(DraftLocalId, void),

        fn init(allocator: Allocator) SerializationPlanInputs {
            return .{
                .record_keys = std.AutoHashMap(names.TypeDigest, void).init(allocator),
                .seen_types = collections.DenseMap(Type.TypeId, void).init(allocator),
                .seen_locals = collections.DenseMap(DraftLocalId, void).init(allocator),
            };
        }

        fn deinit(self: *SerializationPlanInputs, allocator: Allocator) void {
            self.seen_locals.deinit();
            self.seen_types.deinit();
            self.record_keys.deinit();
            self.locals.deinit(allocator);
        }
    };

    fn parserPlanKey(self: *BodyContext, shape_ty: Type.TypeId) names.TypeDigest {
        var hasher = std.crypto.hash.sha2.Sha256.init(.{});
        hasher.update("roc.parser_precomputed_record");
        const fields = self.recordFieldsForShape(shape_ty);
        var count = std.mem.nativeToLittle(u32, @intCast(GuardedList.borrowLen(fields)));
        hasher.update(std.mem.asBytes(&count));
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            const label = self.builder.program.names.recordFieldLabelText(field.name);
            var label_len = std.mem.nativeToLittle(u32, @intCast(label.len));
            hasher.update(std.mem.asBytes(&label_len));
            hasher.update(label);
        }
        return .{ .bytes = hasher.finalResult() };
    }

    fn parserPlanContains(self: *BodyContext, plan: *const ParserPrecomputedPlan, shape_ty: Type.TypeId) bool {
        return plan.records.contains(self.parserPlanKey(shape_ty));
    }

    fn parserPlanGet(self: *BodyContext, plan: *const ParserPrecomputedPlan, shape_ty: Type.TypeId) ?ParserPrecomputedRecord {
        return plan.records.get(self.parserPlanKey(shape_ty));
    }

    fn parserPlanPut(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        shape_ty: Type.TypeId,
        record: ParserPrecomputedRecord,
    ) Allocator.Error!void {
        try plan.records.put(self.parserPlanKey(shape_ty), record);
    }

    fn collectSerializationPlanInputs(
        self: *BodyContext,
        kind: SerializationPlanKind,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        plan: *const ParserPrecomputedPlan,
        inputs: *SerializationPlanInputs,
    ) Allocator.Error!void {
        if (inputs.seen_types.contains(shape_ty)) return;
        try inputs.seen_types.put(shape_ty, {});

        switch (kind) {
            .parser => {
                if (self.tryNullInfo(shape_ty)) |info| {
                    return try self.collectSerializationPlanInputs(kind, info.ok_payload_ty, encoding_ty, plan, inputs);
                }
                if (try self.missingTryInfo(shape_ty)) |info| {
                    return try self.collectSerializationPlanInputs(kind, info.ok_ty, encoding_ty, plan, inputs);
                }
                if (self.builder.optionalFieldSlot(shape_ty)) |slot| {
                    return try self.collectSerializationPlanInputs(kind, slot.payload_ty, encoding_ty, plan, inputs);
                }
                if ((try self.customParserLookup(shape_ty)) != null or self.parseScalarMethodName(shape_ty) != null) return;
            },
            .encoder => {
                if (self.tryNullInfo(shape_ty)) |info| {
                    return try self.collectSerializationPlanInputs(kind, info.ok_payload_ty, encoding_ty, plan, inputs);
                }
                if ((try self.customEncoderForLookup(shape_ty)) != null or self.encodeScalarMethodName(shape_ty) != null) return;
            },
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.collectSerializationPlanInputs(kind, payload_ty, encoding_ty, plan, inputs);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                try self.collectSerializationPlanInputs(kind, dict_shape, encoding_ty, plan, inputs);
            }
            return;
        }

        switch (self.builder.shapeContent(shape_ty)) {
            .list => |elem_ty| try self.collectSerializationPlanInputs(kind, elem_ty, encoding_ty, plan, inputs),
            .box => |payload_ty| try self.collectSerializationPlanInputs(kind, payload_ty, encoding_ty, plan, inputs),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |item_ty| {
                    try self.collectSerializationPlanInputs(kind, item_ty, encoding_ty, plan, inputs);
                }
            },
            .record, .zst => {
                const key = self.parserPlanKey(shape_ty);
                const record = plan.records.get(key) orelse
                    Common.invariant("structural serialization helper was missing precomputed record fields");
                try inputs.record_keys.put(key, {});
                for (record.renamed_field_locals) |local| {
                    if (inputs.seen_locals.contains(local)) continue;
                    try inputs.seen_locals.put(local, {});
                    try inputs.locals.append(self.allocator, local);
                }

                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| {
                    const child_ty = switch (kind) {
                        .parser => field.ty,
                        .encoder => try self.encodeRecordFieldPayloadType(field.ty),
                    };
                    try self.collectSerializationPlanInputs(kind, child_ty, encoding_ty, plan, inputs);
                }
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| {
                        try self.collectSerializationPlanInputs(kind, payload_ty, encoding_ty, plan, inputs);
                    }
                }
            },
            .primitive, .named, .func, .erased => {},
        }
    }

    fn serializationPlanInputs(
        self: *BodyContext,
        kind: SerializationPlanKind,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!SerializationPlanInputs {
        var inputs = SerializationPlanInputs.init(self.allocator);
        errdefer inputs.deinit(self.allocator);
        if (plan) |precomputed| {
            try self.collectSerializationPlanInputs(kind, shape_ty, encoding_ty, precomputed, &inputs);
        }
        return inputs;
    }

    fn cloneSerializationHelperPlan(
        self: *BodyContext,
        source: *const ParserPrecomputedPlan,
        inputs: *const SerializationPlanInputs,
        str_ty: Type.TypeId,
    ) Allocator.Error!SerializationHelperPlan {
        var helper = SerializationHelperPlan{
            .plan = ParserPrecomputedPlan.init(self.allocator),
            .args = try self.allocator.alloc(BodyTypedLocal, inputs.locals.items.len),
        };
        errdefer helper.deinit(self.allocator);
        helper.plan.next_capture_id = source.next_capture_id;

        var local_map = collections.DenseMap(DraftLocalId, DraftLocalId).init(self.allocator);
        defer local_map.deinit();
        var expr_map = collections.DenseMap(DraftLocalId, DraftExprId).init(self.allocator);
        defer expr_map.deinit();
        for (inputs.locals.items, 0..) |source_local, index| {
            const helper_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            const helper_expr = try self.localExpr(helper_local, str_ty);
            try local_map.put(source_local, helper_local);
            try expr_map.put(source_local, helper_expr);
            helper.args[index] = .{ .local = helper_local, .ty = str_ty };
            try helper.plan.captures.append(self.allocator, .{
                .local = helper_local,
                .value = helper_expr,
            });
        }

        var key_iter = inputs.record_keys.keyIterator();
        while (key_iter.next()) |key| {
            const source_record = source.records.get(key.*) orelse
                Common.invariant("structural serialization helper record key was absent from source plan");
            const locals = try self.allocator.alloc(DraftLocalId, source_record.renamed_field_locals.len);
            const values = try self.allocator.alloc(DraftExprId, source_record.renamed_field_locals.len);
            var inserted = false;
            errdefer if (!inserted) {
                self.allocator.free(locals);
                self.allocator.free(values);
            };
            for (source_record.renamed_field_locals, 0..) |source_local, index| {
                const helper_local = local_map.get(source_local) orelse
                    Common.invariant("structural serialization helper record local was absent from input map");
                locals[index] = helper_local;
                values[index] = expr_map.get(source_local) orelse
                    Common.invariant("structural serialization helper record expression was absent from input map");
            }
            const lengths = if (source_record.renamed_field_lengths) |source_lengths|
                try self.allocator.dupe(u32, source_lengths)
            else
                null;
            errdefer if (!inserted) if (lengths) |owned| self.allocator.free(owned);
            const texts = if (source_record.renamed_field_texts) |source_texts|
                try self.allocator.dupe([]const u8, source_texts)
            else
                null;
            errdefer if (!inserted) if (texts) |owned| self.allocator.free(owned);
            try helper.plan.records.put(key.*, .{
                .renamed_field_locals = locals,
                .renamed_field_values = values,
                .renamed_field_lengths = lengths,
                .renamed_field_texts = texts,
            });
            inserted = true;
        }
        return helper;
    }

    const MaterializedArg = struct {
        pattern: checked.CheckedPatternId,
        value: DraftExprId,
        ty: DraftTypeCell,
    };

    const PendingMaterializedPattern = struct {
        pattern: checked.CheckedPatternId,
        local: DraftLocalId,
        cell: DraftTypeCell,
    };

    const PendingMatchRecordRestBinding = struct {
        source_local: DraftLocalId,
        source_node: NodeId,
        rest_local: DraftLocalId,
        rest_node: NodeId,
        rest_cell: DraftTypeCell,
        before_guard: bool,
    };

    const MatchPatternLowering = struct {
        guard: ?DraftExprId,
        body: DraftExprId,
        record_rests: *std.ArrayList(PendingMatchRecordRestBinding),
    };

    const LoweredMatchRecordRestBindings = struct {
        guard_bindings: DraftSpan(DraftStmtId),
        body: DraftExprId,
    };

    const PatternSuccessGuard = struct {
        root_pattern: checked.CheckedPatternId,
        root_node: NodeId,
    };

    const PatternNodeVisit = struct {
        pattern: checked.CheckedPatternId,
        node: NodeId,
    };

    const ParseRecordSlots = struct {
        presence_locals: []const DraftLocalId,
        presence_tys: []const Type.TypeId,
        payload_locals: []const DraftLocalId,
        payload_tys: []const Type.TypeId,

        fn fieldCount(self: ParseRecordSlots) usize {
            return self.payload_locals.len;
        }
    };

    /// Loop-carried control locals for a derived record parser. `done` is set
    /// when the format reports the end of the record so the next iteration
    /// finishes at the loop head, which keeps the record-construction code at
    /// exactly one site. `counted`/`remaining` drive Counted mode, where the
    /// format declared the entry count up front and the driver never calls
    /// `parse_record_after_field`.
    const RecordLoopCtl = struct {
        done_local: DraftLocalId,
        counted_local: DraftLocalId,
        remaining_local: DraftLocalId,
        bool_ty: Type.TypeId,
        u64_ty: Type.TypeId,
    };

    const UpdatedFieldSlot = struct {
        local: DraftLocalId,
        ty: Type.TypeId,
        index: usize,
    };

    /// Loop-carried control locals for a derived list parser. In Counted mode
    /// the format declared the element count up front, so the driver reads
    /// exactly `remaining` more elements and never calls `parse_list_next` or
    /// `parse_list_after_item`.
    /// How a dict entry ends: `uncounted` asks the format whether more entries
    /// follow, `counted` re-enters the loop with one fewer entry left.
    const DictEntryEndMode = enum { counted, uncounted };

    const ListLoopCtl = struct {
        counted_local: DraftLocalId,
        remaining_local: DraftLocalId,
        bool_ty: Type.TypeId,
        u64_ty: Type.TypeId,
    };

    /// Loop params before the payload slots: cursor, done, counted, remaining.
    const record_loop_slot_offset = 4;

    const BindingContinuation = union(enum) {
        expr: DraftExprId,
        checked_expr: checked.CheckedExprId,
        materialized_args: struct {
            args: []const MaterializedArg,
            index: usize,
            body: checked.CheckedExprId,
        },
        iterator_body: struct {
            body: checked.CheckedExprId,
            result_cell: DraftTypeCell,
            rest_expr: DraftExprId,
            carries: []const LoopCarry,
        },
    };

    const CurrentLocal = struct {
        binder: checked.PatternBinderId,
        local: DraftLocalId,
    };

    fn typedBinder(self: *BodyContext, binder: checked.PatternBinderId, ty: Type.TypeId) TypedBinder {
        return .{
            .binder = binder,
            .type_digest = self.builder.program.types.typeDigest(&self.builder.program.names, ty),
        };
    }

    fn putTypedBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        ty: Type.TypeId,
        local: DraftLocalId,
    ) Allocator.Error!?DraftLocalId {
        const key = self.typedBinder(binder, ty);
        const previous = self.typed_binders.get(key);
        try self.typed_binders.put(key, local);
        return previous;
    }

    fn restoreTypedBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        ty: Type.TypeId,
        previous: ?DraftLocalId,
    ) void {
        const key = self.typedBinder(binder, ty);
        if (previous) |local| {
            self.typed_binders.put(key, local) catch |err| switch (err) {
                error.OutOfMemory => Common.invariant("restoring a previously inserted typed binder cannot reallocate"),
            };
        } else {
            _ = self.typed_binders.remove(key);
        }
    }

    fn init(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        return try initWithMethodScope(allocator, builder, view, view, owner_template, graph, draft);
    }

    fn initWithMethodScope(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        method_scope: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        var ctx = try initBodyState(allocator, builder, view, owner_template, graph, draft);
        errdefer ctx.deinit();
        ctx.method_scope = method_scope;
        ctx.source_file_id = try draft.sourceFileIdFor(view.module_identity.module_idx, view.module_env.module_name);
        return ctx;
    }

    /// Construct the operational state for a body-lowering context. Dense
    /// binder state remains lazy, and fresh type-only work uses
    /// `TypeInstantiationContext` directly.
    fn initBodyState(
        allocator: Allocator,
        builder: *Builder,
        view: ModuleView,
        owner_template: names.ProcTemplate,
        graph: *InstGraph,
        draft: *BodyDraftStore,
    ) Allocator.Error!BodyContext {
        builder.countBodyDiagnostic("body_contexts_created");
        return .{
            .allocator = allocator,
            .builder = builder,
            .method_scope = view,
            .view = view,
            .source_file_id = null,
            .owner_template = owner_template,
            .owner_context_fn_key = .{},
            .current_fn_key = .{},
            .comptime_exhaustiveness_context = .{},
            .generated_encoder_source_fn_ty = null,
            .generated_encoder_source_expr = null,
            .generated_encoder_lambda_index = 0,
            .binders = try BinderMap.init(allocator, view.bodies.patternBinderCount()),
            .typed_binders = TypedBinders.init(allocator),
            .local_proc_contexts = std.AutoHashMap(DraftLocalProcAddress, DraftLocalProcContextId).init(allocator),
            .graph = graph,
            .inhabitation_visiting = .{},
            .draft = draft,
            .evidence = rootEvidence(owner_template, &.{}),
            .restore_evidence = rootEvidence(owner_template, &.{}),
            .instantiation = TypeInstantiationContext.init(allocator, builder.allocateInstantiationScope(), view.key.bytes),
            .loop_contexts = .empty,
            .pattern_literal_guards = .empty,
            .equality_expansion_stack = collections.DenseMap(Type.TypeId, void).init(allocator),
            .hash_expansion_stack = collections.DenseMap(Type.TypeId, void).init(allocator),
            .inspect_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .equality_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .hash_defs = std.AutoHashMap(GeneratedHelperDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .encoder_defs = std.AutoHashMap(GeneratedEncoderDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .parser_defs = std.AutoHashMap(GeneratedParserDefAddress, DraftGeneratedHelperDefEntry).init(allocator),
            .frozen_equality_method_calls = null,
            .frozen_codec_calls = null,
        };
    }

    fn deinit(self: *BodyContext) void {
        if (self.specialization_dispatch_divergence) |*divergence| divergence.deinit(self.allocator);
        if (self.owns_specialization_dispatch_crashes) {
            self.allocator.free(self.specialization_dispatch_crashes.?);
        }
        self.parser_defs.deinit();
        self.encoder_defs.deinit();
        self.hash_defs.deinit();
        self.equality_defs.deinit();
        self.inspect_defs.deinit();
        self.hash_expansion_stack.deinit();
        self.equality_expansion_stack.deinit();
        self.pattern_literal_guards.deinit(self.allocator);
        self.optional_destruct_binds.deinit(self.allocator);
        self.loop_contexts.deinit(self.allocator);
        self.inhabitation_visiting.deinit(self.allocator);
        self.instantiation.deinit();
        self.local_proc_contexts.deinit();
        self.typed_binders.deinit();
        self.binders.deinit();
    }

    fn draftTypeCell(self: *BodyContext, ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        return try DraftTypeCell.fromActiveType(self.graph, ty);
    }

    fn activeTypeFromNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        return try self.graph.activeTypeViewForNode(node);
    }

    fn activeTypeFromCell(self: *BodyContext, cell: DraftTypeCell) Allocator.Error!Type.TypeId {
        return switch (cell) {
            .graph_node => |node| try self.activeTypeFromNode(node),
            .sealed => |ty| ty,
        };
    }

    fn addImpossibilityProof(
        self: *BodyContext,
        proof: RuntimeImpossibilityProof,
    ) Allocator.Error!RuntimeImpossibilityProofId {
        return try appendRuntimeImpossibilityProof(self.draft, self.allocator, proof);
    }

    fn impossibilityProofSpan(
        self: *BodyContext,
        span: DraftSpan(RuntimeImpossibilityProofId),
    ) []const RuntimeImpossibilityProofId {
        if (span.start > self.draft.impossibility_proof_ids.items.len or
            span.len > self.draft.impossibility_proof_ids.items.len - span.start)
        {
            Common.invariant("runtime impossibility proof span was outside the draft proof store");
        }
        return self.draft.impossibility_proof_ids.items[span.start..][0..span.len];
    }

    /// A `.node` proof leaf, or null when the node provably can never finalize
    /// as uninhabited—such a proof could never hold, so omitting it keeps
    /// proofs and demand-guard frames down to the guards that can actually
    /// exempt something.
    fn maybeNodeImpossibilityProof(self: *BodyContext, node: NodeId) Allocator.Error!?RuntimeImpossibilityProofId {
        if (!try self.graph.mayFinalizeAsUninhabited(node)) return null;
        return try self.addImpossibilityProof(.{ .node = node });
    }

    fn alwaysImpossibilityProof(self: *BodyContext) Allocator.Error!RuntimeImpossibilityProofId {
        return try self.addImpossibilityProof(.always);
    }

    fn anyImpossibilityProof(
        self: *BodyContext,
        candidates: []const ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return try anyRuntimeImpossibilityProof(self.draft, self.allocator, candidates);
    }

    fn allImpossibilityProof(
        self: *BodyContext,
        candidates: []const ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        return try allRuntimeImpossibilityProof(self.draft, self.allocator, candidates);
    }

    fn maybeNodesImpossibilityProof(
        self: *BodyContext,
        nodes: []const NodeId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        for (nodes) |node| {
            combined = try self.anyImpossibilityProof(&.{ combined, try self.maybeNodeImpossibilityProof(node) });
        }
        return combined;
    }

    fn currentRuntimeImpossibilityProof(
        self: *BodyContext,
        expression_proof: ?RuntimeImpossibilityProofId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        if (self.function_entry_demand_guards.len != 0) {
            combined = try self.maybeNodesImpossibilityProof(self.function_entry_demand_guards);
        }
        var frame_id = self.runtime_demand_guard_frames.head;
        while (frame_id) |id| {
            const frame = runtimeDemandGuardFrame(self.draft, id);
            combined = try self.anyImpossibilityProof(&.{ combined, frame.proof });
            frame_id = frame.parent;
        }
        return try self.anyImpossibilityProof(&.{ combined, expression_proof });
    }

    fn exprImpossibilityProof(self: *BodyContext, expr: DraftExprId) ?RuntimeImpossibilityProofId {
        return self.draft.expr_impossibility_proofs.items[@intFromEnum(expr)];
    }

    fn stmtImpossibilityProof(self: *BodyContext, stmt: DraftStmtId) ?RuntimeImpossibilityProofId {
        return self.draft.stmt_impossibility_proofs.items[@intFromEnum(stmt)];
    }

    fn anyExprSpanImpossibilityProof(
        self: *BodyContext,
        span: DraftSpan(DraftExprId),
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var combined: ?RuntimeImpossibilityProofId = null;
        for (self.exprSpan(span)) |expr| {
            combined = try self.anyImpossibilityProof(&.{ combined, self.exprImpossibilityProof(expr) });
        }
        return combined;
    }

    fn anyStmtSpanImpossibilityProof(
        self: *BodyContext,
        stmts: []const DraftStmtId,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var active_count: usize = 0;
        var sole: RuntimeImpossibilityProofId = undefined;
        for (stmts) |stmt| if (self.stmtImpossibilityProof(stmt)) |id| switch (self.draft.impossibility_proofs.items[@intFromEnum(id)]) {
            .never => {},
            .always => return id,
            .node, .pending, .forward, .any, .all => {
                sole = id;
                active_count += 1;
            },
        };
        return switch (active_count) {
            0 => null,
            1 => sole,
            else => blk: {
                const start: u32 = @intCast(self.draft.impossibility_proof_ids.items.len);
                const ids = try self.draft.impossibility_proof_ids.addManyAsSlice(self.allocator, active_count);
                var index: usize = 0;
                for (stmts) |stmt| if (self.stmtImpossibilityProof(stmt)) |id| switch (self.draft.impossibility_proofs.items[@intFromEnum(id)]) {
                    .never => {},
                    .always => unreachable,
                    .node, .pending, .forward, .any, .all => {
                        ids[index] = id;
                        index += 1;
                    },
                };
                break :blk try self.addImpossibilityProof(.{
                    .any = .{ .start = start, .len = @intCast(active_count) },
                });
            },
        };
    }

    fn patternSuccessImpossibilityProof(
        self: *BodyContext,
        pat: DraftPatId,
    ) ?RuntimeImpossibilityProofId {
        return self.draft.pat_impossibility_proofs.items[@intFromEnum(pat)];
    }

    /// Build a proof leaf without importing a sealed type back into the
    /// specialization graph. Phase-B deferred emission may create expressions
    /// after relation production is frozen, so sealed cells must use their
    /// immutable Monotype inhabitation result directly.
    fn cellImpossibilityProof(
        self: *BodyContext,
        cell: DraftTypeCell,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        return switch (cell) {
            .graph_node => |node| try self.maybeNodeImpossibilityProof(node),
            .sealed => |ty| if (try self.typeIsProvenUninhabited(ty))
                try self.alwaysImpossibilityProof()
            else
                null,
        };
    }

    fn patDataImpossibilityProof(
        self: *BodyContext,
        ty: DraftTypeCell,
        data: DraftPatData,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
        defer proofs.deinit(self.allocator);
        try proofs.append(self.allocator, try self.cellImpossibilityProof(ty));
        switch (data) {
            .as => |as| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(as.pattern)),
            .record => |span| for (self.recordDestructSpan(span)) |field|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(field.pattern)),
            .tuple => |span| for (self.patSpan(span)) |child|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .list => |list| {
                for (self.patSpan(list.patterns)) |child|
                    try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child));
                if (list.rest) |rest| if (rest.pattern) |child|
                    try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child));
            },
            .tag => |tag| for (self.patSpan(tag.payloads)) |child|
                try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .nominal => |child| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .str_pattern => |str_pattern| for (self.strPatternStepSpan(str_pattern.steps)) |step|
                if (step.capture) |child| try proofs.append(self.allocator, self.patternSuccessImpossibilityProof(child)),
            .bind, .wildcard, .int_lit, .dec_lit, .frac_f32_lit, .frac_f64_lit, .str_lit => {},
        }
        return try self.anyImpossibilityProof(proofs.items);
    }

    fn exprDataImpossibilityProof(
        self: *BodyContext,
        ty: DraftTypeCell,
        data: DraftExprData,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return switch (data) {
            .local,
            .unit,
            .pending_deferred,
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .lambda,
            .def_ref,
            .fn_ref,
            .uninitialized,
            .uninitialized_payload,
            => null,
            .static_data_candidate => |candidate| self.exprImpossibilityProof(candidate.runtime_expr),
            .@"unreachable",
            .break_,
            .continue_,
            .return_,
            .crash,
            .comptime_exhaustiveness_failed,
            => try self.alwaysImpossibilityProof(),
            .list, .tuple => |span| try self.anyExprSpanImpossibilityProof(span),
            .record => |span| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.fieldExprSpan(span)) |field|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(field.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .record_update => |update| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                try proofs.append(self.allocator, self.exprImpossibilityProof(update.base));
                for (self.fieldExprSpan(update.fields)) |field|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(field.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .tag => |tag| try self.anyExprSpanImpossibilityProof(tag.payloads),
            .nominal => |backing| self.exprImpossibilityProof(backing),
            .fn_def => |fn_def| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.fnDefCaptureSpan(fn_def.captures)) |capture|
                    try proofs.append(self.allocator, self.exprImpossibilityProof(capture.value));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .let_ => |let_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(let_.value),
                self.patternSuccessImpossibilityProof(let_.bind),
                self.exprImpossibilityProof(let_.rest),
            }),
            .call_value => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(call.callee),
                try self.anyExprSpanImpossibilityProof(call.args),
            }),
            .call_proc => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                try self.anyExprSpanImpossibilityProof(call.args),
                try self.anyExprSpanImpossibilityProof(call.captures),
            }),
            .low_level => |call| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                try self.anyExprSpanImpossibilityProof(call.args),
            }),
            .field_access => |field| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(field.receiver),
            }),
            .tuple_access => |tuple| try self.anyImpossibilityProof(&.{
                try self.cellImpossibilityProof(ty),
                self.exprImpossibilityProof(tuple.tuple),
            }),
            .structural_eq => |eq| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(eq.lhs),
                self.exprImpossibilityProof(eq.rhs),
            }),
            .structural_hash => |hash| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(hash.value),
                self.exprImpossibilityProof(hash.hasher),
            }),
            .match_ => |match_| blk: {
                var alternatives = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer alternatives.deinit(self.allocator);
                for (self.branchSpan(match_.branches)) |branch| {
                    try alternatives.append(self.allocator, try self.anyImpossibilityProof(&.{
                        self.patternSuccessImpossibilityProof(branch.pat),
                        try self.anyStmtSpanImpossibilityProof(self.stmtSpan(branch.bindings)),
                        if (branch.guard) |guard| self.exprImpossibilityProof(guard) else null,
                        self.exprImpossibilityProof(branch.body),
                    }));
                }
                break :blk try self.anyImpossibilityProof(&.{
                    self.exprImpossibilityProof(match_.scrutinee),
                    try self.allImpossibilityProof(alternatives.items),
                });
            },
            .if_ => |if_| blk: {
                var remaining = self.exprImpossibilityProof(if_.final_else);
                const branches = self.ifBranchSpan(if_.branches);
                var index = branches.len;
                while (index > 0) {
                    index -= 1;
                    remaining = try self.anyImpossibilityProof(&.{
                        self.exprImpossibilityProof(branches[index].cond),
                        try self.allImpossibilityProof(&.{
                            self.exprImpossibilityProof(branches[index].body),
                            remaining,
                        }),
                    });
                }
                break :blk remaining;
            },
            .if_initialized_payload => |switch_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(switch_.cond),
                try self.allImpossibilityProof(&.{
                    self.exprImpossibilityProof(switch_.initialized),
                    self.exprImpossibilityProof(switch_.uninitialized),
                }),
            }),
            .try_sequence => |try_| self.exprImpossibilityProof(try_.try_expr),
            .try_record_sequence => |try_| self.exprImpossibilityProof(try_.try_expr),
            .block => |block| blk: {
                var proofs = std.ArrayList(?RuntimeImpossibilityProofId).empty;
                defer proofs.deinit(self.allocator);
                for (self.stmtSpan(block.statements)) |stmt|
                    try proofs.append(self.allocator, self.stmtImpossibilityProof(stmt));
                try proofs.append(self.allocator, self.exprImpossibilityProof(block.final_expr));
                break :blk try self.anyImpossibilityProof(proofs.items);
            },
            .loop_ => |loop_| try self.anyExprSpanImpossibilityProof(loop_.initial_values),
            .comptime_branch_taken => |branch| self.exprImpossibilityProof(branch.body),
            .dbg => |child| self.exprImpossibilityProof(child),
            .expect_err => |expect_err| self.exprImpossibilityProof(expect_err.msg),
            .expect => |child| self.exprImpossibilityProof(child),
        };
    }

    fn stmtDataImpossibilityProof(
        self: *BodyContext,
        stmt: DraftStmt,
    ) Allocator.Error!?RuntimeImpossibilityProofId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        return switch (stmt) {
            .uninitialized => null,
            .let_ => |let_| try self.anyImpossibilityProof(&.{
                self.exprImpossibilityProof(let_.value),
                self.patternSuccessImpossibilityProof(let_.pat),
            }),
            .expr, .expect, .dbg => |expr| self.exprImpossibilityProof(expr),
            .return_, .crash => try self.alwaysImpossibilityProof(),
        };
    }

    fn addExpr(self: *BodyContext, expr: BodyExpr) Allocator.Error!DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addExprWithSource(
            .{ .ty = try self.draftTypeCell(expr.ty), .data = expr.data },
            self.builder.program.current_loc,
            self.builder.program.current_region,
        );
        self.draft.expr_impossibility_proofs.items[@intFromEnum(id)] = try self.exprDataImpossibilityProof(
            self.draft.exprs.items[@intFromEnum(id)].ty,
            expr.data,
        );
        return id;
    }

    fn addFieldAccessExpr(
        self: *BodyContext,
        receiver: DraftExprId,
        field: names.RecordFieldNameId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field }});
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .field_access = .{
                .receiver = receiver,
                .segments = segments,
            } },
        });
    }

    fn addExprWithTypeCell(self: *BodyContext, ty: DraftTypeCell, data: BodyExprData) Allocator.Error!DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addExprWithSource(
            .{ .ty = ty, .data = data },
            self.builder.program.current_loc,
            self.builder.program.current_region,
        );
        self.draft.expr_impossibility_proofs.items[@intFromEnum(id)] = try self.exprDataImpossibilityProof(ty, data);
        return id;
    }

    fn fillExprReservation(self: *BodyContext, reservation: DraftExprId, value: DraftExprId) void {
        self.draft.exprs.items[@intFromEnum(reservation)] =
            self.draft.exprs.items[@intFromEnum(value)];
        self.draft.expr_impossibility_proofs.items[@intFromEnum(reservation)] =
            self.draft.expr_impossibility_proofs.items[@intFromEnum(value)];
    }

    /// Add a structural constructor expression (tag, record, or tuple),
    /// typing it at the nominal construction backing and wrapping it in one
    /// explicit `.nominal` node per nominal layer of `ty`. This keeps
    /// nominal construction explicit in the IR even when the checked
    /// expression was an unqualified constructor promoted to a nominal type
    /// during unification.
    fn addConstructorExpr(self: *BodyContext, ty: Type.TypeId, data: BodyExprData) Allocator.Error!DraftExprId {
        if (self.builder.nominalConstructionLayer(ty)) |layer| {
            const backing_expr = try self.addConstructorExpr(layer.backing, data);
            return try self.addExpr(.{ .ty = layer.named, .data = .{ .nominal = backing_expr } });
        }
        return try self.addExpr(.{ .ty = ty, .data = data });
    }

    fn addConstructorExprAtNode(self: *BodyContext, node: NodeId, data: BodyExprData) Allocator.Error!DraftExprId {
        const representation_node = self.constructorRepresentationNode(node);
        return switch (self.graph.content(representation_node)) {
            .named => blk: {
                const named = self.graph.namedNodes(representation_node);
                if (named.kind == .alias) Common.invariant("constructor representation retained a transparent alias node");
                const backing = named.backing orelse
                    Common.invariant("named constructor graph node had no explicit backing");
                const backing_expr = try self.addConstructorExprAtNode(backing.node, data);
                break :blk try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(representation_node),
                    .{ .nominal = backing_expr },
                );
            },
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(node), data),
        };
    }

    /// Follow only producer-authored transparent alias edges to the runtime
    /// representation node used by constructor and pattern topology. A
    /// nominal or opaque node remains as an explicit construction layer;
    /// an alias never creates a `.nominal` expression or pattern.
    fn constructorRepresentationNode(self: *BodyContext, node: NodeId) NodeId {
        var current = node;
        while (self.graph.content(current) == .named) {
            const named = self.graph.namedNodes(current);
            if (named.kind != .alias) return current;
            const backing = named.backing orelse
                Common.invariant("transparent alias graph node had no explicit backing");
            if (backing.node == current) Common.invariant("transparent alias backing did not advance");
            current = backing.node;
        }
        return current;
    }

    /// Pattern counterpart to `addConstructorExpr`, used by compiler-generated
    /// exhaustive matches whose constructor pattern has no checked source node.
    fn addConstructorPat(self: *BodyContext, ty: Type.TypeId, data: BodyPatData) Allocator.Error!DraftPatId {
        if (self.builder.nominalConstructionLayer(ty)) |layer| {
            const backing_pat = try self.addConstructorPat(layer.backing, data);
            return try self.addPat(.{ .ty = layer.named, .data = .{ .nominal = backing_pat } });
        }
        return try self.addPat(.{ .ty = ty, .data = data });
    }

    fn addPat(self: *BodyContext, pat: BodyPat) Allocator.Error!DraftPatId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const ty = try self.draftTypeCell(pat.ty);
        const id = try self.draft.addPat(.{ .ty = ty, .data = pat.data });
        self.draft.pat_impossibility_proofs.items[@intFromEnum(id)] = try self.patDataImpossibilityProof(ty, pat.data);
        return id;
    }

    fn addPatWithTypeCell(self: *BodyContext, ty: DraftTypeCell, data: BodyPatData) Allocator.Error!DraftPatId {
        if (std.debug.runtime_safety and data == .nominal) {
            switch (ty) {
                .graph_node => |node| if (self.graph.content(node) == .named and self.graph.namedNodes(node).kind == .alias) {
                    Common.invariant("Monotype graph lowering emitted a nominal pattern at an alias type");
                },
                .sealed => {},
            }
        }
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const id = try self.draft.addPat(.{ .ty = ty, .data = data });
        self.draft.pat_impossibility_proofs.items[@intFromEnum(id)] = try self.patDataImpossibilityProof(ty, data);
        return id;
    }

    fn addLocal(self: *BodyContext, symbol: Common.Symbol, ty: Type.TypeId) Allocator.Error!DraftLocalId {
        return try self.addLocalWithBinder(symbol, ty, null);
    }

    fn addLocalWithBinder(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: Type.TypeId,
        binder: ?checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        return try self.addLocalWithBinderCell(symbol, try self.draftTypeCell(ty), binder);
    }

    fn addLocalWithBinderCell(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: ?checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        const inherited_capture_id = if (binder) |source_binder| blk: {
            const existing = self.binders.get(source_binder) orelse break :blk null;
            break :blk self.draft.locals.items[@intFromEnum(existing)].capture_id;
        } else null;
        return try self.draft.addLocal(symbol, ty, binder, inherited_capture_id);
    }

    /// Materialize a new runtime binding from checked capture provenance even
    /// when another instantiation of that checked binder is temporarily in
    /// scope. This is the one-to-many boundary; ordinary local versions use
    /// `addLocalWithBinderCell` and inherit the current binding's identity.
    fn addFreshLocalWithBinder(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: Type.TypeId,
        binder: checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        return try self.addFreshLocalWithBinderCell(symbol, try self.draftTypeCell(ty), binder);
    }

    fn addFreshLocalWithBinderCell(
        self: *BodyContext,
        symbol: Common.Symbol,
        ty: DraftTypeCell,
        binder: checked.PatternBinderId,
    ) Allocator.Error!DraftLocalId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .draft_ir);
        defer timing_scope.end();
        return try self.draft.addLocal(symbol, ty, binder, null);
    }

    fn addFn(self: *BodyContext, source: Ast.FnTemplate) Allocator.Error!DraftFnId {
        if (source.const_evidence.len != 0 or source.const_evidence_frames.len != 0 or source.const_evidence_frame_head != null) {
            Common.invariant("body-local function source carried evidence outside its lexical lowering context");
        }
        const stored_evidence = try self.builder.constFnEvidence(self.evidence);
        const evidence_digest = Ast.fnEvidenceDigest(stored_evidence.nodes, stored_evidence.frames, stored_evidence.head);
        return try self.draft.addFn(.{
            .source = .{
                .fn_def = source.fn_def,
                .source_fn_ty = source.source_fn_ty,
                .source_fn_key = source.source_fn_key,
                .mono_fn_ty = try self.draftTypeCell(source.mono_fn_ty),
                .const_evidence = try self.builder.program.addConstFnEvidence(stored_evidence.nodes),
                .const_evidence_frames = try self.builder.program.addConstFnEvidenceFrames(stored_evidence.frames),
                .const_evidence_frame_head = stored_evidence.head,
                .evidence_digest = evidence_digest,
            },
        });
    }

