    fn exprDependsOnFreeLocal(
        self: *BodyContext,
        expr: DraftExprId,
        target: DraftLocalId,
    ) Allocator.Error!bool {
        var bound = collections.DenseMap(DraftLocalId, void).init(self.allocator);
        defer bound.deinit();
        return try self.exprDependsOnFreeLocalInner(expr, target, &bound);
    }

    fn exprDependsOnFreeLocalInner(
        self: *BodyContext,
        expr_id: DraftExprId,
        target: DraftLocalId,
        bound: *collections.DenseMap(DraftLocalId, void),
    ) Allocator.Error!bool {
        const expr = self.draft.exprs.items[@intFromEnum(expr_id)];
        switch (expr.data) {
            .pending_deferred => Common.invariant("pending deferred expression reached draft free-local analysis"),
            .local => |local| return try self.localDependsOnTarget(local, target, bound),
            .@"unreachable",
            .unit,
            .int_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .dec_lit,
            .str_lit,
            .bytes_lit,
            .uninitialized,
            .crash,
            .comptime_exhaustiveness_failed,
            .def_ref,
            .fn_ref,
            => return false,
            .uninitialized_payload => |payload| return try self.localDependsOnTarget(payload.condition, target, bound),
            .list,
            .tuple,
            => |items| {
                for (self.exprSpan(items)) |child| {
                    if (try self.exprDependsOnFreeLocalInner(child, target, bound)) return true;
                }
                return false;
            },
            .record => |fields| {
                for (self.fieldExprSpan(fields)) |field| {
                    if (try self.exprDependsOnFreeLocalInner(field.value, target, bound)) return true;
                }
                return false;
            },
            .record_update => |update| {
                if (try self.exprDependsOnFreeLocalInner(update.base, target, bound)) return true;
                for (self.fieldExprSpan(update.fields)) |field| {
                    if (try self.exprDependsOnFreeLocalInner(field.value, target, bound)) return true;
                }
                return false;
            },
            .tag => |tag| {
                for (self.exprSpan(tag.payloads)) |payload| {
                    if (try self.exprDependsOnFreeLocalInner(payload, target, bound)) return true;
                }
                return false;
            },
            .static_data_candidate => |candidate| return try self.exprDependsOnFreeLocalInner(candidate.runtime_expr, target, bound),
            .nominal,
            .dbg,
            .expect,
            => |child| return try self.exprDependsOnFreeLocalInner(child, target, bound),
            .return_ => |ret| return try self.exprDependsOnFreeLocalInner(ret.value, target, bound),
            .expect_err => |expect_err| return try self.exprDependsOnFreeLocalInner(expect_err.msg, target, bound),
            .comptime_branch_taken => |taken| return try self.exprDependsOnFreeLocalInner(taken.body, target, bound),
            .let_ => |let_| {
                if (try self.exprDependsOnFreeLocalInner(let_.value, target, bound)) return true;
                var added = std.ArrayList(DraftLocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindPatLocals(let_.bind, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(let_.rest, target, bound);
            },
            .lambda => |lambda| {
                var added = std.ArrayList(DraftLocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindTypedLocalLocals(lambda.args, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(lambda.body, target, bound);
            },
            .fn_def => |fn_def| {
                for (self.fnDefCaptureSpan(fn_def.captures)) |capture| {
                    if (try self.exprDependsOnFreeLocalInner(capture.value, target, bound)) return true;
                }
                return false;
            },
            .call_value => |call| {
                if (try self.exprDependsOnFreeLocalInner(call.callee, target, bound)) return true;
                for (self.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound)) return true;
                }
                return false;
            },
            .call_proc => |call| {
                for (self.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound)) return true;
                }
                for (self.exprSpan(call.captures)) |capture| {
                    if (try self.exprDependsOnFreeLocalInner(capture, target, bound)) return true;
                }
                return false;
            },
            .low_level => |call| {
                for (self.exprSpan(call.args)) |arg| {
                    if (try self.exprDependsOnFreeLocalInner(arg, target, bound)) return true;
                }
                return false;
            },
            .field_access => |field| return try self.exprDependsOnFreeLocalInner(field.receiver, target, bound),
            .tuple_access => |access| return try self.exprDependsOnFreeLocalInner(access.tuple, target, bound),
            .structural_eq => |eq| {
                if (try self.exprDependsOnFreeLocalInner(eq.lhs, target, bound)) return true;
                return try self.exprDependsOnFreeLocalInner(eq.rhs, target, bound);
            },
            .structural_hash => |hash| {
                if (try self.exprDependsOnFreeLocalInner(hash.value, target, bound)) return true;
                return try self.exprDependsOnFreeLocalInner(hash.hasher, target, bound);
            },
            .match_ => |match| {
                if (try self.exprDependsOnFreeLocalInner(match.scrutinee, target, bound)) return true;
                for (self.branchSpan(match.branches)) |branch| {
                    var added = std.ArrayList(DraftLocalId).empty;
                    defer added.deinit(self.allocator);
                    try self.bindPatLocals(branch.pat, bound, &added);
                    defer removeBoundLocals(bound, added.items);
                    for (self.stmtSpan(branch.bindings)) |stmt| {
                        if (try self.stmtDependsOnFreeLocal(stmt, target, bound, &added)) return true;
                    }
                    if (branch.guard) |guard| {
                        if (try self.exprDependsOnFreeLocalInner(guard, target, bound)) return true;
                    }
                    if (try self.exprDependsOnFreeLocalInner(branch.body, target, bound)) return true;
                }
                return false;
            },
            .if_ => |if_| {
                for (self.ifBranchSpan(if_.branches)) |branch| {
                    if (try self.exprDependsOnFreeLocalInner(branch.cond, target, bound)) return true;
                    if (try self.exprDependsOnFreeLocalInner(branch.body, target, bound)) return true;
                }
                return try self.exprDependsOnFreeLocalInner(if_.final_else, target, bound);
            },
            .if_initialized_payload => |payload| {
                if (try self.exprDependsOnFreeLocalInner(payload.cond, target, bound)) return true;
                if (try self.localDependsOnTarget(payload.payload, target, bound)) return true;
                if (try self.exprDependsOnFreeLocalInner(payload.initialized, target, bound)) return true;
                return try self.exprDependsOnFreeLocalInner(payload.uninitialized, target, bound);
            },
            .try_sequence => |sequence| {
                if (try self.exprDependsOnFreeLocalInner(sequence.try_expr, target, bound)) return true;
                try bound.put(sequence.ok_local, {});
                defer _ = bound.remove(sequence.ok_local);
                return try self.exprDependsOnFreeLocalInner(sequence.ok_body, target, bound);
            },
            .try_record_sequence => |sequence| {
                if (try self.exprDependsOnFreeLocalInner(sequence.try_expr, target, bound)) return true;
                try bound.put(sequence.value_local, {});
                try bound.put(sequence.rest_local, {});
                defer _ = bound.remove(sequence.rest_local);
                defer _ = bound.remove(sequence.value_local);
                return try self.exprDependsOnFreeLocalInner(sequence.ok_body, target, bound);
            },
            .block => |block| {
                var added = std.ArrayList(DraftLocalId).empty;
                defer added.deinit(self.allocator);
                defer removeBoundLocals(bound, added.items);
                for (self.stmtSpan(block.statements)) |stmt| {
                    if (try self.stmtDependsOnFreeLocal(stmt, target, bound, &added)) return true;
                }
                return try self.exprDependsOnFreeLocalInner(block.final_expr, target, bound);
            },
            .loop_ => |loop| {
                for (self.exprSpan(loop.initial_values)) |initial| {
                    if (try self.exprDependsOnFreeLocalInner(initial, target, bound)) return true;
                }
                var added = std.ArrayList(DraftLocalId).empty;
                defer added.deinit(self.allocator);
                try self.bindTypedLocalLocals(loop.params, bound, &added);
                defer removeBoundLocals(bound, added.items);
                return try self.exprDependsOnFreeLocalInner(loop.body, target, bound);
            },
            .break_ => |maybe| if (maybe) |value|
                return try self.exprDependsOnFreeLocalInner(value, target, bound)
            else
                return false,
            .continue_ => |continue_| {
                for (self.exprSpan(continue_.values)) |value| {
                    if (try self.exprDependsOnFreeLocalInner(value, target, bound)) return true;
                }
                return false;
            },
        }
    }

    fn localDependsOnTarget(
        self: *BodyContext,
        local: DraftLocalId,
        target: DraftLocalId,
        bound: *collections.DenseMap(DraftLocalId, void),
    ) Allocator.Error!bool {
        if (!try self.sameLocalIdentity(local, target)) return false;
        return !try self.boundContainsLocalIdentity(bound, local);
    }

    fn boundContainsLocalIdentity(
        self: *BodyContext,
        bound: *collections.DenseMap(DraftLocalId, void),
        local: DraftLocalId,
    ) Allocator.Error!bool {
        if (bound.contains(local)) return true;
        var iter = bound.keyIterator();
        while (iter.next()) |active| {
            if (try self.sameLocalIdentity(active.*, local)) return true;
        }
        return false;
    }

    fn sameLocalIdentity(self: *BodyContext, lhs: DraftLocalId, rhs: DraftLocalId) Allocator.Error!bool {
        if (lhs == rhs) return true;
        const lhs_data = self.draft.locals.items[@intFromEnum(lhs)];
        const rhs_data = self.draft.locals.items[@intFromEnum(rhs)];
        if (lhs_data.binder == null or rhs_data.binder == null or lhs_data.binder.? != rhs_data.binder.?) {
            return false;
        }
        const lhs_node = try lhs_data.ty.toGraphNode(self.graph);
        const rhs_node = try rhs_data.ty.toGraphNode(self.graph);
        return self.graph.sameClass(lhs_node, rhs_node);
    }

    fn stmtDependsOnFreeLocal(
        self: *BodyContext,
        stmt_id: DraftStmtId,
        target: DraftLocalId,
        bound: *collections.DenseMap(DraftLocalId, void),
        added: *std.ArrayList(DraftLocalId),
    ) Allocator.Error!bool {
        const stmt = self.draft.stmts.items[@intFromEnum(stmt_id)];
        switch (stmt) {
            .uninitialized => |pat| {
                try self.bindPatLocals(pat, bound, added);
                return false;
            },
            .let_ => |let_| {
                if (let_.recursive) {
                    try self.bindPatLocals(let_.pat, bound, added);
                    return try self.exprDependsOnFreeLocalInner(let_.value, target, bound);
                } else {
                    if (try self.exprDependsOnFreeLocalInner(let_.value, target, bound)) return true;
                    try self.bindPatLocals(let_.pat, bound, added);
                    return false;
                }
            },
            .expr,
            .expect,
            .dbg,
            => |expr| return try self.exprDependsOnFreeLocalInner(expr, target, bound),
            .return_ => |ret| return try self.exprDependsOnFreeLocalInner(ret.value, target, bound),
            .crash => return false,
        }
    }

    fn bindTypedLocalLocals(
        self: *BodyContext,
        span: DraftSpan(DraftTypedLocal),
        bound: *collections.DenseMap(DraftLocalId, void),
        added: *std.ArrayList(DraftLocalId),
    ) Allocator.Error!void {
        for (self.typedLocalSpan(span)) |local| {
            try bound.put(local.local, {});
            try added.append(self.allocator, local.local);
        }
    }

    fn bindPatLocals(
        self: *BodyContext,
        pat_id: DraftPatId,
        bound: *collections.DenseMap(DraftLocalId, void),
        added: *std.ArrayList(DraftLocalId),
    ) Allocator.Error!void {
        const pat = self.draft.pats.items[@intFromEnum(pat_id)];
        switch (pat.data) {
            .bind => |local| {
                try bound.put(local, {});
                try added.append(self.allocator, local);
            },
            .wildcard,
            .int_lit,
            .dec_lit,
            .frac_f32_lit,
            .frac_f64_lit,
            .str_lit,
            => {},
            .as => |as| {
                try self.bindPatLocals(as.pattern, bound, added);
                try bound.put(as.local, {});
                try added.append(self.allocator, as.local);
            },
            .record => |fields| {
                for (self.recordDestructSpan(fields)) |field| {
                    try self.bindPatLocals(field.pattern, bound, added);
                }
            },
            .tuple => |items| {
                for (self.patSpan(items)) |child| try self.bindPatLocals(child, bound, added);
            },
            .list => |list| {
                for (self.patSpan(list.patterns)) |child| try self.bindPatLocals(child, bound, added);
                if (list.rest) |rest| if (rest.pattern) |rest_pat| try self.bindPatLocals(rest_pat, bound, added);
            },
            .tag => |tag| {
                for (self.patSpan(tag.payloads)) |payload| try self.bindPatLocals(payload, bound, added);
            },
            .nominal => |backing| try self.bindPatLocals(backing, bound, added),
            .str_pattern => |str| {
                for (self.strPatternStepSpan(str.steps)) |step| {
                    if (step.capture) |capture| try self.bindPatLocals(capture, bound, added);
                }
            },
        }
    }

    fn removeBoundLocals(bound: *collections.DenseMap(DraftLocalId, void), locals: []const DraftLocalId) void {
        var index = locals.len;
        while (index > 0) {
            index -= 1;
            _ = bound.remove(locals[index]);
        }
    }

    /// Constrain a checked type to a Monotype: instantiate the checked type
    /// into the graph and unify with the (linked or imported) Monotype node.
    fn constrainTypeToMono(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        try self.graph.unify(try self.instNode(checked_ty), try self.graph.importMono(mono_ty));
    }

    fn requireClosedCheckedType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (!self.checkedTypeIsClosed(checked_ty)) {
            Common.invariant("sealed Monotype cell was paired with an identity-bearing checked type");
        }
        const lowered = try self.builder.lowerType(self.view, checked_ty);
        if (!self.sameType(lowered, mono_ty)) {
            Common.invariant("sealed Monotype cell differed from its closed checked type");
        }
    }

    fn constrainTypeToCell(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        cell: DraftTypeCell,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        try self.graph.unify(try self.instNode(checked_ty), try cell.toGraphNode(self.graph));
    }

    /// Relate a checked public interface to an exact producer-owned value
    /// representation without allowing that private representation to replace
    /// the checked type node shared by other source occurrences. A binding's
    /// draft cell retains the private node directly; the fresh checked node is
    /// only its source-level interface proof.
    fn constrainCheckedInterfaceToCell(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        cell: DraftTypeCell,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        const value_node = try cell.toGraphNode(self.graph);
        if (try self.graph.containsGeneratedPrivate(value_node)) {
            try self.graph.relateOpaqueInterface(try self.freshInstNode(checked_ty), value_node);
        } else {
            try self.constrainTypeToCell(checked_ty, cell);
        }
    }

    /// Constrain two checked types from (possibly different) instantiation
    /// contexts of the same specialization to denote one type.
    fn constrainCheckedTypeRelations(
        self: *BodyContext,
        left_ty: checked.CheckedTypeId,
        right_ctx: *BodyContext,
        right_ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        if (self.graph != right_ctx.graph) {
            Common.invariant("checked type relation crossed specialization graphs");
        }
        try self.graph.unify(try self.instNode(left_ty), try right_ctx.instNode(right_ty));
    }

    fn monoAliasBacking(types: *const Type.Store, mono_ty: Type.TypeId) ?Type.TypeId {
        return switch (types.get(mono_ty)) {
            .named => |named| if (named.kind == .alias) blk: {
                const backing = named.backing orelse break :blk null;
                break :blk backing.ty;
            } else null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn constrainKnownType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        mono_ty: Type.TypeId,
    ) Allocator.Error!void {
        try self.constrainTypeToMono(checked_ty, mono_ty);
    }

    fn scopedCheckedType(self: *BodyContext, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
        if (!moduleBytesEqual(self.instantiation.module_bytes, self.view.key.bytes)) {
            Common.invariant("checked type lookup used an instantiation context owned by another module");
        }
        return checked_ty;
    }

    fn lowerTypeNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        return try self.instNode(checked_ty);
    }

    fn checkedTypeContainsError(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!bool {
        var visited = collections.DenseMap(checked.CheckedTypeId, void).init(self.allocator);
        defer visited.deinit();
        return try self.checkedTypeContainsErrorInner(checked_ty, &visited);
    }

    fn checkedTypeContainsErrorInner(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        visited: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        if (visited.contains(checked_ty)) return false;
        try visited.put(checked_ty, {});

        return switch (checkedPayload(self.view, checked_ty)) {
            .pending => Common.invariant("pending checked type reached Monotype error scan"),
            .err => true,
            .flex, .rigid, .empty_record, .empty_tag_union => false,
            .alias => |alias| blk: {
                if (try self.checkedTypeContainsErrorInner(alias.backing, visited)) break :blk true;
                break :blk try self.checkedTypeSpanContainsError(alias.args, visited);
            },
            .record_unbound => |fields| try self.checkedRecordFieldsContainError(fields, visited),
            .record => |record| blk: {
                if (try self.checkedRecordFieldsContainError(record.fields, visited)) break :blk true;
                break :blk try self.checkedTypeContainsErrorInner(record.ext, visited);
            },
            .tuple => |items| try self.checkedTypeSpanContainsError(items, visited),
            .nominal => |nominal| blk: {
                if (try self.checkedTypeSpanContainsError(nominal.args, visited)) break :blk true;
                break :blk try self.checkedTypeSpanContainsError(nominal.padding_field_types, visited);
            },
            .function => |function| blk: {
                if (try self.checkedTypeSpanContainsError(function.args, visited)) break :blk true;
                break :blk try self.checkedTypeContainsErrorInner(function.ret, visited);
            },
            .tag_union => |tag_union| blk: {
                if (try self.checkedTagsContainError(tag_union.tags, visited)) break :blk true;
                break :blk try self.checkedTypeContainsErrorInner(tag_union.ext, visited);
            },
        };
    }

    fn checkedTypeSpanContainsError(
        self: *BodyContext,
        checked_tys: []const checked.CheckedTypeId,
        visited: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        for (checked_tys) |ty| {
            if (try self.checkedTypeContainsErrorInner(ty, visited)) return true;
        }
        return false;
    }

    fn checkedRecordFieldsContainError(
        self: *BodyContext,
        fields: []const checked.CheckedRecordField,
        visited: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        for (fields) |field| {
            if (try self.checkedTypeContainsErrorInner(field.ty, visited)) return true;
        }
        return false;
    }

    fn checkedTagsContainError(
        self: *BodyContext,
        tags: []const checked.CheckedTag,
        visited: *collections.DenseMap(checked.CheckedTypeId, void),
    ) Allocator.Error!bool {
        for (tags) |tag| {
            if (try self.checkedTypeSpanContainsError(tag.argsSlice(self.view.types), visited)) return true;
        }
        return false;
    }

    fn activeNodeFromType(self: *BodyContext, ty: Type.TypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        if (self.graph.activeSnapshotNode(ty)) |node| return node;
        return try self.graph.importMono(ty);
    }

    fn activeTypeFromType(self: *BodyContext, ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromNode(try self.activeNodeFromType(ty));
    }

    fn lowerTypeCell(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!DraftTypeCell {
        return DraftTypeCell.fromGraphNode(try self.lowerTypeNode(checked_ty));
    }

    fn resolvedTypeViewForNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        if (!try self.graph.typeIsResolved(node)) {
            Common.invariant("resolved Monotype view requested for an unresolved instantiation node");
        }
        return try self.activeTypeFromNode(node);
    }

    fn currentPhaseTypeForNode(self: *BodyContext, node: NodeId) Allocator.Error!Type.TypeId {
        if (self.frozen_sealed_emission) {
            const finals = self.frozen_type_finals orelse
                Common.invariant("frozen Monotype emission had no graph type finalizer");
            return try finals.sealNode(node);
        }
        return try self.resolvedTypeViewForNode(node);
    }

    fn resolvedCheckedTypeView(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        return try self.resolvedTypeViewForNode(try self.lowerTypeNode(checked_ty));
    }

    fn lowerTypeView(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromCell(try self.lowerTypeCell(checked_ty));
    }

    fn graphFunctionNode(
        self: *BodyContext,
        args: []const NodeId,
        ret: NodeId,
    ) Allocator.Error!NodeId {
        const stored_args = try self.graph.arena().alloc(NodeId, args.len);
        @memcpy(stored_args, args);
        return try self.graph.newNode(.{ .func = .{
            .args = stored_args,
            .ret = ret,
        } });
    }

    fn graphFunctionNodeFromMono(
        self: *BodyContext,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!NodeId {
        const args = try self.graph.arena().alloc(NodeId, arg_tys.len);
        for (arg_tys, 0..) |arg_ty, index| {
            args[index] = try self.graph.importMono(arg_ty);
        }
        return try self.graphFunctionNode(args, try self.graph.importMono(ret_ty));
    }

    fn graphFunctionTypeCellFromMono(
        self: *BodyContext,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftTypeCell {
        return DraftTypeCell.fromGraphNode(try self.graphFunctionNodeFromMono(arg_tys, ret_ty));
    }

    fn hashFnTypeCell(self: *BodyContext, value_ty: Type.TypeId, hasher_ty: Type.TypeId) Allocator.Error!DraftTypeCell {
        const args = [_]Type.TypeId{ value_ty, hasher_ty };
        return try self.graphFunctionTypeCellFromMono(&args, hasher_ty);
    }

    /// Instantiate a checked type into this specialization's graph, caching by
    /// checked identity so every occurrence of the same checked root resolves
    /// to the same node within this instantiation context.
    fn instNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("checked_node_requests");
        const scoped_ty = self.scopedCheckedType(checked_ty);
        if (self.scopedNode(scoped_ty)) |existing| {
            self.builder.countBodyDiagnostic("checked_node_cache_hits");
            return existing;
        }
        self.builder.countBodyDiagnostic("checked_node_cache_misses");
        const placeholder = try self.graph.newNode(.{ .unresolved = InstVariable.placeholder() });
        try self.putScopedNode(scoped_ty, placeholder);
        const built = try self.instNodeContent(checked_ty);
        try self.graph.unify(placeholder, built);
        return placeholder;
    }

    fn freshInstNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("fresh_checked_node_requests");
        const previous = self.instantiation;
        self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), self.view.key.bytes);
        defer {
            self.instantiation.deinit();
            self.instantiation = previous;
        }
        return try self.instNode(checked_ty);
    }

    fn scopedNode(self: *BodyContext, checked_ty: checked.CheckedTypeId) ?NodeId {
        var index = self.instantiation.decl_scopes.items.len;
        while (index > 0) {
            index -= 1;
            if (self.instantiation.decl_scopes.items[index].get(checked_ty)) |existing| return existing;
        }
        if (self.instantiation.decl_scopes.items.len != 0) return null;
        return self.instantiation.node_map.get(checked_ty);
    }

    fn putScopedNode(self: *BodyContext, checked_ty: checked.CheckedTypeId, node: NodeId) Allocator.Error!void {
        if (self.instantiation.decl_scopes.items.len != 0) {
            try self.instantiation.decl_scopes.items[self.instantiation.decl_scopes.items.len - 1].put(checked_ty, node);
            return;
        }
        try self.instantiation.node_map.put(checked_ty, node);
    }

    fn scopedFieldKind(self: *BodyContext, checked_ty: checked.CheckedTypeId) ?InstantiatedFieldKind {
        var index = self.instantiation.field_kind_decl_scopes.items.len;
        while (index > 0) {
            index -= 1;
            if (self.instantiation.field_kind_decl_scopes.items[index].get(checked_ty)) |existing| return existing;
        }
        if (self.instantiation.field_kind_decl_scopes.items.len != 0) return null;
        return self.instantiation.field_kind_map.get(checked_ty);
    }

    fn putScopedFieldKind(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        field_kind: InstantiatedFieldKind,
    ) Allocator.Error!void {
        if (self.instantiation.field_kind_decl_scopes.items.len != 0) {
            try self.instantiation.field_kind_decl_scopes.items[self.instantiation.field_kind_decl_scopes.items.len - 1].put(checked_ty, field_kind);
            return;
        }
        try self.instantiation.field_kind_map.put(checked_ty, field_kind);
    }

    fn instNodeSlice(self: *BodyContext, checked_tys: []const checked.CheckedTypeId) Allocator.Error![]NodeId {
        const out = try self.graph.arena().alloc(NodeId, checked_tys.len);
        for (checked_tys, 0..) |checked_ty, index| {
            out[index] = try self.instNode(checked_ty);
        }
        return out;
    }

    fn instNodeContent(self: *BodyContext, checked_ty: checked.CheckedTypeId) Allocator.Error!NodeId {
        return switch (checkedPayload(self.view, checked_ty)) {
            .pending => Common.invariant("pending checked type reached Monotype instantiation"),
            .err => Common.invariant("erroneous checked type reached Monotype instantiation"),
            .flex, .rigid => |variable| try self.graph.newNode(.{ .unresolved = InstVariable.checkedVariable(
                variable.numeric_default_phase,
                variable.row_default,
            ) }),
            .empty_record => try self.graph.newNode(.empty_record),
            .empty_tag_union => try self.graph.newNode(.empty_tag_union),
            .alias => |alias| try self.graph.newNode(.{ .named = .{
                .named_type = .{ .module = self.builder.declaredModuleForAlias(self.view, alias), .ty = checked_ty },
                .def = try self.builder.typeDef(self.view, alias.origin_module, alias.name, alias.source_decl),
                .kind = .alias,
                .builtin_owner = null,
                .args = try self.instNodeSlice(alias.args),
                .backing = .{
                    .node = try self.instNode(alias.backing),
                    .use = .inspectable,
                },
            } }),
            .record_unbound => |fields| try self.graph.newNode(.{ .record = .{
                .fields = try self.instFields(fields),
                .ext = try self.graph.newNode(.{ .unresolved = InstVariable.row(.empty_record) }),
            } }),
            .record => |record| try self.graph.newNode(.{ .record = .{
                .fields = try self.instFields(record.fields),
                .ext = try self.instNode(record.ext),
            } }),
            .tuple => |items| try self.graph.newNode(.{ .tuple = try self.instNodeSlice(items) }),
            .function => |function| try self.graph.newNode(.{ .func = .{
                .args = try self.instNodeSlice(function.args),
                .ret = try self.instNode(function.ret),
            } }),
            .tag_union => |tag_union| try self.graph.newNode(.{ .tag_union = .{
                .tags = try self.instTags(tag_union.tags),
                .ext = try self.instNode(tag_union.ext),
            } }),
            .nominal => |nominal| try self.instNominalNode(checked_ty, nominal),
        };
    }

    fn instFields(self: *BodyContext, fields: []const checked.CheckedRecordField) Allocator.Error![]InstField {
        const out = try self.graph.arena().alloc(InstField, fields.len);
        for (fields, 0..) |field, index| {
            const value_node = try self.instNode(field.ty);
            const name = try self.builder.recordFieldName(self.view, field.name);
            const default = try self.builder.monoFieldDefault(self.view, field);
            out[index] = switch (field.kind.tag) {
                .required => .{ .name = name, .ty = value_node, .kind = .required, .default = null },
                .defaulted => .{
                    .name = name,
                    .ty = value_node,
                    .kind = .{ .defaulted = default orelse Common.invariant("defaulted checked field carried no default identity") },
                    .default = default,
                },
                .optional => .{
                    .name = name,
                    .ty = try self.optionalSlotNode(value_node),
                    .value_ty = value_node,
                    .kind = .optional,
                    .default = null,
                },
                .undetermined => blk: {
                    const checked_kind = self.scopedCheckedType(field.kind.undeterminedVariable() orelse
                        Common.invariant("undetermined checked field kind carried no presence variable"));
                    if (self.scopedFieldKind(checked_kind)) |existing| {
                        try self.graph.unify(existing.value, value_node);
                        break :blk .{
                            .name = name,
                            .ty = existing.slot,
                            .value_ty = existing.value,
                            .kind = .{ .undetermined = existing.id },
                            .default = null,
                        };
                    }
                    const slot_node = try self.graph.newNode(.{ .unresolved = InstVariable.placeholder() });
                    const kind = try self.graph.newUndeterminedFieldKind();
                    self.graph.registerUndeterminedFieldKindCells(kind, slot_node, value_node);
                    const instantiated = InstantiatedFieldKind{
                        .id = kind,
                        .slot = slot_node,
                        .value = value_node,
                    };
                    try self.putScopedFieldKind(checked_kind, instantiated);
                    break :blk .{
                        .name = name,
                        .ty = instantiated.slot,
                        .value_ty = instantiated.value,
                        .kind = .{ .undetermined = instantiated.id },
                        .default = null,
                    };
                },
                .err => Common.invariant("poisoned checked field kind reached Monotype instantiation"),
            };
        }
        return out;
    }

    /// The instantiation-graph node of an optional field's tagged slot: the
    /// closed structural union `[#Missing, #Present(value)]`, matching
    /// `Builder.optionalSlotType` exactly so graph-solved and directly-lowered
    /// occurrences of one checked row seal to the same Monotype.
    fn optionalSlotNode(self: *BodyContext, value_node: NodeId) Allocator.Error!NodeId {
        const missing = try self.builder.program.names.internTagLabel(Builder.optional_slot_missing_tag);
        const present = try self.builder.program.names.internTagLabel(Builder.optional_slot_present_tag);
        const tags = try self.graph.arena().alloc(InstTag, 2);
        tags[0] = .{
            .name = missing,
            .checked_name = missing,
            .payloads = try self.graph.arena().alloc(NodeId, 0),
        };
        const present_payloads = try self.graph.arena().alloc(NodeId, 1);
        present_payloads[0] = value_node;
        tags[1] = .{
            .name = present,
            .checked_name = present,
            .payloads = present_payloads,
        };
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.{ .unresolved = InstVariable.row(.empty_tag_union) }),
        } });
    }

    fn instTags(self: *BodyContext, tags: []const checked.CheckedTag) Allocator.Error![]InstTag {
        const out = try self.graph.arena().alloc(InstTag, tags.len);
        for (tags, 0..) |tag, index| {
            out[index] = .{
                .name = try self.builder.tagName(self.view, tag.name),
                .checked_name = try self.builder.tagName(self.view, tag.name),
                .payloads = try self.instNodeSlice(tag.argsSlice(self.view.types)),
            };
        }
        return out;
    }

    fn instNominalNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error!NodeId {
        switch (nominal.representation) {
            .builtin => |builtin| switch (checked.builtinRuntimeEncoding(builtin)) {
                .primitive => |primitive| return try self.graph.newNode(.{ .primitive = primitive }),
                .bool_tag_union => {},
                .list => {
                    if (nominal.args.len != 1) Common.invariant("checked List nominal must have exactly one type argument");
                    return try self.graph.newNode(.{ .list = try self.instNode(nominal.args[0]) });
                },
                .box => {
                    if (nominal.args.len != 1) Common.invariant("checked Box nominal must have exactly one type argument");
                    return try self.graph.newNode(.{ .box = try self.instNode(nominal.args[0]) });
                },
                .try_nominal,
                .iterator,
                .parse_tag_union_spec,
                .fields,
                .field,
                .dict,
                .set,
                .crypto_sha256_digest,
                .crypto_sha256_hasher,
                .crypto_blake3_digest,
                .crypto_blake3_hasher,
                => {},
            },
            .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability, .opaque_without_backing => {},
        }

        const args = try self.instNodeSlice(nominal.args);
        const backing_node: ?NodeId = switch (nominal.representation) {
            .opaque_without_backing => null,
            .builtin, .local_declaration, .imported_declaration, .local_box_payload_capability, .imported_box_payload_capability => try self.instNominalBackingNode(nominal, args),
        };
        const backing: ?InstBacking = if (backing_node) |node| .{
            .node = node,
            .use = if (nominal.is_opaque) .runtime_layout_only else .inspectable,
        } else null;
        const def = try self.builder.typeDef(self.view, nominal.origin_module, nominal.name, nominal.source_decl);
        self.builder.noteBuiltinTryDef(nominal.builtin, def);
        return try self.graph.newNode(.{ .named = .{
            .named_type = .{ .module = self.builder.declaredModuleForNominal(self.view, nominal), .ty = checked_ty },
            .def = def,
            .kind = if (nominal.is_opaque) .@"opaque" else .nominal,
            .builtin_owner = builtinOwner(nominal.builtin),
            .args = args,
            .backing = backing,
            .declared_order = try self.instDeclaredOrderForNominal(nominal),
        } });
    }

    fn instDeclaredOrderForNominal(
        self: *BodyContext,
        nominal: checked.CheckedNominalType,
    ) Allocator.Error![]const InstDeclaredField {
        const lookup = self.builder.nominalDeclarationFor(self.view, nominal) orelse {
            if (!nominalHasDeclarationBacking(nominal)) return &.{};
            Common.invariant("declaration-backed nominal reached Monotype instantiation without declaration data");
        };
        const fields = lookup.declaration.declaredRecordFields(lookup.view.types);
        if (fields.len == 0) return &.{};

        const entries = try self.graph.arena().alloc(InstDeclaredField, fields.len);
        const padding_types = lookup.padding_field_tys;
        var padding_cursor: usize = 0;
        for (fields, 0..) |field, index| {
            switch (field) {
                .named => |label| entries[index] = .{ .named = try self.builder.recordFieldName(lookup.view, label) },
                .padding => {
                    if (padding_cursor >= padding_types.len) {
                        Common.invariant("nominal declaration had more unnamed fields than recorded padding types");
                    }
                    const checked_ty = padding_types[padding_cursor];
                    padding_cursor += 1;
                    entries[index] = .{ .padding = try self.instNode(self.checkedTypeInCurrentView(lookup.view, checked_ty)) };
                },
            }
        }
        return entries;
    }

    /// Instantiate a nominal instance's backing. A declaration-backed nominal's
    /// formals and backing share one set of checked roots across every instance
    /// of the nominal, so the backing instantiates inside a fresh scope seeded
    /// with this instance's argument nodes: two instances of the same nominal at
    /// different arguments stay independent, and the recursive uses inside the
    /// backing resolve through the scope chain.
    fn instNominalBackingNode(
        self: *BodyContext,
        nominal: checked.CheckedNominalType,
        args: []NodeId,
    ) Allocator.Error!NodeId {
        const source = self.nominalInstantiationSource(nominal) orelse
            Common.invariant("nominal backing instantiation could not resolve a declaration-backed nominal");
        return try self.instNominalDeclarationBackingNode(source, args);
    }

    fn instNominalDeclarationBackingNode(
        self: *BodyContext,
        source: NominalInstantiationSource,
        args: []NodeId,
    ) Allocator.Error!NodeId {
        const declaration_id: u32 = @intFromEnum(source.declaration.id);
        if (self.graph.nominalBackingNode(source.view.key.bytes, declaration_id, args)) |cached| {
            self.builder.count("nominal_backing_reuses");
            return cached;
        }
        self.builder.count("nominal_backing_instantiations");

        const placeholder = try self.graph.newNode(.{ .unresolved = InstVariable.placeholder() });
        try self.graph.putNominalBackingNode(source.view.key.bytes, declaration_id, args, placeholder);

        const backing = if (moduleBytesEqual(source.view.key.bytes, self.view.key.bytes)) backing: {
            break :backing try self.instNominalDeclarationBackingNodeInCurrentView(source.declaration, args);
        } else backing: {
            const previous_view = self.view;
            const previous_instantiation = self.instantiation;
            self.view = source.view;
            self.instantiation = TypeInstantiationContext.init(self.allocator, self.builder.allocateInstantiationScope(), source.view.key.bytes);
            defer {
                self.instantiation.deinit();
                self.instantiation = previous_instantiation;
                self.view = previous_view;
            }
            break :backing try self.instNominalDeclarationBackingNodeInCurrentView(source.declaration, args);
        };
        try self.graph.unify(placeholder, backing);
        return placeholder;
    }

    fn instNominalDeclarationBackingNodeInCurrentView(
        self: *BodyContext,
        declaration: checked.CheckedNominalDeclaration,
        args: []NodeId,
    ) Allocator.Error!NodeId {
        const formal_args = declaration.formalArgs(self.view.types);
        if (formal_args.len != args.len) {
            Common.invariant("checked nominal declaration arity differed from nominal type use");
        }
        var scope = collections.DenseMap(checked.CheckedTypeId, NodeId).init(self.allocator);
        defer scope.deinit();
        var field_kind_scope = collections.DenseMap(checked.CheckedTypeId, InstantiatedFieldKind).init(self.allocator);
        defer field_kind_scope.deinit();
        for (formal_args, args) |formal, arg| {
            try scope.put(self.scopedCheckedType(formal), arg);
        }
        try self.instantiation.decl_scopes.append(self.allocator, &scope);
        defer _ = self.instantiation.decl_scopes.pop();
        try self.instantiation.field_kind_decl_scopes.append(self.allocator, &field_kind_scope);
        defer _ = self.instantiation.field_kind_decl_scopes.pop();
        return try self.instNode(declaration.backing);
    }

    const NominalInstantiationSource = struct {
        view: ModuleView,
        declaration: checked.CheckedNominalDeclaration,
    };

    fn nominalInstantiationSource(
        self: *BodyContext,
        nominal: checked.CheckedNominalType,
    ) ?NominalInstantiationSource {
        return switch (nominal.representation) {
            .local_declaration => |id| .{
                .view = self.view,
                .declaration = self.view.types.nominalDeclarationById(id),
            },
            .local_box_payload_capability => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal) orelse
                    Common.invariant("local box-payload nominal had no declaration source");
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .imported_declaration => |imported| blk: {
                const source_view = self.builder.moduleForId(checked.importedNominalDeclarationModuleId(imported));
                break :blk .{
                    .view = source_view,
                    .declaration = source_view.types.nominalDeclarationById(imported.declaration),
                };
            },
            .imported_box_payload_capability => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal) orelse
                    Common.invariant("imported box-payload nominal had no declaration source");
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .builtin => blk: {
                const lookup = self.builder.nominalDeclarationFor(self.view, nominal) orelse break :blk null;
                break :blk .{
                    .view = lookup.view,
                    .declaration = lookup.declaration,
                };
            },
            .opaque_without_backing => null,
        };
    }

    fn checkedTypeInCurrentView(
        self: *BodyContext,
        source_view: ModuleView,
        source_ty: checked.CheckedTypeId,
    ) checked.CheckedTypeId {
        if (moduleBytesEqual(source_view.key.bytes, self.view.key.bytes)) return source_ty;
        return self.view.types.rootForKey(source_view.types.rootKey(source_ty)) orelse
            Common.invariant("imported nominal declaration formal was not projected into the current checked type store");
    }

    fn lowerTemplateBodyAtNode(
        self: *BodyContext,
        template_ref: names.ProcTemplate,
        template: checked.CheckedProcedureTemplate,
        fn_node: NodeId,
    ) Allocator.Error!LoweredTemplateBody {
        var timing_scope = ProcedureTimingScope.begin(self.builder.timing, .body_lowering);
        defer timing_scope.end();

        if (!names.procedureTemplateRefEql(self.owner_template, template_ref)) {
            Common.invariant("Monotype body context owner did not match lowered checked template");
        }
        const fn_nodes = try self.graph.functionNodes(fn_node);
        const saved_function_entry_demand_guards = self.function_entry_demand_guards;
        defer self.function_entry_demand_guards = saved_function_entry_demand_guards;
        self.function_entry_demand_guards = fn_nodes.args;
        const ret_cell = DraftTypeCell.fromGraphNode(fn_nodes.ret);
        return switch (template.body) {
            .checked_body => |body_id| blk: {
                const body = self.view.bodies.body(body_id);
                const root = self.view.bodies.expr(body.root_expr);
                break :blk switch (root.data) {
                    .lambda => |lambda| try self.lowerLambdaTemplateAtNode(body.root_expr, lambda, fn_node),
                    .closure => |closure| closure_blk: {
                        if (closure.captures.len != 0) {
                            Common.invariant("checked procedure template root closure had captures");
                        }
                        const lambda_expr = self.view.bodies.expr(closure.lambda);
                        if (lambda_expr.data != .lambda) Common.invariant("checked procedure template root closure did not point at a lambda");
                        break :closure_blk try self.lowerLambdaTemplateAtNode(closure.lambda, lambda_expr.data.lambda, fn_node);
                    },
                    .hosted_lambda => Common.invariant("hosted lambda template must lower through hosted metadata, not source lambda body"),
                    .pending,
                    .numeral,
                    .str_from_quote,
                    .str_segment,
                    .str,
                    .bytes_literal,
                    .lookup_local,
                    .lookup_external,
                    .lookup_required,
                    .list,
                    .empty_list,
                    .tuple,
                    .match_,
                    .if_,
                    .call,
                    .record,
                    .empty_record,
                    .block,
                    .tag,
                    .nominal,
                    .zero_argument_tag,
                    .binop,
                    .unary_minus,
                    .unary_not,
                    .field_access,
                    .dispatch_call,
                    .interpolation,
                    .structural_eq,
                    .structural_hash,
                    .method_eq,
                    .type_dispatch_call,
                    .tuple_access,
                    .runtime_error,
                    .crash,
                    .dbg,
                    .expect_err,
                    .expect,
                    .ellipsis,
                    .anno_only,
                    .break_,
                    .return_,
                    .for_,
                    .run_low_level,
                    => .{
                        .args = .empty(),
                        .body = try self.lowerExprAtTypeCell(body.root_expr, ret_cell),
                        .ret = ret_cell,
                    },
                };
            },
            .entry_wrapper => |wrapper_id| return try self.lowerEntryWrapperAtCell(wrapper_id, ret_cell),
            .intrinsic_wrapper => |wrapper_id| {
                const wrapper = self.view.intrinsic_wrappers.get(wrapper_id);
                return switch (wrapper.intrinsic) {
                    .str_inspect => try self.lowerStrInspectIntrinsicAtNode(fn_nodes, ret_cell),
                    .structural_eq => Common.invariant("structural equality intrinsic wrapper must lower through checked dispatch plans"),
                    .parse_tag_union,
                    .field_names_rename_fields,
                    .field_names_shortest_name,
                    .field_names_longest_name,
                    .field_names_iter,
                    .field_names_for_size,
                    .field_name,
                    => Common.invariant("encoding intrinsic wrapper must lower through a checked direct call"),
                };
            },
        };
    }

    fn applyCheckedTemplateInterfaceRelations(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        root_node: NodeId,
    ) Allocator.Error!void {
        var replay_state = InterfaceReplayState.init(self.allocator);
        defer replay_state.deinit(self.allocator);
        var active_local_scopes = collections.DenseMap(checked.DispatchScopeId, NodeId).init(self.allocator);
        defer active_local_scopes.deinit();
        try self.applyCheckedTemplateInterfaceScopeRelations(
            template,
            null,
            root_node,
            &active_local_scopes,
            &replay_state,
        );
        try self.finishCheckedTemplateInterfaceReplay(&replay_state);
    }

    fn applyCheckedTemplateInterfaceScopeRelations(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        scope_id: ?checked.DispatchScopeId,
        scope_root_node: NodeId,
        active_local_scopes: *collections.DenseMap(checked.DispatchScopeId, NodeId),
        replay_state: *InterfaceReplayState,
    ) Allocator.Error!void {
        const PendingDependency = struct {
            target: checked.ResolvedValueId,
            source_fn_ty: checked.CheckedTypeId,
            request_fn_node: NodeId,
            provisional_ty: Type.TypeId,
        };
        var pending_dependencies = std.ArrayList(PendingDependency).empty;
        defer pending_dependencies.deinit(self.allocator);

        const relations = self.view.templates.specializationRelations(&template);
        for (relations) |relation| {
            if (!dispatchRefBelongsToScope(relation.scope, scope_id)) continue;
            switch (relation.data) {
                .type_equality => |equality| try relateRequestComponent(
                    self.graph,
                    try self.instNode(equality.left),
                    try self.instNode(equality.right),
                ),
                .procedure => |procedure| {
                    const fn_node = try self.instNode(procedure.fn_ty);
                    if (procedure.owns_scope) {
                        try relateFunctionRequestInterface(self.graph, fn_node, scope_root_node);
                    }
                    const function = try self.graph.functionNodes(fn_node);
                    try relateRequestComponent(
                        self.graph,
                        function.ret,
                        try self.instNode(procedure.body_ret_ty),
                    );
                },
                .call => |call| {
                    const source_fn_ty = if (call.direct_target) |target|
                        self.directCallInstantiationSourceFnType(target, call.callable_ty)
                    else
                        call.callable_ty;
                    const fn_node = try self.instNode(source_fn_ty);
                    try relateRequestComponent(self.graph, fn_node, try self.instNode(call.callee_ty));
                    const function = try self.graph.functionNodes(fn_node);
                    const arg_tys = self.view.templates.specializationRelationTypes(call.args);
                    if (function.args.len != arg_tys.len) {
                        Common.invariant("checked specialization call relation changed arity");
                    }
                    for (function.args, arg_tys) |arg_node, arg_ty| {
                        try relateRequestComponent(self.graph, arg_node, try self.instNode(arg_ty));
                    }
                    try relateRequestComponent(self.graph, function.ret, try self.instNode(call.ret_ty));
                    if (call.direct_target) |target| {
                        try pending_dependencies.append(self.allocator, .{
                            .target = target,
                            .source_fn_ty = source_fn_ty,
                            .request_fn_node = fn_node,
                            .provisional_ty = undefined,
                        });
                    }
                },
                .local_proc_use => |ref_id| {
                    const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
                    const local = switch (record.ref) {
                        .local_proc => |local| local,
                        .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => Common.invariant("checked local specialization relation targeted a non-local procedure"),
                    };
                    const local_scope = local.dispatch_scope orelse
                        Common.invariant("generalized local specialization relation had no checked scope");
                    const request_node = try self.instNode(record.checked_ty);
                    if (active_local_scopes.get(local_scope)) |active_root| {
                        try relateFunctionRequestInterface(self.graph, active_root, request_node);
                        continue;
                    }
                    var local_ctx = try BodyContext.initWithMethodScope(
                        self.allocator,
                        self.builder,
                        self.view,
                        self.method_scope,
                        self.owner_template,
                        self.graph,
                        self.draft,
                    );
                    defer local_ctx.deinit();
                    local_ctx.owner_context_fn_key = self.owner_context_fn_key;
                    local_ctx.current_fn_key = self.current_fn_key;
                    const local_root_node = try local_ctx.checkedTemplateInterfaceScopeRootNode(local_scope);
                    try relateFunctionRequestInterface(self.graph, local_root_node, request_node);
                    try active_local_scopes.put(local_scope, local_root_node);
                    defer _ = active_local_scopes.remove(local_scope);

                    const use_evidence = try self.evidenceForUseSiteForPurpose(
                        record.expr,
                        .specialization_interface,
                    );
                    local_ctx.evidence = try enterEvidenceScope(
                        self.builder,
                        self.evidence,
                        local_scope,
                        local.expr,
                        use_evidence,
                    );
                    try local_ctx.instantiateTemplateDispatchRelations(template, local_scope);
                    try local_ctx.applyCheckedTemplateInterfaceScopeRelations(
                        template,
                        local_scope,
                        local_root_node,
                        active_local_scopes,
                        replay_state,
                    );
                },
            }
        }

        for (pending_dependencies.items) |*pending| {
            pending.provisional_ty = try self.graph.provisionalTypeViewForNode(pending.request_fn_node);
        }
        for (pending_dependencies.items) |pending| {
            try self.applyDirectCalleeInterfaceRelations(
                pending.target,
                pending.source_fn_ty,
                pending.request_fn_node,
                pending.provisional_ty,
                replay_state,
            );
        }
    }

    fn checkedTemplateInterfaceScopeRootNode(
        self: *BodyContext,
        scope_id: checked.DispatchScopeId,
    ) Allocator.Error!NodeId {
        const raw_scope = @intFromEnum(scope_id);
        if (raw_scope >= self.view.templates.dispatch_scopes.len) {
            Common.invariant("checked specialization relation named an unknown local scope");
        }
        const scheme_root = self.view.templates.dispatch_scopes[raw_scope].scheme_root;
        return try self.instNode(scheme_root);
    }

    fn applyDirectCalleeInterfaceRelations(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        request_fn_node: NodeId,
        provisional_ty: Type.TypeId,
        replay_state: *InterfaceReplayState,
    ) Allocator.Error!void {
        const record = self.view.resolved_refs.records[@intFromEnum(target)];
        const procedure, const root_evidence = switch (record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| .{ procedure, @as(?checked.CheckedEvidenceSpan, null) },
            .platform_required_proc => |required| .{ required.procedure, required.root_evidence },
            .local_proc => return,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => Common.invariant("checked specialization call relation targeted a non-procedure"),
        };
        const template_ref = self.builder.templateRefForProcedureUse(procedure);
        const callee_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(template_ref));
        const template = callee_view.templates.get(template_ref.template);
        const partial_evidence = if (root_evidence) |producer_evidence|
            try self.builder.materializeCheckedProcedureEvidence(template_ref, producer_evidence)
        else
            try self.evidenceForUseSiteForPurpose(record.expr, .specialization_interface);
        const evidence = if (partial_evidence.len == template.evidence_params.len)
            partial_evidence
        else
            try self.builder.completeRootTemplateEvidenceForPurpose(
                callee_view,
                template_ref,
                template,
                partial_evidence,
                .specialization_interface,
            );
        const stored_evidence = try self.builder.constFnEvidence(rootEvidence(template_ref, evidence));
        const evidence_digest = Ast.fnEvidenceDigest(
            stored_evidence.nodes,
            stored_evidence.frames,
            stored_evidence.head,
        );
        const source_fn_key = self.view.types.rootKey(source_fn_ty);
        const provisional_digest = self.builder.specializationTypeDigest(provisional_ty);
        const address = InterfaceReplayAddress{
            .family = DraftTemplateFamilyAddress.init(template_ref, self.method_scope.key, source_fn_key),
            .evidence_digest = evidence_digest.bytes,
            .provisional_digest = provisional_digest.bytes,
        };

        if (replay_state.buckets.get(address)) |candidates| for (candidates.items) |raw_entry| {
            const entry = &replay_state.entries.items[raw_entry];
            if (!storedConstFnEvidenceEql(entry.evidence, stored_evidence) or
                !try self.builder.program.types.typeEql(
                    &self.builder.program.names,
                    entry.provisional_ty,
                    provisional_ty,
                ))
            {
                continue;
            }
            switch (entry.status) {
                .expanding => try relateFunctionRequestInterface(
                    self.graph,
                    entry.representative,
                    request_fn_node,
                ),
                .ready => try entry.duplicates.append(self.allocator, request_fn_node),
            }
            return;
        };

        const replay_index = replay_state.entries.items.len;
        try replay_state.entries.append(self.allocator, .{
            .evidence = stored_evidence,
            .provisional_ty = provisional_ty,
            .representative = request_fn_node,
        });
        const bucket = try replay_state.buckets.getOrPut(address);
        if (!bucket.found_existing) bucket.value_ptr.* = .empty;
        try bucket.value_ptr.append(self.allocator, @intCast(replay_index));

        var callee_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            callee_view,
            self.method_scope,
            template_ref,
            self.graph,
            self.draft,
        );
        defer callee_ctx.deinit();
        callee_ctx.owner_context_fn_key = self.owner_context_fn_key;
        callee_ctx.current_fn_key = self.current_fn_key;
        callee_ctx.evidence = rootEvidence(template_ref, evidence);
        const root_node = try callee_ctx.instNode(template.checked_fn_root);
        if (template.target == .hosted) {
            try relateHostedFunctionRequestInterface(
                self.graph,
                try self.builder.hostedTryAdapterCapability(callee_view, template.hosted_try_adapter),
                root_node,
                request_fn_node,
            );
        } else {
            try relateFunctionRequestInterface(self.graph, root_node, request_fn_node);
        }
        try callee_ctx.instantiateTemplateDispatchRelations(template, null);

        var active_local_scopes = collections.DenseMap(checked.DispatchScopeId, NodeId).init(self.allocator);
        defer active_local_scopes.deinit();
        try callee_ctx.applyCheckedTemplateInterfaceScopeRelations(
            template,
            null,
            root_node,
            &active_local_scopes,
            replay_state,
        );
        replay_state.entries.items[replay_index].status = .ready;
    }

    fn finishCheckedTemplateInterfaceReplay(
        self: *BodyContext,
        replay_state: *InterfaceReplayState,
    ) Allocator.Error!void {
        const final_types = try self.allocator.alloc(Type.TypeId, replay_state.entries.items.len);
        defer self.allocator.free(final_types);
        for (replay_state.entries.items, final_types) |entry, *final_ty| {
            if (entry.status != .ready) {
                Common.invariant("checked specialization interface replay did not finish");
            }
            final_ty.* = try self.graph.provisionalTypeViewForNode(entry.representative);
        }
        for (replay_state.entries.items, final_types) |entry, final_ty| {
            for (entry.duplicates.items) |duplicate| {
                try relateFunctionRequestInterface(
                    self.graph,
                    try self.graph.instantiateProvisionalTypeView(final_ty),
                    duplicate,
                );
            }
        }
    }

    fn lowerEntryWrapperAtCell(
        self: *BodyContext,
        wrapper_id: anytype,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredTemplateBody {
        const wrapper = self.view.entry_wrappers.get(wrapper_id);
        const root = self.view.compile_time_roots.root(wrapper.root);
        const saved_entry_root = self.current_entry_root;
        defer self.current_entry_root = saved_entry_root;
        self.current_entry_root = .{ .module = self.view.key, .root = wrapper.root };
        const saved_source_region_override = self.source_region_override;
        defer self.source_region_override = saved_source_region_override;
        self.source_region_override = switch (root.kind) {
            .constant,
            .hoisted_constant,
            .callable_binding,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .field_default,
            => saved_source_region_override,
        };
        const body = if (root.literalConversionKind() != null) blk: {
            const ret_ty = try self.activeTypeFromCell(ret_cell);
            break :blk try self.lowerNumeralRootBody(wrapper.body_expr, ret_ty);
        } else switch (root.kind) {
            // A field default's root body is an ordinary pure expression
            // (design.md "Defaulted Fields"); it lowers through the general
            // comptime-root path.
            .constant,
            .hoisted_constant,
            .callable_binding,
            .expect,
            .field_default,
            => try self.lowerComptimeRootExprAtCell(wrapper.body_expr, ret_cell),
            .numeral_conversion,
            .quote_conversion,
            => Common.invariant("literal-conversion root bypassed literal-conversion lowering"),
        };
        const declared_ret_node = try ret_cell.toGraphNode(self.graph);
        const body_ret_cell = self.exprTypeCell(body);
        const body_ret_node = try body_ret_cell.toGraphNode(self.graph);
        const produced_ret_cell = if (self.graph.sameClass(declared_ret_node, body_ret_node))
            ret_cell
        else if (try self.resultCompletesRequest(declared_ret_node, body_ret_node) or
            try self.graph.containsGeneratedPrivate(body_ret_node) or
            self.exprCarriesFunctionDefinitionEvidence(body))
            body_ret_cell
        else blk: {
            try relateRequestComponent(self.graph, declared_ret_node, body_ret_node);
            break :blk ret_cell;
        };
        self.draft.exprs.items[@intFromEnum(body)].ty = produced_ret_cell;
        return .{ .args = .empty(), .body = body, .ret = produced_ret_cell };
    }

    fn instantiateTemplateDispatchRelations(
        self: *BodyContext,
        template: checked.CheckedProcedureTemplate,
        scope_id: ?checked.DispatchScopeId,
    ) Allocator.Error!void {
        const span = template.dispatch_relations;
        const refs = self.view.static_dispatch_plans.dispatch_relation_refs[span.start .. span.start + span.len];
        const scopes = self.view.templates.dispatch_ref_scopes[span.start .. span.start + span.len];
        const kinds = self.view.templates.dispatch_relation_kinds[span.start .. span.start + span.len];
        if (refs.len != scopes.len or refs.len != kinds.len) Common.invariant("checked template dispatch refs and relation metadata differed in length");

        // Resolve every plan in this scope before instantiating any of its type
        // relations. A rejected inner dispatch makes every enclosing expression
        // that evaluates it divergent, so relation replay must consume the
        // complete specialization-specific divergence column, not only the
        // entries discovered earlier in source order.
        var added_crash = false;
        for (refs, scopes) |plan_id, dispatch_scope| {
            if (!dispatchRefBelongsToScope(dispatch_scope, scope_id)) continue;
            const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
            switch (self.dispatchRuntimePlan(plan)) {
                .callable => {},
                .crash => {
                    added_crash = (try self.recordSpecializationDispatchCrash(plan.expr)) or added_crash;
                },
            }
        }
        if (added_crash) try self.refreshSpecializationDispatchDivergence();

        for (refs, scopes, kinds) |plan_id, dispatch_scope, relation_kind| {
            if (!dispatchRefBelongsToScope(dispatch_scope, scope_id)) continue;
            const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
            if (self.checkedExprDivergesInLoweredRuntime(plan.expr)) continue;
            if (relation_kind == .conversion) continue;
            const callable_plan = switch (self.dispatchRuntimePlan(plan)) {
                .callable => |value| value,
                .crash => Common.invariant("non-divergent dispatch relation resolved to a crash"),
            };
            const expr_ty = self.view.bodies.expr(plan.expr).ty;
            _ = try self.callableDispatchResultTypeNodeInPhase(
                expr_ty,
                callable_plan,
                null,
                .template_relation_replay,
            );
        }
    }

    fn dispatchRefBelongsToScope(
        dispatch_scope: checked.DispatchScope,
        scope_id: ?checked.DispatchScopeId,
    ) bool {
        return if (scope_id) |wanted_scope|
            switch (dispatch_scope) {
                .root => false,
                .generalized => |id| id == wanted_scope,
            }
        else switch (dispatch_scope) {
            .root => true,
            .generalized => false,
        };
    }

    fn recordSpecializationDispatchCrash(
        self: *BodyContext,
        expr: checked.CheckedExprId,
    ) Allocator.Error!bool {
        if (!self.owns_specialization_dispatch_crashes) {
            const previous = self.specialization_dispatch_crashes orelse &.{};
            const crashes = try self.allocator.alloc(bool, self.view.bodies.exprCount());
            @memset(crashes, false);
            if (previous.len != 0) {
                if (previous.len != crashes.len) {
                    Common.invariant("specialization dispatch crash array length differed from checked body expression count");
                }
                @memcpy(crashes, previous);
            }
            self.specialization_dispatch_crashes = crashes;
            self.owns_specialization_dispatch_crashes = true;
        }
        const crashes = self.specialization_dispatch_crashes.?;
        const raw = @intFromEnum(expr);
        if (raw >= crashes.len) Common.invariant("specialization dispatch crash referenced a missing checked expression");
        if (crashes[raw]) return false;
        crashes[raw] = true;
        return true;
    }

    fn refreshSpecializationDispatchDivergence(self: *BodyContext) Allocator.Error!void {
        if (self.specialization_dispatch_divergence) |*divergence| divergence.deinit(self.allocator);
        self.specialization_dispatch_divergence = try checked.dispatchDivergenceForEvidence(
            self.allocator,
            self.view.bodies,
            self.view.static_dispatch_plans,
            self.specialization_dispatch_crashes.?,
        );
        self.borrowed_specialization_dispatch_divergence = null;
    }

    fn specializationDispatchDivergence(self: *const BodyContext) ?*const checked.DispatchDivergence {
        if (self.specialization_dispatch_divergence) |*divergence| return divergence;
        return self.borrowed_specialization_dispatch_divergence;
    }

    fn replayStoredEvidenceRelations(self: *BodyContext, chain: EvidenceChain) Allocator.Error!void {
        if (!names.procedureTemplateRefEql(chain.scope.owner, self.owner_template)) {
            Common.invariant("stored function evidence belonged to a different checked template");
        }
        if (chain.parent) |parent| try self.replayStoredEvidenceRelations(parent.*);
        const template = self.view.templates.get(self.owner_template.template);
        switch (chain.scope.lexical) {
            .root => try self.instantiateTemplateDispatchRelations(template, null),
            .generalized => |scope| try self.instantiateTemplateDispatchRelations(template, scope),
        }
    }

    fn lowerStrInspectIntrinsicAtNode(
        self: *BodyContext,
        fn_nodes: FunctionNodes,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredTemplateBody {
        if (fn_nodes.args.len != 1) Common.invariant("Str.inspect intrinsic requires exactly one argument");

        const arg_node = fn_nodes.args[0];
        const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
        const arg_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
        const local_expr = try self.addExprWithTypeCell(arg_cell, .{ .local = arg_local });
        const ret_ty = try self.activeTypeFromCell(ret_cell);
        const body = switch (self.graph.content(arg_node)) {
            // Rendering a function never inspects its nested signature. Keep
            // that signature graph-native so unresolved child cells survive
            // until the owning draft is sealed once.
            .func, .erased => try self.stringExpr("<function>", ret_ty),
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .zst => if (try self.graph.typeIsResolved(arg_node))
                try self.inspectCall(local_expr, try self.activeTypeFromNode(arg_node), ret_ty)
            else
                try self.deferInspectAtNode(local_expr, arg_node, ret_ty),
        };
        return .{
            .args = try self.draft.addTypedLocalSpan(&.{.{ .local = arg_local, .ty = arg_cell }}),
            .body = body,
            .ret = ret_cell,
        };
    }

    fn deferInspectAtNode(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const expr = try self.addExprWithTypeCell(.{ .sealed = ret_ty }, .pending_deferred);
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_inspects.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .value = value,
            .value_node = value_node,
            .ret_ty = ret_ty,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
            .impossibility_proof = try self.currentRuntimeImpossibilityProof(null),
        });
        return expr;
    }

    const RequestCompletion = enum {
        unchanged,
        completed,
        mismatch,
    };

    const RequestCompletionPair = struct {
        request: NodeId,
        produced: NodeId,
    };

    const ProducedValuePair = struct {
        request: NodeId,
        produced: NodeId,
    };

    const ProducedValueRowKind = enum {
        record,
        tag_union,
    };

    fn resultCompletesRequest(
        self: *BodyContext,
        request_ret_node: NodeId,
        produced_ret_node: NodeId,
    ) Allocator.Error!bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        var visiting = std.AutoHashMap(RequestCompletionPair, void).init(self.allocator);
        defer visiting.deinit();
        return (try self.requestCompletionRelation(request_ret_node, produced_ret_node, &visiting)) == .completed;
    }

    fn relateCheckedNodeToProducedValue(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
    ) Allocator.Error!NodeId {
        var visiting = std.AutoHashMap(ProducedValuePair, void).init(self.allocator);
        defer visiting.deinit();
        return try self.relateCheckedNodeToProducedValueInner(checked_node, produced_node, &visiting);
    }

    fn relateCheckedNodeToProducedValueInner(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!NodeId {
        const checked_root = self.graph.rootNode(checked_node);
        const produced_root = self.graph.rootNode(produced_node);
        if (checked_root == produced_root) return checked_node;

        const pair = ProducedValuePair{ .request = checked_root, .produced = produced_root };
        const entry = try visiting.getOrPut(pair);
        if (entry.found_existing) return produced_node;
        defer _ = visiting.remove(pair);

        if (try self.producedRuntimeValueIsProvenUninhabited(produced_root)) return produced_node;
        const checked_private = try self.graph.containsGeneratedPrivate(checked_root);
        const produced_private = try self.graph.containsGeneratedPrivate(produced_root);
        if (checked_private or produced_private) {
            try relateRequestComponent(self.graph, checked_root, produced_root);
            return if (produced_private) produced_node else checked_node;
        }
        if (try self.resultCompletesRequest(checked_root, produced_root)) return produced_node;
        if (try self.relateMatchingProducedValueContainers(checked_root, produced_root, visiting)) |witness| {
            return witness;
        }
        try self.graph.unify(checked_root, produced_root);
        return checked_node;
    }

    fn producedValueHasExplicitRepresentationEvidence(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
    ) Allocator.Error!bool {
        var visiting = std.AutoHashMap(ProducedValuePair, void).init(self.allocator);
        defer visiting.deinit();
        return try self.producedValueHasExplicitRepresentationEvidenceInner(
            checked_node,
            produced_node,
            &visiting,
        );
    }

    fn producedValueHasExplicitRepresentationEvidenceInner(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!bool {
        const checked_root = self.graph.rootNode(checked_node);
        const produced_root = self.graph.rootNode(produced_node);
        if (checked_root == produced_root) return false;
        if (try self.graph.containsGeneratedPrivate(checked_root)) return true;
        if (try self.graph.containsGeneratedPrivate(produced_root)) return true;
        if (try self.resultCompletesRequest(checked_root, produced_root)) return true;

        const pair = ProducedValuePair{ .request = checked_root, .produced = produced_root };
        const entry = try visiting.getOrPut(pair);
        if (entry.found_existing) return false;
        defer _ = visiting.remove(pair);

        const checked_content = self.graph.content(checked_root);
        const produced_content = self.graph.content(produced_root);
        switch (checked_content) {
            .named => |checked_named| switch (produced_content) {
                .named => |produced_named| {
                    if (!sameNamedValueDefinition(checked_named, produced_named)) return false;
                    const checked_backing = checked_named.backing orelse return false;
                    const produced_backing = produced_named.backing orelse return false;
                    return try self.producedValueHasExplicitRepresentationEvidenceInner(
                        checked_backing.node,
                        produced_backing.node,
                        visiting,
                    );
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
            },
            .func => |checked_fn| switch (produced_content) {
                .func => |produced_fn| return checked_fn.args.len == produced_fn.args.len,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .list => |checked_elem| switch (produced_content) {
                .list => |produced_elem| return try self.producedValueHasExplicitRepresentationEvidenceInner(
                    checked_elem,
                    produced_elem,
                    visiting,
                ),
                .redirect, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .box => |checked_elem| switch (produced_content) {
                .box => |produced_elem| return try self.producedValueHasExplicitRepresentationEvidenceInner(
                    checked_elem,
                    produced_elem,
                    visiting,
                ),
                .redirect, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .tuple => |checked_items| switch (produced_content) {
                .tuple => |produced_items| {
                    if (checked_items.len != produced_items.len) return false;
                    var has_evidence = false;
                    for (checked_items, produced_items) |checked_item, produced_item| {
                        if (self.graph.sameClass(checked_item, produced_item)) continue;
                        if (!try self.producedValueHasExplicitRepresentationEvidenceInner(
                            checked_item,
                            produced_item,
                            visiting,
                        )) return false;
                        has_evidence = true;
                    }
                    return has_evidence;
                },
                .redirect, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .record => |checked_row| switch (produced_content) {
                .record => |produced_row| return try self.recordValueHasExplicitRepresentationEvidence(
                    checked_row,
                    produced_row,
                    visiting,
                ),
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .tag_union => |checked_row| switch (produced_content) {
                .tag_union => |produced_row| return try self.tagValueHasExplicitRepresentationEvidence(
                    checked_row,
                    produced_row,
                    visiting,
                ),
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return false,
            },
            .redirect, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => return false,
        }
    }

    fn recordValueHasExplicitRepresentationEvidence(
        self: *BodyContext,
        checked_row: anytype,
        produced_row: anytype,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!bool {
        if (checked_row.fields.len != produced_row.fields.len) return false;
        if (!self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .record)) return false;
        var has_evidence = false;
        for (checked_row.fields, produced_row.fields) |checked_field, produced_field| {
            if (checked_field.name != produced_field.name) return false;
            if (self.graph.sameClass(checked_field.ty, produced_field.ty)) continue;
            if (!try self.producedValueHasExplicitRepresentationEvidenceInner(
                checked_field.ty,
                produced_field.ty,
                visiting,
            )) return false;
            has_evidence = true;
        }
        return has_evidence;
    }

    fn tagValueHasExplicitRepresentationEvidence(
        self: *BodyContext,
        checked_row: anytype,
        produced_row: anytype,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!bool {
        if (checked_row.tags.len != produced_row.tags.len) return false;
        if (!self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .tag_union)) return false;
        var has_evidence = false;
        for (checked_row.tags, produced_row.tags) |checked_tag, produced_tag| {
            if (checked_tag.name != produced_tag.name or checked_tag.payloads.len != produced_tag.payloads.len) {
                return false;
            }
            for (checked_tag.payloads, produced_tag.payloads) |checked_payload, produced_payload| {
                if (self.graph.sameClass(checked_payload, produced_payload)) continue;
                if (!try self.producedValueHasExplicitRepresentationEvidenceInner(
                    checked_payload,
                    produced_payload,
                    visiting,
                )) return false;
                has_evidence = true;
            }
        }
        return has_evidence;
    }

    fn relateMatchingProducedValueContainers(
        self: *BodyContext,
        checked_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!?NodeId {
        const checked_content = self.graph.content(checked_node);
        const produced_content = self.graph.content(produced_node);
        switch (checked_content) {
            .named => |checked_named| switch (produced_content) {
                .named => |produced_named| {
                    if (!sameNamedValueDefinition(checked_named, produced_named)) return null;
                    const checked_backing = checked_named.backing orelse return null;
                    const produced_backing = produced_named.backing orelse return null;
                    const backing = try self.relateCheckedNodeToProducedValueInner(
                        checked_backing.node,
                        produced_backing.node,
                        visiting,
                    );
                    if (self.graph.sameClass(backing, produced_backing.node)) return produced_node;
                    var witness = produced_named;
                    witness.backing = .{
                        .node = backing,
                        .use = produced_backing.use,
                        .authority = produced_backing.authority,
                    };
                    return try self.graph.newNode(.{ .named = witness });
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
            },
            .list => |checked_elem| switch (produced_content) {
                .list => |produced_elem| {
                    const elem = try self.relateCheckedNodeToProducedValueInner(checked_elem, produced_elem, visiting);
                    if (self.graph.sameClass(elem, produced_elem)) return produced_node;
                    return try self.graph.newNode(.{ .list = elem });
                },
                .redirect, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .box => |checked_elem| switch (produced_content) {
                .box => |produced_elem| {
                    const elem = try self.relateCheckedNodeToProducedValueInner(checked_elem, produced_elem, visiting);
                    if (self.graph.sameClass(elem, produced_elem)) return produced_node;
                    return try self.graph.newNode(.{ .box = elem });
                },
                .redirect, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .tuple => |checked_items| switch (produced_content) {
                .tuple => |produced_items| {
                    if (checked_items.len != produced_items.len) return null;
                    const items = try self.graph.arena().alloc(NodeId, produced_items.len);
                    var changed = false;
                    for (checked_items, produced_items, items) |checked_item, produced_item, *out| {
                        const item = try self.relateCheckedNodeToProducedValueInner(checked_item, produced_item, visiting);
                        out.* = item;
                        changed = changed or !self.graph.sameClass(item, produced_item);
                    }
                    if (!changed) return produced_node;
                    return try self.graph.newNode(.{ .tuple = items });
                },
                .redirect, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .func => |checked_fn| switch (produced_content) {
                .func => |produced_fn| {
                    if (checked_fn.args.len != produced_fn.args.len) return null;
                    return checked_node;
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .record => |checked_row| switch (produced_content) {
                .record => |produced_row| {
                    return try self.producedRecordValueWitness(checked_row, produced_row, produced_node, visiting);
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .tag_union => |checked_row| switch (produced_content) {
                .tag_union => |produced_row| {
                    return try self.producedTagValueWitness(checked_row, produced_row, produced_node, visiting);
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
            },
            .redirect, .unresolved, .primitive, .empty_tag_union, .empty_record, .erased, .zst => return null,
        }
    }

    fn rowExtsAreValueCompatible(self: *BodyContext, checked_ext: NodeId, produced_ext: NodeId, kind: ProducedValueRowKind) bool {
        const checked_root = self.graph.rootNode(checked_ext);
        const produced_root = self.graph.rootNode(produced_ext);
        if (checked_root == produced_root) return true;
        return switch (self.graph.content(checked_root)) {
            .empty_record => kind == .record and self.graph.content(produced_root) == .empty_record,
            .empty_tag_union => kind == .tag_union and self.graph.content(produced_root) == .empty_tag_union,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .named, .erased, .zst => false,
        };
    }

    fn producedRecordValueWitness(
        self: *BodyContext,
        checked_row: anytype,
        produced_row: anytype,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!?NodeId {
        if (checked_row.fields.len != produced_row.fields.len) return null;
        if (!self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .record)) return null;
        const fields = try self.graph.arena().alloc(InstField, produced_row.fields.len);
        var changed = false;
        for (checked_row.fields, produced_row.fields, fields) |checked_field, produced_field, *out| {
            if (checked_field.name != produced_field.name) return null;
            const ty = try self.relateCheckedNodeToProducedValueInner(checked_field.ty, produced_field.ty, visiting);
            out.* = .{
                .name = produced_field.name,
                .ty = ty,
                .value_ty = produced_field.value_ty,
                .kind = produced_field.kind,
                .default = produced_field.default,
            };
            changed = changed or !self.graph.sameClass(ty, produced_field.ty);
        }
        if (!changed) return produced_node;
        return try self.graph.newNode(.{ .record = .{
            .fields = fields,
            .ext = self.graph.rootNode(produced_row.ext),
        } });
    }

    fn producedTagValueWitness(
        self: *BodyContext,
        checked_row: anytype,
        produced_row: anytype,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(ProducedValuePair, void),
    ) Allocator.Error!?NodeId {
        if (checked_row.tags.len != produced_row.tags.len) return null;
        if (!self.rowExtsAreValueCompatible(checked_row.ext, produced_row.ext, .tag_union)) return null;
        const tags = try self.graph.arena().alloc(InstTag, produced_row.tags.len);
        var changed = false;
        for (checked_row.tags, produced_row.tags, tags) |checked_tag, produced_tag, *out| {
            if (checked_tag.name != produced_tag.name or checked_tag.payloads.len != produced_tag.payloads.len) return null;
            const payloads = try self.graph.arena().alloc(NodeId, produced_tag.payloads.len);
            for (checked_tag.payloads, produced_tag.payloads, payloads) |checked_payload, produced_payload, *payload_out| {
                const payload = try self.relateCheckedNodeToProducedValueInner(checked_payload, produced_payload, visiting);
                payload_out.* = payload;
                changed = changed or !self.graph.sameClass(payload, produced_payload);
            }
            out.* = .{
                .name = produced_tag.name,
                .checked_name = produced_tag.checked_name,
                .payloads = payloads,
            };
        }
        if (!changed) return produced_node;
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = self.graph.rootNode(produced_row.ext),
        } });
    }

    fn requestCompletionRelation(
        self: *BodyContext,
        request_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!RequestCompletion {
        const request_root = self.graph.rootNode(request_node);
        const produced_root = self.graph.rootNode(produced_node);
        if (request_root == produced_root) return .unchanged;
        if (try self.nodeIsProvenUninhabited(request_root) and
            !try self.nodeIsProvenUninhabited(produced_root))
        {
            return .completed;
        }

        const pair = RequestCompletionPair{ .request = request_root, .produced = produced_root };
        const entry = try visiting.getOrPut(pair);
        if (entry.found_existing) return .unchanged;
        defer _ = visiting.remove(pair);

        if (try self.producedPublicNamedBackingCompletion(request_root, produced_root, visiting)) |relation| {
            return relation;
        }
        if (try self.requestPublicNamedBackingCompletion(request_root, produced_root, visiting)) |relation| {
            return relation;
        }

        return switch (self.graph.content(request_root)) {
            .primitive => |request_primitive| switch (self.graph.content(produced_root)) {
                .primitive => |produced_primitive| if (request_primitive == produced_primitive) .unchanged else .mismatch,
                .redirect, .unresolved, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .list => |request_elem| switch (self.graph.content(produced_root)) {
                .list => |produced_elem| try self.requestCompletionRelation(request_elem, produced_elem, visiting),
                .redirect, .unresolved, .primitive, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .box => |request_elem| switch (self.graph.content(produced_root)) {
                .box => |produced_elem| try self.requestCompletionRelation(request_elem, produced_elem, visiting),
                .redirect, .unresolved, .primitive, .list, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .tuple => |request_items| switch (self.graph.content(produced_root)) {
                .tuple => |produced_items| try self.requestCompletionSliceRelation(request_items, produced_items, visiting),
                .redirect, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .func => |request_fn| switch (self.graph.content(produced_root)) {
                .func => |produced_fn| try self.requestCompletionFunctionRelation(request_fn, produced_fn, visiting),
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .tag_union => |request_row| switch (self.graph.content(produced_root)) {
                .tag_union => |produced_row| try self.requestCompletionTagRowRelation(request_row, produced_row, visiting),
                .empty_tag_union => .mismatch,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .record => |request_row| switch (self.graph.content(produced_root)) {
                .record => |produced_row| try self.requestCompletionRecordRelation(request_row, produced_row, visiting),
                .empty_record => .mismatch,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .named, .erased, .zst => .mismatch,
            },
            .empty_tag_union => switch (self.graph.content(produced_root)) {
                .empty_tag_union => .unchanged,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_record, .named, .erased, .zst => .mismatch,
            },
            .empty_record => switch (self.graph.content(produced_root)) {
                .empty_record => .unchanged,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .named, .erased, .zst => .mismatch,
            },
            .erased => |request_digest| switch (self.graph.content(produced_root)) {
                .erased => |produced_digest| if (std.mem.eql(u8, request_digest.bytes[0..], produced_digest.bytes[0..])) .unchanged else .mismatch,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .zst => .mismatch,
            },
            .zst => switch (self.graph.content(produced_root)) {
                .zst => .unchanged,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased => .mismatch,
            },
            .named,
            .unresolved,
            .redirect,
            => .mismatch,
        };
    }

    fn producedPublicNamedBackingCompletion(
        self: *BodyContext,
        request_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!?RequestCompletion {
        const backing = self.checkedPublicInspectableBacking(produced_node) orelse return null;

        return switch (try self.requestCompletionRelation(request_node, backing.node, visiting)) {
            .unchanged, .completed => .completed,
            .mismatch => .mismatch,
        };
    }

    fn requestPublicNamedBackingCompletion(
        self: *BodyContext,
        request_node: NodeId,
        produced_node: NodeId,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!?RequestCompletion {
        const backing = self.checkedPublicInspectableBacking(request_node) orelse return null;

        return switch (try self.requestCompletionRelation(backing.node, produced_node, visiting)) {
            .unchanged, .completed => .completed,
            .mismatch => .mismatch,
        };
    }

    fn checkedPublicInspectableBacking(self: *BodyContext, node: NodeId) ?InstBacking {
        const named = switch (self.graph.content(node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
        };
        const backing = named.backing orelse return null;
        if (backing.authority != .checked_public or backing.use != .inspectable) return null;
        return backing;
    }

    fn requestCompletionSliceRelation(
        self: *BodyContext,
        request_items: []const NodeId,
        produced_items: []const NodeId,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!RequestCompletion {
        if (request_items.len != produced_items.len) return .mismatch;
        var relation: RequestCompletion = .unchanged;
        for (request_items, produced_items) |request_item, produced_item| {
            switch (try self.requestCompletionRelation(request_item, produced_item, visiting)) {
                .unchanged => {},
                .completed => relation = .completed,
                .mismatch => return .mismatch,
            }
        }
        return relation;
    }

    fn requestCompletionFunctionRelation(
        self: *BodyContext,
        request_fn: anytype,
        produced_fn: anytype,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!RequestCompletion {
        if (request_fn.args.len != produced_fn.args.len) return .mismatch;
        for (request_fn.args, produced_fn.args) |request_arg, produced_arg| {
            if (!self.graph.sameClass(request_arg, produced_arg)) return .mismatch;
        }
        return try self.requestCompletionRelation(request_fn.ret, produced_fn.ret, visiting);
    }

    fn requestCompletionTagRowRelation(
        self: *BodyContext,
        request_row: anytype,
        produced_row: anytype,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!RequestCompletion {
        if ((try self.requestCompletionRelation(request_row.ext, produced_row.ext, visiting)) != .unchanged) {
            return .mismatch;
        }
        if (request_row.tags.len != produced_row.tags.len) return .mismatch;
        var relation: RequestCompletion = .unchanged;
        for (request_row.tags, produced_row.tags) |request_tag, produced_tag| {
            if (request_tag.name != produced_tag.name) return .mismatch;
            switch (try self.requestCompletionSliceRelation(request_tag.payloads, produced_tag.payloads, visiting)) {
                .unchanged => {},
                .completed => relation = .completed,
                .mismatch => return .mismatch,
            }
        }
        return relation;
    }

    fn requestCompletionRecordRelation(
        self: *BodyContext,
        request_row: anytype,
        produced_row: anytype,
        visiting: *std.AutoHashMap(RequestCompletionPair, void),
    ) Allocator.Error!RequestCompletion {
        if ((try self.requestCompletionRelation(request_row.ext, produced_row.ext, visiting)) != .unchanged) {
            return .mismatch;
        }
        if (request_row.fields.len != produced_row.fields.len) return .mismatch;
        var relation: RequestCompletion = .unchanged;
        for (request_row.fields, produced_row.fields) |request_field, produced_field| {
            if (request_field.name != produced_field.name) return .mismatch;
            switch (try self.requestCompletionRelation(request_field.ty, produced_field.ty, visiting)) {
                .unchanged => {},
                .completed => relation = .completed,
                .mismatch => return .mismatch,
            }
        }
        return relation;
    }

    fn completedFunctionNodeForLoweredRet(
        self: *BodyContext,
        fn_node: NodeId,
        lowered_ret: DraftTypeCell,
        has_explicit_value_witness: bool,
    ) Allocator.Error!NodeId {
        const function = try self.graph.functionNodes(fn_node);
        const lowered_ret_node = try lowered_ret.toGraphNode(self.graph);
        if (self.graph.sameClass(function.ret, lowered_ret_node)) return fn_node;
        const completes_request = try self.resultCompletesRequest(function.ret, lowered_ret_node);
        const contains_generated_private = try self.graph.containsGeneratedPrivate(lowered_ret_node);
        if (!completes_request and !contains_generated_private and !has_explicit_value_witness) {
            try relateRequestComponent(self.graph, function.ret, lowered_ret_node);
            return fn_node;
        }
        const completed_fn = try self.graphFunctionNode(function.args, lowered_ret_node);
        if (try self.graph.containsGeneratedPrivate(completed_fn) and
            self.graph.requestSourceInterface(completed_fn) == null)
        {
            const source_interface = self.graph.requestSourceInterface(fn_node) orelse fn_node;
            try self.graph.registerRequestSourceInterface(completed_fn, source_interface);
        }
        return completed_fn;
    }

    fn lowerLambdaTemplateAtNode(
        self: *BodyContext,
        lambda_id: checked.CheckedExprId,
        lambda: anytype,
        fn_node: NodeId,
    ) Allocator.Error!LoweredTemplateBody {
        const fn_nodes = try self.graph.functionNodes(fn_node);
        if (fn_nodes.args.len != lambda.args.len) Common.invariant("lambda template arity differs from concrete function type");

        const lowered = try self.lowerLambdaArgsAndBodyAtCell(
            lambda_id,
            lambda.args,
            fn_nodes.args,
            lambda.body,
            DraftTypeCell.fromGraphNode(fn_nodes.ret),
        );
        return .{
            .args = lowered.args,
            .body = lowered.body,
            .ret = lowered.ret,
        };
    }

    fn lowerLambdaArgsAndBodyAtCell(
        self: *BodyContext,
        lambda_id: checked.CheckedExprId,
        checked_args: []const checked.CheckedPatternId,
        arg_nodes: []const NodeId,
        checked_body: checked.CheckedExprId,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!LoweredLambdaArgs {
        if (arg_nodes.len != checked_args.len) Common.invariant("lambda arity differs from concrete function type");
        const saved_return_target = self.current_return_target;
        defer self.current_return_target = saved_return_target;
        self.current_return_target = .{ .lambda = lambda_id, .cell = ret_cell };
        const saved_loc = self.builder.program.current_loc;
        defer self.builder.program.current_loc = saved_loc;
        const saved_region = self.builder.program.current_region;
        defer self.builder.program.current_region = saved_region;
        const body_expr = self.view.bodies.expr(checked_body);
        const body_region = self.sourceRegionForExpr(body_expr);
        self.builder.program.current_loc = try self.sourceLocFor(body_region);
        self.builder.program.current_region = body_region;

        const exhaustiveness_scope = self.comptime_exhaustiveness_context.resetForRuntimeFunction();
        defer exhaustiveness_scope.leave();

        for (arg_nodes, 0..) |arg_node, uninhabited_index| {
            if (!try self.nodeIsProvenUninhabited(arg_node)) continue;
            const args = try self.allocator.alloc(DraftTypedLocal, checked_args.len);
            defer self.allocator.free(args);
            for (arg_nodes, 0..) |node, index| {
                const cell = DraftTypeCell.fromGraphNode(node);
                args[index] = .{ .local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null), .ty = cell };
            }
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            const scrutinee = try self.addExprWithTypeCell(arg_cell, .{ .local = args[uninhabited_index].local });
            const body = try self.addExprWithTypeCell(ret_cell, .{ .match_ = .{
                .scrutinee = scrutinee,
                .branches = try self.addBranchSpan(&.{}),
            } });
            return .{
                .args = try self.draft.addTypedLocalSpan(args),
                .body = body,
                .ret = ret_cell,
            };
        }

        const args = try self.allocator.alloc(DraftTypedLocal, checked_args.len);
        defer self.allocator.free(args);
        var arg_lets = std.ArrayList(LambdaArgLet).empty;
        defer arg_lets.deinit(self.allocator);
        var arg_literal_guards = std.ArrayList(PatternLiteralGuard).empty;
        defer arg_literal_guards.deinit(self.allocator);
        var materialized_args = std.ArrayList(MaterializedArg).empty;
        defer materialized_args.deinit(self.allocator);

        for (checked_args, arg_nodes, 0..) |pattern_id, arg_node, i| {
            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            try relateRequestComponent(
                self.graph,
                try self.instNode(self.view.bodies.pattern(pattern_id).ty),
                arg_node,
            );
            if (self.patternIsShapeFree(pattern_id)) {
                const pat = try self.lowerShapeFreePatternAtCell(pattern_id, arg_cell);
                switch (self.patData(pat)) {
                    .bind => |local| args[i] = .{ .local = local, .ty = arg_cell },
                    .wildcard, .as, .record, .tuple, .list, .tag, .nominal, .int_lit, .dec_lit, .frac_f32_lit, .frac_f64_lit, .str_lit, .str_pattern => {
                        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
                        args[i] = .{ .local = local, .ty = arg_cell };
                        const value = try self.addExprWithTypeCell(arg_cell, .{ .local = local });
                        try arg_lets.append(self.allocator, .{ .pat = pat, .value = value });
                    },
                }
                continue;
            }
            if (try self.patternNeedsExplicitBinding(pattern_id)) {
                const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), arg_cell, null);
                args[i] = .{ .local = local, .ty = arg_cell };
                const value = try self.addExprWithTypeCell(arg_cell, .{ .local = local });
                try materialized_args.append(self.allocator, .{
