    fn parserPrecomputedRecordShapesForTagUnion(
        self: *BodyContext,
        plan: ?*const ParserPrecomputedPlan,
        union_ty: Type.TypeId,
    ) Allocator.Error![]Type.TypeId {
        var shapes = std.ArrayList(Type.TypeId).empty;
        errdefer shapes.deinit(self.allocator);
        var seen = collections.DenseMap(Type.TypeId, void).init(self.allocator);
        defer seen.deinit();

        try self.appendParserPrecomputedRecordShapes(plan, &shapes, &seen, union_ty);
        return try shapes.toOwnedSlice(self.allocator);
    }

    fn appendParserPrecomputedRecordShapes(
        self: *BodyContext,
        plan: ?*const ParserPrecomputedPlan,
        shapes: *std.ArrayList(Type.TypeId),
        seen: *collections.DenseMap(Type.TypeId, void),
        shape_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, info.ok_payload_ty);
        }
        if ((try self.customParserLookup(shape_ty)) != null) return;
        if (self.parseScalarMethodName(shape_ty) != null) return;
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, payload_ty);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, dict_shape);
            }
            return;
        }

        if (seen.contains(shape_ty)) return;
        try seen.put(shape_ty, {});

        switch (self.builder.shapeContent(shape_ty)) {
            .list => |elem_ty| try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, elem_ty),
            .box => |payload_ty| try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, payload_ty),
            .tuple => |span| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(span));
                defer self.allocator.free(item_tys);
                for (item_tys) |elem_ty| {
                    try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, elem_ty);
                }
            },
            .record, .zst => {
                if (plan == null or self.parserPlanContains(plan.?, shape_ty)) {
                    try shapes.append(self.allocator, shape_ty);
                }
                const fields = try self.dupeRecordFieldsForShape(shape_ty);
                defer self.allocator.free(fields);
                for (fields) |field| {
                    try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, field.ty);
                }
            },
            .tag_union => |span| {
                const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(span));
                defer self.allocator.free(tags);
                for (tags) |tag| {
                    const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(tag.payloads));
                    defer self.allocator.free(payload_tys);
                    for (payload_tys) |payload_ty| {
                        try self.appendParserPrecomputedRecordShapes(plan, shapes, seen, payload_ty);
                    }
                }
            },
            .primitive, .named, .func, .erased => {},
        }
    }

    fn generatedParseTagUnionSpecBackingRecordFieldName(
        self: *BodyContext,
        index: usize,
    ) Allocator.Error!names.RecordFieldNameId {
        const label = try std.fmt.allocPrint(self.allocator, "record_{d:0>20}", .{index});
        defer self.allocator.free(label);
        return try self.builder.program.names.internRecordFieldLabel(label);
    }

    fn generatedParseTagUnionSpecBackingFieldName(
        self: *BodyContext,
        index: usize,
    ) Allocator.Error!names.RecordFieldNameId {
        const label = try std.fmt.allocPrint(self.allocator, "field_{d:0>20}", .{index});
        defer self.allocator.free(label);
        return try self.builder.program.names.internRecordFieldLabel(label);
    }

    fn lowerParseTagUnionSpecValue(
        self: *BodyContext,
        spec_ty: Type.TypeId,
        spec_backing_ty: Type.TypeId,
        record_shapes: []const Type.TypeId,
        plan: *const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.builder.primitiveType(.str);
        const backing_fields = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(spec_backing_ty)));
        defer self.allocator.free(backing_fields);
        if (backing_fields.len != record_shapes.len) Common.invariant("generated tag-union spec backing arity differed from record shape count");

        const outer_values = try self.allocator.alloc(DraftFieldExpr, record_shapes.len);
        defer self.allocator.free(outer_values);

        for (record_shapes, backing_fields, 0..) |record_shape, backing_field, record_index| {
            const precomputed = self.parserPlanGet(plan, record_shape) orelse
                Common.invariant("generated tag-union spec requested missing parser precomputed record");
            const inner_fields = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(backing_field.ty)));
            defer self.allocator.free(inner_fields);
            if (inner_fields.len != precomputed.renamed_field_locals.len) {
                Common.invariant("generated tag-union spec record arity differed from precomputed record");
            }

            const inner_values = try self.allocator.alloc(DraftFieldExpr, inner_fields.len);
            defer self.allocator.free(inner_values);
            for (inner_fields, precomputed.renamed_field_locals, 0..) |inner_field, renamed_local, field_index| {
                inner_values[field_index] = .{
                    .name = inner_field.name,
                    .value = try self.localExpr(renamed_local, str_ty),
                };
            }

            outer_values[record_index] = .{
                .name = backing_field.name,
                .value = try self.addExpr(.{
                    .ty = backing_field.ty,
                    .data = .{ .record = try self.addFieldExprSpan(inner_values) },
                }),
            };
        }

        const backing_expr = try self.addExpr(.{
            .ty = spec_backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(outer_values) },
        });
        return try self.addExpr(.{
            .ty = spec_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn buildParserPrecomputedPlanFromTagUnionSpec(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        spec_backing_local: DraftLocalId,
        spec_backing_ty: Type.TypeId,
        union_ty: Type.TypeId,
    ) Allocator.Error!void {
        const record_shapes = try self.parserPrecomputedRecordShapesForTagUnion(null, union_ty);
        defer self.allocator.free(record_shapes);

        const backing_fields = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(spec_backing_ty)));
        defer self.allocator.free(backing_fields);
        if (backing_fields.len != record_shapes.len) {
            Common.invariant("generated tag-union spec backing arity differed from payload record shape count");
        }

        const str_ty = try self.builder.primitiveType(.str);
        for (record_shapes, backing_fields) |record_shape, backing_field| {
            if (self.parserPlanContains(plan, record_shape)) continue;

            const record_fields = try self.dupeRecordFieldsForShape(record_shape);
            defer self.allocator.free(record_fields);
            const backing_record_fields = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(backing_field.ty)));
            defer self.allocator.free(backing_record_fields);
            if (backing_record_fields.len != record_fields.len) {
                Common.invariant("generated tag-union spec record arity differed from payload record arity");
            }

            const locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
            const values = try self.allocator.alloc(DraftExprId, record_fields.len);
            var inserted = false;
            errdefer if (!inserted) {
                self.allocator.free(locals);
                self.allocator.free(values);
            };

            const record_expr = try self.addFieldAccessExpr(
                try self.localExpr(spec_backing_local, spec_backing_ty),
                backing_field.name,
                backing_field.ty,
            );

            for (backing_record_fields, 0..) |field, index| {
                if (!self.sameType(field.ty, str_ty)) {
                    Common.invariant("generated tag-union spec field name value was not Str");
                }
                locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                values[index] = try self.addFieldAccessExpr(record_expr, field.name, str_ty);
            }

            try self.parserPlanPut(plan, record_shape, .{
                .renamed_field_locals = locals,
                .renamed_field_values = values,
                .renamed_field_lengths = null,
                .renamed_field_texts = null,
            });
            inserted = true;

            try self.appendParserPrecomputedCaptures(plan, record_fields, locals, values);
        }
    }

    fn buildParserRestoredRecordPrecomputedPlan(
        self: *BodyContext,
        plan: *ParserPrecomputedPlan,
        fn_value: check.ConstStore.ConstFn,
        store_view: ModuleView,
        fn_view: ModuleView,
        shape_ty: Type.TypeId,
        str_ty: Type.TypeId,
    ) Allocator.Error!void {
        if (self.parserPlanContains(plan, shape_ty)) return;

        const fields = try self.dupeRecordFieldsForShape(shape_ty);
        defer self.allocator.free(fields);
        const locals = try self.allocator.alloc(DraftLocalId, fields.len);
        const values = try self.allocator.alloc(DraftExprId, fields.len);
        const lengths = try self.allocator.alloc(u32, fields.len);
        const texts = try self.allocator.alloc([]const u8, fields.len);
        var inserted = false;
        errdefer if (!inserted) {
            self.allocator.free(locals);
            self.allocator.free(values);
            self.allocator.free(lengths);
            self.allocator.free(texts);
        };

        const base_capture_id = plan.next_capture_id;
        plan.next_capture_id += fields.len;
        if (plan.next_capture_id > std.math.maxInt(u32)) Common.invariant("parser generated too many captures");

        for (fields, 0..) |_, index| {
            const capture_id = self.parserFieldCaptureIdForRecordField(fields, index, base_capture_id);
            const node = constGeneratedCaptureNode(fn_value, capture_id) orelse
                Common.invariant("stored parser runtime function was missing a renamed field capture");
            locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
            self.setLocalCaptureId(locals[index], capture_id);
            values[index] = try self.restoreConstNodeAtType(store_view, fn_view, node, str_ty);
            lengths[index] = constStrNodeByteLen(store_view, node);
            texts[index] = constStrNodeBytes(store_view, node);
        }

        try self.parserPlanPut(plan, shape_ty, .{
            .renamed_field_locals = locals,
            .renamed_field_values = values,
            .renamed_field_lengths = lengths,
            .renamed_field_texts = texts,
        });
        inserted = true;

        try self.appendParserPrecomputedCaptures(plan, fields, locals, values);

        for (fields) |field| {
            try self.buildParserRestoredPrecomputedPlan(plan, fn_value, store_view, fn_view, field.ty, str_ty);
        }
    }

    fn lowerParseShapeFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        // A nominal opaque with a scalar backing and no custom parser (e.g. `Username := Str`)
        // parses its backing scalar, then rewraps the value in the nominal.
        if (self.builder.nominalExprBackingType(shape_ty)) |backing_ty| {
            if (self.parseScalarMethodName(backing_ty) != null) {
                return try self.lowerParseNominalScalarFromState(shape_ty, backing_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            }
        }
        const selected = self.parseShapeSelection(shape_ty);
        if (Ident.textEql(selected.tag_text, "Record")) {
            const precomputed = if (precomputed_plan) |plan| self.parserPlanGet(plan, shape_ty) else null;
            return try self.lowerParseRecordFromState(
                shape_ty,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
                precomputed_plan,
                if (precomputed) |record| record.renamed_field_locals else null,
                if (precomputed) |record| record.renamed_field_lengths else null,
                if (precomputed) |record| record.renamed_field_texts else null,
            );
        }

        const method_name: []const u8 =
            if (Ident.textEql(selected.tag_text, "TagUnion"))
                "parse_tag_union"
            else
                selected.tag_text;

        const parse_lookup = try self.methodLookupForTypeName(encoding_ty, method_name);
        const parse_mono_ty = try self.frozenCodecCallableForShape(parse_lookup, shape_ty) orelse
            Common.invariant("parser format callable was not prepared before graph sealing");
        const parse_fn = self.builder.functionShape(parse_mono_ty, "parser target method was not a function");
        const parse_arg_tys = self.builder.program.types.span(parse_fn.args);
        if (!Ident.textEql(selected.tag_text, "TagUnion")) {
            if (parse_arg_tys.len != 2) Common.invariant("parser target scalar method had an unexpected arity");
            if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parser target encoding type differed from input encoding type");
            if (!self.sameType(GuardedList.at(parse_arg_tys, 1), state_ty)) Common.invariant("parser target state type differed from input state type");

            const parse_args = [_]DraftExprId{ encoding_expr, state_expr };
            return try self.addExpr(.{
                .ty = ret_ty,
                .data = .{ .call_proc = .{
                    .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(parse_lookup, parse_mono_ty, .synthesize)),
                    .args = try self.addExprSpan(&parse_args),
                    .captures = try self.methodTargetCaptureSpan(parse_lookup),
                } },
            });
        }
        if (parse_arg_tys.len != 3) Common.invariant("parser target tag-union method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parser target tag-union encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 2), state_ty)) Common.invariant("parser target tag-union state type differed from input state type");

        const record_shapes = if (precomputed_plan) |plan|
            try self.parserPrecomputedRecordShapesForTagUnion(plan, shape_ty)
        else
            &.{};
        defer if (precomputed_plan != null) self.allocator.free(record_shapes);

        const callable_mono_ty = parse_mono_ty;
        const callable_fn = self.builder.functionShape(callable_mono_ty, "parser target tag-union method was not a function");
        const callable_arg_tys = self.builder.program.types.span(callable_fn.args);
        if (callable_arg_tys.len != 3) Common.invariant("parser target tag-union method had an unexpected arity");
        const spec_ty = GuardedList.at(callable_arg_tys, 1);
        if (!self.sameType(GuardedList.at(callable_arg_tys, 0), encoding_ty)) Common.invariant("parser target tag-union encoding type differed from generated input encoding type");
        if (!self.sameType(GuardedList.at(callable_arg_tys, 1), spec_ty)) Common.invariant("parser target tag-union spec type differed from generated spec type");
        if (!self.sameType(GuardedList.at(callable_arg_tys, 2), state_ty)) Common.invariant("parser target tag-union state type differed from generated input state type");

        const final_spec_expr = blk: {
            const plan = precomputed_plan orelse Common.invariant("generated tag-union spec requested without a precomputed plan");
            const spec_backing_ty = self.builder.namedBackingType(spec_ty) orelse
                Common.invariant("generated tag-union spec had no backing type");
            break :blk try self.lowerParseTagUnionSpecValue(spec_ty, spec_backing_ty, record_shapes, plan);
        };
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(parse_lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, final_spec_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(parse_lookup),
            } },
        });
    }

    fn lowerParseNominalScalarFromState(
        self: *BodyContext,
        nominal_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const backing_parse_ok_ty = try self.parseResultOkType(backing_ty, state_ty);
        const backing_parse_ret_ty = try self.tryTypeLike(ret_ty, backing_parse_ok_ty, ret_info.err_ty);
        const backing_parse = try self.lowerParseShapeHelperCall(
            backing_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            backing_parse_ret_ty,
            precomputed_plan,
        );

        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const nominal_value = try self.addExpr(.{
            .ty = nominal_ty,
            .data = .{ .nominal = try self.localExpr(backing_local, backing_ty) },
        });
        const ok_body = try self.parseResultOk(ret_ty, nominal_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(backing_parse, backing_parse_ret_ty, backing_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    fn lowerParseRecordFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        precomputed_renamed_field_locals: ?[]const DraftLocalId,
        precomputed_renamed_field_lengths: ?[]const u32,
        precomputed_renamed_field_texts: ?[][]const u8,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const parse_ok_ty = try self.parseResultOkType(shape_ty, state_ty);
        if (!self.sameType(ret_info.ok_ty, parse_ok_ty)) Common.invariant("record parser return Ok type differed from generated parse result");

        const record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.builder.shapeContent(shape_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => self.builder.program.types.fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record parser requested for a non-record shape"),
        });
        defer self.allocator.free(record_fields);

        const u64_ty = try self.builder.primitiveType(.u64);
        const presence_word_count = recordPresenceWordCount(record_fields.len);
        const presence_locals = try self.allocator.alloc(DraftLocalId, presence_word_count);
        defer self.allocator.free(presence_locals);
        const presence_tys = try self.allocator.alloc(Type.TypeId, presence_word_count);
        defer self.allocator.free(presence_tys);
        const initial_presence_values = try self.allocator.alloc(DraftExprId, presence_word_count);
        defer self.allocator.free(initial_presence_values);
        for (presence_locals, 0..) |*local, index| {
            local.* = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
            presence_tys[index] = u64_ty;
            initial_presence_values[index] = try self.intLiteralExpr(0, u64_ty);
        }

        const payload_locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
        defer self.allocator.free(payload_locals);
        const payload_tys = try self.allocator.alloc(Type.TypeId, record_fields.len);
        defer self.allocator.free(payload_tys);
        const initial_payload_values = try self.allocator.alloc(DraftExprId, record_fields.len);
        defer self.allocator.free(initial_payload_values);
        for (record_fields, 0..) |field, index| {
            payload_tys[index] = field.ty;
            payload_locals[index] = try self.addLocal(self.builder.symbols.fresh(), field.ty);
            initial_payload_values[index] = try self.uninitializedPayloadExpr(
                field.ty,
                presence_locals[recordPresenceWordIndex(index)],
                recordPresenceMask(index),
            );
        }
        const record_slots = ParseRecordSlots{
            .presence_locals = presence_locals,
            .presence_tys = presence_tys,
            .payload_locals = payload_locals,
            .payload_tys = payload_tys,
        };

        const parse_lookup = try self.methodLookupForTypeName(encoding_ty, "parse_record_field");
        const callable_mono_ty = try self.frozenCodecCallableForShape(parse_lookup, shape_ty) orelse
            Common.invariant("record parser callable was not prepared before graph sealing");
        const parse_fn = self.builder.functionShape(callable_mono_ty, "parse_record_field target method was not a function");
        const parse_arg_tys = self.builder.program.types.span(parse_fn.args);
        if (parse_arg_tys.len != 3) Common.invariant("parse_record_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("parse_record_field encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 2), state_ty)) Common.invariant("parse_record_field state type differed from input state type");
        const fields_ty = GuardedList.at(parse_arg_tys, 1);
        const step_try_ty = parse_fn.ret;
        const step_try_info = self.tryInfo(step_try_ty);
        if (!self.sameType(step_try_info.err_ty, ret_info.err_ty)) Common.invariant("parse_record_field error type differed from structural parser error type");
        const event_ty = step_try_info.ok_ty;
        const field_handle_ty = try self.recordEventFieldHandleTemplate(event_ty);
        const fields_backing_ty = self.builder.namedBackingType(fields_ty) orelse
            Common.invariant("prepared parse_record_field field set had no backing type");

        const str_ty = try self.builder.primitiveType(.str);
        var owned_renamed_field_locals: ?[]DraftLocalId = null;
        defer if (owned_renamed_field_locals) |locals| self.allocator.free(locals);
        var owned_renamed_field_values: ?[]DraftExprId = null;
        defer if (owned_renamed_field_values) |values| self.allocator.free(values);

        const renamed_field_locals = if (precomputed_renamed_field_locals) |locals| blk: {
            if (locals.len != record_fields.len) Common.invariant("precomputed renamed field arity differed from record field count");
            break :blk locals;
        } else blk: {
            const locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
            const values = try self.allocator.alloc(DraftExprId, record_fields.len);
            owned_renamed_field_locals = locals;
            owned_renamed_field_values = values;

            for (record_fields, 0..) |field, index| {
                locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                values[index] = try self.renamedRecordFieldNameExpr(encoding_expr, encoding_ty, field, str_ty);
            }

            break :blk locals;
        };
        const renamed_field_lengths = if (precomputed_renamed_field_lengths) |lengths| blk: {
            if (lengths.len != record_fields.len) Common.invariant("precomputed renamed field length arity differed from record field count");
            break :blk lengths;
        } else null;
        const renamed_field_texts = if (precomputed_renamed_field_texts) |texts| blk: {
            if (texts.len != record_fields.len) Common.invariant("precomputed renamed field text arity differed from record field count");
            break :blk texts;
        } else null;

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const bool_ty = try self.builder.primitiveType(.bool);
        const ctl = RecordLoopCtl{
            .done_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };
        const fields_expr = try self.lowerFieldNamesValue(fields_ty, fields_backing_ty, field_handle_ty, renamed_field_locals, renamed_field_lengths);
        const fields_local = try self.addLocal(self.builder.symbols.fresh(), fields_ty);
        const step_expr = try self.addExpr(.{
            .ty = step_try_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(parse_lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{
                    encoding_expr,
                    try self.localExpr(fields_local, fields_ty),
                    try self.localExpr(cursor_local, state_ty),
                }),
                .captures = try self.methodTargetCaptureSpan(parse_lookup),
            } },
        });

        const event_local = try self.addLocal(self.builder.symbols.fresh(), event_ty);
        const event_body = try self.lowerParseRecordEvent(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            event_local,
            event_ty,
        );
        const step_body = try self.sequenceTry(step_expr, step_try_ty, event_local, event_body, ret_ty);

        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, u64_ty),
            try self.intLiteralExpr(0, u64_ty),
        }, bool_ty);
        const counted_finished = try self.ifExpr(
            try self.localExpr(ctl.counted_local, bool_ty),
            remaining_is_zero,
            try self.boolLiteral(false, bool_ty),
            bool_ty,
        );
        const finish_cond = try self.ifExpr(
            try self.localExpr(ctl.done_local, bool_ty),
            try self.boolLiteral(true, bool_ty),
            counted_finished,
            bool_ty,
        );
        const finish_body = try self.lowerParseRecordFinish(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            record_slots,
            renamed_field_locals,
            try self.localExpr(cursor_local, state_ty),
        );
        const loop_body = try self.ifExpr(finish_cond, finish_body, step_body, ret_ty);

        const params = try self.allocator.alloc(BodyTypedLocal, record_loop_slot_offset + record_slots.payload_locals.len + record_slots.presence_locals.len);
        defer self.allocator.free(params);
        params[0] = .{ .local = cursor_local, .ty = state_ty };
        params[1] = .{ .local = ctl.done_local, .ty = bool_ty };
        params[2] = .{ .local = ctl.counted_local, .ty = bool_ty };
        params[3] = .{ .local = ctl.remaining_local, .ty = u64_ty };
        // Payloads must be carried before presence words. LIR lowers continue
        // arguments into ordered `set_local` statements; ARC inserts cleanup of
        // the old payload immediately before the payload write, and that cleanup
        // must test the old presence bit, not the just-updated one.
        const payload_param_offset = record_loop_slot_offset;
        for (record_slots.payload_locals, record_slots.payload_tys, 0..) |local, ty, index| {
            params[payload_param_offset + index] = .{ .local = local, .ty = ty };
        }
        const presence_param_offset = payload_param_offset + record_slots.payload_locals.len;
        for (record_slots.presence_locals, record_slots.presence_tys, 0..) |local, ty, index| {
            params[presence_param_offset + index] = .{ .local = local, .ty = ty };
        }

        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_record_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const init_counted_name = try self.builder.program.names.internRecordFieldLabel("counted");
        const init_cursor_name = try self.builder.program.names.internRecordFieldLabel("cursor");
        const init_remaining_name = try self.builder.program.names.internRecordFieldLabel("remaining");
        const init_field_tys = [_]Type.Field{
            .{ .name = init_counted_name, .ty = bool_ty, .default = null },
            .{ .name = init_cursor_name, .ty = state_ty, .default = null },
            .{ .name = init_remaining_name, .ty = u64_ty, .default = null },
        };
        const init_ty = try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &init_field_tys) });

        const counted_tag = self.monoTagByText(start_event_ty, "Counted");
        const counted_payload_ty = self.singleTagPayloadType(counted_tag, "record parse Counted start event");
        const counted_payload_local = try self.addLocal(self.builder.symbols.fresh(), counted_payload_ty);
        const counted_payload_pat = try self.bindPat(counted_payload_local, counted_payload_ty);
        const counted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = counted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{counted_payload_pat}),
        } } });
        const counted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(true, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "rest") },
            .{ .name = init_remaining_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "len") },
        };
        const counted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&counted_init_fields) },
        });

        const uncounted_tag = self.monoTagByText(start_event_ty, "Uncounted");
        const uncounted_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const uncounted_state_pat = try self.bindPat(uncounted_state_local, state_ty);
        const uncounted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = uncounted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{uncounted_state_pat}),
        } } });
        const uncounted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(false, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.localExpr(uncounted_state_local, state_ty) },
            .{ .name = init_remaining_name, .value = try self.intLiteralExpr(0, u64_ty) },
        };
        const uncounted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&uncounted_init_fields) },
        });

        const init_branches = [_]DraftBranch{
            .{ .pat = counted_pat, .body = counted_init },
            .{ .pat = uncounted_pat, .body = uncounted_init },
        };
        const init_expr = try self.addExpr(.{ .ty = init_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(start_event_local, start_event_ty),
            .branches = try self.addBranchSpan(&init_branches),
        } } });
        const init_local = try self.addLocal(self.builder.symbols.fresh(), init_ty);

        const initial_values = try self.allocator.alloc(DraftExprId, record_loop_slot_offset + initial_payload_values.len + initial_presence_values.len);
        defer self.allocator.free(initial_values);
        initial_values[0] = try self.recordPayloadFieldAccess(init_local, init_ty, "cursor");
        initial_values[1] = try self.boolLiteral(false, bool_ty);
        initial_values[2] = try self.recordPayloadFieldAccess(init_local, init_ty, "counted");
        initial_values[3] = try self.recordPayloadFieldAccess(init_local, init_ty, "remaining");
        @memcpy(initial_values[record_loop_slot_offset .. record_loop_slot_offset + initial_payload_values.len], initial_payload_values);
        @memcpy(initial_values[record_loop_slot_offset + initial_payload_values.len ..], initial_presence_values);
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        loop_expr = try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
        loop_expr = try self.wrapLet(fields_local, fields_ty, fields_expr, loop_expr, ret_ty);
        if (owned_renamed_field_values) |renamed_field_values| {
            var index = renamed_field_locals.len;
            while (index > 0) {
                index -= 1;
                loop_expr = try self.wrapLet(renamed_field_locals[index], str_ty, renamed_field_values[index], loop_expr, ret_ty);
            }
        }
        return loop_expr;
    }

    fn lowerParseRecordEvent(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const continue_tag = self.monoTagByText(event_ty, "Continue");
        const done_tag = self.monoTagByText(event_ty, "Done");
        const field_tag = self.monoTagByText(event_ty, "Field");
        const try_field_tag = self.monoTagByText(event_ty, "TryField");
        const try_field_caseless_tag = self.monoTagByText(event_ty, "TryFieldCaseless");
        const field_payload_ty = self.singleTagPayloadType(field_tag, "record parse Field event");
        const try_field_payload_ty = self.singleTagPayloadType(try_field_tag, "record parse TryField event");
        const try_field_caseless_payload_ty = self.singleTagPayloadType(try_field_caseless_tag, "record parse TryFieldCaseless event");

        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_body = try self.lowerParseRecordContinueEvent(
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            continue_state_local,
        );

        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_body = try self.lowerParseRecordDoneEvent(
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            done_state_local,
        );

        const field_payload_local = try self.addLocal(self.builder.symbols.fresh(), field_payload_ty);
        const field_payload_pat = try self.bindPat(field_payload_local, field_payload_ty);
        const field_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = field_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{field_payload_pat}),
        } } });
        const field_body = try self.lowerParseRecordDirectFieldEvent(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
            field_payload_local,
            field_payload_ty,
        );

        const try_field_payload_local = try self.addLocal(self.builder.symbols.fresh(), try_field_payload_ty);
        const try_field_payload_pat = try self.bindPat(try_field_payload_local, try_field_payload_ty);
        const try_field_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = try_field_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{try_field_payload_pat}),
        } } });
        const try_field_body = try self.lowerParseRecordNamedFieldEvent(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            try_field_payload_local,
            try_field_payload_ty,
            .exact,
        );

        const try_field_caseless_payload_local = try self.addLocal(self.builder.symbols.fresh(), try_field_caseless_payload_ty);
        const try_field_caseless_payload_pat = try self.bindPat(try_field_caseless_payload_local, try_field_caseless_payload_ty);
        const try_field_caseless_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = try_field_caseless_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{try_field_caseless_payload_pat}),
        } } });
        const try_field_caseless_body = try self.lowerParseRecordNamedFieldEvent(
            shape_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            try_field_caseless_payload_local,
            try_field_caseless_payload_ty,
            .caseless,
        );

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
            .{ .pat = field_pat, .body = field_body },
            .{ .pat = try_field_pat, .body = try_field_body },
            .{ .pat = try_field_caseless_pat, .body = try_field_caseless_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseRecordNamedDispatchBody(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        matched_bodies: []const DraftExprId,
        unknown_body: DraftExprId,
        mode: RecordFieldMatchMode,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (renamed_field_locals.len != matched_bodies.len) Common.invariant("record parser dispatch arity did not match renamed fields");
        if (renamed_field_lengths) |lengths| {
            if (lengths.len != renamed_field_locals.len) Common.invariant("record parser dispatch length arity did not match renamed fields");
            return try self.lowerParseRecordLengthBucketedDispatchBody(
                key_local,
                key_ty,
                renamed_field_locals,
                lengths,
                renamed_field_texts,
                matched_bodies,
                unknown_body,
                mode,
                ret_ty,
            );
        }
        var body = unknown_body;
        var index = matched_bodies.len;
        while (index > 0) {
            index -= 1;
            const renamed_field_expr = try self.localExpr(renamed_field_locals[index], key_ty);
            const cond = try self.recordFieldNameMatch(
                key_local,
                key_ty,
                renamed_field_expr,
                if (renamed_field_texts) |texts| texts[index] else null,
                mode,
            );
            body = try self.ifExpr(cond, matched_bodies[index], body, ret_ty);
        }
        return body;
    }

    fn lowerParseRecordLengthBucketedDispatchBody(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: []const u32,
        renamed_field_texts: ?[]const []const u8,
        matched_bodies: []const DraftExprId,
        unknown_body: DraftExprId,
        mode: RecordFieldMatchMode,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const key_len_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);

        var body = unknown_body;
        var index = matched_bodies.len;
        while (index > 0) {
            index -= 1;
            const length = renamed_field_lengths[index];
            if (fieldLengthAlreadyHandled(renamed_field_lengths, index, length)) continue;
            const static_lane: ?StaticFieldLane = if ((mode == .exact or mode == .caseless) and length <= 24)
                if (renamed_field_texts) |texts| selectStaticFieldLane(renamed_field_lengths, texts, length) else null
            else
                null;

            var group_body = unknown_body;
            var field_index = matched_bodies.len;
            while (field_index > 0) {
                field_index -= 1;
                if (renamed_field_lengths[field_index] != length) continue;

                const renamed_field_expr = try self.localExpr(renamed_field_locals[field_index], key_ty);
                if (static_lane) |lane| {
                    const texts = renamed_field_texts orelse Common.invariant("static field lane requested without field text");
                    const field_text = texts[field_index];
                    const probe = switch (mode) {
                        .direct => Common.invariant("direct field handles do not use string matching"),
                        .exact => try self.recordFieldNameStaticSmallWordMatch(key_local, key_ty, field_text, lane.offset, lane.active_len),
                        .caseless => try self.recordFieldNameStaticSmallWordCaselessMatch(key_local, key_ty, field_text, lane.offset, lane.active_len),
                    };
                    const matched_or_next = if (lane.offset == 0 and lane.active_len == length)
                        matched_bodies[field_index]
                    else blk: {
                        const full_cond = switch (mode) {
                            .direct => Common.invariant("direct field handles do not use string matching"),
                            .exact => try self.recordFieldNameStaticSmallExactMatch(key_local, key_ty, field_text),
                            .caseless => try self.recordFieldNameStaticSmallCaselessMatch(key_local, key_ty, field_text),
                        };
                        break :blk try self.ifExpr(full_cond, matched_bodies[field_index], group_body, ret_ty);
                    };
                    group_body = try self.ifExpr(probe, matched_or_next, group_body, ret_ty);
                } else {
                    const cond = try self.recordFieldNameMatch(
                        key_local,
                        key_ty,
                        renamed_field_expr,
                        if (renamed_field_texts) |texts| texts[field_index] else null,
                        mode,
                    );
                    group_body = try self.ifExpr(cond, matched_bodies[field_index], group_body, ret_ty);
                }
            }

            const key_len_expr = try self.localExpr(key_len_local, u64_ty);
            const length_expr = try self.intLiteralExpr(length, u64_ty);
            const length_matches = try self.lowLevelExpr(.num_is_eq, &.{ key_len_expr, length_expr }, bool_ty);
            body = try self.ifExpr(length_matches, group_body, body, ret_ty);
        }

        const key_expr = try self.localExpr(key_local, key_ty);
        const key_len_expr = try self.lowLevelExpr(.str_count_utf8_bytes, &.{key_expr}, u64_ty);
        return try self.wrapLet(key_len_local, u64_ty, key_len_expr, body, ret_ty);
    }

    fn continueRecordLoop(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        cursor_expr: DraftExprId,
        done_expr: DraftExprId,
        remaining_expr: DraftExprId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        updated: ?UpdatedFieldSlot,
    ) Allocator.Error!DraftExprId {
        const values = try self.allocator.alloc(DraftExprId, record_loop_slot_offset + record_slots.payload_locals.len + record_slots.presence_locals.len);
        defer self.allocator.free(values);
        values[0] = cursor_expr;
        values[1] = done_expr;
        values[2] = try self.localExpr(ctl.counted_local, ctl.bool_ty);
        values[3] = remaining_expr;
        // Keep this order in sync with `lowerParseRecordFromState`: ARC cleanup
        // of the old slot must see the old presence word before the new value is
        // marked present.
        const payload_offset = record_loop_slot_offset;
        for (record_slots.payload_locals, record_slots.payload_tys, 0..) |local, ty, index| {
            values[payload_offset + index] = if (updated != null and index == updated.?.index) blk: {
                if (!self.sameType(ty, updated.?.ty)) Common.invariant("record parser field payload type differed from slot payload type");
                break :blk try self.localExpr(updated.?.local, updated.?.ty);
            } else try self.localExpr(local, ty);
        }
        const presence_offset = payload_offset + record_slots.payload_locals.len;
        for (record_slots.presence_locals, record_slots.presence_tys, 0..) |local, ty, index| {
            values[presence_offset + index] = if (updated != null and index == recordPresenceWordIndex(updated.?.index))
                try self.recordPresenceWithBit(local, ty, recordPresenceMask(updated.?.index))
            else
                try self.localExpr(local, ty);
        }
        return try self.continueWith(.{ .sealed = ret_ty }, values);
    }

    /// After a record entry (matched field, skipped field) has been consumed:
    /// in Counted mode decrement `remaining` and re-enter the loop directly;
    /// otherwise ask `parse_record_after_field` whether more entries follow.
    fn lowerParseRecordEntryEnd(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        entry_state_local: DraftLocalId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        updated: ?UpdatedFieldSlot,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const false_expr = try self.boolLiteral(false, ctl.bool_ty);
        const remaining_minus_one = try self.lowLevelExpr(.num_minus_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(entry_state_local, state_ty),
            false_expr,
            remaining_minus_one,
            record_slots,
            ctl,
            updated,
        );

        const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
        const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
        const after_try = try self.lowerParseFormatMethod(
            "parse_record_after_field",
            &.{ encoding_expr, try self.localExpr(entry_state_local, state_ty) },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            after_try_ty,
        );
        const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);
        const remaining_expr = try self.localExpr(ctl.remaining_local, ctl.u64_ty);

        const continue_tag = self.monoTagByText(after_event_ty, "Continue");
        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(continue_state_local, state_ty),
            try self.boolLiteral(false, ctl.bool_ty),
            remaining_expr,
            record_slots,
            ctl,
            updated,
        );

        const done_tag = self.monoTagByText(after_event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_body = try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(done_state_local, state_ty),
            try self.boolLiteral(true, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
            updated,
        );

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
        };
        const after_match = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(after_event_local, after_event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
        const uncounted_body = try self.sequenceTry(after_try, after_try_ty, after_event_local, after_match, ret_ty);

        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseRecordNamedFieldEvent(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        payload_local: DraftLocalId,
        payload_ty: Type.TypeId,
        mode: RecordFieldMatchMode,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.builder.primitiveType(.str);
        const key_expr = try self.recordPayloadFieldAccess(payload_local, payload_ty, "name");
        if (!self.sameType(try self.exprType(key_expr), str_ty)) {
            Common.invariant("record named-field event key was not Str");
        }
        const rest_expr = try self.recordPayloadFieldAccess(payload_local, payload_ty, "rest");
        const key_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerRecordNamedFieldDispatchBody(
            shape_ty,
            encoding_expr,
            encoding_ty,
            key_local,
            str_ty,
            rest_local,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            mode,
        );
        return try self.wrapLet(key_local, str_ty, key_expr, try self.wrapLet(rest_local, state_ty, rest_expr, body, ret_ty), ret_ty);
    }

    /// A `Continue` event means the format consumed a whole entry itself and
    /// the cursor is already at the next entry boundary, so the loop re-enters
    /// without calling `parse_record_after_field`.
    fn lowerParseRecordContinueEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        continue_state_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        const cursor_expr = try self.localExpr(continue_state_local, state_ty);
        const false_expr = try self.boolLiteral(false, ctl.bool_ty);
        const remaining_minus_one = try self.lowLevelExpr(.num_minus_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_body = try self.continueRecordLoop(ret_ty, cursor_expr, false_expr, remaining_minus_one, record_slots, ctl, null);
        const uncounted_body = try self.continueRecordLoop(
            ret_ty,
            cursor_expr,
            try self.boolLiteral(false, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
            null,
        );
        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseRecordDoneEvent(
        self: *BodyContext,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        done_state_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        return try self.continueRecordLoop(
            ret_ty,
            try self.localExpr(done_state_local, state_ty),
            try self.boolLiteral(true, ctl.bool_ty),
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            record_slots,
            ctl,
            null,
        );
    }

    /// The single record-construction site: runs at the loop head once `done`
    /// is set or a counted record has consumed all its entries.
    fn lowerParseRecordFinish(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        renamed_field_locals: []const DraftLocalId,
        rest_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const record_try_ty = try self.tryTypeLike(ret_ty, shape_ty, ret_info.err_ty);
        const record_expr = try self.finishGeneratedRecordSlots(
            record_slots,
            shape_ty,
            record_try_ty,
            encoding_expr,
            encoding_ty,
            rest_expr,
            state_ty,
            renamed_field_locals,
        );
        const record_local = try self.addLocal(self.builder.symbols.fresh(), shape_ty);
        const ok_body = try self.parseResultOk(
            ret_ty,
            try self.localExpr(record_local, shape_ty),
            rest_expr,
            state_ty,
        );
        return try self.sequenceTry(record_expr, record_try_ty, record_local, ok_body, ret_ty);
    }

    fn lowerParseRecordDirectFieldEvent(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        field_payload_local: DraftLocalId,
        field_payload_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const rest_expr = try self.recordPayloadFieldAccess(field_payload_local, field_payload_ty, "rest");
        const field_expr = try self.recordPayloadFieldAccess(field_payload_local, field_payload_ty, "field");
        const field_ty = try self.exprType(field_expr);
        const field_local = try self.addLocal(self.builder.symbols.fresh(), field_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerRecordDirectFieldDispatchBody(
            shape_ty,
            encoding_expr,
            encoding_ty,
            field_local,
            field_ty,
            rest_local,
            state_ty,
            ret_ty,
            record_slots,
            ctl,
            precomputed_plan,
        );
        return try self.wrapLet(field_local, field_ty, field_expr, try self.wrapLet(rest_local, state_ty, rest_expr, body, ret_ty), ret_ty);
    }

    fn lowerRecordDirectFieldDispatchBody(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        field_local: DraftLocalId,
        field_ty: Type.TypeId,
        rest_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.builder.shapeContent(shape_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => self.builder.program.types.fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record direct field dispatch requested for a non-record shape"),
        });
        defer self.allocator.free(fields);
        if (fields.len != record_slots.fieldCount()) Common.invariant("record direct field dispatch state arity differed from field count");

        if (fields.len == 0) {
            return try self.lowerSkipRecordFieldNext(
                encoding_expr,
                encoding_ty,
                state_ty,
                ret_ty,
                rest_local,
                record_slots,
                ctl,
            );
        }

        const u64_ty = try self.builder.primitiveType(.u64);
        const index_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        var body = try self.lowerParseMatchedRecordFieldNext(
            fields[fields.len - 1],
            fields.len - 1,
            encoding_expr,
            encoding_ty,
            state_ty,
            record_slots,
            ctl,
            precomputed_plan,
            rest_local,
            ret_ty,
        );
        var index = fields.len - 1;
        while (index > 0) {
            index -= 1;
            const matched = try self.lowerParseMatchedRecordFieldNext(
                fields[index],
                index,
                encoding_expr,
                encoding_ty,
                state_ty,
                record_slots,
                ctl,
                precomputed_plan,
                rest_local,
                ret_ty,
            );
            const index_expr = try self.localExpr(index_local, u64_ty);
            const literal_expr = try self.intLiteralExpr(@intCast(index), u64_ty);
            const cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, literal_expr }, try self.builder.primitiveType(.bool));
            body = try self.ifExpr(cond, matched, body, ret_ty);
        }

        const handle_index = try self.fieldHandleIndexExpr(field_local, field_ty, u64_ty);
        return try self.wrapLet(index_local, u64_ty, handle_index, body, ret_ty);
    }

    fn lowerRecordNamedFieldDispatchBody(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        rest_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        renamed_field_locals: []const DraftLocalId,
        renamed_field_lengths: ?[]const u32,
        renamed_field_texts: ?[]const []const u8,
        mode: RecordFieldMatchMode,
    ) Allocator.Error!DraftExprId {
        const fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.builder.shapeContent(shape_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => self.builder.program.types.fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record named field dispatch requested for a non-record shape"),
        });
        defer self.allocator.free(fields);
        if (fields.len != record_slots.fieldCount()) Common.invariant("record named field dispatch state arity differed from field count");
        if (fields.len != renamed_field_locals.len) Common.invariant("record named field dispatch renamed field arity differed from field count");
        if (renamed_field_lengths) |lengths| {
            if (fields.len != lengths.len) Common.invariant("record named field dispatch renamed length arity differed from field count");
        }
        if (renamed_field_texts) |texts| {
            if (fields.len != texts.len) Common.invariant("record named field dispatch renamed text arity differed from field count");
        }

        const matched_bodies = try self.allocator.alloc(DraftExprId, fields.len);
        defer self.allocator.free(matched_bodies);
        for (fields, 0..) |field, index| {
            matched_bodies[index] = try self.lowerParseMatchedRecordFieldNext(
                field,
                index,
                encoding_expr,
                encoding_ty,
                state_ty,
                record_slots,
                ctl,
                precomputed_plan,
                rest_local,
                ret_ty,
            );
        }

        const unknown_body = try self.lowerSkipRecordFieldNext(
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            rest_local,
            record_slots,
            ctl,
        );

        return try self.lowerParseRecordNamedDispatchBody(
            key_local,
            key_ty,
            renamed_field_locals,
            renamed_field_lengths,
            renamed_field_texts,
            matched_bodies,
            unknown_body,
            mode,
            ret_ty,
        );
    }

    fn lowerSkipRecordFieldNext(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        rest_local: DraftLocalId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const skip_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const lookup = try self.methodLookupForTypeName(encoding_ty, "skip_record_field");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{ encoding_ty, state_ty }, skip_try_ty);
        const skip_fn = self.builder.functionShape(callable_mono_ty, "skip_record_field target method was not a function");
        const arg_tys = self.builder.program.types.span(skip_fn.args);
        if (arg_tys.len != 2) Common.invariant("skip_record_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("skip_record_field encoding type differed from record encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), state_ty)) Common.invariant("skip_record_field state type differed from record state type");

        const skip_expr = try self.addExpr(.{
            .ty = skip_try_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, try self.localExpr(rest_local, state_ty) }),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
        const skipped_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const ok_body = try self.lowerParseRecordEntryEnd(
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            skipped_local,
            record_slots,
            ctl,
            null,
        );
        return try self.sequenceTry(skip_expr, skip_try_ty, skipped_local, ok_body, ret_ty);
    }

    fn lowerParseMatchedRecordFieldNext(
        self: *BodyContext,
        field: Type.Field,
        field_index: usize,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        ctl: RecordLoopCtl,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        rest_local: DraftLocalId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const maybe_missing_try = try self.missingTryInfo(field.ty);
        const maybe_slot = self.builder.optionalFieldSlot(field.ty);
        const field_parse_ty = if (maybe_missing_try) |info|
            info.ok_ty
        else if (maybe_slot) |slot|
            slot.payload_ty
        else
            field.ty;
        const parse_ok_ty = try self.parseResultOkType(field_parse_ty, state_ty);
        const parse_ret_ty = try self.tryTypeLike(ret_ty, parse_ok_ty, ret_info.err_ty);
        const parse_expr = try self.lowerParseShapeHelperCall(
            field_parse_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(rest_local, state_ty),
            state_ty,
            parse_ret_ty,
            precomputed_plan,
        );
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const parsed_value_local = try self.addLocal(self.builder.symbols.fresh(), field_parse_ty);
        const field_value = if (maybe_missing_try != null)
            try self.tryOk(field.ty, try self.localExpr(parsed_value_local, field_parse_ty))
        else if (maybe_slot) |slot|
            // A matched `?:` field parses at the slot's Present payload type
            // and wraps in the `#Present` tag (design.md "Field Kinds").
            try self.optionalSlotPresentExpr(field.ty, slot, try self.localExpr(parsed_value_local, field_parse_ty))
        else
            try self.localExpr(parsed_value_local, field_parse_ty);
        const field_value_local = try self.addLocal(self.builder.symbols.fresh(), field.ty);
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const ok_body = try self.lowerParseRecordEntryEnd(
            encoding_expr,
            encoding_ty,
            state_ty,
            ret_ty,
            parsed_rest_local,
            record_slots,
            ctl,
            .{ .local = field_value_local, .ty = field.ty, .index = field_index },
        );
        const with_field_value = try self.wrapLet(field_value_local, field.ty, field_value, ok_body, ret_ty);
        return try self.sequenceTryRecord(parse_expr, parse_ret_ty, parsed_value_local, value_name, parsed_rest_local, rest_name, with_field_value, ret_ty);
    }

    fn lowerParseShapeHelperCall(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const def_id = try self.parseShapeDefForType(
            shape_ty,
            encoding_ty,
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        var plan_inputs = try self.serializationPlanInputs(.parser, shape_ty, encoding_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.builder.primitiveType(.str);
        const arg_tys = try self.allocator.alloc(Type.TypeId, 2 + plan_inputs.locals.items.len);
        defer self.allocator.free(arg_tys);
        const args = try self.allocator.alloc(DraftExprId, arg_tys.len);
        defer self.allocator.free(args);
        arg_tys[0] = state_ty;
        arg_tys[1] = encoding_ty;
        args[0] = state_expr;
        args[1] = encoding_expr;
        for (plan_inputs.locals.items, 0..) |local, index| {
            arg_tys[2 + index] = str_ty;
            args[2 + index] = try self.localExpr(local, str_ty);
        }
        const fn_ty = try self.functionType(arg_tys, ret_ty);
        const callee = try self.addExpr(.{
            .ty = fn_ty,
            .data = .{ .def_ref = .{ .draft = def_id } },
        });
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_value = .{
                .callee = callee,
                .args = try self.addExprSpan(args),
            } },
        });
    }

    fn parseShapeDefForType(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftDefId {
        const address = GeneratedParserDefAddress{
            .value_ty = @intFromEnum(shape_ty),
            .encoding_ty = @intFromEnum(encoding_ty),
            .state_ty = @intFromEnum(state_ty),
            .result_ty = @intFromEnum(ret_ty),
        };
        if (self.parser_defs.get(address)) |entry| return entry.id();

        const def_id = try self.draft.reserveDef(self.draft.current_owner);
        try self.parser_defs.put(address, .{ .reserved = def_id });

        var plan_inputs = try self.serializationPlanInputs(.parser, shape_ty, encoding_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.builder.primitiveType(.str);
        var helper_plan: ?SerializationHelperPlan = if (precomputed_plan) |plan|
            try self.cloneSerializationHelperPlan(plan, &plan_inputs, str_ty)
        else
            null;
        defer if (helper_plan) |*plan| plan.deinit(self.allocator);

        const state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), encoding_ty);
        const body = try self.lowerParseResultFromState(
            shape_ty,
            try self.localExpr(encoding_local, encoding_ty),
            encoding_ty,
            try self.localExpr(state_local, state_ty),
            state_ty,
            ret_ty,
            if (helper_plan) |*plan| &plan.plan else null,
        );
        const args = try self.allocator.alloc(BodyTypedLocal, 2 + plan_inputs.locals.items.len);
        defer self.allocator.free(args);
        args[0] = .{ .local = state_local, .ty = state_ty };
        args[1] = .{ .local = encoding_local, .ty = encoding_ty };
        if (helper_plan) |*plan| {
            @memcpy(args[2..], plan.args);
        } else if (plan_inputs.locals.items.len != 0) {
            Common.invariant("structural parser helper had plan inputs without a precomputed plan");
        }
        self.draft.setDef(def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .args = try self.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = try self.draftTypeCell(ret_ty),
        });
        try self.parser_defs.put(address, .{ .ready = def_id });
        return def_id;
    }

    fn lowerParseResultFromState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.lowerParseNullTryFromState(info, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            return try self.lowerParseDictFromState(dict.key_ty, dict.value_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.lowerParseSetFromState(payload_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        switch (self.builder.shapeContent(shape_ty)) {
            .list => |elem_ty| return try self.lowerParseListFromState(elem_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .tuple => |items| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(items));
                defer self.allocator.free(item_tys);
                return try self.lowerParseTupleFromState(item_tys, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            },
            .box => |payload_ty| return try self.lowerParseBoxFromState(payload_ty, shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .primitive, .named, .record, .tag_union, .func, .erased, .zst => {},
        }
        if (try self.customParserLookup(shape_ty)) |raw_lookup| {
            return try self.lowerCustomParserFromState(
                try self.withLocalProcContext(raw_lookup),
                shape_ty,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
            );
        }
        return try self.lowerParseShapeFromState(shape_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
    }

    /// A tuple's arity is static, so the format is told the element count and
    /// never decides when the sequence ends: no per-element event union, and
    /// arity mismatches are reported by the format itself, where it can say
    /// what it actually found.
    fn lowerParseTupleFromState(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const len_expr = try self.intLiteralExpr(@intCast(item_tys.len), u64_ty);
        const state_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);

        const item_locals = try self.allocator.alloc(DraftLocalId, item_tys.len);
        defer self.allocator.free(item_locals);
        for (item_tys, 0..) |item_ty, index| {
            item_locals[index] = try self.addLocal(self.builder.symbols.fresh(), item_ty);
        }

        const start_try = try self.lowerParseFormatMethod(
            "parse_tuple_start",
            &.{ encoding_expr, state_expr, len_expr },
            &.{ encoding_ty, state_ty, u64_ty },
            encoding_ty,
            state_try_ty,
        );
        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerParseTupleElement(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            cursor_local,
            state_ty,
            ret_ty,
            item_locals,
            0,
            precomputed_plan,
        );
        return try self.sequenceTry(start_try, state_try_ty, cursor_local, body, ret_ty);
    }

    fn lowerParseTupleElement(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const len_expr = try self.intLiteralExpr(@intCast(item_tys.len), u64_ty);
        const state_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);

        if (item_index == item_tys.len) {
            const end_try = try self.lowerParseFormatMethod(
                "parse_tuple_end",
                &.{ encoding_expr, try self.localExpr(cursor_local, state_ty), len_expr },
                &.{ encoding_ty, state_ty, u64_ty },
                encoding_ty,
                state_try_ty,
            );
            const end_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const done_body = try self.lowerParseTupleDone(
                item_tys,
                tuple_ty,
                item_locals,
                try self.localExpr(end_local, state_ty),
                state_ty,
                ret_ty,
            );
            return try self.sequenceTry(end_try, state_try_ty, end_local, done_body, ret_ty);
        }

        const item_ty = item_tys[item_index];
        const parse_ok_ty = try self.parseResultOkType(item_ty, state_ty);
        const parse_ret_ty = try self.tryTypeLike(ret_ty, parse_ok_ty, ret_info.err_ty);
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const rest_body = try self.lowerParseTupleElement(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            parsed_rest_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index + 1,
            precomputed_plan,
        );

        const parse_expr = try self.lowerParseShapeHelperCall(
            item_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(cursor_local, state_ty),
            state_ty,
            parse_ret_ty,
            precomputed_plan,
        );
        const element_body = try self.sequenceTryRecord(
            parse_expr,
            parse_ret_ty,
            item_locals[item_index],
            value_name,
            parsed_rest_local,
            rest_name,
            rest_body,
            ret_ty,
        );

        // Every element after the first is preceded by a separator the format
        // consumes, told which element is coming and how many there are.
        if (item_index == 0) return element_body;

        const index_expr = try self.intLiteralExpr(@intCast(item_index), u64_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_tuple_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty), index_expr, len_expr },
            &.{ encoding_ty, state_ty, u64_ty, u64_ty },
            encoding_ty,
            state_try_ty,
        );
        const separated_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const separated_body = try self.lowerParseTupleElementAfterSeparator(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            separated_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index,
            precomputed_plan,
        );
        return try self.sequenceTry(next_try, state_try_ty, separated_local, separated_body, ret_ty);
    }

    /// The element read itself, with the cursor already past the separator.
    fn lowerParseTupleElementAfterSeparator(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const item_ty = item_tys[item_index];
        const parse_ok_ty = try self.parseResultOkType(item_ty, state_ty);
        const parse_ret_ty = try self.tryTypeLike(ret_ty, parse_ok_ty, ret_info.err_ty);
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const rest_body = try self.lowerParseTupleElement(
            item_tys,
            tuple_ty,
            encoding_expr,
            encoding_ty,
            parsed_rest_local,
            state_ty,
            ret_ty,
            item_locals,
            item_index + 1,
            precomputed_plan,
        );
        const parse_expr = try self.lowerParseShapeHelperCall(
            item_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(cursor_local, state_ty),
            state_ty,
            parse_ret_ty,
            precomputed_plan,
        );
        return try self.sequenceTryRecord(
            parse_expr,
            parse_ret_ty,
            item_locals[item_index],
            value_name,
            parsed_rest_local,
            rest_name,
            rest_body,
            ret_ty,
        );
    }

    fn lowerParseTupleDone(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        tuple_ty: Type.TypeId,
        item_locals: []const DraftLocalId,
        rest_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (item_tys.len != item_locals.len) Common.invariant("tuple parser local count differed from tuple type arity");
        const items = try self.allocator.alloc(DraftExprId, item_tys.len);
        defer self.allocator.free(items);
        for (item_tys, item_locals, 0..) |item_ty, item_local, index| {
            items[index] = try self.localExpr(item_local, item_ty);
        }
        const tuple_expr = try self.addExpr(.{
            .ty = tuple_ty,
            .data = .{ .tuple = try self.addExprSpan(items) },
        });
        return try self.parseResultOk(ret_ty, tuple_expr, rest_expr, state_ty);
    }

    /// A format that knows its element count up front returns `Counted`, and
    /// the driver then reads exactly that many elements with no further format
    /// calls and preallocates the list. Otherwise the element loop asks the
    /// format after every element whether more follow.
    fn lowerParseListFromState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_list_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const list_local = try self.addLocal(self.builder.symbols.fresh(), list_ty);
        const ctl = ListLoopCtl{
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };
        const loop_body = try self.lowerParseListLoopBody(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const loop_params = [_]BodyTypedLocal{
            .{ .local = cursor_local, .ty = state_ty },
            .{ .local = list_local, .ty = list_ty },
            .{ .local = ctl.counted_local, .ty = bool_ty },
            .{ .local = ctl.remaining_local, .ty = u64_ty },
        };

        const init_counted_name = try self.builder.program.names.internRecordFieldLabel("counted");
        const init_cursor_name = try self.builder.program.names.internRecordFieldLabel("cursor");
        const init_remaining_name = try self.builder.program.names.internRecordFieldLabel("remaining");
        const init_field_tys = [_]Type.Field{
            .{ .name = init_counted_name, .ty = bool_ty, .default = null },
            .{ .name = init_cursor_name, .ty = state_ty, .default = null },
            .{ .name = init_remaining_name, .ty = u64_ty, .default = null },
        };
        const init_ty = try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &init_field_tys) });

        const counted_tag = self.monoTagByText(start_event_ty, "Counted");
        const counted_payload_ty = self.singleTagPayloadType(counted_tag, "list parse Counted start event");
        const counted_payload_local = try self.addLocal(self.builder.symbols.fresh(), counted_payload_ty);
        const counted_payload_pat = try self.bindPat(counted_payload_local, counted_payload_ty);
        const counted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = counted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{counted_payload_pat}),
        } } });
        const counted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(true, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "rest") },
            .{ .name = init_remaining_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "len") },
        };
        const counted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&counted_init_fields) },
        });

        const uncounted_tag = self.monoTagByText(start_event_ty, "Uncounted");
        const uncounted_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const uncounted_state_pat = try self.bindPat(uncounted_state_local, state_ty);
        const uncounted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = uncounted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{uncounted_state_pat}),
        } } });
        const uncounted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(false, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.localExpr(uncounted_state_local, state_ty) },
            .{ .name = init_remaining_name, .value = try self.intLiteralExpr(0, u64_ty) },
        };
        const uncounted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&uncounted_init_fields) },
        });

        const init_branches = [_]DraftBranch{
            .{ .pat = counted_pat, .body = counted_init },
            .{ .pat = uncounted_pat, .body = uncounted_init },
        };
        const init_expr = try self.addExpr(.{ .ty = init_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(start_event_local, start_event_ty),
            .branches = try self.addBranchSpan(&init_branches),
        } } });
        const init_local = try self.addLocal(self.builder.symbols.fresh(), init_ty);

        const remaining_expr = try self.recordPayloadFieldAccess(init_local, init_ty, "remaining");
        const initial_values = [_]DraftExprId{
            try self.recordPayloadFieldAccess(init_local, init_ty, "cursor"),
            try self.lowLevelExpr(.list_with_capacity, &.{remaining_expr}, list_ty),
            try self.recordPayloadFieldAccess(init_local, init_ty, "counted"),
            try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"),
        };
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(&loop_params),
            .initial_values = try self.addExprSpan(&initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        return try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
    }

    fn lowerParseSetFromState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        set_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const list_ty = try self.listType(elem_ty);
        const list_parse_ok_ty = try self.parseResultOkType(list_ty, state_ty);
        const list_parse_ret_ty = try self.tryTypeLike(ret_ty, list_parse_ok_ty, ret_info.err_ty);
        const list_parse = try self.lowerParseListFromState(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            list_parse_ret_ty,
            precomputed_plan,
        );

        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const list_local = try self.addLocal(self.builder.symbols.fresh(), list_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const set_value = try self.lowerSetFromList(set_ty, list_ty, try self.localExpr(list_local, list_ty));
        const ok_body = try self.parseResultOk(ret_ty, set_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(list_parse, list_parse_ret_ty, list_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    /// A dict's entries are parsed the same way a list's elements are, with a
    /// key read before each value: `Counted` lets a length-prefixed format
    /// declare the entry count up front, and the key goes through the key
    /// type's own parser rather than being routed through a string.
    fn lowerParseDictFromState(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const start_event_ty = try self.parseCountedStartEventType(state_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, start_event_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_dict_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            start_try_ty,
        );
        const start_event_local = try self.addLocal(self.builder.symbols.fresh(), start_event_ty);

        const cursor_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const dict_local = try self.addLocal(self.builder.symbols.fresh(), dict_ty);
        const ctl = ListLoopCtl{
            .counted_local = try self.addLocal(self.builder.symbols.fresh(), bool_ty),
            .remaining_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty),
            .bool_ty = bool_ty,
            .u64_ty = u64_ty,
        };
        const loop_body = try self.lowerParseDictLoopBody(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            dict_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const loop_params = [_]BodyTypedLocal{
            .{ .local = cursor_local, .ty = state_ty },
            .{ .local = dict_local, .ty = dict_ty },
            .{ .local = ctl.counted_local, .ty = bool_ty },
            .{ .local = ctl.remaining_local, .ty = u64_ty },
        };

        const init_counted_name = try self.builder.program.names.internRecordFieldLabel("counted");
        const init_cursor_name = try self.builder.program.names.internRecordFieldLabel("cursor");
        const init_remaining_name = try self.builder.program.names.internRecordFieldLabel("remaining");
        const init_field_tys = [_]Type.Field{
            .{ .name = init_counted_name, .ty = bool_ty, .default = null },
            .{ .name = init_cursor_name, .ty = state_ty, .default = null },
            .{ .name = init_remaining_name, .ty = u64_ty, .default = null },
        };
        const init_ty = try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &init_field_tys) });

        const counted_tag = self.monoTagByText(start_event_ty, "Counted");
        const counted_payload_ty = self.singleTagPayloadType(counted_tag, "dict parse Counted start event");
        const counted_payload_local = try self.addLocal(self.builder.symbols.fresh(), counted_payload_ty);
        const counted_payload_pat = try self.bindPat(counted_payload_local, counted_payload_ty);
        const counted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = counted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{counted_payload_pat}),
        } } });
        const counted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(true, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "rest") },
            .{ .name = init_remaining_name, .value = try self.recordPayloadFieldAccess(counted_payload_local, counted_payload_ty, "len") },
        };
        const counted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&counted_init_fields) },
        });

        const uncounted_tag = self.monoTagByText(start_event_ty, "Uncounted");
        const uncounted_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const uncounted_state_pat = try self.bindPat(uncounted_state_local, state_ty);
        const uncounted_pat = try self.addPat(.{ .ty = start_event_ty, .data = .{ .tag = .{
            .name = uncounted_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{uncounted_state_pat}),
        } } });
        const uncounted_init_fields = [_]DraftFieldExpr{
            .{ .name = init_counted_name, .value = try self.boolLiteral(false, bool_ty) },
            .{ .name = init_cursor_name, .value = try self.localExpr(uncounted_state_local, state_ty) },
            .{ .name = init_remaining_name, .value = try self.intLiteralExpr(0, u64_ty) },
        };
        const uncounted_init = try self.addExpr(.{
            .ty = init_ty,
            .data = .{ .record = try self.addFieldExprSpan(&uncounted_init_fields) },
        });

        const init_branches = [_]DraftBranch{
            .{ .pat = counted_pat, .body = counted_init },
            .{ .pat = uncounted_pat, .body = uncounted_init },
        };
        const init_expr = try self.addExpr(.{ .ty = init_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(start_event_local, start_event_ty),
            .branches = try self.addBranchSpan(&init_branches),
        } } });
        const init_local = try self.addLocal(self.builder.symbols.fresh(), init_ty);

        const initial_values = [_]DraftExprId{
            try self.recordPayloadFieldAccess(init_local, init_ty, "cursor"),
            try self.lowerDictWithCapacity(dict_ty, try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"), u64_ty),
            try self.recordPayloadFieldAccess(init_local, init_ty, "counted"),
            try self.recordPayloadFieldAccess(init_local, init_ty, "remaining"),
        };
        var loop_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .loop_ = .{
            .params = try self.addTypedLocalSpan(&loop_params),
            .initial_values = try self.addExprSpan(&initial_values),
            .body = loop_body,
        } } });
        loop_expr = try self.wrapLet(init_local, init_ty, init_expr, loop_expr, ret_ty);
        return try self.sequenceTry(start_try, start_try_ty, start_event_local, loop_expr, ret_ty);
    }

    fn lowerParseDictLoopBody(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const event_ty = try self.parseArrayEventType(state_ty, "Entry", "Done");
        const event_try_ty = try self.tryTypeLike(ret_ty, event_ty, ret_info.err_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_dict_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty) },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            event_try_ty,
        );
        const event_local = try self.addLocal(self.builder.symbols.fresh(), event_ty);
        const event_body = try self.lowerParseDictNextEvent(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            event_local,
            event_ty,
            dict_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const uncounted_body = try self.sequenceTry(next_try, event_try_ty, event_local, event_body, ret_ty);

        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(cursor_local, state_ty),
            state_ty,
        );
        const counted_done = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });
        const remaining_minus_one = try self.lowLevelExpr(.num_minus_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const counted_entry = try self.lowerParseDictEntry(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            dict_local,
            ctl,
            remaining_minus_one,
            .counted,
            ret_ty,
            precomputed_plan,
        );
        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(0, ctl.u64_ty),
        }, ctl.bool_ty);
        const counted_body = try self.ifExpr(remaining_is_zero, counted_done, counted_entry, ret_ty);

        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    fn lowerParseDictNextEvent(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const entry_tag = self.monoTagByText(event_ty, "Entry");
        const entry_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const entry_state_pat = try self.bindPat(entry_state_local, state_ty);
        const entry_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = entry_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{entry_state_pat}),
        } } });
        const entry_body = try self.lowerParseDictEntry(
            key_ty,
            value_ty,
            dict_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            entry_state_local,
            dict_local,
            ctl,
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            .uncounted,
            ret_ty,
            precomputed_plan,
        );

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(done_state_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = entry_pat, .body = entry_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    /// One key-value entry. In Uncounted mode the format decides after each
    /// entry whether more follow; Counted mode instead re-enters the loop with
    /// one fewer entry left.
    fn lowerParseDictEntry(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        entry_state_local: DraftLocalId,
        dict_local: DraftLocalId,
        ctl: ListLoopCtl,
        remaining_expr: DraftExprId,
        entry_end_mode: DictEntryEndMode,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");

        const key_parse_ok_ty = try self.parseResultOkType(key_ty, state_ty);
        const key_parse_ret_ty = try self.tryTypeLike(ret_ty, key_parse_ok_ty, ret_info.err_ty);
        const key_parse = try self.lowerParseDictKey(
            key_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(entry_state_local, state_ty),
            state_ty,
            key_parse_ret_ty,
            precomputed_plan,
        );
        const key_local = try self.addLocal(self.builder.symbols.fresh(), key_ty);
        const after_key_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const separator_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const separator_try = try self.lowerParseFormatMethod(
            "parse_dict_after_key",
            &.{ encoding_expr, try self.localExpr(after_key_local, state_ty) },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            separator_try_ty,
        );
        const value_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const value_parse_ok_ty = try self.parseResultOkType(value_ty, state_ty);
        const value_parse_ret_ty = try self.tryTypeLike(ret_ty, value_parse_ok_ty, ret_info.err_ty);
        const value_parse = try self.lowerParseShapeHelperCall(
            value_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(value_state_local, state_ty),
            state_ty,
            value_parse_ret_ty,
            precomputed_plan,
        );
        const value_local = try self.addLocal(self.builder.symbols.fresh(), value_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const inserted = try self.lowerDictInsert(
            dict_ty,
            key_ty,
            value_ty,
            try self.localExpr(dict_local, dict_ty),
            try self.localExpr(key_local, key_ty),
            try self.localExpr(value_local, value_ty),
        );
        const inserted_local = try self.addLocal(self.builder.symbols.fresh(), dict_ty);

        const entry_end = switch (entry_end_mode) {
            .uncounted => blk: {
                const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
                const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
                const after_try = try self.lowerParseFormatMethod(
                    "parse_dict_after_entry",
                    &.{ encoding_expr, try self.localExpr(rest_local, state_ty) },
                    &.{ encoding_ty, state_ty },
                    encoding_ty,
                    after_try_ty,
                );
                const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);

                const continue_tag = self.monoTagByText(after_event_ty, "Continue");
                const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
                const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
                const continue_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
                    .name = continue_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
                } } });
                const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
                    .values = try self.addExprSpan(&[_]DraftExprId{
                        try self.localExpr(continue_state_local, state_ty),
                        try self.localExpr(inserted_local, dict_ty),
                        try self.localExpr(ctl.counted_local, ctl.bool_ty),
                        remaining_expr,
                    }),
                } } });

                const after_done_tag = self.monoTagByText(after_event_ty, "Done");
                const after_done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
                const after_done_state_pat = try self.bindPat(after_done_state_local, state_ty);
                const after_done_pat = try self.addPat(.{ .ty = after_event_ty, .data = .{ .tag = .{
                    .name = after_done_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{after_done_state_pat}),
                } } });
                const after_done_value = try self.parseResultOk(
                    ret_ty,
                    try self.localExpr(inserted_local, dict_ty),
                    try self.localExpr(after_done_state_local, state_ty),
                    state_ty,
                );
                const after_done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = after_done_value } });

                const after_branches = [_]DraftBranch{
                    .{ .pat = continue_pat, .body = continue_body },
                    .{ .pat = after_done_pat, .body = after_done_body },
                };
                const after_match = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
                    .scrutinee = try self.localExpr(after_event_local, after_event_ty),
                    .branches = try self.addBranchSpan(&after_branches),
                } } });
                break :blk try self.sequenceTry(after_try, after_try_ty, after_event_local, after_match, ret_ty);
            },
            .counted => try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
                .values = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(rest_local, state_ty),
                    try self.localExpr(inserted_local, dict_ty),
                    try self.localExpr(ctl.counted_local, ctl.bool_ty),
                    remaining_expr,
                }),
            } } }),
        };

        const with_inserted = try self.wrapLet(inserted_local, dict_ty, inserted, entry_end, ret_ty);
        const value_body = try self.sequenceTryRecord(value_parse, value_parse_ret_ty, value_local, value_name, rest_local, rest_name, with_inserted, ret_ty);
        const separator_body = try self.sequenceTry(separator_try, separator_try_ty, value_state_local, value_body, ret_ty);
        return try self.sequenceTryRecord(key_parse, key_parse_ret_ty, key_local, value_name, after_key_local, rest_name, separator_body, ret_ty);
    }

    fn lowerParseDictKey(
        self: *BodyContext,
        key_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.parseDictKeyMethodName(key_ty)) |method_name| {
            return try self.lowerParseFormatMethod(
                method_name,
                &.{ encoding_expr, state_expr },
                &.{ encoding_ty, state_ty },
                encoding_ty,
                ret_ty,
            );
        }
        if (self.dictKeyUnitTags(key_ty)) |tags_span| {
            return try self.lowerParseUnitTagDictKey(tags_span, key_ty, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty);
        }

        // A key the format cannot render as a key string is read by the key's
        // own parser, after `parse_key_start` opens the key position.
        const ret_info = self.tryInfo(ret_ty);
        const start_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const start_try = try self.lowerParseFormatMethod(
            "parse_key_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            start_try_ty,
        );
        const opened_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const key_parse = try self.lowerParseShapeHelperCall(
            key_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(opened_local, state_ty),
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        return try self.sequenceTry(start_try, start_try_ty, opened_local, key_parse, ret_ty);
    }

    /// An enum key arrives as text, and an unmatched name is the one dict
    /// failure the driver detects rather than the format, so it builds the
    /// error through `invalid_value`.
    fn lowerParseUnitTagDictKey(
        self: *BodyContext,
        tags_span: Type.Span,
        key_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const str_ty = try self.builder.primitiveType(.str);
        const key_parse_ok_ty = try self.parseResultOkType(str_ty, state_ty);
        const key_parse_ret_ty = try self.tryTypeLike(ret_ty, key_parse_ok_ty, ret_info.err_ty);
        const key_parse = try self.lowerParseFormatMethod(
            "parse_key_str",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            key_parse_ret_ty,
        );
        const key_local = try self.addLocal(self.builder.symbols.fresh(), str_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        var body = try self.tryErr(ret_ty, try self.invalidValueError(
            encoding_expr,
            try self.localExpr(rest_local, state_ty),
            encoding_ty,
            state_ty,
            ret_info.err_ty,
        ));
        const tags = self.builder.program.types.tagSpan(tags_span);
        var index = tags.len;
        while (index > 0) {
            index -= 1;
            const tag = GuardedList.at(tags, index);
            const tag_text = self.builder.program.names.tagLabelText(tag.name);
            const tag_name_expr = try self.stringExpr(tag_text, str_ty);
            const key_expr = try self.localExpr(key_local, str_ty);
            const cond = try self.lowLevelExpr(.str_is_eq, &.{ key_expr, tag_name_expr }, try self.builder.primitiveType(.bool));
            const value = try self.tagUnionValueWithoutPayload(key_ty, tag_text);
            const matched = try self.parseResultOk(ret_ty, value, try self.localExpr(rest_local, state_ty), state_ty);
            body = try self.ifExpr(cond, matched, body, ret_ty);
        }

        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        return try self.sequenceTryRecord(key_parse, key_parse_ret_ty, key_local, value_name, rest_local, rest_name, body, ret_ty);
    }

    fn lowerParseListLoopBody(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const next_event_ty = try self.parseArrayEventType(state_ty, "Item", "Done");
        const next_try_ty = try self.tryTypeLike(ret_ty, next_event_ty, ret_info.err_ty);
        const next_try = try self.lowerParseFormatMethod(
            "parse_list_next",
            &.{ encoding_expr, try self.localExpr(cursor_local, state_ty) },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            next_try_ty,
        );
        const event_local = try self.addLocal(self.builder.symbols.fresh(), next_event_ty);
        const event_body = try self.lowerParseListNextEvent(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            event_local,
            next_event_ty,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        const uncounted_body = try self.sequenceTry(next_try, next_try_ty, event_local, event_body, ret_ty);

        const counted_body = try self.lowerParseListCountedStep(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            cursor_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );
        return try self.ifExpr(
            try self.localExpr(ctl.counted_local, ctl.bool_ty),
            counted_body,
            uncounted_body,
            ret_ty,
        );
    }

    /// Counted mode: stop once the declared count is exhausted, otherwise read
    /// one more element back-to-back with no intervening format call.
    fn lowerParseListCountedStep(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        cursor_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(list_local, list_ty),
            try self.localExpr(cursor_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const elem_parse_ok_ty = try self.parseResultOkType(elem_ty, state_ty);
        const elem_parse_ret_ty = try self.tryTypeLike(ret_ty, elem_parse_ok_ty, ret_info.err_ty);
        const elem_parse = try self.lowerParseShapeHelperCall(
            elem_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(cursor_local, state_ty),
            state_ty,
            elem_parse_ret_ty,
            precomputed_plan,
        );
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const elem_local = try self.addLocal(self.builder.symbols.fresh(), elem_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const remaining_minus_one = try self.lowLevelExpr(.num_minus_wrap, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(1, ctl.u64_ty),
        }, ctl.u64_ty);
        const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                try self.localExpr(rest_local, state_ty),
                appended,
                try self.localExpr(ctl.counted_local, ctl.bool_ty),
                remaining_minus_one,
            }),
        } } });
        const element_body = try self.sequenceTryRecord(elem_parse, elem_parse_ret_ty, elem_local, value_name, rest_local, rest_name, continue_body, ret_ty);

        const remaining_is_zero = try self.lowLevelExpr(.num_is_eq, &.{
            try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            try self.intLiteralExpr(0, ctl.u64_ty),
        }, ctl.bool_ty);
        return try self.ifExpr(remaining_is_zero, done_body, element_body, ret_ty);
    }

    fn lowerParseListNextEvent(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const item_tag = self.monoTagByText(event_ty, "Item");
        const element_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const element_state_pat = try self.bindPat(element_state_local, state_ty);
        const element_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = item_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{element_state_pat}),
        } } });
        const element_body = try self.lowerParseListElement(
            elem_ty,
            list_ty,
            encoding_expr,
            encoding_ty,
            state_ty,
            element_state_local,
            list_local,
            ctl,
            ret_ty,
            precomputed_plan,
        );

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_value = try self.parseResultOk(
            ret_ty,
            try self.localExpr(list_local, list_ty),
            try self.localExpr(done_state_local, state_ty),
            state_ty,
        );
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = element_pat, .body = element_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseListElement(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        element_state_local: DraftLocalId,
        list_local: DraftLocalId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const elem_parse_ok_ty = try self.parseResultOkType(elem_ty, state_ty);
        const elem_parse_ret_ty = try self.tryTypeLike(ret_ty, elem_parse_ok_ty, ret_info.err_ty);
        const elem_parse = try self.lowerParseShapeHelperCall(
            elem_ty,
            encoding_expr,
            encoding_ty,
            try self.localExpr(element_state_local, state_ty),
            state_ty,
            elem_parse_ret_ty,
            precomputed_plan,
        );
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const elem_local = try self.addLocal(self.builder.symbols.fresh(), elem_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);

        const after_event_ty = try self.parseArrayEventType(state_ty, "Continue", "Done");
        const after_try_ty = try self.tryTypeLike(ret_ty, after_event_ty, ret_info.err_ty);
        const after_try = try self.lowerParseFormatMethod(
            "parse_list_after_item",
            &.{ encoding_expr, try self.localExpr(rest_local, state_ty) },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            after_try_ty,
        );
        const after_event_local = try self.addLocal(self.builder.symbols.fresh(), after_event_ty);
        const after_body = try self.lowerParseListAfterItemEvent(
            elem_ty,
            list_ty,
            state_ty,
            elem_local,
            list_local,
            after_event_local,
            after_event_ty,
            ctl,
            ret_ty,
        );
        const sequenced_after = try self.sequenceTry(after_try, after_try_ty, after_event_local, after_body, ret_ty);
        return try self.sequenceTryRecord(elem_parse, elem_parse_ret_ty, elem_local, value_name, rest_local, rest_name, sequenced_after, ret_ty);
    }

    fn lowerParseListAfterItemEvent(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        list_ty: Type.TypeId,
        state_ty: Type.TypeId,
        elem_local: DraftLocalId,
        list_local: DraftLocalId,
        event_local: DraftLocalId,
        event_ty: Type.TypeId,
        ctl: ListLoopCtl,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const continue_tag = self.monoTagByText(event_ty, "Continue");
        const continue_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const continue_state_pat = try self.bindPat(continue_state_local, state_ty);
        const continue_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = continue_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{continue_state_pat}),
        } } });
        const continue_appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const continue_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                try self.localExpr(continue_state_local, state_ty),
                continue_appended,
                try self.localExpr(ctl.counted_local, ctl.bool_ty),
                try self.localExpr(ctl.remaining_local, ctl.u64_ty),
            }),
        } } });

        const done_tag = self.monoTagByText(event_ty, "Done");
        const done_state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const done_state_pat = try self.bindPat(done_state_local, state_ty);
        const done_pat = try self.addPat(.{ .ty = event_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{done_state_pat}),
        } } });
        const done_appended = try self.appendListElement(
            try self.localExpr(list_local, list_ty),
            try self.localExpr(elem_local, elem_ty),
            list_ty,
        );
        const done_value = try self.parseResultOk(ret_ty, done_appended, try self.localExpr(done_state_local, state_ty), state_ty);
        const done_body = try self.addExpr(.{ .ty = ret_ty, .data = .{ .break_ = done_value } });

        const branches = [_]DraftBranch{
            .{ .pat = continue_pat, .body = continue_body },
            .{ .pat = done_pat, .body = done_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(event_local, event_ty),
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerParseBoxFromState(
        self: *BodyContext,
        payload_ty: Type.TypeId,
        box_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const payload_parse_ok_ty = try self.parseResultOkType(payload_ty, state_ty);
        const payload_parse_ret_ty = try self.tryTypeLike(ret_ty, payload_parse_ok_ty, ret_info.err_ty);
        const payload_parse = try self.lowerParseShapeHelperCall(
            payload_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            payload_parse_ret_ty,
            precomputed_plan,
        );

        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const boxed_value = try self.lowLevelExpr(.box_box, &.{try self.localExpr(payload_local, payload_ty)}, box_ty);
        const ok_body = try self.parseResultOk(ret_ty, boxed_value, try self.localExpr(rest_local, state_ty), state_ty);
        return try self.sequenceTryRecord(payload_parse, payload_parse_ret_ty, payload_local, value_name, rest_local, rest_name, ok_body, ret_ty);
    }

    fn lowerParseNullTryFromState(
        self: *BodyContext,
        info: TryNullInfo,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const null_try_ty = try self.tryTypeLike(ret_ty, state_ty, ret_info.err_ty);
        const parse_null_lookup = try self.methodLookupForTypeName(encoding_ty, "parse_null");
        const parse_null_mono_ty = try self.methodTargetMonoTypeFromArgs(parse_null_lookup, &.{ encoding_ty, state_ty }, null_try_ty);
        const parse_null_fn = self.builder.functionShape(parse_null_mono_ty, "parse_null target method was not a function");
        const parse_null_arg_tys = self.builder.program.types.span(parse_null_fn.args);
        if (parse_null_arg_tys.len != 2) Common.invariant("parse_null target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_null_arg_tys, 0), encoding_ty)) Common.invariant("parse_null encoding type differed from input encoding type");
        if (!self.sameType(GuardedList.at(parse_null_arg_tys, 1), state_ty)) Common.invariant("parse_null state type differed from input state type");
        if (!self.sameType(parse_null_fn.ret, null_try_ty)) Common.invariant("parse_null return type differed from generated Try type");

        const parse_null_expr = try self.addExpr(.{
            .ty = null_try_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(parse_null_lookup, parse_null_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(parse_null_lookup),
            } },
        });

        const null_try_info = self.tryInfo(null_try_ty);
        const null_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const null_rest_pat = try self.bindPat(null_rest_local, state_ty);
        const null_ok_backing_pat = try self.addPat(.{ .ty = null_try_info.backing_ty, .data = .{ .tag = .{
            .name = null_try_info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{null_rest_pat}),
        } } });
        const null_ok_pat = try self.addPat(.{ .ty = null_try_ty, .data = .{ .nominal = null_ok_backing_pat } });
        const null_marker = try self.tagUnionValueWithoutPayload(info.err_ty, "Null");
        const null_value = try self.tryErr(shape_ty, null_marker);
        const null_ok_body = try self.parseResultOk(ret_ty, null_value, try self.localExpr(null_rest_local, state_ty), state_ty);

        const child_parse_ok_ty = try self.parseResultOkType(info.ok_payload_ty, state_ty);
        const child_parse_ty = try self.tryTypeLike(ret_ty, child_parse_ok_ty, ret_info.err_ty);
        const child_parse = try self.lowerParseShapeHelperCall(
            info.ok_payload_ty,
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            child_parse_ty,
            precomputed_plan,
        );
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const parsed_value_local = try self.addLocal(self.builder.symbols.fresh(), info.ok_payload_ty);
        const parsed_rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const present_value = try self.tryOk(shape_ty, try self.localExpr(parsed_value_local, info.ok_payload_ty));
        const child_ok_body = try self.parseResultOk(ret_ty, present_value, try self.localExpr(parsed_rest_local, state_ty), state_ty);
        const child_body = try self.sequenceTryRecord(child_parse, child_parse_ty, parsed_value_local, value_name, parsed_rest_local, rest_name, child_ok_body, ret_ty);

        const null_err_payload_pat = try self.addPat(.{ .ty = null_try_info.err_ty, .data = .wildcard });
        const null_err_backing_pat = try self.addPat(.{ .ty = null_try_info.backing_ty, .data = .{ .tag = .{
            .name = null_try_info.err_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{null_err_payload_pat}),
        } } });
        const null_err_pat = try self.addPat(.{ .ty = null_try_ty, .data = .{ .nominal = null_err_backing_pat } });

        const branches = [_]DraftBranch{
            .{ .pat = null_ok_pat, .body = null_ok_body },
            .{ .pat = null_err_pat, .body = child_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = parse_null_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerCustomParserFromState(
        self: *BodyContext,
        lookup: MethodLookup,
        shape_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const prepared = self.frozenCustomCodecCall(.parser, shape_ty, lookup);
        const callable_mono_ty = prepared.callable_ty;
        const parse_fn = self.builder.functionShape(callable_mono_ty, "custom parser target was not a function");
        const parse_arg_tys = self.builder.program.types.span(parse_fn.args);
        if (parse_arg_tys.len != 1) Common.invariant("custom parser target had an unexpected arity");
        if (!self.sameType(GuardedList.at(parse_arg_tys, 0), encoding_ty)) Common.invariant("custom parser encoding type differed from input encoding type");
        const runtime_fn_ty = parse_fn.ret;
        const runtime_fn = self.builder.functionShape(runtime_fn_ty, "custom parser runtime target was not a function");
        const runtime_arg_tys = self.builder.program.types.span(runtime_fn.args);
        if (runtime_arg_tys.len != 1 or !self.sameType(GuardedList.at(runtime_arg_tys, 0), state_ty)) {
            Common.invariant("custom parser runtime argument differed from parser state type");
        }
        const source_ret_ty = runtime_fn.ret;

        const source_ret_info = self.tryInfo(source_ret_ty);
        const target_ret_info = self.tryInfo(ret_ty);
        if (!self.sameType(source_ret_info.ok_ty, target_ret_info.ok_ty)) {
            Common.invariant("custom parser result Ok type differed from derived parser result Ok type");
        }
        if (!self.builder.errorRowIsIncludedIn(source_ret_info.err_ty, target_ret_info.err_ty)) {
            Common.invariant("custom parser error row was not included in derived parser error row");
        }
        const parse_ok_fields = switch (self.builder.shapeContent(source_ret_info.ok_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("custom parser result Ok type was not a parse result record"),
        };
        var found_value = false;
        for (0..GuardedList.borrowLen(parse_ok_fields)) |index| {
            const field = GuardedList.at(parse_ok_fields, index);
            const field_text = self.builder.program.names.recordFieldLabelText(field.name);
            if (Ident.textEql(field_text, "value")) {
                found_value = true;
                if (!self.sameType(field.ty, shape_ty)) Common.invariant("custom parser value type differed from parsed shape");
            }
        }
        if (!found_value) Common.invariant("custom parser result was missing value field");

        const parser_expr = try self.addExpr(.{
            .ty = runtime_fn_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{encoding_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
        const source_result = try self.addExpr(.{
            .ty = source_ret_ty,
            .data = .{ .call_value = .{
                .callee = parser_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{state_expr}),
            } },
        });
        return try self.injectTryErrorRow(source_result, source_ret_ty, ret_ty);
    }

    fn injectTryErrorRow(
        self: *BodyContext,
        source_expr: DraftExprId,
        source_try_ty: Type.TypeId,
        target_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (self.sameType(source_try_ty, target_try_ty)) return source_expr;

        const source_info = self.tryInfo(source_try_ty);
        const target_info = self.tryInfo(target_try_ty);
        if (!self.sameType(source_info.ok_ty, target_info.ok_ty)) {
            Common.invariant("parser Try error-row injection changed the Ok type");
        }
        if (!self.builder.errorRowIsIncludedIn(source_info.err_ty, target_info.err_ty)) {
            Common.invariant("parser Try error-row injection source was not included in target");
        }

        const ok_local = try self.addLocal(self.builder.symbols.fresh(), source_info.ok_ty);
        const ok_payload_pat = try self.bindPat(ok_local, source_info.ok_ty);
        const ok_backing_pat = try self.addPat(.{ .ty = source_info.backing_ty, .data = .{ .tag = .{
            .name = source_info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_pat = try self.addPat(.{ .ty = source_try_ty, .data = .{ .nominal = ok_backing_pat } });
        const ok_body = try self.tryOk(target_try_ty, try self.localExpr(ok_local, source_info.ok_ty));

        const source_err_tags = self.builder.tagUnionTags(source_info.err_ty);
        const branch_count: usize = if (source_err_tags.len == 0) 1 else 2;
        const branches = try self.allocator.alloc(DraftBranch, branch_count);
        defer self.allocator.free(branches);
        branches[0] = .{ .pat = ok_pat, .body = ok_body };

        if (source_err_tags.len != 0) {
            const err_local = try self.addLocal(self.builder.symbols.fresh(), source_info.err_ty);
            const err_payload_pat = try self.bindPat(err_local, source_info.err_ty);
            const err_backing_pat = try self.addPat(.{ .ty = source_info.backing_ty, .data = .{ .tag = .{
                .name = source_info.err_tag.name,
                .payloads = try self.addPatSpan(&[_]DraftPatId{err_payload_pat}),
            } } });
            const err_pat = try self.addPat(.{ .ty = source_try_ty, .data = .{ .nominal = err_backing_pat } });
            const err_value = try self.localExpr(err_local, source_info.err_ty);
            const injected_err = try self.injectErrorRow(err_value, source_info.err_ty, target_info.err_ty);
            branches[1] = .{ .pat = err_pat, .body = try self.tryErr(target_try_ty, injected_err) };
        }

        return try self.addExpr(.{ .ty = target_try_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn injectErrorRow(
        self: *BodyContext,
        source_expr: DraftExprId,
        source_err_ty: Type.TypeId,
        target_err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (self.sameType(source_err_ty, target_err_ty)) return source_expr;

        const source_tags = self.builder.tagUnionTags(source_err_ty);
        if (source_tags.len == 0) Common.invariant("cannot inject an empty parser error row into a different row");
        const branches = try self.allocator.alloc(DraftBranch, source_tags.len);
        defer self.allocator.free(branches);

        for (0..source_tags.len) |tag_index| {
            const source_tag = GuardedList.at(source_tags, tag_index);
            const target_tag = self.builder.tagByName(target_err_ty, source_tag.name);
            const source_payload_tys = self.builder.program.types.span(source_tag.payloads);
            const target_payload_tys = self.builder.program.types.span(target_tag.payloads);
            if (source_payload_tys.len != target_payload_tys.len) {
                Common.invariant("parser error-row injection changed tag payload arity");
            }

            const payload_pats = try self.allocator.alloc(DraftPatId, source_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(DraftExprId, source_payload_tys.len);
            defer self.allocator.free(payload_exprs);
            for (0..source_payload_tys.len) |payload_index| {
                const source_payload_ty = GuardedList.at(source_payload_tys, payload_index);
                const target_payload_ty = GuardedList.at(target_payload_tys, payload_index);
                if (!self.sameType(source_payload_ty, target_payload_ty)) {
                    Common.invariant("parser error-row injection changed tag payload type");
                }
                const local = try self.addLocal(self.builder.symbols.fresh(), source_payload_ty);
                payload_pats[payload_index] = try self.bindPat(local, source_payload_ty);
                payload_exprs[payload_index] = try self.localExpr(local, source_payload_ty);
            }

            const pat = try self.addPat(.{ .ty = source_err_ty, .data = .{ .tag = .{
                .name = source_tag.name,
                .payloads = try self.addPatSpan(payload_pats),
            } } });
            branches[tag_index] = .{
                .pat = pat,
                .body = try self.tagUnionValue(target_err_ty, target_tag, payload_exprs),
            };
        }

        return try self.addExpr(.{ .ty = target_err_ty, .data = .{ .match_ = .{
            .scrutinee = source_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn parseResultOkType(
        self: *BodyContext,
        value_ty: Type.TypeId,
        rest_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const fields = [_]Type.Field{
            .{ .name = rest_name, .ty = rest_ty, .default = null },
            .{ .name = value_name, .ty = value_ty, .default = null },
        };
        return try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &fields) });
    }

    fn parseResultOk(
        self: *BodyContext,
        try_ty: Type.TypeId,
        value_expr: DraftExprId,
        rest_expr: DraftExprId,
        rest_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const try_info = self.tryInfo(try_ty);
        const value_ty = try self.exprType(value_expr);
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const fields = [_]DraftFieldExpr{
            .{ .name = rest_name, .value = rest_expr },
            .{ .name = value_name, .value = value_expr },
        };
        const record_expr = try self.addExpr(.{
            .ty = try_info.ok_ty,
            .data = .{ .record = try self.addFieldExprSpan(&fields) },
        });
        const parse_ok_ty = try self.parseResultOkType(value_ty, rest_ty);
        if (!self.sameType(try_info.ok_ty, parse_ok_ty)) Common.invariant("parse result Ok type differed from generated parse result record");
        return try self.tryOk(try_ty, record_expr);
    }

    fn uninitializedPayloadExpr(self: *BodyContext, ty: Type.TypeId, condition_local: DraftLocalId, condition_mask: u64) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .uninitialized_payload = .{ .condition = condition_local, .mask = condition_mask } },
        });
    }

    fn recordPresenceWithBit(
        self: *BodyContext,
        presence_local: DraftLocalId,
        presence_ty: Type.TypeId,
        mask: u64,
    ) Allocator.Error!DraftExprId {
        const current = try self.localExpr(presence_local, presence_ty);
        const bit = try self.intLiteralExpr(mask, presence_ty);
        return try self.lowLevelExpr(.num_bitwise_or, &.{ current, bit }, presence_ty);
    }

    /// The event a variable-length container's `parse_*_start` returns: either
    /// the format declared the entry count up front (`Counted`) or the driver
    /// must ask after every entry whether more follow (`Uncounted`).
    /// `freshParseCountedStartEventVar` in check/Check.zig builds the same row.
    fn parseCountedStartEventType(
        self: *BodyContext,
        state_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const len_name = try self.builder.program.names.internRecordFieldLabel("len");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const u64_ty = try self.builder.primitiveType(.u64);

        const counted_fields = [_]Type.Field{
            .{ .name = len_name, .ty = u64_ty, .default = null },
            .{ .name = rest_name, .ty = state_ty, .default = null },
        };
        const counted_payload_ty = try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &counted_fields) });

        const counted_name = try self.builder.program.names.internTagLabel("Counted");
        const uncounted_name = try self.builder.program.names.internTagLabel("Uncounted");
        var tags = [_]Type.Tag{
            .{
                .name = counted_name,
                .checked_name = counted_name,
                .payloads = try self.builder.program.types.addSpan(&[_]Type.TypeId{counted_payload_ty}),
            },
            .{
                .name = uncounted_name,
                .checked_name = uncounted_name,
                .payloads = try self.builder.program.types.addSpan(&[_]Type.TypeId{state_ty}),
            },
        };
        std.mem.sort(Type.Tag, tags[0..], &self.builder.program.names, solve.tagLessThan);
        return try self.builder.program.types.add(.{ .tag_union = try self.builder.program.types.addTags(&tags) });
    }

    fn parseArrayEventType(
        self: *BodyContext,
        state_ty: Type.TypeId,
        comptime first_tag_text: []const u8,
        comptime second_tag_text: []const u8,
    ) Allocator.Error!Type.TypeId {
        const first_name = try self.builder.program.names.internTagLabel(first_tag_text);
        const second_name = try self.builder.program.names.internTagLabel(second_tag_text);
        var tags = [_]Type.Tag{
            .{
                .name = first_name,
                .checked_name = first_name,
                .payloads = try self.builder.program.types.addSpan(&[_]Type.TypeId{state_ty}),
            },
            .{
                .name = second_name,
                .checked_name = second_name,
                .payloads = try self.builder.program.types.addSpan(&[_]Type.TypeId{state_ty}),
            },
        };
        std.mem.sort(Type.Tag, tags[0..], &self.builder.program.names, solve.tagLessThan);
        return try self.builder.program.types.add(.{ .tag_union = try self.builder.program.types.addTags(&tags) });
    }

    fn appendListElement(
        self: *BodyContext,
        list_expr: DraftExprId,
        elem_expr: DraftExprId,
        list_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const reserved = try self.lowLevelExpr(.list_reserve, &.{ list_expr, try self.intLiteralExpr(1, u64_ty) }, list_ty);
        return try self.lowLevelExpr(.list_append_unsafe, &.{ reserved, elem_expr }, list_ty);
    }

    fn recordEventFieldHandleTemplate(self: *BodyContext, event_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        const field_tag = self.monoTagByText(event_ty, "Field");
        const payload_ty = self.singleTagPayloadType(field_tag, "record parse Field event");
        const field_name = try self.builder.program.names.internRecordFieldLabel("field");
        return self.builder.recordFieldType(payload_ty, field_name);
    }

    fn singleTagPayloadType(self: *BodyContext, tag: Type.Tag, comptime context: []const u8) Type.TypeId {
        const payloads = self.builder.program.types.span(tag.payloads);
        if (payloads.len != 1) Common.invariant(context ++ " had an unexpected payload count");
        return GuardedList.at(payloads, 0);
    }

    fn recordPayloadFieldAccess(
        self: *BodyContext,
        payload_local: DraftLocalId,
        payload_ty: Type.TypeId,
        comptime field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        const field_name = try self.builder.program.names.internRecordFieldLabel(field_text);
        const field_ty = self.builder.recordFieldType(payload_ty, field_name);
        return try self.addFieldAccessExpr(
            try self.localExpr(payload_local, payload_ty),
            field_name,
            field_ty,
        );
    }

    fn finishGeneratedRecordSlots(
        self: *BodyContext,
        record_slots: ParseRecordSlots,
        record_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        rest_value: DraftExprId,
        state_ty: Type.TypeId,
        renamed_field_locals: []const DraftLocalId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        if (!self.sameType(ret_info.ok_ty, record_ty)) Common.invariant("record finish Try Ok type differed from record type");

        const record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.builder.shapeContent(record_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => self.builder.program.types.fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("record finish Ok type was not a record"),
        });
        defer self.allocator.free(record_fields);
        if (record_fields.len != record_slots.fieldCount()) Common.invariant("record parse state arity did not match finish record field count");
        if (record_fields.len != renamed_field_locals.len) Common.invariant("record parse renamed field arity did not match finish record field count");

        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const rest_expr = try self.localExpr(rest_local, state_ty);

        const out_fields = try self.allocator.alloc(DraftFieldExpr, record_fields.len);
        defer self.allocator.free(out_fields);
        const field_tries = try self.allocator.alloc(?DraftExprId, record_fields.len);
        defer self.allocator.free(field_tries);
        @memset(field_tries, null);
        const field_try_tys = try self.allocator.alloc(?Type.TypeId, record_fields.len);
        defer self.allocator.free(field_try_tys);
        @memset(field_try_tys, null);
        const field_locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
        defer self.allocator.free(field_locals);
        for (record_fields, 0..) |field, index| {
            field_locals[index] = try self.addLocal(self.builder.symbols.fresh(), field.ty);
            const field_can_be_missing = (try self.missingTryInfo(field.ty)) != null or
                self.builder.optionalFieldSlot(field.ty) != null or
                self.parserFieldDefaultFor(record_ty, field.name) != null;
            if (!field_can_be_missing) {
                const field_try_ty = try self.tryTypeLike(ret_ty, field.ty, ret_info.err_ty);
                field_try_tys[index] = field_try_ty;
                const presence_word = recordPresenceWordIndex(index);
                const is_present = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]);
                field_tries[index] = try self.parseRecordFieldFromPresencePayload(
                    is_present,
                    recordPresenceMask(index),
                    record_slots.payload_locals[index],
                    record_slots.payload_tys[index],
                    field,
                    field_try_ty,
                    renamed_field_locals[index],
                    encoding_expr,
                    encoding_ty,
                    rest_expr,
                    state_ty,
                );
            }
            out_fields[index] = .{
                .name = field.name,
                .value = try self.localExpr(field_locals[index], field.ty),
            };
        }

        const record_expr = try self.addExpr(.{
            .ty = ret_info.ok_ty,
            .data = .{ .record = try self.addFieldExprSpan(out_fields) },
        });
        var body = try self.tryOk(ret_ty, record_expr);
        var field_index = record_fields.len;
        while (field_index > 0) {
            field_index -= 1;
            const maybe_default = self.parserFieldDefaultFor(record_ty, record_fields[field_index].name);
            const field_can_be_missing = (try self.missingTryInfo(record_fields[field_index].ty)) != null or
                self.builder.optionalFieldSlot(record_fields[field_index].ty) != null or
                maybe_default != null;
            body = if (maybe_default) |default|
                try self.finishDefaultedRecordFieldFromPresencePayload(
                    body,
                    ret_ty,
                    record_slots,
                    record_fields[field_index],
                    field_index,
                    field_locals[field_index],
                    default,
                )
            else if (field_can_be_missing)
                try self.finishOptionalRecordFieldFromPresencePayload(
                    body,
                    ret_ty,
                    record_slots,
                    record_fields[field_index],
                    field_index,
                    field_locals[field_index],
                )
            else
                try self.sequenceTry(
                    field_tries[field_index] orelse Common.invariant("required record field was missing finish Try"),
                    field_try_tys[field_index] orelse Common.invariant("required record field was missing finish Try type"),
                    field_locals[field_index],
                    body,
                    ret_ty,
                );
        }
        return try self.wrapLet(rest_local, state_ty, rest_value, body, ret_ty);
    }

    const ParseShapeSelection = struct {
        tag_text: []const u8,
    };

    fn parseShapeSelection(self: *BodyContext, shape_ty: Type.TypeId) ParseShapeSelection {
        if (self.parseScalarMethodName(shape_ty)) |method_name| return .{ .tag_text = method_name };
        return switch (self.builder.shapeContent(shape_ty)) {
            .record => .{ .tag_text = "Record" },
            .zst => .{ .tag_text = "Record" },
            .tag_union => .{ .tag_text = "TagUnion" },
            .primitive, .named, .tuple, .list, .box, .func, .erased => Common.invariant("parser shape was not supported"),
        };
    }

    fn lowerParseTagUnionDecode(
        self: *BodyContext,
        args: []const checked.CheckedExprId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
        pre_lowered_args: ?[]const DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (args.len != 2 or arg_tys.len != 2) Common.invariant("ParseTagUnionSpec.parse reached Monotype with an unexpected arity");
        if (pre_lowered_args) |lowered| {
            if (lowered.len != args.len) Common.invariant("ParseTagUnionSpec.parse pre-lowered argument arity differed from its checked call");
        }
        const ret_info = self.tryInfo(ret_ty);

        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const value_ty = self.builder.recordFieldType(ret_info.ok_ty, value_name);
        const tag_span = switch (self.builder.shapeContent(value_ty)) {
            .tag_union => |span| span,
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("ParseTagUnionSpec.parse value type was not a tag union"),
        };
        const spec_ty = arg_tys[0];
        const spec_value = if (pre_lowered_args) |lowered| lowered[0] else try self.lowerCallsiteIntrinsicArgAtType(args[0], arg_tys[0]);
        const options_value = if (pre_lowered_args) |lowered| lowered[1] else try self.lowerCallsiteIntrinsicArgAtType(args[1], arg_tys[1]);
        const options_ty = arg_tys[1];
        const key_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("tag"));
        const encoding_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("encoding"));
        const state_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("state"));
        const start_payloads_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("start_payloads"));
        const next_payload_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("next_payload"));
        const finish_payloads_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("finish_payloads"));
        const missing_ty = self.builder.recordFieldType(options_ty, try self.builder.program.names.internRecordFieldLabel("missing"));

        const options_local = try self.addLocal(self.builder.symbols.fresh(), options_ty);
        const key_value = try self.recordPayloadFieldAccess(options_local, options_ty, "tag");
        const encoding_value = try self.recordPayloadFieldAccess(options_local, options_ty, "encoding");
        const slot_value = try self.recordPayloadFieldAccess(options_local, options_ty, "state");
        const start_payloads_value = try self.recordPayloadFieldAccess(options_local, options_ty, "start_payloads");
        const next_payload_value = try self.recordPayloadFieldAccess(options_local, options_ty, "next_payload");
        const finish_payloads_value = try self.recordPayloadFieldAccess(options_local, options_ty, "finish_payloads");
        const missing_value = try self.recordPayloadFieldAccess(options_local, options_ty, "missing");

        const key_local = try self.addLocal(self.builder.symbols.fresh(), key_ty);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), encoding_ty);
        const slot_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const start_payloads_local = try self.addLocal(self.builder.symbols.fresh(), start_payloads_ty);
        const next_payload_local = try self.addLocal(self.builder.symbols.fresh(), next_payload_ty);
        const finish_payloads_local = try self.addLocal(self.builder.symbols.fresh(), finish_payloads_ty);
        const missing_local = try self.addLocal(self.builder.symbols.fresh(), missing_ty);
        const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(tag_span));
        defer self.allocator.free(tags);

        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        const maybe_spec_backing_ty = if (self.generatedParseTagUnionSpecBackingInfo(spec_ty) != null)
            self.builder.namedBackingType(spec_ty) orelse Common.invariant("generated tag-union spec had no backing type")
        else
            null;
        const spec_local = if (maybe_spec_backing_ty != null)
            try self.addLocal(self.builder.symbols.fresh(), spec_ty)
        else
            null;
        const spec_backing_local = if (maybe_spec_backing_ty) |spec_backing_ty| blk: {
            const local = try self.addLocal(self.builder.symbols.fresh(), spec_backing_ty);
            try self.buildParserPrecomputedPlanFromTagUnionSpec(&precomputed_plan, local, spec_backing_ty, value_ty);
            break :blk local;
        } else null;

        var body = try self.unknownDecodedTagErr(ret_ty, missing_local, missing_ty);
        var index = tags.len;
        while (index > 0) {
            index -= 1;
            const tag_expr = try self.decodedTagUnionValue(
                tags[index],
                value_ty,
                ret_ty,
                encoding_local,
                encoding_ty,
                slot_local,
                state_ty,
                start_payloads_local,
                start_payloads_ty,
                next_payload_local,
                next_payload_ty,
                finish_payloads_local,
                finish_payloads_ty,
                if (maybe_spec_backing_ty != null) &precomputed_plan else null,
            );
            const cond = try self.parseTagExactMatch(key_local, key_ty, tags[index]);
            body = try self.ifExpr(cond, tag_expr, body, ret_ty);
        }

        body = try self.wrapLet(missing_local, missing_ty, missing_value, body, ret_ty);
        body = try self.wrapLet(finish_payloads_local, finish_payloads_ty, finish_payloads_value, body, ret_ty);
        body = try self.wrapLet(next_payload_local, next_payload_ty, next_payload_value, body, ret_ty);
        body = try self.wrapLet(start_payloads_local, start_payloads_ty, start_payloads_value, body, ret_ty);
        body = try self.wrapLet(slot_local, state_ty, slot_value, body, ret_ty);
        body = try self.wrapLet(encoding_local, encoding_ty, encoding_value, body, ret_ty);
        body = try self.wrapLet(key_local, key_ty, key_value, body, ret_ty);
        body = try self.wrapLet(options_local, options_ty, options_value, body, ret_ty);
        if (maybe_spec_backing_ty) |spec_backing_ty| {
            var capture_index = precomputed_plan.captures.items.len;
            while (capture_index > 0) {
                capture_index -= 1;
                const capture = precomputed_plan.captures.items[capture_index];
                body = try self.wrapLet(capture.local, try self.builder.primitiveType(.str), capture.value, body, ret_ty);
            }
            const backing_local = spec_backing_local orelse Common.invariant("generated tag-union spec backing local was missing");
            const spec_pat = try self.addPat(.{
                .ty = spec_ty,
                .data = .{ .nominal = try self.bindPat(backing_local, spec_backing_ty) },
            });
            const branch = DraftBranch{ .pat = spec_pat, .body = body };
            const matched = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
                .scrutinee = try self.localExpr(spec_local orelse Common.invariant("generated tag-union spec local was missing"), spec_ty),
                .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
            } } });
            return try self.wrapLet(spec_local orelse Common.invariant("generated tag-union spec local was missing"), spec_ty, spec_value, matched, ret_ty);
        }
        return try self.wrapWildcardLet(arg_tys[0], spec_value, body, ret_ty);
    }

    fn decodedTagUnionValue(
        self: *BodyContext,
        tag: Type.Tag,
        union_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        encoding_local: DraftLocalId,
        encoding_ty: Type.TypeId,
        slot_local: DraftLocalId,
        slot_ty: Type.TypeId,
        start_payloads_local: DraftLocalId,
        start_payloads_ty: Type.TypeId,
        next_payload_local: DraftLocalId,
        next_payload_ty: Type.TypeId,
        finish_payloads_local: DraftLocalId,
        finish_payloads_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(tag.payloads));
        defer self.allocator.free(payload_tys);
        const payload_locals = try self.allocator.alloc(DraftLocalId, payload_tys.len);
        defer self.allocator.free(payload_locals);
        for (payload_tys, 0..) |payload_ty, index| {
            payload_locals[index] = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
        }
        const boundary_try_ty = try self.tryTypeLike(ret_ty, slot_ty, ret_info.err_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const count_expr = try self.intLiteralExpr(@intCast(payload_tys.len), u64_ty);
        self.assertTagPayloadBoundaryType(start_payloads_ty, &.{ slot_ty, u64_ty }, boundary_try_ty);
        self.assertTagPayloadBoundaryType(next_payload_ty, &.{ slot_ty, u64_ty, u64_ty }, boundary_try_ty);
        self.assertTagPayloadBoundaryType(finish_payloads_ty, &.{ slot_ty, u64_ty }, boundary_try_ty);

        const started_try = try self.addExpr(.{
            .ty = boundary_try_ty,
            .data = .{ .call_value = .{
                .callee = try self.localExpr(start_payloads_local, start_payloads_ty),
                .args = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(slot_local, slot_ty),
                    count_expr,
                }),
            } },
        });
        const started_local = try self.addLocal(self.builder.symbols.fresh(), slot_ty);
        const body = try self.decodedTagPayloadsFromState(
            tag,
            union_ty,
            ret_ty,
            encoding_local,
            encoding_ty,
            try self.localExpr(started_local, slot_ty),
            slot_ty,
            payload_tys,
            payload_locals,
            0,
            next_payload_local,
            next_payload_ty,
            finish_payloads_local,
            finish_payloads_ty,
            count_expr,
            boundary_try_ty,
            precomputed_plan,
        );
        return try self.sequenceTry(started_try, boundary_try_ty, started_local, body, ret_ty);
    }

    fn assertTagPayloadBoundaryType(
        self: *BodyContext,
        fn_ty: Type.TypeId,
        expected_args: []const Type.TypeId,
        expected_ret: Type.TypeId,
    ) void {
        const fn_shape = self.builder.functionShape(fn_ty, "tag payload boundary was not a function");
        const args = self.builder.program.types.span(fn_shape.args);
        if (args.len != expected_args.len) Common.invariant("tag payload boundary had an unexpected arity");
        for (expected_args, 0..) |expected, index| {
            if (!self.sameType(GuardedList.at(args, index), expected)) Common.invariant("tag payload boundary argument type differed from expected type");
        }
        if (!self.sameType(fn_shape.ret, expected_ret)) Common.invariant("tag payload boundary return type differed from expected type");
    }

    fn decodedTagPayloadsFromState(
        self: *BodyContext,
        tag: Type.Tag,
        union_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        encoding_local: DraftLocalId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        payload_tys: []const Type.TypeId,
        payload_locals: []const DraftLocalId,
        payload_index: usize,
        next_payload_local: DraftLocalId,
        next_payload_ty: Type.TypeId,
        finish_payloads_local: DraftLocalId,
        finish_payloads_ty: Type.TypeId,
        count_expr: DraftExprId,
        boundary_try_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (payload_index == payload_tys.len) {
            const payloads = try self.allocator.alloc(DraftExprId, payload_tys.len);
            defer self.allocator.free(payloads);
            for (payload_tys, 0..) |payload_ty, index| {
                payloads[index] = try self.localExpr(payload_locals[index], payload_ty);
            }
            const tag_expr = try self.tagUnionValue(union_ty, tag, payloads);
            const finished_try = try self.addExpr(.{
                .ty = boundary_try_ty,
                .data = .{ .call_value = .{
                    .callee = try self.localExpr(finish_payloads_local, finish_payloads_ty),
                    .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, count_expr }),
                } },
            });
            const finished_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const finished = try self.parseResultOk(ret_ty, tag_expr, try self.localExpr(finished_local, state_ty), state_ty);
            return try self.sequenceTry(finished_try, boundary_try_ty, finished_local, finished, ret_ty);
        }

        const ret_info = self.tryInfo(ret_ty);
        const payload_ty = payload_tys[payload_index];
        const payload_ok_ty = try self.parseResultOkType(payload_ty, state_ty);
        const payload_try_ty = try self.tryTypeLike(ret_ty, payload_ok_ty, ret_info.err_ty);
        const payload_try = payload_try: {
            // A payload whose parse can report a missing required field is
            // only decodable when the spec's checked error row carries that
            // report. A closed row without it is checker-authored proof this
            // payload is converter-fed and never parsed from source text, so
            // the impossible parse lowers to the failure mapping instead of
            // generating helpers over unparsable internals.
            var required_visited = collections.DenseMap(Type.TypeId, void).init(self.allocator);
            defer required_visited.deinit();
            if (try self.parserShapeNeedsRequiredFieldError(payload_ty, &required_visited) and
                self.monoTagByTextOptional(ret_info.err_ty, "MissingRequiredField") == null)
            {
                break :payload_try try self.invalidValueParseResult(
                    try self.localExpr(encoding_local, encoding_ty),
                    state_expr,
                    encoding_ty,
                    state_ty,
                    payload_try_ty,
                );
            }
            break :payload_try try self.lowerParseShapeHelperCall(
                payload_ty,
                try self.localExpr(encoding_local, encoding_ty),
                encoding_ty,
                state_expr,
                state_ty,
                payload_try_ty,
                precomputed_plan,
            );
        };
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const rest_expr = try self.localExpr(rest_local, state_ty);
        const next_body = if (payload_index + 1 < payload_tys.len) blk: {
            const u64_ty = try self.builder.primitiveType(.u64);
            const next_try = try self.addExpr(.{
                .ty = boundary_try_ty,
                .data = .{ .call_value = .{
                    .callee = try self.localExpr(next_payload_local, next_payload_ty),
                    .args = try self.addExprSpan(&[_]DraftExprId{
                        rest_expr,
                        try self.intLiteralExpr(@intCast(payload_index + 1), u64_ty),
                        count_expr,
                    }),
                } },
            });
            const next_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
            const body = try self.decodedTagPayloadsFromState(
                tag,
                union_ty,
                ret_ty,
                encoding_local,
                encoding_ty,
                try self.localExpr(next_local, state_ty),
                state_ty,
                payload_tys,
                payload_locals,
                payload_index + 1,
                next_payload_local,
                next_payload_ty,
                finish_payloads_local,
                finish_payloads_ty,
                count_expr,
                boundary_try_ty,
                precomputed_plan,
            );
            break :blk try self.sequenceTry(next_try, boundary_try_ty, next_local, body, ret_ty);
        } else try self.decodedTagPayloadsFromState(
            tag,
            union_ty,
            ret_ty,
            encoding_local,
            encoding_ty,
            rest_expr,
            state_ty,
            payload_tys,
            payload_locals,
            payload_index + 1,
            next_payload_local,
            next_payload_ty,
            finish_payloads_local,
            finish_payloads_ty,
            count_expr,
            boundary_try_ty,
            precomputed_plan,
        );
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        return try self.sequenceTryRecord(
            payload_try,
            payload_try_ty,
            payload_locals[payload_index],
            value_name,
            rest_local,
            rest_name,
            next_body,
            ret_ty,
        );
    }

    fn tagUnionValue(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        tag: Type.Tag,
        payloads: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.builder.namedBackingType(ret_ty);
        const tag_ty = backing_ty orelse ret_ty;
        const backing_expr = try self.addExpr(.{
            .ty = tag_ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = try self.addExprSpan(payloads),
            } },
        });
        if (backing_ty == null) return backing_expr;
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn unknownDecodedTagErr(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        missing_local: DraftLocalId,
        missing_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.tryErr(ret_ty, try self.localExpr(missing_local, missing_ty));
    }

    fn parseTagExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        tag: Type.Tag,
    ) Allocator.Error!DraftExprId {
        if (!self.typeHasBuiltinOwner(key_ty, .str)) Common.invariant("ParseTagUnionSpec.parse key was not Str");
        const tag_text = self.builder.program.names.tagLabelText(tag.name);
        const tag_expr = try self.stringExpr(tag_text, key_ty);
        const key_expr = try self.localExpr(key_local, key_ty);
        return try self.lowLevelExpr(.str_is_eq, &.{ key_expr, tag_expr }, try self.builder.primitiveType(.bool));
    }

    fn recordFieldNameExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const key_expr = try self.localExpr(key_local, key_ty);
        return try self.lowLevelExpr(.str_is_eq, &.{ key_expr, field_expr }, try self.builder.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallExactMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small field match requested for a long field name");

        var words = [3]u64{ 0, 0, 0 };
        for (field_text, 0..) |byte, index| {
            words[index / @sizeOf(u64)] |= @as(u64, byte) << @intCast((index % @sizeOf(u64)) * 8);
        }

        const u64_ty = try self.builder.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const args = [_]DraftExprId{
            key_expr,
            try self.intLiteralExpr(@intCast(field_text.len), u64_ty),
            try self.intLiteralExpr(words[0], u64_ty),
            try self.intLiteralExpr(words[1], u64_ty),
            try self.intLiteralExpr(words[2], u64_ty),
        };
        return try self.lowLevelExpr(.str_is_eq_static_small, &args, try self.builder.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallWordMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
        offset: u32,
        active_len: u32,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small field lane requested for a long field name");
        const word = staticFieldLaneWord(field_text, offset, active_len);

        const u64_ty = try self.builder.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const args = [_]DraftExprId{
            key_expr,
            try self.intLiteralExpr(offset, u64_ty),
            try self.intLiteralExpr(active_len, u64_ty),
            try self.intLiteralExpr(word, u64_ty),
        };
        return try self.lowLevelExpr(.str_static_small_word_eq, &args, try self.builder.primitiveType(.bool));
    }

    fn recordFieldNameStaticSmallCaselessMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small caseless field match requested for a long field name");

        const bool_ty = try self.builder.primitiveType(.bool);
        var body = try self.boolLiteral(true, bool_ty);
        var offset: u32 = @intCast(((field_text.len + 7) / 8) * 8);
        while (offset > 0) {
            offset -= 8;
            const remaining: u32 = @intCast(field_text.len - offset);
            const active_len: u32 = @min(remaining, 8);
            const cond = try self.recordFieldNameStaticSmallWordCaselessMatch(key_local, key_ty, field_text, offset, active_len);
            body = try self.ifExpr(cond, body, try self.boolLiteral(false, bool_ty), bool_ty);
        }

        const u64_ty = try self.builder.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const key_len_expr = try self.lowLevelExpr(.str_count_utf8_bytes, &.{key_expr}, u64_ty);
        const length_expr = try self.intLiteralExpr(@intCast(field_text.len), u64_ty);
        const length_matches = try self.lowLevelExpr(.num_is_eq, &.{ key_len_expr, length_expr }, bool_ty);
        return try self.ifExpr(length_matches, body, try self.boolLiteral(false, bool_ty), bool_ty);
    }

    fn recordFieldNameStaticSmallWordCaselessMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_text: []const u8,
        offset: u32,
        active_len: u32,
    ) Allocator.Error!DraftExprId {
        if (field_text.len > 24) Common.invariant("static small caseless field lane requested for a long field name");
        const word = staticFieldLaneWord(field_text, offset, active_len);

        const u64_ty = try self.builder.primitiveType(.u64);
        const key_expr = try self.localExpr(key_local, key_ty);
        const args = [_]DraftExprId{
            key_expr,
            try self.intLiteralExpr(offset, u64_ty),
            try self.intLiteralExpr(active_len, u64_ty),
            try self.intLiteralExpr(word, u64_ty),
        };
        return try self.lowLevelExpr(.str_static_small_word_caseless_eq, &args, try self.builder.primitiveType(.bool));
    }

    fn renamedRecordFieldNameExpr(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        field: Type.Field,
        str_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const field_text = self.builder.program.names.recordFieldLabelText(field.name);
        const field_expr = try self.stringExpr(field_text, str_ty);
        const lookup = try self.methodLookupForTypeName(encoding_ty, "rename_field");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{ encoding_ty, str_ty }, str_ty);
        const rename_fn = self.builder.functionShape(callable_mono_ty, "rename_field target method was not a function");
        const arg_tys = self.builder.program.types.span(rename_fn.args);
        if (arg_tys.len != 2) Common.invariant("rename_field target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("rename_field encoding argument differed from parser encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), str_ty)) Common.invariant("rename_field name argument differed from Str");
        if (!self.sameType(rename_fn.ret, str_ty)) Common.invariant("rename_field return type differed from Str");
        return try self.addExpr(.{
            .ty = str_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, field_expr }),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn recordFieldNameMatch(
        self: *BodyContext,
        key_local: DraftLocalId,
        key_ty: Type.TypeId,
        field_expr: DraftExprId,
        precomputed_field_text: ?[]const u8,
        mode: RecordFieldMatchMode,
    ) Allocator.Error!DraftExprId {
        return switch (mode) {
            .direct => Common.invariant("direct field handles do not use string matching"),
            .exact => if (precomputed_field_text) |field_text|
                if (field_text.len <= 24)
                    try self.recordFieldNameStaticSmallExactMatch(key_local, key_ty, field_text)
                else
                    try self.recordFieldNameExactMatch(key_local, key_ty, field_expr)
            else
                try self.recordFieldNameExactMatch(key_local, key_ty, field_expr),
            .caseless => blk: {
                if (precomputed_field_text) |field_text| {
                    if (field_text.len <= 24) break :blk try self.recordFieldNameStaticSmallCaselessMatch(key_local, key_ty, field_text);
                }
                const key_expr = try self.localExpr(key_local, key_ty);
                break :blk try self.lowLevelExpr(.str_caseless_ascii_equals, &.{ key_expr, field_expr }, try self.builder.primitiveType(.bool));
            },
        };
    }

    fn wrapLet(
        self: *BodyContext,
        local: DraftLocalId,
        ty: Type.TypeId,
        value: DraftExprId,
        rest: DraftExprId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .let_ = .{
            .bind = try self.bindPat(local, ty),
            .value = value,
            .rest = rest,
        } } });
    }

    fn wrapLetAtTypeCell(
        self: *BodyContext,
        local: DraftLocalId,
        local_cell: DraftTypeCell,
        value: DraftExprId,
        rest: DraftExprId,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
            .bind = try self.addPatWithTypeCell(local_cell, .{ .bind = local }),
            .value = value,
            .rest = rest,
        } });
    }

    fn wrapRecursiveConstLocalAtTypeCell(
        self: *BodyContext,
        local: DraftLocalId,
        cell: DraftTypeCell,
        value: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const value_node = try self.exprTypeCell(value).toGraphNode(self.graph);
        const local_node = try cell.toGraphNode(self.graph);
        try relateRequestComponent(self.graph, local_node, value_node);
        const local_expr = try self.addExprWithTypeCell(cell, .{ .local = local });
        const stmt = try self.addStmt(.{ .let_ = .{
            .pat = try self.addPatWithTypeCell(cell, .{ .bind = local }),
            .value = value,
            .recursive = true,
        } });
        return try self.addExprWithTypeCell(cell, .{ .block = .{
            .statements = try self.addStmtSpan(&.{stmt}),
            .final_expr = local_expr,
        } });
    }

    fn wrapWildcardLet(
        self: *BodyContext,
        ty: Type.TypeId,
        value: DraftExprId,
        rest: DraftExprId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .let_ = .{
            .bind = try self.addPat(.{ .ty = ty, .data = .wildcard }),
            .value = value,
            .rest = rest,
        } } });
    }

    fn lowerCall(self: *BodyContext, checked_ret_ty: checked.CheckedTypeId, call: anytype) Allocator.Error!LoweredCall {
        return try self.lowerCallAtExpectedNode(checked_ret_ty, call, null, null);
    }

    fn lowerCallAtType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!LoweredCall {
        return try self.lowerCallAtExpectedNode(
            checked_ret_ty,
            call,
            if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
            expected_ret_ty,
        );
    }

    fn lowerCallAtNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_node: NodeId,
    ) Allocator.Error!LoweredCall {
        return try self.lowerCallAtExpectedNode(checked_ret_ty, call, expected_ret_node, null);
    }

    fn lowerCallAtExpectedNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_node: ?NodeId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!LoweredCall {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .call_dispatch);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("call_expressions");
        if (try self.lowerCallThatCannotReachCallee(checked_ret_ty, call, expected_ret_node)) |lowered| return lowered;

        if (call.direct_target) |target| {
            var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
            call_ctx.evidence = self.evidence;
            defer call_ctx.deinit();
            call_ctx.owner_context_fn_key = self.owner_context_fn_key;
            call_ctx.current_fn_key = self.current_fn_key;
            call_ctx.source_region_override = self.source_region_override;
            call_ctx.current_entry_root = self.current_entry_root;

            const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
            var fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
                source_fn_ty,
                self,
                checked_ret_ty,
                call.args,
                expected_ret_node,
                try self.hostedTryCapabilityForResolvedTarget(target),
            );
            const iterator_procedure = self.iteratorProcedureForResolvedTarget(target);
            if (iterator_procedure) |procedure| {
                const public_fn_node = self.graph.requestSourceInterface(fn_node) orelse fn_node;
                if (try self.generatedIteratorFunctionNode(procedure, public_fn_node, fn_node, call.args)) |private_fn_node| {
                    try self.graph.registerRequestSourceInterface(private_fn_node, public_fn_node);
                    try relateFunctionRequestInterface(self.graph, public_fn_node, private_fn_node);
                    fn_node = private_fn_node;
                }
            }
            const fn_nodes = try self.graph.functionNodes(fn_node);
            try self.prepareExprSpanAtNodes(call.args, fn_nodes.args);
            if (try self.lowerDirectCallWithUninhabitedArgument(call.args, fn_nodes)) |lowered| return lowered;
            if (iterator_procedure) |procedure| {
                if (try self.lowerGeneratedIteratorNextCall(procedure, call.args, fn_nodes)) |lowered| return lowered;
            }
            const source_fn_key = call_ctx.view.types.rootKey(source_fn_ty);
            if (self.resolvedTargetIsStrInspect(target)) {
                const args = try self.lowerPreparedExprSpanAtNodes(call.args, fn_nodes.args);
                if (args.len != 1) Common.invariant("Str.inspect call did not have exactly one lowered argument");
                const callee = try self.fnTemplateForDirectCallAtNode(target, source_fn_ty, source_fn_key, fn_node);
                const captures = try self.directCallCaptureSpan(target);
                return .{
                    .ret_ty = DraftTypeCell.fromGraphNode(fn_nodes.ret),
                    .data = .{ .call_proc = .{
                        .callee = .{ .func = callee },
                        .args = args,
                        .iterator_procedure = iterator_procedure,
                        .captures = captures,
                    } },
                };
            }
            const callee = try self.fnTemplateForDirectCallAtNode(target, source_fn_ty, source_fn_key, fn_node);
            const callee_fn_node = try self.draftFnSlotTypeNode(callee, fn_node);
            const callee_fn_nodes = try self.graph.functionNodes(callee_fn_node);
            if (callee_fn_nodes.args.len != fn_nodes.args.len) {
                Common.invariant("completed direct-call specialization changed argument arity");
            }
            const lowered_args = try self.lowerPreparedExprSpanAtNodes(call.args, fn_nodes.args);
            const captures = try self.directCallCaptureSpan(target);
            return .{
                .ret_ty = DraftTypeCell.fromGraphNode(callee_fn_nodes.ret),
                .data = .{ .call_proc = .{
                    .callee = .{ .func = callee },
                    .args = lowered_args,
                    .iterator_procedure = iterator_procedure,
                    .captures = captures,
                } },
            };
        }

        if (try self.indirectCalleeMonoType(call.func, call.args, expected_ret_ty)) |fn_ty| {
            const fn_data = self.builder.functionShape(fn_ty, "checked call function type was not a function");
            try self.constrainTypeToMono(checked_ret_ty, fn_data.ret);
            if (expected_ret_ty) |expected| {
                if (!self.sameType(expected, fn_data.ret)) {
                    Common.invariant("checked indirect call result type differed from its expected Monotype type");
                }
            }
            return .{
                .ret_ty = .{ .sealed = fn_data.ret },
                .data = .{ .call_value = .{
                    .callee = try self.lowerExprAtType(call.func, fn_ty),
                    .args = try self.lowerExprSpanAtTypes(call.args, self.builder.program.types.span(fn_data.args)),
                } },
            };
        }

        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        const fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
            call.source_fn_ty_payload,
            self,
            checked_ret_ty,
            call.args,
            expected_ret_node,
            null,
        );
        const fn_nodes = try self.graph.functionNodes(fn_node);
        try self.prepareExprSpanAtNodes(call.args, fn_nodes.args);
        return .{
            .ret_ty = DraftTypeCell.fromGraphNode(fn_nodes.ret),
            .data = .{ .call_value = .{
                .callee = try self.lowerExprAtTypeCell(call.func, DraftTypeCell.fromGraphNode(fn_node)),
                .args = try self.lowerPreparedExprSpanAtNodes(call.args, fn_nodes.args),
            } },
        };
    }

    fn lowerGeneratedIteratorNextCall(
        self: *BodyContext,
        procedure: checked.IteratorProcedureId,
        checked_args: []const checked.CheckedExprId,
        fn_nodes: FunctionNodes,
    ) Allocator.Error!?LoweredCall {
        if (procedure != .iter_next) return null;
        if (checked_args.len != 1 or fn_nodes.args.len != 1) {
            Common.invariant("Iter.next reached Monotype with an unexpected arity");
        }
        const iterator_node = fn_nodes.args[0];
        if (!self.isGeneratedIteratorEvidenceNode(iterator_node)) return null;

        const iterator = try self.lowerExprAtTypeCell(
            checked_args[0],
            DraftTypeCell.fromGraphNode(iterator_node),
        );
        return .{
            .ret_ty = DraftTypeCell.fromGraphNode(fn_nodes.ret),
            .data = try self.lowerGeneratedIteratorNextData(iterator, iterator_node),
        };
    }

    fn lowerGeneratedIteratorNextData(
        self: *BodyContext,
        iterator: DraftExprId,
        iterator_node: NodeId,
    ) Allocator.Error!BodyExprData {
        const backing = self.graph.namedNodes(iterator_node).backing orelse
            Common.invariant("generated iterator next requested a type without backing");
        const step_name = try self.builder.program.names.internRecordFieldLabel("step");
        const step_node = try self.graph.opaqueDefinitionFieldNode(backing.node, step_name);
        const step = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(step_node),
            .{ .field_access = .{
                .receiver = iterator,
                .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = step_name }}),
            } },
        );
        return .{ .call_value = .{
            .callee = step,
            .args = .empty(),
        } };
    }

    fn lowerDirectCallWithUninhabitedArgument(
        self: *BodyContext,
        checked_args: []const checked.CheckedExprId,
        fn_nodes: FunctionNodes,
    ) Allocator.Error!?LoweredCall {
        for (fn_nodes.args, 0..) |arg_node, uninhabited_index| {
            if (!try self.nodeIsProvenUninhabited(arg_node)) continue;

            const prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
            defer self.allocator.free(prior);
            for (0..uninhabited_index) |index| {
                prior[index] = try self.lowerExprAtTypeCell(
                    checked_args[index],
                    DraftTypeCell.fromGraphNode(fn_nodes.args[index]),
                );
            }

            const uninhabited_cell = DraftTypeCell.fromGraphNode(arg_node);
            const scrutinee = try self.lowerUninhabitedScrutineeAtTypeCell(
                checked_args[uninhabited_index],
                uninhabited_cell,
            );
            const ret_cell = DraftTypeCell.fromGraphNode(fn_nodes.ret);
            var result = try self.addExprWithTypeCell(ret_cell, .{ .match_ = .{
                .scrutinee = scrutinee,
                .branches = try self.addBranchSpan(&.{}),
                .comptime_site = null,
            } });
            var index = uninhabited_index;
            while (index > 0) {
                index -= 1;
                const arg_cell = DraftTypeCell.fromGraphNode(fn_nodes.args[index]);
                result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                    .bind = try self.addPatWithTypeCell(arg_cell, .wildcard),
                    .value = prior[index],
                    .rest = result,
                } });
            }
            return .{
                .ret_ty = ret_cell,
                .data = try self.exprIdAsDivergentData(result),
            };
        }
        return null;
    }

    /// Materialize an indirect callee only when a binding use already provides
    /// a complete callable snapshot. Structured callees such as field accesses
    /// retain their graph nodes until their call request supplies every cell.
    fn indirectCalleeMonoType(
        self: *BodyContext,
        checked_func: checked.CheckedExprId,
        checked_args: []const checked.CheckedExprId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const expr = self.view.bodies.expr(checked_func);
        return switch (expr.data) {
            .lookup_local,
            .lookup_external,
            .lookup_required,
            => try self.localCalleeMonoType(checked_func, checked_args, expected_ret_ty),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn localCalleeMonoType(
        self: *BodyContext,
        checked_func: checked.CheckedExprId,
        checked_args: []const checked.CheckedExprId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const expr = self.view.bodies.expr(checked_func);
        const maybe_ref = switch (expr.data) {
            .lookup_local => |lookup| lookup.resolved,
            .lookup_external => |resolved| resolved,
            .lookup_required => |resolved| resolved,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        };
        const ref_id = maybe_ref orelse Common.invariant("checked callee lookup reached Monotype without resolved value ref");
        const local_id = (try self.currentLocalForResolvedValue(ref_id)) orelse return null;
        const fn_ty = switch (self.localTypeCell(local_id)) {
            .sealed => |ty| ty,
            .graph_node => return null,
        };
        const fn_data = self.builder.functionShape(fn_ty, "checked local callee type was not a function");
        const arg_tys = self.builder.program.types.span(fn_data.args);
        if (arg_tys.len != checked_args.len) Common.invariant("checked local callee arity differed from call arity");
        if (expected_ret_ty) |expected| {
            if (!self.sameType(expected, fn_data.ret)) return null;
        }
        for (checked_args) |checked_arg| {
            if (try self.callArgumentEvidenceNode(checked_arg, null)) |evidence_node| {
                if (try self.graph.containsGeneratedPrivate(evidence_node)) return null;
            }
        }
        return fn_ty;
    }

    fn directCallInstantiationSourceFnType(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        fallback: checked.CheckedTypeId,
    ) checked.CheckedTypeId {
        const raw = @intFromEnum(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        return switch (self.view.resolved_refs.records[raw].ref) {
            .platform_required_proc => |required| required.procedure.source_fn_ty_payload orelse
                Common.invariant("platform-required procedure call missing relation-owned requested function type"),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .promoted_top_level_proc => fallback,
        };
    }

    fn hostedTryCapabilityForResolvedTarget(
        self: *BodyContext,
        target: checked.ResolvedValueId,
    ) Allocator.Error!?HostedTryAdapterCapability {
        const raw = @intFromEnum(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        return switch (record.ref) {
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| try self.hostedTryCapabilityForProcedureUse(proc),
            .platform_required_proc => |proc| try self.hostedTryCapabilityForProcedureUse(proc.procedure),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => null,
        };
    }

    fn hostedTryCapabilityForProcedureUse(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
    ) Allocator.Error!?HostedTryAdapterCapability {
        const hosted = switch (proc.binding) {
            .hosted => |hosted| hosted,
            .top_level, .imported, .platform_required => return null,
        };
        const view = self.builder.moduleForId(checked.hostedProcedureTemplateModuleId(hosted));
        const template = view.templates.get(hosted.template.template);
        if (template.target != .hosted) {
            Common.invariant("hosted procedure use referenced a non-hosted template");
        }
        return try self.builder.hostedTryAdapterCapability(view, template.hosted_try_adapter);
    }

    fn lowerCallThatCannotReachCallee(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!?LoweredCall {
        if (self.checkedExprDivergesInLoweredRuntime(call.func)) {
            return try self.lowerDivergentCallOperand(checked_ret_ty, call.func, expected_ret_node);
        }
        for (call.args) |arg| {
            if (self.checkedExprDivergesInLoweredRuntime(arg)) {
                return try self.lowerDivergentCallOperand(checked_ret_ty, arg, expected_ret_node);
            }
        }
        return null;
    }

    fn lowerDivergentCallOperand(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        operand: checked.CheckedExprId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!LoweredCall {
        const ret_cell = if (expected_ret_node) |expected|
            DraftTypeCell.fromGraphNode(expected)
        else
            try self.lowerTypeCell(checked_ret_ty);
        try self.constrainCheckedInterfaceToCell(checked_ret_ty, ret_cell);
        const divergent = try self.lowerDivergentExprAtTypeCell(operand, ret_cell);
        return .{
            .ret_ty = ret_cell,
            .data = try self.exprIdAsDivergentData(divergent),
        };
    }

    /// Unify a callee formal with the caller's checked argument type. The
    /// checked type's cached cell may already carry a generated-private
    /// producer representation (e.g. a list literal of minted iterators), and
    /// private content never enters ordinary public unification: the formal
    /// gets a fresh public interface related opaquely, and the private node
    /// itself becomes the request argument.
    fn unifyFormalWithCallerArgNode(
        self: *BodyContext,
        caller: *BodyContext,
        formal_node: NodeId,
        arg_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        const arg_node = try caller.instNode(arg_ty);
        if (try self.graph.containsGeneratedPrivate(arg_node)) {
            const public_node = try caller.freshInstNode(arg_ty);
            try self.graph.relateOpaqueInterface(public_node, arg_node);
            try relateRequestComponent(self.graph, formal_node, public_node);
            return arg_node;
        }
        try relateRequestComponent(self.graph, formal_node, arg_node);
        return formal_node;
    }

    fn instantiateCallNodeFromCallerAtNode(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        checked_args: []const checked.CheckedExprId,
        expected_ret_node: ?NodeId,
        hosted_try_capability: ?HostedTryAdapterCapability,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != checked_args.len) {
            Common.invariant("checked direct call arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const fn_graph = switch (self.graph.content(fn_node)) {
            .func => |func| func,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked direct call had a non-function instantiation node"),
        };
        if (fn_graph.args.len != checked_args.len) {
            Common.invariant("checked direct call graph arity differed from its argument span");
        }
        const request_args = try self.graph.arena().alloc(NodeId, function.args.len);
        for (fn_graph.args, checked_args, 0..) |formal_node, checked_arg, index| {
            const arg_ty = caller.view.bodies.expr(checked_arg).ty;
            if (try caller.callArgumentEvidenceNode(checked_arg, null)) |evidence_node| {
                if (try self.graph.containsGeneratedPrivate(evidence_node)) {
                    const public_node = try caller.freshInstNode(arg_ty);
                    try self.graph.relateOpaqueInterface(public_node, evidence_node);
                    try relateRequestComponent(self.graph, formal_node, public_node);
                    request_args[index] = evidence_node;
                } else {
                    const request = try self.unifyFormalWithCallerArgNode(caller, formal_node, arg_ty);
                    try relateRequestComponent(self.graph, formal_node, evidence_node);
                    request_args[index] = request;
                }
            } else {
                request_args[index] = try self.unifyFormalWithCallerArgNode(caller, formal_node, arg_ty);
            }
        }
        if (expected_ret_node) |expected| {
            if (hosted_try_capability) |capability| {
                if (try self.hostedTryWidenedRequestNode(capability, fn_node, request_args, expected)) |request_fn| {
                    return request_fn;
                }
            }
            // An explicit request owns the call's exact result evidence. Keep
            // the checked result as a fresh public interface: its cached cell
            // may already contain private evidence from another occurrence.
            const public_ret = try caller.freshInstNode(checked_ret_ty);
            try relateRequestComponent(self.graph, fn_graph.ret, public_ret);
        } else {
            const caller_ret = try caller.instNode(checked_ret_ty);
            if (hosted_try_capability) |capability| {
                if (try self.hostedTryWidenedRequestNode(capability, fn_node, request_args, caller_ret)) |request_fn| {
                    return request_fn;
                }
            }
            if (try self.graph.containsGeneratedPrivate(caller_ret)) {
                // A prior occurrence may already have refined this cached cell
                // to a private producer representation. Preserve its public
                // interface without letting that representation select this
                // call's producer before the call itself has done so.
                const public_ret = try caller.freshInstNode(checked_ret_ty);
                try self.graph.relateOpaqueInterface(public_ret, caller_ret);
                try relateRequestComponent(self.graph, fn_graph.ret, public_ret);
            } else {
                try relateRequestComponent(self.graph, fn_graph.ret, caller_ret);
            }
        }
        var request_ret = fn_graph.ret;
        if (expected_ret_node) |expected| {
            request_ret = if (try self.graph.containsGeneratedPrivate(expected))
                expected
            else
                try checkedMonoRequestNode(self.graph, fn_graph.ret, expected);
        }
        return try functionRequestNode(self.graph, fn_node, request_args, request_ret);
    }

    fn hostedTryWidenedRequestNode(
        self: *BodyContext,
        capability: HostedTryAdapterCapability,
        source_fn: NodeId,
        request_args: []const NodeId,
        request_ret: NodeId,
    ) Allocator.Error!?NodeId {
        if (!try hostedTryWideningRequestHasAdditionalErrors(self.graph, capability, source_fn, request_ret)) {
            return null;
        }
        const request_fn = try self.graph.newNode(.{ .func = .{
            .args = try self.graph.arena().dupe(NodeId, request_args),
            .ret = request_ret,
        } });
        if (!try relateHostedTryWidening(self.graph, capability, source_fn, request_fn)) {
            Common.invariant("hosted Try widening request lost its additional error labels");
        }
        try self.graph.registerRequestSourceInterface(request_fn, source_fn);
        return request_fn;
    }

    fn instantiateCallableDispatchPlanCallNodeFromCaller(
        self: *BodyContext,
        callable_plan: CallableDispatchPlan,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return try self.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            caller,
            checked_ret_ty,
            if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
            .expression_lowering,
        );
    }

    fn instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
        self: *BodyContext,
        callable_plan: CallableDispatchPlan,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
    ) Allocator.Error!NodeId {
        const plan = callable_plan.plan;
        const operands = callable_plan.operands;
        const source_fn_ty = plan.callable_ty;
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != operands.len) {
            Common.invariant("checked dispatch plan arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const fn_graph = switch (self.graph.content(fn_node)) {
            .func => |func| func,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function instantiation node"),
        };
        if (fn_graph.args.len != operands.len) {
            Common.invariant("checked dispatch plan graph arity differed from its operand span");
        }
        switch (plan.dispatcher) {
            .arg => |index| {
                if (index >= fn_graph.args.len) Common.invariant("dispatch plan dispatcher argument index was outside the callable graph");
                const dispatcher_node = try caller.instNode(plan.dispatcher_ty);
                try relateRequestComponent(self.graph, fn_graph.args[index], dispatcher_node);
            },
            .type_only => {},
        }
        const request_args = try self.graph.arena().alloc(NodeId, function.args.len);
        for (fn_graph.args, operands, request_args) |formal_node, operand, *request_arg| {
            request_arg.* = formal_node;
            switch (operand) {
                .checked_expr => |checked_arg| {
                    const arg_ty = caller.view.bodies.expr(checked_arg).ty;
                    if (phase == .expression_lowering) {
                        const evidence_node = try caller.lowerExprTypeNode(checked_arg);
                        if (try self.graph.containsGeneratedPrivate(evidence_node)) {
                            const public_node = try caller.freshInstNode(arg_ty);
                            try self.graph.relateOpaqueInterface(public_node, evidence_node);
                            try relateRequestComponent(self.graph, formal_node, public_node);
                            request_arg.* = evidence_node;
                        } else {
                            const public_node = try caller.instNode(arg_ty);
                            try relateRequestComponent(self.graph, formal_node, public_node);
                            try relateRequestComponent(self.graph, formal_node, evidence_node);
                        }
                    } else {
                        try relateRequestComponent(self.graph, formal_node, try caller.instNode(arg_ty));
                    }
                },
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
        var request_ret = fn_graph.ret;
        if (expected_ret_node) |expected| {
            try relateRequestComponent(self.graph, fn_graph.ret, try caller.freshInstNode(checked_ret_ty));
            request_ret = if (try self.graph.containsGeneratedPrivate(expected))
                expected
            else
                try checkedMonoRequestNode(self.graph, fn_graph.ret, expected);
        } else {
            const caller_ret = try caller.instNode(checked_ret_ty);
            if (try self.graph.containsGeneratedPrivate(caller_ret)) {
                const public_ret = try caller.freshInstNode(checked_ret_ty);
                try self.graph.relateOpaqueInterface(public_ret, caller_ret);
                try relateRequestComponent(self.graph, fn_graph.ret, public_ret);
            } else {
                try relateRequestComponent(self.graph, fn_graph.ret, caller_ret);
            }
        }
        return try functionRequestNode(self.graph, fn_node, request_args, request_ret);
    }

    fn relateFormalToOperand(
        self: *BodyContext,
        formal_node: NodeId,
        caller: *BodyContext,
        operand: static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!void {
        switch (operand) {
            .checked_expr => |checked_arg| {
                const arg_ty = caller.view.bodies.expr(checked_arg).ty;
                try relateRequestComponent(self.graph, formal_node, try caller.instNode(arg_ty));
            },
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => {},
        }
    }

    fn instantiateNumeralPlanCallNode(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        caller: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        target_ty: Type.TypeId,
        operands: []const static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != operands.len) {
            Common.invariant("checked from_numeral plan arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const fn_graph = switch (self.graph.content(fn_node)) {
            .func => |func| func,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked from_numeral plan had a non-function instantiation node"),
        };
        if (fn_graph.args.len != operands.len) {
            Common.invariant("checked from_numeral plan graph arity differed from its operand span");
        }
        // The numeral expression's checked type is the converted value type;
        // the plan's checked structure relates it to the Try-shaped return.
        try self.graph.unify(try caller.instNode(checked_ret_ty), try self.graph.importMono(target_ty));
        try self.graph.unify(try self.instNode(checked_ret_ty), try self.graph.importMono(target_ty));
        for (fn_graph.args, operands) |formal_node, operand| {
            try self.relateFormalToOperand(formal_node, caller, operand);
        }
        return fn_node;
    }

    fn instantiateTargetFromPlanNode(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        plan_ctx: *BodyContext,
        plan_fn_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        const plan_function = plan_ctx.checkedFunctionType(plan_fn_ty);
        if (function.args.len != plan_function.args.len) {
            Common.invariant("checked dispatch target arity differed from its dispatch plan");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const plan_node = try plan_ctx.instNode(plan_fn_ty);
        try relateFunctionRequestInterface(self.graph, fn_node, plan_node);
        return fn_node;
    }

    fn instantiateTargetCallTypeFromMonoArgs(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const fn_node = try self.instantiateTargetCallNodeFromMonoArgs(source_fn_ty, arg_tys, ret_ty);
        return try self.activeTypeFromNode(fn_node);
    }

    fn instantiateTargetCallNodeFromMonoArgs(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != arg_tys.len) {
            Common.invariant("checked synthetic dispatch target arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const function_nodes = try self.graph.functionNodes(fn_node);
        if (function_nodes.args.len != arg_tys.len) {
            Common.invariant("checked synthetic dispatch target graph arity differed from its argument span");
        }
        const request_args = try self.graph.arena().alloc(NodeId, function_nodes.args.len);
        for (function_nodes.args, arg_tys, request_args) |formal_node, arg_ty, *request_arg| {
            request_arg.* = try checkedMonoRequestNode(
                self.graph,
                formal_node,
                try self.graph.importMono(arg_ty),
            );
        }
        const request_ret = try checkedMonoRequestNode(
            self.graph,
            function_nodes.ret,
            try self.graph.importMono(ret_ty),
        );
        return try functionRequestNode(self.graph, fn_node, request_args, request_ret);
    }

    /// Return exact producer evidence for a call operand without sealing and
    /// re-importing a live result node. Lookup-only evidence may already be a
    /// finished Monotype snapshot, so the lookup path retains its TypeId edge.
    fn callArgumentEvidenceNode(
        self: *BodyContext,
        checked_arg: checked.CheckedExprId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?NodeId {
        if (self.checkedExprDivergesInLoweredRuntime(checked_arg)) return null;
        const expr = self.view.bodies.expr(checked_arg);
        switch (expr.data) {
            .call => |call| {
                if (call.direct_target) |target| {
                    const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                    const fn_node = try self.directCallTypeNode(
                        expr.ty,
                        call,
                        source_fn_ty,
                        if (expected_ty) |expected| try self.activeNodeFromType(expected) else null,
                    );
                    const fn_nodes = try self.graph.functionNodes(fn_node);
                    if (self.isGeneratedIteratorEvidenceNode(fn_nodes.ret)) return fn_nodes.ret;
                    if (self.isIteratorInterfaceNode(fn_nodes.ret)) {
                        try self.ensureNestedCallablesAtNodes(call.args, fn_nodes.args);
                        const callee = try self.fnTemplateForDirectCallAtNode(
                            target,
                            source_fn_ty,
                            self.view.types.rootKey(source_fn_ty),
                            fn_node,
                        );
                        const completed_fn_node = try self.draftFnSlotTypeNode(callee, fn_node);
                        return (try self.graph.functionNodes(completed_fn_node)).ret;
                    }
                    return fn_nodes.ret;
                }
                return try self.callResultTypeNode(expr.ty, call, expected_ty);
            },
            .dispatch_call => |plan| return try self.dispatchResultTypeNode(expr.ty, plan, expected_ty),
            .interpolation => |interpolation| return try self.dispatchResultTypeNode(expr.ty, interpolation.plan, expected_ty),
            .type_dispatch_call => |plan| return try self.dispatchResultTypeNode(expr.ty, plan, expected_ty),
            .method_eq => |plan| return try self.dispatchResultTypeNode(expr.ty, plan, expected_ty),
            .field_access => |field| return try self.fieldAccessTypeNode(expr.ty, field, expected_ty),
            .lookup_local => |lookup| return try self.lookupCallArgumentEvidenceNode(expr.ty, lookup.resolved, expected_ty),
            .lookup_external => |resolved| return try self.lookupCallArgumentEvidenceNode(expr.ty, resolved, expected_ty),
            .lookup_required => |resolved| return try self.lookupCallArgumentEvidenceNode(expr.ty, resolved, expected_ty),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        if (expected_ty) |ty| {
            try self.constrainTypeToMono(expr.ty, ty);
            return try self.activeNodeFromType(ty);
        }
        return null;
    }

    fn lookupCallArgumentEvidenceNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?NodeId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        local: {
            switch (record.ref) {
                // A selected hoisted constant has a local binder only while
                // lowering its own root; the ConstStore path below serves
                // every other use.
                .selected_hoisted_const => break :local,
                .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
            }
            if ((try self.currentLocalForResolvedValue(ref_id)) == null) break :local;
            // A generated-private evidence node (e.g. a minted iterator) may
            // still carry unresolved leaves whose defaults apply at final
            // sealing, so it stays a graph node instead of forcing an eager
            // resolved view.
            if (try self.localCallArgumentEvidenceNode(checked_ty, ref_id, expected_ty)) |node| return node;
            return if (expected_ty) |ty| try self.activeNodeFromType(ty) else null;
        }
        return if (try self.lookupCallArgumentMonoType(checked_ty, maybe_ref, expected_ty)) |ty|
            try self.activeNodeFromType(ty)
        else
            null;
    }

    fn lookupCallArgumentMonoType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        switch (record.ref) {
            .selected_hoisted_const => |selected| {
                // A selected hoisted constant has a local binder only while
                // lowering its own root. Every other use consumes the
                // checker-selected ConstStore entry directly.
                if (try self.selectedHoistedConstMonoType(selected, checked_ty)) |ty| return ty;
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
        }
        if ((try self.currentLocalForResolvedValue(ref_id)) != null) {
            return try self.localCallArgumentEvidenceType(checked_ty, ref_id, expected_ty);
        }
        return switch (record.ref) {
            .top_level_const,
            .imported_const,
            .platform_required_const,
            .local_proc,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .platform_required_declaration, .platform_required_checked_error => try self.lookupExprMonoType(checked_ty, ref_id),
        };
    }

    fn localCallArgumentEvidenceType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        ref_id: checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const node = (try self.localCallArgumentEvidenceNode(checked_ty, ref_id, expected_ty)) orelse
            return expected_ty;
        return try self.activeTypeFromNode(node);
    }

    /// Constrain a local call argument's cell and return its evidence node
    /// when the local carries generated-private content; otherwise the
    /// caller's expected type (if any) is the evidence.
    fn localCallArgumentEvidenceNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        ref_id: checked.ResolvedValueId,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!?NodeId {
        const local_id = (try self.currentLocalForResolvedValue(ref_id)) orelse
            Common.invariant("local call argument evidence requested without a current local");
        const cell = self.localTypeCell(local_id);
        const node = switch (cell) {
            .graph_node => |graph_node| graph_node,
            .sealed => |ty| try self.activeNodeFromType(ty),
        };
        try self.constrainCheckedInterfaceToCell(checked_ty, cell);
        if (expected_ty) |expected| try self.graph.unify(node, try self.graph.importMono(expected));
        return if (try self.graph.containsGeneratedPrivate(node)) node else null;
    }

    fn lookupExprTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
    ) Allocator.Error!NodeId {
        const ref_id = maybe_ref orelse
            Common.invariant("checked lookup reached Monotype without a resolved value ref");
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            const local_id = binding.local;
            const node = switch (self.localTypeCell(local_id)) {
                .graph_node => |graph_node| graph_node,
                .sealed => |ty| try self.activeNodeFromType(ty),
            };
            try self.constrainCheckedInterfaceToCell(checked_ty, self.localTypeCell(local_id));
            return node;
        }
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        switch (record.ref) {
            .selected_hoisted_const => |selected| return try self.constUseTypeNode(checked_ty, selected.const_use),
            .top_level_const => |const_use| return try self.constUseTypeNode(checked_ty, const_use),
            .imported_const => |const_use| return try self.constUseTypeNode(checked_ty, const_use),
            .platform_required_const => |required| return try self.constUseTypeNode(checked_ty, required.const_use),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => {},
        }
        return try self.lowerTypeNode(checked_ty);
    }

    fn lookupExprMonoType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
    ) Allocator.Error!Type.TypeId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        switch (record.ref) {
            .local_value,
            .pattern_binder,
            => {},
            .selected_hoisted_const => |selected| {
                if (try self.selectedHoistedConstMonoType(selected, checked_ty)) |ty| return ty;
            },
            .local_param,
            .local_mutable_version,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
        if (try self.currentLocalForResolvedValue(ref_id)) |local_id| {
            const local_ty = try self.localType(local_id);
            try self.relateCheckedTypeToMono(checked_ty, local_ty);
            return local_ty;
        }
        return switch (record.ref) {
            .top_level_const => |const_use| try self.constUseMonoType(const_use),
            .imported_const => |const_use| try self.constUseMonoType(const_use),
            .platform_required_const => |required| try self.constUseMonoType(required.const_use),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_proc,
            .promoted_top_level_proc,
            => try self.lowerTypeView(checked_ty),
        };
    }

    fn fieldAccessTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        access: anytype,
        expected_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        if (access.segments.len == 0) Common.invariant("checked field access path had no segments");
        var saw_optional = false;
        var field_node = try self.lowerExprTypeNode(access.receiver);
        for (access.segments, 0..) |segment, index| {
            const is_last = index + 1 == access.segments.len;
            const mono_field_name = try self.builder.recordFieldName(self.view, segment.field_name);
            switch (segment.mode) {
                // A required segment's slot IS the field's value: the chain
                // continues from the receiver-derived slot node so a
                // producer-authored (generated-private) representation—e.g.
                // a stored iterator witness—survives the access. The
                // segment's checked success type relates to the slot only as
                // its public interface, never by direct unification; the
                // final segment's relation is the trailing whole-expression
                // constraint below.
                .required => {
                    const slot_node = switch (segment.backing_access) {
                        .inspectable => try self.graph.requiredRecordFieldNode(field_node, mono_field_name),
                        .opaque_definition_private => try self.graph.requiredOpaqueDefinitionFieldNode(field_node, mono_field_name),
                    };
                    if (!is_last) {
                        try self.constrainCheckedInterfaceToCell(
                            segment.success_ty,
                            DraftTypeCell.fromGraphNode(slot_node),
                        );
                    }
                    field_node = slot_node;
                },
                // A `.?` segment's slot is the tagged representation of the
                // value; the chain continues from the Present payload.
                .optional => {
                    saw_optional = true;
                    const field = switch (segment.backing_access) {
                        .inspectable => try self.graph.optionalRecordFieldNodes(field_node, mono_field_name),
                        .opaque_definition_private => try self.graph.optionalOpaqueDefinitionFieldNodes(field_node, mono_field_name),
                    };
                    const value_node = try self.instNode(segment.success_ty);
                    try self.graph.unify(field.value, value_node);
                    try self.graph.unify(field.slot, try self.optionalSlotNode(value_node));
                    field_node = field.value;
                },
            }
        }
        if (saw_optional) {
            // The chain's observable type is the checked expression's own
            // `Try(τ, [MissingField])` from the checking output; constrain
            // its Ok argument with the receiver-refined final value node
            // (instNode caches by checked identity, so this reaches the Try
            // node's arg).
            try self.graph.unify(field_node, try self.instNode(self.checkedTryOkArg(checked_ty)));
            field_node = try self.instNode(checked_ty);
        }
        try self.constrainCheckedInterfaceToCell(
            checked_ty,
            DraftTypeCell.fromGraphNode(field_node),
        );
        if (expected_ty) |expected| {
            try relateRequestComponent(self.graph, try self.graph.importMono(expected), field_node);
        }
        return field_node;
    }

    /// The Ok type argument of a checked nominal `Try` type (behind
    /// transparent aliases)—the type the checker gave an optional access
    /// chain's successful value.
    fn checkedTryOkArg(self: *BodyContext, checked_try_ty: checked.CheckedTypeId) checked.CheckedTypeId {
        var current = checked_try_ty;
        while (true) {
            switch (checkedPayload(self.view, current)) {
                .alias => |alias| current = alias.backing,
                .nominal => |nominal| {
                    if (nominal.args.len != 2) {
                        Common.invariant("optional access chain's checked Try type did not carry two type arguments");
                    }
                    return nominal.args[0];
                },
                .pending, .err, .flex, .rigid, .record, .record_unbound, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => Common.invariant("optional access chain's checked type was not a nominal Try"),
            }
        }
    }

    fn callResultMonoType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ret_node = try self.callResultTypeNode(checked_ret_ty, call, expected_ret_ty);
        if (expected_ret_ty) |expected| return expected;
        return try self.activeTypeFromNode(ret_node);
    }

    fn callResultTypeNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        if (call.direct_target == null) {
            if (try self.indirectCalleeMonoType(call.func, call.args, expected_ret_ty)) |fn_ty| {
                const ret_ty = self.functionReturnType(fn_ty);
                if (expected_ret_ty) |expected| {
                    if (!self.sameType(expected, ret_ty)) {
                        Common.invariant("checked indirect call result type differed from its expected Monotype type");
                    }
                    try self.constrainTypeToMono(checked_ret_ty, expected);
                    return try self.activeNodeFromType(expected);
                }
                try self.constrainTypeToMono(checked_ret_ty, ret_ty);
                return try self.activeNodeFromType(ret_ty);
            }

            var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
            call_ctx.evidence = self.evidence;
            defer call_ctx.deinit();
            call_ctx.owner_context_fn_key = self.owner_context_fn_key;
            call_ctx.current_fn_key = self.current_fn_key;
            call_ctx.source_region_override = self.source_region_override;
            call_ctx.current_entry_root = self.current_entry_root;

            const fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
                call.source_fn_ty_payload,
                self,
                checked_ret_ty,
                call.args,
                if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
                null,
            );
            return switch (self.graph.content(fn_node)) {
                .func => |function| function.ret,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked indirect call instantiated a non-function graph node"),
            };
        }

        const source_fn_ty = self.directCallInstantiationSourceFnType(call.direct_target.?, call.source_fn_ty_payload);
        const fn_node = try self.directCallTypeNode(
            checked_ret_ty,
            call,
            source_fn_ty,
            if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
        );
        return switch (self.graph.content(fn_node)) {
            .func => |function| function.ret,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked direct call instantiated a non-function graph node"),
        };
    }

    fn directCallTypeNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        source_fn_ty: checked.CheckedTypeId,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!NodeId {
        if (call.direct_target == null) {
            Common.invariant("direct checked call instantiation received an indirect call");
        }
        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;
        var fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
            source_fn_ty,
            self,
            checked_ret_ty,
            call.args,
            expected_ret_node,
            try self.hostedTryCapabilityForResolvedTarget(call.direct_target.?),
        );
        if (self.iteratorProcedureForResolvedTarget(call.direct_target.?)) |procedure| {
            const public_fn_node = self.graph.requestSourceInterface(fn_node) orelse fn_node;
            if (try self.generatedIteratorFunctionNode(procedure, public_fn_node, fn_node, call.args)) |private_fn_node| {
                try self.graph.registerRequestSourceInterface(private_fn_node, public_fn_node);
                try relateFunctionRequestInterface(self.graph, public_fn_node, private_fn_node);
                fn_node = private_fn_node;
            }
        }
        return fn_node;
    }

    fn fnTemplateForDirectCallAtNode(
        self: *BodyContext,
        target: checked.ResolvedValueId,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnSlot {
        const raw = @intFromEnum(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        const evidence = try self.evidenceForUseSite(record.expr);
        return switch (record.ref) {
            .local_proc => |local| .{ .local = try self.lowerDraftLocalProcAtNode(
                local,
                self.view,
                try self.localProcContextId(self.view, local.binder, local.expr),
                source_fn_ty,
                source_fn_key,
                request_fn_node,
                evidence,
            ) },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| try self.draftFnSlotForProcedureUseAtNode(proc, source_fn_ty, source_fn_key, request_fn_node, evidence, null),
            .platform_required_proc => |proc| try self.draftFnSlotForProcedureUseAtNode(
                proc.procedure,
                source_fn_ty,
                source_fn_key,
                request_fn_node,
                evidence,
                proc.root_evidence,
            ),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => Common.invariant("checked direct call target was not a procedure"),
        };
    }

    fn draftFnSlotForProcedureUseAtNode(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
        evidence: []const SpecEvidence,
        root_evidence: ?checked.CheckedEvidenceSpan,
    ) Allocator.Error!DraftFnSlot {
        const template_ref = self.builder.templateRefForProcedureUse(proc);
        const requested_evidence = if (root_evidence) |producer_evidence|
            try self.builder.materializeCheckedProcedureEvidence(template_ref, producer_evidence)
        else
            evidence;
        return try self.builder.lowerDraftTemplateFromContext(
            self,
            template_ref,
            source_fn_ty,
            source_fn_key,
            request_fn_node,
            requested_evidence,
            .resolved,
            if (proc.iterator_procedure == .iter_from_step) .exact_graph else .independent_roots,
        );
    }

    fn lowerDraftLocalProcAtNode(
        self: *BodyContext,
        local: checked.LocalProcedureBinding,
        local_view: ModuleView,
        context_id: DraftLocalProcContextId,
        source_fn_ty: checked.CheckedTypeId,
        source_fn_key: names.TypeDigest,
        request_fn_node: NodeId,
        evidence: []const SpecEvidence,
    ) Allocator.Error!DraftFnTarget {
        const context = self.validateLocalProcContext(
            context_id,
            local_view.key.bytes,
            local.binder,
            local.expr,
            null,
        );
        const previous_view = self.view;
        const previous_source_file_id = self.source_file_id;
        const local_source_file_id = try self.draft.sourceFileIdFor(local_view.module_identity.module_idx, local_view.module_env.module_name);
        self.view = local_view;
        self.source_file_id = local_source_file_id;
        defer {
            self.view = previous_view;
            self.source_file_id = previous_source_file_id;
        }
        const crosses_module = !moduleBytesEqual(previous_view.key.bytes, local_view.key.bytes);
        const previous_binders = self.binders;
        const previous_typed_binders = self.typed_binders;
        if (crosses_module) {
            self.binders = try BinderMap.init(self.allocator, local_view.bodies.patternBinderCount());
            self.typed_binders = TypedBinders.init(self.allocator);
        }
        defer if (crosses_module) {
            self.binders.deinit();
            self.typed_binders.deinit();
            self.binders = previous_binders;
            self.typed_binders = previous_typed_binders;
        };
        var installed_context = try self.installLocalProcContext(context);
        defer installed_context.deinit();
        const previous_owner_template = self.owner_template;
        self.owner_template = context.owner_template;
        defer self.owner_template = previous_owner_template;
        const context_fn_key = self.localProcUseContextKey(context);
        const nested = try self.builder.nestedFnForExpr(
            self.view,
            context.owner_template,
            local.expr,
            context_fn_key,
            try self.localProcContextsDigest(),
        );
        const requested_evidence = if (local.dispatch_scope) |scope|
            try enterEvidenceScope(self.builder, context.evidence, scope, local.expr, evidence)
        else blk: {
            if (evidence.len != 0) {
                Common.invariant("local procedure without a checked evidence scope received use evidence");
            }
            break :blk context.evidence;
        };
        const lexical_owner_scope = try self.draft.enterOwner(context.lexical_owner);
        defer lexical_owner_scope.leave();
        // The declaration context's capture types are part of the
        // specialization identity: two enclosing instantiations can request
        // this local procedure at the same monomorphic function type while
        // capturing at different types, and those must not share a body.
        const capture_bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(capture_bindings);
        const capture_entry_guards = try self.graph.arena().alloc(NodeId, capture_bindings.len);
        for (capture_bindings, capture_entry_guards) |binding, *node| {
            node.* = try binding.ty.toGraphNode(self.graph);
        }
        return try self.builder.lowerDraftNestedFromContext(
            self,
            local.expr,
            nested,
            source_fn_ty,
            source_fn_key,
            request_fn_node,
            capture_entry_guards,
            requested_evidence,
            local.dispatch_scope,
            .independent_roots,
        );
    }

    const LocalProcCaptureBinding = struct {
        local: DraftLocalId,
        ty: DraftTypeCell,
    };

    /// The lexical-context bindings a local procedure captures at its
    /// declaration, deduplicated by CaptureId (first entry wins). Every
    /// consumer of a declaration context—capture entry guards, fn-def
    /// capture spans, and direct-call capture operands—derives from this one
    /// walk so they agree on count and order. Caller owns the returned slice.
    fn localProcCaptureBindings(
        self: *BodyContext,
        context: LocalProcContext,
    ) Allocator.Error![]LocalProcCaptureBinding {
        var seen = collections.DenseMap(checked.CaptureId, void).init(self.allocator);
        defer seen.deinit();
        var bindings = std.ArrayList(LocalProcCaptureBinding).empty;
        errdefer bindings.deinit(self.allocator);

        for (context.entries) |entry| {
            const local: DraftLocalId = @enumFromInt(entry.local);
            const raw = @intFromEnum(local);
            if (raw >= self.draft.locals.items.len) {
                Common.invariant("local procedure context capture referenced an unknown local");
            }
            const local_data = self.draft.locals.items[raw];
            const capture_id = local_data.capture_id orelse
                Common.invariant("local procedure context capture local had no capture identity");
            const seen_entry = try seen.getOrPut(capture_id);
            if (seen_entry.found_existing) continue;
            try bindings.append(self.allocator, .{ .local = local, .ty = local_data.ty });
        }

        return try bindings.toOwnedSlice(self.allocator);
    }

    fn localProcFnDefCaptureSpan(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) Allocator.Error!DraftSpan(DraftFnDefCapture) {
        const context = self.validateLocalProcContext(
            context_id,
            module,
            binder,
            expr,
            context_anchor,
        );
        if (context.entries.len == 0) return DraftSpan(DraftFnDefCapture).empty();

        const bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(bindings);
        var captures = std.ArrayList(DraftFnDefCapture).empty;
        defer captures.deinit(self.allocator);
        try captures.ensureTotalCapacityPrecise(self.allocator, bindings.len);

        for (bindings) |binding| {
            const value = try self.addExprWithTypeCell(
                binding.ty,
                .{ .local = binding.local },
            );
            captures.appendAssumeCapacity(.{ .local = binding.local, .value = value });
        }

        return try self.addFnDefCaptureSpan(captures.items);
    }

    fn localProcCaptureExprSpan(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const context = self.validateLocalProcContext(
            context_id,
            module,
            binder,
            expr,
            context_anchor,
        );
        if (context.entries.len == 0) return DraftSpan(DraftExprId).empty();

        const bindings = try self.localProcCaptureBindings(context);
        defer self.allocator.free(bindings);
        var captures = std.ArrayList(DraftExprId).empty;
        defer captures.deinit(self.allocator);
        try captures.ensureTotalCapacityPrecise(self.allocator, bindings.len);

        for (bindings) |binding| {
            captures.appendAssumeCapacity(try self.addExprWithTypeCell(
                binding.ty,
                .{ .local = binding.local },
            ));
        }

        return try self.addExprSpan(captures.items);
    }

    fn directCallCaptureSpan(self: *BodyContext, target: checked.ResolvedValueId) Allocator.Error!DraftSpan(DraftExprId) {
        const raw = @intFromEnum(target);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked direct call target is outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        return switch (record.ref) {
            .local_proc => |local| try self.localProcCaptureExprSpan(
                try self.localProcContextId(self.view, local.binder, local.expr),
                self.view.key.bytes,
                local.binder,
                local.expr,
                null,
            ),
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => DraftSpan(DraftExprId).empty(),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => Common.invariant("checked direct call target was not a procedure"),
        };
    }

    fn methodTargetCaptureSpan(self: *BodyContext, lookup: MethodLookup) Allocator.Error!DraftSpan(DraftExprId) {
        return switch (lookup.target.kind) {
            .local_proc => |local| try self.localProcCaptureExprSpan(
                lookup.local_proc_context orelse
                    Common.invariant("local method target did not carry its declaration context"),
                lookup.view.key.bytes,
                local.binder,
                local.expr,
                local.context_anchor,
            ),
            .procedure,
            .structural,
            => DraftSpan(DraftExprId).empty(),
        };
    }

    fn currentLocalBindingForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) ?CurrentLocal {
        const raw = @intFromEnum(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        return switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| .{
                .binder = local.binder,
                .local = self.binders.get(local.binder) orelse
                    Common.invariant("local lookup referenced an unbound pattern binder"),
            },
            .selected_hoisted_const => |selected| if (self.binders.get(selected.local.binder)) |local|
                .{ .binder = selected.local.binder, .local = local }
            else
                null,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
        };
    }

    fn currentConstLocalForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) Allocator.Error!?DraftLocalId {
        var active_id = self.active_const_binding;
        if (active_id == null) return null;
        const raw = @intFromEnum(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        const const_use = switch (record.ref) {
            .top_level_const => |value| value,
            .imported_const => |value| value,
            .platform_required_const => |required| required.const_use,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => return null,
        };
        while (active_id) |id| {
            const index = @intFromEnum(id);
            const active = self.draft.active_const_bindings.items[index];
            if (constUseEql(active.const_use, const_use.const_ref)) {
                self.draft.active_const_bindings.items[index].used = true;
                try self.materializeActiveConstBinding(id);
                return active.local;
            }
            active_id = active.parent;
        }
        return null;
    }

    fn markActiveConstBinderUsed(self: *BodyContext, binder: checked.PatternBinderId) Allocator.Error!void {
        var active_id = self.active_const_binding;
        while (active_id) |id| {
            const index = @intFromEnum(id);
            const active = self.draft.active_const_bindings.items[index];
            if (moduleBytesEqual(checked.constModuleId(active.const_use).bytes, self.view.key.bytes) and active.binder == binder) {
                self.draft.active_const_bindings.items[index].used = true;
                try self.materializeActiveConstBinding(id);
                return;
            }
            active_id = active.parent;
        }
    }

    fn topLevelConstBinderForUse(store_view: ModuleView, const_use: checked.ConstLocator) ?checked.PatternBinderId {
        const owner = switch (const_use.owner) {
            .top_level_binding => |owner| owner,
            .hoisted_expr => return null,
        };
        if (!moduleBytesEqual(checked.constModuleId(const_use).bytes, store_view.key.bytes)) {
            Common.invariant("top-level const template referenced a different checked module");
        }
        const root_id = store_view.compile_time_roots.lookupIdByPattern(owner.pattern) orelse
            Common.invariant("top-level const template had no compile-time root");
        const root = store_view.compile_time_roots.root(root_id);
        if (root.kind != .constant) {
            Common.invariant("top-level const template did not reference a constant root");
        }
        if (root.module_idx != owner.module_idx) {
            Common.invariant("top-level const template root had a mismatched module index");
        }
        const pattern = root.pattern orelse
            Common.invariant("top-level const template root had no checked pattern");
        if (pattern != owner.pattern) {
            Common.invariant("top-level const template root had a mismatched checked pattern");
        }
        return switch (store_view.bodies.pattern(pattern).data) {
            .assign => |binder| binder,
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("top-level const root pattern was not a binder"),
        };
    }

    fn inheritActiveConstBinding(self: *BodyContext, parent: *BodyContext) Allocator.Error!void {
        try self.inheritActiveConstBindingId(parent.active_const_binding);
    }

    fn inheritActiveConstBindingId(self: *BodyContext, active_id: ?ActiveConstBindingId) Allocator.Error!void {
        self.active_const_binding = active_id;
        var chain = std.ArrayList(ActiveConstBindingId).empty;
        defer chain.deinit(self.allocator);
        var cursor = active_id;
        while (cursor) |id| {
            try chain.append(self.allocator, id);
            cursor = self.draft.active_const_bindings.items[@intFromEnum(id)].parent;
        }
        var index = chain.items.len;
        while (index > 0) {
            index -= 1;
            const active = self.draft.active_const_bindings.items[@intFromEnum(chain.items[index])];
            if (!moduleBytesEqual(checked.constModuleId(active.const_use).bytes, self.view.key.bytes)) continue;
            try self.binders.put(active.binder, active.local);
        }
    }

    fn enterActiveConstBindingAtCell(
        self: *BodyContext,
        store_view: ModuleView,
        const_use: checked.ConstLocator,
        cell: DraftTypeCell,
        scope: *ActiveConstBindingScope,
    ) Allocator.Error!bool {
        const binder = topLevelConstBinderForUse(store_view, const_use) orelse return false;
        const local = try self.addFreshLocalWithBinderCell(
            self.builder.symbols.fresh(),
            cell,
            binder,
        );
        try self.bindLocalNameFromView(store_view, local, binder);
        const reservation = try self.addExprWithTypeCell(cell, .pending_deferred);
        const active_id: ActiveConstBindingId = @enumFromInt(@as(u32, @intCast(self.draft.active_const_bindings.items.len)));
        try self.draft.active_const_bindings.append(self.allocator, .{
            .parent = self.active_const_binding,
            .const_use = const_use,
            .binder = binder,
            .local = local,
            .cell = cell,
            .owner = self.draft.current_owner,
            .reservation = reservation,
        });
        const bound_in_current_view = moduleBytesEqual(
            checked.constModuleId(const_use).bytes,
            self.view.key.bytes,
        );
        scope.* = .{
            .active = active_id,
            .previous_active = self.active_const_binding,
            .binder = binder,
            .previous_local = if (bound_in_current_view) self.binders.get(binder) else null,
            .bound_in_current_view = bound_in_current_view,
            .entered = true,
        };
        // Pattern binder IDs are dense and local to a checked module. A const
        // restored from another module must remain in the active-const chain so
        // recursive uses preserve their identity, but its binder cannot be
        // installed in this module's lexical binder map. When lowering enters
        // the const's own module, inheritActiveConstBindingId installs it there.
        if (bound_in_current_view) {
            try self.binders.put(binder, local);
        }
        self.active_const_binding = active_id;
        return true;
    }

    fn copyActiveConstReservation(self: *BodyContext, reservation: DraftExprId, source: DraftExprId) void {
        const reservation_index = @intFromEnum(reservation);
        const source_index = @intFromEnum(source);
        self.draft.exprs.items[reservation_index] = self.draft.exprs.items[source_index];
        self.draft.expr_locs.items[reservation_index] = self.draft.expr_locs.items[source_index];
        self.draft.expr_regions.items[reservation_index] = self.draft.expr_regions.items[source_index];
        self.draft.expr_impossibility_proofs.items[reservation_index] = self.draft.expr_impossibility_proofs.items[source_index];
    }

    fn finishActiveConstBinding(self: *BodyContext, active_id: ActiveConstBindingId, source: DraftExprId) Allocator.Error!DraftExprId {
        const index = @intFromEnum(active_id);
        if (self.draft.active_const_bindings.items[index].restored_source != null) {
            Common.invariant("active const binding was finished more than once");
        }
        const reservation = self.draft.active_const_bindings.items[index].reservation;
        self.draft.active_const_bindings.items[index].restored_source = source;
        self.copyActiveConstReservation(reservation, source);
        try self.materializeActiveConstBinding(active_id);
        return reservation;
    }

    fn materializeActiveConstBinding(self: *BodyContext, active_id: ActiveConstBindingId) Allocator.Error!void {
        const index = @intFromEnum(active_id);
        const active = self.draft.active_const_bindings.items[index];
        if (!active.used or active.wrapped) return;
        const source = active.restored_source orelse return;

        const owner_scope = try self.draft.enterOwner(active.owner);
        defer owner_scope.leave();
        const saved_loc = self.builder.program.current_loc;
        defer self.builder.program.current_loc = saved_loc;
        const saved_region = self.builder.program.current_region;
        defer self.builder.program.current_region = saved_region;
        self.builder.program.current_loc = self.draft.expr_locs.items[@intFromEnum(source)];
        self.builder.program.current_region = self.draft.expr_regions.items[@intFromEnum(source)];

        const wrapped = try self.wrapRecursiveConstLocalAtTypeCell(active.local, active.cell, source);
        self.copyActiveConstReservation(active.reservation, wrapped);
        self.draft.expr_locs.items[@intFromEnum(active.reservation)] = self.draft.expr_locs.items[@intFromEnum(source)];
        self.draft.expr_regions.items[@intFromEnum(active.reservation)] = self.draft.expr_regions.items[@intFromEnum(source)];
        self.draft.expr_impossibility_proofs.items[@intFromEnum(active.reservation)] = self.draft.expr_impossibility_proofs.items[@intFromEnum(source)];
        self.draft.active_const_bindings.items[index].wrapped = true;
    }

    fn leaveActiveConstBinding(self: *BodyContext, scope: *const ActiveConstBindingScope) void {
        if (!scope.entered) return;
        if (scope.bound_in_current_view) {
            if (scope.previous_local) |previous| {
                self.binders.put(scope.binder, previous) catch |err| switch (err) {
                    error.OutOfMemory => Common.invariant("restoring a previously inserted const binder cannot reallocate"),
                };
            } else {
                _ = self.binders.remove(scope.binder);
            }
        }
        self.active_const_binding = scope.previous_active;
    }

    fn currentLocalForResolvedValue(self: *BodyContext, ref_id: checked.ResolvedValueId) Allocator.Error!?DraftLocalId {
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| return binding.local;
        return try self.currentConstLocalForResolvedValue(ref_id);
    }

    fn currentTypedLocalBindingForResolvedValue(
        self: *BodyContext,
        ref_id: checked.ResolvedValueId,
        ty: Type.TypeId,
    ) ?CurrentLocal {
        const raw = @intFromEnum(ref_id);
        if (raw >= self.view.resolved_refs.records.len) {
            Common.invariant("checked lookup resolved value id was outside resolved value table");
        }
        const record = self.view.resolved_refs.records[raw];
        const binder = switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| local.binder,
            .selected_hoisted_const => |selected| selected.local.binder,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => return null,
        };
        return if (self.typed_binders.get(self.typedBinder(binder, ty))) |local|
            .{ .binder = binder, .local = local }
        else
            null;
    }

    fn currentLocalBindingAtType(
        self: *BodyContext,
        ref_id: checked.ResolvedValueId,
        ty: Type.TypeId,
    ) Allocator.Error!?CurrentLocal {
        const current = self.currentLocalBindingForResolvedValue(ref_id);
        if (current) |binding| {
            // `binders` is the lexical/SSA timeline, while `typed_binders`
            // holds alternative Monotype materializations of a checked binder
            // restored across a compile-time boundary. A same-typed mutable
            // version must shadow that older restored materialization.
            const matches = switch (self.localTypeCell(binding.local)) {
                .sealed => |local_ty| self.sameType(local_ty, ty),
                .graph_node => |local_node| self.graph.sameClass(
                    local_node,
                    try self.activeNodeFromType(ty),
                ),
            };
            if (matches) return binding;
        }
        return self.currentTypedLocalBindingForResolvedValue(ref_id, ty) orelse current;
    }

    fn lowerLocalBindingAtNode(
        self: *BodyContext,
        binding: CurrentLocal,
        checked_ty: checked.CheckedTypeId,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const local_cell = self.localTypeCell(binding.local);
        const local_node = try local_cell.toGraphNode(self.graph);
        try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binding.binder), local_cell);
        try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
        try relateRequestComponent(self.graph, local_node, expected_node);
        return try self.addExprWithTypeCell(local_cell, .{ .local = binding.local });
    }

    fn lowerLookupExprAtType(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        switch (record.ref) {
            .platform_required_checked_error => return try self.runtimeCrashExpr(ty, "platform requirement failed checking"),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => {},
        }
        switch (record.ref) {
            .local_value,
            .pattern_binder,
            => {},
            .selected_hoisted_const => |selected| {
                if (try self.restoreSelectedHoistedConstAtType(selected, ty)) |restored| return restored;
            },
            .local_param,
            .local_mutable_version,
            .local_proc,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
        if (try self.currentLocalBindingAtType(ref_id, ty)) |binding| {
            const local_id = binding.local;
            const binder_ty = checkedBinderType(self.view, binding.binder);
            const local_cell = self.localTypeCell(local_id);
            if (local_cell == .graph_node) {
                return try self.lowerLocalBindingAtNode(
                    binding,
                    checked_ty,
                    try self.activeNodeFromType(ty),
                );
            }
            const local_ty = try self.activeTypeFromCell(local_cell);
            if (self.checkedTypeIsClosed(binder_ty) and
                self.checkedTypeIsClosed(checked_ty) and
                self.sameType(local_ty, ty))
            {
                const checked_binder_ty = try self.builder.lowerType(self.view, binder_ty);
                const checked_use_ty = try self.builder.lowerType(self.view, checked_ty);
                if (!self.sameType(checked_binder_ty, local_ty) or
                    !self.sameType(checked_use_ty, ty))
                {
                    Common.invariant("closed checked local lookup differed from its sealed binding type");
                }
                return try self.addExprWithTypeCell(.{ .sealed = local_ty }, .{ .local = local_id });
            }
            // The local's Monotype identifies the binder's node in the
            // context that bound it; importing it unifies this context's
            // instantiation with that node before the use type is unified.
            try self.relateCheckedTypeToMono(binder_ty, local_ty);
            try self.relateCheckedTypeToMono(binder_ty, ty);
            try self.relateCheckedTypeToMono(checked_ty, ty);
            const live_ty = try self.lowerTypeView(binder_ty);
            const use_ty = if (self.sameType(ty, local_ty))
                local_ty
            else if (self.sameType(ty, live_ty))
                live_ty
            else
                Common.invariant("checked local lookup type differed from its expected Monotype use type");
            if (use_ty != local_ty) try self.setLocalType(local_id, use_ty);
            return try self.addExpr(.{ .ty = use_ty, .data = .{ .local = local_id } });
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const local_cell = self.localTypeCell(local_id);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
            try relateRequestComponent(self.graph, local_node, try self.activeNodeFromType(ty));
            return try self.addExprWithTypeCell(local_cell, .{ .local = local_id });
        }

        switch (record.ref) {
            .top_level_const => |const_use| return try self.restoreConstUseAtType(
                const_use,
                ty,
                try self.evidenceForUseSite(record.expr),
            ),
            .imported_const => |const_use| return try self.restoreConstUseAtType(
                const_use,
                ty,
                try self.evidenceForUseSite(record.expr),
            ),
            .platform_required_const => |required| return try self.restoreConstUseAtType(
                required.const_use,
                ty,
                try self.evidenceForUseSite(record.expr),
            ),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }

        switch (record.ref) {
            // The nested specialization applies its checked scope relations
            // before joining this contextual graph node.
            .local_proc => {},
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => try self.constrainTypeToMono(checked_ty, ty),
        }
        return switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            => Common.invariant("local lookup reached Monotype without a current local binding"),
            .local_proc => |local| blk: {
                const request_fn_node = try self.activeNodeFromType(ty);
                const context_id = try self.localProcContextId(self.view, local.binder, local.expr);
                const fn_id = try self.lowerDraftLocalProcAtNode(
                    local,
                    self.view,
                    context_id,
                    checked_ty,
                    self.view.types.rootKey(checked_ty),
                    request_fn_node,
                    try self.evidenceForUseSite(record.expr),
                );
                const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, request_fn_node);
                break :blk try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(fn_node),
                    .{ .fn_def = .{ .fn_id = fn_id, .captures = try self.localProcFnDefCaptureSpan(
                        context_id,
                        self.view.key.bytes,
                        local.binder,
                        local.expr,
                        null,
                    ) } },
                );
            },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| try self.lowerProcedureUseValueAtNode(proc, try self.activeNodeFromType(ty), try self.evidenceForUseSite(record.expr), null),
            .platform_required_proc => |proc| try self.lowerProcedureUseValueAtNode(proc.procedure, try self.activeNodeFromType(ty), try self.evidenceForUseSite(record.expr), proc.root_evidence),
            .top_level_const,
            .imported_const,
            .platform_required_const,
            => unreachable,
            .platform_required_declaration => Common.invariant("platform required declaration reached Monotype without a binding"),
            .platform_required_checked_error => return try self.runtimeCrashExpr(ty, "platform requirement failed checking"),
        };
    }

    fn checkedTypeIsClosed(self: *const BodyContext, ty: checked.CheckedTypeId) bool {
        const raw = @intFromEnum(ty);
        if (raw >= self.view.types.roots.len) {
            Common.invariant("checked type closure query referenced a missing root");
        }
        return !self.view.types.roots[raw].contains_identity_variables;
    }

    fn lowerLookupExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            return try self.lowerLocalBindingAtNode(
                binding,
                self.view.bodies.expr(checked_expr).ty,
                expected_node,
            );
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const checked_ty = self.view.bodies.expr(checked_expr).ty;
            const local_cell = self.localTypeCell(local_id);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(checked_ty, local_cell);
            try relateRequestComponent(self.graph, local_node, expected_node);
            return try self.addExprWithTypeCell(
                local_cell,
                .{ .local = local_id },
            );
        }
        switch (record.ref) {
            .selected_hoisted_const => |selected| {
                const entry = self.selectedHoistedConstEntry(selected);
                if (!self.loweringOwnHoistedConstRoot(entry)) {
                    return try self.deferConstUseAtNode(
                        self.view.bodies.expr(checked_expr).ty,
                        selected.const_use,
                        expected_node,
                        try self.evidenceForUseSite(record.expr),
                        .{ .hoisted = entry },
                    );
                }
            },
            .top_level_const => |const_use| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    const_use,
                    expected_node,
                    try self.evidenceForUseSite(record.expr),
                    .declared,
                );
            },
            .imported_const => |const_use| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    const_use,
                    expected_node,
                    try self.evidenceForUseSite(record.expr),
                    .declared,
                );
            },
            .platform_required_const => |required| {
                return try self.deferConstUseAtNode(
                    self.view.bodies.expr(checked_expr).ty,
                    required.const_use,
                    expected_node,
                    try self.evidenceForUseSite(record.expr),
                    .declared,
                );
            },
            .local_proc => |local| {
                const checked_ty = self.view.bodies.expr(checked_expr).ty;
                const context_id = try self.localProcContextId(self.view, local.binder, local.expr);
                const fn_id = try self.lowerDraftLocalProcAtNode(
                    local,
                    self.view,
                    context_id,
                    checked_ty,
                    self.view.types.rootKey(checked_ty),
                    expected_node,
                    try self.evidenceForUseSite(record.expr),
                );
                const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, expected_node);
                return try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(fn_node),
                    .{ .fn_def = .{
                        .fn_id = fn_id,
                        .captures = try self.localProcFnDefCaptureSpan(
                            context_id,
                            self.view.key.bytes,
                            local.binder,
                            local.expr,
                            null,
                        ),
                    } },
                );
            },
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |proc| return try self.lowerProcedureUseValueAtNode(
                proc,
                expected_node,
                try self.evidenceForUseSite(record.expr),
                null,
            ),
            .platform_required_proc => |proc| return try self.lowerProcedureUseValueAtNode(
                proc.procedure,
                expected_node,
                try self.evidenceForUseSite(record.expr),
                proc.root_evidence,
            ),
            // The required def failed checking, so its type never resolves;
            // crash at the use site instead of materializing the expected node.
            .platform_required_checked_error => return try self.runtimeCrashExprAtCell(
                DraftTypeCell.fromGraphNode(expected_node),
                "platform requirement failed checking",
            ),
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .platform_required_declaration => {},
        }
        const ty = try self.activeTypeFromNode(expected_node);
        return try self.lowerLookupExprAtType(self.view.bodies.expr(checked_expr).ty, maybe_ref, ty);
    }

    fn deferConstUseAtNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        const_use: checked.ConstUseTemplate,
        expected_node: NodeId,
        use_evidence: []const SpecEvidence,
        provenance: DraftConstUseProvenance,
    ) Allocator.Error!DraftExprId {
        switch (provenance) {
            .declared => switch (const_use.const_ref.owner) {
                .top_level_binding => {},
                .hoisted_expr => Common.invariant("hoisted const use reached a declared deferred boundary"),
            },
            .hoisted => |entry| {
                switch (const_use.const_ref.owner) {
                    .hoisted_expr => {},
                    .top_level_binding => Common.invariant("declared const use reached a hoisted deferred boundary"),
                }
                if (!std.meta.eql(entry.const_ref, const_use.const_ref)) {
                    Common.invariant("deferred hoisted const provenance referenced a different const template");
                }
            },
        }
        const requested_node = try self.constUseTypeNode(checked_ty, const_use);
        try relateRequestComponent(self.graph, expected_node, requested_node);
        const expr = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(requested_node),
            .pending_deferred,
        );
        const proof_reservation = try self.addImpossibilityProof(.pending);
        self.draft.expr_impossibility_proofs.items[@intFromEnum(expr)] = proof_reservation;
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_const_uses.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .request_node = expected_node,
            .witness_node = requested_node,
            .const_use = const_use,
            .provenance = provenance,
            .context_evidence = self.evidence,
            .use_evidence = use_evidence,
            .current_fn_key = self.current_fn_key,
            .active_const_binding = self.active_const_binding,
            .lexical = lexical,
            .proof_reservation = proof_reservation,
        });
        return expr;
    }

    fn lowerProcedureUseValueAtNode(
        self: *BodyContext,
        proc: checked.ProcedureUseTemplate,
        request_fn_node: NodeId,
        evidence: []const SpecEvidence,
        root_evidence: ?checked.CheckedEvidenceSpan,
    ) Allocator.Error!DraftExprId {
        if (self.builder.callableEvalForProcedureUse(proc)) |callable_eval| {
            return try self.lowerCallableEvalBindingValueAtNode(
                callable_eval.view,
                callable_eval.template,
                request_fn_node,
                evidence,
            );
        }
        const source_fn_ty = proc.source_fn_ty_payload orelse
            Common.invariant("checked procedure value reached Monotype without a requested function type");
        const slot = try self.draftFnSlotForProcedureUseAtNode(
            proc,
            source_fn_ty,
            proc.source_fn_ty_template,
            request_fn_node,
            evidence,
            root_evidence,
        );
        const fn_id = try self.requireLocalDraftSlot(slot);
        const fn_node = try self.draftFnSlotTypeNode(slot, request_fn_node);
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_node),
            .{ .fn_def = .{ .fn_id = fn_id } },
        );
    }

    fn requireLocalDraftSlot(self: *BodyContext, slot: DraftFnSlot) Allocator.Error!DraftFnTarget {
        return switch (slot) {
            .local => |local| blk: {
                switch (local) {
                    .draft => |draft_fn| {
                        for (self.draft.template_specs.items) |*spec| {
                            if (spec.fn_id == draft_fn) {
                                spec.requires_local = true;
                                break;
                            }
                        } else Common.invariant("draft procedure value had no owning template specialization");
                    },
                    .final => {},
                }
                break :blk local;
            },
            .imported => Common.invariant("active procedure value resolved directly to an imported function without a local value definition"),
        };
    }

    fn draftFnSlotTypeNode(
        self: *BodyContext,
        slot: DraftFnSlot,
        imported_fallback: NodeId,
    ) Allocator.Error!NodeId {
        return switch (slot) {
            .local => |local| switch (local) {
                .draft => |draft_fn| try self.draft.fns.items[@intFromEnum(draft_fn)].source.mono_fn_ty.toGraphNode(self.graph),
                .final => |final_fn| try self.activeNodeFromType(self.builder.program.fnSource(final_fn).mono_fn_ty),
            },
            // Imported slots were selected from this exact request. Their
            // durable signature belongs to another shard, while the active
            // graph request is already the local representation witness.
            .imported => imported_fallback,
        };
    }

    fn constUseMonoType(self: *BodyContext, const_use: checked.ConstUseTemplate) Allocator.Error!Type.TypeId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| try self.storedConstRootMonoType(store_view, stored, requested_ty),
            .eval_template => try self.lowerTypeView(requested_ty),
            .reserved => Common.invariant("reserved checked const template reached Monotype type selection"),
        };
    }

    fn constUseTypeNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        const_use: checked.ConstUseTemplate,
    ) Allocator.Error!NodeId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        const requested_node = switch (template.state) {
            .stored_const => |stored| try self.storedConstRootTypeNode(store_view, stored, requested_ty),
            .eval_template => try self.instNode(requested_ty),
            .reserved => Common.invariant("reserved checked const template reached Monotype type selection"),
        };
        return try self.relateCheckedNodeToProducedValue(try self.instNode(checked_ty), requested_node);
    }

    fn restoreConstUseAtType(
        self: *BodyContext,
        const_use: checked.ConstUseTemplate,
        ty: Type.TypeId,
        use_evidence: []const SpecEvidence,
    ) Allocator.Error!DraftExprId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const previous_restore_evidence = self.restore_evidence;
        self.restore_evidence = rootEvidence(self.owner_template, use_evidence);
        defer self.restore_evidence = previous_restore_evidence;

        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_ty = try self.storedConstRootMonoType(store_view, stored, requested_ty);
                if (!self.sameType(ty, stored_ty)) {
                    Common.invariant("stored const representation differed from its expected Monotype type");
                }
                var active_const_scope: ActiveConstBindingScope = .{};
                const has_active_const_binding = try self.enterActiveConstBindingAtCell(
                    store_view,
                    const_use.const_ref,
                    try self.draftTypeCell(stored_ty),
                    &active_const_scope,
                );
                defer self.leaveActiveConstBinding(&active_const_scope);
                const restored = try self.restoredStaticDataCandidateNode(
                    store_view,
                    self.view,
                    stored.node,
                    stored_ty,
                    const_use.const_ref,
                    requested_ty,
                    .disallow,
                );
                if (has_active_const_binding) break :blk try self.finishActiveConstBinding(active_const_scope.active, restored);
                break :blk restored;
            },
            .reserved => Common.invariant("reserved checked const template reached Monotype"),
            .eval_template => |eval| blk: {
                try self.constrainTypeToMono(requested_ty, ty);
                break :blk try self.lowerConstEvalTemplateUse(store_view, eval, const_use.const_ref, ty, null, null);
            },
        };
    }

    /// Restore a checked const directly into the active specialization graph.
    /// This phase may add relations and deferred work, so it must not
    /// materialize a durable Monotype snapshot of `request_node`.
    fn restoreConstUseAtNode(
        self: *BodyContext,
        const_use: checked.ConstUseTemplate,
        request_node: NodeId,
        use_evidence: []const SpecEvidence,
    ) Allocator.Error!DraftExprId {
        const requested_ty = const_use.requested_source_ty_payload orelse
            Common.invariant("checked const use reached Monotype without a requested checked type");
        const previous_restore_evidence = self.restore_evidence;
        self.restore_evidence = rootEvidence(self.owner_template, use_evidence);
        defer self.restore_evidence = previous_restore_evidence;

        const store_view = self.builder.moduleForId(checked.constModuleId(const_use.const_ref));
        const template = store_view.const_templates.get(const_use.const_ref);
        return switch (template.state) {
            .stored_const => |stored| blk: {
                const stored_node = try self.storedConstRootTypeNode(store_view, stored, requested_ty);
                const interface_node = try self.instNode(requested_ty);
                try relateRequestComponent(self.graph, request_node, stored_node);
                var active_const_scope: ActiveConstBindingScope = .{};
                const has_active_const_binding = try self.enterActiveConstBindingAtCell(
                    store_view,
                    const_use.const_ref,
                    DraftTypeCell.fromGraphNode(interface_node),
                    &active_const_scope,
                );
                defer self.leaveActiveConstBinding(&active_const_scope);
                const restored = try self.restoredStaticDataCandidateNodeAtNode(
                    store_view,
                    self.view,
                    stored.node,
                    stored_node,
                    const_use.const_ref,
                    requested_ty,
                    .disallow,
                );
                if (has_active_const_binding) break :blk try self.finishActiveConstBinding(active_const_scope.active, restored);
                break :blk restored;
            },
            .reserved => Common.invariant("reserved checked const template reached Monotype"),
            .eval_template => |eval| blk: {
                try self.graph.unify(try self.instNode(requested_ty), request_node);
                break :blk try self.lowerConstEvalTemplateUseAtNode(
                    store_view,
                    eval,
                    const_use.const_ref,
                    request_node,
                    null,
                    null,
                );
            },
        };
    }

    /// Return the exact producer-owned runtime representation stored beside a
    /// ConstStore value. The checked source type is related to that witness
    /// here, and consumers use that representation directly instead of the
    /// source type or an incidental empty row.
    fn storedConstRootMonoType(
        self: *BodyContext,
        store_view: ModuleView,
        stored: checked.StoredConstTemplate,
        requested_ty: checked.CheckedTypeId,
    ) Allocator.Error!Type.TypeId {
        const stored_ty = try self.lowerConstCaptureType(store_view, stored.root_type);
        _ = try self.relateCheckedNodeToProducedValue(try self.instNode(requested_ty), try self.graph.importMono(stored_ty));
        return stored_ty;
    }

    /// Return the active graph witness for a stored const root in the current
    /// request. Stored function values keep checked identity only, so graph
    /// restorations must not freeze their producer snapshot before the request
    /// has selected the callable signature that will re-lower the function.
    fn storedConstRootTypeNode(
        self: *BodyContext,
        store_view: ModuleView,
        stored: checked.StoredConstTemplate,
        requested_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        const stored_ty = try self.lowerConstCaptureType(store_view, stored.root_type);
        return try self.relateCheckedNodeToProducedValue(
            try self.instNode(requested_ty),
            try self.graph.importMono(stored_ty),
        );
    }

    /// Checked root-edge evidence for a compile-time root's
    /// template (site evidence keyed by the root's body expression),
    /// materialized. `template` bounds the expected param count.
    fn rootEdgeEvidenceByExpr(
        self: *BodyContext,
        view: ModuleView,
        root_expr: checked.CheckedExprId,
        template: checked.CheckedProcedureTemplate,
    ) Allocator.Error!?[]const SpecEvidence {
        return self.rootEdgeEvidenceByExprForPurpose(
            view,
            root_expr,
            template,
            .body_lowering,
        );
    }

    fn rootEdgeEvidenceByExprForPurpose(
        self: *BodyContext,
        view: ModuleView,
        root_expr: checked.CheckedExprId,
        template: checked.CheckedProcedureTemplate,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!?[]const SpecEvidence {
        const refs = view.static_dispatch_plans.siteEvidence(root_expr) orelse return null;
        if (refs.len != template.evidence_params.len) {
            Common.invariant("compile-time root evidence length differed from its procedure template");
        }
        return try self.materializeEvidenceForPurpose(refs, purpose);
    }

    fn rootEdgeEvidenceForPurpose(
        self: *BodyContext,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!?[]const SpecEvidence {
        const root_expr = switch (template.body) {
            .entry_wrapper => |wrapper_id| view.compile_time_roots.root(view.entry_wrappers.get(wrapper_id).root).expr,
            .checked_body => |body_id| view.bodies.body(body_id).root_expr,
            .intrinsic_wrapper => return null,
        };
        return try self.rootEdgeEvidenceByExprForPurpose(view, root_expr, template, purpose);
    }

    fn lowerConstEvalTemplateUse(
        self: *BodyContext,
        store_view: ModuleView,
        eval: checked.ConstEvalTemplate,
        const_use: checked.ConstLocator,
        ty: Type.TypeId,
        source_region_override: ?base.Region,
        current_entry_root: ?EntryRoot,
    ) Allocator.Error!DraftExprId {
        return try self.lowerConstEvalTemplateUseAtNode(
            store_view,
            eval,
            const_use,
            try self.activeNodeFromType(ty),
            source_region_override,
            current_entry_root,
        );
    }

    fn lowerConstEvalTemplateUseAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        eval: checked.ConstEvalTemplate,
        const_use: checked.ConstLocator,
        request_node: NodeId,
        source_region_override: ?base.Region,
        current_entry_root: ?EntryRoot,
    ) Allocator.Error!DraftExprId {
        const body = store_view.checked_const_bodies.get(eval.body);
        const entry_template = store_view.templates.get(eval.entry_template.template);

        var body_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            store_view,
            self.method_scope,
            eval.entry_template,
            self.graph,
            self.draft,
        );
        try body_ctx.inheritActiveConstBinding(self);
        body_ctx.evidence = rootEvidence(eval.entry_template, self.restore_evidence.vector);
        if (self.restore_evidence.vector.len < entry_template.evidence_params.len) {
            const eval_root = store_view.compile_time_roots.root(body.root);
            if (try self.rootEdgeEvidenceByExpr(store_view, eval_root.expr, entry_template)) |root_evidence| {
                body_ctx.evidence = rootEvidence(eval.entry_template, root_evidence);
            } else {
                Common.invariant("compile-time evaluation template did not contain its checked root evidence");
            }
        }
        defer body_ctx.deinit();
        body_ctx.source_region_override = source_region_override;
        body_ctx.current_entry_root = current_entry_root orelse .{
            .module = store_view.key,
            .root = body.root,
        };

        var active_const_scope: ActiveConstBindingScope = .{};
        const has_active_const_binding = try body_ctx.enterActiveConstBindingAtCell(
            store_view,
            const_use,
            DraftTypeCell.fromGraphNode(request_node),
            &active_const_scope,
        );
        defer body_ctx.leaveActiveConstBinding(&active_const_scope);

        // A checked source key is stable while the request remains a live
        // graph node. Nested specializations additionally key their concrete
        // request through the draft graph, so no provisional TypeId digest is
        // needed here.
        const root_fn_key = store_view.types.rootKey(entry_template.checked_fn_root);
        body_ctx.owner_context_fn_key = root_fn_key;
        body_ctx.current_fn_key = root_fn_key;

        const wrapper_fn_node = try body_ctx.graphFunctionNode(&.{}, request_node);
        try self.graph.unify(
            try body_ctx.instNode(entry_template.checked_fn_root),
            wrapper_fn_node,
        );
        try self.graph.unify(try body_ctx.instNode(body.checked_type), request_node);

        const restored = try body_ctx.lowerComptimeRootExprAtCell(
            body.body_expr,
            DraftTypeCell.fromGraphNode(request_node),
        );
        if (has_active_const_binding) return try body_ctx.finishActiveConstBinding(active_const_scope.active, restored);
        return restored;
    }

    fn restoreConstNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstNodeAtType(store_view, type_view, node, try self.builder.lowerType(type_view, checked_ty));
    }

    fn restoreConstNodeAtType(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, null);
    }

    fn restoreConstNodeAtTypeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const value = store_view.const_store.get(node);
        const representation: ActiveConstNodeRepresentation = .{ .sealed = ty };
        const cell = DraftTypeCell.fromSealed(ty);
        if (try self.materializedConstNodeExpr(store_view, node, representation, cell, static_data_const_locator)) |existing| return existing;

        switch (value) {
            .fn_value => {},
            .tag, .record, .tuple => if (self.builder.nominalConstructionLayer(ty)) |layer| {
                const backing_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, layer.backing, static_data_const_locator);
                const materialized = try self.addExpr(.{ .ty = layer.named, .data = .{ .nominal = backing_expr } });
                try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
                return materialized;
            },
            .nominal => |nominal| if (self.builder.nominalConstructionLayer(ty)) |layer| {
                const backing_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, nominal.backing, layer.backing, static_data_const_locator);
                const materialized = try self.addExpr(.{ .ty = layer.named, .data = .{ .nominal = backing_expr } });
                try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
                return materialized;
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash => {},
        }

        if (try self.activeConstNodeBindingExpr(store_view, node, representation, cell)) |active| return active;

        try self.reserveConstNodeBinding(store_view, node, representation, cell);
        const lowered = switch (value) {
            .fn_value => |fn_id| try self.restoreConstFn(store_view, fn_id, ty, static_data_const_locator),
            .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .crash, .tag, .nominal => try self.addExpr(.{
                .ty = ty,
                .data = try self.restoreConstData(store_view, type_view, value, ty, static_data_const_locator),
            }),
        };
        const materialized = try self.finishConstNodeBinding(store_view, node, representation, cell, lowered);
        try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
        return materialized;
    }

    fn restoredStaticDataCandidateNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        ty: Type.TypeId,
        const_locator: checked.ConstLocator,
        checked_type: checked.CheckedTypeId,
        bare_fn: Builder.BareFnCandidate,
    ) Allocator.Error!DraftExprId {
        if (!moduleBytesEqual(checked.constModuleId(const_locator).bytes, store_view.key.bytes)) {
            Common.invariant("static-data const context referenced a different ConstStore module");
        }
        if (self.builder.static_data_literals and
            try self.builder.constNodeHasStableStaticDataRepresentation(store_view, node) and
            self.builder.constNodeMayUseStaticDataCandidate(store_view, node, bare_fn))
        {
            const id = try self.builder.staticDataValue(const_locator, node, checked_type, DraftTypeCell.fromSealed(ty));
            const address: StaticDataCandidateAddress = .{
                .static_data = id,
                .owner = self.draft.current_owner,
            };
            if (self.draft.static_data_candidate_exprs.get(address)) |existing| return existing;

            const runtime_expr = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, const_locator);
            const candidate_expr = try self.addExpr(.{ .ty = ty, .data = .{ .static_data_candidate = .{
                .static_data = id,
                .runtime_expr = runtime_expr,
            } } });
            try self.draft.static_data_candidate_exprs.put(address, candidate_expr);
            return candidate_expr;
        }
        return try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, node, ty, const_locator);
    }

    fn restoredStaticDataCandidateNodeAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
        const_locator: checked.ConstLocator,
        checked_type: checked.CheckedTypeId,
        bare_fn: Builder.BareFnCandidate,
    ) Allocator.Error!DraftExprId {
        if (!moduleBytesEqual(checked.constModuleId(const_locator).bytes, store_view.key.bytes)) {
            Common.invariant("static-data const context referenced a different ConstStore module");
        }
        const runtime_expr = try self.restoreConstNodeAtNodeWithStaticRoot(
            store_view,
            type_view,
            node,
            request_node,
            const_locator,
        );
        if (self.builder.static_data_literals and
            try self.builder.constNodeHasStableStaticDataRepresentation(store_view, node) and
            self.builder.constNodeMayUseStaticDataCandidate(store_view, node, bare_fn))
        {
            const id = try self.builder.staticDataValue(
                const_locator,
                node,
                checked_type,
                DraftTypeCell.fromGraphNode(request_node),
            );
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(request_node), .{ .static_data_candidate = .{
                .static_data = id,
                .runtime_expr = runtime_expr,
            } });
        }
        return runtime_expr;
    }

    fn restoreConstNodeAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstNodeAtNodeWithStaticRoot(
            store_view,
            type_view,
            node,
            request_node,
            null,
        );
    }

    fn restoreConstNodeAtNodeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        node: checked.ConstNodeId,
        request_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const value = store_view.const_store.get(node);
        const representation: ActiveConstNodeRepresentation = .{ .graph = request_node };
        const cell = DraftTypeCell.fromGraphNode(request_node);
        if (try self.materializedConstNodeExpr(store_view, node, representation, cell, static_data_const_locator)) |existing| return existing;
        if (try self.activeConstNodeBindingExpr(store_view, node, representation, cell)) |active| return active;

        try self.reserveConstNodeBinding(store_view, node, representation, cell);
        const lowered = switch (value) {
            .fn_value => |fn_id| try self.restoreConstFnAtNodeWithStaticRoot(
                store_view,
                fn_id,
                request_node,
                static_data_const_locator,
            ),
            .tag, .record, .tuple => try self.addConstructorExprAtNode(
                request_node,
                try self.restoreConstDataAtNode(
                    store_view,
                    type_view,
                    value,
                    request_node,
                    static_data_const_locator,
                ),
            ),
            .nominal => |nominal| blk: {
                const representation_node = self.constructorRepresentationNode(request_node);
                if (self.graph.content(representation_node) != .named) {
                    Common.invariant("ConstStore nominal restored without a nominal graph representation");
                }
                const named = self.graph.namedNodes(representation_node);
                const backing = named.backing orelse
                    Common.invariant("ConstStore nominal restored with a named graph node that had no backing");
                const backing_expr = try self.restoreConstNodeAtNodeWithStaticRoot(
                    store_view,
                    type_view,
                    nominal.backing,
                    backing.node,
                    static_data_const_locator,
                );
                break :blk try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(representation_node),
                    .{ .nominal = backing_expr },
                );
            },
            .pending, .zst, .scalar, .str, .list, .box, .crash => try self.addExprWithTypeCell(
                DraftTypeCell.fromGraphNode(request_node),
                try self.restoreConstDataAtNode(
                    store_view,
                    type_view,
                    value,
                    request_node,
                    static_data_const_locator,
                ),
            ),
        };
        const materialized = try self.finishConstNodeBinding(store_view, node, representation, cell, lowered);
        try self.cacheMaterializedConstNode(store_view, node, representation, materialized, static_data_const_locator);
        return materialized;
    }

    fn restoreConstDataAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        value: checked.ConstValue,
        request_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!BodyExprData {
        return switch (value) {
            .pending => Common.invariant("pending ConstStore node reached Monotype restore"),
            .zst => .unit,
            .scalar => |scalar| restoreScalarBody(scalar),
            .str => |str| .{ .str_lit = try self.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .crash => |str| .{ .crash = try self.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .list => |list| try self.restoreConstListDataAtNode(
                store_view,
                type_view,
                request_node,
                list,
                static_data_const_locator,
            ),
            .box => |payload| blk: {
                const child = try self.restoreConstNodeAtNodeWithStaticRoot(
                    store_view,
                    type_view,
                    payload,
                    try self.graph.boxElementNode(request_node),
                    static_data_const_locator,
                );
                break :blk .{ .low_level = .{
                    .op = .box_box,
                    .args = try self.addExprSpan(&.{child}),
                } };
            },
            .tuple => |items| .{ .tuple = try self.restoreConstTupleAtNode(
                store_view,
                type_view,
                request_node,
                items,
                static_data_const_locator,
            ) },
            .record => |items| .{ .record = try self.restoreConstRecordAtNode(
                store_view,
                type_view,
                request_node,
                items,
                static_data_const_locator,
            ) },
            .tag => |tag| .{ .tag = .{
                .name = try self.builder.program.names.internTagLabel(tag.tag_name),
                .payloads = try self.restoreConstTagPayloadsAtNode(
                    store_view,
                    type_view,
                    request_node,
                    tag,
                    static_data_const_locator,
                ),
            } },
            .nominal => Common.invariant("ConstStore nominal must be restored as an expression"),
            .fn_value => Common.invariant("ConstStore function value must be restored as an expression"),
        };
    }

    fn restoreConstListAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        request_node: NodeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const element_node = try self.graph.listElementNode(request_node);
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            lowered[index] = try self.restoreConstNodeAtNodeWithStaticRoot(
                store_view,
                type_view,
                item,
                element_node,
                static_data_const_locator,
            );
        }
        return try self.addExprSpan(lowered);
    }

    fn restoreConstListDataAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        request_node: NodeId,
        list: checked.ConstList,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!BodyExprData {
        return switch (list) {
            .nodes => |items| .{ .list = try self.restoreConstListAtNode(
                store_view,
                type_view,
                request_node,
                items,
                static_data_const_locator,
            ) },
            .scalar_bytes => |scalar_bytes| .{ .bytes_lit = .{
                .literal = try self.addStringView(
                    store_view.const_store.blobData(scalar_bytes.bytes.data),
                    scalar_bytes.bytes.offset,
                    scalar_bytes.bytes.len,
                ),
                .len = scalar_bytes.len,
                .element = scalar_bytes.element,
            } },
        };
    }

    fn restoreConstTupleAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        request_node: NodeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const item_nodes = try self.graph.tupleItemNodes(request_node);
        if (item_nodes.len != items.len) Common.invariant("ConstStore tuple length differs from checked graph type");
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, item_nodes, 0..) |item, item_node, index| {
            lowered[index] = try self.restoreConstNodeAtNodeWithStaticRoot(
                store_view,
                type_view,
                item,
                item_node,
                static_data_const_locator,
            );
        }
        return try self.addExprSpan(lowered);
    }

    fn restoreConstRecordAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        request_node: NodeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftFieldExpr) {
        // ConstStore record children follow the lexicographic Monotype field
        // order used to build the LIR const plan, not the checked constructor's
        // original row-fragment order. Read the flattened backing row so every
        // stored child is paired with its exact graph field cell.
        const record_node = switch (self.graph.content(request_node)) {
            .named => |named| (named.backing orelse
                Common.invariant("ConstStore record restored through a named graph node without a backing")).node,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => request_node,
        };
        const graph_fields = (try self.graph.recordNodes(record_node)).fields;
        if (graph_fields.len != items.len) Common.invariant("ConstStore record length differs from checked graph type");
        const fields = try self.allocator.dupe(InstField, graph_fields);
        defer self.allocator.free(fields);
        std.mem.sort(
            InstField,
            fields,
            &self.builder.program.names,
            instRecordFieldLessThan,
        );
        const lowered = try self.allocator.alloc(DraftFieldExpr, items.len);
        defer self.allocator.free(lowered);
        for (items, fields, 0..) |item, field, index| {
            lowered[index] = .{
                .name = field.name,
                .value = try self.restoreConstNodeAtNodeWithStaticRoot(
                    store_view,
                    type_view,
                    item,
                    field.ty,
                    static_data_const_locator,
                ),
            };
        }
        return try self.addFieldExprSpan(lowered);
    }

    fn restoreConstTagPayloadsAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        request_node: NodeId,
        tag: anytype,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const mono_tag_name = try self.builder.program.names.internTagLabel(tag.tag_name);
        const lowered = try self.allocator.alloc(DraftExprId, tag.payloads.len);
        defer self.allocator.free(lowered);
        for (tag.payloads, 0..) |payload, index| {
            lowered[index] = try self.restoreConstNodeAtNodeWithStaticRoot(
                store_view,
                type_view,
                payload,
                try self.graph.tagConstructionPayloadNode(request_node, mono_tag_name, index),
                static_data_const_locator,
            );
        }
        return try self.addExprSpan(lowered);
    }

    fn restoreConstData(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        value: checked.ConstValue,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!BodyExprData {
        return switch (value) {
            .pending => Common.invariant("pending ConstStore node reached Monotype restore"),
            .zst => .unit,
            .scalar => |scalar| restoreScalarBody(scalar),
            .str => |str| .{ .str_lit = try self.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .crash => |str| .{ .crash = try self.addStringView(
                store_view.const_store.blobData(str.data),
                str.offset,
                str.len,
            ) },
            .list => |list| try self.restoreConstListData(store_view, type_view, ty, list, static_data_const_locator),
            .box => |payload| blk: {
                const child = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, payload, self.constBoxPayloadType(ty), static_data_const_locator);
                break :blk .{ .low_level = .{
                    .op = .box_box,
                    .args = try self.addExprSpan(&.{child}),
                } };
            },
            .tuple => |items| .{ .tuple = try self.restoreConstTuple(store_view, type_view, ty, items, static_data_const_locator) },
            .record => |items| .{ .record = try self.restoreConstRecord(store_view, type_view, ty, items, static_data_const_locator) },
            .tag => |tag| .{ .tag = .{
                .name = try self.builder.program.names.internTagLabel(tag.tag_name),
                .payloads = try self.restoreConstTagPayloads(store_view, type_view, ty, tag, static_data_const_locator),
            } },
            .nominal => |nominal| .{ .nominal = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, nominal.backing, self.builder.namedBackingType(ty) orelse ty, static_data_const_locator) },
            .fn_value => Common.invariant("ConstStore function value must be restored as an expression"),
        };
    }

    fn restoreConstList(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const elem_ty = self.constListElemType(ty);
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, elem_ty, static_data_const_locator);
        }
        return try self.addExprSpan(lowered);
    }

    fn restoreConstListData(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        list: checked.ConstList,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!BodyExprData {
        return switch (list) {
            .nodes => |items| .{ .list = try self.restoreConstList(store_view, type_view, ty, items, static_data_const_locator) },
            .scalar_bytes => |scalar_bytes| .{ .bytes_lit = .{
                .literal = try self.addStringView(
                    store_view.const_store.blobData(scalar_bytes.bytes.data),
                    scalar_bytes.bytes.offset,
                    scalar_bytes.bytes.len,
                ),
                .len = scalar_bytes.len,
                .element = scalar_bytes.element,
            } },
        };
    }

    fn restoreConstTuple(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const item_span = self.builder.tupleItemSpan(ty);
        const item_count: usize = @intCast(item_span.len);
        if (item_count != items.len) Common.invariant("ConstStore tuple length differs from checked type");
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            const item_tys = self.builder.program.types.span(item_span);
            const item_ty = GuardedList.at(item_tys, index);
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, item_ty, static_data_const_locator);
        }
        return try self.addExprSpan(lowered);
    }

    fn restoreConstRecord(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        items: []const checked.ConstNodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftFieldExpr) {
        const field_span = self.builder.recordFieldsSpan(ty);
        const field_count: usize = @intCast(field_span.len);
        if (field_count != items.len) Common.invariant("ConstStore record length differs from checked type");
        const lowered = try self.allocator.alloc(DraftFieldExpr, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            const fields = self.builder.program.types.fieldSpan(field_span);
            const field = GuardedList.at(fields, index);
            lowered[index] = .{
                .name = field.name,
                .value = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, item, field.ty, static_data_const_locator),
            };
        }
        return try self.addFieldExprSpan(lowered);
    }

    fn restoreConstTagPayloads(
        self: *BodyContext,
        store_view: ModuleView,
        type_view: ModuleView,
        ty: Type.TypeId,
        tag: anytype,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        const mono_tag_name = try self.builder.program.names.internTagLabel(tag.tag_name);
        const payload_span = self.builder.tagPayloadSpan(ty, mono_tag_name);
        const payload_count: usize = @intCast(payload_span.len);
        if (payload_count != tag.payloads.len) Common.invariant("ConstStore tag payload count differs from checked type");
        const lowered = try self.allocator.alloc(DraftExprId, tag.payloads.len);
        defer self.allocator.free(lowered);
        for (tag.payloads, 0..) |payload, index| {
            const payload_tys = self.builder.program.types.span(payload_span);
            const payload_ty = GuardedList.at(payload_tys, index);
            lowered[index] = try self.restoreConstNodeAtTypeWithStaticRoot(store_view, type_view, payload, payload_ty, static_data_const_locator);
        }
        return try self.addExprSpan(lowered);
    }

    fn constListElemType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.builder.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("ConstStore list restored with a non-list monotype"),
        };
    }

    fn constBoxPayloadType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.builder.shapeContent(ty)) {
            .box => |payload| payload,
            .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => Common.invariant("ConstStore box restored with a non-box monotype"),
        };
    }

    fn lowerConstCaptureType(
        self: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
    ) Allocator.Error!Type.TypeId {
        var map = collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId).init(self.allocator);
        defer map.deinit();
        return try self.lowerConstCaptureTypeInner(store_view, ty, &map);
    }

    fn lowerConstCaptureTypeInner(
        self: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),
    ) Allocator.Error!Type.TypeId {
        if (map.get(ty)) |existing| return existing;
        const context = ConstTypeLowerContext{
            .body = self,
            .store_view = store_view,
            .ty = ty,
            .map = map,
        };
        return self.builder.program.types.addRecursive(context, ConstTypeLowerContext.fill) catch |err| {
            _ = map.remove(ty);
            return err;
        };
    }

    const ConstTypeLowerContext = struct {
        body: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),

        fn fill(self: ConstTypeLowerContext, reserved: Type.TypeId) Allocator.Error!Type.Content {
            try self.map.put(self.ty, reserved);
            return try self.body.lowerConstCaptureTypeContent(self.store_view, self.ty, self.map);
        }
    };

    fn lowerConstCaptureTypeContent(
        self: *BodyContext,
        store_view: ModuleView,
        ty: check.ConstStore.ConstTypeId,
        map: *collections.DenseMap(check.ConstStore.ConstTypeId, Type.TypeId),
    ) Allocator.Error!Type.Content {
        const type_store = &store_view.const_store.type_store;
        return switch (type_store.get(ty)) {
            .primitive => |primitive| .{ .primitive = monotypePrimitive(primitive) },
            .zst => .zst,
            .erased => |erased| .{ .erased = erased },
            .list => |elem| .{ .list = try self.lowerConstCaptureTypeInner(store_view, elem, map) },
            .box => |elem| .{ .box = try self.lowerConstCaptureTypeInner(store_view, elem, map) },
            .tuple => |items| blk: {
                const source = type_store.typeSpan(items);
                const out = try self.allocator.alloc(Type.TypeId, source.len);
                defer self.allocator.free(out);
                for (source, 0..) |item, index| {
                    out[index] = try self.lowerConstCaptureTypeInner(store_view, item, map);
                }
                break :blk .{ .tuple = try self.builder.program.types.addSpan(out) };
            },
            .func => |func| blk: {
                const source = type_store.typeSpan(func.args);
                const out = try self.allocator.alloc(Type.TypeId, source.len);
                defer self.allocator.free(out);
                for (source, 0..) |arg, index| {
                    out[index] = try self.lowerConstCaptureTypeInner(store_view, arg, map);
                }
                break :blk .{ .func = .{
                    .args = try self.builder.program.types.addSpan(out),
                    .ret = try self.lowerConstCaptureTypeInner(store_view, func.ret, map),
                } };
            },
            .record => |fields| blk: {
                const source = type_store.fieldSpan(fields);
                const out = try self.allocator.alloc(Type.Field, source.len);
                defer self.allocator.free(out);
                for (source, 0..) |field, index| {
                    out[index] = .{
                        .name = try self.constRecordFieldName(store_view, field.name),
                        .ty = try self.lowerConstCaptureTypeInner(store_view, field.ty, map),
                        .value_ty = if (field.value_ty) |value_ty|
                            try self.lowerConstCaptureTypeInner(store_view, value_ty, map)
                        else
                            null,
                        .default = try self.constFieldDefault(store_view, field.default),
                    };
                }
                break :blk .{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, out) };
            },
            .tag_union => |tags| blk: {
                const source = type_store.tagSpan(tags);
                const out = try self.allocator.alloc(Type.Tag, source.len);
                defer self.allocator.free(out);
                for (source, 0..) |tag, index| {
                    const payloads = type_store.typeSpan(tag.payloads);
                    const out_payloads = try self.allocator.alloc(Type.TypeId, payloads.len);
                    defer self.allocator.free(out_payloads);
                    for (payloads, 0..) |payload, payload_index| {
                        out_payloads[payload_index] = try self.lowerConstCaptureTypeInner(store_view, payload, map);
                    }
                    out[index] = .{
                        .name = try self.constTagName(store_view, tag.name),
                        .checked_name = try self.constTagName(store_view, tag.checked_name),
                        .payloads = try self.builder.program.types.addSpan(out_payloads),
                    };
                }
                break :blk .{ .tag_union = try self.builder.program.types.addTagVariants(&self.builder.program.names, out) };
            },
            .named => |named| blk: {
                const args = type_store.typeSpan(named.args);
                const out_args = try self.allocator.alloc(Type.TypeId, args.len);
                defer self.allocator.free(out_args);
                for (args, 0..) |arg, index| {
                    out_args[index] = try self.lowerConstCaptureTypeInner(store_view, arg, map);
                }

                const declared = type_store.declaredFieldSpan(named.declared_order);
                const out_declared = try self.allocator.alloc(Type.DeclaredField, declared.len);
                defer self.allocator.free(out_declared);
                for (declared, 0..) |entry, index| {
                    out_declared[index] = switch (entry) {
                        .named => |name| .{ .named = try self.constRecordFieldName(store_view, name) },
                        .padding => |padding| .{ .padding = try self.lowerConstCaptureTypeInner(store_view, padding, map) },
                    };
                }

                break :blk .{ .named = .{
                    .named_type = .{
                        .module = named.named_type.module,
                        .ty = named.named_type.ty,
                    },
                    .def = try self.constTypeDef(store_view, named.def),
                    .kind = monotypeNamedKind(named.kind),
                    .builtin_owner = named.builtin_owner,
                    .args = try self.builder.program.types.addSpan(out_args),
                    .backing = if (named.backing) |backing| .{
                        .ty = try self.lowerConstCaptureTypeInner(store_view, backing.ty, map),
                        .use = monotypeBackingUse(backing.use),
                        .authority = monotypeBackingAuthority(backing.authority),
                    } else null,
                    .declared_order = try self.builder.program.types.addDeclaredFields(out_declared),
                } };
            },
        };
    }

    fn constRecordFieldName(
        self: *BodyContext,
        store_view: ModuleView,
        name: names.RecordFieldNameId,
    ) Allocator.Error!names.RecordFieldNameId {
        return try self.builder.program.names.internRecordFieldLabel(store_view.names.recordFieldLabelText(name));
    }

    /// Re-intern a field default's declaring-module identity from the const
    /// store's name table into the program name store, like
    /// `constRecordFieldName` does for the label.
    fn constFieldDefault(
        self: *BodyContext,
        store_view: ModuleView,
        default: ?check.ConstStore.TypeFieldDefault,
    ) Allocator.Error!?Type.FieldDefault {
        const field_default = default orelse return null;
        return .{
            .module = try self.builder.program.names.internModuleIdentity(store_view.names.moduleIdentityBytes(field_default.module)),
            .expr_node = field_default.expr_node,
        };
    }

    fn constTagName(
        self: *BodyContext,
        store_view: ModuleView,
        name: names.TagNameId,
    ) Allocator.Error!names.TagNameId {
        return try self.builder.program.names.internTagLabel(store_view.names.tagLabelText(name));
    }

    fn constTypeDef(
        self: *BodyContext,
        store_view: ModuleView,
        def: check.ConstStore.TypeDef,
    ) Allocator.Error!Type.TypeDef {
        return .{
            .module = try self.builder.program.names.internModuleIdentity(store_view.names.moduleIdentityBytes(def.module)),
            .type_name = try self.builder.program.names.internTypeName(store_view.names.typeNameText(def.type_name)),
            .source_decl = def.source_decl,
            .generated = def.generated,
            .iterator_representation = @enumFromInt(@intFromEnum(def.iterator_representation)),
            .iterator_kind = @enumFromInt(@intFromEnum(def.iterator_kind)),
            .iterator_depth = def.iterator_depth,
            .iterator_topology = if (def.iterator_topology) |topology| .{
                .len_field = try self.constRecordFieldName(store_view, topology.len_field),
                .step_field = try self.constRecordFieldName(store_view, topology.step_field),
                .known_tag = try self.constTagName(store_view, topology.known_tag),
                .unknown_tag = try self.constTagName(store_view, topology.unknown_tag),
                .done_tag = try self.constTagName(store_view, topology.done_tag),
                .one_tag = try self.constTagName(store_view, topology.one_tag),
                .skip_tag = try self.constTagName(store_view, topology.skip_tag),
                .item_field = try self.constRecordFieldName(store_view, topology.item_field),
                .rest_field = try self.constRecordFieldName(store_view, topology.rest_field),
            } else null,
        };
    }

    fn constRecordFields(self: *BodyContext, ty: Type.TypeId) Type.StoreSpanBorrow(Type.Field, "fields") {
        return self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(ty));
    }

    fn restoreConstFnAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        return try self.restoreConstFnAtNodeWithStaticRoot(
            store_view,
            fn_id,
            request_fn_node,
            null,
        );
    }

    fn restoreConstFnAtNodeWithStaticRoot(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        request_fn_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const raw = @intFromEnum(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@enumFromInt(raw));
        switch (fn_value.fn_def) {
            .parser_runtime => return try self.restoreConstParserRuntimeFnAtNode(
                store_view,
                fn_id,
                fn_value,
                request_fn_node,
                static_data_const_locator,
            ),
            .encoder_for_runtime => return try self.restoreConstEncoderForRuntimeFnAtNode(
                store_view,
                fn_id,
                fn_value,
                request_fn_node,
                static_data_const_locator,
            ),
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated => {},
        }
        if (fn_value.evidence_frames.len == 0 or fn_value.evidence_frame_head == null) {
            Common.invariant("stored checked function did not contain an explicit evidence root frame");
        }
        const retained_evidence = try self.materializeConstFnEvidence(fn_value);
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        const checked_template = templateForConstFnDef(fn_value.fn_def);
        _ = fn_view.templates.get(checked_template.template);
        const fn_def = try self.builder.constFnDefToMono(fn_value.fn_def);
        if (fn_value.captures.len != 0) {
            return try self.restoreCapturingConstFnAtNode(
                store_view,
                fn_value,
                fn_def,
                request_fn_node,
                retained_evidence,
                static_data_const_locator,
            );
        }
        const restored_fn = try self.restoreConstFnTemplateAtNode(
            fn_value,
            fn_def,
            retained_evidence,
            request_fn_node,
        );
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{ .fn_id = restored_fn } },
        );
    }

    fn restoreConstFnTemplateAtNode(
        self: *BodyContext,
        fn_value: check.ConstStore.ConstFn,
        fn_def: Ast.FnDef,
        retained_evidence: EvidenceChain,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnTarget {
        return switch (fn_def) {
            .nested => |nested| {
                const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
                var fn_ctx = try BodyContext.initWithMethodScope(
                    self.allocator,
                    self.builder,
                    fn_view,
                    self.method_scope,
                    ownerTemplateForConstFnDef(fn_value.fn_def),
                    self.graph,
                    self.draft,
                );
                fn_ctx.evidence = retained_evidence;
                fn_ctx.inheritFrozenEmissionContext(self);
                defer fn_ctx.deinit();
                try fn_ctx.inheritActiveConstBinding(self);
                try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
                fn_ctx.current_fn_key = nested.context_fn_key;
                const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, nested.context_fn_key);
                defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
                return try self.builder.lowerDraftNestedFromContext(
                    &fn_ctx,
                    checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def),
                    nested,
                    fn_value.source_fn_ty,
                    fn_value.source_fn_key,
                    request_fn_node,
                    &.{},
                    fn_ctx.evidence,
                    null,
                    .exact_graph,
                );
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => try self.requireLocalDraftSlot(try self.builder.lowerDraftTemplateFromContext(
                self,
                templateForConstFnDef(fn_value.fn_def),
                fn_value.source_fn_ty,
                fn_value.source_fn_key,
                request_fn_node,
                retained_evidence.vector,
                .resolved,
                .independent_roots,
            )),
        };
    }

    fn restoreCapturingConstFnAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        fn_def: Ast.FnDef,
        request_fn_node: NodeId,
        retained_evidence: EvidenceChain,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        var fn_ctx = try BodyContext.initWithMethodScope(
            self.allocator,
            self.builder,
            fn_view,
            self.method_scope,
            ownerTemplateForConstFnDef(fn_value.fn_def),
            self.graph,
            self.draft,
        );
        fn_ctx.evidence = retained_evidence;
        fn_ctx.inheritFrozenEmissionContext(self);
        defer fn_ctx.deinit();
        try fn_ctx.inheritActiveConstBinding(self);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        _ = try checkedMonoRequestNode(
            self.graph,
            try fn_ctx.instNode(fn_value.source_fn_ty),
            request_fn_node,
        );

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);
        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            node: NodeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        var initialized: usize = 0;
        errdefer {
            while (initialized > 0) {
                initialized -= 1;
                fn_ctx.restoreTypedBinder(
                    captures[initialized].binder,
                    captures[initialized].ty,
                    captures[initialized].previous_typed,
                );
                if (captures[initialized].previous) |previous| {
                    fn_ctx.binders.put(captures[initialized].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    _ = fn_ctx.binders.remove(captures[initialized].binder);
                }
            }
            self.allocator.free(captures);
        }
        defer self.allocator.free(captures);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_node = try self.graph.importMono(lowered_ty);
            const capture_cell = DraftTypeCell.fromGraphNode(capture_node);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.builder.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .node = capture_node,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNodeAtNode(
                    store_view,
                    fn_view,
                    capture.value,
                    captures[index].node,
                    const_locator,
                    checkedBinderType(fn_view, constCaptureBinder(capture.id)),
                    .allow,
                )
            else
                try fn_ctx.restoreConstNodeAtNode(
                    store_view,
                    fn_view,
                    capture.value,
                    captures[index].node,
                );
        }

        const capture_nested = switch (fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(capture_nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);

        defer {
            var index = initialized;
            while (index > 0) {
                index -= 1;
                fn_ctx.restoreTypedBinder(captures[index].binder, captures[index].ty, captures[index].previous_typed);
                if (captures[index].previous) |previous| {
                    fn_ctx.binders.put(captures[index].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    _ = fn_ctx.binders.remove(captures[index].binder);
                }
            }
        }

        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node| node.* = capture.node;
        const restored_fn_id = switch (lambda_expr.data) {
            .lambda => try self.builder.lowerDraftNestedFromContext(
                &fn_ctx,
                lambda_expr_id,
                capture_nested,
                fn_value.source_fn_ty,
                fn_value.source_fn_key,
                request_fn_node,
                capture_entry_guards,
                fn_ctx.evidence,
                null,
                .exact_graph,
            ),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored capturing function did not reference a checked lambda"),
        };

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        defer self.allocator.free(capture_values);
        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .local = capture.local, .value = capture.value };
        }

        return try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn_id,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
    }

    fn restoreConstFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const raw = @intFromEnum(fn_id);
        if (raw >= store_view.const_store.fns.items.len) Common.invariant("ConstStore function id is out of range");
        const fn_value = store_view.const_store.getFn(@enumFromInt(raw));
        if (fn_value.fn_def == .parser_runtime) {
            return try self.restoreConstParserRuntimeFn(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        if (fn_value.fn_def == .encoder_for_runtime) {
            return try self.restoreConstEncoderForRuntimeFn(store_view, fn_id, fn_value, ty, static_data_const_locator);
        }
        const template = try self.builder.restoredConstFnTemplateToMono(store_view, fn_id, fn_value, ty);
        if (fn_value.evidence_frames.len == 0 or fn_value.evidence_frame_head == null) {
            Common.invariant("stored checked function did not contain an explicit evidence root frame");
        }
        const retained_evidence = try self.materializeConstFnEvidence(fn_value);
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        const checked_template = templateForConstFnDef(fn_value.fn_def);
        _ = fn_view.templates.get(checked_template.template);
        if (fn_value.captures.len != 0) {
            return try self.restoreCapturingConstFn(store_view, fn_value, template, ty, retained_evidence, static_data_const_locator);
        }
        const request_fn_node = try self.activeNodeFromType(ty);
        const restored_fn = try self.restoreConstFnTemplate(fn_value, template, retained_evidence, request_fn_node);
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{ .fn_id = restored_fn } },
        );
    }

    fn restoreConstFnTemplate(
        self: *BodyContext,
        fn_value: check.ConstStore.ConstFn,
        template: Ast.FnTemplate,
        retained_evidence: EvidenceChain,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnTarget {
        return switch (template.fn_def) {
            .nested => |nested| {
                const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
                var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, ownerTemplateForConstFnDef(fn_value.fn_def), self.graph, self.draft);
                fn_ctx.evidence = retained_evidence;
                fn_ctx.inheritFrozenEmissionContext(self);
                defer fn_ctx.deinit();
                try fn_ctx.inheritActiveConstBinding(self);
                try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
                fn_ctx.current_fn_key = nested.context_fn_key;
                const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(nested, nested.context_fn_key);
                defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);
                return try self.builder.lowerDraftNestedFromContext(
                    &fn_ctx,
                    checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def),
                    nested,
                    template.source_fn_ty,
                    template.source_fn_key,
                    request_fn_node,
                    &.{},
                    fn_ctx.evidence,
                    null,
                    .exact_graph,
                );
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => try self.requireLocalDraftSlot(try self.builder.lowerDraftTemplateFromContext(
                self,
                templateForConstFnDef(fn_value.fn_def),
                template.source_fn_ty,
                template.source_fn_key,
                request_fn_node,
                retained_evidence.vector,
                .resolved,
                .independent_roots,
            )),
        };
    }

    fn restoreCapturingConstFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_value: check.ConstStore.ConstFn,
        template: Ast.FnTemplate,
        ty: Type.TypeId,
        retained_evidence: EvidenceChain,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const fn_view = self.builder.moduleForConstFnDef(fn_value.fn_def);
        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, ownerTemplateForConstFnDef(fn_value.fn_def), self.graph, self.draft);
        fn_ctx.evidence = retained_evidence;
        fn_ctx.inheritFrozenEmissionContext(self);
        defer fn_ctx.deinit();
        try fn_ctx.inheritActiveConstBinding(self);
        try fn_ctx.replayStoredEvidenceRelations(fn_ctx.evidence);
        fn_ctx.current_fn_key = switch (template.fn_def) {
            .nested => |nested| nested.context_fn_key,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        try fn_ctx.constrainTypeToMono(fn_value.source_fn_ty, ty);

        const lambda_expr_id = checkedLambdaExprIdForConstFn(fn_view, fn_value.fn_def);
        const lambda_expr = fn_view.bodies.expr(lambda_expr_id);

        const captures = try self.allocator.alloc(struct {
            binder: checked.PatternBinderId,
            local: DraftLocalId,
            previous: ?DraftLocalId,
            previous_typed: ?DraftLocalId,
            ty: Type.TypeId,
            value: DraftExprId,
        }, fn_value.captures.len);
        var initialized: usize = 0;
        errdefer {
            while (initialized > 0) {
                initialized -= 1;
                if (captures[initialized].previous) |previous| {
                    fn_ctx.restoreTypedBinder(captures[initialized].binder, captures[initialized].ty, captures[initialized].previous_typed);
                    fn_ctx.binders.put(captures[initialized].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    fn_ctx.restoreTypedBinder(captures[initialized].binder, captures[initialized].ty, captures[initialized].previous_typed);
                    _ = fn_ctx.binders.remove(captures[initialized].binder);
                }
            }
            self.allocator.free(captures);
        }
        defer self.allocator.free(captures);

        for (fn_value.captures, 0..) |capture, index| {
            const binder = constCaptureBinder(capture.id);
            const lowered_ty = try fn_ctx.lowerConstCaptureType(store_view, capture.ty);
            const capture_cell = try fn_ctx.draftTypeCell(lowered_ty);
            const local = try fn_ctx.addFreshLocalWithBinderCell(self.builder.symbols.fresh(), capture_cell, binder);
            try fn_ctx.bindLocalName(local, binder);
            const previous = fn_ctx.binders.get(binder);
            try fn_ctx.binders.put(binder, local);
            const previous_typed = try fn_ctx.putTypedBinder(binder, lowered_ty, local);
            captures[index] = .{
                .binder = binder,
                .local = local,
                .previous = previous,
                .previous_typed = previous_typed,
                .ty = lowered_ty,
                .value = undefined,
            };
            initialized += 1;
        }
        for (fn_value.captures, 0..) |capture, index| {
            captures[index].value = if (static_data_const_locator) |const_locator|
                try fn_ctx.restoredStaticDataCandidateNode(store_view, fn_view, capture.value, captures[index].ty, const_locator, checkedBinderType(fn_view, constCaptureBinder(capture.id)), .allow)
            else
                try fn_ctx.restoreConstNodeAtType(store_view, fn_view, capture.value, captures[index].ty);
        }

        const capture_nested = switch (template.fn_def) {
            .nested => |nested| nested,
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => Common.invariant("capturing stored function had no nested function identity"),
        };
        const restored_local_proc_entries = try fn_ctx.enterRestoredLocalProcScope(capture_nested, fn_ctx.current_fn_key);
        defer if (restored_local_proc_entries) |entries| fn_ctx.allocator.free(entries);

        defer {
            var index = initialized;
            while (index > 0) {
                index -= 1;
                fn_ctx.restoreTypedBinder(captures[index].binder, captures[index].ty, captures[index].previous_typed);
                if (captures[index].previous) |previous| {
                    fn_ctx.binders.put(captures[index].binder, previous) catch |err| switch (err) {
                        error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                    };
                } else {
                    _ = fn_ctx.binders.remove(captures[index].binder);
                }
            }
        }

        const request_fn_node = try fn_ctx.activeNodeFromType(ty);
        const capture_entry_guards = try self.allocator.alloc(NodeId, captures.len);
        defer self.allocator.free(capture_entry_guards);
        for (captures, capture_entry_guards) |capture, *node|
            node.* = try fn_ctx.activeNodeFromType(capture.ty);
        const restored_fn_id = switch (lambda_expr.data) {
            .lambda => try self.builder.lowerDraftNestedFromContext(
                &fn_ctx,
                lambda_expr_id,
                capture_nested,
                template.source_fn_ty,
                template.source_fn_key,
                request_fn_node,
                capture_entry_guards,
                fn_ctx.evidence,
                null,
                .exact_graph,
            ),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("stored capturing function did not reference a checked lambda"),
        };

        const capture_values = try self.allocator.alloc(DraftFnDefCapture, captures.len);
        defer self.allocator.free(capture_values);
        for (captures, 0..) |capture, index| {
            capture_values[index] = .{ .local = capture.local, .value = capture.value };
        }

        return try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .{ .fn_def = .{
                .fn_id = restored_fn_id,
                .captures = try fn_ctx.addFnDefCaptureSpan(capture_values),
            } },
        );
    }

    fn restoreConstParserRuntimeFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const runtime = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant("non-parser function reached parser runtime restore"),
        };
        const fn_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));

        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, runtime.owner, self.graph, self.draft);
        defer fn_ctx.deinit();
        fn_ctx.inheritFrozenEmissionContext(self);
        try fn_ctx.inheritActiveConstBinding(self);
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.builder.functionShape(callable_mono_ty, "stored parser constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored parser constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored parser constructor result type differed from restored function type");

        const runtime_fn = self.builder.functionShape(ty, "stored parser runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 1) Common.invariant("stored parser runtime function had an unexpected arity");

        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        const shape_ty = try fn_ctx.resolvedTypeViewForNode(shape_node);
        const runtime_node = (try self.graph.functionNodes(callable_node)).ret;
        const runtime_boundary = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(runtime_node),
            .pending_deferred,
        );
        const previous_codec_calls = fn_ctx.frozen_codec_calls;
        var runtime_codec_calls: ?FrozenPreparedCodecCalls = null;
        if (!fn_ctx.frozen_sealed_emission) {
            _ = try fn_ctx.prepareStructuralCodecCallsAtNode(
                runtime_boundary,
                .parser,
                shape_node,
                callable_node,
            );
            runtime_codec_calls = try fn_ctx.resolvedPreparedCodecCallsForBoundary(runtime_boundary);
            fn_ctx.frozen_codec_calls = if (runtime_codec_calls) |*calls| calls else unreachable;
        }
        defer {
            fn_ctx.frozen_codec_calls = previous_codec_calls;
            if (runtime_codec_calls) |*calls| calls.deinit(self.allocator);
        }
        const state_local = try fn_ctx.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[0]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, parserEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, parserEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.builder.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try fn_ctx.buildParserRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, str_ty);

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(&.{runtime_arg_tys[0]}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerParseResultFromState(
                shape_ty,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[0],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try fn_ctx.addFn(.{
            .fn_def = .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var parser_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = runtime_arg_tys[0] },
            }),
            .body = parsed,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, parser_expr, ty);
        }
        if (encoding_let) |let_| {
            parser_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, parser_expr, ty);
        }
        fn_ctx.fillExprReservation(runtime_boundary, parser_expr);
        return runtime_boundary;
    }

    fn restoreConstParserRuntimeFnAtNode(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        request_fn_node: NodeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const runtime = switch (fn_value.fn_def) {
            .parser_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .encoder_for_runtime => Common.invariant("non-parser function reached graph-native parser runtime restore"),
        };
        const fn_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));

        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, runtime.owner, self.graph, self.draft);
        defer fn_ctx.deinit();
        fn_ctx.inheritFrozenEmissionContext(self);
        try fn_ctx.inheritActiveConstBinding(self);
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        var source_captures = try self.builder.bindConstSourceCaptures(
            &fn_ctx,
            store_view,
            fn_view,
            fn_value,
            static_data_const_locator,
        );
        defer self.builder.releaseConstSourceCaptures(&fn_ctx, &source_captures);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            &fn_ctx,
            expr.ty,
            request_fn_node,
            .expression_lowering,
        );
        const callable = try self.graph.functionNodes(callable_node);
        if (callable.args.len != 1) Common.invariant("stored parser constructor had an unexpected arity");
        if (!self.graph.sameClass(callable.ret, request_fn_node)) {
            Common.invariant("stored parser constructor result cell differed from its graph-native request");
        }
        const encoding_node = callable.args[0];
        const encoding_cell = DraftTypeCell.fromGraphNode(encoding_node);
        const encoding_ty = try fn_ctx.resolvedTypeViewForNode(encoding_node);

        const runtime_fn = try self.graph.functionNodes(request_fn_node);
        if (runtime_fn.args.len != 1) Common.invariant("stored parser runtime function had an unexpected arity");
        const state_cell = DraftTypeCell.fromGraphNode(runtime_fn.args[0]);
        const ret_cell = DraftTypeCell.fromGraphNode(runtime_fn.ret);
        const state_ty = try fn_ctx.resolvedTypeViewForNode(runtime_fn.args[0]);
        const ret_ty = try fn_ctx.resolvedTypeViewForNode(runtime_fn.ret);

        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        const shape_ty = try fn_ctx.resolvedTypeViewForNode(shape_node);
        const runtime_boundary = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(request_fn_node),
            .pending_deferred,
        );
        const previous_codec_calls = fn_ctx.frozen_codec_calls;
        var runtime_codec_calls: ?FrozenPreparedCodecCalls = null;
        if (!fn_ctx.frozen_sealed_emission) {
            _ = try fn_ctx.prepareStructuralCodecCallsAtNode(
                runtime_boundary,
                .parser,
                shape_node,
                callable_node,
            );
            runtime_codec_calls = try fn_ctx.resolvedPreparedCodecCallsForBoundary(runtime_boundary);
            fn_ctx.frozen_codec_calls = if (runtime_codec_calls) |*calls| calls else unreachable;
        }
        defer {
            fn_ctx.frozen_codec_calls = previous_codec_calls;
            if (runtime_codec_calls) |*calls| calls.deinit(self.allocator);
        }
        const state_local = try fn_ctx.addLocalWithBinderCell(self.builder.symbols.fresh(), state_cell, null);
        const state_expr = try fn_ctx.addExprWithTypeCell(state_cell, .{ .local = state_local });

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, parserEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocalWithBinderCell(self.builder.symbols.fresh(), encoding_cell, null);
            fn_ctx.setLocalCaptureId(local, parserEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtNodeWithStaticRoot(
                        store_view,
                        fn_view,
                        node,
                        encoding_node,
                        const_locator,
                    )
                else
                    try fn_ctx.restoreConstNodeAtNode(store_view, fn_view, node, encoding_node),
            };
            break :blk try fn_ctx.addExprWithTypeCell(encoding_cell, .{ .local = local });
        } else try fn_ctx.lowerDispatchOperandAtNode(plan_args[0], encoding_node);

        const str_ty = try self.builder.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try fn_ctx.buildParserRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, str_ty);

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, encoding_ty);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(&.{state_ty}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerParseResultFromState(
                shape_ty,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
                &precomputed_plan,
            );
        };
        const parsed_node = try fn_ctx.exprTypeCell(parsed).toGraphNode(self.graph);
        if (!self.graph.sameClass(parsed_node, runtime_fn.ret)) {
            Common.invariant("stored parser runtime body differed from its graph-native return cell");
        }
        fn_ctx.draft.exprs.items[@intFromEnum(parsed)].ty = ret_cell;

        const stored_evidence = try self.builder.constFnEvidence(fn_ctx.evidence);
        const evidence_digest = Ast.fnEvidenceDigest(stored_evidence.nodes, stored_evidence.frames, stored_evidence.head);
        const runtime_fn_id = try fn_ctx.draft.addFn(.{ .source = .{
            .fn_def = .{ .parser_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
            .const_evidence = try self.builder.program.addConstFnEvidence(stored_evidence.nodes),
            .const_evidence_frames = try self.builder.program.addConstFnEvidenceFrames(stored_evidence.frames),
            .const_evidence_frame_head = stored_evidence.head,
            .evidence_digest = evidence_digest,
        } });
        var parser_expr = try fn_ctx.addExprWithTypeCell(DraftTypeCell.fromGraphNode(request_fn_node), .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try fn_ctx.draft.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = state_cell },
            }),
            .body = parsed,
        } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try fn_ctx.wrapLetAtTypeCell(
                capture.local,
                try fn_ctx.draftTypeCell(str_ty),
                capture.value,
                parser_expr,
                DraftTypeCell.fromGraphNode(request_fn_node),
            );
        }
        if (encoding_let) |let_| {
            parser_expr = try fn_ctx.wrapLetAtTypeCell(
                let_.local,
                encoding_cell,
                let_.value,
                parser_expr,
                DraftTypeCell.fromGraphNode(request_fn_node),
            );
        }
        parser_expr = try self.builder.wrapConstSourceCaptureLetsAtTypeCell(
            &fn_ctx,
            source_captures.items,
            parser_expr,
            DraftTypeCell.fromGraphNode(request_fn_node),
        );
        fn_ctx.fillExprReservation(runtime_boundary, parser_expr);
        return runtime_boundary;
    }

    fn restoreConstEncoderForRuntimeFn(
        self: *BodyContext,
        store_view: ModuleView,
        fn_id: checked.ConstFnId,
        fn_value: check.ConstStore.ConstFn,
        ty: Type.TypeId,
        static_data_const_locator: ?checked.ConstLocator,
    ) Allocator.Error!DraftExprId {
        const runtime = switch (fn_value.fn_def) {
            .encoder_for_runtime => |runtime| runtime,
            .local_template, .imported_template, .nested, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime => Common.invariant("non-encoder_for function reached encoder_for runtime restore"),
        };
        const fn_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(runtime.owner));

        var fn_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, fn_view, self.method_scope, runtime.owner, self.graph, self.draft);
        defer fn_ctx.deinit();
        fn_ctx.inheritFrozenEmissionContext(self);
        try fn_ctx.inheritActiveConstBinding(self);
        fn_ctx.current_fn_key = restoredConstFnContextKey(store_view.key, fn_id, fn_value.source_fn_key);

        const expr = fn_view.bodies.expr(runtime.expr);
        const plan = dispatchPlanForRuntimeExpr(fn_view, runtime.expr);
        const callable_plan = fn_ctx.requireStoredRuntimeCallableDispatchPlan(plan);
        const plan_args = callable_plan.operands;
        const callable_node = try fn_ctx.instantiateCallableDispatchPlanCallNodeFromCaller(callable_plan, &fn_ctx, expr.ty, ty);
        const callable_mono_ty = try fn_ctx.resolvedTypeViewForNode(callable_node);
        const fn_data = self.builder.functionShape(callable_mono_ty, "stored encoder_for constructor had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 1) Common.invariant("stored encoder_for constructor had an unexpected arity");
        if (!fn_ctx.sameType(fn_data.ret, ty)) Common.invariant("stored encoder_for constructor result type differed from restored function type");

        const runtime_fn = self.builder.functionShape(ty, "stored encoder_for runtime value had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 2) Common.invariant("stored encoder_for runtime function had an unexpected arity");

        const shape_node = try fn_ctx.instNode(plan.dispatcher_ty);
        const shape_ty = try fn_ctx.resolvedTypeViewForNode(shape_node);
        const runtime_node = (try self.graph.functionNodes(callable_node)).ret;
        const runtime_boundary = try fn_ctx.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(runtime_node),
            .pending_deferred,
        );
        const previous_codec_calls = fn_ctx.frozen_codec_calls;
        var runtime_codec_calls: ?FrozenPreparedCodecCalls = null;
        if (!fn_ctx.frozen_sealed_emission) {
            _ = try fn_ctx.prepareStructuralCodecCallsAtNode(
                runtime_boundary,
                .encoder,
                shape_node,
                callable_node,
            );
            runtime_codec_calls = try fn_ctx.resolvedPreparedCodecCallsForBoundary(runtime_boundary);
            fn_ctx.frozen_codec_calls = if (runtime_codec_calls) |*calls| calls else unreachable;
        }
        defer {
            fn_ctx.frozen_codec_calls = previous_codec_calls;
            if (runtime_codec_calls) |*calls| calls.deinit(self.allocator);
        }
        const value_local = try fn_ctx.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);
        const value_expr = try fn_ctx.localExpr(value_local, runtime_arg_tys[0]);
        const state_local = try fn_ctx.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[1]);
        const state_expr = try fn_ctx.localExpr(state_local, runtime_arg_tys[1]);

        var encoding_let: ?struct {
            local: DraftLocalId,
            value: DraftExprId,
        } = null;
        const encoding_expr = if (constGeneratedCaptureNode(fn_value, encoderForEncodingCaptureId())) |node| blk: {
            const local = try fn_ctx.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
            fn_ctx.setLocalCaptureId(local, encoderForEncodingCaptureId());
            encoding_let = .{
                .local = local,
                .value = if (static_data_const_locator) |const_locator|
                    try fn_ctx.restoreConstNodeAtTypeWithStaticRoot(store_view, fn_view, node, arg_tys[0], const_locator)
                else
                    try fn_ctx.restoreConstNodeAtType(store_view, fn_view, node, arg_tys[0]),
            };
            break :blk try fn_ctx.localExpr(local, arg_tys[0]);
        } else try fn_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const str_ty = try self.builder.primitiveType(.str);
        var precomputed_plan = BodyContext.ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try fn_ctx.buildEncodeRestoredPrecomputedPlan(&precomputed_plan, fn_value, store_view, fn_view, shape_ty, arg_tys[0], str_ty);

        const saved_encoder_source_fn_ty = fn_ctx.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = fn_ctx.generated_encoder_source_expr;
        const saved_encoder_lambda_index = fn_ctx.generated_encoder_lambda_index;
        fn_ctx.generated_encoder_source_fn_ty = fn_value.source_fn_ty;
        fn_ctx.generated_encoder_source_expr = runtime.expr;
        fn_ctx.generated_encoder_lambda_index = 0;
        defer {
            fn_ctx.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            fn_ctx.generated_encoder_source_expr = saved_encoder_source_expr;
            fn_ctx.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (encoding_let != null) try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try fn_ctx.enterCallableBodyDemandScope(runtime_arg_tys, capture_tys.items);
            defer demand_scope.leave();
            break :blk try fn_ctx.lowerEncodeShapeToState(
                shape_ty,
                value_expr,
                encoding_expr,
                arg_tys[0],
                state_expr,
                runtime_arg_tys[1],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const runtime_fn_id = try fn_ctx.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = runtime.owner,
                .expr = runtime.expr,
            } },
            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var encoder_expr = try fn_ctx.addExpr(.{ .ty = ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try fn_ctx.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = runtime_arg_tys[0] },
                .{ .local = state_local, .ty = runtime_arg_tys[1] },
            }),
            .body = encoded,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try fn_ctx.wrapLet(capture.local, str_ty, capture.value, encoder_expr, ty);
        }
        if (encoding_let) |let_| {
            encoder_expr = try fn_ctx.wrapLet(let_.local, arg_tys[0], let_.value, encoder_expr, ty);
        }
        fn_ctx.fillExprReservation(runtime_boundary, encoder_expr);
        return runtime_boundary;
    }

