            .source_fn_ty = fn_value.source_fn_ty,
            .source_fn_key = fn_value.source_fn_key,
            .mono_fn_ty = DraftTypeCell.fromGraphNode(request_fn_node),
            .const_evidence = try self.builder.program.addConstFnEvidence(stored_evidence.nodes),
            .const_evidence_frames = try self.builder.program.addConstFnEvidenceFrames(stored_evidence.frames),
            .const_evidence_frame_head = stored_evidence.head,
            .evidence_digest = evidence_digest,
        } });
        var encoder_expr = try fn_ctx.addExprWithTypeCell(DraftTypeCell.fromGraphNode(request_fn_node), .{ .lambda = .{
            .fn_id = .{ .draft = runtime_fn_id },
            .args = try fn_ctx.draft.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = value_cell },
                .{ .local = state_local, .ty = state_cell },
            }),
            .body = encoded,
        } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try fn_ctx.wrapLetAtTypeCell(
                capture.local,
                try fn_ctx.draftTypeCell(str_ty),
                capture.value,
                encoder_expr,
                DraftTypeCell.fromGraphNode(request_fn_node),
            );
        }
        if (encoding_let) |let_| {
            encoder_expr = try fn_ctx.wrapLetAtTypeCell(
                let_.local,
                encoding_cell,
                let_.value,
                encoder_expr,
                DraftTypeCell.fromGraphNode(request_fn_node),
            );
        }
        encoder_expr = try self.builder.wrapConstSourceCaptureLetsAtTypeCell(
            &fn_ctx,
            source_captures.items,
            encoder_expr,
            DraftTypeCell.fromGraphNode(request_fn_node),
        );
        fn_ctx.fillExprReservation(runtime_boundary, encoder_expr);
        return runtime_boundary;
    }

    fn lowerConstructorChildAtCell(
        self: *BodyContext,
        child: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const node = try cell.toGraphNode(self.graph);
        if (try self.nodeIsProvenUninhabited(node)) {
            return try self.lowerExplicitUninhabitedInvocationAtTypeCell(child, cell);
        }
        return try self.lowerExprAtTypeCell(child, cell);
    }

    fn relateLookupExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        maybe_ref: ?checked.ResolvedValueId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        const ref_id = maybe_ref orelse Common.invariant("checked lookup reached Monotype without resolved value ref");
        const expr = self.view.bodies.expr(checked_expr);
        if (self.currentLocalBindingForResolvedValue(ref_id)) |binding| {
            const local_cell = self.localTypeCell(binding.local);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(expr.ty, local_cell);
            try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binding.binder), local_cell);
            try relateRequestComponent(self.graph, local_node, expected_node);
            return;
        }
        if (try self.currentConstLocalForResolvedValue(ref_id)) |local_id| {
            const local_cell = self.localTypeCell(local_id);
            const local_node = try local_cell.toGraphNode(self.graph);
            try self.constrainCheckedInterfaceToCell(expr.ty, local_cell);
            try relateRequestComponent(self.graph, local_node, expected_node);
            return;
        }
        const record = self.view.resolved_refs.records[@intFromEnum(ref_id)];
        const const_use: ?checked.ConstUseTemplate = switch (record.ref) {
            .selected_hoisted_const => |selected| selected.const_use,
            .top_level_const => |value| value,
            .imported_const => |value| value,
            .platform_required_const => |required| required.const_use,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_proc, .promoted_top_level_proc => null,
        };
        if (const_use) |value| {
            const witness_node = try self.constUseTypeNode(expr.ty, value);
            try relateRequestComponent(self.graph, expected_node, witness_node);
            return;
        }
        switch (record.ref) {
            .local_proc,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {
                _ = try self.graph.functionNodes(expected_node);
                try constrainDeferredTemplateTypeArguments(
                    self.graph,
                    try self.instNode(expr.ty),
                    expected_node,
                );
                return;
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => {},
        }
        try self.graph.unify(expected_node, try self.instNode(expr.ty));
    }

    fn relateExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("expr_relation_requests");
        // Divergent expressions never return a value to relate to the request.
        // In particular, checking may replace a failed callee with
        // `runtime_error`, which emits a crash, while its unused call type
        // contains `.err`.
        if (self.checkedExprDivergesInLoweredRuntime(checked_expr)) return;
        const expr = self.view.bodies.expr(checked_expr);
        switch (expr.data) {
            .lookup_local => |lookup| try self.relateLookupExprAtNode(checked_expr, lookup.resolved, expected_node),
            .lookup_external => |resolved| try self.relateLookupExprAtNode(checked_expr, resolved, expected_node),
            .lookup_required => |resolved| try self.relateLookupExprAtNode(checked_expr, resolved, expected_node),
            .call => |call| try self.relateCallExprAtNode(expr.ty, call, expected_node),
            .dispatch_call => |plan| try self.relateDispatchExprAtNode(expr.ty, plan, expected_node),
            .interpolation => |interpolation| try self.relateDispatchExprAtNode(expr.ty, interpolation.plan, expected_node),
            .type_dispatch_call => |plan| try self.relateDispatchExprAtNode(expr.ty, plan, expected_node),
            .method_eq => |plan| try self.relateDispatchExprAtNode(expr.ty, plan, expected_node),
            .field_access => |field| try self.relateFieldAccessExprAtNode(expr.ty, field, expected_node),
            .tag => |tag| try self.relateTagExprAtNode(tag, expected_node),
            .zero_argument_tag => _ = try self.graph.tagRowNodes(expected_node),
            .nominal => |nominal| try self.relateNominalExprAtNode(nominal, expected_node),
            .tuple => |items| try self.relateTupleExprAtNode(items, expected_node),
            .list => |items| try self.relateListExprAtNode(items, expected_node),
            .empty_list => _ = try self.graph.listElementNode(expected_node),
            .empty_record => _ = try self.graph.recordConstructionNodes(expected_node),
            .record => |record| try self.relateRecordExprAtNode(record, expected_node),
            // These forms propagate the exact result cell while their own
            // lowering establishes branch-local binders and statement state.
            // Relating their shared checked result node here would collapse
            // distinct generated-private representations across branches.
            .block, .match_, .if_, .runtime_error => {},
            .lambda, .closure => _ = try self.graph.functionNodes(expected_node),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => try self.graph.unify(expected_node, try self.lowerExprTypeNode(checked_expr)),
        }
    }

    fn relateTagExprAtNode(
        self: *BodyContext,
        tag: anytype,
        tag_node: NodeId,
    ) Allocator.Error!void {
        const name = try self.builder.tagName(self.view, tag.name);
        for (tag.args, 0..) |arg, index| {
            try self.relateExprAtNode(
                arg,
                try self.graph.tagConstructionPayloadNode(tag_node, name, index),
            );
        }
    }

    fn relateNominalExprAtNode(
        self: *BodyContext,
        nominal: anytype,
        nominal_node: NodeId,
    ) Allocator.Error!void {
        const representation_node = self.constructorRepresentationNode(nominal_node);
        if (self.graph.content(representation_node) != .named) {
            Common.invariant("nominal constructor had no nominal graph representation");
        }
        const named = self.graph.namedNodes(representation_node);
        const backing_node = (named.backing orelse
            Common.invariant("nominal constructor graph node had no backing")).node;
        try self.relateExprAtNode(nominal.backing_expr, backing_node);
    }

    fn relateTupleExprAtNode(
        self: *BodyContext,
        items: []const checked.CheckedExprId,
        tuple_node: NodeId,
    ) Allocator.Error!void {
        const item_nodes = try self.graph.tupleItemNodes(tuple_node);
        if (items.len != item_nodes.len) Common.invariant("tuple constructor arity differed from its graph type");
        for (items, item_nodes) |item, item_node| try self.relateExprAtNode(item, item_node);
    }

    fn relateListExprAtNode(
        self: *BodyContext,
        items: []const checked.CheckedExprId,
        list_node: NodeId,
    ) Allocator.Error!void {
        const element_node = try self.graph.listElementNode(list_node);
        for (items) |item| try self.relateExprAtNode(item, element_node);
    }

    fn relateRecordExprAtNode(
        self: *BodyContext,
        record: anytype,
        record_node: NodeId,
    ) Allocator.Error!void {
        _ = try self.graph.recordConstructionNodes(record_node);
        for (record.fields) |field| {
            const mono_field_name = try self.builder.recordFieldName(self.view, field.label);
            try self.relateExprAtNode(
                field.value,
                try self.graph.recordConstructionFieldValueNode(record_node, mono_field_name),
            );
        }
    }

    fn relateDispatchExprAtNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_node: NodeId,
    ) Allocator.Error!void {
        const actual_ret_node = try self.dispatchResultTypeNodeInPhase(
            checked_ret_ty,
            maybe_plan,
            expected_ret_node,
            .expression_lowering,
        );
        try relateRequestComponent(self.graph, actual_ret_node, expected_ret_node);
    }

    fn relateCallExprAtNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        call: anytype,
        expected_ret_node: NodeId,
    ) Allocator.Error!void {
        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        const source_fn_ty = if (call.direct_target) |target|
            self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload)
        else
            call.source_fn_ty_payload;
        const hosted_try_capability = if (call.direct_target) |target|
            try self.hostedTryCapabilityForResolvedTarget(target)
        else
            null;
        const fn_node = try call_ctx.instantiateCallNodeFromCallerAtNode(
            source_fn_ty,
            self,
            checked_ret_ty,
            call.args,
            if (hosted_try_capability != null) expected_ret_node else null,
            hosted_try_capability,
        );
        const fn_nodes = try self.graph.functionNodes(fn_node);
        try relateRequestComponent(self.graph, fn_nodes.ret, expected_ret_node);
        for (call.args, fn_nodes.args) |arg, arg_node| try self.relateExprAtNode(arg, arg_node);
        if (call.direct_target == null) try self.relateExprAtNode(call.func, fn_node);
    }

    fn relateFieldAccessExprAtNode(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        field: anytype,
        expected_field_node: NodeId,
    ) Allocator.Error!void {
        const actual_field_node = try self.fieldAccessTypeNode(checked_ty, field, null);
        try relateRequestComponent(self.graph, actual_field_node, expected_field_node);
    }

    fn prepareConstructorChildrenAtNodes(
        self: *BodyContext,
        checked_exprs: []const checked.CheckedExprId,
        nodes: []const NodeId,
    ) Allocator.Error!void {
        if (checked_exprs.len != nodes.len) Common.invariant("constructor child count differed from graph construction arity");
        for (checked_exprs, nodes) |checked_expr, node| {
            try self.relateExprAtNode(checked_expr, node);
        }
        try self.ensureNestedCallablesAtNodes(checked_exprs, nodes);
    }

    fn lowerExprSpan(self: *BodyContext, checked_exprs: []const checked.CheckedExprId) Allocator.Error!DraftSpan(DraftExprId) {
        const reserved = try self.reserveExprSpan(checked_exprs.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (checked_exprs, 0..) |child, i| {
            self.draft.setReservedExprSpanItem(
                reserved,
                i,
                try self.lowerExprAtTypeCell(
                    child,
                    DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(child)),
                ),
            );
        }
        return reserved.span;
    }

    fn prepareExprSpanAtNodes(
        self: *BodyContext,
        checked_exprs: []const checked.CheckedExprId,
        nodes: []const NodeId,
    ) Allocator.Error!void {
        if (checked_exprs.len != nodes.len) Common.invariant("checked call argument count differed from graph function arity");
        self.builder.countBodyDiagnostic("argument_spans_prepared");
        self.builder.countBodyDiagnosticBy("arguments_prepared", checked_exprs.len);
        for (checked_exprs, nodes) |checked_expr, node| {
            try self.relateExprAtNode(checked_expr, node);
        }
        try self.ensureNestedCallablesAtNodes(checked_exprs, nodes);
    }

    fn lowerPreparedExprSpanAtNodes(
        self: *BodyContext,
        checked_exprs: []const checked.CheckedExprId,
        nodes: []const NodeId,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        if (checked_exprs.len != nodes.len) Common.invariant("checked call argument count differed from graph function arity");
        const reserved = try self.reserveExprSpan(checked_exprs.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (checked_exprs, nodes, 0..) |checked_expr, node, index| {
            self.draft.setReservedExprSpanItem(
                reserved,
                index,
                try self.lowerExprAtTypeCell(checked_expr, DraftTypeCell.fromGraphNode(node)),
            );
        }
        return reserved.span;
    }

    fn lowerListExpr(self: *BodyContext, checked_exprs: []const checked.CheckedExprId, ty: Type.TypeId) Allocator.Error!DraftSpan(DraftExprId) {
        const elem_ty = switch (self.builder.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("list expression had a non-list monotype"),
        };
        const reserved = try self.reserveExprSpan(checked_exprs.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (checked_exprs, 0..) |child, i| {
            const lowered = if (try self.typeIsProvenUninhabited(elem_ty))
                try self.lowerExplicitUninhabitedInvocation(child, elem_ty)
            else
                try self.lowerExprAtType(child, elem_ty);
            self.draft.setReservedExprSpanItem(reserved, i, lowered);
        }
        return reserved.span;
    }

    fn lowerExprSpanAtTypes(
        self: *BodyContext,
        checked_exprs: []const checked.CheckedExprId,
        tys: anytype,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        if (checked_exprs.len != GuardedList.borrowLen(tys)) Common.invariant("call argument arity differs from concrete function type");
        const stable_tys = try GuardedList.dupe(self.allocator, Type.TypeId, tys);
        defer self.allocator.free(stable_tys);
        const reserved = try self.reserveExprSpan(checked_exprs.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (checked_exprs, stable_tys, 0..) |child, ty, i| {
            const lowered = if (try self.typeIsProvenUninhabited(ty))
                try self.lowerExplicitUninhabitedInvocation(child, ty)
            else
                try self.lowerExprAtType(child, ty);
            self.draft.setReservedExprSpanItem(reserved, i, lowered);
        }
        return reserved.span;
    }

    const PreLoweredOperand = struct {
        index: usize,
        expr: DraftExprId,
    };

    const PreLoweredChild = struct {
        checked_expr: checked.CheckedExprId,
        expr: DraftExprId,
    };

    fn preLoweredChildAt(_: *BodyContext, children: []const PreLoweredChild, checked_expr: checked.CheckedExprId) ?DraftExprId {
        for (children) |child| {
            if (child.checked_expr == checked_expr) return child.expr;
        }
        return null;
    }

    fn preLoweredOperandAt(_: *BodyContext, operands: []const PreLoweredOperand, index: usize) ?DraftExprId {
        for (operands) |operand| {
            if (operand.index == index) return operand.expr;
        }
        return null;
    }

    fn lowerDispatchOperandsAtNodes(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        nodes: []const NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        try self.prepareDispatchOperandsAtNodes(operands, nodes, pre_lowered);
        return try self.lowerPreparedDispatchOperandsAtNodes(operands, nodes, pre_lowered);
    }

    fn prepareDispatchOperandsAtNodes(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        nodes: []const NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!void {
        if (operands.len != nodes.len) Common.invariant("dispatch argument arity differs from function graph node");
        for (operands, nodes, 0..) |operand, node, index| {
            if (self.preLoweredOperandAt(pre_lowered, index)) |pre| {
                try relateRequestComponent(
                    self.graph,
                    node,
                    try self.exprTypeCell(pre).toGraphNode(self.graph),
                );
                continue;
            }
            switch (operand) {
                .checked_expr => |expr| try self.relateExprAtNode(expr, node),
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
        for (operands, nodes, 0..) |operand, node, index| {
            if (self.preLoweredOperandAt(pre_lowered, index) != null) continue;
            switch (operand) {
                .checked_expr => |expr| try self.ensureNestedCallableAtNode(expr, node),
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => {},
            }
        }
    }

    fn lowerPreparedDispatchOperandsAtNodes(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        nodes: []const NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftSpan(DraftExprId) {
        if (operands.len != nodes.len) Common.invariant("dispatch argument arity differs from function graph node");
        const reserved = try self.reserveExprSpan(operands.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (operands, nodes, 0..) |operand, node, index| {
            if (self.preLoweredOperandAt(pre_lowered, index)) |pre| {
                self.draft.setReservedExprSpanItem(reserved, index, pre);
                continue;
            }
            const lowered = switch (operand) {
                .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(node)),
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => try self.lowerDispatchOperandAtType(operand, try self.activeTypeFromNode(node)),
            };
            self.draft.setReservedExprSpanItem(reserved, index, lowered);
            try relateRequestComponent(
                self.graph,
                node,
                try self.exprTypeCell(lowered).toGraphNode(self.graph),
            );
        }
        return reserved.span;
    }

    fn lowerDispatchOperandAtType(
        self: *BodyContext,
        operand: static_dispatch.StaticDispatchOperand,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprAtType(expr, ty),
            .generated_interpolation_iter => |expr| try self.lowerGeneratedInterpolationIter(expr, ty),
            .generated_numeral => |literal| try self.lowerNumeralValue(literal, ty),
            .generated_quote => |literal| try self.lowerQuoteValue(literal, ty),
        };
    }

    fn lowerDispatchOperandAtNode(
        self: *BodyContext,
        operand: static_dispatch.StaticDispatchOperand,
        node: NodeId,
    ) Allocator.Error!DraftExprId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(node)),
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => try self.lowerDispatchOperandAtType(operand, try self.activeTypeFromNode(node)),
        };
    }

    fn lowerGeneratedInterpolationIter(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const expr = self.view.bodies.expr(expr_id);
        const interpolation = switch (expr.data) {
            .interpolation => |interpolation| interpolation,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("generated interpolation iterator operand pointed at non-interpolation expression"),
        };

        const backing_ty = self.builder.namedBackingType(ty) orelse
            Common.invariant("generated interpolation iterator expected Iter nominal type");
        const topology = try self.iteratorRepresentationNames();
        const len_field = self.recordFieldByName(backing_ty, topology.len_field);
        const step_field = self.recordFieldByName(backing_ty, topology.step_field);
        const step_fn_ty = step_field.ty;
        const step_shape = self.builder.functionShape(step_fn_ty, "generated interpolation iterator step field was not a function");
        if (self.builder.program.types.span(step_shape.args).len != 0) {
            Common.invariant("generated interpolation iterator step function was not zero-argument");
        }

        return try self.lowerInterpolationIterFromIndex(
            interpolation,
            0,
            expr_id,
            ty,
            backing_ty,
            len_field.ty,
            step_fn_ty,
            step_shape.ret,
        );
    }

    fn lowerInterpolationIterFromIndex(
        self: *BodyContext,
        interpolation: checked.CheckedInterpolation,
        index: usize,
        source_expr_id: checked.CheckedExprId,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_ty: Type.TypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const remaining = interpolation.parts.len - index;
        const len_expr = try self.lowerInterpolationLenIfKnown(remaining, len_ty);

        if (index == interpolation.parts.len) {
            const step_expr = try self.lowerInterpolationDoneStep(interpolation.step_fn_ty, source_expr_id, index, step_fn_ty, step_ret_ty);
            return try self.lowerInterpolationIterRecord(iter_ty, backing_ty, len_expr, step_expr);
        }

        const rest_expr = try self.lowerInterpolationIterFromIndex(
            interpolation,
            index + 1,
            source_expr_id,
            iter_ty,
            backing_ty,
            len_ty,
            step_fn_ty,
            step_ret_ty,
        );
        const rest_local = try self.addLocal(self.builder.symbols.fresh(), iter_ty);
        const rest_pat = try self.bindPat(rest_local, iter_ty);
        const rest_ref = try self.localExpr(rest_local, iter_ty);
        const step_expr = try self.lowerInterpolationOneStep(
            interpolation,
            index,
            source_expr_id,
            rest_ref,
            iter_ty,
            interpolation.step_fn_ty,
            step_fn_ty,
            step_ret_ty,
        );
        const iter_expr = try self.lowerInterpolationIterRecord(iter_ty, backing_ty, len_expr, step_expr);
        return try self.addExpr(.{ .ty = iter_ty, .data = .{ .let_ = .{
            .bind = rest_pat,
            .value = rest_expr,
            .rest = iter_expr,
        } } });
    }

    fn lowerInterpolationIterRecord(
        self: *BodyContext,
        iter_ty: Type.TypeId,
        backing_ty: Type.TypeId,
        len_expr: DraftExprId,
        step_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fields = self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(backing_ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);
        const topology = try self.iteratorRepresentationNames();

        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            lowered[i] = .{
                .name = field.name,
                .value = if (field.name == topology.len_field)
                    len_expr
                else if (field.name == topology.step_field)
                    step_expr
                else
                    Common.invariant("Iter backing record contained an unexpected field"),
            };
        }

        const record_expr = try self.addExpr(.{
            .ty = backing_ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
        return try self.addExpr(.{
            .ty = iter_ty,
            .data = .{ .nominal = record_expr },
        });
    }

    fn lowerInterpolationLenIfKnown(
        self: *BodyContext,
        remaining: usize,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const topology = try self.iteratorRepresentationNames();
        const known_tag = self.monoTagByName(ty, topology.known_tag);
        const payloads = self.builder.program.types.span(known_tag.payloads);
        if (payloads.len != 1) Common.invariant("Iter.len_if_known Known tag did not have one payload");
        const count = try self.intLiteralExpr(@intCast(remaining), GuardedList.at(payloads, 0));
        return try self.addExpr(.{ .ty = ty, .data = .{ .tag = .{
            .name = known_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{count}),
        } } });
    }

    fn lowerInterpolationDoneStep(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const demand_scope = try self.enterCallableBodyDemandScope(&.{}, &.{});
        defer demand_scope.leave();
        const topology = try self.iteratorRepresentationNames();
        const done_tag = self.monoTagByName(step_ret_ty, topology.done_tag);
        const body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = done_tag.name,
            .payloads = .empty(),
        } } });
        return try self.lowerInterpolationStepLambda(source_fn_ty, source_expr_id, index, step_fn_ty, body);
    }

    fn lowerInterpolationOneStep(
        self: *BodyContext,
        interpolation: checked.CheckedInterpolation,
        index: usize,
        source_expr_id: checked.CheckedExprId,
        rest_expr: DraftExprId,
        rest_ty: Type.TypeId,
        source_fn_ty: checked.CheckedTypeId,
        step_fn_ty: Type.TypeId,
        step_ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const demand_scope = try self.enterCallableBodyDemandScope(&.{}, &.{rest_ty});
        defer demand_scope.leave();
        const item_ty = self.iterItemType(rest_ty);
        const item_fields = self.builder.tupleItemTypes(item_ty);
        if (item_fields.len != 2) Common.invariant("generated interpolation iterator item was not a pair");

        const part = interpolation.parts[index];
        const value_expr = try self.lowerExprAtType(part.value, GuardedList.at(item_fields, 0));
        const segment_expr = try self.lowerExprAtType(part.following_segment, GuardedList.at(item_fields, 1));
        const item_expr = try self.addExpr(.{ .ty = item_ty, .data = .{
            .tuple = try self.addExprSpan(&[_]DraftExprId{ value_expr, segment_expr }),
        } });

        const topology = try self.iteratorRepresentationNames();
        const one_tag = self.monoTagByName(step_ret_ty, topology.one_tag);
        const payloads = self.builder.program.types.span(one_tag.payloads);
        if (payloads.len != 1) Common.invariant("Iter step One tag did not have one record payload");
        const payload_ty = GuardedList.at(payloads, 0);
        const payload_expr = try self.lowerInterpolationOnePayload(payload_ty, item_expr, rest_expr);

        const body = try self.addExpr(.{ .ty = step_ret_ty, .data = .{ .tag = .{
            .name = one_tag.name,
            .payloads = try self.addExprSpan(&[_]DraftExprId{payload_expr}),
        } } });
        return try self.lowerInterpolationStepLambda(source_fn_ty, source_expr_id, index, step_fn_ty, body);
    }

    fn lowerInterpolationOnePayload(
        self: *BodyContext,
        ty: Type.TypeId,
        item_expr: DraftExprId,
        rest_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fields = self.builder.program.types.fieldSpan(self.builder.recordFieldsSpan(ty));
        const lowered = try self.allocator.alloc(DraftFieldExpr, fields.len);
        defer self.allocator.free(lowered);
        const topology = try self.iteratorRepresentationNames();

        for (0..GuardedList.borrowLen(fields)) |i| {
            const field = GuardedList.at(fields, i);
            lowered[i] = .{
                .name = field.name,
                .value = if (field.name == topology.item_field)
                    item_expr
                else if (field.name == topology.rest_field)
                    rest_expr
                else
                    Common.invariant("Iter step One payload contained an unexpected field"),
            };
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
    }

    fn lowerInterpolationStepLambda(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        source_expr_id: checked.CheckedExprId,
        index: usize,
        step_fn_ty: Type.TypeId,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const fn_id = try self.addFn(.{
            .fn_def = .{ .checked_generated = self.owner_template },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = generatedInterpolationStepKey(self.current_fn_key, source_expr_id, index),
            .mono_fn_ty = step_fn_ty,
        });
        return try self.addExpr(.{ .ty = step_fn_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{}),
            .body = body,
        } } });
    }

    fn recordFieldByText(self: *BodyContext, ty: Type.TypeId, text: []const u8) Type.Field {
        return self.recordFieldByTextOptional(ty, text) orelse
            Common.invariant("expected record field was absent from monotype type");
    }

    fn recordFieldByName(self: *BodyContext, ty: Type.TypeId, name: names.RecordFieldNameId) Type.Field {
        const fields = switch (self.builder.shapeContent(ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("expected record field belonged to a non-record monotype type"),
        };
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (field.name == name) return field;
        }
        Common.invariant("expected record field id was absent from monotype type");
    }

    fn recordFieldByTextOptional(self: *BodyContext, ty: Type.TypeId, text: []const u8) ?Type.Field {
        const fields = switch (self.builder.shapeContent(ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => return null,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => return null,
        };
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (Ident.textEql(self.builder.program.names.recordFieldLabelText(field.name), text)) return field;
        }
        return null;
    }

    fn iterItemType(self: *BodyContext, ty: Type.TypeId) Type.TypeId {
        return switch (self.builder.program.types.get(ty)) {
            .named => |named| blk: {
                const args = self.builder.program.types.span(named.args);
                if (args.len != 1) Common.invariant("Iter nominal did not have one type argument");
                break :blk GuardedList.at(args, 0);
            },
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("generated interpolation iterator expected named Iter type"),
        };
    }

    fn lowerExprAtType(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCell(checked_expr, .{ .sealed = ty });
    }

    fn lowerExprAtTypeCell(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithDemand(checked_expr, cell, .runtime_value);
    }

    fn lowerExprAtTypeCellWithDemand(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
        demand: LoweringDemand,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithKnownDivergence(
            checked_expr,
            cell,
            demand,
            self.checkedExprDivergesInLoweredRuntime(checked_expr),
        );
    }

    fn lowerExprAtTypeCellWithKnownDivergence(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
        demand: LoweringDemand,
        expr_diverges: bool,
    ) Allocator.Error!DraftExprId {
        const expr = self.view.bodies.expr(checked_expr);
        const saved_loc = self.builder.program.current_loc;
        defer self.builder.program.current_loc = saved_loc;
        const saved_region = self.builder.program.current_region;
        defer self.builder.program.current_region = saved_region;
        const region = self.sourceRegionForExpr(expr);
        self.builder.program.current_loc = try self.sourceLocFor(region);
        self.builder.program.current_region = region;
        return switch (cell) {
            .sealed => |ty| blk: {
                const lowered = if (expr_diverges)
                    try self.lowerDivergentExprAtTypeCell(checked_expr, cell)
                else
                    try self.lowerExprAtTypeWithDemandInner(checked_expr, ty);
                break :blk try self.requireLoweredExprAtCell(expr, cell, demand, lowered);
            },
            .graph_node => |expected_node| blk: {
                const lowered = if (expr_diverges)
                    try self.lowerDivergentExprAtTypeCell(checked_expr, cell)
                else
                    try self.lowerExprAtTypeCellInner(checked_expr, cell, expected_node);
                break :blk try self.requireLoweredExpr(expr, expected_node, demand, lowered);
            },
        };
    }

    fn lowerExprAtTypeCellInner(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        cell: DraftTypeCell,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        return switch (cell) {
            .sealed => Common.invariant("sealed expression reached graph-cell lowering"),
            .graph_node => blk: {
                if (try self.restoredHoistedExprAtNode(checked_expr, expected_node)) |restored| {
                    break :blk restored;
                }
                const expr = self.view.bodies.expr(checked_expr);
                switch (expr.data) {
                    .lookup_local => |lookup| break :blk try self.lowerLookupExprAtNode(checked_expr, lookup.resolved, expected_node),
                    .lookup_external => |resolved| break :blk try self.lowerLookupExprAtNode(checked_expr, resolved, expected_node),
                    .lookup_required => |resolved| break :blk try self.lowerLookupExprAtNode(checked_expr, resolved, expected_node),
                    .lambda => break :blk try self.lowerLambdaExprAtNode(checked_expr, expected_node),
                    .closure => |closure| break :blk try self.lowerClosureAtNode(checked_expr, closure, expected_node),
                    .field_access => |field| break :blk try self.lowerFieldAccessExprAtNode(checked_expr, field, expected_node),
                    .tag => |tag| break :blk try self.lowerTagConstructorAtNode(tag, expected_node),
                    .zero_argument_tag => |tag| break :blk try self.addConstructorExprAtNode(expected_node, .{ .tag = .{
                        .name = try self.builder.tagName(self.view, tag.name),
                        .payloads = .empty(),
                    } }),
                    .nominal => |nominal| break :blk try self.lowerNominalConstructorAtNode(nominal, expected_node),
                    .tuple => |items| break :blk try self.lowerTupleConstructorAtNode(items, expected_node),
                    .list => |items| break :blk try self.lowerListConstructorAtNode(items, expected_node),
                    .empty_list => break :blk try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(expected_node),
                        .{ .list = .empty() },
                    ),
                    // `{}` is a record construction that omits every field:
                    // lower it through the record path so the demanded row's
                    // DEFAULTED fields materialize their defaults into the
                    // inline slots (design.md "Defaulted Fields").
                    .empty_record => {
                        break :blk try self.lowerRecordConstructorAtNode(checked_expr, .{
                            .fields = @as([]const checked.CheckedRecordExprField, &.{}),
                            .ext = @as(?checked.CheckedExprId, null),
                        }, expected_node);
                    },
                    .record => |record| break :blk try self.lowerRecordConstructorAtNode(checked_expr, record, expected_node),
                    .call => break :blk try self.lowerCallExprAtNode(checked_expr, expected_node),
                    .dispatch_call => |plan| {
                        try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                        break :blk try self.lowerDispatchExprAtType(self.view.bodies.expr(checked_expr).ty, plan, cell);
                    },
                    .interpolation => |interpolation| {
                        try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                        break :blk try self.lowerDispatchExprAtType(self.view.bodies.expr(checked_expr).ty, interpolation.plan, cell);
                    },
                    .type_dispatch_call => |plan| {
                        try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                        break :blk try self.lowerDispatchExprAtType(self.view.bodies.expr(checked_expr).ty, plan, cell);
                    },
                    .method_eq => |plan| {
                        try self.selectExprRepresentationAtNode(checked_expr, expected_node);
                        break :blk try self.lowerDispatchExprAtType(self.view.bodies.expr(checked_expr).ty, plan, cell);
                    },
                    .block => |block| break :blk try self.lowerBlockAtTypeCell(block, cell),
                    .match_ => |match| break :blk try self.lowerMatchExprAtTypeCell(checked_expr, match, cell),
                    .if_ => |if_| break :blk try self.lowerIfExprAtTypeCell(checked_expr, if_, cell),
                    .runtime_error => break :blk try self.runtimeCrashExprAtCell(cell, "runtime error"),
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
                }
                switch (expr.data) {
                    .tuple_access => |access| {
                        if (try self.checkedTypeContainsError(expr.ty)) {
                            break :blk try self.runtimeCrashExprAtCell(cell, "runtime error");
                        }
                        if (try self.checkedTypeContainsError(self.view.bodies.expr(access.tuple).ty)) {
                            break :blk try self.runtimeCrashExprAtCell(cell, "runtime error");
                        }
                    },
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
                }
                try relateRequestComponent(
                    self.graph,
                    expected_node,
                    try self.lowerExprTypeNode(checked_expr),
                );
                switch (expr.data) {
                    .tuple_access => |access| {
                        const tuple_node = try self.lowerExprTypeNode(access.tuple);
                        const item_nodes = try self.graph.tupleItemNodes(tuple_node);
                        if (access.elem_index >= item_nodes.len) Common.invariant("tuple access index was outside its graph tuple type");
                        const item_node = item_nodes[access.elem_index];
                        try relateRequestComponent(self.graph, expected_node, item_node);
                        const result_cell = DraftTypeCell.fromGraphNode(
                            if (try self.graph.containsGeneratedPrivate(item_node)) item_node else expected_node,
                        );
                        break :blk try self.addExprWithTypeCell(result_cell, .{ .tuple_access = .{
                            .tuple = try self.lowerExprAtTypeCell(access.tuple, DraftTypeCell.fromGraphNode(tuple_node)),
                            .elem_index = access.elem_index,
                        } });
                    },
                    .run_low_level => |low_level| break :blk try self.addExprWithTypeCell(
                        cell,
                        .{ .low_level = .{
                            .op = low_level.op,
                            .args = try self.lowerExprSpan(low_level.args),
                        } },
                    ),
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda => {},
                }
                const lowered = try self.lowerExprInner(checked_expr);
                try relateRequestComponent(
                    self.graph,
                    expected_node,
                    try self.exprTypeCell(lowered).toGraphNode(self.graph),
                );
                self.draft.exprs.items[@intFromEnum(lowered)].ty = cell;
                break :blk lowered;
            },
        };
    }

    fn selectExprRepresentationAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!void {
        try selectRequestRepresentation(
            self.graph,
            expected_node,
            try self.lowerExprTypeNode(checked_expr),
        );
    }

    fn lowerCallExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const expr = self.view.bodies.expr(checked_expr);
        const call = switch (expr.data) {
            .call => |call| call,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("call-at-node lowering received a non-call expression"),
        };
        const producer_request = if (self.isGeneratedPrivateRootNode(expected_node)) expected_node else null;
        const lowered = if (try self.lowerInspectOnlyCall(
            expr.ty,
            call,
            try self.builder.primitiveType(.str),
            self.inspectCallDemand(call),
        )) |rendered|
            rendered
        else if (try self.restoredHoistedExprAtNode(checked_expr, expected_node)) |restored|
            restored
        else if (if (producer_request) |request|
            try self.lowerCallsiteIntrinsicCallExprAtNode(checked_expr, expr.ty, call, request)
        else
            try self.lowerCallsiteIntrinsicCallExpr(checked_expr, expr.ty, call, null)) |intrinsic|
            intrinsic
        else lowered: {
            // Preserve the expected result as an active graph relation. It may
            // contain unresolved payload cells here, so materializing it as a
            // Monotype TypeId would emit an incomplete output.
            const call_data = if (producer_request) |request|
                try self.lowerCallAtNode(expr.ty, call, request)
            else
                try self.lowerCall(expr.ty, call);
            break :lowered try self.addExprWithTypeCell(call_data.ret_ty, call_data.data);
        };
        const lowered_node = try self.exprTypeCell(lowered).toGraphNode(self.graph);
        const completes_request = try self.resultCompletesRequest(expected_node, lowered_node);
        const contains_generated_private = try self.graph.containsGeneratedPrivate(lowered_node);
        const result_node = if (completes_request)
            lowered_node
        else if (contains_generated_private) blk: {
            try relateRequestComponent(
                self.graph,
                expected_node,
                lowered_node,
            );
            break :blk lowered_node;
        } else try self.relateCheckedNodeToProducedValue(expected_node, lowered_node);
        self.draft.exprs.items[@intFromEnum(lowered)].ty = DraftTypeCell.fromGraphNode(
            result_node,
        );
        return lowered;
    }

    fn lowerFieldAccessExprAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        field: anytype,
        expected_node: NodeId,
    ) Allocator.Error!DraftExprId {
        if (field.segments.len == 0) Common.invariant("checked field access path had no segments");
        if (fieldAccessAnySegmentOptional(field.segments)) {
            // A `.?` chain compiles to runtime slot tests producing the
            // chain's checked `Try` (design.md "Field Kinds (All-Dynamic
            // Optional Fields)"). Both the receiver and result stay attached
            // to the specialization graph until their active Monotypes are
            // needed by the runtime chain lowering.
            const checked_ty = self.view.bodies.expr(expr_id).ty;
            const receiver_node = try self.lowerExprTypeNode(field.receiver);
            const observable = try self.fieldAccessTypeNode(checked_ty, field, null);
            try relateRequestComponent(self.graph, expected_node, observable);
            const result_node = if (try self.graph.containsGeneratedPrivate(observable)) observable else expected_node;
            return try self.lowerOptionalFieldAccessChainAtNode(field, receiver_node, result_node);
        }
        const receiver_node = try self.lowerExprTypeNode(field.receiver);
        const start: u32 = @intCast(self.draft.field_access_segments.items.len);
        try self.draft.field_access_segments.ensureUnusedCapacity(self.allocator, field.segments.len);
        var prefix_node = receiver_node;
        for (field.segments) |segment| {
            const field_name = try self.builder.recordFieldName(self.view, segment.field_name);
            prefix_node = switch (segment.backing_access) {
                .inspectable => try self.graph.requiredRecordFieldNode(prefix_node, field_name),
                .opaque_definition_private => try self.graph.requiredOpaqueDefinitionFieldNode(prefix_node, field_name),
            };
            self.draft.field_access_segments.appendAssumeCapacity(.{ .field = field_name });
        }
        try relateRequestComponent(self.graph, expected_node, prefix_node);
        const result_node = if (try self.graph.containsGeneratedPrivate(prefix_node)) prefix_node else expected_node;
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(result_node),
            .{ .field_access = .{
                .receiver = try self.lowerExprAtTypeCell(field.receiver, DraftTypeCell.fromGraphNode(receiver_node)),
                .segments = .{ .start = start, .len = @intCast(field.segments.len) },
            } },
        );
    }

    fn lowerExprAtTypeWithDemand(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        ty: Type.TypeId,
        demand: LoweringDemand,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithDemand(checked_expr, .{ .sealed = ty }, demand);
    }

    fn lowerExprAtTypeWithDemandInner(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const expr = self.view.bodies.expr(checked_expr);
        switch (expr.data) {
            .call => |call| if (try self.lowerInspectOnlyCall(
                expr.ty,
                call,
                ty,
                self.inspectCallDemand(call),
            )) |rendered| return rendered,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        if (try self.restoredHoistedExprAtType(checked_expr, ty)) |restored| return restored;
        switch (expr.data) {
            .runtime_error => return try self.lowerExprWithType(checked_expr, ty),
            .call => |call| {
                if (try self.lowerCallsiteIntrinsicCallExpr(checked_expr, expr.ty, call, ty)) |lowered| {
                    return lowered;
                }
                try self.constrainKnownType(expr.ty, ty);
                const lowered = try self.lowerCallAtType(expr.ty, call, ty);
                if (!self.sameType(ty, try self.activeTypeFromCell(lowered.ret_ty))) {
                    Common.invariant("checked call expression lowered at a type different from its context type");
                }
                const ret_node = try lowered.ret_ty.toGraphNode(self.graph);
                const expected_node = try self.activeNodeFromType(ty);
                const completes_request = try self.resultCompletesRequest(expected_node, ret_node);
                const contains_generated_private = try self.graph.containsGeneratedPrivate(ret_node);
                const result_cell: DraftTypeCell = if (completes_request)
                    lowered.ret_ty
                else if (contains_generated_private) blk: {
                    try relateRequestComponent(self.graph, expected_node, ret_node);
                    break :blk lowered.ret_ty;
                } else DraftTypeCell.fromGraphNode(try self.relateCheckedNodeToProducedValue(expected_node, ret_node));
                const lowered_expr = try self.addExprWithTypeCell(result_cell, lowered.data);
                return lowered_expr;
            },
            .dispatch_call => |plan| return try self.lowerDispatchExprAtType(expr.ty, plan, .{ .sealed = ty }),
            .interpolation => |interpolation| return try self.lowerDispatchExprAtType(expr.ty, interpolation.plan, .{ .sealed = ty }),
            .type_dispatch_call => |plan| return try self.lowerDispatchExprAtType(expr.ty, plan, .{ .sealed = ty }),
            .method_eq => |plan| return try self.lowerDispatchExprAtType(expr.ty, plan, .{ .sealed = ty }),
            .lookup_local => |lookup| return try self.lowerLookupExprAtType(expr.ty, lookup.resolved, ty),
            .lookup_external => |resolved| return try self.lowerLookupExprAtType(expr.ty, resolved, ty),
            .lookup_required => |resolved| return try self.lowerLookupExprAtType(expr.ty, resolved, ty),
            .structural_eq => |eq| {
                try self.constrainKnownType(expr.ty, ty);
                const lowered = try self.lowerDirectStructuralEqAtType(eq, ty);
                if (!self.sameType(ty, try self.exprType(lowered))) {
                    Common.invariant("checked structural equality lowered at a type different from its context type");
                }
                return lowered;
            },
            .structural_hash => |h| {
                try self.constrainKnownType(expr.ty, ty);
                const lowered = try self.lowerDirectStructuralHashAtType(h, ty);
                if (!self.sameType(ty, try self.exprType(lowered))) {
                    Common.invariant("checked structural hash lowered at a type different from its context type");
                }
                return lowered;
            },
            .field_access => |field| {
                // A sealed result does not imply that the receiver is sealed:
                // it may be a graph-backed local whose open row is constrained
                // only at this field. Keep the receiver and field relation in
                // the graph and let normal finalization seal the result.
                return try self.lowerFieldAccessExprAtNode(
                    checked_expr,
                    field,
                    try self.activeNodeFromType(ty),
                );
            },
            .lambda,
            .closure,
            => {
                const lowered = try self.lowerExprWithType(checked_expr, ty);
                if (!self.sameType(ty, try self.exprType(lowered))) {
                    Common.invariant("checked function expression lowered at a type different from its context type");
                }
                return lowered;
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
        try self.constrainKnownType(expr.ty, ty);
        const lowered = try self.lowerExprWithType(checked_expr, ty);
        if (!self.sameType(ty, try self.exprType(lowered))) {
            Common.invariant("checked expression lowered at a type different from its call operand type");
        }
        return lowered;
    }

    fn sameType(self: *BodyContext, expected: Type.TypeId, actual: Type.TypeId) bool {
        var visiting = std.AutoHashMap(TypePair, void).init(self.allocator);
        defer visiting.deinit();
        return self.sameTypeInner(expected, actual, &visiting);
    }

    const TypePair = struct {
        expected: Type.TypeId,
        actual: Type.TypeId,
    };

    fn sameTypeInner(
        self: *BodyContext,
        expected: Type.TypeId,
        actual: Type.TypeId,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        if (expected == actual) return true;
        if (monoAliasBacking(&self.builder.program.types, expected)) |backing| {
            if (self.sameTypeInner(backing, actual, visiting)) return true;
        }
        if (monoAliasBacking(&self.builder.program.types, actual)) |backing| {
            if (self.sameTypeInner(expected, backing, visiting)) return true;
        }
        const expected_digest = self.builder.program.types.typeDigestCached(&self.builder.program.names, expected, null);
        const actual_digest = self.builder.program.types.typeDigestCached(&self.builder.program.names, actual, null);
        if (std.mem.eql(u8, expected_digest.bytes[0..], actual_digest.bytes[0..])) return true;

        const pair = TypePair{ .expected = expected, .actual = actual };
        if (visiting.contains(pair)) return true;
        visiting.put(pair, {}) catch Common.invariant("monotype equality could not record a recursive type pair");
        defer _ = visiting.remove(pair);

        return self.sameTypeContent(expected, actual, visiting);
    }

    fn sameTypeContent(
        self: *BodyContext,
        expected: Type.TypeId,
        actual: Type.TypeId,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        const expected_content = self.builder.program.types.get(expected);
        const actual_content = self.builder.program.types.get(actual);
        return switch (expected_content) {
            .primitive => |primitive| switch (actual_content) {
                .primitive => |actual_primitive| primitive == actual_primitive,
                .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => false,
            },
            .named => |named| switch (actual_content) {
                .named => |actual_named| self.sameNamedType(named, actual_named, visiting),
                .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => false,
            },
            .record => |fields| switch (actual_content) {
                .record => |actual_fields| self.sameRecordFieldNames(fields, actual_fields, visiting),
                .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => false,
            },
            .tuple => |items| switch (actual_content) {
                .tuple => |actual_items| self.sameTypeSpans(items, actual_items, visiting),
                .primitive, .named, .record, .tag_union, .list, .box, .func, .erased, .zst => false,
            },
            .tag_union => |tags| switch (actual_content) {
                .tag_union => |actual_tags| self.sameTags(tags, actual_tags, visiting),
                .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => false,
            },
            .list => |elem| switch (actual_content) {
                .list => |actual_elem| self.sameTypeInner(elem, actual_elem, visiting),
                .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => false,
            },
            .box => |elem| switch (actual_content) {
                .box => |actual_elem| self.sameTypeInner(elem, actual_elem, visiting),
                .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => false,
            },
            .func => |function| switch (actual_content) {
                .func => |actual_function| self.sameTypeSpans(function.args, actual_function.args, visiting) and
                    self.sameTypeInner(function.ret, actual_function.ret, visiting),
                .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => false,
            },
            .erased => |erased| switch (actual_content) {
                .erased => |actual_erased| std.mem.eql(u8, erased.bytes[0..], actual_erased.bytes[0..]),
                .primitive, .named, .record, .tuple, .tag_union, .list, .box, .func, .zst => false,
            },
            .zst => switch (actual_content) {
                .zst => true,
                .primitive, .named, .record, .tuple, .tag_union, .list, .box, .func, .erased => false,
            },
        };
    }

    fn sameNamedType(
        self: *BodyContext,
        expected: anytype,
        actual: anytype,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        if (!std.mem.eql(u8, expected.named_type.module.bytes[0..], actual.named_type.module.bytes[0..])) return false;
        if (expected.def.module != actual.def.module) return false;
        if (expected.def.source_decl != actual.def.source_decl) return false;
        if (expected.def.source_decl == null and expected.def.type_name != actual.def.type_name) return false;
        if (expected.kind != actual.kind) return false;
        if (expected.builtin_owner != actual.builtin_owner) return false;
        if (!self.sameTypeSpans(expected.args, actual.args, visiting)) return false;
        if (!self.sameNamedBacking(expected.backing, actual.backing, visiting)) return false;
        return self.sameDeclaredOrder(expected.declared_order, actual.declared_order, visiting);
    }

    fn sameNamedBacking(
        self: *BodyContext,
        expected: anytype,
        actual: anytype,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        if (expected == null and actual == null) return true;
        if (expected == null or actual == null) return false;

        const expected_backing = expected.?;
        const actual_backing = actual.?;
        if (expected_backing.use != actual_backing.use) return false;
        if (expected_backing.authority != actual_backing.authority) return false;
        return self.sameTypeInner(expected_backing.ty, actual_backing.ty, visiting);
    }

    fn sameDeclaredOrder(
        self: *BodyContext,
        expected: Type.Span,
        actual: Type.Span,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        const expected_entries = self.builder.program.types.declaredFieldSpan(expected);
        const actual_entries = self.builder.program.types.declaredFieldSpan(actual);
        if (expected_entries.len != actual_entries.len) return false;
        for (0..GuardedList.borrowLen(expected_entries)) |index| {
            const expected_entry = GuardedList.at(expected_entries, index);
            const actual_entry = GuardedList.at(actual_entries, index);
            switch (expected_entry) {
                .named => |expected_name| switch (actual_entry) {
                    .named => |actual_name| if (expected_name != actual_name) return false,
                    .padding => return false,
                },
                .padding => |expected_ty| switch (actual_entry) {
                    .named => return false,
                    .padding => |actual_ty| if (!self.sameTypeInner(expected_ty, actual_ty, visiting)) return false,
                },
            }
        }
        return true;
    }

    fn sameTypeSpans(
        self: *BodyContext,
        expected: Type.Span,
        actual: Type.Span,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        const expected_items = self.builder.program.types.span(expected);
        const actual_items = self.builder.program.types.span(actual);
        if (expected_items.len != actual_items.len) return false;
        for (0..GuardedList.borrowLen(expected_items)) |index| {
            const expected_item = GuardedList.at(expected_items, index);
            const actual_item = GuardedList.at(actual_items, index);
            if (!self.sameTypeInner(expected_item, actual_item, visiting)) return false;
        }
        return true;
    }

    fn sameRecordFieldNames(
        self: *BodyContext,
        expected: Type.Span,
        actual: Type.Span,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        const expected_fields = self.builder.program.types.fieldSpan(expected);
        const actual_fields = self.builder.program.types.fieldSpan(actual);
        if (expected_fields.len != actual_fields.len) return false;
        for (0..GuardedList.borrowLen(expected_fields)) |index| {
            const expected_field = GuardedList.at(expected_fields, index);
            const actual_field = GuardedList.at(actual_fields, index);
            if (expected_field.name != actual_field.name) return false;
            if (expected_field.kind_state != actual_field.kind_state) return false;
            if (!self.sameTypeInner(expected_field.ty, actual_field.ty, visiting)) return false;
            if ((expected_field.value_ty == null) != (actual_field.value_ty == null)) return false;
            if (expected_field.value_ty) |expected_value_ty| {
                if (!self.sameTypeInner(expected_value_ty, actual_field.value_ty.?, visiting)) return false;
            }
        }
        return true;
    }

    fn sameTags(
        self: *BodyContext,
        expected: Type.Span,
        actual: Type.Span,
        visiting: *std.AutoHashMap(TypePair, void),
    ) bool {
        const expected_tags = self.builder.program.types.tagSpan(expected);
        const actual_tags = self.builder.program.types.tagSpan(actual);
        if (expected_tags.len != actual_tags.len) return false;
        for (0..GuardedList.borrowLen(expected_tags)) |index| {
            const expected_tag = GuardedList.at(expected_tags, index);
            const actual_tag = GuardedList.at(actual_tags, index);
            if (expected_tag.name != actual_tag.name) return false;
            if (!self.sameTypeSpans(expected_tag.payloads, actual_tag.payloads, visiting)) return false;
        }
        return true;
    }

    /// Materialize a checked field-default identity at `field_ty`.
    fn defaultedFieldValueFromDefault(
        self: *BodyContext,
        default: checked.CheckedFieldDefault,
        field_ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        const origin_module = default.origin() orelse return null;
        return try self.defaultedFieldValueAt(self.view.names.moduleIdentityBytes(origin_module), default.expr_node, field_ty);
    }

    /// Materialize a Monotype field-default identity at `field_ty`.
    fn defaultedFieldValueFromMonoDefault(
        self: *BodyContext,
        default: Type.FieldDefault,
        field_ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        return try self.defaultedFieldValueAt(self.builder.program.names.moduleIdentityBytes(default.module), default.expr_node, field_ty);
    }

    /// Restore a default from its declaring module, including during local root finalization.
    fn defaultedFieldValueAt(
        self: *BodyContext,
        origin_hash: *const [32]u8,
        expr_node: u32,
        field_ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        const declaring_view = if (moduleViewIdentityMatches(self.view, origin_hash))
            self.view
        else
            self.builder.moduleForIdentityHash(origin_hash) orelse
                Common.invariant("defaulted field's declaring module was not present in the lowering input");
        const default_expr = declaring_view.bodies.defaultExpr(expr_node) orelse
            Common.invariant("defaulted field's default expression was not archived");
        // Local roots may still be pending; imported roots must be finalized.
        if (declaring_view.compile_time_roots.lookupFieldDefaultRootByExpr(default_expr)) |root| {
            switch (root.payload) {
                .const_node => |node| return try self.restoreConstNodeAtType(declaring_view, declaring_view, node, field_ty),
                .pending, .fn_value, .expect => {},
            }
        }
        if (!moduleViewIdentityMatches(self.view, origin_hash)) {
            Common.invariant("imported defaulted field's default constant was not finalized");
        }
        return try self.lowerExprAtType(default_expr, field_ty);
    }

    /// The explicit `??` identity carried by a field in `record_ty`.
    fn parserFieldDefaultFor(
        self: *BodyContext,
        record_ty: Type.TypeId,
        field_name: names.RecordFieldNameId,
    ) ?Type.FieldDefault {
        const span = switch (self.builder.shapeContent(record_ty)) {
            .record => |span| span,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        const fields = self.builder.program.types.fieldSpan(span);
        for (0..GuardedList.borrowLen(fields)) |index| {
            const field = GuardedList.at(fields, index);
            if (field.name == field_name) return field.default;
        }
        return null;
    }

    /// Read the concrete kind selected on an immutable Monotype field.
    fn monotypeFieldKindTag(_: *BodyContext, field: Type.Field) checked.CheckedFieldKind.Tag {
        if (field.kind_state != .resolved) {
            Common.invariant("provisional field kind reached sealed record construction");
        }
        if (field.value_ty != null) {
            if (field.default != null) Common.invariant("optional Monotype field carried a default identity");
            return .optional;
        }
        return if (field.default != null) .defaulted else .required;
    }

    fn sealedDefaultedFieldIdentity(field: Type.Field) Type.FieldDefault {
        if (field.kind_state != .resolved or field.value_ty != null) {
            Common.invariant("sealed defaulted field did not have a resolved inline slot");
        }
        return field.default orelse
            Common.invariant("sealed defaulted field carried no Monotype default identity");
    }

    /// Read the kind selected by the checker for a destructured field.
    fn recordDestructFieldKind(
        self: *BodyContext,
        record_checked_ty: checked.CheckedTypeId,
        destruct: checked.CheckedRecordDestruct,
    ) Allocator.Error!checked.CheckedFieldKind.Tag {
        const target = try self.builder.recordFieldName(self.view, destruct.label);
        return recordDestructKindFromResolution(try self.checkedRecordFieldByName(record_checked_ty, target)) orelse
            Common.invariant("record destructure field was missing from its checked row");
    }

    /// Whether a destructure needs checked-Try to runtime-slot translation.
    fn recordDestructsHaveOptionalField(
        self: *BodyContext,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
    ) Allocator.Error!bool {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required, .sub_pattern => {
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) return true;
                },
                .rest => {},
            }
        }
        return false;
    }

    /// The structural backing node behind a (possibly named) Try node.
    fn optionalTryBackingNode(self: *BodyContext, node: NodeId) NodeId {
        if (self.graph.content(node) == .named) {
            const backing = self.graph.namedNodes(node).backing orelse
                Common.invariant("optional destructure Try node had no runtime backing");
            if (backing.node == node) Common.invariant("optional destructure Try backing did not advance");
            return backing.node;
        }
        return node;
    }

    /// The Try value a destructured OPTIONAL field binds: a runtime test on
    /// the field's tagged slot—EXACTLY a one-segment `.?` access chain
    /// result (`optionalChainRest`, design.md "Field Kinds")—`Present(v)`
    /// yields `Ok(v)` and `Missing` yields `Err(MissingField)`, constructed
    /// at the binder's own checked `Try(payload, [MissingField])` node.
    fn optionalDestructTryExprAtNode(
        self: *BodyContext,
        slot_expr: DraftExprId,
        slot_node: NodeId,
        try_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const present_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_present_tag);
        const missing_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_missing_tag);
        const ok_name = try self.builder.program.names.internTagLabel("Ok");
        const err_name = try self.builder.program.names.internTagLabel("Err");
        const slot_cell = DraftTypeCell.fromGraphNode(slot_node);

        const payload_node = try self.graph.tagPayloadNode(slot_node, present_name, 0);
        const payload_cell = DraftTypeCell.fromGraphNode(payload_node);
        const payload_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), payload_cell, null);
        const present_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
            .name = present_name,
            .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(payload_cell, .{ .bind = payload_local })}),
        } });
        const ok_body = try self.addConstructorExprAtNode(try_node, .{ .tag = .{
            .name = ok_name,
            .payloads = try self.addExprSpan(&.{try self.addExprWithTypeCell(payload_cell, .{ .local = payload_local })}),
        } });

        const missing_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
            .name = missing_name,
            .payloads = .empty(),
        } });
        const err_node = try self.graph.tagPayloadNode(self.optionalTryBackingNode(try_node), err_name, 0);
        const err_body = try self.addConstructorExprAtNode(try_node, .{ .tag = .{
            .name = err_name,
            .payloads = try self.addExprSpan(&.{try self.optionalDestructMissingFieldExprAtNode(err_node)}),
        } });

        const branches = [_]DraftBranch{
            .{ .pat = present_pat, .body = ok_body },
            .{ .pat = missing_pat, .body = err_body },
        };
        return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(try_node), .{ .match_ = .{
            .scrutinee = slot_expr,
            .branches = try self.addBranchSpan(&branches),
        } });
    }

    /// The constant `MissingField` error value at the Try's error node (the
    /// closed `[MissingField]` union the checker minted for the binder).
    fn optionalDestructMissingFieldExprAtNode(self: *BodyContext, err_node: NodeId) Allocator.Error!DraftExprId {
        const missing_field_name = try self.builder.program.names.internTagLabel("MissingField");
        return try self.addConstructorExprAtNode(err_node, .{ .tag = .{
            .name = missing_field_name,
            .payloads = .empty(),
        } });
    }

    /// Translate an optional destructure from checked Try space into flat
    /// Present/Missing slot space, queueing binder preludes as needed.
    fn lowerOptionalDestructChildAtSlotNode(
        self: *BodyContext,
        child: checked.CheckedPatternId,
        slot_node: NodeId,
        result_node: NodeId,
    ) Allocator.Error!DraftPatId {
        const slot_cell = DraftTypeCell.fromGraphNode(slot_node);
        const pattern = self.view.bodies.pattern(child);
        const data: BodyPatData = switch (pattern.data) {
            .underscore => .wildcard,
            .assign => |binder| blk: {
                const slot_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), slot_cell, null);
                try self.queueOptionalDestructSlotBind(binder, slot_local, slot_node, result_node);
                break :blk .{ .bind = slot_local };
            },
            .as => |as| blk: {
                const slot_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), slot_cell, null);
                try self.queueOptionalDestructSlotBind(as.binder, slot_local, slot_node, result_node);
                break :blk .{ .as = .{
                    .pattern = try self.lowerOptionalDestructChildAtSlotNode(as.pattern, slot_node, result_node),
                    .local = slot_local,
                } };
            },
            .nominal => |nominal| return try self.lowerOptionalDestructChildAtSlotNode(
                nominal.backing_pattern,
                slot_node,
                self.optionalTryBackingNode(result_node),
            ),
            .applied_tag => |tag| blk: {
                const tag_name = try self.builder.tagName(self.view, tag.name);
                const ok_name = try self.builder.program.names.internTagLabel("Ok");
                const err_name = try self.builder.program.names.internTagLabel("Err");
                const present_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_present_tag);
                const missing_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_missing_tag);
                if (tag.args.len != 1) {
                    Common.invariant("optional destructure Try pattern tag did not carry exactly one payload");
                }
                if (tag_name == ok_name) {
                    const payload_node = try self.graph.tagPayloadNode(slot_node, present_name, 0);
                    break :blk .{ .tag = .{
                        .name = present_name,
                        .payloads = try self.addPatSpan(&.{try self.lowerPatternAtNode(tag.args[0], payload_node)}),
                    } };
                }
                if (tag_name == err_name) {
                    const err_node = try self.graph.tagPayloadNode(
                        self.optionalTryBackingNode(result_node),
                        err_name,
                        0,
                    );
                    try self.queueOptionalDestructErrPayloadBinds(tag.args[0], err_node);
                    break :blk .{ .tag = .{
                        .name = missing_name,
                        .payloads = .empty(),
                    } };
                }
                Common.invariant("optional destructure Try pattern used a tag other than Ok or Err");
            },
            .pending,
            .runtime_error,
            .record_destructure,
            .tuple,
            .list,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            => Common.invariant("optional destructure sub-pattern had a non-Try checked shape"),
        };
        return try self.addPatWithTypeCell(slot_cell, data);
    }

    /// Queue a translated optional-destruct binder whose value is the slot
    /// local materialized as Try.
    fn queueOptionalDestructSlotBind(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        slot_local: DraftLocalId,
        slot_node: NodeId,
        result_node: NodeId,
    ) Allocator.Error!void {
        const binder_local = try self.materializePatternBinderAtCell(binder, DraftTypeCell.fromGraphNode(result_node));
        try self.optional_destruct_binds.append(self.allocator, .{
            .binder_local = binder_local,
            .value = .{ .slot_to_try = .{
                .slot_local = slot_local,
                .slot_node = slot_node,
                .try_node = result_node,
            } },
        });
    }

    /// Queue the binders of an `Err(p)` payload pattern translated to the
    /// slot's `Missing` tag: `p` matches the closed `[MissingField]` union,
    /// so its refutable part (`MissingField`) always matches and its binders
    /// bind the constant error value.
    fn queueOptionalDestructErrPayloadBinds(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        err_node: NodeId,
    ) Allocator.Error!void {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .underscore => {},
            .assign => |binder| {
                const binder_local = try self.materializePatternBinderAtCell(binder, DraftTypeCell.fromGraphNode(err_node));
                try self.optional_destruct_binds.append(self.allocator, .{
                    .binder_local = binder_local,
                    .value = .{ .missing_err = .{ .err_node = err_node } },
                });
            },
            .as => |as| {
                const binder_local = try self.materializePatternBinderAtCell(as.binder, DraftTypeCell.fromGraphNode(err_node));
                try self.optional_destruct_binds.append(self.allocator, .{
                    .binder_local = binder_local,
                    .value = .{ .missing_err = .{ .err_node = err_node } },
                });
                try self.queueOptionalDestructErrPayloadBinds(as.pattern, err_node);
            },
            .applied_tag => |tag| {
                // `[MissingField]` has exactly one payload-less tag; the
                // pattern always matches once the slot is Missing.
                if (tag.args.len != 0) {
                    Common.invariant("optional destructure MissingField pattern carried a payload");
                }
            },
            .pending,
            .nominal,
            .record_destructure,
            .list,
            .tuple,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .runtime_error,
            => Common.invariant("optional destructure Err payload pattern had a non-[MissingField] checked shape"),
        }
    }

    /// Take ownership of the optional-destruct binder preludes collected
    /// since `start`, restoring the collection to that length (the
    /// `drainPatternLiteralGuards` discipline).
    fn drainOptionalDestructBinds(self: *BodyContext, start: usize) Allocator.Error![]OptionalDestructBind {
        const drained = try self.allocator.dupe(OptionalDestructBind, self.optional_destruct_binds.items[start..]);
        self.optional_destruct_binds.shrinkRetainingCapacity(start);
        return drained;
    }

    /// Wrap an expression (a match branch's body or guard) in the queued
    /// optional-destruct binder preludes: one `let` per user binder,
    /// computing its Try (or constant error) value from the slot local the
    /// translated pattern bound.
    fn applyOptionalDestructBinds(
        self: *BodyContext,
        binds: []const OptionalDestructBind,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const BoundValue = struct {
            value: DraftExprId,
            cell: DraftTypeCell,
        };
        var result = body;
        const result_cell = self.exprTypeCell(body);
        var index = binds.len;
        while (index > 0) {
            index -= 1;
            const bind = binds[index];
            const bound: BoundValue = switch (bind.value) {
                .slot_to_try => |conv| blk: {
                    const slot_expr = try self.addExprWithTypeCell(
                        DraftTypeCell.fromGraphNode(conv.slot_node),
                        .{ .local = conv.slot_local },
                    );
                    break :blk .{
                        .value = try self.optionalDestructTryExprAtNode(slot_expr, conv.slot_node, conv.try_node),
                        .cell = DraftTypeCell.fromGraphNode(conv.try_node),
                    };
                },
                .missing_err => |err| .{
                    .value = try self.optionalDestructMissingFieldExprAtNode(err.err_node),
                    .cell = DraftTypeCell.fromGraphNode(err.err_node),
                },
            };
            result = try self.addExprWithTypeCell(result_cell, .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(bound.cell, .{ .bind = bind.binder_local }),
                .value = bound.value,
                .rest = result,
            } });
        }
        return result;
    }

    /// How a checked-row field lookup resolved. `scheme_interior` is not a
    /// miss: the walk reached a row that is still a type VARIABLE at
    /// template lowering (a generalized scheme interior, e.g. the result
    /// row of a generic record update), which every read boundary treats
    /// required-equivalent per design.md "Kind defaulting as a checker
    /// pass". Only `absent`—a concrete row that does not carry the field—
    /// is a genuine miss.
    const CheckedFieldResolution = union(enum) {
        found: checked.CheckedRecordField,
        scheme_interior,
        absent,
    };

    fn recordDestructKindFromResolution(resolution: CheckedFieldResolution) ?checked.CheckedFieldKind.Tag {
        return switch (resolution) {
            .found => |field| field.kind.tag,
            .scheme_interior => .required,
            .absent => null,
        };
    }

    /// Find a checked field through aliases, nominal backing, and row tails.
    fn checkedRecordFieldByName(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        field_name: names.RecordFieldNameId,
    ) Allocator.Error!CheckedFieldResolution {
        const Visited = struct { module: @TypeOf(self.view.key.bytes), ty: checked.CheckedTypeId };
        var seen = std.AutoHashMap(Visited, void).init(self.allocator);
        defer seen.deinit();
        var view = self.view;
        var current = checked_ty;
        while (true) {
            const visit = Visited{ .module = view.key.bytes, .ty = current };
            if (seen.contains(visit)) return .absent;
            try seen.put(visit, {});
            switch (checkedPayload(view, current)) {
                .alias => |alias| current = alias.backing,
                .record => |record| {
                    for (record.fields) |checked_field| {
                        const lowered_name = try self.builder.recordFieldName(view, checked_field.name);
                        if (lowered_name == field_name) return .{ .found = checked_field };
                    }
                    current = record.ext;
                },
                .record_unbound => |tail_fields| {
                    for (tail_fields) |checked_field| {
                        const lowered_name = try self.builder.recordFieldName(view, checked_field.name);
                        if (lowered_name == field_name) return .{ .found = checked_field };
                    }
                    // An unbound row has no committed extension: the tail is
                    // still open exactly like a scheme-interior variable.
                    return .scheme_interior;
                },
                .nominal => |nominal| {
                    const lookup = self.builder.nominalDeclarationFor(view, nominal) orelse return .absent;
                    view = lookup.view;
                    current = lookup.declaration.backing;
                },
                .flex, .rigid => return .scheme_interior,
                .pending, .err, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => return .absent,
            }
        }
    }

    /// Construct an optional field's tagged Present slot at its graph node
    /// (the closed `[#Missing, #Present(value)]` union). The supplied value's
    /// node was already unified into the slot union's Present payload by the
    /// caller, so no active Monotype view is demanded here.
    fn optionalSlotPresentExprAtNode(
        self: *BodyContext,
        slot_node: NodeId,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const present = try self.builder.program.names.internTagLabel(Builder.optional_slot_present_tag);
        return try self.addConstructorExprAtNode(slot_node, .{ .tag = .{
            .name = present,
            .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
        } });
    }

    /// Construct an optional field's tagged slot in the missing state at its
    /// graph node.
    fn optionalSlotMissingExprAtNode(self: *BodyContext, slot_node: NodeId) Allocator.Error!DraftExprId {
        const missing = try self.builder.program.names.internTagLabel(Builder.optional_slot_missing_tag);
        return try self.addConstructorExprAtNode(slot_node, .{ .tag = .{
            .name = missing,
            .payloads = .empty(),
        } });
    }

    fn optionalSlotPresentExpr(
        self: *BodyContext,
        slot_ty: Type.TypeId,
        slot: Builder.OptionalSlotInfo,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        if (!self.sameType(try self.exprType(value_expr), slot.payload_ty)) {
            Common.invariant("optional field's supplied value type differed from its slot payload type");
        }
        return try self.addExpr(.{
            .ty = slot_ty,
            .data = .{ .tag = .{
                .name = slot.present_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
            } },
        });
    }

    /// Construct an optional field's tagged slot in the missing state:
    /// `Missing` at the slot's union type.
    fn optionalSlotMissingExpr(self: *BodyContext, slot_ty: Type.TypeId) Allocator.Error!DraftExprId {
        const slot = try self.builder.optionalSlotInfo(slot_ty);
        return try self.addExpr(.{
            .ty = slot_ty,
            .data = .{ .tag = .{
                .name = slot.missing_tag.name,
                .payloads = .empty(),
            } },
        });
    }

    /// Lower a mixed access chain to one flat Try, short-circuiting on the
    /// first Missing slot (design.md "Field Kinds").
    fn lowerOptionalFieldAccessChainAtNode(
        self: *BodyContext,
        access: anytype,
        receiver_node: NodeId,
        out_try_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const receiver_cell = DraftTypeCell.fromGraphNode(receiver_node);
        const receiver = try self.lowerExprAtTypeCell(access.receiver, receiver_cell);
        return try self.optionalChainRestAtNode(
            access.segments,
            0,
            receiver,
            receiver_node,
            out_try_node,
        );
    }

    fn optionalChainRestAtNode(
        self: *BodyContext,
        segments: []const checked.CheckedFieldAccessSegment,
        index: usize,
        current: DraftExprId,
        current_node: NodeId,
        out_try_node: NodeId,
    ) Allocator.Error!DraftExprId {
        if (index == segments.len) {
            const ok_name = try self.builder.program.names.internTagLabel("Ok");
            return try self.addConstructorExprAtNode(out_try_node, .{ .tag = .{
                .name = ok_name,
                .payloads = try self.addExprSpan(&.{current}),
            } });
        }

        const segment = segments[index];
        const field_name = try self.builder.recordFieldName(self.view, segment.field_name);
        switch (segment.mode) {
            .required => {
                const field_node = switch (segment.backing_access) {
                    .inspectable => try self.graph.requiredRecordFieldNode(current_node, field_name),
                    .opaque_definition_private => try self.graph.requiredOpaqueDefinitionFieldNode(current_node, field_name),
                };
                const field_expr = try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(field_node),
                    .{ .field_access = .{
                        .receiver = current,
                        .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field_name }}),
                    } },
                );
                return try self.optionalChainRestAtNode(
                    segments,
                    index + 1,
                    field_expr,
                    field_node,
                    out_try_node,
                );
            },
            .optional => {
                const field = switch (segment.backing_access) {
                    .inspectable => try self.graph.optionalRecordFieldNodes(current_node, field_name),
                    .opaque_definition_private => try self.graph.optionalOpaqueDefinitionFieldNodes(current_node, field_name),
                };
                const slot_cell = DraftTypeCell.fromGraphNode(field.slot);
                const payload_cell = DraftTypeCell.fromGraphNode(field.value);
                const slot_expr = try self.addExprWithTypeCell(slot_cell, .{ .field_access = .{
                    .receiver = current,
                    .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field_name }}),
                } });

                const present_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_present_tag);
                const missing_name = try self.builder.program.names.internTagLabel(Builder.optional_slot_missing_tag);
                const payload_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), payload_cell, null);
                const present_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
                    .name = present_name,
                    .payloads = try self.addPatSpan(&.{try self.addPatWithTypeCell(payload_cell, .{ .bind = payload_local })}),
                } });
                const present_body = try self.optionalChainRestAtNode(
                    segments,
                    index + 1,
                    try self.addExprWithTypeCell(payload_cell, .{ .local = payload_local }),
                    field.value,
                    out_try_node,
                );

                const missing_pat = try self.addPatWithTypeCell(slot_cell, .{ .tag = .{
                    .name = missing_name,
                    .payloads = .empty(),
                } });
                const err_name = try self.builder.program.names.internTagLabel("Err");
                const err_node = try self.graph.tagPayloadNode(self.optionalTryBackingNode(out_try_node), err_name, 0);
                const missing_body = try self.addConstructorExprAtNode(out_try_node, .{ .tag = .{
                    .name = err_name,
                    .payloads = try self.addExprSpan(&.{try self.optionalDestructMissingFieldExprAtNode(err_node)}),
                } });

                const branches = [_]DraftBranch{
                    .{ .pat = present_pat, .body = present_body },
                    .{ .pat = missing_pat, .body = missing_body },
                };
                return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(out_try_node), .{ .match_ = .{
                    .scrutinee = slot_expr,
                    .branches = try self.addBranchSpan(&branches),
                } });
            },
        }
    }

    fn lowerOptionalFieldAccessChain(
        self: *BodyContext,
        access: anytype,
        receiver_ty: Type.TypeId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const receiver = try self.lowerExprAtType(access.receiver, receiver_ty);
        return try self.optionalChainRest(access.segments, 0, receiver, receiver_ty, out_try_ty);
    }

    fn optionalChainRest(
        self: *BodyContext,
        segments: []const checked.CheckedFieldAccessSegment,
        index: usize,
        current: DraftExprId,
        current_ty: Type.TypeId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (index == segments.len) return try self.tryOk(out_try_ty, current);
        const segment = segments[index];
        const field_name = try self.builder.recordFieldName(self.view, segment.field_name);
        const slot_ty = self.builder.recordFieldType(current_ty, field_name);
        switch (segment.mode) {
            .required => return try self.optionalChainRest(
                segments,
                index + 1,
                try self.addFieldAccessExpr(current, field_name, slot_ty),
                slot_ty,
                out_try_ty,
            ),
            .optional => {
                const slot = try self.builder.optionalSlotInfo(slot_ty);
                const slot_expr = try self.addFieldAccessExpr(current, field_name, slot_ty);

                const payload_local = try self.addLocal(self.builder.symbols.fresh(), slot.payload_ty);
                const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
                const present_pat = try self.addPat(.{ .ty = slot_ty, .data = .{ .tag = .{
                    .name = slot.present_tag.name,
                    .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
                } } });
                const present_body = try self.optionalChainRest(
                    segments,
                    index + 1,
                    try self.localExpr(payload_local, slot.payload_ty),
                    slot.payload_ty,
                    out_try_ty,
                );

                const missing_pat = try self.addPat(.{ .ty = slot_ty, .data = .{ .tag = .{
                    .name = slot.missing_tag.name,
                    .payloads = .empty(),
                } } });
                const err_ty = self.tryInfo(out_try_ty).err_ty;
                const missing_body = try self.tryErr(
                    out_try_ty,
                    try self.tagUnionValueWithoutPayload(err_ty, "MissingField"),
                );

                const branches = [_]DraftBranch{
                    .{ .pat = present_pat, .body = present_body },
                    .{ .pat = missing_pat, .body = missing_body },
                };
                return try self.addExpr(.{ .ty = out_try_ty, .data = .{ .match_ = .{
                    .scrutinee = slot_expr,
                    .branches = try self.addBranchSpan(&branches),
                } } });
            },
        }
    }

    fn lowerRecordExpr(
        self: *BodyContext,
        record: anytype,
        ty: Type.TypeId,
        pre_lowered: []const PreLoweredChild,
    ) Allocator.Error!DraftExprId {
        if (record.ext) |ext| {
            const base_expr = self.preLoweredChildAt(pre_lowered, ext) orelse try self.lowerExpr(ext);
            const fields = try self.allocator.alloc(DraftFieldExpr, record.fields.len);
            defer self.allocator.free(fields);
            for (record.fields, 0..) |field, index| {
                const name = try self.builder.recordFieldName(self.view, field.label);
                const target_field = self.builder.recordField(ty, name);
                const slot_ty = target_field.ty;
                const field_kind: checked.CheckedFieldKind.Tag =
                    self.monotypeFieldKindTag(target_field);
                fields[index] = .{
                    .name = name,
                    .value = value: {
                        // Supplied optional values enter the slot through #Present.
                        if (field_kind == .optional) {
                            const slot = try self.builder.optionalSlotInfo(slot_ty);
                            const payload = if (self.preLoweredChildAt(pre_lowered, field.value)) |pre| pre_blk: {
                                if (!self.sameType(slot.payload_ty, try self.exprType(pre))) {
                                    Common.invariant("record update child lowered at a type different from its finalized field type");
                                }
                                break :pre_blk pre;
                            } else try self.lowerExprAtType(field.value, slot.payload_ty);
                            break :value try self.optionalSlotPresentExpr(slot_ty, slot, payload);
                        }
                        break :value if (self.preLoweredChildAt(pre_lowered, field.value)) |pre|
                            pre
                        else
                            try self.lowerExprAtType(field.value, slot_ty);
                    },
                };
            }
            return try self.addExpr(.{ .ty = ty, .data = .{ .record_update = .{
                .base = base_expr,
                .fields = try self.addFieldExprSpan(fields),
            } } });
        }

        const target_fields = switch (self.builder.shapeContent(ty)) {
            .record => |fields| fields,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record expression had a non-record monotype"),
        };
        const target_field_count: usize = @intCast(target_fields.len);
        const lowered = try self.allocator.alloc(DraftFieldExpr, target_field_count);
        defer self.allocator.free(lowered);
        const base_record = if (record.ext) |ext|
            self.preLoweredChildAt(pre_lowered, ext) orelse try self.lowerExpr(ext)
        else
            null;
        const base_ty = if (base_record) |base_expr| try self.exprType(base_expr) else ty;
        const base_local = if (base_record) |_| try self.addLocal(self.builder.symbols.fresh(), base_ty) else null;
        const base_expr = if (base_local) |local| try self.localExpr(local, base_ty) else null;
        const target_field_list = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(target_fields));
        defer self.allocator.free(target_field_list);

        // See lowerRecordExprAtNode: spread-carried reads bind before the
        // update's own field expressions run, so the base's last use precedes
        // any mutation they perform.
        const SpreadRead = struct { local: DraftLocalId, value: DraftExprId };
        const spread_reads = try self.allocator.alloc(?SpreadRead, target_field_count);
        defer self.allocator.free(spread_reads);
        @memset(spread_reads, null);

        for (0..target_field_count) |i| {
            const field = target_field_list[i];
            const field_kind: checked.CheckedFieldKind.Tag =
                self.monotypeFieldKindTag(field);
            const value = if (try self.recordUpdateFieldValue(record.fields, field.name)) |field_value| supplied: {
                // A SUPPLIED OPTIONAL field wraps its value in the slot's
                // Present tag (design.md "Field Kinds"); the checked field
                // expression's type is the VALUE type, never the slot.
                if (field_kind == .optional) {
                    const slot = try self.builder.optionalSlotInfo(field.ty);
                    const payload = if (self.preLoweredChildAt(pre_lowered, field_value)) |pre| pre_blk: {
                        if (!self.sameType(slot.payload_ty, try self.exprType(pre))) {
                            Common.invariant("record constructor child lowered at a type different from its finalized field type");
                        }
                        break :pre_blk pre;
                    } else try self.lowerExprAtType(field_value, slot.payload_ty);
                    break :supplied try self.optionalSlotPresentExpr(field.ty, slot, payload);
                }
                if (self.preLoweredChildAt(pre_lowered, field_value)) |pre| {
                    if (!self.sameType(field.ty, try self.exprType(pre))) {
                        Common.invariant("record constructor child lowered at a type different from its finalized field type");
                    }
                    break :supplied pre;
                }
                if (try self.typeIsProvenUninhabited(field.ty)) {
                    break :supplied try self.lowerExplicitUninhabitedInvocation(field_value, field.ty);
                }
                break :supplied try self.lowerExprAtType(field_value, field.ty);
            } else if (base_expr) |base_value| blk: {
                // Record update copies unmentioned slots verbatim—for an
                // optional field that copies the tagged slot, presence state
                // included. (A MENTIONED optional field takes the supplied
                // branch above: the construction rule applies, the value wraps in
                // `Present` exactly as construction does.) The read is
                // hoisted into its own local so the base's last use ends
                // before any updated field's expression runs (see the
                // spread_reads comment above).
                const read = try self.addFieldAccessExpr(base_value, field.name, field.ty);
                const read_local = try self.addLocal(self.builder.symbols.fresh(), field.ty);
                spread_reads[i] = .{ .local = read_local, .value = read };
                break :blk try self.localExpr(read_local, field.ty);
            } else if (field_kind == .defaulted) defaulted: {
                const default = sealedDefaultedFieldIdentity(field);
                break :defaulted (try self.defaultedFieldValueFromMonoDefault(default, field.ty)) orelse
                    Common.invariant("sealed defaulted field had no archived default value");
            } else if (field_kind == .optional)
                // An OMITTED OPTIONAL field (admitted by width absorption)
                // constructs the slot's Missing tag.
                try self.optionalSlotMissingExpr(field.ty)
            else
                Common.invariant("closed record literal was missing a checked field value");
            lowered[i] = .{
                .name = field.name,
                .value = value,
            };
        }
        var record_expr = try self.addConstructorExpr(ty, .{ .record = try self.addFieldExprSpan(lowered) });
        var spread_index: usize = target_field_count;
        while (spread_index > 0) {
            spread_index -= 1;
            const read = spread_reads[spread_index] orelse continue;
            record_expr = try self.addExpr(.{ .ty = ty, .data = .{ .let_ = .{
                .bind = try self.bindPat(read.local, target_field_list[spread_index].ty),
                .value = read.value,
                .rest = record_expr,
            } } });
        }
        if (base_record) |base_value| {
            return try self.addExpr(.{ .ty = ty, .data = .{ .let_ = .{
                .bind = try self.bindPat(base_local orelse Common.invariant("record update lowered base without a base local"), base_ty),
                .value = base_value,
                .rest = record_expr,
            } } });
        }
        return record_expr;
    }

    fn lowerRecordExprAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        record: anytype,
        record_node: NodeId,
        pre_lowered: []const PreLoweredChild,
    ) Allocator.Error!DraftExprId {
        if (record.ext) |ext| {
            const base_expr = self.preLoweredChildAt(pre_lowered, ext) orelse
                Common.invariant("record graph update lost its pre-lowered base child");
            const fields = try self.allocator.alloc(DraftFieldExpr, record.fields.len);
            defer self.allocator.free(fields);
            for (record.fields, 0..) |field, index| {
                const name = try self.builder.recordFieldName(self.view, field.label);
                const pre = self.preLoweredChildAt(pre_lowered, field.value) orelse
                    Common.invariant("record graph update lost its pre-lowered field child");
                const field_kind = try self.graph.recordConstructionFieldKind(record_node, name);
                // A SUPPLIED OPTIONAL field's child was lowered at the slot's
                // Present payload; wrap it into the tagged slot at the slot's
                // graph node (design.md "Field Kinds (All-Dynamic Optional
                // Fields)"). Required and defaulted slots write the child
                // verbatim.
                const value = if (field_kind == .optional)
                    try self.optionalSlotPresentExprAtNode(
                        try self.graph.recordConstructionFieldNode(record_node, name),
                        pre,
                    )
                else
                    pre;
                fields[index] = .{ .name = name, .value = value };
            }
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(record_node), .{ .record_update = .{
                .base = base_expr,
                .fields = try self.addFieldExprSpan(fields),
            } });
        }

        const target_fields = (try self.graph.recordConstructionNodes(record_node)).fields;
        const lowered = try self.allocator.alloc(DraftFieldExpr, target_fields.len);
        defer self.allocator.free(lowered);
        const produced_fields = try self.allocator.alloc(InstField, target_fields.len);
        defer self.allocator.free(produced_fields);
        var requires_distinct_witness = false;
        var distinct_witness_needs_relation = false;

        const base_record = if (record.ext) |ext|
            self.preLoweredChildAt(pre_lowered, ext) orelse try self.lowerExpr(ext)
        else
            null;
        const base_cell = if (base_record) |base_expr|
            self.exprTypeCell(base_expr)
        else
            DraftTypeCell.fromGraphNode(record_node);
        const base_local = if (base_record != null)
            try self.addLocalWithBinderCell(self.builder.symbols.fresh(), base_cell, null)
        else
            null;
        const base_expr = if (base_local) |local|
            try self.addExprWithTypeCell(base_cell, .{ .local = local })
        else
            null;

        // Spread-carried fields are read out of the base before the update's
        // own field expressions run, each bound to its own local. Each field
        // read only accesses already-evaluated record storage, so scheduling
        // the reads first preserves effects and ends the base's last use ahead
        // of any mutation an updated field performs. Without it, the base stays
        // live across those mutations and only the field read scheduled last
        // by ascending field-name order finds its collection
        // uniquely referenced; every other field copies its whole value.
        const SpreadRead = struct { local: DraftLocalId, cell: DraftTypeCell, value: DraftExprId };
        const spread_reads = try self.allocator.alloc(?SpreadRead, target_fields.len);
        defer self.allocator.free(spread_reads);
        @memset(spread_reads, null);

        for (0..target_fields.len) |index| {
            const field = target_fields[index];
            const value = if (try self.recordUpdateFieldValue(record.fields, field.name)) |field_value| blk: {
                const field_kind = try self.graph.recordConstructionFieldKind(record_node, field.name);
                const pre = self.preLoweredChildAt(pre_lowered, field_value) orelse
                    Common.invariant("record graph constructor lost its pre-lowered field child");
                // A SUPPLIED OPTIONAL field's child was lowered at the slot's
                // Present payload; wrap it into the tagged slot (design.md
                // "Field Kinds (All-Dynamic Optional Fields)").
                if (field_kind == .optional) {
                    // The slot node is not resolved during expression
                    // lowering, so the construction stays in node space.
                    produced_fields[index] = field;
                    break :blk try self.optionalSlotPresentExprAtNode(field.ty, pre);
                }
                const child_node = try self.exprTypeCell(pre).toGraphNode(self.graph);
                if (!self.graph.sameClass(field.ty, child_node)) {
                    // Either side may carry the generated-private
                    // representation: a producer-authored child adopted by a
                    // checked-public construction, or a construction whose
                    // field slot was selected private by generated codec
                    // machinery while the user's opaque handle value stays
                    // checked-public (e.g. a FieldName passed through
                    // user-authored parse_record_field).
                    const child_private = try self.graph.containsGeneratedPrivate(child_node);
                    const field_private = try self.graph.containsGeneratedPrivate(field.ty);
                    const field_completion = try self.resultCompletesRequest(field.ty, child_node);
                    const has_explicit_evidence = try self.producedValueHasExplicitRepresentationEvidence(
                        field.ty,
                        child_node,
                    );
                    if (!child_private and !field_private and !field_completion and !has_explicit_evidence) {
                        Common.invariant("record graph constructor child differed without explicit representation evidence");
                    }
                    requires_distinct_witness = true;
                    if (child_private or field_private) {
                        distinct_witness_needs_relation = true;
                    }
                }
                produced_fields[index] = .{
                    .name = field.name,
                    .ty = child_node,
                    .value_ty = field.value_ty,
                    .kind = field.kind,
                    .default = field.default,
                };
                break :blk pre;
            } else if (base_expr) |base_value| blk: {
                // Record update copies unmentioned slots verbatim—for an
                // optional field that copies the tagged slot, presence state
                // included.
                produced_fields[index] = field;
                const read_cell = DraftTypeCell.fromGraphNode(field.ty);
                const read = try self.addExprWithTypeCell(read_cell, .{ .field_access = .{
                    .receiver = base_value,
                    .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field.name }}),
                } });
                const read_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), read_cell, null);
                spread_reads[index] = .{ .local = read_local, .cell = read_cell, .value = read };
                break :blk try self.addExprWithTypeCell(read_cell, .{ .local = read_local });
            } else omitted: {
                produced_fields[index] = field;
                if (self.omittedRecordFieldDefault(checked_expr, field.name)) |default| {
                    const value_node = field.value_ty orelse field.ty;
                    const value_ty = try self.resolvedTypeViewForNode(value_node);
                    break :omitted (try self.defaultedFieldValueFromDefault(default, value_ty)) orelse
                        Common.invariant("checker-selected omitted default had no archived default value");
                }
                const field_kind = try self.graph.recordOmittedFieldKind(record_node, field.name);
                break :omitted switch (field_kind) {
                    .defaulted => |default| blk: {
                        const value_node = field.value_ty orelse field.ty;
                        const value_ty = try self.resolvedTypeViewForNode(value_node);
                        break :blk (try self.defaultedFieldValueFromMonoDefault(default, value_ty)) orelse
                            Common.invariant("resolved defaulted field had no archived default value");
                    },
                    .optional => try self.optionalSlotMissingExprAtNode(field.ty),
                    .required => Common.invariant("closed record graph constructor was missing a required field value"),
                };
            };
            lowered[index] = .{ .name = field.name, .value = value };
        }

        const produced_node = if (requires_distinct_witness) blk: {
            const fields = try self.graph.arena().dupe(InstField, produced_fields);
            const node = try self.graph.newNode(.{ .record = .{
                .fields = fields,
                .ext = try self.graph.newNode(.empty_record),
            } });
            if (distinct_witness_needs_relation) {
                try relateRequestComponent(self.graph, record_node, node);
            }
            break :blk node;
        } else record_node;
        var record_expr = try self.addConstructorExprAtNode(produced_node, .{ .record = try self.addFieldExprSpan(lowered) });
        var spread_index: usize = target_fields.len;
        while (spread_index > 0) {
            spread_index -= 1;
            const read = spread_reads[spread_index] orelse continue;
            record_expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(produced_node), .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(read.cell, .{ .bind = read.local }),
                .value = read.value,
                .rest = record_expr,
            } });
        }
        if (base_record) |base_value| {
            const local = base_local orelse Common.invariant("record graph update lowered base without a base local");
            return try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(produced_node), .{ .let_ = .{
                .bind = try self.addPatWithTypeCell(base_cell, .{ .bind = local }),
                .value = base_value,
                .rest = record_expr,
            } });
        }
        return record_expr;
    }

    fn lowerTagConstructorAtNode(
        self: *BodyContext,
        tag: anytype,
        tag_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const name = try self.builder.tagName(self.view, tag.name);
        const payload_nodes = try self.allocator.alloc(NodeId, tag.args.len);
        defer self.allocator.free(payload_nodes);
        for (tag.args, 0..) |_, index| {
            payload_nodes[index] = try self.graph.tagConstructionPayloadNode(tag_node, name, index);
        }
        try self.prepareConstructorChildrenAtNodes(tag.args, payload_nodes);
        const lowered = try self.allocator.alloc(DraftExprId, tag.args.len);
        defer self.allocator.free(lowered);
        for (tag.args, payload_nodes, 0..) |arg, payload_node, index| {
            lowered[index] = try self.lowerConstructorChildAtCell(
                arg,
                DraftTypeCell.fromGraphNode(payload_node),
            );
        }
        return try self.addConstructorExprAtNode(tag_node, .{ .tag = .{
            .name = name,
            .payloads = try self.addExprSpan(lowered),
        } });
    }

    fn lowerNominalConstructorAtNode(
        self: *BodyContext,
        nominal: anytype,
        nominal_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const representation_node = self.constructorRepresentationNode(nominal_node);
        if (self.graph.content(representation_node) != .named) {
            Common.invariant("nominal constructor had no nominal graph representation");
        }
        const named = self.graph.namedNodes(representation_node);
        const backing_node = (named.backing orelse
            Common.invariant("nominal constructor graph node had no backing")).node;
        try self.prepareConstructorChildrenAtNodes(&.{nominal.backing_expr}, &.{backing_node});
        const backing = try self.lowerConstructorChildAtCell(
            nominal.backing_expr,
            DraftTypeCell.fromGraphNode(backing_node),
        );
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(representation_node),
            .{ .nominal = backing },
        );
    }

    fn lowerTupleConstructorAtNode(
        self: *BodyContext,
        items: []const checked.CheckedExprId,
        tuple_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const item_nodes = try self.graph.tupleItemNodes(tuple_node);
        if (items.len != item_nodes.len) Common.invariant("tuple constructor arity differed from its graph type");
        try self.prepareConstructorChildrenAtNodes(items, item_nodes);
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, item_nodes, 0..) |item, item_node, index| {
            lowered[index] = try self.lowerConstructorChildAtCell(item, DraftTypeCell.fromGraphNode(item_node));
        }
        return try self.addConstructorExprAtNode(tuple_node, .{ .tuple = try self.addExprSpan(lowered) });
    }

    fn lowerListConstructorAtNode(
        self: *BodyContext,
        items: []const checked.CheckedExprId,
        list_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const element_node = try self.graph.listElementNode(list_node);
        const item_nodes = try self.allocator.alloc(NodeId, items.len);
        defer self.allocator.free(item_nodes);
        @memset(item_nodes, element_node);
        try self.prepareConstructorChildrenAtNodes(items, item_nodes);
        const lowered = try self.allocator.alloc(DraftExprId, items.len);
        defer self.allocator.free(lowered);
        for (items, 0..) |item, index| {
            lowered[index] = try self.lowerConstructorChildAtCell(item, DraftTypeCell.fromGraphNode(element_node));
        }
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(list_node),
            .{ .list = try self.addExprSpan(lowered) },
        );
    }

    fn lowerRecordConstructorAtNode(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        record: anytype,
        record_node: NodeId,
    ) Allocator.Error!DraftExprId {
        var children = std.ArrayList(PreLoweredChild).empty;
        defer children.deinit(self.allocator);
        const child_count = record.fields.len + @as(usize, if (record.ext != null) 1 else 0);
        const child_exprs = try self.allocator.alloc(checked.CheckedExprId, child_count);
        defer self.allocator.free(child_exprs);
        const child_nodes = try self.allocator.alloc(NodeId, child_count);
        defer self.allocator.free(child_nodes);
        var child_index: usize = 0;
        if (record.ext) |ext| {
            child_exprs[child_index] = ext;
            child_nodes[child_index] = try self.instNode(self.view.bodies.expr(ext).ty);
            child_index += 1;
        }
        for (record.fields) |field| {
            child_exprs[child_index] = field.value;
            const mono_field_name = try self.builder.recordFieldName(self.view, field.label);
            child_nodes[child_index] = try self.graph.recordConstructionFieldValueNode(record_node, mono_field_name);
            child_index += 1;
        }
        try self.prepareConstructorChildrenAtNodes(child_exprs, child_nodes);
        child_index = 0;
        if (record.ext) |ext| {
            try children.append(self.allocator, .{
                .checked_expr = ext,
                .expr = try self.lowerConstructorChildAtCell(ext, DraftTypeCell.fromGraphNode(child_nodes[child_index])),
            });
            child_index += 1;
        }
        for (record.fields) |field| {
            try children.append(self.allocator, .{
                .checked_expr = field.value,
                .expr = try self.lowerConstructorChildAtCell(field.value, DraftTypeCell.fromGraphNode(child_nodes[child_index])),
            });
            child_index += 1;
        }
        return try self.lowerRecordExprAtNode(checked_expr, record, record_node, children.items);
    }

    fn omittedRecordFieldDefault(
        self: *BodyContext,
        checked_expr: checked.CheckedExprId,
        field_name: names.RecordFieldNameId,
    ) ?checked.CheckedFieldDefault {
        const wanted = self.builder.program.names.recordFieldLabelText(field_name);
        for (self.view.bodies.record_omitted_defaults) |entry| {
            if (entry.expr != checked_expr) continue;
            if (Ident.textEql(self.view.names.recordFieldLabelText(entry.field_name), wanted)) {
                return entry.default;
            }
        }
        return null;
    }

    fn recordUpdateFieldValue(
        self: *BodyContext,
        fields: []const checked.CheckedRecordExprField,
        name: names.RecordFieldNameId,
    ) Allocator.Error!?checked.CheckedExprId {
        for (fields) |field| {
            const lowered_name = try self.builder.recordFieldName(self.view, field.label);
            if (self.builder.program.names.recordFieldLabelTextEql(lowered_name, name)) return field.value;
        }
        return null;
    }

    fn lowerClosureAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        closure: anytype,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const capture_span = try self.lowerClosureCaptureExprSpan(closure.captures);
        const capture_nodes = try self.graph.arena().alloc(NodeId, capture_span.len);
        for (self.fnDefCaptureSpan(capture_span), capture_nodes) |capture, *node| {
            node.* = try self.exprTypeCell(capture.value).toGraphNode(self.graph);
        }
        const fn_id = try self.ensureClosureAtNode(expr_id, closure, request_fn_node, capture_nodes);
        const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, request_fn_node);
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_node),
            .{ .fn_def = .{
                .fn_id = fn_id,
                .captures = capture_span,
            } },
        );
    }

    fn ensureClosureAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        closure: anytype,
        request_fn_node: NodeId,
        capture_entry_guards: []const NodeId,
    ) Allocator.Error!DraftFnTarget {
        const lambda = self.view.bodies.expr(closure.lambda);
        const source_fn_ty = lambda.ty;
        if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
        const nested = try self.builder.nestedFnForExpr(
            self.view,
            self.owner_template,
            expr_id,
            self.current_fn_key,
            try self.localProcContextsDigest(),
        );
        const nested_evidence = try self.evidenceForNestedSiteAtNode(nested, expr_id, request_fn_node);
        return try self.builder.lowerDraftNestedFromContext(
            self,
            expr_id,
            nested,
            source_fn_ty,
            self.view.types.rootKey(source_fn_ty),
            request_fn_node,
            capture_entry_guards,
            nested_evidence.chain,
            nested_evidence.owned_scope,
            .exact_graph,
        );
    }

    fn lowerClosureCaptureExprSpan(self: *BodyContext, captures: []const checked.CheckedCapture) Allocator.Error!DraftSpan(DraftFnDefCapture) {
        if (captures.len == 0) return DraftSpan(DraftFnDefCapture).empty();

        var capture_values = std.ArrayList(DraftFnDefCapture).empty;
        defer capture_values.deinit(self.allocator);

        for (captures) |capture| {
            const binder = checkedCaptureBinder(self.view, capture.pattern);
            const local = self.binders.get(binder) orelse continue;
            try self.markActiveConstBinderUsed(binder);
            const cell = self.localTypeCell(local);
            try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binder), cell);
            const value = try self.addExprWithTypeCell(
                cell,
                .{ .local = local },
            );
            try capture_values.append(self.allocator, .{ .local = local, .value = value });
        }

        return try self.addFnDefCaptureSpan(capture_values.items);
    }

    fn closureFunctionType(self: *BodyContext, closure: anytype) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromNode(try self.closureFunctionNode(closure));
    }

    fn closureFunctionNode(self: *BodyContext, closure: anytype) Allocator.Error!NodeId {
        const lambda = self.view.bodies.expr(closure.lambda);
        if (lambda.data != .lambda) Common.invariant("checked closure did not point at a lambda expression");
        return try self.lambdaFunctionNode(lambda.ty, lambda.data.lambda);
    }

    fn lambdaFunctionType(self: *BodyContext, source_fn_ty: checked.CheckedTypeId, lambda: anytype) Allocator.Error!Type.TypeId {
        return try self.activeTypeFromNode(try self.lambdaFunctionNode(source_fn_ty, lambda));
    }

    fn lambdaFunctionNode(self: *BodyContext, source_fn_ty: checked.CheckedTypeId, lambda: anytype) Allocator.Error!NodeId {
        const fn_node = try self.instNode(source_fn_ty);
        const fn_nodes = try self.graph.functionNodes(fn_node);
        std.debug.assert(fn_nodes.args.len == lambda.args.len);
        for (lambda.args, fn_nodes.args) |pattern_id, arg_node| {
            try self.constrainCheckedInterfaceToCell(
                self.view.bodies.pattern(pattern_id).ty,
                DraftTypeCell.fromGraphNode(arg_node),
            );
        }
        return fn_node;
    }

    fn lowerLambdaExprAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const fn_id = try self.ensureLambdaAtNode(expr_id, request_fn_node);
        const fn_node = try self.draftFnSlotTypeNode(.{ .local = fn_id }, request_fn_node);
        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_node),
            .{ .fn_def = .{ .fn_id = fn_id } },
        );
    }

    fn ensureNestedCallableAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!void {
        self.builder.countBodyDiagnostic("nested_callable_checks");
        switch (self.view.bodies.expr(expr_id).data) {
            .lambda => {
                self.builder.countBodyDiagnostic("nested_lambdas_prepared");
                _ = try self.ensureLambdaAtNode(expr_id, request_fn_node);
            },
            .closure => |closure| {
                self.builder.countBodyDiagnostic("nested_closures_prepared");
                var capture_nodes = std.ArrayList(NodeId).empty;
                defer capture_nodes.deinit(self.allocator);
                for (closure.captures) |capture| {
                    const binder = checkedCaptureBinder(self.view, capture.pattern);
                    const local = self.binders.get(binder) orelse continue;
                    try self.markActiveConstBinderUsed(binder);
                    const cell = self.localTypeCell(local);
                    try self.constrainCheckedInterfaceToCell(checkedBinderType(self.view, binder), cell);
                    try capture_nodes.append(self.allocator, try cell.toGraphNode(self.graph));
                }
                _ = try self.ensureClosureAtNode(expr_id, closure, request_fn_node, capture_nodes.items);
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }
    }

    fn ensureNestedCallablesAtNodes(
        self: *BodyContext,
        expr_ids: []const checked.CheckedExprId,
        request_fn_nodes: []const NodeId,
    ) Allocator.Error!void {
        if (expr_ids.len != request_fn_nodes.len) Common.invariant("nested callable argument count differed from graph function arity");
        for (expr_ids, request_fn_nodes) |expr_id, request_fn_node| {
            try self.ensureNestedCallableAtNode(expr_id, request_fn_node);
        }
    }

    fn ensureLambdaAtNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!DraftFnTarget {
        const source_fn_ty = self.view.bodies.expr(expr_id).ty;
        const nested = try self.builder.nestedFnForExpr(
            self.view,
            self.owner_template,
            expr_id,
            self.current_fn_key,
            try self.localProcContextsDigest(),
        );
        const nested_evidence = try self.evidenceForNestedSiteAtNode(nested, expr_id, request_fn_node);
        return try self.builder.lowerDraftNestedFromContext(
            self,
            expr_id,
            nested,
            source_fn_ty,
            self.view.types.rootKey(source_fn_ty),
            request_fn_node,
            &.{},
            nested_evidence.chain,
            nested_evidence.owned_scope,
            .exact_graph,
        );
    }

    const NestedSiteEvidence = struct {
        chain: EvidenceChain,
        owned_scope: ?checked.DispatchScopeId,
    };

    /// Enter exactly the lexical dispatch scope recorded by checking for a
    /// nested procedure, consuming the producer-authored evidence source for
    /// that construction edge.
    fn evidenceForNestedSiteAtNode(
        self: *BodyContext,
        nested: Ast.NestedFn,
        expr_id: checked.CheckedExprId,
        request_fn_node: NodeId,
    ) Allocator.Error!NestedSiteEvidence {
        const raw_site = @intFromEnum(nested.site);
        if (raw_site >= self.view.nested_proc_sites.sites.len) {
            Common.invariant("nested function referenced a site absent from the CheckedModule procedure-site table");
        }
        const site = self.view.nested_proc_sites.sites[raw_site];
        if (!names.procedureTemplateRefEql(site.owner_template, self.owner_template) or
            site.checked_expr == null or site.checked_expr.? != expr_id)
        {
            Common.invariant("nested function site did not match its checked expression owner");
        }

        const lexical_scope: LexicalDispatchScope = switch (site.lexical_scope) {
            .root => .root,
            .generalized => |scope| .{ .generalized = scope },
        };
        const owned_scope: ?checked.DispatchScopeId = switch (site.lexical_scope) {
            .root => null,
            .generalized => |scope_id| blk: {
                const raw_scope = @intFromEnum(scope_id);
                if (raw_scope >= self.view.templates.dispatch_scopes.len) {
                    Common.invariant("nested function site referenced an unknown checked dispatch scope");
                }
                break :blk if (self.view.templates.dispatch_scopes[raw_scope].checked_expr == expr_id)
                    scope_id
                else
                    null;
            },
        };
        if (std.meta.eql(self.evidence.scope.lexical, lexical_scope)) {
            return .{
                .chain = self.evidence,
                .owned_scope = owned_scope,
            };
        }

        const scope_id = owned_scope orelse switch (site.lexical_scope) {
            .root => Common.invariant("root nested function site was lowered from a non-root evidence scope"),
            .generalized => Common.invariant("nested function site was lowered outside its checked lexical evidence scope"),
        };
        const raw_scope = @intFromEnum(scope_id);
        const scope = self.view.templates.dispatch_scopes[raw_scope];
        const params = self.view.templates.evidence_params_pool[scope.evidence_params.start .. scope.evidence_params.start + scope.evidence_params.len];
        const vector = switch (site.evidence_source) {
            .inherited => Common.invariant("nested procedure that owned a dispatch scope declared inherited evidence"),
            .checked_site => blk: {
                const start: usize = site.evidence.start;
                const len: usize = site.evidence.len;
                if (start > self.view.static_dispatch_plans.evidence_refs.len or
                    len > self.view.static_dispatch_plans.evidence_refs.len - start)
                {
                    Common.invariant("nested procedure checked evidence was outside the producer table");
                }
                break :blk try self.materializeNestedSiteEvidence(
                    self.view.static_dispatch_plans.evidence_refs[start .. start + len],
                    params,
                    request_fn_node,
                );
            },
        };
        return .{
            .chain = try enterEvidenceScope(self.builder, self.evidence, scope_id, expr_id, vector),
            .owned_scope = scope_id,
        };
    }

    fn lowerDispatchExprAtType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .call_dispatch);
        defer timing_scope.end();
        self.builder.countBodyDiagnostic("dispatch_expressions");
        const plan_id = maybe_plan orelse Common.invariant("checked dispatch expression reached Monotype without a dispatch plan");
        const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
        var direct_parametric_low_level: ?can.CIR.Expr.LowLevel = null;
        var direct_graph_call = false;
        switch (plan.resolution) {
            .direct_closed => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                switch (node.target.kind) {
                    .procedure => |procedure| switch (procedure.runtime_target) {
                        .low_level => |op| return try self.lowerClosedDirectLowLevelDispatch(
                            checked_ret_ty,
                            plan,
                            op,
                            expected_ret_cell,
                        ),
                        .procedure => return try self.lowerClosedDirectProcedureDispatch(
                            checked_ret_ty,
                            plan,
                            direct.evidence,
                            procedure,
                            expected_ret_cell,
                        ),
                        .intrinsic, .graph_participating => {},
                    },
                    .local_proc => direct_graph_call = true,
                    .structural => {},
                }
            },
            .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                switch (node.target.kind) {
                    .procedure => |procedure| switch (procedure.runtime_target) {
                        .low_level => |op| direct_parametric_low_level = op,
                        .procedure => direct_graph_call = true,
                        .intrinsic, .graph_participating => {},
                    },
                    .local_proc => direct_graph_call = true,
                    .structural => {},
                }
            },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .evidence_dependent, .structural, .@"unreachable", .checked_error => {},
        }
        const callable_plan = switch (self.dispatchRuntimePlan(plan)) {
            .callable => |value| value,
            .crash => |reason| {
                const message = dispatchCrashMessage(reason);
                return try self.addExprWithTypeCell(expected_ret_cell, .{ .crash = try self.addStringLiteral(message) });
            },
        };
        const plan_args = callable_plan.operands;
        const expected_ret_ty: ?Type.TypeId = switch (expected_ret_cell) {
            .sealed => |ty| ty,
            .graph_node => null,
        };
        const expected_ret_node = try expected_ret_cell.toGraphNode(self.graph);

        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        var callable_node = try call_ctx.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            self,
            checked_ret_ty,
            expected_ret_node,
            .expression_lowering,
        );
        const resolution = self.evidenceResolution(plan) orelse
            Common.invariant("runtime method call had no CheckedCallResolution evidence");
        switch (resolution) {
            .target => |initial_lookup| {
                if (direct_parametric_low_level == null and !direct_graph_call) {
                    const target_node = try self.methodTargetNodeFromPlan(initial_lookup, &call_ctx, plan.callable_ty);
                    try relateFunctionRequestInterface(self.graph, target_node, callable_node);
                    if (try self.generatedIteratorMethodRequestNode(
                        initial_lookup,
                        target_node,
                        callable_node,
                        plan_args,
                    )) |private_node| {
                        callable_node = private_node;
                    }
                }
            },
            .structural => {},
        }
        const callsite_intrinsic = switch (resolution) {
            .target => |lookup| self.callsiteIntrinsicForMethodTarget(lookup.target),
            .structural => null,
        };
        if (callsite_intrinsic) |intrinsic| {
            if (plan.result_mode != .value) {
                Common.invariant("call-site intrinsic dispatch had a non-value result mode");
            }
            return try self.lowerCallsiteIntrinsicAtCallableNode(
                intrinsic,
                plan.expr,
                plan.callable_ty,
                .{ .dispatch = plan_args },
                callable_node,
                expected_ret_ty,
            );
        }
        const callable_graph = switch (self.graph.content(callable_node)) {
            .func => |function| function,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function graph node"),
        };
        var pre_lowered = std.ArrayList(PreLoweredOperand).empty;
        defer pre_lowered.deinit(self.allocator);
        for (plan_args, 0..) |operand, index| switch (operand) {
            .checked_expr => |expr| {
                try self.relateExprAtNode(expr, callable_graph.args[index]);
            },
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => {},
        };
        for (plan_args, 0..) |operand, index| switch (operand) {
            .checked_expr => |expr| try self.ensureNestedCallableAtNode(expr, callable_graph.args[index]),
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => {},
        };
        if (try self.lowerDispatchWithUninhabitedArgument(
            plan_args,
            callable_graph.args,
            expected_ret_cell,
        )) |uninhabited| return uninhabited;
        for (plan_args, 0..) |operand, index| switch (operand) {
            .checked_expr => |expr| {
                const lowered = try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(callable_graph.args[index]));
                try pre_lowered.append(self.allocator, .{ .index = index, .expr = lowered });
            },
            .generated_interpolation_iter,
            .generated_numeral,
            .generated_quote,
            => {},
        };
        const plan_ret_node = callable_graph.ret;
        // `dispatchTarget` raises the "dispatch plan had no method owner" invariant
        // when the receiver never grounded to a concrete owner and the result mode
        // is not a structural dispatch. That is only reachable inside a bare
        // polymorphic function value never called at a concrete type—e.g.
        // evaluating `run` itself for `run : a -> a where [a.go : a -> a]`.
        // Checking classified such dispatches (`unreachable_dispatch`, or a
        // `checked_error` for reported missing methods); both emit an ordinary
        // Roc runtime crash and never return a dispatch result. A genuinely
        // reachable ownerless dispatch was rejected at check time.
        const resolved = switch (self.evidenceResolution(plan) orelse
            Common.invariant("CheckedStaticDispatchCallPlan had no MethodTarget or StructuralDerivation")) {
            .target => |lookup| lookup,
            .structural => |derivation| return switch (derivation) {
                .equality => try self.lowerStructuralEqualityAtNode(plan, callable_node, self, pre_lowered.items),
                .hash => try self.lowerStructuralHashAtNode(plan, callable_node, self, pre_lowered.items),
                .parser, .encoder => try self.deferStructuralSerializationAtNode(
                    plan,
                    callable_node,
                    try call_ctx.instNode(plan.dispatcher_ty),
                    pre_lowered.items,
                ),
                .map => |map_plan| blk: {
                    const callable_mono_ty = try call_ctx.resolvedTypeViewForNode(callable_node);
                    const plan_ret_ty = self.builder.functionShape(callable_mono_ty, "checked structural map plan had a non-function type").ret;
                    break :blk try self.lowerStructuralMap("map", plan, map_plan, callable_mono_ty, plan_ret_ty, self, pre_lowered.items);
                },
                .map_effectful => |map_plan| blk: {
                    const callable_mono_ty = try call_ctx.resolvedTypeViewForNode(callable_node);
                    const plan_ret_ty = self.builder.functionShape(callable_mono_ty, "checked structural map! plan had a non-function type").ret;
                    break :blk try self.lowerStructuralMap("map!", plan, map_plan, callable_mono_ty, plan_ret_ty, self, pre_lowered.items);
                },
            },
        };
        const checked_result_node = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
            try self.freshInstNode(checked_ret_ty)
        else
            try self.lowerTypeNode(checked_ret_ty);
        _ = try checkedMonoRequestNode(self.graph, checked_result_node, plan_ret_node);
        if (direct_parametric_low_level) |op| {
            const args = try self.lowerDispatchOperandsAtNodes(
                plan_args,
                callable_graph.args,
                pre_lowered.items,
            );
            const call_ret_cell = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
                DraftTypeCell.fromGraphNode(plan_ret_node)
            else
                expected_ret_cell;
            const call_expr = try self.addExprWithTypeCell(call_ret_cell, .{ .low_level = .{
                .op = op,
                .args = args,
            } });
            // Only equality/hash result modes inspect the result type; a
            // `.value` low-level result may still be an unresolved open row
            // (e.g. an open error union) with no Monotype view yet.
            return switch (plan.result_mode) {
                .value, .parser_for, .encoder_for, .map, .map_effectful => call_expr,
                .equality, .hash => try self.applyDispatchResultMode(
                    plan.result_mode,
                    call_expr,
                    try self.activeTypeFromNode(plan_ret_node),
                ),
            };
        }
        const call_data = if (direct_graph_call)
            try self.lowerResolvedDirectDispatchAtNode(plan, resolved, callable_node, self, pre_lowered.items)
        else
            try self.lowerResolvedDispatchAtNode(plan, resolved, callable_node, self, pre_lowered.items);
        const call_ret_cell = if (try self.graph.containsGeneratedPrivate(plan_ret_node))
            DraftTypeCell.fromGraphNode(plan_ret_node)
        else
            expected_ret_cell;
        const call_expr = try self.addExprWithTypeCell(
            call_ret_cell,
            call_data,
        );
        return switch (plan.result_mode) {
            .value, .parser_for, .encoder_for, .map, .map_effectful => call_expr,
            .equality, .hash => blk: {
                const ret_ty = try self.activeTypeFromNode(plan_ret_node);
                if (expected_ret_ty) |expected| {
                    const expected_ty = try self.activeTypeFromType(expected);
                    if (!self.sameType(expected_ty, ret_ty)) Common.invariant("checked dispatch expression lowered at a type different from its call operand type");
                }
                break :blk try self.applyDispatchResultMode(plan.result_mode, call_expr, ret_ty);
            },
        };
    }

    fn lowerClosedDirectLowLevelDispatch(
        self: *BodyContext,
        _: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        op: can.CIR.Expr.LowLevel,
        expected_ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const callable_ty = blk: {
            var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
            defer timing_scope.end();
            break :blk try self.builder.lowerType(self.view, plan.callable_ty);
        };
        const function = self.builder.functionShape(callable_ty, "checked closed direct low-level call had a non-function type");
        const operands = plan.argsSlice(self.view.static_dispatch_plans);
        if (operands.len != self.builder.program.types.span(function.args).len) {
            Common.invariant("checked closed direct low-level call argument arity differed from its callable type");
        }

        switch (expected_ret_cell) {
            .sealed => |expected| if (!self.sameType(expected, function.ret)) {
                Common.invariant("checked closed direct low-level call result differed from its expected type");
            },
            .graph_node => |expected| try relateRequestComponent(
                self.graph,
                expected,
                try self.activeNodeFromType(function.ret),
            ),
        }

        const lowered = switch (try self.lowerClosedDispatchOperandsAtTypes(
            operands,
            self.builder.program.types.span(function.args),
            expected_ret_cell,
        )) {
            .args => |args| args,
            .uninhabited => |expr| return expr,
        };
        const call = try self.addExprWithTypeCell(expected_ret_cell, .{ .low_level = .{
            .op = op,
            .args = lowered,
        } });
        return try self.applyDispatchResultMode(plan.result_mode, call, function.ret);
    }

    fn lowerClosedDispatchOperandsAtTypes(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        arg_types: anytype,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!ClosedDispatchOperands {
        if (operands.len != GuardedList.borrowLen(arg_types)) {
            Common.invariant("closed dispatch argument arity differed from its sealed callable type");
        }
        const stable_types = try GuardedList.dupe(self.allocator, Type.TypeId, arg_types);
        defer self.allocator.free(stable_types);

        for (stable_types, 0..) |arg_ty, uninhabited_index| {
            if (!try self.typeIsProvenUninhabited(arg_ty)) continue;
            const checked_arg = switch (operands[uninhabited_index]) {
                .checked_expr => |expr| expr,
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => Common.invariant("compiler-generated dispatch operand had an uninhabited sealed type"),
            };
            const prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
            defer self.allocator.free(prior);
            for (operands[0..uninhabited_index], stable_types[0..uninhabited_index], prior) |operand, ty, *out| {
                out.* = try self.lowerDispatchOperandAtType(operand, ty);
            }
            const scrutinee = try self.lowerUninhabitedScrutinee(checked_arg, arg_ty);
            var result = try self.zeroBranchMatchAtTypeCell(scrutinee, ret_cell);
            var index = uninhabited_index;
            while (index > 0) {
                index -= 1;
                result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                    .bind = try self.addPatWithTypeCell(.{ .sealed = stable_types[index] }, .wildcard),
                    .value = prior[index],
                    .rest = result,
                } });
            }
            return .{ .uninhabited = result };
        }

        const reserved = try self.reserveExprSpan(operands.len);
        errdefer self.draft.expr_ids.shrinkRetainingCapacity(reserved.span.start);
        for (operands, stable_types, 0..) |operand, ty, index| {
            self.draft.setReservedExprSpanItem(
                reserved,
                index,
                try self.lowerDispatchOperandAtType(operand, ty),
            );
        }
        return .{ .args = reserved.span };
    }

    fn lowerClosedDirectProcedureDispatch(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        evidence_id: static_dispatch.EvidenceNodeId,
        procedure: static_dispatch.ProcedureMethodTarget,
        expected_ret_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const callable_ty = blk: {
            var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
            defer timing_scope.end();
            break :blk try self.builder.lowerType(self.view, plan.callable_ty);
        };
        const function = self.builder.functionShape(callable_ty, "checked closed direct procedure call had a non-function type");
        const operands = plan.argsSlice(self.view.static_dispatch_plans);
        if (operands.len != self.builder.program.types.span(function.args).len) {
            Common.invariant("checked closed direct procedure call argument arity differed from its callable type");
        }
        try self.constrainTypeToMono(checked_ret_ty, function.ret);
        switch (expected_ret_cell) {
            .sealed => |expected| if (!self.sameType(expected, function.ret)) {
                Common.invariant("checked closed direct procedure call result differed from its expected type");
            },
            .graph_node => |expected| try relateRequestComponent(
                self.graph,
                expected,
                try self.activeNodeFromType(function.ret),
            ),
        }

        const callable_node = try self.activeNodeFromType(callable_ty);
        const lowered = switch (try self.lowerClosedDispatchOperandsAtNode(
            operands,
            callable_node,
            expected_ret_cell,
        )) {
            .args => |args| args,
            .uninhabited => |expr| return expr,
        };
        const evidence_node = self.view.static_dispatch_plans.evidenceNode(evidence_id);
        const lookup = self.methodLookupForResolvedTarget(evidence_node.target);
        const direct_key = ClosedDirectCallIdentity{
            .callable = checkedTypeAddress(self.view, plan.callable_ty),
            .evidence = evidence_id,
            .method_scope = self.method_scope.key,
        };
        const slot = if (self.draft.closed_direct_specializations.get(direct_key)) |existing| blk: {
            if (existing.draft_spec) |raw_spec| {
                if (raw_spec >= self.draft.template_specs.items.len) {
                    Common.invariant("closed direct call cache referenced a missing draft specialization");
                }
                const spec = &self.draft.template_specs.items[raw_spec];
                if (spec.state != .deferred and !runtimeDemandGuardFrameSetsEql(
                    spec.runtime_demand_guard_frames,
                    try self.runtimeDemandGuardFrameAddresses(),
                )) {
                    try self.draft.template_spec_reuses.append(self.allocator, .{
                        .spec = raw_spec,
                        .prefix_proof = try self.currentRuntimeImpossibilityProof(null),
                    });
                }
            }
            break :blk existing.slot;
        } else blk: {
            const evidence_vector = switch (try self.evidenceForDispatchTarget(plan)) {
                .resolved => |evidence| evidence,
                .synthesize => Common.invariant("closed direct procedure call had specialization-dependent evidence"),
            };
            const source_fn_ty = lookup.target.callable_ty;
            const created = try self.builder.lowerDraftTemplateFromContext(
                self,
                procedure.template,
                source_fn_ty,
                lookup.view.types.rootKey(source_fn_ty),
                callable_node,
                evidence_vector,
                .resolved,
                .independent_roots,
            );
            const draft_spec: ?u32 = switch (created) {
                .local => |local| switch (local) {
                    .draft => |draft_fn| self.draft.template_spec_by_fn.get(draft_fn) orelse
                        Common.invariant("closed direct call created a draft function without a specialization record"),
                    .final => null,
                },
                .imported => null,
            };
            try self.draft.closed_direct_specializations.put(direct_key, .{
                .slot = created,
                .draft_spec = draft_spec,
            });
            break :blk created;
        };
        const call = try self.addExprWithTypeCell(expected_ret_cell, .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(slot),
            .args = lowered,
            .captures = try self.methodTargetCaptureSpan(lookup),
        } });
        return try self.applyDispatchResultMode(plan.result_mode, call, function.ret);
    }

    const ClosedDispatchOperands = union(enum) {
        args: DraftSpan(DraftExprId),
        uninhabited: DraftExprId,
    };

    fn lowerClosedDispatchOperandsAtNode(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        callable_node: NodeId,
        expected_ret_cell: DraftTypeCell,
    ) Allocator.Error!ClosedDispatchOperands {
        const function = blk: {
            var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .type_graph);
            defer timing_scope.end();
            break :blk try self.graph.functionNodes(callable_node);
        };
        if (operands.len != function.args.len) {
            Common.invariant("closed dispatch argument arity differed from its callable type");
        }
        try self.prepareDispatchOperandsAtNodes(operands, function.args, &.{});
        if (try self.lowerDispatchWithUninhabitedArgument(
            operands,
            function.args,
            expected_ret_cell,
        )) |uninhabited| {
            return .{ .uninhabited = uninhabited };
        }
        return .{ .args = try self.lowerPreparedDispatchOperandsAtNodes(
            operands,
            function.args,
            &.{},
        ) };
    }

    fn lowerDispatchWithUninhabitedArgument(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
        arg_nodes: []const NodeId,
        ret_cell: DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        if (operands.len != arg_nodes.len) {
            Common.invariant("dispatch argument arity differed while lowering an uninhabited invocation");
        }
        for (operands, arg_nodes, 0..) |operand, arg_node, uninhabited_index| {
            if (!try self.nodeIsProvenUninhabited(arg_node)) continue;
            const checked_arg = switch (operand) {
                .checked_expr => |expr| expr,
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => Common.invariant("compiler-generated dispatch operand had an uninhabited type"),
            };

            const prior = try self.allocator.alloc(DraftExprId, uninhabited_index);
            defer self.allocator.free(prior);
            for (operands[0..uninhabited_index], arg_nodes[0..uninhabited_index], 0..) |prior_operand, prior_node, index| {
                prior[index] = switch (prior_operand) {
                    .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(prior_node)),
                    .generated_interpolation_iter,
                    .generated_numeral,
                    .generated_quote,
                    => try self.lowerDispatchOperandAtType(prior_operand, try self.activeTypeFromNode(prior_node)),
                };
            }

            const arg_cell = DraftTypeCell.fromGraphNode(arg_node);
            const scrutinee = try self.lowerUninhabitedScrutineeAtTypeCell(checked_arg, arg_cell);
            var result = try self.zeroBranchMatchAtTypeCell(scrutinee, ret_cell);
            var index = uninhabited_index;
            while (index > 0) {
                index -= 1;
                const prior_cell = DraftTypeCell.fromGraphNode(arg_nodes[index]);
                result = try self.addExprWithTypeCell(ret_cell, .{ .let_ = .{
                    .bind = try self.addPatWithTypeCell(prior_cell, .wildcard),
                    .value = prior[index],
                    .rest = result,
                } });
            }
            return result;
        }
        return null;
    }

    fn applyDispatchResultMode(
        self: *BodyContext,
        mode: static_dispatch.StaticDispatchResultMode,
        expr: DraftExprId,
        expr_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return switch (mode) {
            .value => expr,
            .parser_for => expr,
            .encoder_for => expr,
            .map => expr,
            .map_effectful => expr,
            .equality => |eq| if (eq.negated) blk: {
                if (!self.typeHasBuiltinOwner(expr_ty, .bool)) Common.invariant("checked equality dispatch returned a non-Bool value");
                break :blk try self.lowLevelExpr(.bool_not, &.{expr}, expr_ty);
            } else expr,
            // A resolved `to_hash` dispatch returns its Hasher result directly.
            .hash => expr,
        };
    }

    fn lowerNumeralCall(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const result = try self.lowerNumeralCallRaw(checked_ret_ty, maybe_plan, target_ty);
        return try self.unwrapNumeralResult(result.call, result.try_ty, target_ty);
    }

    const NumeralCall = struct {
        call: DraftExprId,
        try_ty: Type.TypeId,
    };

    fn lowerNumeralCallRaw(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        target_ty: Type.TypeId,
    ) Allocator.Error!NumeralCall {
        const plan_id = maybe_plan orelse Common.invariant("checked from_numeral expression reached Monotype without a dispatch plan");
        const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
        if (plan.result_mode != .value) Common.invariant("checked from_numeral plan had a non-value result mode");
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);

        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        const callable_node = try call_ctx.instantiateNumeralPlanCallNode(plan.callable_ty, self, checked_ret_ty, target_ty, plan_args);

        const resolved = self.dispatchTarget(plan) orelse
            Common.invariant("checked from_numeral dispatch unexpectedly resolved to structural equality");

        const target_node = try self.methodTargetNodeFromPlan(resolved, &call_ctx, plan.callable_ty);
        try relateFunctionRequestInterface(self.graph, target_node, callable_node);
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const ret_ty = try self.activeTypeFromNode(fn_nodes.ret);

        const call_expr = try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_nodes.ret),
            try self.lowerResolvedDispatchAtNode(plan, resolved, callable_node, self, &.{}),
        );
        return .{ .call = call_expr, .try_ty = ret_ty };
    }

    fn lowerNumeralRootBody(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const expr = self.view.bodies.expr(expr_id);
        const plan = switch (expr.data) {
            .numeral => |numeral| numeral.plan,
            .str_from_quote => |quote| quote.plan,
            .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("literal conversion root did not point at a conversion expression"),
        };
        const ok_tag = self.monoTagByText(try_ty, "Ok");
        const ok_payloads = self.builder.program.types.span(ok_tag.payloads);
        if (ok_payloads.len != 1) Common.invariant("numeral conversion root Try.Ok did not carry one payload");
        const result = try self.lowerNumeralCallRaw(expr.ty, plan, GuardedList.at(ok_payloads, 0));
        if (!self.sameType(result.try_ty, try_ty)) {
            Common.invariant("numeral conversion root type differed from the from_numeral result type");
        }
        return result.call;
    }

    fn restoredNumeralConst(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!?DraftExprId {
        const root = self.view.compile_time_roots.lookupNumeralRootByExpr(expr_id) orelse return null;
        return switch (root.payload) {
            .const_node => |node| try self.restoreConstNodeAtType(self.view, self.view, node, ty),
            .pending => null,
            .fn_value, .expect => Common.invariant("numeral conversion root stored a non-constant payload"),
        };
    }

    /// Produce a numeric literal's constant—the ONE place in the compiler
    /// that turns a literal's exact digits into a bit pattern, always for
    /// the instantiated Monotype primitive. A custom numeric target keeps its
    /// real user-defined `from_numeral` dispatch call instead.
    fn lowerNumeralExpr(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        numeral: checked.CheckedNumeralData,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const primitive = switch (self.builder.shapeContent(target_ty)) {
            .primitive => |p| p,
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return try self.lowerNumeralCall(checked_ret_ty, numeral.plan, target_ty),
        };
        const data = (try self.numeralBits(numeral.literal, primitive)) orelse blk: {
            // A value that does not fit its concrete integer or Dec target (a
            // literal forced to an unrepresentable type after monomorphization;
            // checking reports these, so this is unreachable for error-free
            // programs) matches the generic from_numeral behavior: a runtime
            // crash on the conversion's Err branch.
            const msg = try self.addStringLiteral("invalid numeric literal");
            break :blk BodyExprData{ .crash = msg };
        };
        return try self.addExpr(.{ .ty = target_ty, .data = data });
    }

    /// Specialize a checked quote conversion without guessing its target at
    /// the checked boundary. Primitive Str receives the literal directly;
    /// every custom target follows the explicit from_quote dispatch plan.
    fn lowerQuoteExpr(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        quote: checked.CheckedQuoteData,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        switch (self.builder.shapeContent(target_ty)) {
            .primitive => |primitive| {
                if (primitive != .str) {
                    // Checking reports this literal-conversion mismatch. Keep
                    // error-path lowering total, matching raw strings and
                    // unrepresentable numerals, so diagnostics can complete.
                    return try self.addExpr(.{
                        .ty = target_ty,
                        .data = .{ .crash = try self.addStringLiteral("invalid string literal") },
                    });
                }
                return try self.lowerQuoteValue(quote.literal, target_ty);
            },
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return try self.lowerNumeralCall(checked_ret_ty, quote.plan, target_ty),
        }
    }

    /// A numeric literal's scalar constant at a builtin numeric primitive—
    /// the payload both the expression and pattern lowerers map into their
    /// own IR node flavor.
    const NumeralScalarBits = union(enum) {
        int: can.CIR.IntValue,
        f32: f32,
        f64: f64,
        dec: builtins.dec.RocDec,
    };

    /// The literal's bit pattern at a builtin primitive, from its exact
    /// digits—the ONE place that turns digits into bits: integers by limb
    /// assembly with a fit check, Dec by exact scale shift, floats by
    /// correctly-rounded decimal→binary conversion (total: out-of-range
    /// rounds toward ±inf). Null when an integer or Dec target cannot
    /// represent the exact value; each caller maps null to its own failure
    /// mode (expression: runtime crash node; pattern: never-matching branch).
    /// Checking reports every such literal, so null is unreachable for
    /// error-free programs.
    fn numeralScalarBits(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        primitive: Type.Primitive,
    ) Allocator.Error!?NumeralScalarBits {
        const exact = self.view.module_env.exactNumeral(literal);
        return switch (primitive) {
            .u8, .u16, .u32, .u64, .u128, .i8, .i16, .i32, .i64, .i128 => blk: {
                const bits = exact_numeral.intBits(exact, numeralTargetFromPrimitive(primitive)) orelse break :blk null;
                break :blk switch (bits) {
                    .i128 => |value| .{ .int = .{ .bytes = @bitCast(value), .kind = .i128 } },
                    .u128 => |value| .{ .int = .{ .bytes = @bitCast(value), .kind = .u128 } },
                };
            },
            .f32 => .{ .f32 = try exact_numeral.floatBits(f32, self.allocator, exact) },
            .f64 => .{ .f64 = try exact_numeral.floatBits(f64, self.allocator, exact) },
            .dec => blk: {
                const num = (try exact_numeral.decBits(self.allocator, exact)) orelse break :blk null;
                break :blk .{ .dec = .{ .num = num } };
            },
            // A non-numeric target cannot represent any numeral. Checking
            // reports every such literal, so this is reachable only while
            // running a program with reported errors; the caller's failure
            // mapping (crash node / never-matching branch) is the behavior.
            .bool, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => null,
        };
    }

    /// The expression flavor of `numeralScalarBits`; null passes through for
    /// the caller's crash-node mapping.
    fn numeralBits(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        primitive: Type.Primitive,
    ) Allocator.Error!?BodyExprData {
        const bits = (try self.numeralScalarBits(literal, primitive)) orelse return null;
        return switch (bits) {
            .int => |value| .{ .int_lit = value },
            .f32 => |value| .{ .frac_f32_lit = value },
            .f64 => |value| .{ .frac_f64_lit = value },
            .dec => |value| .{ .dec_lit = value },
        };
    }

    /// Materialize a string literal as the `Str` argument of a `from_quote`
    /// dispatch call.
    fn lowerQuoteValue(
        self: *BodyContext,
        literal: checked.CheckedStringLiteralId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .str_lit = try self.lowerStringLiteral(literal) },
        });
    }

    fn lowerNumeralValue(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const backing_ty = self.builder.namedBackingType(ty) orelse
            Common.invariant("checked from_numeral argument was not the Numeral nominal type");
        const literal_tag = self.monoTagByText(backing_ty, "Literal");
        const payloads = self.builder.program.types.span(literal_tag.payloads);
        if (payloads.len != 1) Common.invariant("Numeral Literal tag must have one record payload");

        const record_expr = try self.lowerNumeralRecord(literal, GuardedList.at(payloads, 0));
        const backing_expr = try self.addExpr(.{
            .ty = backing_ty,
            .data = .{ .tag = .{
                .name = literal_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{record_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn lowerNumeralRecord(
        self: *BodyContext,
        literal: can.ModuleEnv.NumeralLiteral,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (!literal.isMaterialized()) {
            Common.invariant("checked from_numeral argument literal was not materialized");
        }
        const field_span = switch (self.builder.shapeContent(ty)) {
            .record => |span| span,
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("Numeral Literal payload was not a record"),
        };
        const field_count: usize = @intCast(field_span.len);
        const lowered = try self.allocator.alloc(DraftFieldExpr, field_count);
        defer self.allocator.free(lowered);
        const fields = try GuardedList.dupe(self.allocator, Type.Field, self.builder.program.types.fieldSpan(field_span));
        defer self.allocator.free(fields);

        const before = self.view.module_env.numeralDigitsBefore(literal);
        const after = self.view.module_env.numeralDigitsAfter(literal);
        for (0..field_count) |i| {
            const field = fields[i];
            const label = self.builder.program.names.recordFieldLabelText(field.name);
            const value = if (Ident.textEql(label, "is_negative"))
                try self.boolLiteral(literal.isNegative(), field.ty)
            else if (Ident.textEql(label, "digits_before_pt"))
                try self.lowerU8List(before, field.ty)
            else if (Ident.textEql(label, "digits_after_pt"))
                try self.lowerU8List(after, field.ty)
            else if (Ident.textEql(label, "digits_after_pt_count"))
                try self.intLiteralExpr(literal.after_decimal_digit_count, field.ty)
            else
                Common.invariant("Numeral record contained an unexpected field");
            lowered[i] = .{ .name = field.name, .value = value };
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .record = try self.addFieldExprSpan(lowered) },
        });
    }

    fn lowerU8List(
        self: *BodyContext,
        values: []const u8,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const elem_ty = switch (self.builder.shapeContent(ty)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => Common.invariant("Numeral digit field was not a List(U8)"),
        };
        const items = try self.allocator.alloc(DraftExprId, values.len);
        defer self.allocator.free(items);
        for (values, 0..) |value, i| {
            items[i] = try self.intLiteralExpr(value, elem_ty);
        }
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .list = try self.addExprSpan(items) },
        });
    }

    fn unwrapNumeralResult(
        self: *BodyContext,
        result: DraftExprId,
        try_ty: Type.TypeId,
        target_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ok_tag = self.monoTagByText(try_ty, "Ok");
        const err_tag = self.monoTagByText(try_ty, "Err");
        const ok_payloads = self.builder.program.types.span(ok_tag.payloads);
        const err_payloads = self.builder.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1) Common.invariant("Try.Ok from from_numeral did not carry one payload");
        if (!self.sameType(GuardedList.at(ok_payloads, 0), target_ty)) {
            Common.invariant("Try.Ok from from_numeral carried a type different from the literal target type");
        }

        const ok_local = try self.addLocal(self.builder.symbols.fresh(), target_ty);
        const ok_payload_pat = try self.bindPat(ok_local, target_ty);
        const ok_pat = try self.addPat(.{ .ty = try_ty, .data = .{ .tag = .{
            .name = ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_body = try self.localExpr(ok_local, target_ty);

        const err_payload_pats = try self.allocator.alloc(DraftPatId, err_payloads.len);
        defer self.allocator.free(err_payload_pats);
        for (0..GuardedList.borrowLen(err_payloads)) |i| {
            const payload_ty = GuardedList.at(err_payloads, i);
            err_payload_pats[i] = try self.addPat(.{ .ty = payload_ty, .data = .wildcard });
        }
        const err_pat = try self.addPat(.{ .ty = try_ty, .data = .{ .tag = .{
            .name = err_tag.name,
            .payloads = try self.addPatSpan(err_payload_pats),
        } } });
        const msg = try self.addStringLiteral("invalid numeric literal");
        const err_body = try self.addExpr(.{ .ty = target_ty, .data = .{ .crash = msg } });

        const branches = [_]DraftBranch{
            .{ .pat = ok_pat, .body = ok_body },
            .{ .pat = err_pat, .body = err_body },
        };
        return try self.addExpr(.{ .ty = target_ty, .data = .{ .match_ = .{
            .scrutinee = result,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn monoTagByText(self: *BodyContext, ty: Type.TypeId, text: []const u8) Type.Tag {
        return self.monoTagByTextOptional(ty, text) orelse Common.invariant("expected tag was absent from monotype tag union");
    }

    fn monoTagByName(self: *BodyContext, ty: Type.TypeId, name: names.TagNameId) Type.Tag {
        const tags = switch (self.builder.shapeContent(ty)) {
            .tag_union => |span| self.builder.program.types.tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("expected tag belonged to a non-union monotype type"),
        };
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (tag.name == name) return tag;
        }
        Common.invariant("expected tag id was absent from monotype tag union");
    }

    fn monoTagByTextOptional(self: *BodyContext, ty: Type.TypeId, text: []const u8) ?Type.Tag {
        return switch (self.builder.shapeContent(ty)) {
            .tag_union => |span| {
                const tags = self.builder.program.types.tagSpan(span);
                for (0..GuardedList.borrowLen(tags)) |index| {
                    const tag = GuardedList.at(tags, index);
                    if (Ident.textEql(self.builder.program.names.tagLabelText(tag.name), text)) return tag;
                }
                return null;
            },
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => null,
        };
    }

    fn typeHasBuiltinOwner(self: *BodyContext, ty: Type.TypeId, owner: static_dispatch.BuiltinOwner) bool {
        return switch (methodOwnerFromType(&self.builder.program.types, ty) orelse return false) {
            .builtin => |actual| actual == owner,
            .nominal => false,
        };
    }

    fn setPayloadType(self: *BodyContext, ty: Type.TypeId) ?Type.TypeId {
        if (!self.typeHasBuiltinOwner(ty, .set)) return null;
        const named = switch (self.builder.program.types.get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("builtin Set type was not a named monotype"),
        };
        const args = self.builder.program.types.span(named.args);
        if (args.len != 1) Common.invariant("builtin Set type had an unexpected arity");
        return GuardedList.at(args, 0);
    }

    const DictEntryShape = struct {
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
    };

    fn dictEntryShape(self: *BodyContext, ty: Type.TypeId) ?DictEntryShape {
        if (!self.typeHasBuiltinOwner(ty, .dict)) return null;
        const named = switch (self.builder.program.types.get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("builtin Dict type was not a named monotype"),
        };
        const args = self.builder.program.types.span(named.args);
        if (args.len != 2) Common.invariant("builtin Dict type had an unexpected arity");
        return .{ .key_ty = GuardedList.at(args, 0), .value_ty = GuardedList.at(args, 1) };
    }

    fn listType(self: *BodyContext, elem_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.builder.program.types.add(.{ .list = elem_ty });
    }

    fn tupleType(self: *BodyContext, item_tys: []const Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.builder.program.types.add(.{ .tuple = try self.builder.program.types.addSpan(item_tys) });
    }

    fn lowerSetFromList(
        self: *BodyContext,
        set_ty: Type.TypeId,
        list_ty: Type.TypeId,
        list_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(set_ty, "from_list");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{list_ty}, set_ty);
        const from_list_fn = self.builder.functionShape(callable_mono_ty, "Set.from_list target method was not a function");
        const arg_tys = self.builder.program.types.span(from_list_fn.args);
        if (arg_tys.len != 1) Common.invariant("Set.from_list target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), list_ty)) Common.invariant("Set.from_list argument type differed from generated List type");
        if (!self.sameType(from_list_fn.ret, set_ty)) Common.invariant("Set.from_list return type differed from Set type");

        return try self.addExpr(.{
            .ty = set_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{list_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerSetToList(
        self: *BodyContext,
        set_ty: Type.TypeId,
        list_ty: Type.TypeId,
        set_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(set_ty, "to_list");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{set_ty}, list_ty);
        const to_list_fn = self.builder.functionShape(callable_mono_ty, "Set.to_list target method was not a function");
        const arg_tys = self.builder.program.types.span(to_list_fn.args);
        if (arg_tys.len != 1) Common.invariant("Set.to_list target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), set_ty)) Common.invariant("Set.to_list argument type differed from Set type");
        if (!self.sameType(to_list_fn.ret, list_ty)) Common.invariant("Set.to_list return type differed from generated List type");

        return try self.addExpr(.{
            .ty = list_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{set_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerDictWithCapacity(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        capacity_expr: DraftExprId,
        capacity_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(dict_ty, "with_capacity");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{capacity_ty}, dict_ty);
        const with_capacity_fn = self.builder.functionShape(callable_mono_ty, "Dict.with_capacity target method was not a function");
        const arg_tys = self.builder.program.types.span(with_capacity_fn.args);
        if (arg_tys.len != 1) Common.invariant("Dict.with_capacity target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), capacity_ty)) Common.invariant("Dict.with_capacity argument type differed from generated capacity type");
        if (!self.sameType(with_capacity_fn.ret, dict_ty)) Common.invariant("Dict.with_capacity return type differed from Dict type");

        return try self.addExpr(.{
            .ty = dict_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{capacity_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerDictInsert(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_expr: DraftExprId,
        key_expr: DraftExprId,
        value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(dict_ty, "insert");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{ dict_ty, key_ty, value_ty }, dict_ty);
        const insert_fn = self.builder.functionShape(callable_mono_ty, "Dict.insert target method was not a function");
        const arg_tys = self.builder.program.types.span(insert_fn.args);
        if (arg_tys.len != 3) Common.invariant("Dict.insert target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), dict_ty)) Common.invariant("Dict.insert dict argument type differed from Dict type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), key_ty)) Common.invariant("Dict.insert key argument type differed from key type");
        if (!self.sameType(GuardedList.at(arg_tys, 2), value_ty)) Common.invariant("Dict.insert value argument type differed from value type");
        if (!self.sameType(insert_fn.ret, dict_ty)) Common.invariant("Dict.insert return type differed from Dict type");

        return try self.addExpr(.{
            .ty = dict_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ dict_expr, key_expr, value_expr }),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerDictToList(
        self: *BodyContext,
        dict_ty: Type.TypeId,
        list_ty: Type.TypeId,
        dict_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(dict_ty, "to_list");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{dict_ty}, list_ty);
        const to_list_fn = self.builder.functionShape(callable_mono_ty, "Dict.to_list target method was not a function");
        const arg_tys = self.builder.program.types.span(to_list_fn.args);
        if (arg_tys.len != 1) Common.invariant("Dict.to_list target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), dict_ty)) Common.invariant("Dict.to_list argument type differed from Dict type");
        if (!self.sameType(to_list_fn.ret, list_ty)) Common.invariant("Dict.to_list return type differed from generated List type");

        return try self.addExpr(.{
            .ty = list_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{dict_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn parseScalarMethodName(self: *BodyContext, ty: Type.TypeId) ?[]const u8 {
        if (self.typeHasBuiltinOwner(ty, .bool)) return "parse_bool";
        if (self.typeHasBuiltinOwner(ty, .str)) return "parse_str";
        if (self.typeHasBuiltinOwner(ty, .u8)) return "parse_u8";
        if (self.typeHasBuiltinOwner(ty, .i8)) return "parse_i8";
        if (self.typeHasBuiltinOwner(ty, .u16)) return "parse_u16";
        if (self.typeHasBuiltinOwner(ty, .i16)) return "parse_i16";
        if (self.typeHasBuiltinOwner(ty, .u32)) return "parse_u32";
        if (self.typeHasBuiltinOwner(ty, .i32)) return "parse_i32";
        if (self.typeHasBuiltinOwner(ty, .u64)) return "parse_u64";
        if (self.typeHasBuiltinOwner(ty, .i64)) return "parse_i64";
