    /// The shapes a derived codec reads out of a dict: always its value, plus
    /// its key when the key needs its own codec rather than the key-string
    /// methods. Every walk over a dict's codec-reachable shapes goes through
    /// here so the rule lives in one place.
    fn dictCodecShapes(self: *BodyContext, dict: DictEntryShape, buf: *[2]Type.TypeId) []const Type.TypeId {
        buf[0] = dict.value_ty;
        if (self.dictKeyIsStringRendered(dict.key_ty)) return buf[0..1];
        buf[1] = dict.key_ty;
        return buf[0..2];
    }

    /// Whether a dict key renders as a key string, which is what the
    /// `parse_key_*`/`encode_key_*` methods read and write. Any other key is
    /// read by its own codec behind `parse_key_start`/`encode_key_start`.
    fn dictKeyIsStringRendered(self: *BodyContext, ty: Type.TypeId) bool {
        return self.parseDictKeyMethodName(ty) != null or self.dictKeyUnitTags(ty) != null;
    }

    fn dictKeyUnitTags(self: *BodyContext, ty: Type.TypeId) ?Type.Span {
        switch (self.builder.program.types.get(ty)) {
            .named => |named| if (named.kind != .alias) return null,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => {},
        }
        const tags_span = switch (self.builder.shapeContent(ty)) {
            .tag_union => |span| span,
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
        };
        const tags = self.builder.program.types.tagSpan(tags_span);
        if (tags.len == 0) return null;
        for (0..GuardedList.borrowLen(tags)) |index| {
            const tag = GuardedList.at(tags, index);
            if (self.builder.program.types.span(tag.payloads).len != 0) return null;
        }
        return tags_span;
    }

    fn dispatchResultMonoType(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const ret_node = try self.dispatchResultTypeNode(checked_ret_ty, maybe_plan, expected_ret_ty);
        if (expected_ret_ty) |expected| return expected;
        return try self.activeTypeFromNode(ret_node);
    }

    fn dispatchResultTypeNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_ty: ?Type.TypeId,
    ) Allocator.Error!NodeId {
        return try self.dispatchResultTypeNodeInPhase(
            checked_ret_ty,
            maybe_plan,
            if (expected_ret_ty) |expected| try self.activeNodeFromType(expected) else null,
            .expression_lowering,
        );
    }

    fn dispatchResultTypeNodeInPhase(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
    ) Allocator.Error!NodeId {
        const plan_id = maybe_plan orelse Common.invariant("checked dispatch expression reached Monotype without a dispatch plan");
        const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
        if (try self.closedDirectGraphFreeResultNode(checked_ret_ty, plan, expected_ret_node)) |ret_node| {
            return ret_node;
        }
        return switch (self.dispatchRuntimePlan(plan)) {
            .callable => |callable_plan| try self.callableDispatchResultTypeNodeInPhase(
                checked_ret_ty,
                callable_plan,
                expected_ret_node,
                phase,
            ),
            .crash => expected_ret_node orelse
                Common.invariant("rejected dispatch reached result type lookup without a contextual result cell"),
        };
    }

    /// Consume a CheckedModule-proved closed direct call without constructing a
    /// dispatch graph. The producer's runtime category is authoritative:
    /// ordinary procedures and exact low-level operations have a sealed
    /// checked callable interface, while graph-participating operations and
    /// parametric/local/evidence-dependent calls continue through the relation
    /// path below.
    fn closedDirectGraphFreeResultNode(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
        expected_ret_node: ?NodeId,
    ) Allocator.Error!?NodeId {
        const ret_ty = (try self.closedDirectGraphFreeResultType(checked_ret_ty, plan)) orelse return null;
        const ret_node = try self.activeNodeFromType(ret_ty);
        if (expected_ret_node) |expected| {
            try relateRequestComponent(self.graph, ret_node, expected);
        }
        return ret_node;
    }

    /// Return the sealed result type stored in a closed direct call's
    /// producer-authored callable type. No specialization graph node is
    /// created here.
    fn closedDirectGraphFreeResultType(
        self: *BodyContext,
        _: checked.CheckedTypeId,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!?Type.TypeId {
        const direct = switch (plan.resolution) {
            .direct_closed => |direct| direct,
            .direct_pending,
            .direct_parametric,
            .evidence_dependent,
            .structural,
            .checked_error,
            .@"unreachable",
            => return null,
        };
        const evidence = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
        const procedure = switch (evidence.target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => return null,
        };
        switch (procedure.runtime_target) {
            .intrinsic, .graph_participating => return null,
            .procedure, .low_level => {},
        }

        const callable_ty = try self.builder.lowerType(self.view, plan.callable_ty);
        const function = self.builder.functionShape(
            callable_ty,
            "checked closed direct call had a non-function callable type",
        );
        return function.ret;
    }

    fn graphFreeResultTypeForExpr(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!?Type.TypeId {
        const expr = self.view.bodies.expr(expr_id);
        const plan_id = switch (expr.data) {
            .dispatch_call => |plan| plan,
            .interpolation => |interpolation| interpolation.plan,
            .type_dispatch_call => |plan| plan,
            .method_eq => |plan| plan,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        } orelse return null;
        const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
        return try self.closedDirectGraphFreeResultType(expr.ty, plan);
    }

    fn callableDispatchResultTypeNodeInPhase(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        callable_plan: CallableDispatchPlan,
        expected_ret_node: ?NodeId,
        phase: DispatchInstantiationPhase,
    ) Allocator.Error!NodeId {
        const plan = callable_plan.plan;
        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        const plan_args = callable_plan.operands;
        var callable_node = try call_ctx.instantiateCallableDispatchPlanCallNodeFromCallerAtNode(
            callable_plan,
            self,
            checked_ret_ty,
            expected_ret_node,
            phase,
        );
        const resolution = self.evidenceResolution(plan) orelse
            Common.invariant("runtime method result had no CheckedCallResolution evidence");
        switch (resolution) {
            .target => |lookup| {
                const target_node = try self.methodTargetNodeFromPlan(lookup, &call_ctx, plan.callable_ty);
                try relateFunctionRequestInterface(self.graph, target_node, callable_node);
                if (try self.generatedIteratorMethodRequestNode(
                    lookup,
                    target_node,
                    callable_node,
                    plan_args,
                )) |private_node| {
                    callable_node = private_node;
                }
            },
            .structural => {},
        }
        return switch (self.graph.content(callable_node)) {
            .func => |function| function.ret,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => Common.invariant("checked dispatch plan had a non-function graph node"),
        };
    }

    /// Materialize checked evidence refs into self-contained spec evidence,
    /// substituting `constraint(k)` refs from this context's own chain. The
    /// result feeds a callee specialization's vector.
    fn materializeEvidence(self: *BodyContext, refs: []const static_dispatch.CheckedEvidence) Allocator.Error![]const SpecEvidence {
        return self.materializeEvidenceForPurpose(refs, .body_lowering);
    }

    fn materializeEvidenceForPurpose(
        self: *BodyContext,
        refs: []const static_dispatch.CheckedEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        if (refs.len == 0) return &.{};
        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, refs.len);
        for (refs, 0..) |ref, i| {
            out[i] = try self.materializeEvidenceRef(ref, purpose);
        }
        return out;
    }

    /// Materialize the checker-authored recipe for one nested-procedure
    /// construction. Callable-derived entries name the corresponding checked
    /// evidence-param path explicitly; every other entry is already a final
    /// checked resolution.
    fn materializeNestedSiteEvidence(
        self: *BodyContext,
        refs: []const static_dispatch.CheckedEvidence,
        params: []const static_dispatch.EvidenceParamRecord,
        callable_node: NodeId,
    ) Allocator.Error![]const SpecEvidence {
        if (refs.len != params.len) {
            Common.invariant("nested procedure evidence recipe length differed from its checked scope");
        }
        if (refs.len == 0) return &.{};

        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, refs.len);
        for (refs, params, 0..) |ref, param, i| {
            out[i] = switch (ref.resolution) {
                .from_callable => blk: {
                    const path = self.view.templates.evidenceParamPath(param);
                    if (path.len == 0) {
                        Common.invariant("nested procedure callable evidence named a pathless checked parameter");
                    }
                    const component_node = try self.walkEvidencePathNode(self.view, callable_node, path) orelse
                        Common.invariant("nested procedure callable evidence path did not match its checked request");
                    break :blk try self.synthesizeComponentEvidenceAtNode(
                        self.view,
                        param.method,
                        param.structural,
                        component_node,
                    );
                },
                .direct, .constraint, .structural, .checked_error, .unreachable_value => try self.materializeEvidenceRef(ref, .body_lowering),
            };
        }
        return out;
    }

    fn materializeEvidenceRef(
        self: *BodyContext,
        ref: static_dispatch.CheckedEvidence,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!SpecEvidence {
        switch (ref.resolution) {
            .direct => |node_id| {
                const node = self.view.static_dispatch_plans.evidenceNode(node_id);
                return .{ .target = try self.materializeEvidenceTarget(node, purpose) };
            },
            .constraint => |constraint_ref| {
                const entry = self.evidence.at(constraint_ref) orelse
                    Common.invariant("checked evidence reference was absent from its lexical chain");
                return entry;
            },
            .structural => |evidence| return .{ .structural = evidence.derivation },
            .from_callable => Common.invariant("callable-derived checked evidence escaped a nested procedure construction recipe"),
            .checked_error => return .checked_error,
            .unreachable_value => return .unreachable_value,
        }
    }

    fn materializeEvidenceTarget(
        self: *BodyContext,
        node: static_dispatch.EvidenceNode,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!*const SpecEvidenceTarget {
        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.create(SpecEvidenceTarget);
        const lookup = try self.methodLookupForEvidencePurpose(
            self.methodLookupForResolvedTarget(node.target),
            purpose,
        );
        out.* = .{
            .view = lookup.view,
            .target = node.target,
            .instantiation = switch (node.instantiation) {
                .monomorphic => null,
                .callable => |callable_ty| .{ .view = self.view, .callable_ty = callable_ty },
            },
            .local_proc_context = lookup.local_proc_context,
            .nested = switch (node.nested) {
                .resolved => .{ .resolved = try self.materializeEvidenceForPurpose(
                    self.view.static_dispatch_plans.nestedEvidence(node),
                    purpose,
                ) },
                .from_callable => .synthesize,
            },
        };
        return out;
    }

    fn materializeConstFnEvidence(self: *BodyContext, fn_value: check.ConstStore.ConstFn) Allocator.Error!EvidenceChain {
        const frames = fn_value.evidence_frames;
        const head = fn_value.evidence_frame_head orelse
            Common.invariant("stored function evidence did not declare a head frame");
        if (frames.len == 0 or head != frames.len - 1) {
            Common.invariant("stored function evidence head did not name its final frame");
        }
        const owner = templateForConstFnDef(fn_value.fn_def);
        const owner_view = self.builder.moduleForDigest(names.procTemplateModuleDigest(owner));
        var cursor: usize = 0;
        const arena = self.builder.evidence_arena.allocator();
        const restored = try arena.alloc(EvidenceChain, frames.len);
        for (frames, 0..) |frame, index| {
            if (frame.roots_start != cursor) {
                Common.invariant("stored function evidence frame roots were not contiguous");
            }
            const vector = try self.materializeConstFnEvidenceVector(fn_value.evidence, &cursor, frame.roots_len);
            const scope: LexicalDispatchScope = switch (frame.scope()) {
                .root => .root,
                .generalized => |scope_id| .{ .generalized = @enumFromInt(scope_id) },
            };
            if (index == 0) {
                if (scope != .root or frame.parent != null) {
                    Common.invariant("stored function evidence did not begin at the checked root scope");
                }
                restored[index] = rootEvidence(owner, vector);
                continue;
            }
            if (scope == .root or frame.parent == null or frame.parent.? != index - 1) {
                Common.invariant("stored function evidence frame did not name its immediate lexical parent");
            }
            const scope_id = scope.generalized;
            const raw_scope = @intFromEnum(scope_id);
            if (raw_scope >= owner_view.templates.dispatch_scopes.len) {
                Common.invariant("stored function evidence referenced an unknown checked scope");
            }
            const scope_record = owner_view.templates.dispatch_scopes[raw_scope];
            const expected_parent: LexicalDispatchScope = if (scope_record.parent) |parent|
                .{ .generalized = parent }
            else
                .root;
            if (!std.meta.eql(restored[index - 1].scope.lexical, expected_parent)) {
                Common.invariant("stored function evidence parent differed from the checked lexical scope");
            }
            restored[index] = .{
                .scope = .{ .owner = owner, .lexical = scope },
                .vector = vector,
                .parent = &restored[index - 1],
            };
        }
        if (cursor != fn_value.evidence.len) {
            Common.invariant("stored function evidence contained unreferenced nodes");
        }
        const expected_head: LexicalDispatchScope = switch (fn_value.fn_def) {
            .nested => |nested| blk: {
                const raw_site = @intFromEnum(nested.site);
                if (raw_site >= owner_view.nested_proc_sites.sites.len) {
                    Common.invariant("stored nested function referenced an unknown checked site");
                }
                const site = owner_view.nested_proc_sites.sites[raw_site];
                if (!names.procedureTemplateRefEql(site.owner_template, owner)) {
                    Common.invariant("stored nested function site belonged to a different checked template");
                }
                break :blk switch (site.lexical_scope) {
                    .root => .root,
                    .generalized => |scope_id| .{ .generalized = scope_id },
                };
            },
            .local_template, .imported_template, .local_hosted, .imported_hosted, .checked_generated, .parser_runtime, .encoder_for_runtime => .root,
        };
        if (!std.meta.eql(restored[head].scope.lexical, expected_head)) {
            Common.invariant("stored function evidence head differed from its checked nested site scope");
        }
        return restored[head];
    }

    fn materializeConstFnEvidenceVector(
        self: *BodyContext,
        nodes: []const check.ConstStore.ConstFnEvidence,
        cursor: *usize,
        count: u32,
    ) Allocator.Error![]const SpecEvidence {
        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, count);
        for (out) |*entry| {
            if (cursor.* >= nodes.len) Common.invariant("stored function evidence ended before its declared vector length");
            const stored = nodes[cursor.*];
            cursor.* += 1;
            entry.* = switch (stored) {
                .target => |target| blk: {
                    const materialized = try arena.create(SpecEvidenceTarget);
                    const nested: NestedSpecEvidence = switch (target.nested) {
                        .resolved => |resolved| blk_nested: {
                            const nested_start = cursor.*;
                            const nested_vector = try self.materializeConstFnEvidenceVector(nodes, cursor, resolved.count);
                            if (cursor.* - nested_start != resolved.subtree_len) {
                                Common.invariant("stored function nested evidence length differed from its subtree");
                            }
                            break :blk_nested .{ .resolved = nested_vector };
                        },
                        .from_callable => .synthesize,
                    };
                    materialized.* = .{
                        .view = self.builder.moduleForDigest(target.view),
                        .target = target.method,
                        .instantiation = if (target.instantiation) |instantiation| .{
                            .view = self.builder.moduleForDigest(instantiation.view),
                            .callable_ty = instantiation.callable_ty,
                        } else null,
                        .local_proc_context = switch (target.method.kind) {
                            .local_proc => |local| blk_context: {
                                const context_view = self.builder.moduleForDigest(target.view);
                                const context_id = try self.localProcContextId(context_view, local.binder, local.expr);
                                _ = self.validateLocalProcContext(
                                    context_id,
                                    self.builder.moduleForDigest(target.view).key.bytes,
                                    local.binder,
                                    local.expr,
                                    local.context_anchor,
                                );
                                break :blk_context context_id;
                            },
                            .procedure, .structural => null,
                        },
                        .nested = nested,
                    };
                    break :blk .{ .target = materialized };
                },
                .structural => |kind| .{ .structural = kind },
                .unreachable_value => .unreachable_value,
                .checked_error => .checked_error,
            };
        }
        return out;
    }

    /// Evidence vector for the constrained scheme instantiated at `expr` (a
    /// value use resolved in this context's module), or empty when the use
    /// carries no requirements.
    fn evidenceForUseSite(self: *BodyContext, expr: checked.CheckedExprId) Allocator.Error![]const SpecEvidence {
        return self.evidenceForUseSiteForPurpose(expr, .body_lowering);
    }

    fn evidenceForUseSiteForPurpose(
        self: *BodyContext,
        expr: checked.CheckedExprId,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error![]const SpecEvidence {
        const refs = self.view.static_dispatch_plans.siteEvidence(expr) orelse return &.{};
        return self.materializeEvidenceForPurpose(refs, purpose);
    }

    /// Evidence vector for a dispatch plan's chosen target (the target's own
    /// requirements): a direct plan carries it as the evidence node's nested
    /// refs; a constraint plan's edge-supplied target carries it materialized.
    fn evidenceForDispatchTarget(self: *BodyContext, plan: static_dispatch.StaticDispatchCallPlan) Allocator.Error!SpecEvidenceVector {
        switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                return switch (node.nested) {
                    .resolved => .{ .resolved = try self.materializeEvidence(self.view.static_dispatch_plans.nestedEvidence(node)) },
                    .from_callable => .synthesize,
                };
            },
            .evidence_dependent => |constraint_ref| {
                const entry = self.evidence.at(constraint_ref) orelse
                    Common.invariant("method target evidence was absent from its lexical chain");
                return switch (entry) {
                    .target => |target| switch (target.nested) {
                        .resolved => |nested| .{ .resolved = nested },
                        .synthesize => .synthesize,
                    },
                    .structural, .unreachable_value, .checked_error => Common.invariant("method target selected non-target checked evidence"),
                };
            },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("method target evidence requested for a non-target resolution"),
        }
    }

    /// Evidence vector for an iterator dispatch call's chosen target,
    /// mirroring `evidenceForDispatchTarget` for `IteratorDispatchCall`s.
    fn evidenceForIteratorCall(self: *BodyContext, call: static_dispatch.IteratorDispatchCall) Allocator.Error!SpecEvidenceVector {
        switch (call.resolution) {
            .direct_closed, .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                return switch (node.nested) {
                    .resolved => .{ .resolved = try self.materializeEvidence(self.view.static_dispatch_plans.nestedEvidence(node)) },
                    .from_callable => .synthesize,
                };
            },
            .evidence_dependent => |constraint_ref| {
                const entry = self.evidence.at(constraint_ref) orelse
                    Common.invariant("iterator target evidence was absent from its lexical chain");
                return switch (entry) {
                    .target => |target| switch (target.nested) {
                        .resolved => |nested| .{ .resolved = nested },
                        .synthesize => .synthesize,
                    },
                    .structural, .unreachable_value, .checked_error => Common.invariant("iterator target selected non-target checked evidence"),
                };
            },
            .direct_pending => Common.invariant("unfinalized iterator direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("iterator target evidence requested for a non-target resolution"),
        }
    }

    /// A consumed evidence resolution: a concrete target or the checker's
    /// structural decision.
    const EvidenceResolved = union(enum) {
        target: MethodLookup,
        structural: static_dispatch.StructuralDerivation,
    };

    /// The plan's checked or edge-supplied resolution. Null is reserved for
    /// checked-error and explicitly unreachable dispatches.
    fn evidenceResolution(self: *BodyContext, plan: static_dispatch.StaticDispatchCallPlan) ?EvidenceResolved {
        switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                var lookup = self.methodLookupForResolvedTarget(node.target);
                lookup.instantiation = switch (node.instantiation) {
                    .monomorphic => null,
                    .callable => |callable_ty| .{ .view = self.view, .callable_ty = callable_ty },
                };
                return .{ .target = lookup };
            },
            .evidence_dependent => |constraint_ref| {
                const entry = self.evidence.at(constraint_ref) orelse
                    Common.invariant("dispatch resolution evidence was absent from its lexical chain");
                return switch (entry) {
                    .target => |target| .{ .target = .{
                        .view = target.view,
                        .target = target.target,
                        .instantiation = target.instantiation,
                        .local_proc_context = target.local_proc_context,
                    } },
                    .structural => |derivation| .{ .structural = derivation },
                    // Unreachable and checked-error dispatches crash before
                    // target resolution.
                    .unreachable_value, .checked_error => null,
                };
            },
            .structural => |derivation| return .{ .structural = derivation },
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .checked_error, .@"unreachable" => return null,
        }
    }

    const DispatchCrashReason = enum { unreachable_value, checked_error };

    fn dispatchCrashMessage(reason: DispatchCrashReason) []const u8 {
        return switch (reason) {
            .unreachable_value => "dispatch on a value that can never exist",
            .checked_error => "method dispatch failed to check",
        };
    }

    /// A checked dispatch whose resolution names a callable target or structural
    /// derivation. Callable, dispatcher, and operand type instantiation accepts
    /// this wrapper instead of a raw plan. A rejected non-returning dispatch
    /// takes `DispatchRuntimePlan.crash`, so Monotype emits an ordinary Roc
    /// runtime crash without instantiating the rejected callable's type.
    const CallableDispatchPlan = struct {
        plan: static_dispatch.StaticDispatchCallPlan,
        operands: []const static_dispatch.StaticDispatchOperand,
    };

    /// The required gate before any dispatch type instantiation. `crash` means
    /// the dispatch emits an ordinary Roc runtime crash and returns no value.
    const DispatchRuntimePlan = union(enum) {
        callable: CallableDispatchPlan,
        crash: DispatchCrashReason,
    };

    fn dispatchRuntimePlan(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) DispatchRuntimePlan {
        if (self.dispatchCrashReason(plan.resolution)) |reason| return .{ .crash = reason };
        return .{ .callable = .{
            .plan = plan,
            .operands = plan.argsSlice(self.view.static_dispatch_plans),
        } };
    }

    /// A stored generated parser/encoder runtime exists only after compile-time
    /// evaluation successfully consumed its constructor dispatch. ConstStore
    /// intentionally stores no evidence vector for these generated runtimes;
    /// their explicit runtime function tag is the producer-owned proof that a
    /// checked constraint plan is callable. Rejected plan-level resolutions can
    /// never provide that proof.
    fn requireStoredRuntimeCallableDispatchPlan(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) CallableDispatchPlan {
        switch (plan.resolution) {
            .checked_error, .@"unreachable" => Common.invariant("stored generated runtime had a rejected dispatch plan"),
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .direct_closed, .direct_parametric, .evidence_dependent, .structural => {},
        }
        return .{
            .plan = plan,
            .operands = plan.argsSlice(self.view.static_dispatch_plans),
        };
    }

    /// Whether checking decided this is a rejected non-returning dispatch: its
    /// dispatcher is a value no edge can supply (unreachable), or checking
    /// rejected the requirement (a reported missing method). Monotype emits an
    /// ordinary Roc runtime crash instead of a dispatch call for both cases.
    fn dispatchCrashReason(self: *BodyContext, resolution: static_dispatch.CheckedCallResolution) ?DispatchCrashReason {
        return switch (resolution) {
            .@"unreachable" => .unreachable_value,
            .checked_error => .checked_error,
            .evidence_dependent => |constraint_ref| if (self.evidence.at(constraint_ref)) |entry| switch (entry) {
                .unreachable_value => .unreachable_value,
                .checked_error => .checked_error,
                .target, .structural => null,
            } else Common.invariant("dispatch runtime evidence was absent from its lexical chain"),
            .direct_pending => Common.invariant("unfinalized direct call reached Monotype"),
            .direct_closed, .direct_parametric, .structural => null,
        };
    }

    fn dispatchTarget(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
    ) ?MethodLookup {
        const resolution = self.evidenceResolution(plan) orelse
            Common.invariant("dispatch plan reached monotype lowering without a resolution");
        return switch (resolution) {
            .target => |lookup| lookup,
            .structural => null,
        };
    }

    fn methodLookupForResolvedTarget(
        self: *BodyContext,
        target: static_dispatch.MethodTarget,
    ) MethodLookup {
        return switch (target.kind) {
            .procedure => |procedure| .{
                .view = self.builder.moduleForDigest(names.procTemplateModuleDigest(procedure.template)),
                .target = target,
            },
            .local_proc => .{
                .view = self.view,
                .target = target,
            },
            .structural => Common.invariant("structural method registry result reached callable checked evidence"),
        };
    }

    fn methodTargetContext(
        self: *BodyContext,
        lookup: MethodLookup,
    ) Allocator.Error!BodyContext {
        const owner_template = switch (lookup.target.kind) {
            .procedure => |procedure| procedure.template,
            .local_proc => |local| self.localMethodOwnerTemplate(lookup, local),
            .structural => Common.invariant("structural method registry result has no callable body context"),
        };
        return BodyContext.initWithMethodScope(self.allocator, self.builder, lookup.view, self.method_scope, owner_template, self.graph, self.draft);
    }

    fn localMethodOwnerTemplate(
        self: *BodyContext,
        lookup: MethodLookup,
        local: static_dispatch.LocalProcedureMethodTarget,
    ) names.ProcTemplate {
        if (lookup.local_proc_context) |context_id| {
            return self.validateLocalProcContext(
                context_id,
                lookup.view.key.bytes,
                local.binder,
                local.expr,
                local.context_anchor,
            ).owner_template;
        }
        if (moduleBytesEqual(lookup.view.key.bytes, self.view.key.bytes)) return self.owner_template;
        Common.invariant("cross-module local method type lookup had no declaration context");
    }

    fn methodTargetNodeFromPlan(
        self: *BodyContext,
        lookup: MethodLookup,
        plan_ctx: *BodyContext,
        plan_callable_ty: checked.CheckedTypeId,
    ) Allocator.Error!NodeId {
        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instantiateTargetFromPlanNode(lookup.target.callable_ty, plan_ctx, plan_callable_ty);
        if (lookup.instantiation) |instantiation| {
            var edge_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, instantiation.view, self.method_scope, self.owner_template, self.graph, self.draft);
            defer edge_ctx.deinit();
            const edge_node = try edge_ctx.instNode(instantiation.callable_ty);
            try relateFunctionRequestInterface(self.graph, target_node, edge_node);
        }
        return target_node;
    }

    fn generatedIteratorMethodRequestNode(
        self: *BodyContext,
        lookup: MethodLookup,
        public_target_node: NodeId,
        request_node: NodeId,
        operands: []const static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!?NodeId {
        const procedure = self.iteratorProcedureForMethodTarget(lookup.target) orelse return null;
        const checked_args = try self.checkedExprDispatchOperands(operands) orelse return null;
        defer self.allocator.free(checked_args);
        const private_node = (try self.generatedIteratorFunctionNode(
            procedure,
            public_target_node,
            request_node,
            checked_args,
        )) orelse return null;
        try self.graph.registerRequestSourceInterface(private_node, public_target_node);
        try relateFunctionRequestInterface(self.graph, public_target_node, private_node);
        return private_node;
    }

    fn generatedIteratorPlanRequestNode(
        self: *BodyContext,
        lookup: MethodLookup,
        public_target_node: NodeId,
        request_node: NodeId,
        operands: []const static_dispatch.IteratorDispatchOperand,
    ) Allocator.Error!?NodeId {
        const procedure = self.iteratorProcedureForMethodTarget(lookup.target) orelse return null;
        const checked_args = try self.checkedExprIteratorDispatchOperands(operands) orelse return null;
        defer self.allocator.free(checked_args);
        const private_node = (try self.generatedIteratorFunctionNode(
            procedure,
            public_target_node,
            request_node,
            checked_args,
        )) orelse return null;
        try self.graph.registerRequestSourceInterface(private_node, public_target_node);
        try relateFunctionRequestInterface(self.graph, public_target_node, private_node);
        return private_node;
    }

    fn checkedExprDispatchOperands(
        self: *BodyContext,
        operands: []const static_dispatch.StaticDispatchOperand,
    ) Allocator.Error!?[]checked.CheckedExprId {
        const checked_args = try self.allocator.alloc(checked.CheckedExprId, operands.len);
        errdefer self.allocator.free(checked_args);
        for (operands, checked_args) |operand, *checked_arg| {
            checked_arg.* = switch (operand) {
                .checked_expr => |expr| expr,
                .generated_interpolation_iter,
                .generated_numeral,
                .generated_quote,
                => {
                    self.allocator.free(checked_args);
                    return null;
                },
            };
        }
        return checked_args;
    }

    fn checkedExprIteratorDispatchOperands(
        self: *BodyContext,
        operands: []const static_dispatch.IteratorDispatchOperand,
    ) Allocator.Error!?[]checked.CheckedExprId {
        const checked_args = try self.allocator.alloc(checked.CheckedExprId, operands.len);
        errdefer self.allocator.free(checked_args);
        for (operands, checked_args) |operand, *checked_arg| {
            checked_arg.* = switch (operand) {
                .checked_expr => |expr| expr,
                .loop_iterator_state => {
                    self.allocator.free(checked_args);
                    return null;
                },
            };
        }
        return checked_args;
    }

    fn methodTargetMonoTypeFromArgs(
        self: *BodyContext,
        lookup: MethodLookup,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        if (self.frozen_sealed_emission) {
            if (try self.frozenCodecCallableFromArgs(lookup, arg_tys, ret_ty)) |prepared| return prepared;
            Common.invariant("sealed structural codec requested an unprepared callable");
        }
        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        return try target_ctx.instantiateTargetCallTypeFromMonoArgs(lookup.target.callable_ty, arg_tys, ret_ty);
    }

    fn methodLookupForTypeName(
        self: *BodyContext,
        owner_ty: Type.TypeId,
        method_name: []const u8,
    ) Allocator.Error!MethodLookup {
        const owner = methodOwnerFromType(&self.builder.program.types, owner_ty) orelse
            Common.invariant("parser format type did not have a method owner");
        return try self.withLocalProcContext((try self.builder.lookupMethodTargetByName(self.method_scope, owner, method_name)) orelse
            Common.invariant("checked method registry is missing parser format method"));
    }

    fn withLocalProcContext(self: *BodyContext, lookup: MethodLookup) Allocator.Error!MethodLookup {
        var contextual = lookup;
        switch (lookup.target.kind) {
            .local_proc => |local| {
                const context_id = lookup.local_proc_context orelse
                    try self.localProcContextId(lookup.view, local.binder, local.expr);
                _ = self.validateLocalProcContext(
                    context_id,
                    lookup.view.key.bytes,
                    local.binder,
                    local.expr,
                    local.context_anchor,
                );
                contextual.local_proc_context = context_id;
            },
            .procedure, .structural => if (lookup.local_proc_context != null) {
                Common.invariant("non-local method target carried a local declaration context");
            },
        }
        return contextual;
    }

    fn methodLookupForEvidencePurpose(
        self: *BodyContext,
        lookup: MethodLookup,
        purpose: EvidenceMaterializationPurpose,
    ) Allocator.Error!MethodLookup {
        return switch (purpose) {
            .body_lowering => try self.withLocalProcContext(lookup),
            .specialization_interface => blk: {
                if (lookup.local_proc_context != null) {
                    Common.invariant("checked specialization-interface evidence unexpectedly carried a draft-local context");
                }
                break :blk lookup;
            },
        };
    }

    fn validateLocalProcContext(
        self: *BodyContext,
        context_id: DraftLocalProcContextId,
        module: [32]u8,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
        context_anchor: ?checked.CheckedStatementId,
    ) LocalProcContext {
        const raw_context = @intFromEnum(context_id);
        if (raw_context >= self.draft.local_proc_contexts.items.len) {
            Common.invariant("local procedure use referenced an unknown declaration context");
        }
        const context = self.draft.local_proc_contexts.items[raw_context];
        const declaration = context.declaration;
        if (!moduleBytesEqual(declaration.module, module) or declaration.binder != binder or declaration.expr != expr) {
            Common.invariant("local procedure context belonged to a different checked declaration");
        }
        if (context_anchor) |anchor| {
            if (declaration.context_anchor == null or declaration.context_anchor.? != anchor) {
                Common.invariant("local method context belonged to a different checked declaration anchor");
            }
        }
        return context;
    }

    /// Resolve a target's requirements from its checked dispatcher paths
    /// over the concrete monomorphic callable (compiler-generated call edges
    /// only: structural-derivation component calls and builtin helper calls
    /// have no checked instantiation records).
    fn synthesizeTargetEvidence(
        self: *BodyContext,
        lookup: MethodLookup,
        template_ref: names.ProcTemplate,
        callable_mono_ty: Type.TypeId,
    ) Allocator.Error![]const SpecEvidence {
        const template = lookup.view.templates.get(template_ref.template);
        return try self.synthesizeParamsEvidence(lookup.view, template, callable_mono_ty);
    }

    /// Resolve a template's requirements from its checked dispatcher paths
    /// over the concrete monomorphic callable.
    fn synthesizeParamsEvidence(
        self: *BodyContext,
        view: ModuleView,
        template: checked.CheckedProcedureTemplate,
        callable_mono_ty: Type.TypeId,
    ) Allocator.Error![]const SpecEvidence {
        const params = view.templates.evidenceParams(&template);
        if (params.len == 0) return &.{};

        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, params.len);
        for (params, 0..) |param, i| {
            const path = view.templates.evidenceParamPath(param);
            const component_ty = if (path.len == 0)
                try self.defaultedEvidenceParamType(param)
            else
                try self.walkEvidencePath(view, callable_mono_ty, path) orelse {
                    Common.invariant("compiler-generated method dispatcher path did not match its callable type");
                };
            out[i] = try self.synthesizeComponentEvidence(view, param.method, param.structural, component_ty);
        }
        return out;
    }

    fn defaultedEvidenceParamType(
        self: *BodyContext,
        param: static_dispatch.EvidenceParamRecord,
    ) Allocator.Error!Type.TypeId {
        const primitive = defaultedEvidenceParamPrimitive(param);
        return try self.builder.program.types.add(.{ .primitive = primitive });
    }

    fn defaultedEvidenceParamNode(
        self: *BodyContext,
        param: static_dispatch.EvidenceParamRecord,
    ) Allocator.Error!NodeId {
        const primitive = defaultedEvidenceParamPrimitive(param);
        return try self.graph.newNode(.{ .primitive = primitive });
    }

    fn defaultedEvidenceParamPrimitive(param: static_dispatch.EvidenceParamRecord) Type.Primitive {
        const phase = param.pathless_default_phase orelse
            Common.invariant("compiler-generated method edge did not contain a dispatcher path");
        const target = checked.literal_defaulting.defaultTargetForPhase(phase) orelse
            Common.invariant("checking-finalized pathless evidence param reached Monotype synthesis");
        return switch (target) {
            .dec => .dec,
            .str => .str,
        };
    }

    /// Project checker-authored dispatcher paths over the exact checked root
    /// that authored them. The returned nodes remain live across subsequent
    /// target/request relations and therefore acquire the concrete component
    /// types without re-walking the path over a differently shaped request.
    fn projectEvidenceComponentNodes(
        self: *BodyContext,
        view: ModuleView,
        params: []const static_dispatch.EvidenceParamRecord,
        target_root_node: NodeId,
    ) Allocator.Error![]NodeId {
        const out = try self.allocator.alloc(NodeId, params.len);
        errdefer self.allocator.free(out);
        for (params, 0..) |param, i| {
            const path = view.templates.evidenceParamPath(param);
            out[i] = if (path.len == 0)
                try self.defaultedEvidenceParamNode(param)
            else
                try self.walkEvidencePathNode(view, target_root_node, path) orelse {
                    Common.invariant("compiler-generated method dispatcher path did not match its checked target graph type");
                };
        }
        return out;
    }

    fn synthesizeEvidenceAtComponentNodes(
        self: *BodyContext,
        view: ModuleView,
        params: []const static_dispatch.EvidenceParamRecord,
        component_nodes: []const NodeId,
    ) Allocator.Error![]const SpecEvidence {
        if (params.len != component_nodes.len) {
            Common.invariant("projected dispatcher component count differed from its checked evidence params");
        }
        if (params.len == 0) return &.{};

        const arena = self.builder.evidence_arena.allocator();
        const out = try arena.alloc(SpecEvidence, params.len);
        for (params, component_nodes, 0..) |param, component_node, i| {
            out[i] = try self.synthesizeComponentEvidenceAtNode(
                view,
                param.method,
                param.structural,
                component_node,
            );
        }
        return out;
    }

    fn localProcEvidenceParams(
        _: *BodyContext,
        view: ModuleView,
        local: static_dispatch.LocalProcedureMethodTarget,
    ) []const static_dispatch.EvidenceParamRecord {
        const scope_id = local.dispatch_scope orelse return &.{};
        const raw_scope = @intFromEnum(scope_id);
        if (raw_scope >= view.templates.dispatch_scopes.len) {
            Common.invariant("local method target named a dispatch scope outside its checked template table");
        }
        const scope = view.templates.dispatch_scopes[raw_scope];
        if (scope.checked_expr != local.expr) {
            Common.invariant("local method target dispatch scope belonged to a different checked expression");
        }
        return view.templates.evidence_params_pool[scope.evidence_params.start .. scope.evidence_params.start + scope.evidence_params.len];
    }

    /// Graph-native counterpart of `synthesizeComponentEvidence`. Checked
    /// named/builtin owner identity and proven uninhabitedness are sufficient
    /// to select exact evidence without assigning an immutable Monotype id.
    fn synthesizeComponentEvidenceAtNode(
        self: *BodyContext,
        view: ModuleView,
        method: names.MethodNameId,
        structural: ?static_dispatch.StructuralKind,
        component_node: NodeId,
    ) Allocator.Error!SpecEvidence {
        if (self.methodOwnerFromNode(component_node)) |owner| {
            if (try self.builder.lookupMethodTarget(self.method_scope, owner, view, method)) |found| {
                if (found.target.kind == .structural) {
                    return .{ .structural = structuralDerivationWithoutMap(found.target.kind.structural) };
                }
                const arena = self.builder.evidence_arena.allocator();
                const target = try arena.create(SpecEvidenceTarget);
                const lookup = try self.withLocalProcContext(found);
                target.* = .{
                    .view = lookup.view,
                    .target = lookup.target,
                    .instantiation = null,
                    .local_proc_context = lookup.local_proc_context,
                    .nested = .synthesize,
                };
                return .{ .target = target };
            }
            if (structural) |kind| return .{ .structural = structuralDerivationWithoutMap(kind) };
            Common.invariant("compiler-generated graph component owner had no exact checked method target");
        }
        if (structural) |kind| return .{ .structural = structuralDerivationWithoutMap(kind) };
        if (try self.nodeIsProvenUninhabited(component_node)) return .unreachable_value;
        Common.invariant("compiler-generated ownerless graph component had no checked structural or uninhabited evidence");
    }

    /// Static-dispatch owner identity available directly from a live graph
    /// node. Aliases are transparent, matching `Type.Store.ownerHead`.
    fn methodOwnerFromNode(
        self: *BodyContext,
        node: NodeId,
    ) ?static_dispatch.MethodOwner {
        return switch (self.graph.content(node)) {
            .redirect => unreachable,
            .primitive => |primitive| .{ .builtin = builtinOwnerFromPrimitive(primitive) },
            .list => .{ .builtin = .list },
            .box => .{ .builtin = .box },
            .named => |named| if (named.builtin_owner) |owner|
                .{ .builtin = owner }
            else if (named.kind == .alias)
                (if (named.backing) |backing|
                    self.methodOwnerFromNode(backing.node)
                else
                    null)
            else
                .{ .nominal = .{
                    .module = named.def.module,
                    .type_name = named.def.type_name,
                    .source_decl = named.def.source_decl,
                } },
            .unresolved,
            .tuple,
            .func,
            .tag_union,
            .record,
            .empty_tag_union,
            .empty_record,
            .erased,
            .zst,
            => null,
        };
    }

    /// One synthesized requirement on a concrete component type: its method
    /// target (whose own requirements synthesize at their consumption sites),
    /// the structural implementation for ownerless shapes, or unreachable for
    /// components no value inhabits.
    fn synthesizeComponentEvidence(
        self: *BodyContext,
        view: ModuleView,
        method: names.MethodNameId,
        structural: ?static_dispatch.StructuralKind,
        component_ty: Type.TypeId,
    ) Allocator.Error!SpecEvidence {
        if (methodOwnerFromType(&self.builder.program.types, component_ty)) |owner| {
            if (try self.builder.lookupMethodTarget(self.method_scope, owner, view, method)) |found| {
                if (found.target.kind == .structural) {
                    return .{ .structural = structuralDerivationWithoutMap(found.target.kind.structural) };
                }
                const arena = self.builder.evidence_arena.allocator();
                const target = try arena.create(SpecEvidenceTarget);
                const lookup = try self.withLocalProcContext(found);
                target.* = .{
                    .view = lookup.view,
                    .target = lookup.target,
                    .instantiation = null,
                    .local_proc_context = lookup.local_proc_context,
                    .nested = .synthesize,
                };
                return .{ .target = target };
            }
            if (structural) |kind| return .{ .structural = structuralDerivationWithoutMap(kind) };
            Common.invariant("compiler-generated component owner had no exact checked method target");
        }
        if (structural) |kind| return .{ .structural = structuralDerivationWithoutMap(kind) };
        if (self.typeIsClosedEmptyTagUnion(component_ty)) return .unreachable_value;
        Common.invariant("compiler-generated ownerless component had no checked structural or uninhabited evidence");
    }

    fn structuralDerivationWithoutMap(kind: static_dispatch.StructuralKind) static_dispatch.StructuralDerivation {
        return switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser => .parser,
            .encoder => .encoder,
            .map, .map_effectful => Common.invariant("compiler-generated evidence cannot synthesize a derived map payload selection"),
        };
    }

    /// Walk a checked dispatcher path over a concrete monomorphic type.
    /// Null when the mono shape diverges from the checked scheme; callers treat
    /// that as an invariant because checked dispatcher paths are exact.
    fn walkEvidencePath(
        self: *BodyContext,
        view: ModuleView,
        start_ty: Type.TypeId,
        path: []const static_dispatch.EvidencePathStep,
    ) Allocator.Error!?Type.TypeId {
        var ty = start_ty;
        var path_index: usize = 0;
        while (path_index < path.len) {
            const path_step = path[path_index];
            path_index += 1;
            const content = self.builder.program.types.get(ty);
            switch (path_step.stepKind()) {
                .fn_arg => switch (content) {
                    .func => |func| {
                        const args = self.builder.program.types.span(func.args);
                        if (path_step.data >= args.len) return null;
                        ty = GuardedList.at(args, path_step.data);
                    },
                    .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => return null,
                },
                .fn_ret => switch (content) {
                    .func => |func| ty = func.ret,
                    .primitive, .named, .record, .tuple, .tag_union, .list, .box, .erased, .zst => return null,
                },
                .alias_arg, .nominal_arg => switch (content) {
                    .named => |named| {
                        const args = self.builder.program.types.span(named.args);
                        if (path_step.data >= args.len) return null;
                        ty = GuardedList.at(args, path_step.data);
                    },
                    // Builtin containers erase to dedicated nodes: their
                    // single type argument is the payload.
                    .list, .box => |payload| {
                        if (path_step.data != 0) return null;
                        ty = payload;
                    },
                    .primitive, .record, .tuple, .tag_union, .func, .erased, .zst => return null,
                },
                .alias_backing, .nominal_backing => switch (content) {
                    .named => |named| {
                        const backing = named.backing orelse return null;
                        ty = backing.ty;
                    },
                    .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
                },
                .tuple_elem => switch (content) {
                    .tuple => |span| {
                        const elems = self.builder.program.types.span(span);
                        if (path_step.data >= elems.len) return null;
                        ty = GuardedList.at(elems, path_step.data);
                    },
                    .primitive, .named, .record, .tag_union, .list, .box, .func, .erased, .zst => return null,
                },
                .record_field => switch (content) {
                    .record => |span| {
                        const label = try self.builder.recordFieldName(view, @enumFromInt(path_step.data));
                        const fields = self.builder.program.types.fieldSpan(span);
                        ty = for (0..GuardedList.borrowLen(fields)) |index| {
                            const field = GuardedList.at(fields, index);
                            if (field.name == label) break field.ty;
                        } else return null;
                    },
                    .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
                },
                .tag_payload_tag => switch (content) {
                    .tag_union => |span| {
                        const label = try self.builder.tagName(view, @enumFromInt(path_step.data));
                        const tags = self.builder.program.types.tagSpan(span);
                        const tag = for (0..GuardedList.borrowLen(tags)) |index| {
                            const tag = GuardedList.at(tags, index);
                            if (tag.name == label) break tag;
                        } else return null;

                        if (path_index >= path.len) return null;
                        const payload_step = path[path_index];
                        if (payload_step.stepKind() != .tag_payload_index) return null;
                        path_index += 1;

                        const payloads = self.builder.program.types.span(tag.payloads);
                        if (payload_step.data >= payloads.len) return null;
                        ty = GuardedList.at(payloads, payload_step.data);
                    },
                    .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return null,
                },
                .tag_payload_index => return null, // only valid after tag_payload_tag
            }
        }
        return ty;
    }

    /// Graph-native counterpart of `walkEvidencePath`, used while a callable
    /// still owns unrelated open cells. Tag payload selection consumes the
    /// required following payload-index step explicitly.
    fn walkEvidencePathNode(
        self: *BodyContext,
        view: ModuleView,
        start_node: NodeId,
        path: []const static_dispatch.EvidencePathStep,
    ) Allocator.Error!?NodeId {
        var node = start_node;
        var index: usize = 0;
        while (index < path.len) : (index += 1) {
            const step = path[index];
            const content = self.graph.content(node);
            switch (step.stepKind()) {
                .fn_arg => switch (content) {
                    .func => |function| {
                        if (step.data >= function.args.len) return null;
                        node = function.args[step.data];
                    },
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
                },
                .fn_ret => switch (content) {
                    .func => |function| node = function.ret,
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
                },
                .alias_arg, .nominal_arg => switch (content) {
                    .named => |named| {
                        if (step.data >= named.args.len) return null;
                        node = named.args[step.data];
                    },
                    .list, .box => |payload| {
                        if (step.data != 0) return null;
                        node = payload;
                    },
                    .redirect, .unresolved, .primitive, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
                },
                .alias_backing, .nominal_backing => switch (content) {
                    .named => |named| node = (named.backing orelse return null).node,
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
                },
                .tuple_elem => switch (content) {
                    .tuple => |items| {
                        if (step.data >= items.len) return null;
                        node = items[step.data];
                    },
                    .redirect, .unresolved, .primitive, .list, .box, .func, .tag_union, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
                },
                .record_field => switch (content) {
                    .record => node = try self.graph.recordFieldNode(node, try self.builder.recordFieldName(view, @enumFromInt(step.data))),
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
                },
                .tag_payload_tag => switch (content) {
                    .tag_union => {
                        index += 1;
                        if (index >= path.len or path[index].stepKind() != .tag_payload_index) return null;
                        node = try self.graph.tagPayloadNode(
                            node,
                            try self.builder.tagName(view, @enumFromInt(step.data)),
                            path[index].data,
                        );
                    },
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .named, .erased, .zst => return null,
                },
                .tag_payload_index => return null,
            }
        }
        return node;
    }
    fn methodTargetCalleeWithMono(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_mono_ty: Type.TypeId,
        evidence_vector: SpecEvidenceVector,
    ) Allocator.Error!DraftFnSlot {
        if (self.frozen_sealed_emission) {
            return try self.methodTargetCalleeWithClosedMono(lookup, callable_mono_ty);
        }
        const callable_node = try self.activeNodeFromType(callable_mono_ty);
        const synthesize_from_graph = switch (evidence_vector) {
            .resolved => false,
            .synthesize => try self.graph.typeHasActiveSnapshots(callable_mono_ty),
        };
        if (synthesize_from_graph) {
            return try self.methodTargetCalleeAtNode(lookup, callable_node, .synthesize);
        }
        const evidence: SpecEvidenceVector = switch (evidence_vector) {
            .resolved => evidence_vector,
            .synthesize => switch (lookup.target.kind) {
                .procedure => |procedure| .{ .resolved = try self.synthesizeTargetEvidence(
                    lookup,
                    procedure.template,
                    callable_mono_ty,
                ) },
                .local_proc => .{ .resolved = &.{} },
                .structural => Common.invariant("structural method registry result has no callable procedure body"),
            },
        };
        return try self.methodTargetCalleeAtNode(
            lookup,
            callable_node,
            evidence,
        );
    }

    fn methodTargetCalleeWithClosedMono(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_mono_ty: Type.TypeId,
    ) Allocator.Error!DraftFnSlot {
        if (try self.frozenCodecCallee(lookup, callable_mono_ty)) |prepared| return prepared;
        Common.invariant("sealed structural codec requested an unprepared callee");
    }

    fn methodLookupEql(_: *BodyContext, left: MethodLookup, right: MethodLookup) bool {
        if (!moduleBytesEqual(left.view.key.bytes, right.view.key.bytes)) return false;
        if (!std.meta.eql(left.target, right.target)) return false;
        if (left.local_proc_context != right.local_proc_context) return false;
        if (left.instantiation) |left_instantiation| {
            const right_instantiation = right.instantiation orelse return false;
            return moduleBytesEqual(left_instantiation.view.key.bytes, right_instantiation.view.key.bytes) and
                left_instantiation.callable_ty == right_instantiation.callable_ty;
        }
        return right.instantiation == null;
    }

    fn frozenCodecCallableFromArgs(
        self: *BodyContext,
        lookup: MethodLookup,
        arg_tys: []const Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            const function = self.builder.functionShape(prepared.callable_ty, "prepared codec callable was not a function");
            const prepared_args = self.builder.program.types.span(function.args);
            if (prepared_args.len != arg_tys.len) continue;
            if (!try self.builder.program.types.typeEql(&self.builder.program.names, function.ret, ret_ty)) continue;
            var matches = true;
            for (0..arg_tys.len) |index| {
                if (!try self.builder.program.types.typeEql(
                    &self.builder.program.names,
                    GuardedList.at(prepared_args, index),
                    arg_tys[index],
                )) {
                    matches = false;
                    break;
                }
            }
            if (matches) return prepared.callable_ty;
        }
        return null;
    }

    fn frozenCodecCallableForShape(
        self: *BodyContext,
        lookup: MethodLookup,
        shape_ty: Type.TypeId,
    ) Allocator.Error!?Type.TypeId {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (try self.builder.program.types.typeEql(
                &self.builder.program.names,
                prepared.shape_ty,
                shape_ty,
            )) return prepared.callable_ty;
        }
        return null;
    }

    fn frozenCodecCallableForLookup(
        self: *BodyContext,
        lookup: MethodLookup,
    ) Allocator.Error!?Type.TypeId {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        var found: ?Type.TypeId = null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (found) |previous| {
                if (!try self.builder.program.types.typeEql(
                    &self.builder.program.names,
                    previous,
                    prepared.callable_ty,
                )) Common.invariant("prepared codec lookup had multiple callable interfaces");
            } else {
                found = prepared.callable_ty;
            }
        }
        return found;
    }

    fn frozenCodecCallee(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_ty: Type.TypeId,
    ) Allocator.Error!?DraftFnSlot {
        const prepared_calls = self.frozen_codec_calls orelse return null;
        for (prepared_calls.calls) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (try self.builder.program.types.typeEql(
                &self.builder.program.names,
                prepared.callable_ty,
                callable_ty,
            )) return prepared.callee;
        }
        return null;
    }

    fn frozenCustomCodecCall(
        self: *BodyContext,
        kind: CodecKind,
        shape_ty: Type.TypeId,
        lookup: MethodLookup,
    ) FrozenPreparedCodecCall {
        const prepared_calls = self.frozen_codec_calls orelse
            Common.invariant("custom codec emission had no prepared call plan");
        const prepared = prepared_calls.customCall(kind, shape_ty) orelse
            Common.invariant("custom codec emission reached a shape without a prepared call");
        if (!self.methodLookupEql(prepared.lookup, lookup)) {
            Common.invariant("prepared custom codec call resolved to a different method target");
        }
        return prepared.*;
    }

    fn preparedCodecCalleeAtNode(
        self: *BodyContext,
        lookup: MethodLookup,
        callable_node: NodeId,
    ) Allocator.Error!?DraftFnSlot {
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (self.graph.sameFunctionInterface(prepared.callable_node, callable_node)) {
                return prepared.callee;
            }
            if (try self.graph.typeIsResolved(prepared.callable_node) and
                try self.graph.typeIsResolved(callable_node))
            {
                const prepared_ty = try self.activeTypeFromNode(prepared.callable_node);
                const callable_ty = try self.activeTypeFromNode(callable_node);
                if (try self.builder.program.types.typeEql(
                    &self.builder.program.names,
                    prepared_ty,
                    callable_ty,
                )) return prepared.callee;
            }
        }
        return null;
    }

    /// Instantiate the exact checked procedure root whose evidence paths are
    /// stored in CheckedProcedureTemplate.
    fn procedureTargetRootNode(
        self: *BodyContext,
        lookup: MethodLookup,
        template_ref: names.ProcTemplate,
    ) Allocator.Error!NodeId {
        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const template = lookup.view.templates.get(template_ref.template);
        return try target_ctx.instNode(template.checked_fn_root);
    }

    /// Apply a checked target root to its live call request after any
    /// checker-authored evidence paths have retained their component nodes.
    fn relateEvidenceTargetRootToRequest(
        self: *BodyContext,
        root_node: NodeId,
        request_fn_node: NodeId,
    ) Allocator.Error!void {
        if (try self.graph.containsGeneratedPrivate(request_fn_node)) {
            try relateFunctionRequestInterface(self.graph, root_node, request_fn_node);
        } else {
            try self.graph.unify(root_node, request_fn_node);
        }
    }

    fn methodTargetCalleeAtNode(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        evidence_vector: SpecEvidenceVector,
    ) Allocator.Error!DraftFnSlot {
        const lookup = try self.withLocalProcContext(raw_lookup);
        if (try self.preparedCodecCalleeAtNode(lookup, request_fn_node)) |prepared| return prepared;
        const source_fn_ty = lookup.target.callable_ty;
        const source_fn_key = lookup.view.types.rootKey(source_fn_ty);
        return switch (lookup.target.kind) {
            .procedure => |procedure| blk: {
                const template = lookup.view.templates.get(procedure.template.template);
                const params = lookup.view.templates.evidenceParams(&template);
                const target_root_node = try self.procedureTargetRootNode(lookup, procedure.template);
                const projected_components: ?[]NodeId = switch (evidence_vector) {
                    .resolved => null,
                    .synthesize => try self.projectEvidenceComponentNodes(
                        lookup.view,
                        params,
                        target_root_node,
                    ),
                };
                defer if (projected_components) |components| self.allocator.free(components);
                try self.relateEvidenceTargetRootToRequest(target_root_node, request_fn_node);
                const evidence = switch (evidence_vector) {
                    .resolved => |resolved| resolved,
                    .synthesize => try self.synthesizeEvidenceAtComponentNodes(
                        lookup.view,
                        params,
                        projected_components.?,
                    ),
                };
                const slot = try self.builder.lowerDraftTemplateFromContext(
                    self,
                    procedure.template,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    evidence,
                    switch (evidence_vector) {
                        .resolved => .resolved,
                        .synthesize => .synthesized,
                    },
                    if (procedure.runtime_target.iteratorProcedure() == .iter_from_step) .exact_graph else .independent_roots,
                );
                break :blk slot;
            },
            .local_proc => |local| blk: {
                const params = self.localProcEvidenceParams(lookup.view, local);
                const evidence = switch (evidence_vector) {
                    .resolved => |resolved| resolved,
                    .synthesize => synthesize: {
                        var target_ctx = try self.methodTargetContext(lookup);
                        defer target_ctx.deinit();
                        const target_root_node = try target_ctx.instNode(source_fn_ty);
                        const projected_components = try self.projectEvidenceComponentNodes(
                            lookup.view,
                            params,
                            target_root_node,
                        );
                        defer self.allocator.free(projected_components);
                        try self.relateEvidenceTargetRootToRequest(target_root_node, request_fn_node);
                        break :synthesize try self.synthesizeEvidenceAtComponentNodes(
                            lookup.view,
                            params,
                            projected_components,
                        );
                    },
                };
                break :blk .{ .local = try self.lowerDraftLocalProcAtNode(
                    .{
                        .binder = local.binder,
                        .expr = local.expr,
                        .dispatch_scope = local.dispatch_scope,
                    },
                    lookup.view,
                    lookup.local_proc_context orelse
                        Common.invariant("local method target did not carry its declaration context"),
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    evidence,
                ) };
            },
            .structural => Common.invariant("structural method registry result has no callable procedure body"),
        };
    }

    /// Lower a checker-classified direct target at the already-instantiated
    /// request interface. Unlike evidence-dependent dispatch, this does not
    /// instantiate the target's checked root and relate it back to the request:
    /// CheckedModule construction already performed that target instantiation and
    /// recorded the exact callable in the plan.
    fn methodTargetCalleeDirectAtNode(
        self: *BodyContext,
        raw_lookup: MethodLookup,
        request_fn_node: NodeId,
        evidence_vector: SpecEvidenceVector,
    ) Allocator.Error!DraftFnSlot {
        const lookup = try self.withLocalProcContext(raw_lookup);
        if (try self.preparedCodecCalleeAtNode(lookup, request_fn_node)) |prepared| return prepared;
        const source_fn_ty = lookup.target.callable_ty;
        const source_fn_key = lookup.view.types.rootKey(source_fn_ty);
        return switch (lookup.target.kind) {
            .procedure => |procedure| blk: {
                const template = lookup.view.templates.get(procedure.template.template);
                const params = lookup.view.templates.evidenceParams(&template);
                const evidence = switch (evidence_vector) {
                    .resolved => |resolved| resolved,
                    .synthesize => blk_evidence: {
                        const components = try self.projectEvidenceComponentNodes(
                            lookup.view,
                            params,
                            request_fn_node,
                        );
                        defer self.allocator.free(components);
                        break :blk_evidence try self.synthesizeEvidenceAtComponentNodes(
                            lookup.view,
                            params,
                            components,
                        );
                    },
                };
                break :blk try self.builder.lowerDraftTemplateFromContext(
                    self,
                    procedure.template,
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    evidence,
                    switch (evidence_vector) {
                        .resolved => .resolved,
                        .synthesize => .synthesized,
                    },
                    if (procedure.runtime_target.iteratorProcedure() == .iter_from_step) .exact_graph else .independent_roots,
                );
            },
            .local_proc => |local| blk: {
                const params = self.localProcEvidenceParams(lookup.view, local);
                const evidence = switch (evidence_vector) {
                    .resolved => |resolved| resolved,
                    .synthesize => blk_evidence: {
                        const components = try self.projectEvidenceComponentNodes(
                            lookup.view,
                            params,
                            request_fn_node,
                        );
                        defer self.allocator.free(components);
                        break :blk_evidence try self.synthesizeEvidenceAtComponentNodes(
                            lookup.view,
                            params,
                            components,
                        );
                    },
                };
                break :blk .{ .local = try self.lowerDraftLocalProcAtNode(
                    .{
                        .binder = local.binder,
                        .expr = local.expr,
                        .dispatch_scope = local.dispatch_scope,
                    },
                    lookup.view,
                    lookup.local_proc_context orelse
                        Common.invariant("direct local method target did not carry its declaration context"),
                    source_fn_ty,
                    source_fn_key,
                    request_fn_node,
                    evidence,
                ) };
            },
            .structural => Common.invariant("direct checked call targeted a structural derivation"),
        };
    }

    fn lowerResolvedDispatchAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        lookup: MethodLookup,
        callable_node: NodeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!BodyExprData {
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const args = try arg_ctx.lowerDispatchOperandsAtNodes(
            plan.argsSlice(self.view.static_dispatch_plans),
            fn_nodes.args,
            pre_lowered,
        );
        const contextual_lookup = try self.withLocalProcContext(lookup);
        return .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(try self.methodTargetCalleeAtNode(
                contextual_lookup,
                callable_node,
                try self.evidenceForDispatchTarget(plan),
            )),
            .args = args,
            .iterator_procedure = self.iteratorProcedureForMethodTarget(contextual_lookup.target),
            .captures = try self.methodTargetCaptureSpan(contextual_lookup),
        } };
    }

    fn lowerResolvedDirectDispatchAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        lookup: MethodLookup,
        callable_node: NodeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!BodyExprData {
        const fn_nodes = try self.graph.functionNodes(callable_node);
        const args = try arg_ctx.lowerDispatchOperandsAtNodes(
            plan.argsSlice(self.view.static_dispatch_plans),
            fn_nodes.args,
            pre_lowered,
        );
        const contextual_lookup = try self.withLocalProcContext(lookup);
        return .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(try self.methodTargetCalleeDirectAtNode(
                contextual_lookup,
                callable_node,
                try self.evidenceForDispatchTarget(plan),
            )),
            .args = args,
            .captures = try self.methodTargetCaptureSpan(contextual_lookup),
        } };
    }

    fn lowerStructuralEqualityAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        const eq = switch (plan.result_mode) {
            .equality => |eq| eq,
            .value, .hash, .parser_for, .encoder_for, .map, .map_effectful => Common.invariant("non-equality dispatch plan reached graph equality lowering"),
        };
        if (!eq.structural_allowed) {
            Common.invariant("structural equality dispatch plan did not permit structural equality");
        }

        const fn_nodes = try self.graph.functionNodes(callable_node);
        if (fn_nodes.args.len != 2) {
            Common.invariant("structural equality callable graph node must have two operands");
        }
        try self.graph.unify(fn_nodes.args[0], fn_nodes.args[1]);

        const ret_ty = try self.resolvedTypeViewForNode(fn_nodes.ret);
        const operands_span = try arg_ctx.lowerDispatchOperandsAtNodes(
            plan.argsSlice(self.view.static_dispatch_plans),
            fn_nodes.args,
            pre_lowered,
        );
        const operands = arg_ctx.exprSpan(operands_span);
        if (operands.len != 2) {
            Common.invariant("structural equality dispatch did not lower two operands");
        }

        if (try self.graph.typeIsResolved(fn_nodes.args[0])) {
            return try self.lowerStructuralEqFromOperands(
                try self.activeTypeFromNode(fn_nodes.args[0]),
                operands[0],
                operands[1],
                eq.negated,
                ret_ty,
            );
        }
        return try self.deferStructuralEqOperandsAtNode(
            ret_ty,
            fn_nodes.args[0],
            operands[0],
            operands[1],
            eq.negated,
        );
    }

    /// The hash counterpart of `lowerStructuralEqualityAtNode`: the hashed
    /// value's node may still carry live row defaults, so the derivation
    /// defers to final graph sealing instead of forcing an eager resolved
    /// view. The hasher operand and result share one concrete type.
    fn lowerStructuralHashAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        const hash = switch (plan.result_mode) {
            .hash => |hash| hash,
            .value, .equality, .parser_for, .encoder_for, .map, .map_effectful => Common.invariant("non-hash dispatch plan reached graph hash lowering"),
        };
        if (!hash.structural_allowed) {
            Common.invariant("structural hash dispatch plan did not permit structural hashing");
        }

        const fn_nodes = try self.graph.functionNodes(callable_node);
        if (fn_nodes.args.len != 2) {
            Common.invariant("structural hash callable graph node must have two operands");
        }
        try self.graph.unify(fn_nodes.args[1], fn_nodes.ret);

        const ret_ty = try self.resolvedTypeViewForNode(fn_nodes.ret);
        const operands_span = try arg_ctx.lowerDispatchOperandsAtNodes(
            plan.argsSlice(self.view.static_dispatch_plans),
            fn_nodes.args,
            pre_lowered,
        );
        const operands = arg_ctx.exprSpan(operands_span);
        if (operands.len != 2) {
            Common.invariant("structural hash dispatch did not lower two operands");
        }

        if (try self.graph.typeIsResolved(fn_nodes.args[0])) {
            return try self.lowerHashExpr(
                try self.activeTypeFromNode(fn_nodes.args[0]),
                operands[0],
                operands[1],
                ret_ty,
            );
        }
        return try self.deferStructuralDerivationOperandsAtNode(
            ret_ty,
            fn_nodes.args[0],
            operands[0],
            operands[1],
            .hash,
        );
    }

    fn deferStructuralSerializationAtNode(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_node: NodeId,
        shape_node: NodeId,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        const callable = try self.graph.functionNodes(callable_node);
        if (callable.args.len != 1) {
            Common.invariant("structural serialization callable graph node must have one encoding operand");
        }
        const encoding = self.preLoweredOperandAt(pre_lowered, 0) orelse
            Common.invariant("structural serialization encoding operand was not lowered before deferral");
        const expr = try self.addExprWithTypeCell(DraftTypeCell.fromGraphNode(callable.ret), .pending_deferred);
        self.draft.expr_impossibility_proofs.items[@intFromEnum(expr)] = self.exprImpossibilityProof(encoding);
        const lexical = try self.captureCodecLexicalContext();
        var lexical_needs_cleanup = true;
        errdefer if (lexical_needs_cleanup) {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        };
        try self.draft.deferred_structural_serializations.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .plan = plan,
            .callable_node = callable_node,
            .shape_node = shape_node,
            .encoding = encoding,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
        });
        lexical_needs_cleanup = false;
        const kind: CodecKind = switch (plan.result_mode) {
            .parser_for => .parser,
            .encoder_for => .encoder,
            .value, .equality, .hash, .map, .map_effectful => Common.invariant("non-codec result mode reached structural serialization deferral"),
        };
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        _ = try self.prepareCustomCodecCallsAtNode(expr, kind, shape_node, callable_node, &seen);
        return expr;
    }

    /// The two lowered operands of a structural derivation plus `derived_ty`,
    /// the type being derived on, which the terminal lowering needs.
    const StructuralBinaryOperands = struct {
        first: DraftExprId,
        second: DraftExprId,
        derived_ty: Type.TypeId,
    };

    /// Lower the value and hasher operands of a structural hash dispatch,
    /// honoring a `pre_lowered` operand at index 0 or 1. `noun` is the derivation
    /// name used only in invariant diagnostics.
    fn lowerStructuralBinaryOperands(
        self: *BodyContext,
        comptime noun: []const u8,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!StructuralBinaryOperands {
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (plan_args.len != 2) Common.invariant("structural " ++ noun ++ " dispatch plan must have two operands");
        const fn_data = self.builder.functionShape(callable_mono_ty, "checked structural " ++ noun ++ " target had a non-function type");
        // Copy because the recursive operand lowering below may reallocate
        // types.span, dangling the slice; only the scalar derived type escapes.
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        if (arg_tys.len != 2) Common.invariant("structural " ++ noun ++ " callable type must have two operands");
        const first = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);
        const second = self.preLoweredOperandAt(pre_lowered, 1) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[1], arg_tys[1]);
        return .{ .first = first, .second = second, .derived_ty = arg_tys[0] };
    }

    /// Lower derived `map`/`map!` into the exhaustive tag match selected by
    /// checking. The payload-slot plan is explicit evidence; Monotype never
    /// re-runs eligibility or guesses which payload should be transformed.
    fn lowerStructuralMap(
        self: *BodyContext,
        comptime noun: []const u8,
        plan: static_dispatch.StaticDispatchCallPlan,
        map_plan: static_dispatch.DerivedMapPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
    ) Allocator.Error!DraftExprId {
        switch (plan.result_mode) {
            .map => |mode| if (!mode.structural_allowed) Common.invariant("structural map dispatch plan did not permit structural map lowering"),
            .map_effectful => |mode| if (!mode.structural_allowed) Common.invariant("structural map! dispatch plan did not permit structural map! lowering"),
            .value, .equality, .hash, .parser_for, .encoder_for => Common.invariant("non-map dispatch plan reached structural map lowering"),
        }

        const operands = try self.lowerStructuralBinaryOperands(noun, plan, callable_mono_ty, arg_ctx, pre_lowered);
        const input_ty = operands.derived_ty;
        const transform_ty = try self.exprType(operands.second);
        const transform_fn = self.builder.functionShape(transform_ty, "checked derived map transform had a non-function type");
        const transform_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(transform_fn.args));
        defer self.allocator.free(transform_arg_tys);
        if (transform_arg_tys.len != 1) Common.invariant("checked derived map transform did not have one argument");

        const selected_name = try self.builder.tagName(self.view, map_plan.tag);
        const input_selected_tag = self.builder.tagByName(input_ty, selected_name);
        const output_selected_tag = self.builder.tagByName(ret_ty, selected_name);
        const input_selected_payloads = self.builder.program.types.span(input_selected_tag.payloads);
        const output_selected_payloads = self.builder.program.types.span(output_selected_tag.payloads);
        if (map_plan.payload_index >= input_selected_payloads.len or map_plan.payload_index >= output_selected_payloads.len) {
            Common.invariant("checked derived map payload plan was outside the selected tag's payloads");
        }
        const selected_index: usize = @intCast(map_plan.payload_index);
        if (!self.sameType(transform_arg_tys[0], GuardedList.at(input_selected_payloads, selected_index))) {
            Common.invariant("checked derived map transform argument differed from the selected input payload");
        }
        if (!self.sameType(transform_fn.ret, GuardedList.at(output_selected_payloads, selected_index))) {
            Common.invariant("checked derived map transform result differed from the selected output payload");
        }

        const input_tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.tagUnionTags(input_ty));
        defer self.allocator.free(input_tags);
        const branches = try self.allocator.alloc(DraftBranch, input_tags.len);
        defer self.allocator.free(branches);

        const transform_local = try self.addLocal(self.builder.symbols.fresh(), transform_ty);
        for (input_tags, 0..) |input_tag, branch_index| {
            const input_payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(input_tag.payloads));
            defer self.allocator.free(input_payload_tys);
            const output_tag = self.builder.tagByName(ret_ty, input_tag.name);
            const output_payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(output_tag.payloads));
            defer self.allocator.free(output_payload_tys);
            if (input_payload_tys.len != output_payload_tys.len) {
                Common.invariant("derived map changed an unselected tag's payload arity");
            }

            const payload_pats = try self.allocator.alloc(DraftPatId, input_payload_tys.len);
            defer self.allocator.free(payload_pats);
            const output_payloads = try self.allocator.alloc(DraftExprId, output_payload_tys.len);
            defer self.allocator.free(output_payloads);
            for (input_payload_tys, output_payload_tys, 0..) |input_payload_ty, output_payload_ty, payload_index| {
                const payload_local = try self.addLocal(self.builder.symbols.fresh(), input_payload_ty);
                payload_pats[payload_index] = try self.bindPat(payload_local, input_payload_ty);
                const input_payload = try self.localExpr(payload_local, input_payload_ty);
                if (input_tag.name == selected_name and payload_index == selected_index) {
                    const transform = try self.localExpr(transform_local, transform_ty);
                    output_payloads[payload_index] = try self.addExpr(.{
                        .ty = output_payload_ty,
                        .data = .{ .call_value = .{
                            .callee = transform,
                            .args = try self.addExprSpan(&.{input_payload}),
                        } },
                    });
                } else {
                    if (!self.sameType(input_payload_ty, output_payload_ty)) {
                        Common.invariant("derived map changed an unselected payload type");
                    }
                    output_payloads[payload_index] = input_payload;
                }
            }

            const body = try self.addConstructorExpr(ret_ty, .{ .tag = .{
                .name = output_tag.name,
                .payloads = try self.addExprSpan(output_payloads),
            } });
            const branch_pat = try self.addConstructorPat(input_ty, .{ .tag = .{
                .name = input_tag.name,
                .payloads = try self.addPatSpan(payload_pats),
            } });
            branches[branch_index] = .{ .pat = branch_pat, .body = body };
        }

        const input_local = try self.addLocal(self.builder.symbols.fresh(), input_ty);
        const match_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = try self.localExpr(input_local, input_ty),
            .branches = try self.addBranchSpan(branches),
        } } });
        const bind_transform = try self.wrapLet(transform_local, transform_ty, operands.second, match_expr, ret_ty);
        return try self.wrapLet(input_local, input_ty, operands.first, bind_transform, ret_ty);
    }

    fn lowerStructuralParser(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
        shape_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const parser = switch (plan.result_mode) {
            .parser_for => |parser_for| parser_for,
            .value, .equality, .hash, .encoder_for, .map, .map_effectful => Common.invariant("non-parser_for dispatch plan reached structural parse lowering"),
        };
        if (!parser.structural_allowed) Common.invariant("structural parser dispatch plan did not permit structural parser lowering");

        const fn_data = self.builder.functionShape(callable_mono_ty, "checked structural parser target had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (arg_tys.len != 1 or plan_args.len != 1) Common.invariant("structural parser callable type must have one encoding argument");
        if (!self.sameType(fn_data.ret, ret_ty)) Common.invariant("structural parser return type differed from dispatch expression type");

        const runtime_fn = self.builder.functionShape(ret_ty, "checked structural parser return had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 1) Common.invariant("structural parser runtime function must have one state argument");

        const top_level_null_try = self.tryNullInfo(shape_ty);
        const nominal_scalar_backing = if (self.builder.nominalExprBackingType(shape_ty)) |backing_ty|
            self.parseScalarMethodName(backing_ty) != null
        else
            false;
        if (self.parseScalarMethodName(shape_ty) == null and top_level_null_try == null and !nominal_scalar_backing) {
            if (self.setPayloadType(shape_ty)) |elem_ty| {
                if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser set element type was not supported");
            } else if (self.dictEntryShape(shape_ty)) |dict| {
                if (!self.dictKeyIsStringRendered(dict.key_ty) and !try self.parseFieldTypeIsSupported(dict.key_ty, false)) {
                    Common.invariant("structural parser dict key type was not supported");
                }
                if (!try self.parseFieldTypeIsSupported(dict.value_ty, false)) Common.invariant("structural parser dict value type was not supported");
            } else {
                switch (self.builder.shapeContent(shape_ty)) {
                    .list => |elem_ty| {
                        if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser list element type was not supported");
                    },
                    .box => |payload_ty| {
                        if (!try self.parseFieldTypeIsSupported(payload_ty, false)) Common.invariant("structural parser box payload type was not supported");
                    },
                    .tuple => |span| {
                        const elem_tys = self.builder.program.types.span(span);
                        for (0..GuardedList.borrowLen(elem_tys)) |index| {
                            const elem_ty = GuardedList.at(elem_tys, index);
                            if (!try self.parseFieldTypeIsSupported(elem_ty, false)) Common.invariant("structural parser tuple element type was not supported");
                        }
                    },
                    .record => |fields_span| blk: {
                        const fields = self.builder.program.types.fieldSpan(fields_span);
                        for (0..GuardedList.borrowLen(fields)) |index| {
                            const field = GuardedList.at(fields, index);
                            if (!try self.parseFieldTypeIsSupported(field.ty, true)) Common.invariant("structural parser record field type was not supported");
                        }
                        break :blk;
                    },
                    .tag_union => |tags_span| blk: {
                        const tags = self.builder.program.types.tagSpan(tags_span);
                        if (tags.len == 0) Common.invariant("structural parser empty tag union reached postcheck lowering");
                        for (0..GuardedList.borrowLen(tags)) |tag_index| {
                            const tag = GuardedList.at(tags, tag_index);
                            const payload_tys = self.builder.program.types.span(tag.payloads);
                            for (0..GuardedList.borrowLen(payload_tys)) |payload_index| {
                                const payload_ty = GuardedList.at(payload_tys, payload_index);
                                if (!try self.parseFieldTypeIsSupported(payload_ty, false)) Common.invariant("structural parser tag-union payload type was not supported");
                            }
                        }
                        break :blk;
                    },
                    .zst => {},
                    .primitive, .named, .func, .erased => Common.invariant("structural parser dispatcher was not a supported structural type"),
                }
            }
        }

        const encoding_value = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
        self.setLocalCaptureId(encoding_local, parserEncodingCaptureId());
        const state_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);

        const str_ty = try self.builder.primitiveType(.str);
        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        try self.buildParserConstructionPrecomputedPlan(
            &precomputed_plan,
            shape_ty,
            try self.localExpr(encoding_local, arg_tys[0]),
            arg_tys[0],
            str_ty,
        );

        const parsed = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(&.{runtime_arg_tys[0]}, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerParseShapeHelperCall(
                shape_ty,
                try self.localExpr(encoding_local, arg_tys[0]),
                arg_tys[0],
                try self.localExpr(state_local, runtime_arg_tys[0]),
                runtime_arg_tys[0],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const fn_id = try self.addFn(.{
            .fn_def = .{ .parser_runtime = .{
                .owner = self.owner_template,
                .expr = plan.expr,
            } },
            .source_fn_ty = plan.callable_ty,
            .source_fn_key = generatedParserRuntimeKey(self.current_fn_key, plan.expr),
            .mono_fn_ty = ret_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var parser_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{
                .{ .local = state_local, .ty = runtime_arg_tys[0] },
            }),
            .body = parsed,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            parser_expr = try self.wrapLet(capture.local, str_ty, capture.value, parser_expr, ret_ty);
        }
        return try self.wrapLet(encoding_local, arg_tys[0], encoding_value, parser_expr, ret_ty);
    }

    fn lowerStructuralEncoderFor(
        self: *BodyContext,
        plan: static_dispatch.StaticDispatchCallPlan,
        callable_mono_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        arg_ctx: *BodyContext,
        pre_lowered: []const PreLoweredOperand,
        shape_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const encoder_for = switch (plan.result_mode) {
            .encoder_for => |encoder_for| encoder_for,
            .value, .equality, .hash, .parser_for, .map, .map_effectful => Common.invariant("non-encoder_for dispatch plan reached structural encoder_for lowering"),
        };
        if (!encoder_for.structural_allowed) Common.invariant("structural encoder_for dispatch plan did not permit structural encoder_for lowering");

        const fn_data = self.builder.functionShape(callable_mono_ty, "checked structural encoder_for target had a non-function type");
        const arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(fn_data.args));
        defer self.allocator.free(arg_tys);
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (arg_tys.len != 1 or plan_args.len != 1) Common.invariant("structural encoder_for callable type must have one encoding argument");
        if (!self.sameType(fn_data.ret, ret_ty)) Common.invariant("structural encoder_for return type differed from dispatch expression type");

        const runtime_fn = self.builder.functionShape(ret_ty, "checked structural encoder_for return had a non-function type");
        const runtime_arg_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(runtime_fn.args));
        defer self.allocator.free(runtime_arg_tys);
        if (runtime_arg_tys.len != 2) Common.invariant("structural encoder_for runtime function must have value and state arguments");

        if (!try self.encodeFieldTypeIsSupported(shape_ty, arg_tys[0])) Common.invariant("structural encoder_for dispatcher was not a supported structural type");

        const encoding_value = self.preLoweredOperandAt(pre_lowered, 0) orelse
            try arg_ctx.lowerDispatchOperandAtType(plan_args[0], arg_tys[0]);

        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), arg_tys[0]);
        const value_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[0]);
        const state_local = try self.addLocal(self.builder.symbols.fresh(), runtime_arg_tys[1]);
        self.setLocalCaptureId(encoding_local, encoderForEncodingCaptureId());

        const str_ty = try self.builder.primitiveType(.str);
        var precomputed_plan = ParserPrecomputedPlan.init(self.allocator);
        defer precomputed_plan.deinit();
        precomputed_plan.next_capture_id = encoderForFirstFieldCaptureId();
        try self.buildEncodeConstructionPrecomputedPlan(
            &precomputed_plan,
            shape_ty,
            try self.localExpr(encoding_local, arg_tys[0]),
            arg_tys[0],
            str_ty,
        );

        const runtime_source_fn_key = generatedEncoderForRuntimeKey(self.current_fn_key, plan.expr);
        const saved_current_fn_key = self.current_fn_key;
        const saved_encoder_source_fn_ty = self.generated_encoder_source_fn_ty;
        const saved_encoder_source_expr = self.generated_encoder_source_expr;
        const saved_encoder_lambda_index = self.generated_encoder_lambda_index;
        self.current_fn_key = runtime_source_fn_key;
        self.generated_encoder_source_fn_ty = plan.callable_ty;
        self.generated_encoder_source_expr = plan.expr;
        self.generated_encoder_lambda_index = 0;
        defer {
            self.current_fn_key = saved_current_fn_key;
            self.generated_encoder_source_fn_ty = saved_encoder_source_fn_ty;
            self.generated_encoder_source_expr = saved_encoder_source_expr;
            self.generated_encoder_lambda_index = saved_encoder_lambda_index;
        }

        const encoded = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            try capture_tys.append(self.allocator, arg_tys[0]);
            for (precomputed_plan.captures.items) |_| try capture_tys.append(self.allocator, str_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(runtime_arg_tys, capture_tys.items);
            defer demand_scope.leave();
            break :blk try self.lowerEncodeShapeToState(
                shape_ty,
                try self.localExpr(value_local, runtime_arg_tys[0]),
                try self.localExpr(encoding_local, arg_tys[0]),
                arg_tys[0],
                try self.localExpr(state_local, runtime_arg_tys[1]),
                runtime_arg_tys[1],
                runtime_fn.ret,
                &precomputed_plan,
            );
        };
        const fn_id = try self.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = self.owner_template,
                .expr = plan.expr,
            } },
            .source_fn_ty = plan.callable_ty,
            .source_fn_key = runtime_source_fn_key,
            .mono_fn_ty = ret_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        var encoder_expr = try self.addExpr(.{ .ty = ret_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(&.{
                .{ .local = value_local, .ty = runtime_arg_tys[0] },
                .{ .local = state_local, .ty = runtime_arg_tys[1] },
            }),
            .body = encoded,
        } } });
        var capture_index = precomputed_plan.captures.items.len;
        while (capture_index > 0) {
            capture_index -= 1;
            const capture = precomputed_plan.captures.items[capture_index];
            encoder_expr = try self.wrapLet(capture.local, str_ty, capture.value, encoder_expr, ret_ty);
        }
        return try self.wrapLet(encoding_local, arg_tys[0], encoding_value, encoder_expr, ret_ty);
    }

    fn lowerEncodeShapeToState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.tryNullInfo(shape_ty)) |info| {
            return try self.lowerEncodeNullTryToState(info, shape_ty, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.dictEntryShape(shape_ty)) |dict| {
            return try self.lowerEncodeDictToState(dict.key_ty, dict.value_ty, shape_ty, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        if (self.setPayloadType(shape_ty)) |payload_ty| {
            return try self.lowerEncodeSetToState(payload_ty, shape_ty, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
        }
        switch (self.builder.shapeContent(shape_ty)) {
            .list => |elem_ty| return try self.lowerEncodeListToState(elem_ty, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .tuple => |items| {
                const item_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(items));
                defer self.allocator.free(item_tys);
                return try self.lowerEncodeTupleToState(item_tys, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            },
            .box => |payload_ty| {
                const unboxed = try self.lowLevelExpr(.box_unbox, &.{value_expr}, payload_ty);
                return try self.lowerEncodeShapeToState(payload_ty, unboxed, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
            },
            .primitive, .named, .record, .tag_union, .func, .erased, .zst => {},
        }
        if (try self.customEncoderForLookup(shape_ty)) |raw_lookup| {
            return try self.lowerCustomEncoderForState(
                try self.withLocalProcContext(raw_lookup),
                shape_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                state_expr,
                state_ty,
                ret_ty,
            );
        }
        if (self.encodeScalarMethodName(shape_ty)) |method_name| {
            return try self.lowerEncodeFormatMethod(method_name, &.{ value_expr, state_expr }, &.{ shape_ty, state_ty }, encoding_ty, ret_ty);
        }
        // A nominal opaque with a scalar backing and no custom encoder (e.g. `Username := Str`)
        // encodes as its backing: unwrap one nominal layer and encode the scalar.
        if (self.builder.nominalExprBackingType(shape_ty)) |backing_ty| {
            if (self.encodeScalarMethodName(backing_ty) != null) {
                const value_local = try self.addLocal(self.builder.symbols.fresh(), shape_ty);
                const backing_local = try self.addLocal(self.builder.symbols.fresh(), backing_ty);
                const encoded_backing = try self.lowerEncodeShapeToState(
                    backing_ty,
                    try self.localExpr(backing_local, backing_ty),
                    encoding_expr,
                    encoding_ty,
                    state_expr,
                    state_ty,
                    ret_ty,
                    precomputed_plan,
                );
                const unwrap_pat = try self.addPat(.{
                    .ty = shape_ty,
                    .data = .{ .nominal = try self.bindPat(backing_local, backing_ty) },
                });
                const branch = DraftBranch{ .pat = unwrap_pat, .body = encoded_backing };
                const matched = try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
                    .scrutinee = try self.localExpr(value_local, shape_ty),
                    .branches = try self.addBranchSpan(&[_]DraftBranch{branch}),
                } } });
                return try self.wrapLet(value_local, shape_ty, value_expr, matched, ret_ty);
            }
        }
        return switch (self.builder.shapeContent(shape_ty)) {
            .record, .zst => try self.lowerEncodeRecordToState(shape_ty, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .tag_union => |tags_span| try self.lowerEncodeTagUnionToState(tags_span, value_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan),
            .primitive, .named, .tuple, .list, .box, .func, .erased => Common.invariant("encoder_for selected an unsupported shape"),
        };
    }

    fn functionType(self: *BodyContext, arg_tys: []const Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.builder.program.types.add(.{ .func = .{
            .args = try self.builder.program.types.addSpan(arg_tys),
            .ret = ret_ty,
        } });
    }

    fn encodeValueThunkType(self: *BodyContext, state_ty: Type.TypeId, ret_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        return try self.functionType(&.{state_ty}, ret_ty);
    }

    const EncodeContainerKind = enum { tag, record, tuple, list, dict };

    const EncodeContainerMethod = struct {
        lookup: MethodLookup,
        callable_ty: Type.TypeId,
        state_ty: Type.TypeId,
        result_ty: Type.TypeId,
        container_state_ty: Type.TypeId,
        container_result_ty: Type.TypeId,
        writer_ty: Type.TypeId,
        body_ty: Type.TypeId,
    };

    fn resolveEncodeContainerMethod(
        self: *BodyContext,
        method_name: []const u8,
        kind: EncodeContainerKind,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        result_ty: Type.TypeId,
    ) Allocator.Error!EncodeContainerMethod {
        const lookup = try self.methodLookupForTypeName(encoding_ty, method_name);
        const callable_ty = try self.frozenCodecCallableForLookup(lookup) orelse
            Common.invariant("container encoder callable was not prepared before graph sealing");
        const method_fn = self.builder.functionShape(callable_ty, "container encoder method was not a function");
        const method_args = self.builder.program.types.span(method_fn.args);
        const expected_arity: usize = if (kind == .tag) 4 else 3;
        if (method_args.len != expected_arity) Common.invariant("container encoder method had an unexpected arity");
        if (!self.sameType(GuardedList.at(method_args, 0), state_ty)) Common.invariant("container encoder input state type differed from the encoder state type");
        if (!self.sameType(method_fn.ret, result_ty)) Common.invariant("container encoder result type differed from the encoder result type");

        const u64_ty = try self.builder.primitiveType(.u64);
        const str_ty = try self.builder.primitiveType(.str);
        const body_index: usize = expected_arity - 1;
        if (kind == .tag) {
            if (!self.sameType(GuardedList.at(method_args, 1), str_ty)) Common.invariant("tag encoder name argument was not Str");
            if (!self.sameType(GuardedList.at(method_args, 2), u64_ty)) Common.invariant("tag encoder payload count argument was not U64");
        } else if (!self.sameType(GuardedList.at(method_args, 1), u64_ty)) {
            Common.invariant("container encoder item count argument was not U64");
        }

        const body_ty = GuardedList.at(method_args, body_index);
        const body_fn = self.builder.functionShape(body_ty, "container encoder body callback was not a function");
        const body_args = self.builder.program.types.span(body_fn.args);
        if (body_args.len != 2) Common.invariant("container encoder body callback had an unexpected arity");
        const container_state_ty = GuardedList.at(body_args, 0);
        const writer_ty = GuardedList.at(body_args, 1);
        const container_result_ty = body_fn.ret;

        const outer_result = self.tryInfo(result_ty);
        if (!self.sameType(outer_result.ok_ty, state_ty)) Common.invariant("container encoder result Ok type differed from the encoder state type");
        const container_result = self.tryInfo(container_result_ty);
        if (!self.sameType(container_result.ok_ty, container_state_ty)) Common.invariant("container encoder callback result Ok type differed from its state type");
        if (!self.sameType(container_result.err_ty, outer_result.err_ty)) Common.invariant("container encoder callback and outer result error types differed");

        const writer_fn = self.builder.functionShape(writer_ty, "container encoder writer was not a function");
        const writer_args = self.builder.program.types.span(writer_fn.args);
        const expected_writer_arity: usize = switch (kind) {
            .record, .dict => 3,
            .tag, .tuple, .list => 2,
        };
        if (writer_args.len != expected_writer_arity) Common.invariant("container encoder writer had an unexpected arity");
        if (!self.sameType(GuardedList.at(writer_args, 0), container_state_ty)) Common.invariant("container encoder writer state type differed from the callback state type");
        if (!self.sameType(writer_fn.ret, container_result_ty)) Common.invariant("container encoder writer result type differed from the callback result type");
        if (kind == .record and !self.sameType(GuardedList.at(writer_args, 1), str_ty)) Common.invariant("record encoder field name argument was not Str");
        if (kind == .dict) {
            const key_writer_fn = self.builder.functionShape(GuardedList.at(writer_args, 1), "dict encoder key writer was not a function");
            const key_writer_args = self.builder.program.types.span(key_writer_fn.args);
            if (key_writer_args.len != 1) Common.invariant("dict encoder key writer had an unexpected arity");
            if (!self.sameType(GuardedList.at(key_writer_args, 0), state_ty)) Common.invariant("dict encoder key writer state type differed from the encoder state type");
            if (!self.sameType(key_writer_fn.ret, result_ty)) Common.invariant("dict encoder key writer result type differed from the encoder result type");
        }

        const value_writer_ty = GuardedList.at(writer_args, expected_writer_arity - 1);
        const value_writer_fn = self.builder.functionShape(value_writer_ty, "container encoder value writer was not a function");
        const value_writer_args = self.builder.program.types.span(value_writer_fn.args);
        if (value_writer_args.len != 1) Common.invariant("container encoder value writer had an unexpected arity");
        if (!self.sameType(GuardedList.at(value_writer_args, 0), state_ty)) Common.invariant("container encoder value writer state type differed from the encoder state type");
        if (!self.sameType(value_writer_fn.ret, result_ty)) Common.invariant("container encoder value writer result type differed from the encoder result type");

        return .{
            .lookup = lookup,
            .callable_ty = callable_ty,
            .state_ty = state_ty,
            .result_ty = result_ty,
            .container_state_ty = container_state_ty,
            .container_result_ty = container_result_ty,
            .writer_ty = writer_ty,
            .body_ty = body_ty,
        };
    }

    fn lowerEncodeContainerMethodCall(
        self: *BodyContext,
        method: EncodeContainerMethod,
        args: []const DraftExprId,
    ) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = method.result_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(method.lookup, method.callable_ty, .synthesize)),
                .args = try self.addExprSpan(args),
                .captures = try self.methodTargetCaptureSpan(method.lookup),
            } },
        });
    }

    fn lowerGeneratedEncoderCallbackLambda(
        self: *BodyContext,
        lambda_ty: Type.TypeId,
        args: []const BodyTypedLocal,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const source_fn_ty = self.generated_encoder_source_fn_ty orelse
            Common.invariant("generated encoder callback requested outside generated encoder lowering");
        const source_expr = self.generated_encoder_source_expr orelse
            Common.invariant("generated encoder callback source expression was missing");
        const lambda_index = self.generated_encoder_lambda_index;
        self.generated_encoder_lambda_index += 1;
        const fn_id = try self.addFn(.{
            .fn_def = .{ .encoder_for_runtime = .{
                .owner = self.owner_template,
                .expr = source_expr,
            } },
            .source_fn_ty = source_fn_ty,
            .source_fn_key = generatedEncoderCallbackKey(self.current_fn_key, source_expr, lambda_index),
            .mono_fn_ty = lambda_ty,
            .evidence_digest = Ast.fnEvidenceDigest(&.{}, &.{}, null),
        });
        return try self.addExpr(.{ .ty = lambda_ty, .data = .{ .lambda = .{
            .fn_id = .{ .draft = fn_id },
            .args = try self.addTypedLocalSpan(args),
            .body = body,
        } } });
    }

    fn lowerEncodeValueThunk(
        self: *BodyContext,
        value_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const thunk_ty = try self.encodeValueThunkType(state_ty, ret_ty);
        const state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = blk: {
            const demand_scope = try self.enterCallableBodyDemandScope(&.{state_ty}, &.{ value_ty, encoding_ty });
            defer demand_scope.leave();
            break :blk try self.lowerEncodeShapeHelperCall(
                value_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                try self.localExpr(state_local, state_ty),
                state_ty,
                ret_ty,
                precomputed_plan,
            );
        };
        return try self.lowerGeneratedEncoderCallbackLambda(
            thunk_ty,
            &.{.{ .local = state_local, .ty = state_ty }},
            body,
        );
    }

    fn lowerEncodeShapeHelperCall(
        self: *BodyContext,
        value_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const def_id = try self.encodeShapeDefForType(
            value_ty,
            encoding_ty,
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        var plan_inputs = try self.serializationPlanInputs(.encoder, value_ty, encoding_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.builder.primitiveType(.str);
        const arg_tys = try self.allocator.alloc(Type.TypeId, 3 + plan_inputs.locals.items.len);
        defer self.allocator.free(arg_tys);
        const args = try self.allocator.alloc(DraftExprId, arg_tys.len);
        defer self.allocator.free(args);
        arg_tys[0] = value_ty;
        arg_tys[1] = state_ty;
        arg_tys[2] = encoding_ty;
        args[0] = value_expr;
        args[1] = state_expr;
        args[2] = encoding_expr;
        for (plan_inputs.locals.items, 0..) |local, index| {
            arg_tys[3 + index] = str_ty;
            args[3 + index] = try self.localExpr(local, str_ty);
        }
        const fn_ty = try self.functionType(arg_tys, ret_ty);
        const callee = try self.addExpr(.{
            .ty = fn_ty,
            .data = .{ .def_ref = .{ .draft = def_id } },
        });
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_value = .{
                .callee = callee,
                .args = try self.addExprSpan(args),
            } },
        });
    }

    fn encodeShapeDefForType(
        self: *BodyContext,
        value_ty: Type.TypeId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftDefId {
        const address = GeneratedEncoderDefAddress{
            .value_ty = @intFromEnum(value_ty),
            .encoding_ty = @intFromEnum(encoding_ty),
            .state_ty = @intFromEnum(state_ty),
            .result_ty = @intFromEnum(ret_ty),
        };
        if (self.encoder_defs.get(address)) |entry| return entry.id();

        const def_id = try self.draft.reserveDef(self.draft.current_owner);
        try self.encoder_defs.put(address, .{ .reserved = def_id });

        var plan_inputs = try self.serializationPlanInputs(.encoder, value_ty, encoding_ty, precomputed_plan);
        defer plan_inputs.deinit(self.allocator);
        const str_ty = try self.builder.primitiveType(.str);
        var helper_plan: ?SerializationHelperPlan = if (precomputed_plan) |plan|
            try self.cloneSerializationHelperPlan(plan, &plan_inputs, str_ty)
        else
            null;
        defer if (helper_plan) |*plan| plan.deinit(self.allocator);

        const value_local = try self.addLocal(self.builder.symbols.fresh(), value_ty);
        const state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const encoding_local = try self.addLocal(self.builder.symbols.fresh(), encoding_ty);
        const body = try self.lowerEncodeShapeToState(
            value_ty,
            try self.localExpr(value_local, value_ty),
            try self.localExpr(encoding_local, encoding_ty),
            encoding_ty,
            try self.localExpr(state_local, state_ty),
            state_ty,
            ret_ty,
            if (helper_plan) |*plan| &plan.plan else null,
        );
        const args = try self.allocator.alloc(BodyTypedLocal, 3 + plan_inputs.locals.items.len);
        defer self.allocator.free(args);
        args[0] = .{ .local = value_local, .ty = value_ty };
        args[1] = .{ .local = state_local, .ty = state_ty };
        args[2] = .{ .local = encoding_local, .ty = encoding_ty };
        if (helper_plan) |*plan| {
            @memcpy(args[3..], plan.args);
        } else if (plan_inputs.locals.items.len != 0) {
            Common.invariant("structural encoder helper had plan inputs without a precomputed plan");
        }
        self.draft.setDef(def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .fn_id = null,
            .args = try self.addTypedLocalSpan(args),
            .body = .{ .roc = body },
            .ret = try self.draftTypeCell(ret_ty),
        });
        try self.encoder_defs.put(address, .{ .ready = def_id });
        return def_id;
    }

    fn lowerEncodeTupleToState(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const method = try self.resolveEncodeContainerMethod("encode_tuple", .tuple, encoding_ty, state_ty, ret_ty);
        const body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const element_writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
        const body = blk: {
            const value_ty = try self.exprType(value_expr);
            const demand_scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                &.{ value_ty, encoding_ty },
            );
            defer demand_scope.leave();
            break :blk try self.lowerEncodeTupleItemsFromState(
                item_tys,
                value_expr,
                encoding_expr,
                encoding_ty,
                try self.localExpr(body_state_local, method.container_state_ty),
                method,
                try self.localExpr(element_writer_local, method.writer_ty),
                0,
                precomputed_plan,
            );
        };
        const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = body_state_local, .ty = method.container_state_ty },
                .{ .local = element_writer_local, .ty = method.writer_ty },
            },
            body,
        );
        return try self.lowerEncodeContainerMethodCall(
            method,
            &.{ state_expr, try self.intLiteralExpr(@intCast(item_tys.len), u64_ty), body_lambda },
        );
    }

    fn lowerEncodeTupleItemsFromState(
        self: *BodyContext,
        item_tys: []const Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        element_writer_expr: DraftExprId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (item_index == item_tys.len) {
            return try self.tryOk(method.container_result_ty, state_expr);
        }

        const item_ty = item_tys[item_index];
        const item_expr = try self.addExpr(.{ .ty = item_ty, .data = .{ .tuple_access = .{
            .tuple = value_expr,
            .elem_index = @intCast(item_index),
        } } });
        const item_writer = try self.lowerEncodeValueThunk(
            item_ty,
            item_expr,
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const item_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = element_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, item_writer }),
            } },
        });
        const item_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest = try self.lowerEncodeTupleItemsFromState(
            item_tys,
            value_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(item_done_local, method.container_state_ty),
            method,
            element_writer_expr,
            item_index + 1,
            precomputed_plan,
        );
        return try self.sequenceEncodeTry(item_try, method.container_result_ty, item_done_local, rest, method.container_result_ty);
    }

    fn lowerEncodeListToState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const method = try self.resolveEncodeContainerMethod("encode_list", .list, encoding_ty, state_ty, ret_ty);
        const body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const element_writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
        const len_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        const index_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        const loop_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const len_value = try self.lowLevelExpr(.list_len, &.{value_expr}, u64_ty);
        const loop_expr = blk: {
            const value_ty = try self.exprType(value_expr);
            const demand_scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                &.{ value_ty, encoding_ty, u64_ty },
            );
            defer demand_scope.leave();
            const loop_body = try self.lowerEncodeListLoopBody(
                elem_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                method,
                len_local,
                index_local,
                loop_state_local,
                try self.localExpr(element_writer_local, method.writer_ty),
                precomputed_plan,
            );
            const params = [_]BodyTypedLocal{
                .{ .local = index_local, .ty = u64_ty },
                .{ .local = loop_state_local, .ty = method.container_state_ty },
            };
            const initial_values = [_]DraftExprId{
                try self.intLiteralExpr(0, u64_ty),
                try self.localExpr(body_state_local, method.container_state_ty),
            };
            break :blk try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .loop_ = .{
                .params = try self.addTypedLocalSpan(&params),
                .initial_values = try self.addExprSpan(&initial_values),
                .body = loop_body,
            } } });
        };
        const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = body_state_local, .ty = method.container_state_ty },
                .{ .local = element_writer_local, .ty = method.writer_ty },
            },
            loop_expr,
        );
        const encode_list = try self.lowerEncodeContainerMethodCall(
            method,
            &.{ state_expr, try self.localExpr(len_local, u64_ty), body_lambda },
        );
        return try self.wrapLet(len_local, u64_ty, len_value, encode_list, ret_ty);
    }

    fn lowerEncodeSetToState(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        set_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const list_ty = try self.listType(elem_ty);
        const list_expr = try self.lowerSetToList(set_ty, list_ty, value_expr);
        return try self.lowerEncodeListToState(elem_ty, list_expr, encoding_expr, encoding_ty, state_expr, state_ty, ret_ty, precomputed_plan);
    }

    fn lowerEncodeDictToState(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        dict_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const entry_ty = try self.tupleType(&.{ key_ty, value_ty });
        const entries_ty = try self.listType(entry_ty);
        const entries_expr = try self.lowerDictToList(dict_ty, entries_ty, value_expr);
        const entries_local = try self.addLocal(self.builder.symbols.fresh(), entries_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const method = try self.resolveEncodeContainerMethod("encode_dict", .dict, encoding_ty, state_ty, ret_ty);
        const body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const field_writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
        const len_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        const index_local = try self.addLocal(self.builder.symbols.fresh(), u64_ty);
        const loop_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const len_value = try self.lowLevelExpr(.list_len, &.{try self.localExpr(entries_local, entries_ty)}, u64_ty);
        const loop_expr = blk: {
            const demand_scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                &.{ entries_ty, encoding_ty, u64_ty },
            );
            defer demand_scope.leave();
            const loop_body = try self.lowerEncodeDictLoopBody(
                key_ty,
                value_ty,
                entry_ty,
                try self.localExpr(entries_local, entries_ty),
                encoding_expr,
                encoding_ty,
                method,
                len_local,
                index_local,
                loop_state_local,
                try self.localExpr(field_writer_local, method.writer_ty),
                precomputed_plan,
            );
            const params = [_]BodyTypedLocal{
                .{ .local = index_local, .ty = u64_ty },
                .{ .local = loop_state_local, .ty = method.container_state_ty },
            };
            const initial_values = [_]DraftExprId{
                try self.intLiteralExpr(0, u64_ty),
                try self.localExpr(body_state_local, method.container_state_ty),
            };
            break :blk try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .loop_ = .{
                .params = try self.addTypedLocalSpan(&params),
                .initial_values = try self.addExprSpan(&initial_values),
                .body = loop_body,
            } } });
        };
        const body_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = body_state_local, .ty = method.container_state_ty },
                .{ .local = field_writer_local, .ty = method.writer_ty },
            },
            loop_expr,
        );
        const encode_dict = try self.lowerEncodeContainerMethodCall(
            method,
            &.{ state_expr, try self.localExpr(len_local, u64_ty), body_lambda },
        );
        const with_len = try self.wrapLet(len_local, u64_ty, len_value, encode_dict, ret_ty);
        return try self.wrapLet(entries_local, entries_ty, entries_expr, with_len, ret_ty);
    }

    fn lowerEncodeDictLoopBody(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        entry_ty: Type.TypeId,
        entries_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        method: EncodeContainerMethod,
        len_local: DraftLocalId,
        index_local: DraftLocalId,
        loop_state_local: DraftLocalId,
        field_writer_expr: DraftExprId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const len_expr = try self.localExpr(len_local, u64_ty);
        const done_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, len_expr }, bool_ty);
        const finish_body = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .break_ = try self.tryOk(method.container_result_ty, try self.localExpr(loop_state_local, method.container_state_ty)) },
        });

        const step = try self.lowerEncodeDictEntry(
            key_ty,
            value_ty,
            entry_ty,
            entries_expr,
            encoding_expr,
            encoding_ty,
            method,
            index_local,
            loop_state_local,
            field_writer_expr,
            precomputed_plan,
        );
        return try self.ifExpr(done_cond, finish_body, step, method.container_result_ty);
    }

    fn lowerEncodeDictEntry(
        self: *BodyContext,
        key_ty: Type.TypeId,
        value_ty: Type.TypeId,
        entry_ty: Type.TypeId,
        entries_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        method: EncodeContainerMethod,
        index_local: DraftLocalId,
        loop_state_local: DraftLocalId,
        field_writer_expr: DraftExprId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const entry_expr = try self.lowLevelExpr(.list_get_unsafe, &.{ entries_expr, index_expr }, entry_ty);
        const key_expr = try self.addExpr(.{ .ty = key_ty, .data = .{ .tuple_access = .{
            .tuple = entry_expr,
            .elem_index = 0,
        } } });
        const entry_expr_for_value = try self.lowLevelExpr(.list_get_unsafe, &.{ entries_expr, index_expr }, entry_ty);
        const item_value_expr = try self.addExpr(.{ .ty = value_ty, .data = .{ .tuple_access = .{
            .tuple = entry_expr_for_value,
            .elem_index = 1,
        } } });

        const key_writer = try self.lowerEncodeDictKeyThunk(
            key_ty,
            key_expr,
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const value_writer = try self.lowerEncodeValueThunk(
            value_ty,
            item_value_expr,
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const value_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = field_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(loop_state_local, method.container_state_ty),
                    key_writer,
                    value_writer,
                }),
            } },
        });
        const value_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const next_index = try self.lowLevelExpr(.num_plus, &.{ index_expr, try self.intLiteralExpr(1, u64_ty) }, u64_ty);
        const continue_expr = try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                next_index,
                try self.localExpr(value_done_local, method.container_state_ty),
            }),
        } } });
        return try self.sequenceEncodeTry(value_try, method.container_result_ty, value_done_local, continue_expr, method.container_result_ty);
    }

    /// A dict key is written by the same kind of thunk a value uses, so the
    /// format controls how a key is rendered rather than receiving a Str the
    /// driver already committed to.
    fn lowerEncodeDictKeyThunk(
        self: *BodyContext,
        key_ty: Type.TypeId,
        key_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const thunk_ty = try self.functionType(&.{state_ty}, ret_ty);
        const state_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const body = try self.lowerEncodeDictKeyToState(
            key_ty,
            key_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(state_local, state_ty),
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        return try self.lowerGeneratedEncoderCallbackLambda(
            thunk_ty,
            &.{.{ .local = state_local, .ty = state_ty }},
            body,
        );
    }

    fn lowerEncodeDictKeyToState(
        self: *BodyContext,
        key_ty: Type.TypeId,
        key_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (self.encodeDictKeyMethodName(key_ty)) |method_name| {
            return try self.lowerEncodeFormatMethod(
                method_name,
                &.{ encoding_expr, key_expr, state_expr },
                &.{ encoding_ty, key_ty, state_ty },
                encoding_ty,
                ret_ty,
            );
        }
        if (self.dictKeyUnitTags(key_ty)) |tags_span| {
            const str_ty = try self.builder.primitiveType(.str);
            const key_string = try self.lowerEncodeUnitTagDictKeyToString(tags_span, key_ty, key_expr, str_ty);
            return try self.lowerEncodeFormatMethod(
                "encode_key_str",
                &.{ encoding_expr, key_string, state_expr },
                &.{ encoding_ty, str_ty, state_ty },
                encoding_ty,
                ret_ty,
            );
        }

        // Mirrors the parse side: a key the format cannot render as a key
        // string is written by the key's own encoder, after `encode_key_start`
        // opens the key position.
        const start_expr = try self.lowerEncodeFormatMethod(
            "encode_key_start",
            &.{ encoding_expr, state_expr },
            &.{ encoding_ty, state_ty },
            encoding_ty,
            ret_ty,
        );
        const opened_local = try self.addLocal(self.builder.symbols.fresh(), state_ty);
        const key_encode = try self.lowerEncodeShapeHelperCall(
            key_ty,
            key_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(opened_local, state_ty),
            state_ty,
            ret_ty,
            precomputed_plan,
        );
        return try self.sequenceEncodeTry(start_expr, ret_ty, opened_local, key_encode, ret_ty);
    }

    fn lowerEncodeUnitTagDictKeyToString(
        self: *BodyContext,
        tags_span: Type.Span,
        key_ty: Type.TypeId,
        key_expr: DraftExprId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.builder.primitiveType(.str);
        const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(tags_span));
        defer self.allocator.free(tags);
        const branches = try self.allocator.alloc(DraftBranch, tags.len);
        defer self.allocator.free(branches);
        for (tags, 0..) |tag, index| {
            if (self.builder.program.types.span(tag.payloads).len != 0) Common.invariant("dict unit tag key had payloads");
            const pat = try self.addPat(.{ .ty = key_ty, .data = .{ .tag = .{
                .name = tag.name,
                .payloads = .empty(),
            } } });
            branches[index] = .{
                .pat = pat,
                .body = try self.stringExpr(self.builder.program.names.tagLabelText(tag.name), str_ty),
            };
        }
        if (!self.sameType(ret_ty, str_ty)) Common.invariant("dict unit tag key name type was not Str");
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = key_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn lowerEncodeListLoopBody(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        method: EncodeContainerMethod,
        len_local: DraftLocalId,
        index_local: DraftLocalId,
        loop_state_local: DraftLocalId,
        element_writer_expr: DraftExprId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const len_expr = try self.localExpr(len_local, u64_ty);
        const done_cond = try self.lowLevelExpr(.num_is_eq, &.{ index_expr, len_expr }, bool_ty);
        const finish_body = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .break_ = try self.tryOk(method.container_result_ty, try self.localExpr(loop_state_local, method.container_state_ty)) },
        });

        const step = try self.lowerEncodeListElement(
            elem_ty,
            value_expr,
            encoding_expr,
            encoding_ty,
            method,
            index_local,
            loop_state_local,
            element_writer_expr,
            precomputed_plan,
        );
        return try self.ifExpr(done_cond, finish_body, step, method.container_result_ty);
    }

    fn lowerEncodeListElement(
        self: *BodyContext,
        elem_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        method: EncodeContainerMethod,
        index_local: DraftLocalId,
        loop_state_local: DraftLocalId,
        element_writer_expr: DraftExprId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const index_expr = try self.localExpr(index_local, u64_ty);
        const element_expr = try self.lowLevelExpr(.list_get_unsafe, &.{ value_expr, index_expr }, elem_ty);
        const element_local = try self.addLocal(self.builder.symbols.fresh(), elem_ty);
        const element_writer = try self.lowerEncodeValueThunk(
            elem_ty,
            try self.localExpr(element_local, elem_ty),
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const element_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = element_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{
                    try self.localExpr(loop_state_local, method.container_state_ty),
                    element_writer,
                }),
            } },
        });
        const element_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const next_index = try self.lowLevelExpr(.num_plus, &.{ index_expr, try self.intLiteralExpr(1, u64_ty) }, u64_ty);
        const continue_expr = try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .continue_ = .{
            .values = try self.addExprSpan(&[_]DraftExprId{
                next_index,
                try self.localExpr(element_done_local, method.container_state_ty),
            }),
        } } });
        const after_element = try self.sequenceEncodeTry(element_try, method.container_result_ty, element_done_local, continue_expr, method.container_result_ty);
        return try self.wrapLet(element_local, elem_ty, element_expr, after_element, method.container_result_ty);
    }

    fn lowerEncodeNullTryToState(
        self: *BodyContext,
        info: TryNullInfo,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const try_info = self.tryInfo(shape_ty);

        const ok_payload_local = try self.addLocal(self.builder.symbols.fresh(), info.ok_payload_ty);
        const ok_payload_pat = try self.bindPat(ok_payload_local, info.ok_payload_ty);
        const ok_backing_pat = try self.addPat(.{ .ty = try_info.backing_ty, .data = .{ .tag = .{
            .name = try_info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_pat = try self.addPat(.{ .ty = shape_ty, .data = .{ .nominal = ok_backing_pat } });
        const ok_body = try self.lowerEncodeShapeToState(
            info.ok_payload_ty,
            try self.localExpr(ok_payload_local, info.ok_payload_ty),
            encoding_expr,
            encoding_ty,
            state_expr,
            state_ty,
            ret_ty,
            precomputed_plan,
        );

        const null_tag = self.monoTagByText(info.err_ty, "Null");
        if (self.builder.program.types.span(null_tag.payloads).len != 0) Common.invariant("JSON Null marker unexpectedly had payloads");
        const null_payload_pat = try self.addPat(.{ .ty = info.err_ty, .data = .{ .tag = .{
            .name = null_tag.name,
            .payloads = .empty(),
        } } });
        const err_backing_pat = try self.addPat(.{ .ty = try_info.backing_ty, .data = .{ .tag = .{
            .name = try_info.err_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{null_payload_pat}),
        } } });
        const err_pat = try self.addPat(.{ .ty = shape_ty, .data = .{ .nominal = err_backing_pat } });
        const err_body = try self.lowerEncodeFormatMethod("encode_null", &.{state_expr}, &.{state_ty}, encoding_ty, ret_ty);

        const branches = [_]DraftBranch{
            .{ .pat = ok_pat, .body = ok_body },
            .{ .pat = err_pat, .body = err_body },
        };
        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = value_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn lowerEncodeRecordToState(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        if (!self.sameType(ret_info.ok_ty, state_ty)) Common.invariant("encoder_for record return Ok type differed from state type");

        const record_fields = try GuardedList.dupe(self.allocator, Type.Field, switch (self.builder.shapeContent(shape_ty)) {
            .record => |span| self.builder.program.types.fieldSpan(span),
            .zst => self.builder.program.types.fieldSpan(.empty()),
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased => Common.invariant("encoder_for record requested for a non-record shape"),
        });
        defer self.allocator.free(record_fields);

        const str_ty = try self.builder.primitiveType(.str);
        var owned_renamed_field_locals: ?[]DraftLocalId = null;
        defer if (owned_renamed_field_locals) |locals| self.allocator.free(locals);
        var owned_renamed_field_values: ?[]DraftExprId = null;
        defer if (owned_renamed_field_values) |values| self.allocator.free(values);

        const precomputed = if (precomputed_plan) |plan| self.parserPlanGet(plan, shape_ty) else null;
        const renamed_field_locals = if (precomputed) |record| blk: {
            if (record.renamed_field_locals.len != record_fields.len) Common.invariant("encoder_for precomputed renamed field arity differed from record field count");
            break :blk record.renamed_field_locals;
        } else blk: {
            const locals = try self.allocator.alloc(DraftLocalId, record_fields.len);
            const values = try self.allocator.alloc(DraftExprId, record_fields.len);
            owned_renamed_field_locals = locals;
            owned_renamed_field_values = values;
            for (record_fields, 0..) |field, index| {
                locals[index] = try self.addLocal(self.builder.symbols.fresh(), str_ty);
                values[index] = try self.renamedRecordFieldNameExpr(encoding_expr, encoding_ty, field, str_ty);
            }
            break :blk locals;
        };

        const u64_ty = try self.builder.primitiveType(.u64);
        const method = try self.resolveEncodeContainerMethod("encode_record", .record, encoding_ty, state_ty, ret_ty);
        const body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const field_writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
        const fields_body = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            if (record_fields.len != 0) {
                try capture_tys.append(self.allocator, try self.exprType(value_expr));
                try capture_tys.append(self.allocator, encoding_ty);
                for (renamed_field_locals) |_| try capture_tys.append(self.allocator, str_ty);
            }
            const demand_scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                capture_tys.items,
            );
            defer demand_scope.leave();
            break :blk try self.lowerEncodeRecordFieldNamesFrom(
                shape_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                try self.localExpr(body_state_local, method.container_state_ty),
                method,
                precomputed_plan,
                record_fields,
                renamed_field_locals,
                try self.localExpr(field_writer_local, method.writer_ty),
                0,
            );
        };
        const fields_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = body_state_local, .ty = method.container_state_ty },
                .{ .local = field_writer_local, .ty = method.writer_ty },
            },
            fields_body,
        );
        var body = try self.lowerEncodeContainerMethodCall(
            method,
            &.{ state_expr, try self.intLiteralExpr(@intCast(record_fields.len), u64_ty), fields_lambda },
        );
        if (owned_renamed_field_values) |renamed_field_values| {
            var index = renamed_field_locals.len;
            while (index > 0) {
                index -= 1;
                body = try self.wrapLet(renamed_field_locals[index], str_ty, renamed_field_values[index], body, ret_ty);
            }
        }
        return body;
    }

    fn lowerEncodeRecordFieldNamesFrom(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        record_fields: []const Type.Field,
        renamed_field_locals: []const DraftLocalId,
        field_writer_expr: DraftExprId,
        field_index: usize,
    ) Allocator.Error!DraftExprId {
        if (field_index >= record_fields.len) {
            return try self.tryOk(method.container_result_ty, state_expr);
        }

        const field = record_fields[field_index];
        const field_value_expr = try self.addFieldAccessExpr(value_expr, field.name, field.ty);

        if (try self.missingTryInfo(field.ty)) |optional_info| {
            return try self.lowerEncodeOptionalRecordFieldFrom(
                shape_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                state_expr,
                method,
                precomputed_plan,
                record_fields,
                renamed_field_locals,
                field_writer_expr,
                field_index,
                field_value_expr,
                optional_info,
            );
        }

        if (self.builder.optionalFieldSlot(field.ty)) |slot| {
            return try self.lowerEncodeSlotOptionalRecordFieldFrom(
                shape_ty,
                value_expr,
                encoding_expr,
                encoding_ty,
                state_expr,
                method,
                precomputed_plan,
                record_fields,
                renamed_field_locals,
                field_writer_expr,
                field_index,
                field_value_expr,
                slot,
            );
        }

        return try self.lowerEncodePresentRecordFieldFrom(
            shape_ty,
            value_expr,
            encoding_expr,
            encoding_ty,
            state_expr,
            method,
            precomputed_plan,
            record_fields,
            renamed_field_locals,
            field_writer_expr,
            field_index,
            field.ty,
            field_value_expr,
        );
    }

    fn lowerEncodePresentRecordFieldFrom(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        record_fields: []const Type.Field,
        renamed_field_locals: []const DraftLocalId,
        field_writer_expr: DraftExprId,
        field_index: usize,
        field_value_ty: Type.TypeId,
        field_value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const value_try = try self.lowerEncodePresentRecordField(
            encoding_expr,
            encoding_ty,
            state_expr,
            method,
            precomputed_plan,
            renamed_field_locals,
            field_writer_expr,
            field_index,
            field_value_ty,
            field_value_expr,
        );
        const after_value_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest_body = try self.lowerEncodeRecordFieldNamesFrom(
            shape_ty,
            value_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(after_value_local, method.container_state_ty),
            method,
            precomputed_plan,
            record_fields,
            renamed_field_locals,
            field_writer_expr,
            field_index + 1,
        );
        return try self.sequenceEncodeTry(value_try, method.container_result_ty, after_value_local, rest_body, method.container_result_ty);
    }

    fn lowerEncodePresentRecordField(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        renamed_field_locals: []const DraftLocalId,
        field_writer_expr: DraftExprId,
        field_index: usize,
        field_value_ty: Type.TypeId,
        field_value_expr: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.builder.primitiveType(.str);
        const renamed_field_expr = try self.localExpr(renamed_field_locals[field_index], str_ty);
        const value_writer = try self.lowerEncodeValueThunk(
            field_value_ty,
            field_value_expr,
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const value_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = field_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, renamed_field_expr, value_writer }),
            } },
        });
        return value_try;
    }

    fn lowerEncodeOptionalRecordFieldFrom(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        record_fields: []const Type.Field,
        renamed_field_locals: []const DraftLocalId,
        field_writer_expr: DraftExprId,
        field_index: usize,
        field_value_expr: DraftExprId,
        optional_info: TryInfo,
    ) Allocator.Error!DraftExprId {
        const field_ty = record_fields[field_index].ty;
        const try_info = self.tryInfo(field_ty);
        if (!self.sameType(try_info.ok_ty, optional_info.ok_ty)) Common.invariant("optional encoder_for field Ok payload differed from optional info");
        if (!self.sameType(try_info.err_ty, optional_info.err_ty)) Common.invariant("optional encoder_for field Err payload differed from optional info");

        const ok_payload_local = try self.addLocal(self.builder.symbols.fresh(), optional_info.ok_ty);
        const ok_payload_pat = try self.bindPat(ok_payload_local, optional_info.ok_ty);
        const ok_backing_pat = try self.addPat(.{ .ty = optional_info.backing_ty, .data = .{ .tag = .{
            .name = try_info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = ok_backing_pat },
        });
        const ok_body = try self.lowerEncodePresentRecordField(
            encoding_expr,
            encoding_ty,
            state_expr,
            method,
            precomputed_plan,
            renamed_field_locals,
            field_writer_expr,
            field_index,
            optional_info.ok_ty,
            try self.localExpr(ok_payload_local, optional_info.ok_ty),
        );

        const missing_tag = self.monoTagByText(optional_info.err_ty, "Missing");
        if (self.builder.program.types.span(missing_tag.payloads).len != 0) Common.invariant("Missing marker unexpectedly had payloads");
        const missing_payload_pat = try self.addPat(.{ .ty = optional_info.err_ty, .data = .{ .tag = .{
            .name = missing_tag.name,
            .payloads = .empty(),
        } } });
        const missing_backing_pat = try self.addPat(.{ .ty = optional_info.backing_ty, .data = .{ .tag = .{
            .name = try_info.err_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{missing_payload_pat}),
        } } });
        const missing_pat = try self.addPat(.{
            .ty = field_ty,
            .data = .{ .nominal = missing_backing_pat },
        });
        const missing_body = try self.tryOk(method.container_result_ty, state_expr);

        var branches = std.ArrayList(DraftBranch).empty;
        defer branches.deinit(self.allocator);
        try branches.append(self.allocator, .{ .pat = ok_pat, .body = ok_body });
        try branches.append(self.allocator, .{ .pat = missing_pat, .body = missing_body });

        const field_try = try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .match_ = .{
            .scrutinee = field_value_expr,
            .branches = try self.addBranchSpan(branches.items),
        } } });
        const after_field_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest_body = try self.lowerEncodeRecordFieldNamesFrom(
            shape_ty,
            value_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(after_field_local, method.container_state_ty),
            method,
            precomputed_plan,
            record_fields,
            renamed_field_locals,
            field_writer_expr,
            field_index + 1,
        );
        return try self.sequenceEncodeTry(field_try, method.container_result_ty, after_field_local, rest_body, method.container_result_ty);
    }

    /// The `?:` slot-kind sibling of `lowerEncodeOptionalRecordFieldFrom`
    /// (design.md "Field Kinds (All-Dynamic Optional Fields)"): a `#Present`
    /// slot encodes its payload with the ordinary present-field emitter and a
    /// `#Missing` slot omits the field, passing the encoder state through
    /// untouched. The slot union is structural (no nominal wrapper), so the
    /// match is directly on the reserved-label tags.
    fn lowerEncodeSlotOptionalRecordFieldFrom(
        self: *BodyContext,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        precomputed_plan: ?*const ParserPrecomputedPlan,
        record_fields: []const Type.Field,
        renamed_field_locals: []const DraftLocalId,
        field_writer_expr: DraftExprId,
        field_index: usize,
        field_value_expr: DraftExprId,
        slot: Builder.OptionalSlotInfo,
    ) Allocator.Error!DraftExprId {
        const field_ty = record_fields[field_index].ty;

        const payload_local = try self.addLocal(self.builder.symbols.fresh(), slot.payload_ty);
        const payload_pat = try self.bindPat(payload_local, slot.payload_ty);
        const present_pat = try self.addPat(.{ .ty = field_ty, .data = .{ .tag = .{
            .name = slot.present_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
        } } });
        const present_body = try self.lowerEncodePresentRecordField(
            encoding_expr,
            encoding_ty,
            state_expr,
            method,
            precomputed_plan,
            renamed_field_locals,
            field_writer_expr,
            field_index,
            slot.payload_ty,
            try self.localExpr(payload_local, slot.payload_ty),
        );

        const missing_pat = try self.addPat(.{ .ty = field_ty, .data = .{ .tag = .{
            .name = slot.missing_tag.name,
            .payloads = .empty(),
        } } });
        const missing_body = try self.tryOk(method.container_result_ty, state_expr);

        var branches = std.ArrayList(DraftBranch).empty;
        defer branches.deinit(self.allocator);
        try branches.append(self.allocator, .{ .pat = present_pat, .body = present_body });
        try branches.append(self.allocator, .{ .pat = missing_pat, .body = missing_body });

        const field_try = try self.addExpr(.{ .ty = method.container_result_ty, .data = .{ .match_ = .{
            .scrutinee = field_value_expr,
            .branches = try self.addBranchSpan(branches.items),
        } } });
        const after_field_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest_body = try self.lowerEncodeRecordFieldNamesFrom(
            shape_ty,
            value_expr,
            encoding_expr,
            encoding_ty,
            try self.localExpr(after_field_local, method.container_state_ty),
            method,
            precomputed_plan,
            record_fields,
            renamed_field_locals,
            field_writer_expr,
            field_index + 1,
        );
        return try self.sequenceEncodeTry(field_try, method.container_result_ty, after_field_local, rest_body, method.container_result_ty);
    }

    fn lowerEncodeTagUnionToState(
        self: *BodyContext,
        tags_span: Type.Span,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        const tags = try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(tags_span));
        defer self.allocator.free(tags);
        if (tags.len == 0) Common.invariant("encoder_for selected an empty tag union");

        const value_ty = try self.exprType(value_expr);
        const branches = try self.allocator.alloc(DraftBranch, tags.len);
        defer self.allocator.free(branches);

        for (tags, 0..) |tag, tag_index| {
            const payload_tys = try GuardedList.dupe(self.allocator, Type.TypeId, self.builder.program.types.span(tag.payloads));
            defer self.allocator.free(payload_tys);

            const payload_pats = try self.allocator.alloc(DraftPatId, payload_tys.len);
            defer self.allocator.free(payload_pats);
            const payload_exprs = try self.allocator.alloc(DraftExprId, payload_tys.len);
            defer self.allocator.free(payload_exprs);

            for (payload_tys, 0..) |payload_ty, payload_index| {
                const payload_local = try self.addLocal(self.builder.symbols.fresh(), payload_ty);
                payload_pats[payload_index] = try self.bindPat(payload_local, payload_ty);
                payload_exprs[payload_index] = try self.localExpr(payload_local, payload_ty);
            }

            const pat = try self.addPat(.{ .ty = value_ty, .data = .{ .tag = .{
                .name = tag.name,
                .payloads = try self.addPatSpan(payload_pats),
            } } });
            branches[tag_index] = .{
                .pat = pat,
                .body = try self.lowerEncodeTagUnionBranchToState(
                    tag,
                    payload_exprs,
                    payload_tys,
                    encoding_expr,
                    encoding_ty,
                    state_expr,
                    state_ty,
                    ret_ty,
                    precomputed_plan,
                ),
            };
        }

        return try self.addExpr(.{ .ty = ret_ty, .data = .{ .match_ = .{
            .scrutinee = value_expr,
            .branches = try self.addBranchSpan(branches),
        } } });
    }

    fn lowerEncodeTagUnionBranchToState(
        self: *BodyContext,
        tag: Type.Tag,
        payload_exprs: []const DraftExprId,
        payload_tys: []const Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (payload_exprs.len != payload_tys.len) Common.invariant("tag union encode payload arity mismatch");

        const tag_name_expr = try self.stringExpr(self.builder.program.names.tagLabelText(tag.name), try self.builder.primitiveType(.str));
        const u64_ty = try self.builder.primitiveType(.u64);
        const method = try self.resolveEncodeContainerMethod("encode_tag", .tag, encoding_ty, state_ty, ret_ty);
        const body_state_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const element_writer_local = try self.addLocal(self.builder.symbols.fresh(), method.writer_ty);
        const body = blk: {
            var capture_tys = std.ArrayList(Type.TypeId).empty;
            defer capture_tys.deinit(self.allocator);
            try capture_tys.appendSlice(self.allocator, payload_tys);
            try capture_tys.append(self.allocator, encoding_ty);
            const demand_scope = try self.enterCallableBodyDemandScope(
                &.{ method.container_state_ty, method.writer_ty },
                capture_tys.items,
            );
            defer demand_scope.leave();
            break :blk try self.lowerEncodeTagPayloadsFromState(
                payload_exprs,
                payload_tys,
                encoding_expr,
                encoding_ty,
                try self.localExpr(body_state_local, method.container_state_ty),
                method,
                try self.localExpr(element_writer_local, method.writer_ty),
                0,
                precomputed_plan,
            );
        };
        const payloads_lambda = try self.lowerGeneratedEncoderCallbackLambda(
            method.body_ty,
            &.{
                .{ .local = body_state_local, .ty = method.container_state_ty },
                .{ .local = element_writer_local, .ty = method.writer_ty },
            },
            body,
        );
        return try self.lowerEncodeContainerMethodCall(
            method,
            &.{ state_expr, tag_name_expr, try self.intLiteralExpr(@intCast(payload_tys.len), u64_ty), payloads_lambda },
        );
    }

    fn lowerEncodeTagPayloadsFromState(
        self: *BodyContext,
        payload_exprs: []const DraftExprId,
        payload_tys: []const Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        element_writer_expr: DraftExprId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (item_index == payload_tys.len) {
            return try self.tryOk(method.container_result_ty, state_expr);
        }

        const item_writer = try self.lowerEncodeValueThunk(
            payload_tys[item_index],
            payload_exprs[item_index],
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const item_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = element_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, item_writer }),
            } },
        });
        const item_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest = try self.lowerEncodeTagPayloadsFromState(
            payload_exprs,
            payload_tys,
            encoding_expr,
            encoding_ty,
            try self.localExpr(item_done_local, method.container_state_ty),
            method,
            element_writer_expr,
            item_index + 1,
            precomputed_plan,
        );
        return try self.sequenceEncodeTry(item_try, method.container_result_ty, item_done_local, rest, method.container_result_ty);
    }

    fn lowerEncodePayloadArrayItemsFromState(
        self: *BodyContext,
        payload_exprs: []const DraftExprId,
        payload_tys: []const Type.TypeId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        method: EncodeContainerMethod,
        element_writer_expr: DraftExprId,
        item_index: usize,
        precomputed_plan: ?*const ParserPrecomputedPlan,
    ) Allocator.Error!DraftExprId {
        if (item_index == payload_tys.len) {
            return try self.tryOk(method.container_result_ty, state_expr);
        }

        const item_writer = try self.lowerEncodeValueThunk(
            payload_tys[item_index],
            payload_exprs[item_index],
            encoding_expr,
            encoding_ty,
            method.state_ty,
            method.result_ty,
            precomputed_plan,
        );
        const item_try = try self.addExpr(.{
            .ty = method.container_result_ty,
            .data = .{ .call_value = .{
                .callee = element_writer_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ state_expr, item_writer }),
            } },
        });
        const item_done_local = try self.addLocal(self.builder.symbols.fresh(), method.container_state_ty);
        const rest = try self.lowerEncodePayloadArrayItemsFromState(
            payload_exprs,
            payload_tys,
            encoding_expr,
            encoding_ty,
            try self.localExpr(item_done_local, method.container_state_ty),
            method,
            element_writer_expr,
            item_index + 1,
            precomputed_plan,
        );
        return try self.sequenceEncodeTry(item_try, method.container_result_ty, item_done_local, rest, method.container_result_ty);
    }

    fn encodeRecordFieldPayloadType(self: *BodyContext, field_ty: Type.TypeId) Allocator.Error!Type.TypeId {
        if (try self.missingTryInfo(field_ty)) |optional_info| {
            return optional_info.ok_ty;
        }
        if (self.builder.optionalFieldSlot(field_ty)) |slot| {
            return slot.payload_ty;
        }
        return field_ty;
    }

    fn encodeRecordFieldTypeIsSupported(self: *BodyContext, field_ty: Type.TypeId, encoding_ty: Type.TypeId) Allocator.Error!bool {
        return try self.encodeFieldTypeIsSupported(try self.encodeRecordFieldPayloadType(field_ty), encoding_ty);
    }

    fn encodeTagUnionTypeIsSupported(self: *BodyContext, tags_span: Type.Span, encoding_ty: Type.TypeId) Allocator.Error!bool {
        const tags = self.builder.program.types.tagSpan(tags_span);
        if (tags.len == 0) return false;
        for (0..GuardedList.borrowLen(tags)) |tag_index| {
            const tag = GuardedList.at(tags, tag_index);
            const payloads = self.builder.program.types.span(tag.payloads);
            for (0..GuardedList.borrowLen(payloads)) |payload_index| {
                const payload_ty = GuardedList.at(payloads, payload_index);
                if (!try self.encodeFieldTypeIsSupported(payload_ty, encoding_ty)) return false;
            }
        }
        return true;
    }

    fn lowerCustomEncoderForState(
        self: *BodyContext,
        lookup: MethodLookup,
        shape_ty: Type.TypeId,
        value_expr: DraftExprId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const prepared = self.frozenCustomCodecCall(.encoder, shape_ty, lookup);
        const runtime_fn_ty = try self.builder.program.types.add(.{ .func = .{
            .args = try self.builder.program.types.addSpan(&.{ shape_ty, state_ty }),
            .ret = ret_ty,
        } });
        const callable_mono_ty = prepared.callable_ty;
        const encode_fn = self.builder.functionShape(callable_mono_ty, "custom encoder_for target was not a function");
        const encode_arg_tys = self.builder.program.types.span(encode_fn.args);
        if (encode_arg_tys.len != 1) Common.invariant("custom encoder_for target had an unexpected arity");
        if (!self.sameType(GuardedList.at(encode_arg_tys, 0), encoding_ty)) Common.invariant("custom encoder_for encoding type differed from input encoding type");
        if (!self.sameType(encode_fn.ret, runtime_fn_ty)) Common.invariant("custom encoder_for runtime function type differed from expected type");

        const encoder_expr = try self.addExpr(.{
            .ty = runtime_fn_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(prepared.callee),
                .args = try self.addExprSpan(&[_]DraftExprId{encoding_expr}),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_value = .{
                .callee = encoder_expr,
                .args = try self.addExprSpan(&[_]DraftExprId{ value_expr, state_expr }),
            } },
        });
    }

    fn lowerEncodeFormatMethod(
        self: *BodyContext,
        method_name: []const u8,
        arg_exprs: []const DraftExprId,
        arg_tys: []const Type.TypeId,
        encoding_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(encoding_ty, method_name);
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, arg_tys, ret_ty);
        const encode_fn = self.builder.functionShape(callable_mono_ty, "encoder_for target method was not a function");
        const actual_arg_tys = self.builder.program.types.span(encode_fn.args);
        if (actual_arg_tys.len != arg_tys.len) Common.invariant("encoder_for target method had an unexpected arity");
        for (0..GuardedList.borrowLen(actual_arg_tys)) |index| {
            const actual = GuardedList.at(actual_arg_tys, index);
            const expected = arg_tys[index];
            if (!self.sameType(actual, expected)) Common.invariant("encoder_for target method argument type differed from expected type");
        }
        if (!self.sameType(encode_fn.ret, ret_ty)) Common.invariant("encoder_for target method return type differed from expected type");
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(arg_exprs),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn lowerParseFormatMethod(
        self: *BodyContext,
        method_name: []const u8,
        arg_exprs: []const DraftExprId,
        arg_tys: []const Type.TypeId,
        encoding_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(encoding_ty, method_name);
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, arg_tys, ret_ty);
        const parse_fn = self.builder.functionShape(callable_mono_ty, "parser_for target method was not a function");
        const actual_arg_tys = self.builder.program.types.span(parse_fn.args);
        if (actual_arg_tys.len != arg_tys.len) Common.invariant("parser_for target method had an unexpected arity");
        for (0..GuardedList.borrowLen(actual_arg_tys)) |index| {
            const actual = GuardedList.at(actual_arg_tys, index);
            const expected = arg_tys[index];
            if (!self.sameType(actual, expected)) Common.invariant("parser_for target method argument type differed from expected type");
        }
        if (!self.sameType(parse_fn.ret, ret_ty)) Common.invariant("parser_for target method return type differed from expected type");
        return try self.addExpr(.{
            .ty = ret_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(arg_exprs),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        });
    }

    fn cloneNamedTypeWithArgs(
        self: *BodyContext,
        template_ty: Type.TypeId,
        args: []const Type.TypeId,
        backing_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const template = switch (self.builder.program.types.get(template_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("compiler helper expected a named template type"),
        };
        return try self.cloneNamedTypeWithBackingAuthority(
            template_ty,
            args,
            backing_ty,
            template.backing.?.authority,
        );
    }

    fn cloneNamedTypeWithBackingAuthority(
        self: *BodyContext,
        template_ty: Type.TypeId,
        args: []const Type.TypeId,
        backing_ty: Type.TypeId,
        authority: Type.BackingAuthority,
    ) Allocator.Error!Type.TypeId {
        const template = switch (self.builder.program.types.get(template_ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("compiler helper expected a named template type"),
        };
        return try self.builder.program.types.add(.{ .named = .{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.builder.program.types.addSpan(args),
            .backing = .{ .ty = backing_ty, .use = template.backing.?.use, .authority = authority },
            .declared_order = template.declared_order,
        } });
    }

    const TryNullInfo = struct {
        backing_ty: Type.TypeId,
        ok_payload_ty: Type.TypeId,
        err_ty: Type.TypeId,
    };

    const TryInfo = struct {
        backing_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
        ok_tag: Type.Tag,
        err_tag: Type.Tag,
    };

    const RecordFieldMatchMode = enum {
        direct,
        exact,
        caseless,
    };

    const StaticFieldLane = struct {
        offset: u32,
        active_len: u32,
    };

    fn recordPresenceWordCount(field_count: usize) usize {
        return (field_count + 63) / 64;
    }

    fn recordPresenceWordIndex(field_index: usize) usize {
        return field_index / 64;
    }

    fn recordPresenceMask(field_index: usize) u64 {
        return @as(u64, 1) << @as(u6, @intCast(field_index % 64));
    }

    fn selectStaticFieldLane(lengths: []const u32, texts: []const []const u8, length: u32) StaticFieldLane {
        if (lengths.len != texts.len) Common.invariant("record parser dispatch text arity did not match field lengths");
        if (length == 0 or length > 24) Common.invariant("static field lane requested for an unsupported field length");

        var group_count: usize = 0;
        for (lengths, texts) |field_len, text| {
            if (field_len != length) continue;
            if (text.len != length) Common.invariant("record parser dispatch text length did not match precomputed length");
            group_count += 1;
        }
        if (group_count == 0) Common.invariant("static field lane requested for an empty length bucket");

        var best = StaticFieldLane{ .offset = 0, .active_len = @min(length, 8) };
        var best_distinct: usize = 0;
        const offsets = [_]u32{ 0, 8, 16 };
        for (offsets) |offset| {
            if (offset >= length) continue;
            const active_len: u32 = @min(length - offset, 8);
            var distinct: usize = 0;
            for (texts, lengths, 0..) |text, field_len, text_index| {
                if (field_len != length) continue;
                const word = staticFieldLaneWord(text, offset, active_len);
                var seen = false;
                var previous: usize = 0;
                while (previous < text_index) : (previous += 1) {
                    if (lengths[previous] != length) continue;
                    if (staticFieldLaneWord(texts[previous], offset, active_len) == word) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) distinct += 1;
            }
            if (distinct > best_distinct) {
                best = .{ .offset = offset, .active_len = active_len };
                best_distinct = distinct;
                if (distinct == group_count) break;
            }
        }
        return best;
    }

    fn staticFieldLaneWord(text: []const u8, offset: u32, active_len: u32) u64 {
        if (active_len > 8) Common.invariant("static field lane exceeded one word");
        const offset_usize: usize = @intCast(offset);
        const active_len_usize: usize = @intCast(active_len);
        if (offset_usize > text.len or active_len_usize > text.len - offset_usize) Common.invariant("static field lane exceeded field text");
        var word: u64 = 0;
        var index: u32 = 0;
        while (index < active_len) : (index += 1) {
            word |= @as(u64, text[offset_usize + @as(usize, @intCast(index))]) << @intCast(index * 8);
        }
        return word;
    }

    fn fieldLengthAlreadyHandled(lengths: []const u32, index: usize, length: u32) bool {
        var i = index + 1;
        while (i < lengths.len) : (i += 1) {
            if (lengths[i] == length) return true;
        }
        return false;
    }

    fn tryInfo(self: *BodyContext, try_ty: Type.TypeId) TryInfo {
        const backing_ty = self.builder.namedBackingType(try_ty) orelse Common.invariant("expected a named Try type");
        const ok_tag = self.monoTagByText(backing_ty, "Ok");
        const err_tag = self.monoTagByText(backing_ty, "Err");
        const ok_payloads = self.builder.program.types.span(ok_tag.payloads);
        const err_payloads = self.builder.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) Common.invariant("Try tags must each carry one payload");
        return .{
            .backing_ty = backing_ty,
            .ok_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = GuardedList.at(err_payloads, 0),
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn tryInfoOptional(self: *BodyContext, try_ty: Type.TypeId) ?TryInfo {
        const backing_ty = self.builder.namedBackingType(try_ty) orelse return null;
        const ok_tag = self.monoTagByTextOptional(backing_ty, "Ok") orelse return null;
        const err_tag = self.monoTagByTextOptional(backing_ty, "Err") orelse return null;
        const ok_payloads = self.builder.program.types.span(ok_tag.payloads);
        const err_payloads = self.builder.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) return null;
        return .{
            .backing_ty = backing_ty,
            .ok_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = GuardedList.at(err_payloads, 0),
            .ok_tag = ok_tag,
            .err_tag = err_tag,
        };
    }

    fn missingTryInfo(self: *BodyContext, try_ty: Type.TypeId) Allocator.Error!?TryInfo {
        if (try self.typeHasParserForTarget(try_ty)) return null;
        const info = self.tryInfoOptional(try_ty) orelse return null;
        return if (self.typeIsExactUnitTagUnion(info.err_ty, "Missing")) info else null;
    }

    fn tryTypeLike(
        self: *BodyContext,
        template_try_ty: Type.TypeId,
        ok_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!Type.TypeId {
        const template_backing = self.builder.namedBackingType(template_try_ty) orelse Common.invariant("Try template type had no backing");
        const template_tags = switch (self.builder.shapeContent(template_backing)) {
            .tag_union => |span| try GuardedList.dupe(self.allocator, Type.Tag, self.builder.program.types.tagSpan(span)),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => Common.invariant("Try template backing type was not a tag union"),
        };
        defer self.allocator.free(template_tags);
        const tags = try self.allocator.alloc(Type.Tag, template_tags.len);
        defer self.allocator.free(tags);

        var found_ok = false;
        var found_err = false;
        for (template_tags, 0..) |tag, index| {
            const text = self.builder.program.names.tagLabelText(tag.name);
            const payload_ty = if (Ident.textEql(text, "Ok")) blk: {
                found_ok = true;
                break :blk ok_ty;
            } else if (Ident.textEql(text, "Err")) blk: {
                found_err = true;
                break :blk err_ty;
            } else {
                Common.invariant("Try backing type contained an unexpected tag");
            };
            tags[index] = .{
                .name = tag.name,
                .checked_name = tag.checked_name,
                .payloads = try self.builder.program.types.addSpan(&[_]Type.TypeId{payload_ty}),
            };
        }
        if (!found_ok or !found_err) Common.invariant("Try backing type did not contain Ok and Err tags");

        const backing_ty = try self.builder.program.types.add(.{ .tag_union = try self.builder.program.types.addTagVariants(&self.builder.program.names, tags) });
        const args = [_]Type.TypeId{ ok_ty, err_ty };
        return try self.cloneNamedTypeWithArgs(template_try_ty, &args, backing_ty);
    }

    fn tryOk(self: *BodyContext, try_ty: Type.TypeId, value_expr: DraftExprId) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const value_ty = try self.exprType(value_expr);
        if (!self.sameType(value_ty, info.ok_ty)) Common.invariant("Try.Ok payload type differed from Try Ok type");
        const backing_expr = try self.addExpr(.{
            .ty = info.backing_ty,
            .data = .{ .tag = .{
                .name = info.ok_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{value_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = try_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn tryErr(self: *BodyContext, try_ty: Type.TypeId, err_expr: DraftExprId) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const err_ty = try self.exprType(err_expr);
        if (!self.sameType(err_ty, info.err_ty)) Common.invariant("Try.Err payload type differed from Try Err type");
        const backing_expr = try self.addExpr(.{
            .ty = info.backing_ty,
            .data = .{ .tag = .{
                .name = info.err_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{err_expr}),
            } },
        });
        return try self.addExpr(.{
            .ty = try_ty,
            .data = .{ .nominal = backing_expr },
        });
    }

    fn sequenceTry(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        ok_local: DraftLocalId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const out_info = self.tryInfo(out_try_ty);
        if (!self.sameType(info.err_ty, out_info.err_ty)) Common.invariant("sequenced Try error type differed from output Try error type");

        return try self.addExpr(.{ .ty = out_try_ty, .data = .{ .try_sequence = .{
            .try_expr = try_expr,
            .ok_local = ok_local,
            .err_is_cold = true,
            .ok_body = ok_body,
        } } });
    }

    fn sequenceEncodeTry(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        ok_local: DraftLocalId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const out_info = self.tryInfo(out_try_ty);
        if (!self.sameType(info.err_ty, out_info.err_ty)) Common.invariant("sequenced encoder_for Try error type differed from output Try error type");

        if (!self.typeIsClosedEmptyTagUnion(info.err_ty)) {
            return try self.sequenceTry(try_expr, try_ty, ok_local, ok_body, out_try_ty);
        }

        const ok_payload_pat = try self.bindPat(ok_local, info.ok_ty);
        const ok_backing_pat = try self.addPat(.{ .ty = info.backing_ty, .data = .{ .tag = .{
            .name = info.ok_tag.name,
            .payloads = try self.addPatSpan(&[_]DraftPatId{ok_payload_pat}),
        } } });
        const ok_pat = try self.addPat(.{ .ty = try_ty, .data = .{ .nominal = ok_backing_pat } });
        const branches = [_]DraftBranch{.{ .pat = ok_pat, .body = ok_body }};
        return try self.addExpr(.{ .ty = out_try_ty, .data = .{ .match_ = .{
            .scrutinee = try_expr,
            .branches = try self.addBranchSpan(&branches),
        } } });
    }

    fn typeIsClosedEmptyTagUnion(self: *BodyContext, ty: Type.TypeId) bool {
        var current = ty;
        while (true) switch (self.builder.program.types.get(current)) {
            .named => |named| {
                const backing = named.backing orelse return false;
                if (backing.use != .inspectable) return false;
                current = backing.ty;
            },
            .tag_union => |span| return self.builder.program.types.tagSpan(span).len == 0,
            .primitive, .record, .tuple, .list, .box, .func, .erased, .zst => return false,
        };
    }

    fn sequenceTryRecord(
        self: *BodyContext,
        try_expr: DraftExprId,
        try_ty: Type.TypeId,
        value_local: DraftLocalId,
        value_field: names.RecordFieldNameId,
        rest_local: DraftLocalId,
        rest_field: names.RecordFieldNameId,
        ok_body: DraftExprId,
        out_try_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const info = self.tryInfo(try_ty);
        const out_info = self.tryInfo(out_try_ty);
        if (!self.sameType(info.err_ty, out_info.err_ty)) Common.invariant("sequenced Try record error type differed from output Try error type");
        if (!self.sameType(self.recordFieldType(info.ok_ty, value_field), try self.localType(value_local))) {
            Common.invariant("sequenced Try record value local type differed from Ok record field");
        }
        if (!self.sameType(self.recordFieldType(info.ok_ty, rest_field), try self.localType(rest_local))) {
            Common.invariant("sequenced Try record rest local type differed from Ok record field");
        }

        return try self.addExpr(.{ .ty = out_try_ty, .data = .{ .try_record_sequence = .{
            .try_expr = try_expr,
            .value_local = value_local,
            .value_field = value_field,
            .rest_local = rest_local,
            .rest_field = rest_field,
            .err_is_cold = true,
            .ok_body = ok_body,
        } } });
    }

    fn recordFieldType(self: *BodyContext, record_ty: Type.TypeId, field_name: names.RecordFieldNameId) Type.TypeId {
        return switch (self.builder.shapeContent(record_ty)) {
            .record => |fields_span| {
                const fields = self.builder.program.types.fieldSpan(fields_span);
                for (0..GuardedList.borrowLen(fields)) |index| {
                    const field = GuardedList.at(fields, index);
                    if (field.name == field_name) return field.ty;
                }
                Common.invariant("record field was absent from monotype record");
            },
            .primitive, .named, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("record field operation expected a record type"),
        };
    }

    fn parseFieldTypeIsSupported(self: *BodyContext, ty: Type.TypeId, allow_missing: bool) Allocator.Error!bool {
        if (self.parseScalarMethodName(ty) != null) return true;
        if (try self.missingTryInfo(ty)) |info| {
            if (!allow_missing) return false;
            return try self.parseFieldTypeIsSupported(info.ok_ty, false);
        }
        if (self.builder.optionalFieldSlot(ty)) |slot| {
            if (!allow_missing) return false;
            return try self.parseFieldTypeIsSupported(slot.payload_ty, false);
        }
        if (self.tryNullInfo(ty)) |info| {
            return try self.parseFieldTypeIsSupported(info.ok_payload_ty, false);
        }
        if ((try self.customParserLookup(ty)) != null) return true;
        if (self.builder.nominalExprBackingType(ty)) |backing_ty| {
            if (self.parseScalarMethodName(backing_ty) != null) return true;
        }
        if (self.setPayloadType(ty)) |payload_ty| return try self.parseFieldTypeIsSupported(payload_ty, false);
        if (self.dictEntryShape(ty)) |dict| {
            const key_ok = self.dictKeyIsStringRendered(dict.key_ty) or try self.parseFieldTypeIsSupported(dict.key_ty, false);
            return key_ok and try self.parseFieldTypeIsSupported(dict.value_ty, false);
        }
        return switch (self.builder.shapeContent(ty)) {
            .list => |elem_ty| try self.parseFieldTypeIsSupported(elem_ty, false),
            .box => |payload_ty| try self.parseFieldTypeIsSupported(payload_ty, false),
            .tuple => |span| blk: {
                const elem_tys = self.builder.program.types.span(span);
                for (0..GuardedList.borrowLen(elem_tys)) |index| {
                    const elem_ty = GuardedList.at(elem_tys, index);
                    if (!try self.parseFieldTypeIsSupported(elem_ty, false)) break :blk false;
                }
                break :blk true;
            },
            .record => |fields_span| blk: {
                const fields = self.builder.program.types.fieldSpan(fields_span);
                for (0..GuardedList.borrowLen(fields)) |index| {
                    const field = GuardedList.at(fields, index);
                    if (!try self.parseFieldTypeIsSupported(field.ty, true)) break :blk false;
                }
                break :blk true;
            },
            .tag_union => |tags_span| blk: {
                const tags = self.builder.program.types.tagSpan(tags_span);
                if (tags.len == 0) break :blk false;
                for (0..GuardedList.borrowLen(tags)) |tag_index| {
                    const tag = GuardedList.at(tags, tag_index);
                    const payload_tys = self.builder.program.types.span(tag.payloads);
                    for (0..GuardedList.borrowLen(payload_tys)) |payload_index| {
                        const payload_ty = GuardedList.at(payload_tys, payload_index);
                        if (!try self.parseFieldTypeIsSupported(payload_ty, false)) break :blk false;
                    }
                }
                break :blk true;
            },
            .zst => true,
            .primitive, .named, .func, .erased => false,
        };
    }

    fn encodeFieldTypeIsSupported(self: *BodyContext, ty: Type.TypeId, encoding_ty: Type.TypeId) Allocator.Error!bool {
        if (self.encodeScalarMethodName(ty) != null) return true;
        if (self.tryNullInfo(ty)) |info| {
            return try self.encodeFieldTypeIsSupported(info.ok_payload_ty, encoding_ty);
        }
        if ((try self.customEncoderForLookup(ty)) != null) return true;
        if (self.builder.nominalExprBackingType(ty)) |backing_ty| {
            if (self.encodeScalarMethodName(backing_ty) != null) return true;
        }
        if (self.setPayloadType(ty)) |payload_ty| return try self.encodeFieldTypeIsSupported(payload_ty, encoding_ty);
        if (self.dictEntryShape(ty)) |dict| {
            const key_ok = self.dictKeyIsStringRendered(dict.key_ty) or try self.encodeFieldTypeIsSupported(dict.key_ty, encoding_ty);
            return key_ok and try self.encodeFieldTypeIsSupported(dict.value_ty, encoding_ty);
        }
        return switch (self.builder.shapeContent(ty)) {
            .list => |elem_ty| try self.encodeFieldTypeIsSupported(elem_ty, encoding_ty),
            .box => |payload_ty| try self.encodeFieldTypeIsSupported(payload_ty, encoding_ty),
            .tuple => |span| blk: {
                const elem_tys = self.builder.program.types.span(span);
                for (0..GuardedList.borrowLen(elem_tys)) |index| {
                    const elem_ty = GuardedList.at(elem_tys, index);
                    if (!try self.encodeFieldTypeIsSupported(elem_ty, encoding_ty)) break :blk false;
                }
                break :blk true;
            },
            .record => |fields_span| blk: {
                const fields = self.builder.program.types.fieldSpan(fields_span);
                for (0..GuardedList.borrowLen(fields)) |index| {
                    const field = GuardedList.at(fields, index);
                    if (!try self.encodeRecordFieldTypeIsSupported(field.ty, encoding_ty)) break :blk false;
                }
                break :blk true;
            },
            .tag_union => |tags_span| try self.encodeTagUnionTypeIsSupported(tags_span, encoding_ty),
            .zst => true,
            .primitive, .named, .func, .erased => false,
        };
    }

    fn customParserLookup(self: *BodyContext, ty: Type.TypeId) Allocator.Error!?MethodLookup {
        const named = switch (self.builder.program.types.get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        if (named.builtin_owner != null) return null;
        switch (named.kind) {
            .nominal, .@"opaque" => {},
            .alias => return null,
        }
        const owner = methodOwnerFromType(&self.builder.program.types, ty) orelse
            Common.invariant("custom named parser type had no method owner");
        const lookup = (try self.builder.lookupMethodTargetByName(self.method_scope, owner, "parser_for")) orelse
            Common.invariant("checked method registry is missing custom parser_for target");
        return switch (lookup.target.kind) {
            .structural => |kind| if (kind == .parser) null else Common.invariant("parser_for lookup resolved to a different structural target"),
            .procedure, .local_proc => lookup,
        };
    }

    fn customCodecLookupAtNode(
        self: *BodyContext,
        node: NodeId,
        kind: CodecKind,
    ) Allocator.Error!?MethodLookup {
        const named = switch (self.graph.content(node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return null,
        };
        if (named.builtin_owner != null) return null;
        switch (named.kind) {
            .nominal, .@"opaque" => {},
            .alias => return null,
        }
        const owner = self.methodOwnerFromNode(node) orelse
            Common.invariant("custom codec graph node had no checked method owner");
        const method_name = switch (kind) {
            .parser => "parser_for",
            .encoder => "encoder_for",
        };
        const lookup = (try self.builder.lookupMethodTargetByName(self.method_scope, owner, method_name)) orelse return null;
        return switch (lookup.target.kind) {
            .structural => |structural_kind| switch (kind) {
                .parser => if (structural_kind == .parser) null else Common.invariant("parser_for lookup resolved to a different structural target"),
                .encoder => if (structural_kind == .encoder) null else Common.invariant("encoder_for lookup resolved to a different structural target"),
            },
            .procedure, .local_proc => lookup,
        };
    }

    const GraphTryPayloads = struct {
        ok: NodeId,
        err: NodeId,
    };

    fn graphTryPayloads(self: *BodyContext, try_node: NodeId) Allocator.Error!GraphTryPayloads {
        const named = switch (self.graph.content(try_node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("codec method result was not a named Try type"),
        };
        const backing = named.backing orelse Common.invariant("codec Try type had no checked backing");
        const ok_name = try self.builder.program.names.internTagLabel("Ok");
        const err_name = try self.builder.program.names.internTagLabel("Err");
        const tags = (try self.graph.tagRowNodes(backing.node)).tags;
        const ok = graphTagByName(tags, ok_name) orelse Common.invariant("codec Try backing had no Ok tag");
        const err = graphTagByName(tags, err_name) orelse Common.invariant("codec Try backing had no Err tag");
        if (ok.payloads.len != 1 or err.payloads.len != 1) {
            Common.invariant("codec Try tags did not have one payload each");
        }
        return .{ .ok = ok.payloads[0], .err = err.payloads[0] };
    }

    fn graphParserResultNodes(
        self: *BodyContext,
        try_node: NodeId,
    ) Allocator.Error!struct { value: NodeId, rest: NodeId, err: NodeId } {
        const payloads = try self.graphTryPayloads(try_node);
        const value_name = try self.builder.program.names.internRecordFieldLabel("value");
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        return .{
            .value = try self.graph.recordFieldNode(payloads.ok, value_name),
            .rest = try self.graph.recordFieldNode(payloads.ok, rest_name),
            .err = payloads.err,
        };
    }

    /// Relate the payloads of a custom parser's declared errors to the
    /// enclosing structural parser row without equating the two rows. The
    /// custom parser result is exact; emission explicitly injects that row into
    /// the enclosing result, whose additional structural errors remain owned by
    /// the enclosing parser producer.
    fn relateCustomParserErrorInjection(
        self: *BodyContext,
        source_err: NodeId,
        target_err: NodeId,
    ) Allocator.Error!void {
        const source_tags = (try self.graph.tagRowNodes(source_err)).tags;
        const target_tags = (try self.graph.tagRowNodes(target_err)).tags;
        for (source_tags) |source_tag| {
            const target_tag = graphTagByName(target_tags, source_tag.name) orelse
                Common.invariant("custom parser error row was not included in the enclosing parser row");
            if (source_tag.payloads.len != target_tag.payloads.len) {
                Common.invariant("custom parser error injection changed tag payload arity");
            }
            for (source_tag.payloads, target_tag.payloads) |source_payload, target_payload| {
                try relateRequestComponent(self.graph, source_payload, target_payload);
            }
        }
    }

    fn preparedCodecCallExists(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        lookup: MethodLookup,
    ) bool {
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr or prepared.kind != kind) continue;
            if (!self.methodLookupEql(prepared.lookup, lookup)) continue;
            if (self.graph.sameClass(prepared.shape_node, shape_node)) return true;
        }
        return false;
    }

    fn prepareStructuralCodecCallsAtNode(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        var added_relation = false;
        if (kind == .parser) {
            var required_error_seen = collections.DenseMap(NodeId, void).init(self.allocator);
            defer required_error_seen.deinit();
            if (try self.graphParserShapeNeedsRequiredFieldError(shape_node, &required_error_seen)) {
                added_relation = try self.ensureGraphParserMissingRequiredFieldError(boundary_callable_node);
            }
            const runtime = try self.graph.functionNodes((try self.graph.functionNodes(boundary_callable_node)).ret);
            const outer_result = try self.graphParserResultNodes(runtime.ret);
            var invalid_value_seen = collections.DenseMap(NodeId, void).init(self.allocator);
            defer invalid_value_seen.deinit();
            if (try self.graphParserShapeNeedsInvalidValue(shape_node, outer_result.err, &invalid_value_seen)) {
                added_relation = try self.prepareParserInvalidValueCodecCall(
                    boundary_expr,
                    shape_node,
                    boundary_callable_node,
                ) or added_relation;
            }
        }
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        return try self.prepareCustomCodecCallsAtNode(
            boundary_expr,
            kind,
            shape_node,
            boundary_callable_node,
            &seen,
        ) or added_relation;
    }

    /// `ParseTagUnionSpec.parse` decodes only the selected tag's payloads; the
    /// enclosing format method has already consumed the tag name. Preparing a
    /// full tag-union parser here would re-enter the same format method before
    /// the current synthetic parser is registered.
    fn prepareParseTagUnionPayloadCodecCalls(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        union_node: NodeId,
        err_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        var added_relation = false;
        var missing_required_field_ready = false;

        var required_error_seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer required_error_seen.deinit();
        var invalid_value_seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer invalid_value_seen.deinit();
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();

        for ((try self.graph.tagRowNodes(union_node)).tags) |tag| {
            for (tag.payloads) |payload| {
                if (try self.graphParserShapeNeedsRequiredFieldError(payload, &required_error_seen)) {
                    if (!missing_required_field_ready) {
                        const added_missing = try self.ensureGraphParserMissingRequiredFieldError(boundary_callable_node);
                        added_relation = added_missing or added_relation;
                        missing_required_field_ready = added_missing or try self.graphRowHasTag(err_node, "MissingRequiredField");
                        if (!missing_required_field_ready) {
                            // Checker-closed row without the report: emission
                            // crash-maps this decode, so no format-method
                            // relations may widen it.
                            return false;
                        }
                    }
                }
                if (try self.graphParserShapeNeedsInvalidValue(payload, err_node, &invalid_value_seen)) {
                    added_relation = try self.prepareParserInvalidValueCodecCall(
                        boundary_expr,
                        payload,
                        boundary_callable_node,
                    ) or added_relation;
                }
                added_relation = try self.prepareCustomCodecCallsAtNode(
                    boundary_expr,
                    .parser,
                    payload,
                    boundary_callable_node,
                    &seen,
                ) or added_relation;
            }
        }
        return added_relation;
    }

    fn sealedPreparedCodecCallsForBoundary(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        sealer: *GraphTypeFinals,
    ) Allocator.Error!FrozenPreparedCodecCalls {
        var out = std.ArrayList(FrozenPreparedCodecCall).empty;
        errdefer out.deinit(self.allocator);
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr) continue;
            try out.append(self.allocator, .{
                .kind = prepared.kind,
                .purpose = prepared.purpose,
                .shape_ty = try sealer.sealNode(prepared.shape_node),
                .lookup = prepared.lookup,
                .callable_ty = try sealer.sealNode(prepared.callable_node),
                .callee = prepared.callee,
            });
        }
        return try FrozenPreparedCodecCalls.init(self.allocator, try out.toOwnedSlice(self.allocator));
    }

    fn resolvedPreparedCodecCallsForBoundary(
        self: *BodyContext,
        boundary_expr: DraftExprId,
    ) Allocator.Error!FrozenPreparedCodecCalls {
        var out = std.ArrayList(FrozenPreparedCodecCall).empty;
        errdefer out.deinit(self.allocator);
        for (self.draft.prepared_codec_calls.items) |prepared| {
            if (prepared.boundary_expr != boundary_expr) continue;
            try out.append(self.allocator, .{
                .kind = prepared.kind,
                .purpose = prepared.purpose,
                .shape_ty = try self.currentPhaseTypeForNode(prepared.shape_node),
                .lookup = prepared.lookup,
                .callable_ty = try self.currentPhaseTypeForNode(prepared.callable_node),
                .callee = prepared.callee,
            });
        }
        return try FrozenPreparedCodecCalls.init(self.allocator, try out.toOwnedSlice(self.allocator));
    }

    fn prepareCustomCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
        lookup: MethodLookup,
    ) Allocator.Error!bool {
        if (self.preparedCodecCallExists(boundary_expr, kind, shape_node, lookup)) return false;

        const boundary_callable = try self.graph.functionNodes(boundary_callable_node);
        if (boundary_callable.args.len != 1) Common.invariant("structural codec constructor did not have one encoding argument");
        const encoding_node = boundary_callable.args[0];
        const runtime = try self.graph.functionNodes(boundary_callable.ret);

        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instNode(lookup.target.callable_ty);
        if (lookup.instantiation) |instantiation| {
            var edge_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, instantiation.view, self.method_scope, self.owner_template, self.graph, self.draft);
            defer edge_ctx.deinit();
            try relateFunctionRequestInterface(self.graph, target_node, try edge_ctx.instNode(instantiation.callable_ty));
        }
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 1) Common.invariant("custom codec target did not have one encoding argument");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        const target_runtime = try self.graph.functionNodes(target.ret);

        switch (kind) {
            .parser => {
                if (runtime.args.len != 1 or target_runtime.args.len != 1) {
                    Common.invariant("custom parser runtime did not have one state argument");
                }
                try relateRequestComponent(self.graph, target_runtime.args[0], runtime.args[0]);
                const outer_result = try self.graphParserResultNodes(runtime.ret);
                const target_result = try self.graphParserResultNodes(target_runtime.ret);
                try relateRequestComponent(self.graph, target_result.value, shape_node);
                try relateRequestComponent(self.graph, target_result.rest, outer_result.rest);
                try self.relateCustomParserErrorInjection(target_result.err, outer_result.err);
            },
            .encoder => {
                if (runtime.args.len != 2 or target_runtime.args.len != 2) {
                    Common.invariant("custom encoder runtime did not have value and state arguments");
                }
                try relateRequestComponent(self.graph, target_runtime.args[0], shape_node);
                try relateRequestComponent(self.graph, target_runtime.args[1], runtime.args[1]);
                try relateRequestComponent(self.graph, target_runtime.ret, runtime.ret);
            },
        }
        const callee = try self.methodTargetCalleeAtNode(lookup, target_node, .synthesize);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = kind,
            .purpose = .custom,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = target_node,
            .callee = callee,
        });
        return true;
    }

    fn prepareRenameRecordFieldCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural parser constructor did not have one encoding argument");
        const encoding_node = boundary.args[0];
        const owner = self.methodOwnerFromNode(encoding_node) orelse
            Common.invariant("structural parser encoding node had no checked method owner");
        const lookup = try self.withLocalProcContext((try self.builder.lookupMethodTargetByName(self.method_scope, owner, "rename_field")) orelse
            Common.invariant("checked parser encoding registry was missing rename_field"));
        if (self.preparedCodecCallExists(boundary_expr, kind, shape_node, lookup)) return false;

        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instNode(lookup.target.callable_ty);
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 2) Common.invariant("rename_field target did not have two arguments");
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[1], str_node);
        try relateRequestComponent(self.graph, target.ret, str_node);

        const callee = try self.methodTargetCalleeAtNode(lookup, target_node, .synthesize);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = kind,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = target_node,
            .callee = callee,
        });
        return true;
    }

    fn prepareEncodeContainerCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
        method_name: []const u8,
    ) Allocator.Error!bool {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural encoder constructor did not have one encoding argument");
        const runtime = try self.graph.functionNodes(boundary.ret);
        if (runtime.args.len != 2) Common.invariant("structural encoder runtime did not have value and state arguments");
        const encoding_node = boundary.args[0];
        const state_node = runtime.args[1];
        const owner = self.methodOwnerFromNode(encoding_node) orelse
            Common.invariant("structural encoder encoding node had no checked method owner");
        const lookup = try self.withLocalProcContext((try self.builder.lookupMethodTargetByName(self.method_scope, owner, method_name)) orelse
            Common.invariant("checked encoder registry was missing a container method"));
        if (self.preparedCodecCallExists(boundary_expr, .encoder, shape_node, lookup)) return false;

        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instNode(lookup.target.callable_ty);
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len < 1) Common.invariant("container encoder target had no state argument");
        try relateRequestComponent(self.graph, target.args[0], state_node);
        try relateRequestComponent(self.graph, target.ret, runtime.ret);

        const callee = try self.methodTargetCalleeAtNode(lookup, target_node, .synthesize);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = .encoder,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = target_node,
            .callee = callee,
        });
        return true;
    }

    /// The one shape a derived codec reads out of a builtin keyed container:
    /// a dict's value, or a set's element. Null for anything else.
    /// The shapes a derived codec reads out of a builtin keyed container: a
    /// dict's value and its key, or a set's element. Empty for anything else.
    ///
    /// A key the format renders as a key string is read by the `parse_key_*`
    /// and `encode_key_*` methods rather than by a shape codec, so only a key
    /// that needs its own codec is included.
    fn graphBuiltinContainerShapeNodes(self: *BodyContext, node: NodeId, buf: *[2]NodeId) []const NodeId {
        const named = switch (self.graph.content(node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return &.{},
        };
        const owner = named.builtin_owner orelse return &.{};
        switch (owner) {
            .dict => {
                if (named.args.len != 2) Common.invariant("builtin Dict node had an unexpected arity");
                buf[0] = named.args[1];
                if (self.graphNodeIsStringRenderedDictKey(named.args[0])) return buf[0..1];
                buf[1] = named.args[0];
                return buf[0..2];
            },
            .set => {
                if (named.args.len != 1) Common.invariant("builtin Set node had an unexpected arity");
                buf[0] = named.args[0];
                return buf[0..1];
            },
            .list, .box, .fields, .field, .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => return &.{},
        }
    }

    /// Whether a dict key node is one the `parse_key_*`/`encode_key_*` methods
    /// read, which is every key kind that renders as a key string.
    fn graphNodeIsStringRenderedDictKey(self: *BodyContext, node: NodeId) bool {
        switch (self.graph.content(node)) {
            .tag_union => |row| {
                for (row.tags) |tag| {
                    if (tag.payloads.len != 0) return false;
                }
                return true;
            },
            .named => |named| {
                const owner = named.builtin_owner orelse return false;
                return switch (owner) {
                    .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => true,
                    .list, .box, .dict, .set, .fields, .field, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => false,
                };
            },
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        }
    }

    fn graphNodeIsBuiltinTry(self: *BodyContext, node: NodeId) bool {
        const named = switch (self.graph.content(node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        };
        return self.builder.isBuiltinTryDef(named.def);
    }

    fn graphShapeNode(self: *BodyContext, raw_node: NodeId) NodeId {
        var node = raw_node;
        while (true) {
            switch (self.graph.content(node)) {
                .named => |named| if (named.backing) |backing| {
                    node = backing.node;
                    continue;
                },
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
            }
            return node;
        }
    }

    fn appendGraphParserRecordShapes(
        self: *BodyContext,
        raw_node: NodeId,
        shapes: *std.ArrayList(NodeId),
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!void {
        const node = raw_node;
        const seen_entry = try seen.getOrPut(node);
        if (seen_entry.found_existing) return;

        if (self.graphNodeIsBuiltinTry(node)) {
            const payloads = try self.graphTryPayloads(node);
            return try self.appendGraphParserRecordShapes(payloads.ok, shapes, seen);
        }
        if ((try self.customCodecLookupAtNode(node, .parser)) != null) return;

        switch (self.graph.content(node)) {
            .list, .box => |elem| try self.appendGraphParserRecordShapes(elem, shapes, seen),
            .tuple => |items| for (items) |item| try self.appendGraphParserRecordShapes(item, shapes, seen),
            .record => {
                try shapes.append(self.allocator, node);
                for ((try self.graph.recordNodes(node)).fields) |field|
                    try self.appendGraphParserRecordShapes(field.ty, shapes, seen);
            },
            .tag_union => {
                for ((try self.graph.tagRowNodes(node)).tags) |tag|
                    for (tag.payloads) |payload|
                        try self.appendGraphParserRecordShapes(payload, shapes, seen);
            },
            .named => |named| {
                if (named.builtin_owner == .set and named.args.len == 1) {
                    try self.appendGraphParserRecordShapes(named.args[0], shapes, seen);
                } else if (named.builtin_owner == .dict and named.args.len == 2) {
                    try self.appendGraphParserRecordShapes(named.args[1], shapes, seen);
                } else if (named.backing) |backing| {
                    try self.appendGraphParserRecordShapes(backing.node, shapes, seen);
                }
            },
            .redirect => unreachable,
            .unresolved, .primitive, .empty_tag_union, .empty_record, .func, .erased, .zst => {},
        }
    }

    fn generatedParseTagUnionSpecBackingNode(
        self: *BodyContext,
        union_node: NodeId,
    ) Allocator.Error!NodeId {
        var record_shapes = std.ArrayList(NodeId).empty;
        defer record_shapes.deinit(self.allocator);
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        try self.appendGraphParserRecordShapes(union_node, &record_shapes, &seen);

        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const outer_fields = try self.graph.arena().alloc(InstField, record_shapes.items.len);
        for (record_shapes.items, outer_fields, 0..) |record_shape, *outer_field, record_index| {
            const record_fields = (try self.graph.recordNodes(record_shape)).fields;
            const inner_fields = try self.graph.arena().alloc(InstField, record_fields.len);
            for (inner_fields, 0..) |*inner_field, field_index| {
                inner_field.* = .{
                    .name = try self.generatedParseTagUnionSpecBackingFieldName(field_index),
                    .ty = str_node,
                    .default = null,
                };
            }
            outer_field.* = .{
                .name = try self.generatedParseTagUnionSpecBackingRecordFieldName(record_index),
                .ty = try self.graph.newNode(.{ .record = .{
                    .fields = inner_fields,
                    .ext = try self.graph.newNode(.empty_record),
                } }),
                .default = null,
            };
        }
        return try self.graph.newNode(.{ .record = .{
            .fields = outer_fields,
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    fn cloneGraphNamedWithBackingAuthority(
        self: *BodyContext,
        template_node: NodeId,
        args: []const NodeId,
        backing_node: NodeId,
        authority: Type.BackingAuthority,
    ) Allocator.Error!NodeId {
        const template = switch (self.graph.content(template_node)) {
            .named => |named| named,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("generated codec protocol template was not a named graph node"),
        };
        return try self.graph.newNode(.{ .named = .{
            .named_type = template.named_type,
            .def = template.def,
            .kind = template.kind,
            .builtin_owner = template.builtin_owner,
            .args = try self.graph.arena().dupe(NodeId, args),
            .backing = .{
                .node = backing_node,
                .use = (template.backing orelse Common.invariant("generated codec protocol template had no checked backing")).use,
                .authority = authority,
            },
            .declared_order = template.declared_order,
        } });
    }

    fn cloneGraphNamedWithGeneratedBacking(
        self: *BodyContext,
        template_node: NodeId,
        args: []const NodeId,
        backing_node: NodeId,
    ) Allocator.Error!NodeId {
        return try self.cloneGraphNamedWithBackingAuthority(
            template_node,
            args,
            backing_node,
            .generated_private,
        );
    }

    fn graphClosedRecord(self: *BodyContext, fields: []const InstField) Allocator.Error!NodeId {
        return try self.graph.newNode(.{ .record = .{
            .fields = try self.graph.arena().dupe(InstField, fields),
            .ext = try self.graph.newNode(.empty_record),
        } });
    }

    /// The `parse_record_field` event row at the checked-evidence boundary.
    /// `freshParseRecordFieldEventVar` in check/Check.zig builds the same row
    /// and must agree with this one.
    fn graphParseRecordEvent(
        self: *BodyContext,
        state_node: NodeId,
        field_handle_node: NodeId,
    ) Allocator.Error!NodeId {
        const rest_name = try self.builder.program.names.internRecordFieldLabel("rest");
        const field_label = try self.builder.program.names.internRecordFieldLabel("field");
        const name_label = try self.builder.program.names.internRecordFieldLabel("name");
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const field_payload = try self.graphClosedRecord(&.{
            .{ .name = field_label, .ty = field_handle_node, .default = null },
            .{ .name = rest_name, .ty = state_node, .default = null },
        });
        const try_field_payload = try self.graphClosedRecord(&.{
            .{ .name = name_label, .ty = str_node, .default = null },
            .{ .name = rest_name, .ty = state_node, .default = null },
        });
        const tag_texts = [_][]const u8{ "Continue", "Done", "Field", "TryField", "TryFieldCaseless" };
        const payloads = [_]NodeId{ state_node, state_node, field_payload, try_field_payload, try_field_payload };
        const tags = try self.graph.arena().alloc(InstTag, tag_texts.len);
        for (tag_texts, payloads, tags) |text, payload, *tag| {
            const name = try self.builder.program.names.internTagLabel(text);
            tag.* = .{
                .name = name,
                .checked_name = name,
                .payloads = try self.graph.arena().dupe(NodeId, &.{payload}),
            };
        }
        return try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
    }

    fn graphTryLike(
        self: *BodyContext,
        template_try: NodeId,
        ok_node: NodeId,
        err_node: NodeId,
    ) Allocator.Error!NodeId {
        const ok_name = try self.builder.program.names.internTagLabel("Ok");
        const err_name = try self.builder.program.names.internTagLabel("Err");
        const backing = try self.graph.newNode(.{ .tag_union = .{
            .tags = try self.graph.arena().dupe(InstTag, &.{
                .{ .name = ok_name, .checked_name = ok_name, .payloads = try self.graph.arena().dupe(NodeId, &.{ok_node}) },
                .{ .name = err_name, .checked_name = err_name, .payloads = try self.graph.arena().dupe(NodeId, &.{err_node}) },
            }),
            .ext = try self.graph.newNode(.empty_tag_union),
        } });
        return try self.cloneGraphNamedWithBackingAuthority(
            template_try,
            &.{ ok_node, err_node },
            backing,
            .checked_public,
        );
    }

    fn prepareParseRecordFieldCodecCall(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        shape_node: NodeId,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const boundary = try self.graph.functionNodes(boundary_callable_node);
        if (boundary.args.len != 1) Common.invariant("structural parser constructor did not have one encoding argument");
        const runtime = try self.graph.functionNodes(boundary.ret);
        if (runtime.args.len != 1) Common.invariant("structural parser runtime did not have one state argument");
        const encoding_node = boundary.args[0];
        const state_node = runtime.args[0];
        const outer_result = try self.graphParserResultNodes(runtime.ret);
        const owner = self.methodOwnerFromNode(encoding_node) orelse
            Common.invariant("structural parser encoding node had no checked method owner");
        const lookup = try self.withLocalProcContext((try self.builder.lookupMethodTargetByName(self.method_scope, owner, "parse_record_field")) orelse
            Common.invariant("checked parser encoding registry was missing parse_record_field"));
        if (self.preparedCodecCallExists(boundary_expr, .parser, shape_node, lookup)) return false;

        var target_ctx = try self.methodTargetContext(lookup);
        defer target_ctx.deinit();
        const target_node = try target_ctx.instNode(lookup.target.callable_ty);
        const target = try self.graph.functionNodes(target_node);
        if (target.args.len != 3) Common.invariant("parse_record_field target did not have three arguments");
        try relateRequestComponent(self.graph, target.args[0], encoding_node);
        try relateRequestComponent(self.graph, target.args[2], state_node);
        const target_try = try self.graphTryPayloads(target.ret);
        try relateRequestComponent(self.graph, target_try.err, outer_result.err);

        const field_tag_name = try self.builder.program.names.internTagLabel("Field");
        const field_tag = graphTagByName((try self.graph.tagRowNodes(target_try.ok)).tags, field_tag_name) orelse
            Common.invariant("parse_record_field event type had no Field tag");
        if (field_tag.payloads.len != 1) Common.invariant("parse_record_field Field event did not have one payload");
        const field_label = try self.builder.program.names.internRecordFieldLabel("field");
        const field_handle_template = try self.graph.recordFieldNode(field_tag.payloads[0], field_label);
        const u64_node = try self.graph.newNode(.{ .primitive = .u64 });
        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const field_handle_backing = try self.graphClosedRecord(&.{
            .{ .name = try self.builder.program.names.internRecordFieldLabel("index"), .ty = u64_node, .default = null },
            .{ .name = try self.builder.program.names.internRecordFieldLabel("name"), .ty = str_node, .default = null },
            .{ .name = try self.builder.program.names.internRecordFieldLabel("name_len"), .ty = u64_node, .default = null },
        });
        const field_handle = try self.cloneGraphNamedWithGeneratedBacking(
            field_handle_template,
            &.{shape_node},
            field_handle_backing,
        );

        const record_fields = switch (self.graph.content(self.graphShapeNode(shape_node))) {
            .zst, .empty_record => &.{},
            .record => (try self.graph.recordNodes(self.graphShapeNode(shape_node))).fields,
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .named, .empty_tag_union, .erased => Common.invariant("generated parse tag-union specification shape was not a record"),
        };
        const item_fields = try self.graph.arena().alloc(InstField, record_fields.len);
        for (item_fields, 0..) |*field, index| {
            field.* = .{
                .name = try self.generatedParseTagUnionSpecBackingFieldName(index),
                .ty = field_handle,
                .default = null,
            };
        }
        const items = try self.graphClosedRecord(item_fields);
        const fields_backing = try self.graphClosedRecord(&.{
            .{ .name = try self.builder.program.names.internRecordFieldLabel("items"), .ty = items, .default = null },
            .{ .name = try self.builder.program.names.internRecordFieldLabel("shortest_name"), .ty = u64_node, .default = null },
            .{ .name = try self.builder.program.names.internRecordFieldLabel("longest_name"), .ty = u64_node, .default = null },
        });
        const fields_node = try self.cloneGraphNamedWithGeneratedBacking(
            target.args[1],
            &.{shape_node},
            fields_backing,
        );
        const event_node = try self.graphParseRecordEvent(state_node, field_handle);
        const result_node = try self.graphTryLike(target.ret, event_node, target_try.err);
        const request_node = try functionRequestNode(
            self.graph,
            target_node,
            &.{ encoding_node, fields_node, state_node },
            result_node,
        );
        const callee = try self.methodTargetCalleeAtNode(lookup, request_node, .synthesize);
        try self.draft.prepared_codec_calls.append(self.allocator, .{
            .boundary_expr = boundary_expr,
            .kind = .parser,
            .shape_node = shape_node,
            .lookup = lookup,
            .callable_node = request_node,
            .callee = callee,
        });
        return true;
    }

