    ) Allocator.Error!bool {
        const list_node = try self.graph.newNode(.{ .list = elem_node });
        return switch (kind) {
            .parser => try self.prepareOwnedCodecMethodCall(
                boundary_expr,
                kind,
                set_node,
                set_node,
                "from_list",
                &.{list_node},
                set_node,
            ),
            .encoder => try self.prepareOwnedCodecMethodCall(
                boundary_expr,
                kind,
                set_node,
                set_node,
                "to_list",
                &.{set_node},
                list_node,
            ),
        };
    }

    fn prepareDictCollectionCodecCalls(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        dict_node: NodeId,
        key_node: NodeId,
        value_node: NodeId,
    ) Allocator.Error!bool {
        const entry_node = try self.graph.newNode(.{ .tuple = try self.graph.arena().dupe(NodeId, &.{ key_node, value_node }) });
        const entries_node = try self.graph.newNode(.{ .list = entry_node });
        return switch (kind) {
            .parser => blk: {
                const u64_node = try self.graph.newNode(.{ .primitive = .u64 });
                var added = try self.prepareOwnedCodecMethodCall(
                    boundary_expr,
                    kind,
                    dict_node,
                    dict_node,
                    "with_capacity",
                    &.{u64_node},
                    dict_node,
                );
                added = try self.prepareOwnedCodecMethodCall(
                    boundary_expr,
                    kind,
                    dict_node,
                    dict_node,
                    "insert",
                    &.{ dict_node, key_node, value_node },
                    dict_node,
                ) or added;
                break :blk added;
            },
            .encoder => try self.prepareOwnedCodecMethodCall(
                boundary_expr,
                kind,
                dict_node,
                dict_node,
                "to_list",
                &.{dict_node},
                entries_node,
            ),
        };
    }

    /// Decide the derived parser's required-field error relation from the live
    /// specialization graph. This is deliberately graph-native: unresolved
    /// rows remain producer-owned evidence until the single sealing boundary.
    fn graphParserShapeNeedsRequiredFieldError(
        self: *BodyContext,
        raw_node: NodeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        const node = raw_node;
        const entry = try seen.getOrPut(node);
        if (entry.found_existing) return false;

        if (self.graphNodeHasJsonScalarParser(node)) return false;
        if ((try self.customCodecLookupAtNode(node, .parser)) != null) return false;
        if (self.graphNodeIsBuiltinTry(node)) {
            const payloads = try self.graphTryPayloads(node);
            if (try self.graphErrorIsExactUnitTag(payloads.err, "Missing") or
                try self.graphErrorIsExactUnitTag(payloads.err, "Null"))
            {
                return try self.graphParserShapeNeedsRequiredFieldError(payloads.ok, seen);
            }
            return false;
        }

        return switch (self.graph.content(node)) {
            .list, .box => |payload| try self.graphParserShapeNeedsRequiredFieldError(payload, seen),
            .tuple => |items| blk: {
                for (items) |item| {
                    if (try self.graphParserShapeNeedsRequiredFieldError(item, seen)) break :blk true;
                }
                break :blk false;
            },
            .record => blk: {
                for ((try self.graph.recordNodes(node)).fields) |field| {
                    if (try self.graphMissingTryOkNode(field.ty)) |payload| {
                        if (try self.graphParserShapeNeedsRequiredFieldError(payload, seen)) break :blk true;
                    } else if (try self.graphOptionalFieldSlotPayload(field.ty)) |payload| {
                        // `?:` slot: an absent key parses to `#Missing`.
                        if (try self.graphParserShapeNeedsRequiredFieldError(payload, seen)) break :blk true;
                    } else if (field.default != null) {
                        // `??` field: an absent key fills the archived default.
                        if (try self.graphParserShapeNeedsRequiredFieldError(field.ty, seen)) break :blk true;
                    } else {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .tag_union => blk: {
                for ((try self.graph.tagRowNodes(node)).tags) |tag| {
                    for (tag.payloads) |payload| {
                        if (try self.graphParserShapeNeedsRequiredFieldError(payload, seen)) break :blk true;
                    }
                }
                break :blk false;
            },
            .named => |named| blk: {
                if (named.builtin_owner == .set and named.args.len == 1) {
                    break :blk try self.graphParserShapeNeedsRequiredFieldError(named.args[0], seen);
                }
                if (named.builtin_owner == .dict and named.args.len == 2) {
                    break :blk try self.graphParserShapeNeedsRequiredFieldError(named.args[1], seen);
                }
                if (named.backing) |backing| {
                    break :blk try self.graphParserShapeNeedsRequiredFieldError(backing.node, seen);
                }
                break :blk false;
            },
            .redirect => unreachable,
            .unresolved,
            .primitive,
            .empty_tag_union,
            .empty_record,
            .func,
            .erased,
            .zst,
            => false,
        };
    }

    fn graphParserShapeNeedsInvalidValue(
        self: *BodyContext,
        raw_node: NodeId,
        err_node: NodeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        const node = raw_node;
        const entry = try seen.getOrPut(node);
        if (entry.found_existing) return false;

        if (self.graphNodeHasJsonScalarParser(node)) return false;
        if ((try self.customCodecLookupAtNode(node, .parser)) != null) return false;
        if (self.graphNodeIsBuiltinTry(node)) {
            const payloads = try self.graphTryPayloads(node);
            if (try self.graphErrorIsExactUnitTag(payloads.err, "Missing") or
                try self.graphErrorIsExactUnitTag(payloads.err, "Null"))
            {
                return try self.graphParserShapeNeedsInvalidValue(payloads.ok, err_node, seen);
            }
            return false;
        }

        return switch (self.graph.content(node)) {
            .list, .box => |payload| try self.graphParserShapeNeedsInvalidValue(payload, err_node, seen),
            .tuple => true,
            .record => blk: {
                const has_missing_required_field = try self.graphRowHasTag(err_node, "MissingRequiredField");
                for ((try self.graph.recordNodes(node)).fields) |field| {
                    if (try self.graphMissingTryOkNode(field.ty)) |payload| {
                        if (try self.graphParserShapeNeedsInvalidValue(payload, err_node, seen)) break :blk true;
                    } else if (try self.graphOptionalFieldSlotPayload(field.ty)) |payload| {
                        // `?:` slot: absence is well-defined, only the present
                        // payload's shape can demand more error tags.
                        if (try self.graphParserShapeNeedsInvalidValue(payload, err_node, seen)) break :blk true;
                    } else if (field.default != null) {
                        // `??` field: absence fills the default; the value
                        // shape parses at the inline type.
                        if (try self.graphParserShapeNeedsInvalidValue(field.ty, err_node, seen)) break :blk true;
                    } else {
                        if (!has_missing_required_field) break :blk true;
                        if (try self.graphParserShapeNeedsInvalidValue(field.ty, err_node, seen)) break :blk true;
                    }
                }
                break :blk false;
            },
            .tag_union => blk: {
                for ((try self.graph.tagRowNodes(node)).tags) |tag| {
                    for (tag.payloads) |payload| {
                        if (try self.graphParserShapeNeedsInvalidValue(payload, err_node, seen)) break :blk true;
                    }
                }
                break :blk false;
            },
            .named => |named| blk: {
                if (named.builtin_owner == .set and named.args.len == 1) {
                    break :blk try self.graphParserShapeNeedsInvalidValue(named.args[0], err_node, seen);
                }
                if (named.builtin_owner == .dict and named.args.len == 2) {
                    if (try self.graphNodeIsUnitTagUnion(named.args[0])) break :blk true;
                    break :blk try self.graphParserShapeNeedsInvalidValue(named.args[1], err_node, seen);
                }
                if (named.backing) |backing| {
                    break :blk try self.graphParserShapeNeedsInvalidValue(backing.node, err_node, seen);
                }
                break :blk false;
            },
            .redirect => unreachable,
            .unresolved,
            .primitive,
            .empty_tag_union,
            .empty_record,
            .func,
            .erased,
            .zst,
            => false,
        };
    }

    /// The `#Present` payload node when `raw_node` is an optional field's
    /// tagged slot (`[#Missing, #Present(payload)]`), mirroring
    /// `Builder.optionalFieldSlot` over graph nodes. Labels are matched by
    /// exact text in the compiler-reserved `#` namespace, so this is a
    /// lossless read-back of the `?:` slot encoding, not a shape guess.
    fn graphOptionalFieldSlotPayload(self: *BodyContext, raw_node: NodeId) Allocator.Error!?NodeId {
        const node = self.graphShapeNode(raw_node);
        if (self.graph.content(node) != .tag_union) return null;
        const tags = (try self.graph.tagRowNodes(node)).tags;
        if (tags.len != 2) return null;
        var present_payload: ?NodeId = null;
        var saw_missing = false;
        for (tags) |tag| {
            const text = self.builder.program.names.tagLabelText(tag.name);
            if (std.mem.eql(u8, text, Builder.optional_slot_missing_tag)) {
                if (tag.payloads.len != 0) return null;
                saw_missing = true;
            } else if (std.mem.eql(u8, text, Builder.optional_slot_present_tag)) {
                if (tag.payloads.len != 1) return null;
                present_payload = tag.payloads[0];
            } else {
                return null;
            }
        }
        if (!saw_missing) return null;
        return present_payload;
    }

    fn graphNodeIsUnitTagUnion(self: *BodyContext, raw_node: NodeId) Allocator.Error!bool {
        const node = self.graphShapeNode(raw_node);
        switch (self.graph.content(node)) {
            .tag_union, .named => {},
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .erased, .zst => return false,
        }
        if (!try self.graph.tagRowIsClosed(node)) return false;
        const tags = (try self.graph.tagRowNodes(node)).tags;
        if (tags.len == 0) return false;
        for (tags) |tag| {
            if (tag.payloads.len != 0) return false;
        }
        return true;
    }

    /// Add the parser producer's explicit error evidence before graph sealing.
    /// Finished Monotypes never participate in this relation and therefore
    /// cannot be reopened or widened by codec emission.
    fn ensureGraphParserMissingRequiredFieldError(
        self: *BodyContext,
        boundary_callable_node: NodeId,
    ) Allocator.Error!bool {
        const callable = try self.graph.functionNodes(boundary_callable_node);
        if (callable.args.len != 1) Common.invariant("structural parser constructor did not have one encoding argument");
        const runtime = try self.graph.functionNodes(callable.ret);
        if (runtime.args.len != 1) Common.invariant("structural parser runtime did not have one state argument");
        const outer_result = try self.graphParserResultNodes(runtime.ret);
        const tag_name = try self.builder.program.names.internTagLabel("MissingRequiredField");

        switch (self.graph.content(outer_result.err)) {
            .tag_union, .named => {
                for ((try self.graph.tagRowNodes(outer_result.err)).tags) |tag| {
                    if (!Ident.textEql(self.builder.program.names.tagLabelText(tag.name), "MissingRequiredField")) continue;
                    if (tag.payloads.len != 1) {
                        Common.invariant("MissingRequiredField graph evidence did not carry one Str payload");
                    }
                    switch (self.graph.content(tag.payloads[0])) {
                        .primitive => |primitive| if (primitive != .str) {
                            Common.invariant("MissingRequiredField graph evidence payload was not Str");
                        },
                        .named => |named| if (named.builtin_owner != .str) {
                            Common.invariant("MissingRequiredField graph evidence payload was not Str");
                        },
                        .redirect, .unresolved, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => Common.invariant("MissingRequiredField graph evidence payload was not resolved to Str"),
                    }
                    return false;
                }
            },
            .unresolved, .empty_tag_union => {},
            .redirect, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .erased, .zst => Common.invariant("structural parser error evidence was not a tag-union row"),
        }
        // A row whose extension chain already terminated in a concrete empty
        // union is checker-closed; the generated body crash-maps the missing
        // required-field path instead of widening checked output.
        var row_probe = outer_result.err;
        probe: while (true) {
            switch (self.graph.content(row_probe)) {
                .tag_union => |row| row_probe = row.ext,
                .empty_tag_union => return false,
                .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_record, .named, .erased, .zst => break :probe,
            }
        }

        const str_node = try self.graph.newNode(.{ .primitive = .str });
        const tags = try self.graph.arena().alloc(InstTag, 1);
        tags[0] = .{
            .name = tag_name,
            .checked_name = tag_name,
            .payloads = try self.graph.arena().dupe(NodeId, &.{str_node}),
        };
        const evidence = try self.graph.newNode(.{ .tag_union = .{
            .tags = tags,
            .ext = try self.graph.newNode(.{ .unresolved = InstVariable.row(.empty_tag_union) }),
        } });
        try relateRequestComponent(self.graph, outer_result.err, evidence);
        return true;
    }

    fn graphRowHasTag(self: *BodyContext, row_node: NodeId, text: []const u8) Allocator.Error!bool {
        switch (self.graph.content(row_node)) {
            .tag_union, .named => {
                for ((try self.graph.tagRowNodes(row_node)).tags) |tag| {
                    if (Ident.textEql(self.builder.program.names.tagLabelText(tag.name), text)) return true;
                }
            },
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        }
        return false;
    }

    fn prepareCustomCodecCallsAtNode(
        self: *BodyContext,
        boundary_expr: DraftExprId,
        kind: CodecKind,
        raw_shape_node: NodeId,
        boundary_callable_node: NodeId,
        seen: *collections.DenseMap(NodeId, void),
    ) Allocator.Error!bool {
        const shape_node = raw_shape_node;
        const seen_entry = try seen.getOrPut(shape_node);
        if (seen_entry.found_existing) return false;

        if (try self.customCodecLookupAtNode(shape_node, kind)) |raw_lookup| {
            return try self.prepareCustomCodecCall(
                boundary_expr,
                kind,
                shape_node,
                boundary_callable_node,
                try self.withLocalProcContext(raw_lookup),
            );
        }

        if (kind == .parser) {
            if (self.graphJsonParseScalarMethodName(shape_node)) |method_name| {
                return try self.prepareParseScalarCodecCall(
                    boundary_expr,
                    shape_node,
                    boundary_callable_node,
                    method_name,
                );
            }
        } else if (self.graphJsonEncodeScalarMethodName(shape_node)) |method_name| {
            return try self.prepareEncodeScalarCodecCall(
                boundary_expr,
                shape_node,
                boundary_callable_node,
                method_name,
            );
        }

        // A nominal opaque with a scalar backing (e.g. `Username := Str`) prepares the codec for
        // its backing scalar; the encoder/parser reaches it after unwrapping the nominal.
        switch (self.graph.content(shape_node)) {
            .named => |named| if (named.backing) |backing| {
                const backing_is_scalar = if (kind == .parser)
                    self.graphJsonParseScalarMethodName(backing.node) != null
                else
                    self.graphJsonEncodeScalarMethodName(backing.node) != null;
                if (backing_is_scalar) {
                    return try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, backing.node, boundary_callable_node, seen);
                }
            },
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        }

        if (self.graphNodeIsBuiltinTry(shape_node)) {
            const payloads = try self.graphTryPayloads(shape_node);
            var added = false;
            if (try self.graphErrorIsExactUnitTag(payloads.err, "Null")) {
                added = switch (kind) {
                    .parser => try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "parse_null",
                        true,
                    ),
                    .encoder => try self.prepareEncodeNullCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ),
                };
            }
            return try self.prepareCustomCodecCallsAtNode(
                boundary_expr,
                kind,
                payloads.ok,
                boundary_callable_node,
                seen,
            ) or added;
        }

        switch (self.graph.content(shape_node)) {
            .named => |named| if (named.builtin_owner) |owner| switch (owner) {
                .set => {
                    if (named.args.len != 1) Common.invariant("builtin Set graph node had an unexpected arity");
                    var added = if (kind == .parser)
                        try self.prepareParseListFormatCodecCalls(boundary_expr, shape_node, boundary_callable_node)
                    else
                        try self.prepareEncodeContainerCodecCall(boundary_expr, shape_node, boundary_callable_node, "encode_list");
                    added = try self.prepareSetCollectionCodecCall(
                        boundary_expr,
                        kind,
                        shape_node,
                        named.args[0],
                    ) or added;
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, named.args[0], boundary_callable_node, seen) or added;
                    return added;
                },
                .dict => {
                    if (named.args.len != 2) Common.invariant("builtin Dict graph node had an unexpected arity");
                    var added = if (kind == .parser)
                        try self.prepareParseDictFormatCodecCalls(boundary_expr, shape_node, boundary_callable_node)
                    else
                        try self.prepareEncodeContainerCodecCall(boundary_expr, shape_node, boundary_callable_node, "encode_dict");
                    added = try self.prepareDictKeyCodecCalls(
                        boundary_expr,
                        kind,
                        named.args[0],
                        boundary_callable_node,
                        seen,
                    ) or added;
                    added = try self.prepareDictCollectionCodecCalls(
                        boundary_expr,
                        kind,
                        shape_node,
                        named.args[0],
                        named.args[1],
                    ) or added;
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, named.args[1], boundary_callable_node, seen) or added;
                    return added;
                },
                .list, .box, .fields, .field, .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .parse_tag_union_spec, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher, .iter, .stream => {},
            },
            .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .record, .empty_tag_union, .empty_record, .erased, .zst => {},
        }

        // A dict's and a set's own backings are private representation that no
        // codec reads. Walking into one prepares calls over internals that are
        // never parsed or encoded, so the walk uses the element shape the codec
        // actually reaches instead.
        var container_buf: [2]NodeId = undefined;
        const container_shapes = self.graphBuiltinContainerShapeNodes(shape_node, &container_buf);
        if (container_shapes.len != 0) {
            var container_added = false;
            for (container_shapes) |container_shape| {
                container_added = try self.prepareCustomCodecCallsAtNode(
                    boundary_expr,
                    kind,
                    container_shape,
                    boundary_callable_node,
                    seen,
                ) or container_added;
            }
            return container_added;
        }

        var added = false;
        const structural_node = self.graphShapeNode(shape_node);
        switch (self.graph.content(structural_node)) {
            .list => |elem| {
                if (kind == .parser) {
                    added = try self.prepareParseListFormatCodecCalls(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                } else {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "encode_list",
                    ) or added;
                }
                added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, elem, boundary_callable_node, seen) or added;
            },
            .box => |elem| added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, elem, boundary_callable_node, seen) or added,
            .tuple => |items| {
                if (kind == .parser) {
                    added = try self.prepareParseTupleFormatCodecCalls(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                } else {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "encode_tuple",
                    ) or added;
                }
                for (items) |item| {
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, item, boundary_callable_node, seen) or added;
                }
            },
            .record, .zst, .empty_record => {
                const fields = switch (self.graph.content(structural_node)) {
                    .record => (try self.graph.recordNodes(structural_node)).fields,
                    .zst, .empty_record => &.{},
                    .redirect, .unresolved, .primitive, .list, .box, .tuple, .func, .tag_union, .named, .empty_tag_union, .erased => Common.invariant("record codec preparation reached a non-record shape"),
                };
                if (kind == .encoder) {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "encode_record",
                    ) or added;
                }
                if (kind == .parser) {
                    if (fields.len != 0) {
                        added = try self.prepareRenameRecordFieldCodecCall(
                            boundary_expr,
                            kind,
                            shape_node,
                            boundary_callable_node,
                        ) or added;
                    }
                    added = try self.prepareSkipRecordFieldCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                    added = try self.prepareParseRecordFieldCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                    added = try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "parse_record_start",
                        false,
                    ) or added;
                    added = try self.prepareParseFormatControlCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "parse_record_after_field",
                        false,
                    ) or added;
                } else if (fields.len != 0) {
                    added = try self.prepareRenameRecordFieldCodecCall(
                        boundary_expr,
                        kind,
                        shape_node,
                        boundary_callable_node,
                    ) or added;
                }
                for (fields) |field|
                    added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, field.ty, boundary_callable_node, seen) or added;
            },
            .tag_union => {
                if (kind == .encoder) {
                    added = try self.prepareEncodeContainerCodecCall(
                        boundary_expr,
                        shape_node,
                        boundary_callable_node,
                        "encode_tag",
                    ) or added;
                }
                if (kind == .parser) {
                    added = try self.prepareParseTagUnionCodecCall(boundary_expr, shape_node, boundary_callable_node) or added;
                }
                for ((try self.graph.tagRowNodes(structural_node)).tags) |tag| {
                    for (tag.payloads) |payload|
                        added = try self.prepareCustomCodecCallsAtNode(boundary_expr, kind, payload, boundary_callable_node, seen) or added;
                }
            },
            .named => {},
            .redirect => unreachable,
            .unresolved, .primitive, .empty_tag_union, .func, .erased => {},
        }
        return added;
    }

    fn typeHasParserForTarget(self: *BodyContext, ty: Type.TypeId) Allocator.Error!bool {
        const named = switch (self.builder.program.types.get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return false,
        };
        if (self.builder.isBuiltinTryDef(named.def)) return false;
        if (named.builtin_owner != null) return false;
        const owner = methodOwnerFromType(&self.builder.program.types, ty) orelse return false;
        return (try self.builder.lookupMethodTargetByName(self.method_scope, owner, "parser_for")) != null;
    }

    fn customEncoderForLookup(self: *BodyContext, ty: Type.TypeId) Allocator.Error!?MethodLookup {
        const named = switch (self.builder.program.types.get(ty)) {
            .named => |named| named,
            .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => return null,
        };
        if (named.builtin_owner != null) return null;
        switch (named.kind) {
            .nominal, .@"opaque" => {},
            .alias => return null,
        }
        const owner = methodOwnerFromType(&self.builder.program.types, ty) orelse
            Common.invariant("custom named encoder_for type had no method owner");
        const lookup = (try self.builder.lookupMethodTargetByName(self.method_scope, owner, "encoder_for")) orelse
            Common.invariant("checked method registry is missing custom encoder_for target");
        return switch (lookup.target.kind) {
            .structural => |kind| if (kind == .encoder) null else Common.invariant("encoder_for lookup resolved to a different structural target"),
            .procedure, .local_proc => lookup,
        };
    }

    fn tryNullInfo(self: *BodyContext, ty: Type.TypeId) ?TryNullInfo {
        const backing_ty = self.builder.namedBackingType(ty) orelse return null;
        const ok_tag = self.monoTagByTextOptional(backing_ty, "Ok") orelse return null;
        const err_tag = self.monoTagByTextOptional(backing_ty, "Err") orelse return null;
        const ok_payloads = self.builder.program.types.span(ok_tag.payloads);
        const err_payloads = self.builder.program.types.span(err_tag.payloads);
        if (ok_payloads.len != 1 or err_payloads.len != 1) return null;
        const err_ty = GuardedList.at(err_payloads, 0);
        if (!self.typeIsExactUnitTagUnion(err_ty, "Null")) return null;
        return .{
            .backing_ty = backing_ty,
            .ok_payload_ty = GuardedList.at(ok_payloads, 0),
            .err_ty = err_ty,
        };
    }

    fn tagUnionValueWithoutPayload(self: *BodyContext, ty: Type.TypeId, tag_text: []const u8) Allocator.Error!DraftExprId {
        const tag = self.monoTagByText(ty, tag_text);
        if (self.builder.program.types.span(tag.payloads).len != 0) Common.invariant("JSON Try marker tag unexpectedly had payloads");
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .tag = .{
                .name = tag.name,
                .payloads = .empty(),
            } },
        });
    }

    fn typeIsExactUnitTagUnion(self: *BodyContext, ty: Type.TypeId, tag_text: []const u8) bool {
        const tags = switch (self.builder.shapeContent(ty)) {
            .tag_union => |span| self.builder.program.types.tagSpan(span),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => return false,
        };
        if (tags.len != 1) return false;
        const tag = GuardedList.at(tags, 0);
        if (self.builder.program.types.span(tag.payloads).len != 0) return false;
        return Ident.textEql(self.builder.program.names.tagLabelText(tag.name), tag_text);
    }

    fn finishOptionalRecordFieldFromPresencePayload(
        self: *BodyContext,
        next_body: DraftExprId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        field: Type.Field,
        field_index: usize,
        field_local: DraftLocalId,
    ) Allocator.Error!DraftExprId {
        const field_ty = field.ty;
        const maybe_try_info = try self.missingTryInfo(field_ty);
        if (maybe_try_info == null and self.builder.optionalFieldSlot(field_ty) == null) {
            Common.invariant("optional record finish requested for a field that is neither Try-optional nor a `?:` slot");
        }
        const payload_local = record_slots.payload_locals[field_index];
        const payload_ty = record_slots.payload_tys[field_index];
        if (!self.sameType(payload_ty, field_ty)) {
            Common.invariant("generated optional record payload type differed from field type");
        }
        if (!self.sameType(try self.localType(field_local), field_ty)) {
            Common.invariant("record finish field local type differed from optional field type");
        }

        const missing_field = if (maybe_try_info) |optional_info|
            try self.tryErr(field_ty, try self.tagUnionValueWithoutPayload(optional_info.err_ty, "Missing"))
        else
            // An absent `?:` field materializes the slot's `#Missing` tag
            // (design.md "Field Kinds (All-Dynamic Optional Fields)").
            try self.optionalSlotMissingExpr(field_ty);
        const present_field = try self.localExpr(payload_local, payload_ty);
        const presence_word = recordPresenceWordIndex(field_index);
        const is_present_expr = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]);
        const field_value = try self.addExpr(.{ .ty = field_ty, .data = .{ .if_initialized_payload = .{
            .cond = is_present_expr,
            .cond_mask = recordPresenceMask(field_index),
            .payload = payload_local,
            .uninitialized_is_cold = false,
            .initialized = present_field,
            .uninitialized = missing_field,
        } } });
        return try self.wrapLet(field_local, field_ty, field_value, next_body, ret_ty);
    }

    /// The `??`-defaulted sibling of
    /// `finishOptionalRecordFieldFromPresencePayload`: an absent key
    /// materializes the field's archived default constant into the inline
    /// slot—exactly the construction-site omission behavior `{}`
    /// literals get (design.md "Defaulted Fields"). A present key already parsed at
    /// the field's inline type into the payload slot.
    fn finishDefaultedRecordFieldFromPresencePayload(
        self: *BodyContext,
        next_body: DraftExprId,
        ret_ty: Type.TypeId,
        record_slots: ParseRecordSlots,
        field: Type.Field,
        field_index: usize,
        field_local: DraftLocalId,
        default: Type.FieldDefault,
    ) Allocator.Error!DraftExprId {
        const field_ty = field.ty;
        const payload_local = record_slots.payload_locals[field_index];
        const payload_ty = record_slots.payload_tys[field_index];
        if (!self.sameType(payload_ty, field_ty)) {
            Common.invariant("generated defaulted record payload type differed from field type");
        }
        if (!self.sameType(try self.localType(field_local), field_ty)) {
            Common.invariant("record finish field local type differed from defaulted field type");
        }

        const default_field = (try self.defaultedFieldValueFromMonoDefault(default, field_ty)) orelse
            Common.invariant("defaulted record parse finish had no archived default to materialize");
        const present_field = try self.localExpr(payload_local, payload_ty);
        const presence_word = recordPresenceWordIndex(field_index);
        const is_present_expr = try self.localExpr(record_slots.presence_locals[presence_word], record_slots.presence_tys[presence_word]);
        const field_value = try self.addExpr(.{ .ty = field_ty, .data = .{ .if_initialized_payload = .{
            .cond = is_present_expr,
            .cond_mask = recordPresenceMask(field_index),
            .payload = payload_local,
            .uninitialized_is_cold = false,
            .initialized = present_field,
            .uninitialized = default_field,
        } } });
        return try self.wrapLet(field_local, field_ty, field_value, next_body, ret_ty);
    }

    fn parseRecordFieldFromPresencePayload(
        self: *BodyContext,
        is_present_expr: DraftExprId,
        is_present_mask: u64,
        payload_local: DraftLocalId,
        payload_ty: Type.TypeId,
        field: Type.Field,
        field_try_ty: Type.TypeId,
        renamed_field_local: DraftLocalId,
        encoding_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_expr: DraftExprId,
        state_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const field_ty = field.ty;
        const field_try_info = self.tryInfo(field_try_ty);
        if (!self.sameType(field_try_info.ok_ty, field_ty)) Common.invariant("structural parser field Try Ok type differed from field type");
        const renamed_field_ty = try self.localType(renamed_field_local);
        if (!self.typeHasBuiltinOwner(renamed_field_ty, .str)) Common.invariant("record parser renamed field local was not Str");
        const renamed_field_expr = try self.localExpr(renamed_field_local, renamed_field_ty);

        if (!self.sameType(payload_ty, field_ty)) {
            Common.invariant("generated record parse payload type differed from parsed field type");
        }
        const present_body = try self.tryOk(field_try_ty, try self.localExpr(payload_local, payload_ty));
        const absent_body = try self.tryErr(field_try_ty, try self.missingRequiredFieldError(
            renamed_field_expr,
            encoding_expr,
            state_expr,
            encoding_ty,
            state_ty,
            field_try_info.err_ty,
        ));

        return try self.addExpr(.{ .ty = field_try_ty, .data = .{ .if_initialized_payload = .{
            .cond = is_present_expr,
            .cond_mask = is_present_mask,
            .payload = payload_local,
            .uninitialized_is_cold = true,
            .initialized = present_body,
            .uninitialized = absent_body,
        } } });
    }

    /// Whether parsing `ty` from source text can report a missing required
    /// record field. Mirrors the checker's derived-parse analysis over the
    /// materialized monotype.
    fn parserShapeNeedsRequiredFieldError(
        self: *BodyContext,
        ty: Type.TypeId,
        visited: *collections.DenseMap(Type.TypeId, void),
    ) Allocator.Error!bool {
        if (visited.contains(ty)) return false;
        try visited.put(ty, {});

        if (self.parseScalarMethodName(ty) != null) return false;
        if (try self.missingTryInfo(ty)) |info| {
            return try self.parserShapeNeedsRequiredFieldError(info.ok_ty, visited);
        }
        if (self.tryNullInfo(ty)) |info| {
            return try self.parserShapeNeedsRequiredFieldError(info.ok_payload_ty, visited);
        }
        if ((try self.customParserLookup(ty)) != null) return false;
        if (self.setPayloadType(ty)) |payload_ty| {
            return try self.parserShapeNeedsRequiredFieldError(payload_ty, visited);
        }
        if (self.dictEntryShape(ty)) |dict| {
            var dict_buf: [2]Type.TypeId = undefined;
            for (self.dictCodecShapes(dict, &dict_buf)) |dict_shape| {
                if (try self.parserShapeNeedsRequiredFieldError(dict_shape, visited)) return true;
            }
            return false;
        }

        return switch (self.builder.shapeContent(ty)) {
            .list => |payload_ty| try self.parserShapeNeedsRequiredFieldError(payload_ty, visited),
            .box => |payload_ty| try self.parserShapeNeedsRequiredFieldError(payload_ty, visited),
            .tuple => |span| blk: {
                const elems = self.builder.program.types.span(span);
                for (0..GuardedList.borrowLen(elems)) |index| {
                    if (try self.parserShapeNeedsRequiredFieldError(GuardedList.at(elems, index), visited)) break :blk true;
                }
                break :blk false;
            },
            .record => |span| blk: {
                const fields = self.builder.program.types.fieldSpan(span);
                for (0..GuardedList.borrowLen(fields)) |index| {
                    const field = GuardedList.at(fields, index);
                    if (try self.missingTryInfo(field.ty)) |optional| {
                        if (try self.parserShapeNeedsRequiredFieldError(optional.ok_ty, visited)) break :blk true;
                    } else if (self.builder.optionalFieldSlot(field.ty)) |slot| {
                        // `?:` slot: an absent key parses to `#Missing`, so the
                        // field itself never demands MissingRequiredField.
                        if (try self.parserShapeNeedsRequiredFieldError(slot.payload_ty, visited)) break :blk true;
                    } else if (field.default != null) {
                        // `??` field: an absent key fills the archived default.
                        if (try self.parserShapeNeedsRequiredFieldError(field.ty, visited)) break :blk true;
                    } else {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .tag_union => |span| blk: {
                const tags = self.builder.program.types.tagSpan(span);
                for (0..GuardedList.borrowLen(tags)) |tag_index| {
                    const payloads = self.builder.program.types.span(GuardedList.at(tags, tag_index).payloads);
                    for (0..GuardedList.borrowLen(payloads)) |payload_index| {
                        if (try self.parserShapeNeedsRequiredFieldError(GuardedList.at(payloads, payload_index), visited)) break :blk true;
                    }
                }
                break :blk false;
            },
            .zst => false,
            .primitive, .named, .func, .erased => false,
        };
    }

    fn missingRequiredFieldError(
        self: *BodyContext,
        field_name_expr: DraftExprId,
        encoding_expr: DraftExprId,
        state_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const str_ty = try self.builder.primitiveType(.str);
        if (!self.sameType(try self.exprType(field_name_expr), str_ty)) {
            Common.invariant("generated missing required field name was not Str");
        }
        // Generic structural parsers may hide field-level details behind the
        // format's public error row. Keep the precise generated tag when the row
        // includes it; otherwise use the checked format failure boundary.
        const missing_tag = self.monoTagByTextOptional(err_ty, "MissingRequiredField") orelse
            return try self.invalidValueError(encoding_expr, state_expr, encoding_ty, state_ty, err_ty);
        const payload_tys = self.builder.program.types.span(missing_tag.payloads);
        if (payload_tys.len != 1 or !self.sameType(GuardedList.at(payload_tys, 0), str_ty)) {
            Common.invariant("MissingRequiredField in parser error row did not carry one Str payload");
        }
        return try self.addExpr(.{
            .ty = err_ty,
            .data = .{ .tag = .{
                .name = missing_tag.name,
                .payloads = try self.addExprSpan(&[_]DraftExprId{field_name_expr}),
            } },
        });
    }

    fn invalidValueParseResult(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        state_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const ret_info = self.tryInfo(ret_ty);
        return try self.tryErr(
            ret_ty,
            try self.invalidValueError(encoding_expr, state_expr, encoding_ty, state_ty, ret_info.err_ty),
        );
    }

    fn invalidValueError(
        self: *BodyContext,
        encoding_expr: DraftExprId,
        state_expr: DraftExprId,
        encoding_ty: Type.TypeId,
        state_ty: Type.TypeId,
        err_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const lookup = try self.methodLookupForTypeName(encoding_ty, "invalid_value");
        const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &.{ encoding_ty, state_ty }, err_ty);
        const invalid_fn = self.builder.functionShape(callable_mono_ty, "invalid_value target method was not a function");
        const arg_tys = self.builder.program.types.span(invalid_fn.args);
        if (arg_tys.len != 2) Common.invariant("invalid_value target method had an unexpected arity");
        if (!self.sameType(GuardedList.at(arg_tys, 0), encoding_ty)) Common.invariant("invalid_value encoding type differed from parser encoding type");
        if (!self.sameType(GuardedList.at(arg_tys, 1), state_ty)) Common.invariant("invalid_value state type differed from parser state type");
        if (!self.sameType(invalid_fn.ret, err_ty)) Common.invariant("invalid_value return type differed from parse error type");

        return try self.addExpr(.{
            .ty = err_ty,
            .data = .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize)),
                .args = try self.addExprSpan(&[_]DraftExprId{ encoding_expr, state_expr }),
                .captures = try self.methodTargetCaptureSpan(lookup),
                .is_cold = true,
            } },
        });
    }

    fn lowerDirectStructuralEq(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        eq: anytype,
    ) Allocator.Error!DraftExprId {
        const ret_ty = try self.lowerTypeView(checked_ret_ty);
        return try self.lowerDirectStructuralEqAtType(eq, ret_ty);
    }

    fn lowerDirectStructuralEqAtType(
        self: *BodyContext,
        eq: anytype,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return switch (try self.structuralEqualityOperandType(eq)) {
            .sealed => |operand_ty| try self.lowerDirectStructuralEqWithOperandType(
                eq.lhs,
                eq.rhs,
                eq.negated,
                ret_ty,
                operand_ty,
            ),
            .deferred => |operand_node| try self.deferStructuralEqAtNode(eq, ret_ty, operand_node),
        };
    }

    fn lowerDirectStructuralEqWithOperandType(
        self: *BodyContext,
        lhs_checked: checked.CheckedExprId,
        rhs_checked: checked.CheckedExprId,
        negated: bool,
        ret_ty: Type.TypeId,
        operand_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const lhs = try self.lowerExprAtType(lhs_checked, operand_ty);
        const rhs = try self.lowerExprAtType(rhs_checked, operand_ty);
        return try self.lowerStructuralEqFromOperands(operand_ty, lhs, rhs, negated, ret_ty);
    }

    fn lowerStructuralEqFromOperands(
        self: *BodyContext,
        operand_ty: Type.TypeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        negated: bool,
        ret_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        var result = try self.lowerEqualityExpr(operand_ty, lhs, rhs, "is_eq", ret_ty);
        if (negated) {
            result = try self.lowLevelExpr(.bool_not, &.{result}, ret_ty);
        }
        return result;
    }

    const StructuralEqualityOperand = union(enum) {
        sealed: Type.TypeId,
        deferred: NodeId,
    };

    fn structuralEqualityOperandType(self: *BodyContext, eq: anytype) Allocator.Error!StructuralEqualityOperand {
        const lhs_checked_ty = self.view.bodies.expr(eq.lhs).ty;
        const rhs_checked_ty = self.view.bodies.expr(eq.rhs).ty;

        try self.constrainCheckedTypeRelations(lhs_checked_ty, self, rhs_checked_ty);

        if (try self.structuralEqualityExprResultNode(eq.lhs)) |lhs_node| {
            return try self.constrainStructuralEqualityOperandNode(lhs_node, eq.rhs, rhs_checked_ty);
        }
        if (try self.structuralEqualityExprResultNode(eq.rhs)) |rhs_node| {
            return try self.constrainStructuralEqualityOperandNode(rhs_node, eq.lhs, lhs_checked_ty);
        }

        const operand_node = try self.instNode(lhs_checked_ty);
        return try self.structuralEqualityOperandFromNode(operand_node);
    }

    fn deferStructuralEqAtNode(
        self: *BodyContext,
        eq: anytype,
        ret_ty: Type.TypeId,
        operand_node: NodeId,
    ) Allocator.Error!DraftExprId {
        const operand_cell = DraftTypeCell.fromGraphNode(operand_node);
        const lhs = try self.lowerExprAtTypeCell(eq.lhs, operand_cell);
        const rhs = try self.lowerExprAtTypeCell(eq.rhs, operand_cell);
        return try self.deferStructuralDerivationOperandsAtNode(
            ret_ty,
            operand_node,
            lhs,
            rhs,
            .{ .equality = .{ .negated = eq.negated } },
        );
    }

    fn deferStructuralEqOperandsAtNode(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        operand_node: NodeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        negated: bool,
    ) Allocator.Error!DraftExprId {
        return try self.deferStructuralDerivationOperandsAtNode(
            ret_ty,
            operand_node,
            lhs,
            rhs,
            .{ .equality = .{ .negated = negated } },
        );
    }

    fn deferStructuralDerivationOperandsAtNode(
        self: *BodyContext,
        ret_ty: Type.TypeId,
        operand_node: NodeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        mode: DraftStructuralDerivationMode,
    ) Allocator.Error!DraftExprId {
        const expr = try self.addExprWithTypeCell(.{ .sealed = ret_ty }, .pending_deferred);
        self.draft.expr_impossibility_proofs.items[@intFromEnum(expr)] = try self.anyImpossibilityProof(&.{
            self.exprImpossibilityProof(lhs),
            self.exprImpossibilityProof(rhs),
        });
        const lexical = try self.captureCodecLexicalContext();
        errdefer {
            self.allocator.free(lexical.binders);
            self.allocator.free(lexical.local_procs);
        }
        try self.draft.deferred_structural_eqs.append(self.allocator, .{
            .view = self.view,
            .method_scope = self.method_scope,
            .owner_template = self.owner_template,
            .owner = self.draft.current_owner,
            .expr = expr,
            .operand_node = operand_node,
            .ret_ty = ret_ty,
            .lhs = lhs,
            .rhs = rhs,
            .mode = mode,
            .evidence = self.evidence,
            .current_fn_key = self.current_fn_key,
            .lexical = lexical,
        });
        return expr;
    }

    /// Resolves the graph node an equality operand evaluates to, when that operand is a
    /// result-producing expression (call, dispatch, lookup, field access). The shared
    /// equality operand node is taken from this result so an open tag literal on the other
    /// side cannot narrow it. Returns null for any other expression shape (e.g. a tag
    /// literal): the caller then falls through to the concrete-shape ladder in
    /// structuralEqualityOperandType, so this must not materialize a Monotype view.
    fn structuralEqualityExprResultNode(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!?NodeId {
        if (self.checkedExprDivergesInLoweredRuntime(expr_id)) return null;
        const expr = self.view.bodies.expr(expr_id);
        return switch (expr.data) {
            .call => |call| try self.callResultTypeNode(expr.ty, call, null),
            .dispatch_call => |plan| try self.dispatchResultTypeNode(expr.ty, plan, null),
            .interpolation => |interpolation| try self.dispatchResultTypeNode(expr.ty, interpolation.plan, null),
            .type_dispatch_call => |plan| try self.dispatchResultTypeNode(expr.ty, plan, null),
            .method_eq => |plan| try self.dispatchResultTypeNode(expr.ty, plan, null),
            .lookup_local => |lookup| try self.lookupExprTypeNode(expr.ty, lookup.resolved),
            .lookup_external => |resolved| try self.lookupExprTypeNode(expr.ty, resolved),
            .lookup_required => |resolved| try self.lookupExprTypeNode(expr.ty, resolved),
            .field_access => |field| try self.fieldAccessTypeNode(expr.ty, field, null),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn constrainStructuralEqualityOperandNode(
        self: *BodyContext,
        operand_node: NodeId,
        other_expr_id: checked.CheckedExprId,
        other_checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!StructuralEqualityOperand {
        try self.graph.unify(operand_node, try self.instNode(other_checked_ty));
        if (try self.structuralEqualityExprResultNode(other_expr_id)) |other_node| {
            try self.graph.unify(operand_node, other_node);
        }
        return try self.structuralEqualityOperandFromNode(operand_node);
    }

    fn structuralEqualityOperandFromNode(
        self: *BodyContext,
        operand_node: NodeId,
    ) Allocator.Error!StructuralEqualityOperand {
        if (try self.graph.typeIsResolved(operand_node)) {
            return .{ .sealed = try self.activeTypeFromNode(operand_node) };
        }
        return .{ .deferred = operand_node };
    }

    fn structuralDerivationMethodName(mode: DraftStructuralDerivationMode) []const u8 {
        return switch (mode) {
            .equality => "is_eq",
            .hash => "to_hash",
        };
    }

    fn prepareStructuralEqNode(
        self: *BodyContext,
        boundary_index: usize,
        mode: DraftStructuralDerivationMode,
        raw_node: NodeId,
        result_ty: Type.TypeId,
        seen: *collections.DenseMap(NodeId, void),
        added_method_call: *bool,
    ) Allocator.Error!void {
        const entry = try seen.getOrPut(raw_node);
        if (entry.found_existing) return;

        switch (self.graph.content(raw_node)) {
            .list => {
                const lookup = try self.withLocalProcContext((try self.builder.lookupMethodTargetByName(
                    self.method_scope,
                    .{ .builtin = .list },
                    structuralDerivationMethodName(mode),
                )) orelse Common.invariant("checked method registry is missing the List structural derivation target"));
                if (lookup.target.kind == .structural) {
                    Common.invariant("owned List derivation resolved to a structural registry implementation");
                }
                try self.prepareStructuralEqMethodCall(
                    boundary_index,
                    mode,
                    raw_node,
                    result_ty,
                    lookup,
                    added_method_call,
                );
            },
            .tuple => {
                for (try self.graph.tupleItemNodes(raw_node)) |item| {
                    try self.prepareStructuralEqNode(
                        boundary_index,
                        mode,
                        item,
                        result_ty,
                        seen,
                        added_method_call,
                    );
                }
            },
            .record => {
                for ((try self.graph.recordNodes(raw_node)).fields) |field| {
                    try self.prepareStructuralEqNode(
                        boundary_index,
                        mode,
                        field.ty,
                        result_ty,
                        seen,
                        added_method_call,
                    );
                }
            },
            .tag_union => {
                for ((try self.graph.tagRowNodes(raw_node)).tags) |tag| {
                    for (tag.payloads) |payload| {
                        try self.prepareStructuralEqNode(
                            boundary_index,
                            mode,
                            payload,
                            result_ty,
                            seen,
                            added_method_call,
                        );
                    }
                }
            },
            .named => {
                const named = self.graph.namedNodes(raw_node);
                if (self.methodOwnerFromNode(raw_node)) |owner| {
                    if (try self.builder.lookupMethodTargetByName(self.method_scope, owner, structuralDerivationMethodName(mode))) |raw_lookup| {
                        const lookup = try self.withLocalProcContext(raw_lookup);
                        switch (lookup.target.kind) {
                            .structural => |kind| {
                                const expected: static_dispatch.StructuralKind = switch (mode) {
                                    .equality => .equality,
                                    .hash => .hash,
                                };
                                if (kind != expected) {
                                    Common.invariant("named structural derivation resolved to a different structural registry implementation");
                                }
                            },
                            .procedure, .local_proc => {
                                try self.prepareStructuralEqMethodCall(
                                    boundary_index,
                                    mode,
                                    raw_node,
                                    result_ty,
                                    lookup,
                                    added_method_call,
                                );
                                return;
                            },
                        }
                    }
                }
                if (named.backing) |backing| {
                    try self.prepareStructuralEqNode(
                        boundary_index,
                        mode,
                        backing.node,
                        result_ty,
                        seen,
                        added_method_call,
                    );
                }
            },
            .redirect => unreachable,
            .unresolved,
            .primitive,
            .empty_tag_union,
            .empty_record,
            .func,
            .box,
            .erased,
            .zst,
            => {},
        }
    }

    fn prepareStructuralEqMethodCall(
        self: *BodyContext,
        boundary_index: usize,
        mode: DraftStructuralDerivationMode,
        node: NodeId,
        result_ty: Type.TypeId,
        lookup: MethodLookup,
        added_method_call: *bool,
    ) Allocator.Error!void {
        for (self.draft.structural_eq_method_calls.items) |planned| {
            if (planned.boundary != boundary_index) continue;
            if (self.graph.sameClass(planned.node, node)) return;
        }
        const ret_node = try self.graph.importMono(result_ty);
        const callable_node = switch (mode) {
            .equality => try self.graphFunctionNode(&.{ node, node }, ret_node),
            .hash => try self.graphFunctionNode(&.{ node, ret_node }, ret_node),
        };
        const callee = try self.methodTargetCalleeAtNode(lookup, callable_node, .synthesize);
        try self.draft.structural_eq_method_calls.append(self.allocator, .{
            .boundary = @intCast(boundary_index),
            .node = node,
            .callee = callee,
        });
        added_method_call.* = true;
    }

    /// Whether `shape` is a type the structural-derivation ladders (is_eq /
    /// to_hash) expand a layer at a time, guarding recursion through an
    /// expansion stack. Aggregates and transparent nominals expand; scalars,
    /// owned wrappers (List/Box), and opaque nominals bottom out instead.
    fn structurallyExpands(shape: Type.Content) bool {
        return switch (shape) {
            .record, .tuple, .tag_union => true,
            .named => |named| named.backing != null,
            .primitive, .list, .box, .func, .erased, .zst => false,
        };
    }

    fn lowerEqualityExpr(
        self: *BodyContext,
        ty: Type.TypeId,
        lhs: DraftExprId,
        rhs: DraftExprId,
        method_name: []const u8,
        bool_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerDerivation(EqDeriver, ty, .{ .lhs = lhs, .rhs = rhs }, .{
            .method_name = method_name,
            .result_ty = bool_ty,
        });
    }

    /// Hash `value` (of `value_ty`) into `hasher`, producing a new Hasher of
    /// `hasher_ty`. The threading is "innermost first": each component feeds the
    /// hasher accumulated so far.
    fn lowerHashExpr(
        self: *BodyContext,
        value_ty: Type.TypeId,
        value: DraftExprId,
        hasher: DraftExprId,
        hasher_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerDerivation(HashDeriver, value_ty, .{ .value = value, .hasher = hasher }, .{
            .method_name = "to_hash",
            .result_ty = hasher_ty,
        });
    }

    // Generic structural-derivation driver.
    //
    // is_eq and to_hash share one recursive ladder: walk a type one layer at a
    // time, decomposing aggregates (records/tuples/tag unions) and transparent
    // nominals that have no exact component method. A List or named component
    // with an exact method dispatches to that method before its representation
    // can be inspected. Scalars, opaque nominals, and other inline-handled
    // leaves emit a leaf node (`structural_eq` / `structural_hash`). Recursion is
    // broken by an expansion stack plus a memoized generated helper def.
    //
    // The per-derivation specifics are supplied by a comptime `Deriver` type
    // (`EqDeriver` / `HashDeriver`). A Deriver provides:
    //   - `Operand`: the operands threaded into one derivation step (equality
    //     holds two `DraftExprId`; hashing holds the value plus the running
    //     hasher accumulator).
    //   - the expansion-stack and memoized-def-cache accessors plus the helper
    //     fn type, so recursion breaks identically for both.
    //   - `leaf`: emit the leaf node for inline-handled shapes.
    //   - `componentForField` / `componentForTuple`: build a component's
    //     operands from the aggregate operands and the running fold state.
    //   - `combineSeed` / `combine` plus `forward`: fold the per-component
    //     results (equality conjoins component bools with AND; hashing threads
    //     the accumulator left to right).
    //   - `methodArgTypes` / `named` / `tagUnion`: method call types and the
    //     shapes whose decomposition differs structurally between the two
    //     derivations.
    //
    // A `DerivationCtx` carries the runtime parameters shared by every step:
    // the derivation's result type (Bool / Hasher) and the method name.

    const DerivationCtx = struct {
        method_name: []const u8,
        result_ty: Type.TypeId,
    };

    fn lowerDerivation(
        self: *BodyContext,
        comptime D: type,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const shape = self.builder.program.types.get(ty);

        switch (shape) {
            .list => {
                const lookup = try self.derivationMethodLookup(ty, ctx.method_name) orelse
                    Common.invariant(D.missing_component_method_msg);
                if (lookup.target.kind == .structural) {
                    Common.invariant("owned List derivation resolved to a structural registry implementation");
                }
                return try self.derivationMethodCall(D, lookup, ty, operand, ctx);
            },
            .named => {
                if (try self.derivationMethodLookup(ty, ctx.method_name)) |lookup| {
                    switch (lookup.target.kind) {
                        .structural => |kind| if (kind != D.structural_kind) {
                            Common.invariant("structural registry implementation did not match the active derivation");
                        },
                        .procedure, .local_proc => return try self.derivationMethodCall(D, lookup, ty, operand, ctx),
                    }
                }
            },
            .primitive, .record, .tuple, .tag_union, .box, .func, .erased, .zst => {},
        }

        return try self.lowerDerivationExpansion(D, ty, operand, ctx);
    }

    fn derivationMethodLookup(
        self: *BodyContext,
        ty: Type.TypeId,
        method_name: []const u8,
    ) Allocator.Error!?MethodLookup {
        const owner = methodOwnerFromType(&self.builder.program.types, ty) orelse return null;
        const lookup = (try self.builder.lookupMethodTargetByName(self.method_scope, owner, method_name)) orelse return null;
        return try self.withLocalProcContext(lookup);
    }

    /// Expand `ty` structurally without consulting its exact method target.
    /// Components still derive through `lowerDerivation`, so only the top
    /// layer skips method dispatch. Generated recursive helper bodies use this
    /// entry point to avoid resolving their own method back into a self-call.
    fn lowerDerivationExpansion(
        self: *BodyContext,
        comptime D: type,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const shape = self.builder.program.types.get(ty);
        const expands_structurally = structurallyExpands(shape);
        var remove_active_expansion = false;
        const stack = D.expansionStack(self);
        defer if (remove_active_expansion) {
            _ = stack.remove(ty);
        };
        if (expands_structurally) {
            if (stack.contains(ty)) {
                return try self.derivationCall(D, ty, operand, ctx);
            }
            try stack.put(ty, {});
            remove_active_expansion = true;
        }

        return switch (shape) {
            .list => Common.invariant("structural derivation expansion reached a List; List derivations dispatch to a method target"),
            .record => |fields| try self.derivationRecord(D, self.builder.program.types.fieldSpan(fields), operand, ctx),
            .tuple => |items| try self.derivationTuple(D, self.builder.program.types.span(items), operand, ctx),
            .tag_union => |tags| try D.tagUnion(self, ty, tags, operand, ctx),
            .named => |named| if (named.backing) |backing|
                try D.named(self, ty, backing.ty, operand, ctx)
            else
                try D.leaf(self, operand, ctx),
            .primitive,
            .zst,
            .func,
            .erased,
            .box,
            => try D.leaf(self, operand, ctx),
        };
    }

    /// Emit a call to the memoized recursive helper for `ty`, generating its def
    /// on first request.
    fn derivationCall(
        self: *BodyContext,
        comptime D: type,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const def_id = try self.derivationDefForType(D, ty, ctx);
        const callee = try self.addExprWithTypeCell(
            try D.fnType(self, ty, ctx.result_ty),
            .{ .def_ref = .{ .draft = def_id } },
        );
        const args = D.callArgs(operand);
        return try self.addExpr(.{
            .ty = ctx.result_ty,
            .data = .{ .call_value = .{
                .callee = callee,
                .args = try self.addExprSpan(&args),
            } },
        });
    }

    /// Dispatch a component to its exact checked method target, shared by every
    /// derivation. The argument types come from the comptime `Deriver`; the
    /// operand-to-args mapping reuses `D.callArgs`.
    fn derivationMethodCall(
        self: *BodyContext,
        comptime D: type,
        lookup: MethodLookup,
        ty: Type.TypeId,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        const callee = planned: {
            if (self.frozen_equality_method_calls) |planned_calls| {
                break :planned planned_calls.get(ty) orelse
                    Common.invariant("frozen structural derivation emission reached an unplanned component method");
            }
            const arg_tys = D.methodArgTypes(ty, ctx.result_ty);
            const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &arg_tys, ctx.result_ty);
            break :planned try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize);
        };
        const args = D.callArgs(operand);
        return try self.addExpr(.{ .ty = ctx.result_ty, .data = .{ .call_proc = .{
            .callee = draftProcCalleeForSlot(callee),
            .args = try self.addExprSpan(&args),
            .captures = try self.methodTargetCaptureSpan(lookup),
        } } });
    }

    fn derivationDefForType(
        self: *BodyContext,
        comptime D: type,
        value_ty: Type.TypeId,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftDefId {
        const cache = D.defCache(self);
        const address = D.defAddress(value_ty, ctx.result_ty);
        if (cache.get(address)) |entry| return entry.id();

        const def_id = try self.draft.reserveDef(self.draft.current_owner);
        try cache.put(address, .{ .reserved = def_id });

        // A helper takes two args: the value (`value_ty`) and a second operand
        // whose type is derivation-specific (the other equality operand at
        // `value_ty`, or the running hasher at `result_ty`).
        const second_ty = D.helperSecondArgType(value_ty, ctx.result_ty);
        const self_local = try self.addLocal(self.builder.symbols.fresh(), value_ty);
        const aux_local = try self.addLocal(self.builder.symbols.fresh(), second_ty);
        const self_expr = try self.localExpr(self_local, value_ty);
        const aux_expr = try self.localExpr(aux_local, second_ty);
        const operand = D.helperOperand(self_expr, aux_expr);

        // The helper body is the structural expansion for this type. Temporarily
        // remove the caller's active mark so the body expands exactly one layer
        // and only recursive edges inside that layer call back to the reserved
        // helper.
        const stack = D.expansionStack(self);
        if (!stack.remove(value_ty)) {
            Common.invariant("recursive structural derivation helper requested outside an active expansion");
        }
        defer stack.putAssumeCapacity(value_ty, {});

        const body = try self.lowerDerivationExpansion(D, value_ty, operand, ctx);
        const args = try self.addTypedLocalSpan(&.{
            .{ .local = self_local, .ty = value_ty },
            .{ .local = aux_local, .ty = second_ty },
        });
        self.draft.setDef(def_id, .{
            .symbol = self.builder.symbols.fresh(),
            .fn_def = null,
            .args = args,
            .body = .{ .roc = body },
            .ret = try self.draftTypeCell(ctx.result_ty),
        });
        try cache.put(address, .{ .ready = def_id });
        return def_id;
    }

    fn derivationRecord(
        self: *BodyContext,
        comptime D: type,
        fields: anytype,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        // Copy because recursive lowerDerivation may reallocate types.fields, invalidating the slice.
        const fields_copy = try GuardedList.dupe(self.allocator, Type.Field, fields);
        defer self.allocator.free(fields_copy);
        var state = try D.combineSeed(self, operand, ctx);
        var i: usize = 0;
        while (i < fields_copy.len) : (i += 1) {
            const field = fields_copy[if (D.forward) i else fields_copy.len - 1 - i];
            const component = try D.componentForField(self, operand, state, field);
            const result = try self.lowerDerivation(D, field.ty, component, ctx);
            state = try D.combine(self, state, result, ctx);
        }
        return state;
    }

    fn derivationTuple(
        self: *BodyContext,
        comptime D: type,
        items: anytype,
        operand: D.Operand,
        ctx: DerivationCtx,
    ) Allocator.Error!DraftExprId {
        // Copy because recursive lowerDerivation may reallocate types.spans, invalidating the slice.
        const items_copy = try GuardedList.dupe(self.allocator, Type.TypeId, items);
        defer self.allocator.free(items_copy);
        var state = try D.combineSeed(self, operand, ctx);
        var i: usize = 0;
        while (i < items_copy.len) : (i += 1) {
            const index = if (D.forward) i else items_copy.len - 1 - i;
            const item_ty = items_copy[index];
            const component = try D.componentForTuple(self, operand, state, item_ty, index);
            const result = try self.lowerDerivation(D, item_ty, component, ctx);
            state = try D.combine(self, state, result, ctx);
        }
        return state;
    }

    fn boolLiteral(self: *BodyContext, value: bool, bool_ty: Type.TypeId) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const lhs = try self.intLiteralExpr(0, u64_ty);
        const rhs = try self.intLiteralExpr(if (value) 0 else 1, u64_ty);
        return try self.lowLevelExpr(.num_is_eq, &.{ lhs, rhs }, bool_ty);
    }

    fn lowerDirectStructuralHash(
        self: *BodyContext,
        checked_ret_ty: checked.CheckedTypeId,
        h: anytype,
    ) Allocator.Error!DraftExprId {
        const ret_ty = try self.lowerTypeView(checked_ret_ty);
        return try self.lowerDirectStructuralHashAtType(h, ret_ty);
    }

    fn lowerDirectStructuralHashAtType(
        self: *BodyContext,
        h: anytype,
        hasher_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const value_ty = try self.lowerExprType(h.value);
        const value = try self.lowerExprAtType(h.value, value_ty);
        const hasher = try self.lowerExprAtType(h.hasher, hasher_ty);
        return try self.lowerHashExpr(value_ty, value, hasher, hasher_ty);
    }

    /// Emit `Hasher.write_u64(hasher, value)` as a low-level operation.
    fn hasherWriteU64(
        self: *BodyContext,
        hasher: DraftExprId,
        value: u64,
        hasher_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const value_expr = try self.intLiteralExpr(value, u64_ty);
        return try self.lowLevelExpr(.hasher_write_u64, &.{ hasher, value_expr }, hasher_ty);
    }

    const MatchOutput = union(enum) {
        value: DraftTypeCell,
        state_result: struct {
            result_cell: DraftTypeCell,
            state_cell: DraftTypeCell,
            merge_binders: []const MergeBinder,
        },
        state_only: struct {
            state_cell: DraftTypeCell,
            merge_binders: []const MergeBinder,
        },
    };

    fn matchOutputCell(_: *BodyContext, output: MatchOutput) DraftTypeCell {
        return switch (output) {
            .value => |cell| cell,
            .state_result => |state| state.state_cell,
            .state_only => |state| state.state_cell,
        };
    }

    fn lowerMatchBranchBody(
        self: *BodyContext,
        body: checked.CheckedExprId,
        output: MatchOutput,
    ) Allocator.Error!DraftExprId {
        return switch (output) {
            .value => |result_cell| try self.lowerBranchValueAtTypeCell(body, result_cell),
            .state_result => |state| try self.lowerBodyThenStateResultAtTypeCells(
                body,
                state.result_cell,
                state.state_cell,
                state.merge_binders,
            ),
            .state_only => |state| try self.lowerBodyThenStateOnlyAtTypeCell(
                body,
                state.state_cell,
                state.merge_binders,
            ),
        };
    }

    fn lowerBranchValueAtTypeCell(
        self: *BodyContext,
        body: checked.CheckedExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        if (self.checkedExprDivergesInLoweredRuntime(body)) {
            return try self.lowerDivergentExprAtTypeCell(body, result_cell);
        }
        const result_node = try result_cell.toGraphNode(self.graph);
        if (try self.nodeIsProvenUninhabited(result_node)) {
            return try self.lowerExplicitUninhabitedInvocationAtTypeCell(body, result_cell);
        }
        return try self.lowerExprAtTypeCell(body, result_cell);
    }

    fn lowerMatchExpr(self: *BodyContext, expr_id: checked.CheckedExprId, match: anytype, result_ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.lowerMatchExprAtTypeCell(expr_id, match, .{ .sealed = result_ty });
    }

    fn lowerMatchExprAtTypeCell(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        match: anytype,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const comptime_site = try self.matchComptimeSite(expr_id, match);
        const merge_binders = try self.stateMergeBinders(expr_id);
        defer self.allocator.free(merge_binders);
        if (merge_binders.len == 0) {
            var selection = try self.initControlFlowResultSelection(
                self.view.bodies.expr(expr_id).ty,
                result_cell,
            );
            const data = try self.lowerMatch(
                match,
                .{ .value = selection.selected },
                comptime_site,
                &selection,
            );
            return try self.addExprWithTypeCell(
                try self.finishControlFlowResultSelection(selection),
                data,
            );
        }

        const state_cell = try self.stateResultTypeCell(merge_binders, result_cell);
        const state_expr = try self.lowerMatchExprWithOutput(match, .{ .state_result = .{
            .result_cell = result_cell,
            .state_cell = state_cell,
            .merge_binders = merge_binders,
        } }, comptime_site);
        return try self.unwrapStateResultAtTypeCells(state_expr, state_cell, result_cell, merge_binders);
    }

    fn lowerMatchExprWithOutput(
        self: *BodyContext,
        match: anytype,
        output: MatchOutput,
        comptime_site: ?DraftComptimeSiteId,
    ) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(
            self.matchOutputCell(output),
            try self.lowerMatch(match, output, comptime_site, null),
        );
    }

    fn patternNeedsExplicitBinding(self: *BodyContext, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .list => true,
            .record_destructure => |destructs| blk: {
                if (self.recordDestructsNeedExplicitRest(destructs)) break :blk true;
                if (try self.recordDestructsHaveOptionalField(pattern.ty, destructs)) break :blk true;
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child| child,
                        .rest => |rest| rest,
                    };
                    if (try self.patternNeedsExplicitBinding(child)) break :blk true;
                }
                break :blk false;
            },
            .as => |as| try self.patternNeedsExplicitBinding(as.pattern),
            .applied_tag => |tag| blk: {
                for (tag.args) |arg| {
                    if (try self.patternNeedsExplicitBinding(arg)) break :blk true;
                }
                break :blk false;
            },
            .nominal => |nominal| try self.patternNeedsExplicitBinding(nominal.backing_pattern),
            .tuple => |items| blk: {
                for (items) |item| {
                    if (try self.patternNeedsExplicitBinding(item)) break :blk true;
                }
                break :blk false;
            },
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => false,
        };
    }

    fn patternRequiresOwnMaterialization(self: *BodyContext, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .list => true,
            .record_destructure => |destructs| self.recordDestructsNeedExplicitRest(destructs) or
                try self.recordDestructsHaveOptionalField(pattern.ty, destructs),
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .tuple,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => false,
        };
    }

    const CheckedPatternRefutabilityAdapter = struct {
        pub const PatternId = checked.CheckedPatternId;

        ctx: *BodyContext,

        pub fn patternClass(self: @This(), pattern_id: PatternId) PatternRefutability.PatternClass {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .pending,
                .assign,
                .underscore,
                .runtime_error,
                => .cannot_miss,
                .as,
                .nominal,
                => .child,
                .tuple => .sequence,
                .record_destructure => .record,
                .list => .list,
                .applied_tag,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                => .can_miss,
            };
        }

        pub fn child(self: @This(), pattern_id: PatternId) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .as => |as| as.pattern,
                .nominal => |nominal| nominal.backing_pattern,
                .pending,
                .assign,
                .applied_tag,
                .record_destructure,
                .list,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn sequenceLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .tuple => |items| items.len,
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .list,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn sequenceChild(self: @This(), pattern_id: PatternId, index: usize) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .tuple => |items| items[index],
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .list,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn recordLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .record_destructure => |destructs| destructs.len,
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .list,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn recordChild(self: @This(), pattern_id: PatternId, index: usize) PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .record_destructure => |destructs| switch (destructs[index].kind) {
                    .required, .sub_pattern, .rest => |child_pattern| child_pattern,
                },
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .list,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn listFixedLen(self: @This(), pattern_id: PatternId) usize {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .list => |list| list.patterns.len,
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn listHasRest(self: @This(), pattern_id: PatternId) bool {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .list => |list| list.rest != null,
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }

        pub fn listRestPattern(self: @This(), pattern_id: PatternId) ?PatternId {
            const pattern = self.ctx.view.bodies.pattern(pattern_id);
            return switch (pattern.data) {
                .list => |list| list.rest.?.pattern,
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .tuple,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                .underscore,
                .runtime_error,
                => unreachable,
            };
        }
    };

    fn patternCanMiss(self: *BodyContext, pattern_id: checked.CheckedPatternId) bool {
        return PatternRefutability.canMiss(CheckedPatternRefutabilityAdapter, .{ .ctx = self }, pattern_id);
    }

    fn recordDestructsNeedExplicitRest(self: *BodyContext, destructs: []const checked.CheckedRecordDestruct) bool {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .rest => |child| if (!self.patternIsIgnored(child)) return true,
                .required, .sub_pattern => {},
            }
        }
        return false;
    }

    fn listPatternCondition(
        self: *BodyContext,
        scrutinee: DraftExprId,
        list: anytype,
    ) Allocator.Error!DraftExprId {
        const u64_ty = try self.builder.primitiveType(.u64);
        const bool_ty = try self.builder.primitiveType(.bool);
        const len = try self.lowLevelExpr(.list_len, &.{scrutinee}, u64_ty);
        const required = try self.intLiteralExpr(list.patterns.len, u64_ty);
        const op: can.CIR.Expr.LowLevel = if (list.rest == null) .num_is_eq else .num_is_gte;
        return try self.lowLevelExpr(op, &.{ len, required }, bool_ty);
    }

    fn applyListCheck(
        self: *BodyContext,
        scrutinee: DraftExprId,
        scrutinee_ty: Type.TypeId,
        list: anytype,
        body: DraftExprId,
        fallback: DraftExprId,
        output_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const elem_ty = self.constListElemType(scrutinee_ty);
        const u64_ty = try self.builder.primitiveType(.u64);
        const needs_len = if (list.rest) |rest| rest.index < list.patterns.len or rest.pattern != null else false;
        const len = if (needs_len) try self.lowLevelExpr(.list_len, &.{scrutinee}, u64_ty) else null;

        const values = try self.allocator.alloc(DraftExprId, list.patterns.len);
        defer self.allocator.free(values);
        const patterns = try self.allocator.alloc(DraftPatId, list.patterns.len);
        defer self.allocator.free(patterns);
        const sub_checks_per_elem = try self.allocator.alloc(std.ArrayList(CollectedListPattern), list.patterns.len);
        defer {
            for (sub_checks_per_elem) |*sub| sub.deinit(self.allocator);
            self.allocator.free(sub_checks_per_elem);
        }
        for (sub_checks_per_elem) |*sub| sub.* = std.ArrayList(CollectedListPattern).empty;
        const literal_guards_per_elem = try self.allocator.alloc([]PatternLiteralGuard, list.patterns.len);
        defer {
            for (literal_guards_per_elem) |guards| self.allocator.free(guards);
            self.allocator.free(literal_guards_per_elem);
        }
        for (literal_guards_per_elem) |*guards| guards.* = &.{};

        for (list.patterns, 0..) |pattern_id, index| {
            const item_index = try self.listPatternItemIndex(index, list.patterns.len, list.rest, len, u64_ty);
            values[index] = try self.lowLevelExpr(.list_get_unsafe, &.{ scrutinee, item_index }, elem_ty);
            const guards_start = self.pattern_literal_guards.items.len;
            patterns[index] = try self.lowerPatternAtTypeCollectingLists(pattern_id, elem_ty, &sub_checks_per_elem[index]);
            literal_guards_per_elem[index] = try self.drainPatternLiteralGuards(guards_start);
        }

        var rest_pat: ?DraftPatId = null;
        var rest_value: ?DraftExprId = null;
        var rest_sub_checks = std.ArrayList(CollectedListPattern).empty;
        defer rest_sub_checks.deinit(self.allocator);
        var rest_literal_guards: []PatternLiteralGuard = &.{};
        defer self.allocator.free(rest_literal_guards);
        if (list.rest) |rest| {
            if (rest.pattern) |rest_pattern| {
                const list_len = len orelse try self.lowLevelExpr(.list_len, &.{scrutinee}, u64_ty);
                const fixed_count = try self.intLiteralExpr(list.patterns.len, u64_ty);
                const rest_len = try self.lowLevelExpr(.num_minus, &.{ list_len, fixed_count }, u64_ty);
                const rest_start = try self.intLiteralExpr(rest.index, u64_ty);
                const range = try self.sublistRangeExpr(rest_start, rest_len, u64_ty);
                rest_value = try self.lowLevelExpr(.list_sublist, &.{ scrutinee, range }, scrutinee_ty);
                const guards_start = self.pattern_literal_guards.items.len;
                rest_pat = try self.lowerPatternAtTypeCollectingLists(rest_pattern, scrutinee_ty, &rest_sub_checks);
                rest_literal_guards = try self.drainPatternLiteralGuards(guards_start);
            }
        }

        var success = body;

        var index = patterns.len;
        while (index > 0) {
            index -= 1;
            var elem_success = success;
            var sub_index = sub_checks_per_elem[index].items.len;
            while (sub_index > 0) {
                sub_index -= 1;
                const sub = sub_checks_per_elem[index].items[sub_index];
                const sub_scrut = try self.localExpr(sub.local, sub.ty);
                elem_success = try self.applyListCheck(sub_scrut, sub.ty, sub, elem_success, fallback, output_ty);
            }
            elem_success = try self.applyPatternLiteralGuards(literal_guards_per_elem[index], elem_success, fallback, output_ty);
            success = try self.wrapPatternMatch(values[index], elem_ty, patterns[index], elem_success, fallback, output_ty);
        }

        if (rest_pat) |pat| {
            var rest_success = success;
            var sub_index = rest_sub_checks.items.len;
            while (sub_index > 0) {
                sub_index -= 1;
                const sub = rest_sub_checks.items[sub_index];
                const sub_scrut = try self.localExpr(sub.local, sub.ty);
                rest_success = try self.applyListCheck(sub_scrut, sub.ty, sub, rest_success, fallback, output_ty);
            }
            rest_success = try self.applyPatternLiteralGuards(rest_literal_guards, rest_success, fallback, output_ty);
            success = try self.wrapPatternMatch(
                rest_value orelse Common.invariant("list rest pattern had no lowered rest value"),
                scrutinee_ty,
                pat,
                rest_success,
                fallback,
                output_ty,
            );
        }

        const cond = try self.listPatternCondition(scrutinee, list);
        return try self.ifExpr(cond, success, fallback, output_ty);
    }

    fn preRegisterPatternBinders(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
    ) Allocator.Error!void {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| {
                if (self.currentOwnerPatternBinderLocal(binder) == null) {
                    const local = try self.addLocalWithBinder(self.builder.symbols.fresh(), ty, binder);
                    try self.bindLocalName(local, binder);
                    try self.binders.put(binder, local);
                }
            },
            .as => |as| {
                if (self.currentOwnerPatternBinderLocal(as.binder) == null) {
                    const local = try self.addLocalWithBinder(self.builder.symbols.fresh(), ty, as.binder);
                    try self.bindLocalName(local, as.binder);
                    try self.binders.put(as.binder, local);
                }
                try self.preRegisterPatternBinders(as.pattern, ty);
            },
            .applied_tag => |tag| {
                const name = try self.builder.tagName(self.view, tag.name);
                const payload_tys = self.builder.tagPayloadTypes(ty, name);
                if (tag.args.len != payload_tys.len) Common.invariant("pattern arity differs from concrete checked type");
                for (tag.args, payload_tys) |arg, arg_ty| {
                    try self.preRegisterPatternBinders(arg, arg_ty);
                }
            },
            .nominal => |nominal| {
                try self.preRegisterPatternBinders(nominal.backing_pattern, self.builder.namedBackingType(ty) orelse ty);
            },
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required, .sub_pattern => |child| {
                            const name = try self.builder.recordFieldName(self.view, destruct.label);
                            const child_ty = self.builder.recordFieldType(ty, name);
                            try self.preRegisterPatternBinders(child, child_ty);
                        },
                        .rest => |rest_pattern| {
                            if (!self.patternIsIgnored(rest_pattern)) {
                                Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
                            }
                        },
                    }
                }
            },
            .list => |list| {
                const elem_ty = self.constListElemType(ty);
                for (list.patterns) |child| {
                    try self.preRegisterPatternBinders(child, elem_ty);
                }
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| {
                        try self.preRegisterPatternBinders(rest_pattern, ty);
                    }
                }
            },
            .tuple => |items| {
                const item_tys = self.builder.tupleItemTypes(ty);
                if (items.len != item_tys.len) Common.invariant("pattern arity differs from concrete checked type");
                for (items, item_tys) |item, item_ty| {
                    try self.preRegisterPatternBinders(item, item_ty);
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| {
                        try self.preRegisterPatternBinders(capture, ty);
                    }
                }
            },
            .pending,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn lowerPatternAtTypeCollectingLists(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
        checks_out: *std.ArrayList(CollectedListPattern),
    ) Allocator.Error!DraftPatId {
        const pattern = self.view.bodies.pattern(pattern_id);
        try self.constrainTypeToMono(pattern.ty, ty);
        const data: BodyPatData = switch (pattern.data) {
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached Monotype lowering"),
            .assign => |binder| blk: {
                const local = if (self.currentOwnerPatternBinderLocal(binder)) |existing| existing else inner: {
                    const new_local = try self.addLocalWithBinder(self.builder.symbols.fresh(), ty, binder);
                    try self.bindLocalName(new_local, binder);
                    try self.binders.put(binder, new_local);
                    break :inner new_local;
                };
                break :blk .{ .bind = local };
            },
            .as => |as| blk: {
                const local = if (self.currentOwnerPatternBinderLocal(as.binder)) |existing| existing else inner: {
                    const new_local = try self.addLocalWithBinder(self.builder.symbols.fresh(), ty, as.binder);
                    try self.bindLocalName(new_local, as.binder);
                    try self.binders.put(as.binder, new_local);
                    break :inner new_local;
                };
                break :blk .{ .as = .{
                    .pattern = try self.lowerPatternAtTypeCollectingLists(as.pattern, ty, checks_out),
                    .local = local,
                } };
            },
            .applied_tag => |tag| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, checks_out) };
                }
                break :blk try self.lowerTagPatternCollectingLists(tag, ty, checks_out);
            },
            .nominal => |nominal| blk: {
                const backing_ty = if (self.builder.nominalConstructionLayer(ty)) |layer|
                    layer.backing
                else
                    self.builder.namedBackingType(ty) orelse ty;
                break :blk .{ .nominal = try self.lowerPatternAtTypeCollectingLists(nominal.backing_pattern, backing_ty, checks_out) };
            },
            .record_destructure => |destructs| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, checks_out) };
                }
                break :blk try self.lowerRecordPatternCollectingLists(pattern.ty, destructs, ty, checks_out);
            },
            .list => |list| blk: {
                const local = try self.addLocal(self.builder.symbols.fresh(), ty);
                try checks_out.append(self.allocator, .{
                    .local = local,
                    .ty = ty,
                    .patterns = list.patterns,
                    .rest = list.rest,
                });
                break :blk .{ .bind = local };
            },
            .tuple => |items| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, checks_out) };
                }
                break :blk .{ .tuple = try self.lowerPatternSpanAtTypesCollectingLists(items, self.builder.tupleItemTypes(ty), checks_out) };
            },
            .numeral_literal => |num| try self.lowerNumeralLiteralPattern(num, ty),
            .str_literal => |str| try self.lowerStringLiteralPattern(str, ty),
            .str_interpolation => |str| try self.lowerStrPatternCollectingLists(str, ty, checks_out),
            .underscore => .wildcard,
        };
        return try self.addPat(.{ .ty = ty, .data = data });
    }

    fn lowerStrPatternCollectingLists(
        self: *BodyContext,
        str: anytype,
        ty: Type.TypeId,
        checks_out: *std.ArrayList(CollectedListPattern),
    ) Allocator.Error!BodyPatData {
        const steps = try self.allocator.alloc(DraftStrPatternStep, str.steps.len);
        defer self.allocator.free(steps);

        for (str.steps, 0..) |step, i| {
            steps[i] = .{
                .capture = if (step.capture) |capture| try self.lowerPatternAtTypeCollectingLists(capture, ty, checks_out) else null,
                .delimiter = try self.lowerStringLiteral(step.delimiter),
            };
        }

        return .{ .str_pattern = .{
            .prefix = try self.lowerStringLiteral(str.prefix),
            .steps = try self.addStrPatternStepSpan(steps),
            .end = switch (str.end) {
                .exact => .exact,
                .tail => .tail,
            },
        } };
    }

    fn lowerPatternSpanAtTypesCollectingLists(
        self: *BodyContext,
        checked_patterns: []const checked.CheckedPatternId,
        tys: anytype,
        checks_out: *std.ArrayList(CollectedListPattern),
    ) Allocator.Error!DraftSpan(DraftPatId) {
        if (checked_patterns.len != GuardedList.borrowLen(tys)) Common.invariant("pattern arity differs from concrete checked type");
        const stable_tys = try GuardedList.dupe(self.allocator, Type.TypeId, tys);
        defer self.allocator.free(stable_tys);
        const lowered = try self.allocator.alloc(DraftPatId, checked_patterns.len);
        defer self.allocator.free(lowered);
        for (checked_patterns, stable_tys, 0..) |child, child_ty, i| {
            lowered[i] = try self.lowerPatternAtTypeCollectingLists(child, child_ty, checks_out);
        }
        return try self.addPatSpan(lowered);
    }

    fn lowerTagPatternCollectingLists(
        self: *BodyContext,
        tag: anytype,
        ty: Type.TypeId,
        checks_out: *std.ArrayList(CollectedListPattern),
    ) Allocator.Error!BodyPatData {
        const name = try self.builder.tagName(self.view, tag.name);
        return .{ .tag = .{
            .name = name,
            .payloads = try self.lowerPatternSpanAtTypesCollectingLists(tag.args, self.builder.tagPayloadTypes(ty, name), checks_out),
        } };
    }

    fn lowerRecordPatternCollectingLists(
        self: *BodyContext,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
        ty: Type.TypeId,
        checks_out: *std.ArrayList(CollectedListPattern),
    ) Allocator.Error!BodyPatData {
        var lowered = std.ArrayList(DraftRecordDestruct).empty;
        defer lowered.deinit(self.allocator);
        for (destructs) |destruct| {
            const child = switch (destruct.kind) {
                .required => |pattern| pattern,
                .sub_pattern => |pattern| pattern,
                .rest => |pattern| {
                    if (self.patternIsIgnored(pattern)) continue;
                    Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
                },
            };
            // Optional-field destructs never reach the typed pattern family:
            // the explicit-binding routes and match translation own them
            // (design.md "Field Kinds").
            if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                Common.invariant("optional-field record destructure reached typed pattern lowering");
            }
            const name = try self.builder.recordFieldName(self.view, destruct.label);
            const child_ty = switch (destruct.kind) {
                .required, .sub_pattern => self.builder.recordFieldType(ty, name),
                .rest => unreachable,
            };
            try lowered.append(self.allocator, .{
                .name = name,
                .pattern = try self.lowerPatternAtTypeCollectingLists(child, child_ty, checks_out),
            });
        }
        return .{ .record = try self.addRecordDestructSpan(lowered.items) };
    }

    fn wrapPatternMatch(
        self: *BodyContext,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        pattern: DraftPatId,
        success: DraftExprId,
        miss: DraftExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const wildcard = try self.addPatWithTypeCell(value_cell, .wildcard);
        const branches = [_]DraftBranch{
            .{ .pat = pattern, .body = success },
            .{ .pat = wildcard, .body = miss },
        };
        return try self.addExprWithTypeCell(result_cell, .{ .match_ = .{
            .scrutinee = value,
            .branches = try self.addBranchSpan(&branches),
        } });
    }

    fn lowerBindingContinuation(
        self: *BodyContext,
        continuation: BindingContinuation,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return switch (continuation) {
            .expr => |expr| expr,
            .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, result_cell),
            .materialized_args => |args| blk: {
                if (args.index >= args.args.len) break :blk try self.lowerExprAtTypeCell(args.body, result_cell);
                const arg = args.args[args.index];
                const miss = try self.addExprWithTypeCell(result_cell, .{ .crash = try self.addStringLiteral("pattern match failed") });
                break :blk try self.lowerMaterializedPatternThen(
                    arg.pattern,
                    arg.value,
                    arg.ty,
                    result_cell,
                    .{ .materialized_args = .{
                        .args = args.args,
                        .index = args.index + 1,
                        .body = args.body,
                    } },
                    miss,
                );
            },
            .iterator_body => |body| try self.lowerIteratorBodyThenContinue(
                body.body,
                body.result_cell,
                body.rest_expr,
                body.carries,
            ),
        };
    }

    fn lowerPatternSuccessContinuation(
        self: *BodyContext,
        continuation: BindingContinuation,
        result_cell: DraftTypeCell,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        // Pre-registered binders are reused only while emitting this pattern's
        // shell. Its continuation is a distinct lexical lowering boundary:
        // declarations and reassignments there must allocate their own locals.
        const previous_reuse = self.reuse_pre_registered_pattern_binders;
        self.reuse_pre_registered_pattern_binders = false;
        defer self.reuse_pre_registered_pattern_binders = previous_reuse;
        const guard = success_guard orelse return try self.lowerBindingContinuation(continuation, result_cell);
        const previous_runtime_demand_guard_frames = self.runtime_demand_guard_frames;
        self.runtime_demand_guard_frames = try self.withPatternSuccessRuntimeDemandGuardFrame(guard);
        defer self.runtime_demand_guard_frames = previous_runtime_demand_guard_frames;
        return try self.lowerBindingContinuation(continuation, result_cell);
    }

    fn lowerMaterializedPatternValueThen(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        const value_node = try value_cell.toGraphNode(self.graph);
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern_id).ty, value_cell);
        if (!try self.patternNeedsExplicitBinding(pattern_id)) {
            const guards_start = self.pattern_literal_guards.items.len;
            const binds_start = self.optional_destruct_binds.items.len;
            const pat = try self.lowerPatternAtNode(pattern_id, value_node);
            const literal_guards = try self.drainPatternLiteralGuards(guards_start);
            defer self.allocator.free(literal_guards);
            const optional_binds = try self.drainOptionalDestructBinds(binds_start);
            defer self.allocator.free(optional_binds);
            var success = try self.lowerPatternSuccessContinuation(continuation, result_cell, success_guard);
            if (optional_binds.len > 0) {
                success = try self.applyOptionalDestructBinds(optional_binds, success);
            }
            const rest = try self.applyPatternLiteralGuardsAtCell(
                literal_guards,
                success,
                miss,
                result_cell,
            );
            return try self.wrapPatternMatch(value, value_cell, pat, rest, miss, result_cell);
        }

        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
        const local_expr = try self.addExprWithTypeCell(value_cell, .{ .local = local });
        const rest = try self.lowerMaterializedPatternThen(pattern_id, local_expr, value_cell, result_cell, continuation, miss);
        return try self.addExprWithTypeCell(result_cell, .{ .let_ = .{
            .bind = try self.addPatWithTypeCell(value_cell, .{ .bind = local }),
            .value = value,
            .rest = rest,
        } });
    }

    fn lowerMaterializedPatternThen(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
    ) Allocator.Error!DraftExprId {
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern_id).ty, value_cell);
        return try self.lowerMaterializedPatternThenInner(
            pattern_id,
            value,
            value_cell,
            result_cell,
            continuation,
            miss,
            .{
                .root_pattern = pattern_id,
                .root_node = try value_cell.toGraphNode(self.graph),
            },
        );
    }

    fn lowerMaterializedPatternThenInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern_id).ty, value_cell);
        const value_node = try value_cell.toGraphNode(self.graph);
        try self.preRegisterPatternBindersAtNode(pattern_id, value_node);
        const previous_reuse = self.reuse_pre_registered_pattern_binders;
        defer self.reuse_pre_registered_pattern_binders = previous_reuse;
        self.reuse_pre_registered_pattern_binders = true;
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .list => |list| try self.lowerListPatternBindingThen(value, value_cell, list, result_cell, continuation, miss, success_guard),
            .record_destructure => |destructs| if (self.recordDestructsNeedExplicitRest(destructs) or
                try self.recordDestructsHaveOptionalField(pattern.ty, destructs))
                try self.lowerRecordRestPatternBindingThen(value, value_cell, pattern.ty, destructs, result_cell, continuation, miss, success_guard)
            else if (try self.patternNeedsExplicitBinding(pattern_id))
                try self.lowerWrappedMaterializedPatternThen(pattern_id, value, value_node, value_cell, result_cell, continuation, miss, success_guard)
            else
                try self.lowerMaterializedPatternValueThen(pattern_id, value, value_cell, result_cell, continuation, miss, success_guard),
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .pending,
            .runtime_error,
            => try self.lowerMaterializedPatternValueThen(pattern_id, value, value_cell, result_cell, continuation, miss, success_guard),
            .as,
            .applied_tag,
            .nominal,
            .tuple,
            => if (try self.patternNeedsExplicitBinding(pattern_id))
                try self.lowerWrappedMaterializedPatternThen(pattern_id, value, value_node, value_cell, result_cell, continuation, miss, success_guard)
            else
                try self.lowerMaterializedPatternValueThen(pattern_id, value, value_cell, result_cell, continuation, miss, success_guard),
        };
    }

    fn applyPendingMaterializedPatterns(
        self: *BodyContext,
        pending: []const PendingMaterializedPattern,
        initial_success: DraftExprId,
        miss: DraftExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        var success = initial_success;
        var index = pending.len;
        while (index > 0) {
            index -= 1;
            const plan = pending[index];
            const local_value = try self.addExprWithTypeCell(plan.cell, .{ .local = plan.local });
            success = try self.lowerMaterializedPatternThenInner(
                plan.pattern,
                local_value,
                plan.cell,
                result_cell,
                .{ .expr = success },
                miss,
                null,
            );
        }
        return success;
    }

    fn lowerWrappedMaterializedPatternThen(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        value: DraftExprId,
        value_node: NodeId,
        value_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        var pending = std.ArrayList(PendingMaterializedPattern).empty;
        defer pending.deinit(self.allocator);
        const shell = try self.lowerPatternShellAtNode(pattern_id, value_node, &pending);
        if (pending.items.len == 0) {
            Common.invariant("recursive materialized wrapper produced no explicit descendant plan");
        }
        const continuation_expr = try self.lowerPatternSuccessContinuation(continuation, result_cell, success_guard);
        const success = try self.applyPendingMaterializedPatterns(pending.items, continuation_expr, miss, result_cell);
        return try self.wrapPatternMatch(value, value_cell, shell, success, miss, result_cell);
    }

    fn lowerListPatternBindingThen(
        self: *BodyContext,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        list: anytype,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        const success = try self.lowerListPatternBindingSuccess(value, value_cell, list, result_cell, continuation, miss, success_guard);
        const cond = try self.listPatternCondition(value, list);
        const branches = [_]DraftIfBranch{.{ .cond = cond, .body = success }};
        return try self.addExprWithTypeCell(result_cell, .{ .if_ = .{
            .branches = try self.addIfBranchSpan(&branches),
            .final_else = miss,
        } });
    }

    fn listPatternItemIndex(
        self: *BodyContext,
        index: usize,
        pattern_count: usize,
        rest: ?checked.CheckedListRestPattern,
        len: ?DraftExprId,
        u64_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        if (rest) |rest_info| {
            if (index >= rest_info.index) {
                const list_len = len orelse Common.invariant("list pattern trailing item index required list length");
                const trailing_count = try self.intLiteralExpr(pattern_count - index, u64_ty);
                return try self.lowLevelExpr(.num_minus, &.{ list_len, trailing_count }, u64_ty);
            }
        }
        return try self.intLiteralExpr(index, u64_ty);
    }

    fn sublistRangeExpr(
        self: *BodyContext,
        start: DraftExprId,
        len: DraftExprId,
        u64_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const len_name = try self.builder.program.names.internRecordFieldLabel("len");
        const start_name = try self.builder.program.names.internRecordFieldLabel("start");
        const fields = [_]Type.Field{
            .{ .name = len_name, .ty = u64_ty, .default = null },
            .{ .name = start_name, .ty = u64_ty, .default = null },
        };
        const ty = try self.builder.program.types.add(.{ .record = try self.builder.program.types.addRecordFields(&self.builder.program.names, &fields) });
        const exprs = [_]DraftFieldExpr{
            .{ .name = len_name, .value = len },
            .{ .name = start_name, .value = start },
        };
        return try self.addExpr(.{ .ty = ty, .data = .{ .record = try self.addFieldExprSpan(&exprs) } });
    }

    fn lowerListPatternBindingSuccess(
        self: *BodyContext,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        list: anytype,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        const value_node = try value_cell.toGraphNode(self.graph);
        const elem_node = try self.graph.listElementNode(value_node);
        const elem_cell = DraftTypeCell.fromGraphNode(elem_node);
        const values = try self.allocator.alloc(DraftExprId, list.patterns.len);
        defer self.allocator.free(values);
        const patterns = try self.allocator.alloc(DraftPatId, list.patterns.len);
        defer self.allocator.free(patterns);
        const pending_per_item = try self.allocator.alloc(std.ArrayList(PendingMaterializedPattern), list.patterns.len);
        defer {
            for (pending_per_item) |*pending| pending.deinit(self.allocator);
            self.allocator.free(pending_per_item);
        }
        for (pending_per_item) |*pending| pending.* = .empty;
        const u64_ty = try self.builder.primitiveType(.u64);
        const needs_len = if (list.rest) |rest| rest.index < list.patterns.len or rest.pattern != null else false;
        const len = if (needs_len) try self.lowLevelExpr(.list_len, &.{value}, u64_ty) else null;

        for (list.patterns, 0..) |pattern_id, index| {
            const item_index = try self.listPatternItemIndex(index, list.patterns.len, list.rest, len, u64_ty);
            values[index] = try self.addExprWithTypeCell(elem_cell, .{ .low_level = .{
                .op = .list_get_unsafe,
                .args = try self.addExprSpan(&.{ value, item_index }),
            } });
            patterns[index] = try self.lowerPatternPlanPlaceholderAtNode(pattern_id, elem_node, &pending_per_item[index]);
        }

        var rest_pat: ?DraftPatId = null;
        var rest_value: ?DraftExprId = null;
        var rest_pending = std.ArrayList(PendingMaterializedPattern).empty;
        defer rest_pending.deinit(self.allocator);
        if (list.rest) |rest| {
            if (rest.pattern) |rest_pattern| {
                const list_len = len orelse try self.lowLevelExpr(.list_len, &.{value}, u64_ty);
                const fixed_count = try self.intLiteralExpr(list.patterns.len, u64_ty);
                const rest_len = try self.lowLevelExpr(.num_minus, &.{ list_len, fixed_count }, u64_ty);
                const rest_start = try self.intLiteralExpr(rest.index, u64_ty);
                const range = try self.sublistRangeExpr(rest_start, rest_len, u64_ty);
                rest_value = try self.addExprWithTypeCell(value_cell, .{ .low_level = .{
                    .op = .list_sublist,
                    .args = try self.addExprSpan(&.{ value, range }),
                } });
                rest_pat = try self.lowerPatternPlanPlaceholderAtNode(rest_pattern, value_node, &rest_pending);
            }
        }

        var success = try self.lowerPatternSuccessContinuation(continuation, result_cell, success_guard);
        const has_rest_plan = rest_pat != null;
        const rest_index = if (list.rest) |rest| rest.index else 0;
        var sequence_index = patterns.len + @intFromBool(has_rest_plan);
        while (sequence_index > 0) {
            sequence_index -= 1;
            if (has_rest_plan and sequence_index == rest_index) {
                const rest_success = try self.applyPendingMaterializedPatterns(
                    rest_pending.items,
                    success,
                    miss,
                    result_cell,
                );
                success = try self.wrapPatternMatch(
                    rest_value orelse Common.invariant("list rest pattern had no lowered rest value"),
                    value_cell,
                    rest_pat.?,
                    rest_success,
                    miss,
                    result_cell,
                );
                continue;
            }
            const fixed_index = sequence_index - @intFromBool(has_rest_plan and sequence_index > rest_index);
            const item_success = try self.applyPendingMaterializedPatterns(
                pending_per_item[fixed_index].items,
                success,
                miss,
                result_cell,
            );
            success = try self.wrapPatternMatch(values[fixed_index], elem_cell, patterns[fixed_index], item_success, miss, result_cell);
        }
        return success;
    }

    fn lowerRecordRestPatternBindingThen(
        self: *BodyContext,
        value: DraftExprId,
        value_cell: DraftTypeCell,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
        result_cell: DraftTypeCell,
        continuation: BindingContinuation,
        miss: DraftExprId,
        success_guard: ?PatternSuccessGuard,
    ) Allocator.Error!DraftExprId {
        const PreparedChild = struct {
            value: DraftExprId,
            cell: DraftTypeCell,
            shell: DraftPatId,
            pending: std.ArrayList(PendingMaterializedPattern),
        };
        const value_node = try value_cell.toGraphNode(self.graph);
        const prepared = try self.allocator.alloc(?PreparedChild, destructs.len);
        defer {
            for (prepared) |*entry| {
                if (entry.*) |*child| child.pending.deinit(self.allocator);
            }
            self.allocator.free(prepared);
        }
        for (prepared) |*entry| entry.* = null;

        for (destructs, 0..) |destruct, index| {
            var pending = std.ArrayList(PendingMaterializedPattern).empty;
            var pending_owned = true;
            defer if (pending_owned) pending.deinit(self.allocator);
            switch (destruct.kind) {
                .required, .sub_pattern => |child| {
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    const field_node = try self.graph.recordFieldNode(value_node, name);
                    const field_cell = DraftTypeCell.fromGraphNode(field_node);
                    const field_value = try self.addExprWithTypeCell(field_cell, .{
                        .field_access = .{
                            .receiver = value,
                            .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = name }}),
                        },
                    });
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                        // The field's slot holds the tagged
                        // `[#Missing, #Present(v)]` union; the bound value is
                        // that slot materialized as the binder's checked
                        // `Try(v, [MissingField])` (design.md "Field
                        // Kinds"), against which the sub-pattern matches.
                        const try_node = try self.instNode(self.view.bodies.pattern(child).ty);
                        const try_value = try self.optionalDestructTryExprAtNode(field_value, field_node, try_node);
                        prepared[index] = .{
                            .value = try_value,
                            .cell = DraftTypeCell.fromGraphNode(try_node),
                            .shell = try self.lowerPatternPlanPlaceholderAtNode(child, try_node, &pending),
                            .pending = pending,
                        };
                        pending_owned = false;
                        continue;
                    }
                    prepared[index] = .{
                        .value = field_value,
                        .cell = field_cell,
                        .shell = try self.lowerPatternPlanPlaceholderAtNode(child, field_node, &pending),
                        .pending = pending,
                    };
                    pending_owned = false;
                },
                .rest => |child| {
                    if (self.patternIsIgnored(child)) continue;
                    const rest_node = try self.recordRestNodeForPattern(value_node, destructs, child);
                    const rest_cell = DraftTypeCell.fromGraphNode(rest_node);
                    prepared[index] = .{
                        .value = try self.lowerRecordRestValueWithTypeCell(value, value_node, rest_cell, rest_node),
                        .cell = rest_cell,
                        .shell = try self.lowerPatternPlanPlaceholderAtNode(child, rest_node, &pending),
                        .pending = pending,
                    };
                    pending_owned = false;
                },
            }
        }

        var success = try self.lowerPatternSuccessContinuation(continuation, result_cell, success_guard);
        var i = destructs.len;
        while (i > 0) {
            i -= 1;
            const child = prepared[i] orelse continue;
            const child_success = try self.applyPendingMaterializedPatterns(
                child.pending.items,
                success,
                miss,
                result_cell,
            );
            success = try self.wrapPatternMatch(
                child.value,
                child.cell,
                child.shell,
                child_success,
                miss,
                result_cell,
            );
        }
        return success;
    }

    fn lowerRecordRestValueWithTypeCell(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        rest_cell: DraftTypeCell,
        rest_node: NodeId,
    ) Allocator.Error!DraftExprId {
        try self.relateRecordRestNodeToSource(value_node, rest_node);
        const rest_fields = try self.allocator.dupe(InstField, (try self.graph.recordNodes(rest_node)).fields);
        defer self.allocator.free(rest_fields);
        std.mem.sort(InstField, rest_fields, &self.builder.program.names, instRecordFieldLessThan);
        const fields = try self.allocator.alloc(DraftFieldExpr, rest_fields.len);
        defer self.allocator.free(fields);
        for (rest_fields, 0..) |field, i| {
            fields[i] = .{
                .name = field.name,
                .value = try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(try self.graph.recordFieldNode(value_node, field.name)),
                    .{ .field_access = .{
                        .receiver = value,
                        .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = field.name }}),
                    } },
                ),
            };
        }
        return try self.addExprWithTypeCell(rest_cell, .{
            .record = try self.addFieldExprSpan(fields),
        });
    }

    fn relateRecordRestNodeToSource(
        self: *BodyContext,
        source_node: NodeId,
        rest_node: NodeId,
    ) Allocator.Error!void {
        const rest_fields = (try self.graph.recordNodes(rest_node)).fields;
        for (rest_fields) |field| {
            try self.graph.unify(field.ty, try self.graph.recordFieldNode(source_node, field.name));
        }
    }

    fn recordRestNodeForPattern(
        self: *BodyContext,
        source_node: NodeId,
        destructs: []const checked.CheckedRecordDestruct,
        rest_pattern: checked.CheckedPatternId,
    ) Allocator.Error!NodeId {
        const source_fields = (try self.graph.recordNodes(source_node)).fields;
        var remaining = std.ArrayList(InstField).empty;
        defer remaining.deinit(self.allocator);
        for (source_fields) |field| {
            var consumed = false;
            for (destructs) |destruct| switch (destruct.kind) {
                .required, .sub_pattern => {
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    if (field.name == name) consumed = true;
                },
                .rest => {},
            };
            if (!consumed) try remaining.append(self.allocator, field);
        }

        const rest_node = if (remaining.items.len == 0)
            try self.graph.newNode(.empty_record)
        else
            try self.graph.newNode(.{ .record = .{
                .fields = try self.graph.arena().dupe(InstField, remaining.items),
                .ext = try self.graph.newNode(.empty_record),
            } });
        try self.graph.unify(
            try self.lowerTypeNode(self.view.bodies.pattern(rest_pattern).ty),
            rest_node,
        );
        return rest_node;
    }

    fn runtimeCrashExpr(self: *BodyContext, ty: Type.TypeId, message: []const u8) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .crash = try self.addStringLiteral(message) },
        });
    }

    fn runtimeCrashExprAtCell(self: *BodyContext, cell: DraftTypeCell, message: []const u8) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .crash = try self.addStringLiteral(message) });
    }

    fn comptimeExhaustivenessFailedExpr(self: *BodyContext, ty: Type.TypeId, site: DraftComptimeSiteId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{
            .ty = ty,
            .data = .{ .comptime_exhaustiveness_failed = site },
        });
    }

    fn addComptimeSite(
        self: *BodyContext,
        kind: Ast.ComptimeSiteKind,
        region: base.Region,
        checked_site: ?checked.CheckedExhaustivenessSiteId,
        branch_regions: []const base.Region,
    ) Allocator.Error!DraftComptimeSiteId {
        return try self.draft.addComptimeSite(kind, region, checked_site, branch_regions);
    }

    fn wrapComptimeBranch(
        self: *BodyContext,
        site: ?DraftComptimeSiteId,
        branch_index: usize,
        body: DraftExprId,
    ) Allocator.Error!DraftExprId {
        const actual_site = site orelse return body;
        return try self.addExprWithTypeCell(self.exprTypeCell(body), .{ .comptime_branch_taken = .{
            .site = actual_site,
            .branch_index = @intCast(branch_index),
            .body = body,
        } });
    }

    fn matchComptimeSite(self: *BodyContext, expr_id: checked.CheckedExprId, match: anytype) Allocator.Error!?DraftComptimeSiteId {
        if (match.skip_exhaustiveness) return null;
        const shared_site_kind: ExhaustivenessContext.SiteKind = switch (match.comptime_site_kind) {
            .match => .match,
            .destructure => .destructure,
        };
        if (!self.shouldRecordComptimeSite(shared_site_kind)) return null;
        const branch_regions = try self.matchBranchRegions(match.branches);
        defer self.allocator.free(branch_regions);
        const expr = self.view.bodies.expr(expr_id);
        const site_kind: Ast.ComptimeSiteKind = switch (shared_site_kind) {
            .match => .match,
            .destructure => .destructure,
            .if_ => Common.invariant("if site kind reached match comptime site lowering"),
        };
        const checked_site = if (ExhaustivenessContext.siteHasPendingStaticDiagnostic(shared_site_kind))
            switch (shared_site_kind) {
                .match => self.view.exhaustiveness_sites.lookupByMatchExpr(expr_id),
                .destructure => blk: {
                    if (match.branches.len != 1) break :blk null;
                    const patterns = match.branches[0].patternsSlice(self.view.bodies);
                    if (patterns.len != 1) break :blk null;
                    break :blk self.view.exhaustiveness_sites.lookupByDestructurePattern(patterns[0].pattern);
                },
                .if_ => Common.invariant("if site kind reached checked match site lookup"),
            }
        else
            null;
        return try self.addComptimeSite(site_kind, expr.source_region, checked_site, branch_regions);
    }

    fn matchBranchRegions(self: *BodyContext, branches: []const checked.CheckedMatchBranch) Allocator.Error![]base.Region {
        const regions = try self.allocator.alloc(base.Region, branchCount(branches));
        var index: usize = 0;
        for (branches) |branch| {
            for (branch.patternsSlice(self.view.bodies)) |pattern| {
                regions[index] = self.view.bodies.pattern(pattern.pattern).source_region;
                index += 1;
            }
        }
        return regions;
    }

    fn ifComptimeSite(self: *BodyContext, expr_id: checked.CheckedExprId, if_: anytype) Allocator.Error!?DraftComptimeSiteId {
        if (!if_.warn_unused_branches) return null;
        if (!self.shouldRecordComptimeSite(.if_)) return null;
        const branch_regions = try self.ifBranchRegions(if_);
        defer self.allocator.free(branch_regions);
        const expr = self.view.bodies.expr(expr_id);
        return try self.addComptimeSite(.if_, expr.source_region, null, branch_regions);
    }

    fn ifBranchRegions(self: *BodyContext, if_: anytype) Allocator.Error![]base.Region {
        const regions = try self.allocator.alloc(base.Region, if_.branches.len + 1);
        for (if_.branches, 0..) |branch, index| {
            regions[index] = self.view.bodies.expr(branch.cond).source_region;
        }
        regions[if_.branches.len] = self.view.bodies.expr(if_.final_else).source_region;
        return regions;
    }

    fn lowerMatch(
        self: *BodyContext,
        match: anytype,
        output: MatchOutput,
        comptime_site: ?DraftComptimeSiteId,
        value_selection: ?*ControlFlowResultSelection,
    ) Allocator.Error!BodyExprData {
        const PendingBranch = struct {
            ctx: BodyContext,
            pattern: checked.CheckedMatchBranchPattern,
            checked_guard: ?checked.CheckedExprId,
            checked_body: checked.CheckedExprId,
            source_index: usize,
            user_guard: ?DraftExprId = null,
            body: DraftExprId = undefined,
        };

        const scrutinee_node = try self.lowerExprTypeNode(match.cond);
        const scrutinee_cell = DraftTypeCell.fromGraphNode(scrutinee_node);
        const branches = try self.allocator.alloc(DraftBranch, branchCount(match.branches));
        defer self.allocator.free(branches);
        var pending = std.ArrayListUnmanaged(PendingBranch).empty;
        defer {
            for (pending.items) |*entry| entry.ctx.deinit();
            pending.deinit(self.allocator);
        }
        var source_index: usize = 0;
        for (match.branches) |branch| {
            for (branch.patternsSlice(self.view.bodies)) |pattern| {
                defer source_index += 1;
                if (try self.checkedPatternIsProvenUninhabited(pattern.pattern)) continue;
                var branch_ctx = try self.childContext(self.current_fn_key);
                errdefer branch_ctx.deinit();
                try relateRequestComponent(
                    self.graph,
                    scrutinee_node,
                    try branch_ctx.instNode(branch_ctx.view.bodies.pattern(pattern.pattern).ty),
                );
                try pending.append(self.allocator, .{
                    .ctx = branch_ctx,
                    .pattern = pattern,
                    .checked_guard = branch.guard,
                    .checked_body = branch.value,
                    .source_index = source_index,
                });
            }
        }

        // Every pattern relation must settle before binder cells are projected.
        // This gives derived binders such as record rest their exact graph node
        // without allocating a checked-type approximation and rebinding it later.
        for (pending.items) |*entry| {
            try entry.ctx.preRegisterPatternBindersAtNode(entry.pattern.pattern, scrutinee_node);
            try entry.ctx.applyAlternativeBinderRemaps(entry.pattern.binderRemapsSlice(self.view.bodies));
        }

        // Select the shared result representation from every inhabited branch
        // before any branch body is emitted. Match patterns supplied their
        // exact binder cells above, so branch-local lookups participate in this
        // relation-production pass as ordinary producer evidence.
        if (value_selection) |selection| {
            for (pending.items) |*entry| {
                try entry.ctx.prepareControlFlowResultSelection(selection, entry.checked_body);
            }
        }

        // All checked pattern evidence must reach the shared scrutinee before
        // any branch body can request another specialization.
        for (pending.items) |*entry| {
            entry.ctx.runtime_demand_guard_frames = try entry.ctx.withMatchBranchRuntimeDemandGuardFrame(
                entry.pattern.pattern,
                scrutinee_node,
            );
            entry.user_guard = if (entry.checked_guard) |guard_expr| try entry.ctx.lowerExpr(guard_expr) else null;
            const branch_output: MatchOutput = if (value_selection) |selection|
                .{ .value = selection.selected }
            else
                output;
            entry.body = try entry.ctx.lowerMatchBranchBody(entry.checked_body, branch_output);
            if (value_selection) |selection| {
                try self.includeControlFlowResult(selection, entry.body);
            }
        }

        const scrutinee = if (try self.nodeIsProvenUninhabited(scrutinee_node))
            try self.lowerUninhabitedScrutineeAtTypeCell(match.cond, scrutinee_cell)
        else
            try self.lowerExprAtTypeCell(match.cond, scrutinee_cell);
        var index: usize = 0;
        for (pending.items) |*entry| {
            entry.ctx.reuse_pre_registered_pattern_binders = true;
            entry.ctx.allow_recursive_pattern_lowering_for_match = true;
            var record_rests = std.ArrayList(PendingMatchRecordRestBinding).empty;
            defer record_rests.deinit(self.allocator);
            const pat = try entry.ctx.lowerMatchPatternAtNode(
                entry.pattern.pattern,
                scrutinee_node,
                entry.user_guard,
                entry.body,
                &record_rests,
            );
            if (try entry.ctx.checkedPatternIsProvenUninhabited(entry.pattern.pattern)) continue;
            // Translated optional-field destructs bound their raw slots in
            // the flat pattern; compute the user binders' Try values as
            // preludes around the branch body—and the guard, which may
            // also reference them (the pattern's slot locals are bound
            // before either runs).
            const optional_binds = try entry.ctx.drainOptionalDestructBinds(0);
            defer entry.ctx.allocator.free(optional_binds);
            if (optional_binds.len > 0) {
                entry.body = try entry.ctx.applyOptionalDestructBinds(optional_binds, entry.body);
                if (entry.user_guard) |user_guard| {
                    entry.user_guard = try entry.ctx.applyOptionalDestructBinds(optional_binds, user_guard);
                }
            }
            const guard = try entry.ctx.conjoinPatternLiteralGuards(entry.user_guard);
            const materialized = try entry.ctx.lowerMatchRecordRestBindings(record_rests.items, entry.body);
            branches[index] = .{
                .pat = pat,
                .bindings = materialized.guard_bindings,
                .guard = guard,
                .body = try entry.ctx.wrapComptimeBranch(
                    comptime_site,
                    entry.source_index,
                    materialized.body,
                ),
            };
            index += 1;
        }
        return .{ .match_ = .{
            .scrutinee = scrutinee,
            .branches = try self.addBranchSpan(branches[0..index]),
            .comptime_site = comptime_site,
        } };
    }

    fn runtimeDemandGuardFrameAddress(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        kind: RuntimeDemandGuardFrameKind,
    ) RuntimeDemandGuardFrameAddress {
        return self.runtimeDemandGuardFrameAddressRaw(@intFromEnum(pattern_id), kind);
    }

    fn runtimeDemandGuardFrameAddressRaw(
        self: *BodyContext,
        site: u32,
        kind: RuntimeDemandGuardFrameKind,
    ) RuntimeDemandGuardFrameAddress {
        return .{
            .module = self.view.key.bytes,
            .owner_module = names.procTemplateModuleDigest(self.owner_template).bytes,
            .owner_proc_base = @intFromEnum(self.owner_template.proc_base),
            .owner_template = @intFromEnum(self.owner_template.template),
            .pattern = site,
            .kind = kind,
        };
    }

    fn withMatchBranchRuntimeDemandGuardFrame(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(pattern_id, .match_branch);
        if (runtimeDemandGuardFrameStackContains(self.draft, self.runtime_demand_guard_frames, address))
            return self.runtime_demand_guard_frames;
        // A frame whose proof can never hold exempts nothing; pushing it would
        // only fragment specialization identity across guard contexts.
        const proof = (try self.maybeNodesImpossibilityProof(try self.runtimeDemandGuardsForPattern(pattern_id, node))) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withPatternSuccessRuntimeDemandGuardFrame(
        self: *BodyContext,
        guard: PatternSuccessGuard,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(guard.root_pattern, .pattern_success);
        const proof = (try self.maybeNodesImpossibilityProof(try self.runtimeDemandGuardsForPattern(guard.root_pattern, guard.root_node))) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withIteratorOneRuntimeDemandGuardFrame(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        step: IterStepShape,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        const address = self.runtimeDemandGuardFrameAddress(pattern_id, .iterator_one);
        if (runtimeDemandGuardFrameStackContains(self.draft, self.runtime_demand_guard_frames, address))
            return self.runtime_demand_guard_frames;
        const item_guards = try self.runtimeDemandGuardsForPattern(pattern_id, step.one_item.node);
        const guards = try self.graph.arena().alloc(NodeId, item_guards.len + 1);
        guards[0] = step.one_payload_node;
        @memcpy(guards[1..], item_guards);
        const proof = (try self.maybeNodesImpossibilityProof(guards)) orelse
            return self.runtime_demand_guard_frames;
        return try addRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            address,
            proof,
        );
    }

    fn withStatementSuccessRuntimeDemandGuardFrame(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        proof: RuntimeImpossibilityProofId,
    ) Allocator.Error!RuntimeDemandGuardFrameStack {
        // Checked statement IDs are unique within the module, and the owner
        // template is part of the address. Unlike recursive branch frames,
        // statement-success frames therefore cannot already be active.
        return try pushRuntimeDemandGuardFrame(
            self.draft,
            self.runtime_demand_guard_frames,
            self.runtimeDemandGuardFrameAddressRaw(@intFromEnum(statement_id), .statement_success),
            proof,
        );
    }

    fn runtimeDemandGuardFrameAddresses(
        self: *BodyContext,
    ) Allocator.Error![]const RuntimeDemandGuardFrameAddress {
        const addresses = try self.graph.arena().alloc(RuntimeDemandGuardFrameAddress, self.runtime_demand_guard_frames.depth);
        var address_index = addresses.len;
        var frame_id = self.runtime_demand_guard_frames.head;
        while (frame_id) |id| {
            const frame = runtimeDemandGuardFrame(self.draft, id);
            address_index -= 1;
            addresses[address_index] = frame.address;
            frame_id = frame.parent;
        }
        if (address_index != 0) {
            Common.invariant("runtime-demand guard stack length did not match its parent chain");
        }
        return addresses;
    }

    fn runtimeDemandGuardsForPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error![]const NodeId {
        var guards = std.ArrayList(NodeId).empty;
        defer guards.deinit(self.allocator);
        var seen = collections.DenseMap(NodeId, void).init(self.allocator);
        defer seen.deinit();
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        try self.collectRuntimeDemandGuardsForPattern(pattern_id, node, &guards, &seen, &active);
        return try self.graph.arena().dupe(NodeId, guards.items);
    }

    fn collectRuntimeDemandGuardsForPattern(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        guards: *std.ArrayList(NodeId),
        seen: *collections.DenseMap(NodeId, void),
        active: *std.AutoHashMap(PatternNodeVisit, void),
    ) Allocator.Error!void {
        const key: PatternNodeVisit = .{ .pattern = pattern_id, .node = node };
        if (active.contains(key)) {
            Common.invariant("runtime demand guard walk repeated an active pattern/node visit");
        }
        try active.put(key, {});
        defer _ = active.remove(key);

        const seen_entry = try seen.getOrPut(node);
        if (!seen_entry.found_existing) try guards.append(self.allocator, node);

        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .applied_tag => |tag| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal tag demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tag demand guard backing did not advance");
                    return try self.collectRuntimeDemandGuardsForPattern(pattern_id, backing.node, guards, seen, active);
                }
                const name = try self.builder.tagName(self.view, tag.name);
                for (tag.args, 0..) |arg, payload_index| {
                    try self.collectRuntimeDemandGuardsForPattern(
                        arg,
                        try self.graph.tagPayloadNode(node, name, payload_index),
                        guards,
                        seen,
                        active,
                    );
                }
            },
            .nominal => |nominal| {
                const backing = self.graph.namedNodes(node).backing orelse
                    Common.invariant("nominal demand guard had no runtime backing");
                if (backing.node == node) Common.invariant("nominal demand guard backing did not advance");
                try self.collectRuntimeDemandGuardsForPattern(nominal.backing_pattern, backing.node, guards, seen, active);
            },
            .record_destructure => |destructs| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal record demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal record demand guard backing did not advance");
                    return try self.collectRuntimeDemandGuardsForPattern(pattern_id, backing.node, guards, seen, active);
                }
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child| child,
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            const rest_node = try self.recordRestNodeForPattern(node, destructs, rest);
                            try self.collectRuntimeDemandGuardsForPattern(rest, rest_node, guards, seen, active);
                            continue;
                        },
                    };
                    // A destructured OPTIONAL field's sub-pattern runs in
                    // Try space (its own checked-type node), not against the
                    // record's tagged slot node—mirror the walk the
                    // binder registration and pattern lowering use.
                    if ((try self.recordDestructFieldKind(pattern.ty, destruct)) == .optional) {
                        try self.collectRuntimeDemandGuardsForPattern(
                            child,
                            try self.instNode(self.view.bodies.pattern(child).ty),
                            guards,
                            seen,
                            active,
                        );
                        continue;
                    }
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    try self.collectRuntimeDemandGuardsForPattern(
                        child,
                        try self.graph.recordFieldNode(node, name),
                        guards,
                        seen,
                        active,
                    );
                }
            },
            .list => |list| {
                if (list.patterns.len != 0) {
                    const elem = try self.graph.listElementNode(node);
                    const elem_seen = try seen.getOrPut(elem);
                    if (!elem_seen.found_existing) try guards.append(self.allocator, elem);
                    for (list.patterns) |child| {
                        try self.collectRuntimeDemandGuardsForPattern(child, elem, guards, seen, active);
                    }
                }
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| {
                        try self.collectRuntimeDemandGuardsForPattern(rest_pattern, node, guards, seen, active);
                    }
                }
            },
            .tuple => |items| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal tuple demand guard had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tuple demand guard backing did not advance");
                    return try self.collectRuntimeDemandGuardsForPattern(pattern_id, backing.node, guards, seen, active);
                }
                const item_nodes = try self.graph.tupleItemNodes(node);
                if (items.len != item_nodes.len) Common.invariant("tuple demand guard arity differed from graph tuple arity");
                for (items, item_nodes) |item, item_node| {
                    try self.collectRuntimeDemandGuardsForPattern(item, item_node, guards, seen, active);
                }
            },
            .as => |as| try self.collectRuntimeDemandGuardsForPattern(as.pattern, node, guards, seen, active),
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| {
                        try self.collectRuntimeDemandGuardsForPattern(capture, node, guards, seen, active);
                    }
                }
            },
            .pending,
            .assign,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn savePatternBinders(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        saved: *std.ArrayList(BinderRestore),
    ) Allocator.Error!void {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| try self.saveBinder(binder, saved),
            .as => |as| {
                try self.savePatternBinders(as.pattern, saved);
                try self.saveBinder(as.binder, saved);
            },
            .applied_tag => |tag| for (tag.args) |arg| try self.savePatternBinders(arg, saved),
            .nominal => |nominal| try self.savePatternBinders(nominal.backing_pattern, saved),
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required => |child_pattern| child_pattern,
                        .sub_pattern => |child_pattern| child_pattern,
                        .rest => |child_pattern| child_pattern,
                    };
                    try self.savePatternBinders(child, saved);
                }
            },
            .list => |list| {
                for (list.patterns) |child| try self.savePatternBinders(child, saved);
                if (list.rest) |rest| if (rest.pattern) |rest_pattern| try self.savePatternBinders(rest_pattern, saved);
            },
            .tuple => |items| for (items) |child| try self.savePatternBinders(child, saved),
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.savePatternBinders(capture, saved);
                }
            },
            .pending,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn saveBinder(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        saved: *std.ArrayList(BinderRestore),
    ) Allocator.Error!void {
        for (saved.items) |item| {
            if (item.binder == binder) return;
        }
        try saved.append(self.allocator, .{
            .binder = binder,
            .previous = self.binders.get(binder),
        });
    }

    fn applyAlternativeBinderRemaps(
        self: *BodyContext,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    ) Allocator.Error!void {
        for (remaps) |remap| {
            const local = self.binders.get(remap.candidate_binder) orelse
                Common.invariant("match alternative binder remap referenced an unbound candidate binder");
            try self.binders.put(remap.representative_binder, local);
        }
    }

    fn restoreBinders(self: *BodyContext, saved: []const BinderRestore) void {
        var index = saved.len;
        while (index > 0) {
            index -= 1;
            if (saved[index].previous) |previous| {
                self.binders.put(saved[index].binder, previous) catch |err| switch (err) {
                    error.OutOfMemory => Common.invariant("restoring a previously inserted binder cannot reallocate"),
                };
            } else {
                _ = self.binders.remove(saved[index].binder);
            }
        }
    }

    fn lowerIfExpr(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        if_: anytype,
        result_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerIfExprAtTypeCell(expr_id, if_, .{ .sealed = result_ty });
    }

    fn lowerIfExprAtTypeCell(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        if_: anytype,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const comptime_site = try self.ifComptimeSite(expr_id, if_);
        const merge_binders = try self.stateMergeBinders(expr_id);
        defer self.allocator.free(merge_binders);
        if (merge_binders.len == 0) {
            var selection = try self.initControlFlowResultSelection(
                self.view.bodies.expr(expr_id).ty,
                result_cell,
            );
            const data = try self.lowerIfAtTypeCells(
                if_,
                result_cell,
                result_cell,
                &.{},
                comptime_site,
                &selection,
            );
            return try self.addExprWithTypeCell(
                try self.finishControlFlowResultSelection(selection),
                data,
            );
        }

        const state_cell = try self.stateResultTypeCell(merge_binders, result_cell);
        const state_expr = try self.addExprWithTypeCell(
            state_cell,
            try self.lowerIfAtTypeCells(if_, result_cell, state_cell, merge_binders, comptime_site, null),
        );
        return try self.unwrapStateResultAtTypeCells(state_expr, state_cell, result_cell, merge_binders);
    }

    const ControlFlowResultSelection = struct {
        declared: DraftTypeCell,
        selected: DraftTypeCell,
        has_value: bool = false,
    };

    /// A value-producing control-flow expression owns one result selection
    /// while its inhabited branches are lowered. A finished expected Monotype
    /// remains an immutable outer interface, so selection begins on a fresh
    /// checked-public graph cell unless the caller already supplied exact
    /// generated-private evidence.
    fn initControlFlowResultSelection(
        self: *BodyContext,
        checked_ty: checked.CheckedTypeId,
        declared: DraftTypeCell,
    ) Allocator.Error!ControlFlowResultSelection {
        const declared_node = try declared.toGraphNode(self.graph);
        const selected = if (try self.graph.containsGeneratedPrivate(declared_node) or
            !try self.graph.containsFinishedMono(declared_node))
            DraftTypeCell.fromGraphNode(declared_node)
        else
            DraftTypeCell.fromGraphNode(try self.freshInstNode(checked_ty));
        return .{ .declared = declared, .selected = selected };
    }

    /// Discover producer-authored representation evidence before emitting any
    /// branch. Public-only evidence does not constrain the selection: every
    /// inhabited branch will consume the final selected request during the
    /// subsequent emission pass. Generated-private evidence is joined now, so
    /// source order cannot make an already-emitted branch authoritative.
    fn prepareControlFlowResultSelection(
        self: *BodyContext,
        selection: *ControlFlowResultSelection,
        checked_value: checked.CheckedExprId,
    ) Allocator.Error!void {
        const selected_node = try selection.selected.toGraphNode(self.graph);
        const produced_node = (try self.controlFlowResultEvidenceNode(checked_value, selected_node)) orelse return;
        if (!try self.graph.containsGeneratedPrivate(produced_node)) return;

        try selectRequestRepresentation(self.graph, selected_node, produced_node);
        const selected_private = try self.graph.containsGeneratedPrivate(selected_node);
        const produced_private = try self.graph.containsGeneratedPrivate(produced_node);
        if (selected_private == produced_private) return;
        if (!selected_private and produced_private) {
            selection.selected = DraftTypeCell.fromGraphNode(produced_node);
            return;
        }
        Common.invariant("control-flow representation prepass lost generated-private evidence");
    }

    /// Resolve the exact result evidence of a branch producer against the
    /// shared live request. This is the node-native counterpart of call-
    /// argument evidence: it deliberately keeps the expected graph cell live
    /// so recursive producers see the same fixed point during discovery and
    /// emission.
    fn controlFlowResultEvidenceNode(
        self: *BodyContext,
        checked_value: checked.CheckedExprId,
        expected_node: NodeId,
    ) Allocator.Error!?NodeId {
        if (self.checkedExprDivergesInLoweredRuntime(checked_value)) return null;
        const expr = self.view.bodies.expr(checked_value);
        return switch (expr.data) {
            .call => |call| blk: {
                const target = call.direct_target orelse break :blk null;
                const source_fn_ty = self.directCallInstantiationSourceFnType(target, call.source_fn_ty_payload);
                const fn_node = try self.directCallTypeNode(
                    expr.ty,
                    call,
                    source_fn_ty,
                    expected_node,
                );
                const fn_nodes = try self.graph.functionNodes(fn_node);
                if (self.isGeneratedIteratorEvidenceNode(fn_nodes.ret)) break :blk fn_nodes.ret;
                if (!self.isIteratorInterfaceNode(fn_nodes.ret)) break :blk fn_nodes.ret;

                try self.ensureNestedCallablesAtNodes(call.args, fn_nodes.args);
                const callee = try self.fnTemplateForDirectCallAtNode(
                    target,
                    source_fn_ty,
                    self.view.types.rootKey(source_fn_ty),
                    fn_node,
                );
                const completed_fn_node = try self.draftFnSlotTypeNode(callee, fn_node);
                break :blk (try self.graph.functionNodes(completed_fn_node)).ret;
            },
            .dispatch_call => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .interpolation => |interpolation| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                interpolation.plan,
                expected_node,
                .expression_lowering,
            ),
            .type_dispatch_call => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .method_eq => |plan| try self.dispatchResultTypeNodeInPhase(
                expr.ty,
                plan,
                expected_node,
                .expression_lowering,
            ),
            .field_access => try self.lowerExprTypeNode(checked_value),
            // Lookups are use-sites. Once a generated-private request is
            // selected, branch emission validates the lookup against that
            // request; the prepass must not join the raw stored binding cell.
            .lookup_local,
            .lookup_external,
            .lookup_required,
            => if (try self.graph.containsGeneratedPrivate(expected_node))
                expected_node
            else
                try self.lowerExprTypeNode(checked_value),
            .block => |block| if (block.statements.len == 0)
                try self.controlFlowResultEvidenceNode(block.final_expr, expected_node)
            else
                null,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .structural_eq, .structural_hash, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
    }

    fn includeControlFlowResult(
        self: *BodyContext,
        selection: *ControlFlowResultSelection,
        value: DraftExprId,
    ) Allocator.Error!void {
        if (self.exprImpossibilityProof(value) != null) return;
        const selected_node = try selection.selected.toGraphNode(self.graph);
        const value_cell = self.exprTypeCell(value);
        const value_node = try value_cell.toGraphNode(self.graph);
        try selectRequestRepresentation(self.graph, selected_node, value_node);

        const selected_private = try self.graph.containsGeneratedPrivate(selected_node);
        const value_private = try self.graph.containsGeneratedPrivate(value_node);
        if (selected_private != value_private) {
            if (!selection.has_value and !selected_private and value_private) {
                // A finished private producer remains immutable and therefore
                // cannot merge into the live public accumulator. Carry its
                // exact cell forward as the request for every later branch.
                selection.selected = value_cell;
            } else {
                Common.invariant("control-flow branch could not use its selected runtime representation");
            }
        }
        selection.has_value = true;
        self.draft.exprs.items[@intFromEnum(value)].ty = selection.selected;
    }

    fn finishControlFlowResultSelection(
        self: *BodyContext,
        selection: ControlFlowResultSelection,
    ) Allocator.Error!DraftTypeCell {
        // A control-flow expression whose every branch terminates never
        // produces a runtime result. Its checked result variable may therefore
        // remain unconstrained, and cannot supply representation evidence for
        // the enclosing continuation's declared result cell.
        if (!selection.has_value) return selection.declared;

        const declared_node = try selection.declared.toGraphNode(self.graph);
        const selected_node = try selection.selected.toGraphNode(self.graph);
        try relateRequestComponent(self.graph, declared_node, selected_node);
        return if (try self.graph.containsGeneratedPrivate(selected_node))
            selection.selected
        else
            selection.declared;
    }

    fn stateMergeBinders(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error![]MergeBinder {
        var reassigned = std.ArrayList(checked.PatternBinderId).empty;
        defer reassigned.deinit(self.allocator);
        try self.collectReassignedBindersInExpr(expr_id, &reassigned);

        var merge_binders = std.ArrayList(MergeBinder).empty;
        errdefer merge_binders.deinit(self.allocator);
        for (reassigned.items) |binder| {
            const before = self.binders.get(binder) orelse continue;
            try merge_binders.append(self.allocator, .{
                .binder = binder,
                .before = before,
                .ty = self.localTypeCell(before),
            });
        }
        return try merge_binders.toOwnedSlice(self.allocator);
    }

    fn stateResultTypeCell(
        self: *BodyContext,
        merge_binders: []const MergeBinder,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftTypeCell {
        const nodes = try self.graph.arena().alloc(NodeId, merge_binders.len + 1);
        for (merge_binders, 0..) |merge, index| {
            nodes[index] = try merge.ty.toGraphNode(self.graph);
        }
        nodes[merge_binders.len] = try result_cell.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn unwrapStateResultAtTypeCells(
        self: *BodyContext,
        state_expr: DraftExprId,
        state_cell: DraftTypeCell,
        result_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftExprId {
        const pattern_items = try self.allocator.alloc(DraftPatId, merge_binders.len + 1);
        defer self.allocator.free(pattern_items);
        for (merge_binders, 0..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
        }

        const result_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), result_cell, null);
        pattern_items[merge_binders.len] = try self.addPatWithTypeCell(result_cell, .{ .bind = result_local });
        const bind_pat = try self.addPatWithTypeCell(state_cell, .{ .tuple = try self.addPatSpan(pattern_items) });
        const rest = try self.addExprWithTypeCell(result_cell, .{ .local = result_local });

        return try self.addExprWithTypeCell(result_cell, .{ .let_ = .{
            .bind = bind_pat,
            .value = state_expr,
            .rest = rest,
        } });
    }

    fn stateOnlyTypeCell(
        self: *BodyContext,
        merge_binders: []const MergeBinder,
    ) Allocator.Error!DraftTypeCell {
        if (merge_binders.len == 0) return .{ .sealed = try self.unitType() };
        if (merge_binders.len == 1) return merge_binders[0].ty;
        const nodes = try self.graph.arena().alloc(NodeId, merge_binders.len);
        for (merge_binders, 0..) |merge, index| nodes[index] = try merge.ty.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn lowerIfAtTypeCells(
        self: *BodyContext,
        if_: anytype,
        result_cell: DraftTypeCell,
        branch_cell: DraftTypeCell,
        merge_binders: []const MergeBinder,
        comptime_site: ?DraftComptimeSiteId,
        value_selection: ?*ControlFlowResultSelection,
    ) Allocator.Error!BodyExprData {
        // Conditions do not bind names visible in branch bodies, so all result
        // producers can contribute their representation evidence up front.
        // Branch emission below then consumes one settled request.
        if (value_selection) |selection| {
            for (if_.branches) |branch| {
                try self.prepareControlFlowResultSelection(selection, branch.body);
            }
            try self.prepareControlFlowResultSelection(selection, if_.final_else);
        }

        const branches = try self.allocator.alloc(DraftIfBranch, if_.branches.len);
        defer self.allocator.free(branches);
        for (if_.branches, 0..) |branch, index| {
            const cond = try self.lowerExpr(branch.cond);
            var branch_ctx = try self.childContext(self.current_fn_key);
            defer branch_ctx.deinit();
            const requested_result_cell = if (value_selection) |selection| selection.selected else result_cell;
            const requested_branch_cell = if (value_selection != null) requested_result_cell else branch_cell;
            branches[index] = .{
                .cond = cond,
                .body = try branch_ctx.wrapComptimeBranch(
                    comptime_site,
                    index,
                    try branch_ctx.lowerIfBranchBodyAtTypeCells(
                        branch.body,
                        requested_result_cell,
                        requested_branch_cell,
                        merge_binders,
                    ),
                ),
            };
            if (value_selection) |selection| {
                try self.includeControlFlowResult(selection, branches[index].body);
            }
        }
        var else_ctx = try self.childContext(self.current_fn_key);
        defer else_ctx.deinit();
        const requested_result_cell = if (value_selection) |selection| selection.selected else result_cell;
        const requested_branch_cell = if (value_selection != null) requested_result_cell else branch_cell;
        const final_else = try else_ctx.wrapComptimeBranch(
            comptime_site,
            if_.branches.len,
            try else_ctx.lowerIfBranchBodyAtTypeCells(
                if_.final_else,
                requested_result_cell,
                requested_branch_cell,
                merge_binders,
            ),
        );
        if (value_selection) |selection| {
            try self.includeControlFlowResult(selection, final_else);
        }
        return .{ .if_ = .{
            .branches = try self.addIfBranchSpan(branches),
