        };
        return try self.addExprWithTypeCell(value_cell, .{ .block = .{
            .statements = try self.addStmtSpan(stmts.items[0..stmts.len]),
            .final_expr = final_expr,
        } });
    }

    const StatementTermination = union(enum) {
        none,
        checked_control_transfer,
        uninhabited: DraftExprId,
    };

    const LoweredStatements = struct {
        items: []DraftStmtId,
        len: usize,
        termination: StatementTermination,

        fn append(self: *LoweredStatements, allocator: Allocator, stmt: DraftStmtId) Allocator.Error!void {
            if (self.len == self.items.len) {
                const grown = try allocator.realloc(self.items, self.items.len + 1);
                self.items = grown;
            }
            self.items[self.len] = stmt;
            self.len += 1;
        }
    };

    fn lowerBlockStatements(self: *BodyContext, checked_statements: []const checked.CheckedStatementId) Allocator.Error!LoweredStatements {
        const items = try self.allocator.alloc(DraftStmtId, checked_statements.len);
        var lowered = LoweredStatements{
            .items = items,
            .len = 0,
            .termination = .none,
        };
        for (checked_statements) |statement| {
            try self.registerLocalAssociatedProcedures(statement);
            // Checking records divergence per statement, and marks a block
            // divergent when any statement in it diverges. That output
            // decides whether callers demand the block's own type from its
            // final expression or the effect type from a value that never
            // materializes, so it outranks every statement-local judgement
            // here: a divergent statement transfers control, which makes it
            // observable however little else the statement does, and leaves
            // the rest of the block unreachable.
            const statement_diverges = self.checkedStatementDivergesInLoweredRuntime(statement);
            if (!statement_diverges and !self.checkedStatementHasRuntimeEffect(statement)) continue;
            if (!statement_diverges) {
                if (try self.lowerUninhabitedStatementScrutinee(statement)) |scrutinee| {
                    lowered.termination = .{ .uninhabited = scrutinee };
                    break;
                }
            }
            var termination: StatementTermination = if (statement_diverges)
                .checked_control_transfer
            else
                .none;
            const statement_start = lowered.len;
            if (!try self.appendExpandedPatternStatement(statement, &lowered)) {
                const statement_result = try self.lowerStatement(statement, statement_diverges);
                if (statement_result.stmt) |stmt| try lowered.append(self.allocator, stmt);
                termination = statement_result.termination;
            }
            {
                var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
                defer timing_scope.end();
                if (try self.anyStmtSpanImpossibilityProof(lowered.items[statement_start..lowered.len])) |proof| {
                    self.runtime_demand_guard_frames = try self.withStatementSuccessRuntimeDemandGuardFrame(statement, proof);
                }
            }
            switch (termination) {
                .none => {},
                .checked_control_transfer, .uninhabited => {
                    lowered.termination = termination;
                    break;
                },
            }
        }
        return lowered;
    }

    fn lowerUninhabitedStatementScrutinee(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
    ) Allocator.Error!?DraftExprId {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        const statement = self.view.bodies.statement(statement_id);
        const expr_id = switch (statement.data) {
            .decl => |decl| if (self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return null else decl.expr,
            .var_ => |decl| decl.expr,
            .reassign => |decl| decl.expr,
            .expr => |expr| expr,
            .dbg => |expr| expr,
            .expect => |expr| if (self.builder.inline_expects == .run) expr else return null,
            .pending, .var_uninitialized, .crash, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .import_, .alias_decl, .where_alias_decl, .nominal_decl, .type_anno, .type_var_alias, .runtime_error => return null,
        };
        // An explicit checked runtime error emits a crash and has a deliberately
        // erroneous source type. Probing its type node here would demand an
        // instantiation checking intentionally did not produce.
        if (self.view.bodies.expr(expr_id).data == .runtime_error) return null;
        if (try self.graphFreeResultTypeForExpr(expr_id)) |ty| {
            if (!try self.typeIsProvenUninhabited(ty)) return null;
            return try self.lowerUninhabitedScrutineeAtTypeCell(expr_id, .{ .sealed = ty });
        }
        const node = try self.lowerExprTypeNode(expr_id);
        if (!try self.nodeIsProvenUninhabited(node)) return null;
        return try self.lowerUninhabitedScrutineeAtTypeCell(expr_id, DraftTypeCell.fromGraphNode(node));
    }

    fn statementTerminationIsNone(termination: StatementTermination) bool {
        return switch (termination) {
            .none => true,
            .checked_control_transfer, .uninhabited => false,
        };
    }

    fn appendExpandedPatternStatement(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        lowered: *LoweredStatements,
    ) Allocator.Error!bool {
        const statement = self.view.bodies.statement(statement_id);
        const saved_loc = self.builder.program.current_loc;
        defer self.builder.program.current_loc = saved_loc;
        const saved_region = self.builder.program.current_region;
        defer self.builder.program.current_region = saved_region;
        self.builder.program.current_loc = try self.sourceLocFor(statement.source_region);
        self.builder.program.current_region = statement.source_region;
        const pattern, const expr = switch (statement.data) {
            .decl => |decl| blk: {
                if (self.statementDeclIsLocalProc(decl.pattern, decl.expr)) return false;
                break :blk .{ decl.pattern, decl.expr };
            },
            .var_ => |decl| .{ decl.pattern, decl.expr },
            .reassign => |decl| .{ decl.pattern, decl.expr },
            .pending, .var_uninitialized, .crash, .dbg, .expr, .expect, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .import_, .alias_decl, .where_alias_decl, .nominal_decl, .type_anno, .type_var_alias, .runtime_error => return false,
        };

        const pattern_data = self.view.bodies.pattern(pattern).data;
        if (try self.appendStatefulControlPatternStatement(
            pattern,
            expr,
            statement.source_region,
            lowered,
        )) return true;

        const destructs = switch (pattern_data) {
            .record_destructure => |destructs| destructs,
            .pending, .assign, .as, .applied_tag, .nominal, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => return false,
        };
        // Expand into per-field `let` STATEMENTS both for an explicit rest
        // binder and for any OPTIONAL destructured field: statement-level
        // lets keep the binders bound for the rest of the block, whereas the
        // materialized statement-EXPRESSION route scopes its internal binds
        // to that expression (the lift capture analysis is lexical), which
        // would leave later statements reading free locals.
        if (!self.recordDestructsNeedExplicitRest(destructs) and
            !try self.recordDestructsHaveOptionalField(self.view.bodies.pattern(pattern).ty, destructs)) return false;

        const value_node = try self.lowerExprTypeNode(expr);
        const value_cell = DraftTypeCell.fromGraphNode(value_node);
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, value_cell);
        const value = try self.lowerExprAtTypeCell(expr, value_cell);
        const source_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
        try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
            .pat = try self.addPatWithTypeCell(value_cell, .{ .bind = source_local }),
            .value = value,
        } }));

        const source_expr = try self.addExprWithTypeCell(value_cell, .{ .local = source_local });
        const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and self.patternCanMiss(pattern))
            try self.addComptimeSite(.destructure, statement.source_region, self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern), &.{})
        else
            null;
        try self.appendRecordRestPatternStatements(
            source_expr,
            value_node,
            self.view.bodies.pattern(pattern).ty,
            destructs,
            lowered,
            comptime_site,
        );
        return true;
    }

    /// A statement-position `if`/`match` can both produce the statement value
    /// and reassign surrounding binders. Keep that nested state tuple intact
    /// until the outer statement destructures it. The reassigned locals and
    /// the result local are then bound by an ordinary block statement, so they
    /// remain in scope for every later statement and loop back edge.
    fn appendStatefulControlPatternStatement(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
        source_region: base.Region,
        lowered: *LoweredStatements,
    ) Allocator.Error!bool {
        const checked_expr = self.view.bodies.expr(expr_id);
        switch (checked_expr.data) {
            .if_, .match_ => {},
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return false,
        }

        const merge_binders = try self.stateMergeBinders(expr_id);
        defer self.allocator.free(merge_binders);
        if (merge_binders.len == 0) return false;

        const value_cell = DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(expr_id));
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, value_cell);
        const state_cell = try self.stateResultTypeCell(merge_binders, value_cell);
        const state_value = switch (checked_expr.data) {
            .if_ => |if_| try self.addExprWithTypeCell(
                state_cell,
                try self.lowerIfAtTypeCells(
                    if_,
                    value_cell,
                    state_cell,
                    merge_binders,
                    try self.ifComptimeSite(expr_id, if_),
                    null,
                ),
            ),
            .match_ => |match| try self.lowerMatchExprWithOutput(
                match,
                .{ .state_result = .{
                    .result_cell = value_cell,
                    .state_cell = state_cell,
                    .merge_binders = merge_binders,
                } },
                try self.matchComptimeSite(expr_id, match),
            ),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => unreachable,
        };

        const state_pattern_items = try self.allocator.alloc(DraftPatId, merge_binders.len + 1);
        defer self.allocator.free(state_pattern_items);
        for (merge_binders, 0..) |merge, index| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), merge.ty, merge.binder);
            try self.bindLocalName(local, merge.binder);
            try self.binders.put(merge.binder, local);
            state_pattern_items[index] = try self.addPatWithTypeCell(merge.ty, .{ .bind = local });
        }
        const result_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), value_cell, null);
        state_pattern_items[merge_binders.len] = try self.addPatWithTypeCell(value_cell, .{ .bind = result_local });
        try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
            .pat = try self.addPatWithTypeCell(
                state_cell,
                .{ .tuple = try self.addPatSpan(state_pattern_items) },
            ),
            .value = state_value,
        } }));

        const result = try self.addExprWithTypeCell(value_cell, .{ .local = result_local });
        const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and self.patternCanMiss(pattern))
            try self.addComptimeSite(
                .destructure,
                source_region,
                self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern),
                &.{},
            )
        else
            null;
        if (!try self.patternNeedsExplicitBinding(pattern)) {
            const result_pattern = if (self.patternIsShapeFree(pattern))
                try self.lowerShapeFreePatternAtCell(pattern, value_cell)
            else
                try self.lowerPatternAtNode(pattern, try value_cell.toGraphNode(self.graph));
            try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                .pat = result_pattern,
                .value = result,
                .comptime_site = comptime_site,
            } }));
            return true;
        }

        const unit_ty = try self.unitType();
        var unit = try self.addExpr(.{ .ty = unit_ty, .data = .unit });
        unit = try self.wrapComptimeBranch(comptime_site, 0, unit);
        const miss = if (comptime_site) |site|
            try self.comptimeExhaustivenessFailedExpr(unit_ty, site)
        else
            try self.runtimeCrashExpr(unit_ty, "pattern match failed");
        try lowered.append(self.allocator, try self.addStmt(.{ .expr = try self.lowerMaterializedPatternValueThen(
            pattern,
            result,
            value_cell,
            .{ .sealed = unit_ty },
            .{ .expr = unit },
            miss,
            null,
        ) }));
        return true;
    }

    fn appendRecordRestPatternStatements(
        self: *BodyContext,
        value: DraftExprId,
        value_node: NodeId,
        record_checked_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
        lowered: *LoweredStatements,
        comptime_site: ?DraftComptimeSiteId,
    ) Allocator.Error!void {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required, .sub_pattern => |child| {
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    const field_node = try self.graph.recordFieldNode(value_node, name);
                    const field_cell = DraftTypeCell.fromGraphNode(field_node);
                    const field_value = try self.addExprWithTypeCell(field_cell, .{
                        .field_access = .{
                            .receiver = value,
                            .segments = try self.draft.addFieldAccessSegmentSpan(&.{.{ .field = name }}),
                        },
                    });
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                        // A destructured OPTIONAL field binds its slot
                        // materialized as `Try(v, [MissingField])` (design.md
                        // "Field Kinds").
                        const try_node = try self.instNode(self.view.bodies.pattern(child).ty);
                        const try_value = try self.optionalDestructTryExprAtNode(field_value, field_node, try_node);
                        try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                            .pat = try self.lowerPatternAtNode(child, try_node),
                            .value = try_value,
                            .comptime_site = if (self.patternCanMiss(child)) comptime_site else null,
                        } }));
                        continue;
                    }
                    try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                        .pat = try self.lowerPatternAtNode(child, field_node),
                        .value = field_value,
                        .comptime_site = if (self.patternCanMiss(child)) comptime_site else null,
                    } }));
                },
                .rest => |child| {
                    if (self.patternIsIgnored(child)) continue;
                    const rest_node = try self.recordRestNodeForPattern(value_node, destructs, child);
                    const rest_cell = DraftTypeCell.fromGraphNode(rest_node);
                    const rest_value = try self.lowerRecordRestValueWithTypeCell(
                        value,
                        value_node,
                        rest_cell,
                        rest_node,
                    );
                    try lowered.append(self.allocator, try self.addStmt(.{ .let_ = .{
                        .pat = try self.lowerPatternAtNode(child, rest_node),
                        .value = rest_value,
                        .comptime_site = if (self.patternCanMiss(child)) comptime_site else null,
                    } }));
                },
            }
        }
    }

    fn checkedStatementHasRuntimeEffect(self: *BodyContext, statement_id: checked.CheckedStatementId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        const raw = @intFromEnum(statement_id);
        if (raw >= self.view.bodies.statementCount()) {
            Common.invariant("checked runtime statement filter referenced a missing statement");
        }
        return switch (self.view.bodies.statement(@enumFromInt(raw)).data) {
            .decl => |decl| switch (self.view.bodies.expr(decl.expr).data) {
                // A dangling annotation carries diagnostics and checked type
                // information but has no runtime value to bind.
                .anno_only => false,
                .pending => Common.invariant("pending checked declaration reached Monotype runtime statement filter"),
                .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .break_, .return_, .for_, .hosted_lambda, .run_low_level => self.view.hoisted_constants.lookupByPattern(decl.pattern) == null,
            },
            .var_,
            .var_uninitialized,
            .reassign,
            .crash,
            .dbg,
            .expr,
            .for_,
            .while_,
            .infinite_loop,
            .breakable_loop,
            .break_,
            .return_,
            .runtime_error,
            => true,
            .expect => self.builder.inline_expects == .run,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            => false,
            .pending => Common.invariant("pending checked statement reached Monotype runtime statement filter"),
        };
    }

    fn lowerDivergentExprAtType(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        const checked_expr = self.view.bodies.expr(checked_expr_id);
        switch (checked_expr.data) {
            .match_ => |match| {
                if (self.checkedExprDivergesInLoweredRuntime(match.cond)) {
                    return try self.addExpr(.{
                        .ty = ty,
                        .data = try self.lowerDivergentExprForEffectDataAtType(match.cond, ty),
                    });
                }
                return try self.lowerMatchExpr(checked_expr_id, match, ty);
            },
            .if_ => |if_| {
                if (if_.branches.len > 0 and self.checkedExprDivergesInLoweredRuntime(if_.branches[0].cond)) {
                    return try self.addExpr(.{
                        .ty = ty,
                        .data = try self.lowerDivergentExprForEffectDataAtType(if_.branches[0].cond, ty),
                    });
                }
                return try self.lowerIfExpr(checked_expr_id, if_, ty);
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }

        return try self.addExpr(.{
            .ty = ty,
            .data = try self.lowerDivergentExprDataAtType(checked_expr_id, ty),
        });
    }

    fn lowerDivergentExprAtTypeCell(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const checked_expr = self.view.bodies.expr(checked_expr_id);
        switch (checked_expr.data) {
            .match_ => |match| return try self.lowerMatchExprAtTypeCell(checked_expr_id, match, result_cell),
            .if_ => |if_| return try self.lowerIfExprAtTypeCell(checked_expr_id, if_, result_cell),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }

        const effect_ty = try self.unitType();
        const effect = try self.lowerDivergentExprAtType(checked_expr_id, effect_ty);
        const stmt = try self.addStmt(.{ .expr = effect });
        return try self.addExprWithTypeCell(result_cell, .{ .block = .{
            .statements = try self.addStmtSpan(&.{stmt}),
            .final_expr = try self.addExprWithTypeCell(result_cell, .@"unreachable"),
        } });
    }

    fn exprIdAsDivergentData(self: *BodyContext, expr: DraftExprId) Allocator.Error!BodyExprData {
        return .{ .block = .{
            .statements = try self.addStmtSpan(&[_]DraftStmtId{}),
            .final_expr = expr,
        } };
    }

    fn lowerDivergentExprForEffectDataAtType(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        // A divergent expression never returns a value, so its checked result
        // variable can legitimately remain unconstrained; the continuation's
        // explicit type stands in for a result that cannot exist. An explicit
        // checked runtime error lowers its crash path at unit because its
        // deliberately erroneous source type has no monotype.
        const effect_ty = if (self.view.bodies.expr(checked_expr_id).data == .runtime_error)
            try self.unitType()
        else
            ty;
        const effect = try self.lowerDivergentExprAtType(checked_expr_id, effect_ty);
        const stmt = try self.addStmt(.{ .expr = effect });
        return .{ .block = .{
            .statements = try self.addStmtSpan(&[_]DraftStmtId{stmt}),
            .final_expr = try self.unreachableAfterTerminatingStatementExpr(ty),
        } };
    }

    fn lowerFirstDivergentExprForEffectDataAtType(
        self: *BodyContext,
        items: []const checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        for (items) |item| {
            if (self.checkedExprDivergesInLoweredRuntime(item)) {
                return try self.lowerDivergentExprForEffectDataAtType(item, ty);
            }
        }
        Common.invariant("checked expression was marked divergent but no divergent child was found");
    }

    fn lowerDivergentRecordForEffectDataAtType(
        self: *BodyContext,
        record: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        if (record.ext) |ext| {
            if (self.checkedExprDivergesInLoweredRuntime(ext)) {
                return try self.lowerDivergentExprForEffectDataAtType(ext, ty);
            }
        }
        for (record.fields) |field| {
            if (self.checkedExprDivergesInLoweredRuntime(field.value)) {
                return try self.lowerDivergentExprForEffectDataAtType(field.value, ty);
            }
        }
        Common.invariant("checked record expression was marked divergent but no divergent child was found");
    }

    fn lowerDivergentInterpolationForEffectDataAtType(
        self: *BodyContext,
        interpolation: checked.CheckedInterpolation,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        if (self.checkedExprDivergesInLoweredRuntime(interpolation.first)) {
            return try self.lowerDivergentExprForEffectDataAtType(interpolation.first, ty);
        }
        for (interpolation.parts) |part| {
            if (self.checkedExprDivergesInLoweredRuntime(part.value)) {
                return try self.lowerDivergentExprForEffectDataAtType(part.value, ty);
            }
            if (self.checkedExprDivergesInLoweredRuntime(part.following_segment)) {
                return try self.lowerDivergentExprForEffectDataAtType(part.following_segment, ty);
            }
        }
        Common.invariant("checked interpolation was marked divergent but no divergent child was found");
    }

    fn lowerDivergentDispatchForEffectDataAtType(
        self: *BodyContext,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        const plan_id = maybe_plan orelse Common.invariant("divergent checked dispatch expression did not contain its checked plan");
        const plan = self.view.static_dispatch_plans.plans[@intFromEnum(plan_id)];
        switch (self.dispatchRuntimePlan(plan)) {
            .callable => {},
            .crash => |reason| return .{ .crash = try self.addStringLiteral(dispatchCrashMessage(reason)) },
        }
        for (plan.argsSlice(self.view.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| if (self.checkedExprDivergesInLoweredRuntime(expr)) {
                return try self.lowerDivergentExprForEffectDataAtType(expr, ty);
            },
            .generated_interpolation_iter => |expr| {
                const interpolation = switch (self.view.bodies.expr(expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => Common.invariant("divergent interpolation iterator referenced a non-interpolation expression"),
                };
                return try self.lowerDivergentInterpolationForEffectDataAtType(interpolation, ty);
            },
            .generated_numeral, .generated_quote => {},
        };
        Common.invariant("checked dispatch expression was marked divergent but no divergent operand was found");
    }

    fn lowerDivergentExprDataAtType(
        self: *BodyContext,
        checked_expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyExprData {
        const checked_expr = self.view.bodies.expr(checked_expr_id);
        return switch (checked_expr.data) {
            .crash => |msg| .{ .crash = try self.lowerStringLiteral(msg) },
            .runtime_error => .{ .crash = try self.addStringLiteral("runtime error") },
            .ellipsis => .{ .crash = try self.addStringLiteral("not implemented") },
            .break_ => try self.breakCurrentLoopExprData(),
            .return_ => |ret| .{ .return_ = try self.lowerReturn(ret) },
            .expect_err => |expect_err| .{ .expect_err = .{
                .msg = try self.lowerExpectErrMessage(expect_err.expr, expect_err.snippet),
                .region = checked_expr.source_region,
            } },
            .str => |items| try self.lowerFirstDivergentExprForEffectDataAtType(items, ty),
            .list => |items| try self.lowerFirstDivergentExprForEffectDataAtType(items, ty),
            .tuple => |items| try self.lowerFirstDivergentExprForEffectDataAtType(items, ty),
            .block => |block| try self.lowerBlock(block, ty),
            .match_ => |match| try self.exprIdAsDivergentData(try self.lowerMatchExpr(checked_expr_id, match, ty)),
            .if_ => |if_| try self.exprIdAsDivergentData(try self.lowerIfExpr(checked_expr_id, if_, ty)),
            .call => |call| blk: {
                if (self.checkedExprDivergesInLoweredRuntime(call.func)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(call.func, ty);
                }
                break :blk try self.lowerFirstDivergentExprForEffectDataAtType(call.args, ty);
            },
            .record => |record| try self.lowerDivergentRecordForEffectDataAtType(record, ty),
            .tag => |tag| try self.lowerFirstDivergentExprForEffectDataAtType(tag.args, ty),
            .nominal => |nominal| try self.lowerDivergentExprForEffectDataAtType(nominal.backing_expr, ty),
            .binop => |binop| blk: {
                if (self.checkedExprDivergesInLoweredRuntime(binop.lhs)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(binop.lhs, ty);
                }
                if (self.checkedExprDivergesInLoweredRuntime(binop.rhs)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(binop.rhs, ty);
                }
                Common.invariant("checked binary expression was marked divergent but no divergent child was found");
            },
            .unary_minus,
            .unary_not,
            .dbg,
            => |child| try self.lowerDivergentExprForEffectDataAtType(child, ty),
            .expect => |child| if (self.builder.inline_expects == .run)
                try self.lowerDivergentExprForEffectDataAtType(child, ty)
            else
                Common.invariant("omitted checked expect reached divergent runtime lowering"),
            .field_access => |field| try self.lowerDivergentExprForEffectDataAtType(field.receiver, ty),
            .structural_eq => |eq| blk: {
                if (self.checkedExprDivergesInLoweredRuntime(eq.lhs)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(eq.lhs, ty);
                }
                if (self.checkedExprDivergesInLoweredRuntime(eq.rhs)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(eq.rhs, ty);
                }
                Common.invariant("checked structural equality was marked divergent but no divergent child was found");
            },
            .structural_hash => |hash| blk: {
                if (self.checkedExprDivergesInLoweredRuntime(hash.value)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(hash.value, ty);
                }
                if (self.checkedExprDivergesInLoweredRuntime(hash.hasher)) {
                    break :blk try self.lowerDivergentExprForEffectDataAtType(hash.hasher, ty);
                }
                Common.invariant("checked structural hash was marked divergent but no divergent child was found");
            },
            .tuple_access => |access| try self.lowerDivergentExprForEffectDataAtType(access.tuple, ty),
            .for_ => |for_| try self.lowerDivergentExprForEffectDataAtType(for_.expr, ty),
            .run_low_level => |low_level| blk: {
                for (low_level.args) |arg| {
                    if (self.checkedExprDivergesInLoweredRuntime(arg)) {
                        break :blk try self.lowerDivergentExprForEffectDataAtType(arg, ty);
                    }
                }
                if (low_level.op != .crash) {
                    Common.invariant("checked low-level expression was marked divergent but no divergent argument was found");
                }
                break :blk .{ .low_level = .{
                    .op = low_level.op,
                    .args = try self.lowerExprSpan(low_level.args),
                } };
            },
            .dispatch_call => |plan| try self.lowerDivergentDispatchForEffectDataAtType(plan, ty),
            .interpolation => |interpolation| try self.lowerDivergentInterpolationForEffectDataAtType(interpolation, ty),
            .method_eq => |plan| try self.lowerDivergentDispatchForEffectDataAtType(plan, ty),
            .type_dispatch_call => |plan| try self.lowerDivergentDispatchForEffectDataAtType(plan, ty),
            .numeral => |numeral| try self.lowerDivergentDispatchForEffectDataAtType(numeral.plan, ty),
            .str_from_quote => |quote| try self.lowerDivergentDispatchForEffectDataAtType(quote.plan, ty),
            .pending,
            .str_segment,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .closure,
            .lambda,
            .anno_only,
            .hosted_lambda,
            => Common.invariant("non-divergent checked expression reached divergent lowering"),
        };
    }

    fn unreachableAfterTerminatingStatementExpr(self: *BodyContext, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.addExpr(.{ .ty = ty, .data = .@"unreachable" });
    }

    fn checkedInlineExpectMode(self: *const BodyContext) checked.InlineExpectMode {
        return switch (self.builder.inline_expects) {
            .run => .run,
            .omit => .omit,
        };
    }

    fn checkedStatementDivergesInLoweredRuntime(self: *BodyContext, statement_id: checked.CheckedStatementId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        if (self.specializationDispatchDivergence()) |divergence| {
            const raw = @intFromEnum(statement_id);
            if (raw >= divergence.statements.len) Common.invariant("specialization divergence referenced a missing checked statement");
            return switch (self.checkedInlineExpectMode()) {
                .run => divergence.statements[raw],
                .omit => divergence.statements_without_inline_expects[raw],
            };
        }
        return self.view.bodies.statementDiverges(statement_id, self.checkedInlineExpectMode());
    }

    fn checkedExprDivergesInLoweredRuntime(self: *BodyContext, expr_id: checked.CheckedExprId) bool {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .reachability);
        defer timing_scope.end();
        if (self.specializationDispatchDivergence()) |divergence| {
            const raw = @intFromEnum(expr_id);
            if (raw >= divergence.exprs.len) Common.invariant("specialization divergence referenced a missing checked expression");
            return switch (self.checkedInlineExpectMode()) {
                .run => divergence.exprs[raw],
                .omit => divergence.exprs_without_inline_expects[raw],
            };
        }
        return self.view.bodies.exprDiverges(expr_id, self.checkedInlineExpectMode());
    }

    const LoopCarry = struct {
        binder: checked.PatternBinderId,
        initial_local: DraftLocalId,
        param_local: DraftLocalId,
        ty: DraftTypeCell,
    };

    const LoopContext = struct {
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    };

    fn lowerIteratorFor(
        self: *BodyContext,
        for_: anytype,
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!BodyExprData {
        const plan_id = for_.plan orelse Common.invariant("checked iterator for reached Monotype without an iterator dispatch plan");
        const plan = self.view.static_dispatch_plans.iterator_for_plans[@intFromEnum(plan_id)];

        if (self.dispatchCrashReason(plan.iter.resolution) orelse self.dispatchCrashReason(plan.next.resolution)) |reason| {
            const message = dispatchCrashMessage(reason);
            return .{ .crash = try self.addStringLiteral(message) };
        }

        const initial_iterator = try self.lowerIteratorDispatch(plan.iter, null, null);
        const iterator_cell = self.exprTypeCell(initial_iterator);
        try self.constrainCheckedInterfaceToCell(plan.iterator_ty, iterator_cell);
        const step = try self.iteratorStepShape(plan, iterator_cell);
        try self.constrainCheckedInterfaceToCell(plan.iterator_ty, DraftTypeCell.fromGraphNode(step.one_rest.node));
        try self.constrainCheckedInterfaceToCell(plan.iterator_ty, DraftTypeCell.fromGraphNode(step.skip_rest.node));
        try self.constrainCheckedInterfaceToCell(plan.item_ty, DraftTypeCell.fromGraphNode(step.one_item.node));
        const iterator_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), iterator_cell, null);
        const iterator_param = DraftTypedLocal{ .local = iterator_local, .ty = iterator_cell };

        var saved = std.ArrayList(BinderRestore).empty;
        defer saved.deinit(self.allocator);
        for (carries) |carry| {
            try self.saveBinder(carry.binder, &saved);
            try self.binders.put(carry.binder, carry.param_local);
        }
        defer self.restoreBinders(saved.items);

        try self.pushLoopContext(result_cell, carries);
        defer self.popLoopContext();

        const step_expr = try self.lowerIteratorDispatch(plan.next, iterator_param, DraftTypeCell.fromGraphNode(step.step_node));
        try self.constrainCheckedInterfaceToCell(plan.step_ty, self.exprTypeCell(step_expr));
        const done_body = if (carries.len == 0)
            try self.addExprWithTypeCell(result_cell, .{ .break_ = null })
        else
            try self.addExprWithTypeCell(result_cell, .{ .break_ = try self.loopStateExpr(result_cell, carries) });

        var branches: [3]DraftBranch = undefined;
        branches[0] = .{
            .pat = try self.iteratorDonePattern(step),
            .body = done_body,
        };
        branches[1] = if (try self.nodeIsProvenUninhabited(step.one_item.node))
            try self.uninhabitedIteratorOneBranch(step, done_body)
        else
            try self.iteratorOneBranch(for_, result_cell, step, iterator_cell, carries);
        branches[2] = try self.iteratorSkipBranch(result_cell, step, iterator_cell, carries);

        const match_expr = try self.addExprWithTypeCell(result_cell, .{ .match_ = .{
            .scrutinee = step_expr,
            .branches = try self.addBranchSpan(&branches),
        } });

        const params = try self.allocator.alloc(DraftTypedLocal, 1 + carries.len);
        defer self.allocator.free(params);
        params[0] = iterator_param;
        for (carries, 0..) |carry, i| params[i + 1] = .{ .local = carry.param_local, .ty = carry.ty };

        const initial_values = try self.allocator.alloc(DraftExprId, 1 + carries.len);
        defer self.allocator.free(initial_values);
        initial_values[0] = initial_iterator;
        for (carries, 0..) |carry, i| {
            initial_values[i + 1] = try self.addExprWithTypeCell(carry.ty, .{ .local = carry.initial_local });
        }

        return .{ .loop_ = .{
            .params = try self.draft.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = match_expr,
        } };
    }

    const WhileCondition = enum {
        checked,
        always_true,
    };

    fn lowerWhile(
        self: *BodyContext,
        while_: anytype,
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
        condition: WhileCondition,
    ) Allocator.Error!BodyExprData {
        var saved = std.ArrayList(BinderRestore).empty;
        defer saved.deinit(self.allocator);
        for (carries) |carry| {
            try self.saveBinder(carry.binder, &saved);
            try self.binders.put(carry.binder, carry.param_local);
        }
        defer self.restoreBinders(saved.items);

        try self.pushLoopContext(result_cell, carries);
        defer self.popLoopContext();

        // Checked entry edges observe the loop parameters at the start of an
        // iteration. Lower both the condition and its false-edge result before
        // the body, whose branch merges replace binder mappings with post-body
        // locals used only by the continuation edge.
        const checked_entry = switch (condition) {
            .checked => .{
                .cond = try self.lowerExpr(while_.cond),
                .break_body = try self.breakCurrentLoopExpr(),
            },
            .always_true => null,
        };
        const continue_body = try self.lowerWhileBodyThenContinue(while_.body, result_cell, carries);
        const body = switch (condition) {
            .always_true => continue_body,
            .checked => blk: {
                const entry = checked_entry.?;
                const branches = [_]DraftIfBranch{.{ .cond = entry.cond, .body = continue_body }};
                break :blk try self.addExprWithTypeCell(result_cell, .{ .if_ = .{
                    .branches = try self.addIfBranchSpan(&branches),
                    .final_else = entry.break_body,
                } });
            },
        };

        const params = try self.allocator.alloc(DraftTypedLocal, carries.len);
        defer self.allocator.free(params);
        for (carries, 0..) |carry, i| params[i] = .{ .local = carry.param_local, .ty = carry.ty };

        const initial_values = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(initial_values);
        for (carries, 0..) |carry, i| {
            initial_values[i] = try self.addExprWithTypeCell(carry.ty, .{ .local = carry.initial_local });
        }

        return .{ .loop_ = .{
            .params = try self.draft.addTypedLocalSpan(params),
            .initial_values = try self.addExprSpan(initial_values),
            .body = body,
        } };
    }

    fn lowerIteratorDispatch(
        self: *BodyContext,
        plan: static_dispatch.IteratorDispatchCall,
        loop_iterator: ?DraftTypedLocal,
        expected_ret_ty: ?DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        const plan_args = plan.argsSlice(self.view.static_dispatch_plans);
        if (plan.dispatcher_arg_index >= plan_args.len) Common.invariant("iterator dispatch plan dispatcher argument index was outside the argument span");

        const lookup = self.iteratorMethodLookup(plan);
        if (try self.lowerGeneratedIteratorDispatch(lookup, plan, plan_args, loop_iterator, expected_ret_ty)) |generated| {
            return generated;
        }

        var call_ctx = try BodyContext.initWithMethodScope(self.allocator, self.builder, self.view, self.method_scope, self.owner_template, self.graph, self.draft);
        call_ctx.evidence = self.evidence;
        defer call_ctx.deinit();
        call_ctx.owner_context_fn_key = self.owner_context_fn_key;
        call_ctx.current_fn_key = self.current_fn_key;
        call_ctx.source_region_override = self.source_region_override;
        call_ctx.current_entry_root = self.current_entry_root;

        var callable_node = try call_ctx.instantiateIteratorPlanCallNodeFromCaller(plan.callable_ty, self, plan_args, loop_iterator, expected_ret_ty);
        const target_node = try self.methodTargetNodeFromPlan(lookup, &call_ctx, plan.callable_ty);
        try relateFunctionRequestInterface(self.graph, target_node, callable_node);
        if (try self.generatedIteratorPlanRequestNode(
            lookup,
            target_node,
            callable_node,
            plan_args,
        )) |private_node| {
            callable_node = private_node;
        }
        const plan_fn = try self.graph.functionNodes(callable_node);
        if (expected_ret_ty) |expected| {
            if (!self.graph.sameClass(plan_fn.ret, try expected.toGraphNode(self.graph))) {
                Common.invariant("checked iterator dispatch plan return type differed from iterator-for expected type");
            }
        }

        const dispatcher_node = plan_fn.args[plan.dispatcher_arg_index];
        try call_ctx.constrainCheckedInterfaceToCell(plan.dispatcher_ty, DraftTypeCell.fromGraphNode(dispatcher_node));
        const actual_dispatcher_node = try self.iteratorOperandNode(plan_args[plan.dispatcher_arg_index], loop_iterator);
        try relateRequestComponent(self.graph, dispatcher_node, actual_dispatcher_node);
        if (!self.graph.sameClass(dispatcher_node, actual_dispatcher_node)) {
            Common.invariant("iterator dispatch plan dispatcher operand differed from the checked dispatcher type");
        }
        const fn_nodes = try self.graph.functionNodes(callable_node);
        if (expected_ret_ty) |expected| {
            if (!self.graph.sameClass(fn_nodes.ret, try expected.toGraphNode(self.graph))) {
                Common.invariant("checked iterator dispatch target return type differed from iterator-for expected type");
            }
        }
        const args = try self.allocator.alloc(DraftExprId, plan_args.len);
        defer self.allocator.free(args);
        for (plan_args, 0..) |operand, i| {
            args[i] = try self.lowerIteratorOperandAtNode(operand, loop_iterator, fn_nodes.args[i]);
        }

        return try self.addExprWithTypeCell(
            DraftTypeCell.fromGraphNode(fn_nodes.ret),
            .{ .call_proc = .{
                .callee = draftProcCalleeForSlot(try self.methodTargetCalleeAtNode(lookup, callable_node, try self.evidenceForIteratorCall(plan))),
                .args = try self.addExprSpan(args),
                .iterator_procedure = self.iteratorProcedureForMethodTarget(lookup.target),
                .captures = try self.methodTargetCaptureSpan(lookup),
            } },
        );
    }

    fn lowerGeneratedIteratorDispatch(
        self: *BodyContext,
        lookup: MethodLookup,
        plan: static_dispatch.IteratorDispatchCall,
        plan_args: []const static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
        expected_ret_ty: ?DraftTypeCell,
    ) Allocator.Error!?DraftExprId {
        const procedure = self.iteratorProcedureForMethodTarget(lookup.target) orelse return null;
        if (procedure != .iter_iter and procedure != .iter_next) return null;

        const dispatcher_node = try self.iteratorOperandNode(plan_args[plan.dispatcher_arg_index], loop_iterator);
        if (!self.isGeneratedIteratorEvidenceNode(dispatcher_node)) return null;
        try self.constrainCheckedInterfaceToCell(plan.dispatcher_ty, DraftTypeCell.fromGraphNode(dispatcher_node));

        const iterator = try self.lowerIteratorOperandAtNode(
            plan_args[plan.dispatcher_arg_index],
            loop_iterator,
            dispatcher_node,
        );
        switch (procedure) {
            .iter_iter => {
                if (expected_ret_ty) |expected| {
                    try relateRequestComponent(self.graph, dispatcher_node, try expected.toGraphNode(self.graph));
                }
                return iterator;
            },
            .iter_next => {
                const step_ret_node = try self.generatedIteratorStepReturnNode(dispatcher_node);
                if (expected_ret_ty) |expected| {
                    try relateRequestComponent(self.graph, step_ret_node, try expected.toGraphNode(self.graph));
                }
                return try self.addExprWithTypeCell(
                    DraftTypeCell.fromGraphNode(step_ret_node),
                    try self.lowerGeneratedIteratorNextData(iterator, dispatcher_node),
                );
            },
            .iter_custom, .iter_single, .list_iter, .str_iter_utf8, .iter_map, .iter_keep_if, .iter_drop_if, .iter_take_first, .iter_drop_first, .iter_concat, .iter_append, .iter_exclusive_range, .iter_inclusive_range, .numeric_range_exclusive, .numeric_range_inclusive, .iter_from_step, .range_done => unreachable,
        }
    }

    fn iteratorMethodLookup(self: *BodyContext, plan: static_dispatch.IteratorDispatchCall) MethodLookup {
        return switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| blk: {
                const node = self.view.static_dispatch_plans.evidenceNode(direct.evidence);
                var lookup = self.methodLookupForResolvedTarget(node.target);
                lookup.instantiation = switch (node.instantiation) {
                    .monomorphic => null,
                    .callable => |callable_ty| .{ .view = self.view, .callable_ty = callable_ty },
                };
                break :blk lookup;
            },
            .evidence_dependent => |constraint_ref| if (self.evidence.at(constraint_ref)) |entry| switch (entry) {
                .target => |target| .{
                    .view = target.view,
                    .target = target.target,
                    .instantiation = target.instantiation,
                    .local_proc_context = target.local_proc_context,
                },
                .structural, .unreachable_value, .checked_error => Common.invariant("iterator dispatch evidence was not a callable target"),
            } else Common.invariant("iterator method evidence was absent from its lexical chain"),
            .direct_pending => Common.invariant("unfinalized iterator direct call reached Monotype"),
            .structural, .checked_error, .@"unreachable" => Common.invariant("iterator dispatch plan resolution was not a callable target"),
        };
    }

    fn instantiateIteratorPlanCallNodeFromCaller(
        self: *BodyContext,
        source_fn_ty: checked.CheckedTypeId,
        caller: *BodyContext,
        operands: []const static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
        expected_ret_ty: ?DraftTypeCell,
    ) Allocator.Error!NodeId {
        const function = self.checkedFunctionType(source_fn_ty);
        if (function.args.len != operands.len) {
            Common.invariant("checked iterator dispatch target arity differs from its function type");
        }
        const fn_node = try self.instNode(source_fn_ty);
        const function_nodes = try self.graph.functionNodes(fn_node);
        const request_args = try self.graph.arena().alloc(NodeId, function.args.len);
        var contains_generated_private = false;
        for (function_nodes.args, operands, request_args) |formal_node, operand, *request_arg| {
            switch (operand) {
                .checked_expr => |checked_arg| {
                    const arg_ty = caller.view.bodies.expr(checked_arg).ty;
                    const public_node = try caller.instNode(arg_ty);
                    try relateRequestComponent(self.graph, formal_node, public_node);
                    if (try caller.callArgumentEvidenceNode(checked_arg, null)) |evidence_node| {
                        request_arg.* = try checkedMonoRequestNode(
                            self.graph,
                            public_node,
                            evidence_node,
                        );
                    } else {
                        request_arg.* = formal_node;
                    }
                },
                .loop_iterator_state => {
                    const iterator = loop_iterator orelse Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local");
                    request_arg.* = try checkedMonoRequestNode(
                        self.graph,
                        formal_node,
                        try iterator.ty.toGraphNode(self.graph),
                    );
                },
            }
            if (try self.graph.containsGeneratedPrivate(request_arg.*)) contains_generated_private = true;
        }
        var request_ret = function_nodes.ret;
        if (expected_ret_ty) |expected| {
            const expected_node = try expected.toGraphNode(self.graph);
            request_ret = if (try self.graph.containsGeneratedPrivate(expected_node))
                expected_node
            else
                try checkedMonoRequestNode(self.graph, function_nodes.ret, expected_node);
            if (try self.graph.containsGeneratedPrivate(request_ret)) contains_generated_private = true;
        }
        if (contains_generated_private) return try self.graphFunctionNode(request_args, request_ret);
        return fn_node;
    }

    fn iteratorOperandNode(
        self: *BodyContext,
        operand: static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
    ) Allocator.Error!NodeId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprTypeNode(expr),
            .loop_iterator_state => if (loop_iterator) |iterator|
                try iterator.ty.toGraphNode(self.graph)
            else
                Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local"),
        };
    }

    fn lowerIteratorOperandAtNode(
        self: *BodyContext,
        operand: static_dispatch.IteratorDispatchOperand,
        loop_iterator: ?DraftTypedLocal,
        node: NodeId,
    ) Allocator.Error!DraftExprId {
        return switch (operand) {
            .checked_expr => |expr| try self.lowerExprAtTypeCell(expr, DraftTypeCell.fromGraphNode(node)),
            .loop_iterator_state => blk: {
                const iterator = loop_iterator orelse Common.invariant("iterator .next dispatch reached Monotype without a loop iterator local");
                const iterator_node = try iterator.ty.toGraphNode(self.graph);
                try self.graph.unify(iterator_node, node);
                if (!self.graph.sameClass(iterator_node, node)) Common.invariant("iterator .next operand type differed from instantiated callable argument type");
                break :blk try self.addExprWithTypeCell(iterator.ty, .{ .local = iterator.local });
            },
        };
    }

    fn iteratorDonePattern(self: *BodyContext, step: IterStepShape) Allocator.Error!DraftPatId {
        return try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.builder.tagName(self.view, step.done_tag),
            .payloads = .empty(),
        } });
    }

    fn iteratorOneBranch(
        self: *BodyContext,
        for_: anytype,
        result_cell: DraftTypeCell,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftBranch {
        var saved = std.ArrayList(BinderRestore).empty;
        defer saved.deinit(self.allocator);
        try self.savePatternBinders(for_.pattern, &saved);
        for (carries) |carry| try self.saveBinder(carry.binder, &saved);
        defer self.restoreBinders(saved.items);

        const item_cell = DraftTypeCell.fromGraphNode(step.one_item.node);
        try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(for_.pattern).ty, item_cell);

        const previous_runtime_demand_guard_frames = self.runtime_demand_guard_frames;
        self.runtime_demand_guard_frames = try self.withIteratorOneRuntimeDemandGuardFrame(for_.pattern, step);
        defer self.runtime_demand_guard_frames = previous_runtime_demand_guard_frames;

        const rest_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), iterator_cell, null);
        const item_local: ?DraftLocalId = if (try self.patternNeedsExplicitBinding(for_.pattern))
            try self.addLocalWithBinderCell(self.builder.symbols.fresh(), item_cell, null)
        else
            null;
        const record_pat = try self.iteratorOnePayloadPattern(for_.pattern, step, iterator_cell, rest_local, item_local);
        const tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.builder.tagName(self.view, step.one_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{record_pat}),
        } });

        const rest_expr = try self.addExprWithTypeCell(iterator_cell, .{ .local = rest_local });
        const block = if (item_local) |local| blk: {
            const item_expr = try self.addExprWithTypeCell(item_cell, .{ .local = local });
            const miss = try self.addExprWithTypeCell(result_cell, .{ .crash = try self.addStringLiteral("pattern match failed") });
            break :blk try self.lowerMaterializedPatternThen(
                for_.pattern,
                item_expr,
                item_cell,
                result_cell,
                .{ .iterator_body = .{
                    .body = for_.body,
                    .result_cell = result_cell,
                    .rest_expr = rest_expr,
                    .carries = carries,
                } },
                miss,
            );
        } else try self.lowerIteratorBodyThenContinue(for_.body, result_cell, rest_expr, carries);

        return .{ .pat = tag_pat, .body = block };
    }

    fn uninhabitedIteratorOneBranch(
        self: *BodyContext,
        step: IterStepShape,
        body: DraftExprId,
    ) Allocator.Error!DraftBranch {
        const payload_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.one_payload_node), .wildcard);
        const tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.builder.tagName(self.view, step.one_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{payload_pat}),
        } });
        return .{ .pat = tag_pat, .body = body };
    }

    fn lowerIteratorBodyThenContinue(
        self: *BodyContext,
        body: checked.CheckedExprId,
        result_cell: DraftTypeCell,
        rest_expr: DraftExprId,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        const checked_body = self.view.bodies.expr(body);
        switch (checked_body.data) {
            .block => |block| {
                const previous_statement_success_frames = self.runtime_demand_guard_frames;
                defer self.runtime_demand_guard_frames = previous_statement_success_frames;
                var statements = try self.lowerBlockStatements(block.statements);
                defer self.allocator.free(statements.items);
                if (statementTerminationIsNone(statements.termination)) {
                    const final_result = try self.lowerDiscardedExprStatementAtTypeCell(block.final_expr);
                    if (final_result.stmt) |stmt| try statements.append(self.allocator, stmt);
                    statements.termination = final_result.termination;
                }
                return try self.addExprWithTypeCell(result_cell, .{ .block = .{
                    .statements = try self.addStmtSpan(statements.items[0..statements.len]),
                    .final_expr = switch (statements.termination) {
                        .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, result_cell),
                        .checked_control_transfer => try self.addExprWithTypeCell(result_cell, .@"unreachable"),
                        .none => try self.continueWithState(result_cell, rest_expr, carries),
                    },
                } });
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {
                const body_result = try self.lowerDiscardedExprStatementAtTypeCell(body);
                const stmt_ids = if (body_result.stmt) |stmt| &[_]DraftStmtId{stmt} else &[_]DraftStmtId{};
                return try self.addExprWithTypeCell(result_cell, .{ .block = .{
                    .statements = try self.addStmtSpan(stmt_ids),
                    .final_expr = switch (body_result.termination) {
                        .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, result_cell),
                        .checked_control_transfer => try self.addExprWithTypeCell(result_cell, .@"unreachable"),
                        .none => try self.continueWithState(result_cell, rest_expr, carries),
                    },
                } });
            },
        }
    }

    fn lowerWhileBodyThenContinue(
        self: *BodyContext,
        body: checked.CheckedExprId,
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        const checked_body = self.view.bodies.expr(body);
        switch (checked_body.data) {
            .block => |block| {
                const previous_statement_success_frames = self.runtime_demand_guard_frames;
                defer self.runtime_demand_guard_frames = previous_statement_success_frames;
                var statements = try self.lowerBlockStatements(block.statements);
                defer self.allocator.free(statements.items);
                if (statementTerminationIsNone(statements.termination)) {
                    const final_result = try self.lowerDiscardedExprStatementAtTypeCell(block.final_expr);
                    if (final_result.stmt) |stmt| try statements.append(self.allocator, stmt);
                    statements.termination = final_result.termination;
                }
                return try self.addExprWithTypeCell(result_cell, .{ .block = .{
                    .statements = try self.addStmtSpan(statements.items[0..statements.len]),
                    .final_expr = switch (statements.termination) {
                        .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, result_cell),
                        .checked_control_transfer => try self.addExprWithTypeCell(result_cell, .@"unreachable"),
                        .none => try self.continueWithCurrentState(result_cell, carries),
                    },
                } });
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {
                const body_result = try self.lowerDiscardedExprStatementAtTypeCell(body);
                const stmt_ids = if (body_result.stmt) |stmt| &[_]DraftStmtId{stmt} else &[_]DraftStmtId{};
                return try self.addExprWithTypeCell(result_cell, .{ .block = .{
                    .statements = try self.addStmtSpan(stmt_ids),
                    .final_expr = switch (body_result.termination) {
                        .uninhabited => |scrutinee| try self.zeroBranchMatchAtTypeCell(scrutinee, result_cell),
                        .checked_control_transfer => try self.addExprWithTypeCell(result_cell, .@"unreachable"),
                        .none => try self.continueWithCurrentState(result_cell, carries),
                    },
                } });
            },
        }
    }

    fn iteratorSkipBranch(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftBranch {
        const rest_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), iterator_cell, null);
        const record_pat = try self.iteratorSkipPayloadPattern(step, iterator_cell, rest_local);
        const tag_pat = try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.step_node), .{ .tag = .{
            .name = try self.builder.tagName(self.view, step.skip_tag),
            .payloads = try self.addPatSpan(&[_]DraftPatId{record_pat}),
        } });
        const rest_expr = try self.addExprWithTypeCell(iterator_cell, .{ .local = rest_local });
        return .{
            .pat = tag_pat,
            .body = try self.continueWithState(result_cell, rest_expr, carries),
        };
    }

    fn iteratorOnePayloadPattern(
        self: *BodyContext,
        item_pattern: checked.CheckedPatternId,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        rest_local: DraftLocalId,
        item_local: ?DraftLocalId,
    ) Allocator.Error!DraftPatId {
        const item_pat = if (item_local) |local|
            try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(step.one_item.node), .{ .bind = local })
        else
            try self.lowerPatternAtNode(item_pattern, step.one_item.node);
        const item_field = self.iteratorRecordDestruct(step.one_item.name, item_pat);
        const rest_field = self.iteratorRecordDestruct(step.one_rest.name, try self.addPatWithTypeCell(iterator_cell, .{ .bind = rest_local }));
        const fields = [_]DraftRecordDestruct{ item_field, rest_field };
        return try self.addPatWithTypeCell(
            DraftTypeCell.fromGraphNode(step.one_payload_node),
            .{ .record = try self.addRecordDestructSpan(&fields) },
        );
    }

    fn iteratorSkipPayloadPattern(
        self: *BodyContext,
        step: IterStepShape,
        iterator_cell: DraftTypeCell,
        rest_local: DraftLocalId,
    ) Allocator.Error!DraftPatId {
        const rest_field = self.iteratorRecordDestruct(step.skip_rest.name, try self.addPatWithTypeCell(iterator_cell, .{ .bind = rest_local }));
        const fields = [_]DraftRecordDestruct{rest_field};
        return try self.addPatWithTypeCell(
            DraftTypeCell.fromGraphNode(step.skip_payload_node),
            .{ .record = try self.addRecordDestructSpan(&fields) },
        );
    }

    fn iteratorRecordDestruct(
        _: *BodyContext,
        field: names.RecordFieldNameId,
        pattern: DraftPatId,
    ) DraftRecordDestruct {
        return .{
            .name = field,
            .pattern = pattern,
        };
    }

    fn pushLoopContext(self: *BodyContext, result_cell: DraftTypeCell, carries: []const LoopCarry) Allocator.Error!void {
        try self.loop_contexts.append(self.allocator, .{
            .result_cell = result_cell,
            .carries = carries,
        });
    }

    fn popLoopContext(self: *BodyContext) void {
        _ = self.loop_contexts.pop();
    }

    fn currentLoopContext(self: *BodyContext) LoopContext {
        if (self.loop_contexts.items.len == 0) Common.invariant("break statement reached Monotype outside an explicit loop expression");
        return self.loop_contexts.items[self.loop_contexts.items.len - 1];
    }

    fn breakCurrentLoopExpr(self: *BodyContext) Allocator.Error!DraftExprId {
        const loop = self.currentLoopContext();
        const data = try self.breakCurrentLoopExprData();
        return try self.addExprWithTypeCell(loop.result_cell, data);
    }

    fn breakCurrentLoopExprData(self: *BodyContext) Allocator.Error!BodyExprData {
        const loop = self.currentLoopContext();
        return if (loop.carries.len == 0)
            .{ .break_ = null }
        else
            .{ .break_ = try self.loopStateExpr(loop.result_cell, loop.carries) };
    }

    fn continueWith(self: *BodyContext, cell: DraftTypeCell, values: []const DraftExprId) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .continue_ = .{
            .values = try self.addExprSpan(values),
        } });
    }

    fn continueWithCurrentState(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        if (carries.len == 0) return try self.continueWith(result_cell, &.{});

        const values = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(values);
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            values[i] = try self.loopCarryCurrentExpr(carry, current, .recursive_feedback);
        }
        return try self.continueWith(result_cell, values);
    }

    fn continueWithState(
        self: *BodyContext,
        result_cell: DraftTypeCell,
        rest_expr: DraftExprId,
        carries: []const LoopCarry,
    ) Allocator.Error!DraftExprId {
        const values = try self.allocator.alloc(DraftExprId, 1 + carries.len);
        defer self.allocator.free(values);
        values[0] = rest_expr;
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            values[i + 1] = try self.loopCarryCurrentExpr(carry, current, .recursive_feedback);
        }
        return try self.continueWith(result_cell, values);
    }

    fn loopStateExpr(self: *BodyContext, result_cell: DraftTypeCell, carries: []const LoopCarry) Allocator.Error!DraftExprId {
        if (carries.len == 0) Common.invariant("empty loop state requested");
        if (carries.len == 1) {
            const current = self.binders.get(carries[0].binder) orelse Common.invariant("loop-carried mutable binder was absent");
            return try self.loopCarryCurrentExpr(carries[0], current, .exit_state);
        }

        const items = try self.allocator.alloc(DraftExprId, carries.len);
        defer self.allocator.free(items);
        for (carries, 0..) |carry, i| {
            const current = self.binders.get(carry.binder) orelse Common.invariant("loop-carried mutable binder was absent");
            items[i] = try self.loopCarryCurrentExpr(carry, current, .exit_state);
        }
        return try self.addExprWithTypeCell(result_cell, .{ .tuple = try self.addExprSpan(items) });
    }

    const LoopCarryFeedback = enum {
        recursive_feedback,
        exit_state,
    };

    fn loopCarryCurrentExpr(
        self: *BodyContext,
        carry: LoopCarry,
        current: DraftLocalId,
        feedback: LoopCarryFeedback,
    ) Allocator.Error!DraftExprId {
        const carry_node = try carry.ty.toGraphNode(self.graph);
        const current_node = try self.localTypeCell(current).toGraphNode(self.graph);
        if (feedback == .recursive_feedback) {
            // A continue edge is producer-authored recursive value flow even
            // when an earlier assignment already joined the current value to
            // the loop parameter. Record the edge itself; representation
            // finalization will force only slots that actually joined distinct
            // minted iterator identities.
            try self.graph.markRecursiveValueSlot(carry_node);
        }
        if (!self.graph.sameClass(carry_node, current_node)) {
            try selectRequestRepresentation(self.graph, carry_node, current_node);
        }
        return try self.addExprWithTypeCell(carry.ty, .{ .local = current });
    }

    fn loopStateTypeCell(self: *BodyContext, unit_ty: Type.TypeId, carries: []const LoopCarry) Allocator.Error!DraftTypeCell {
        if (carries.len == 0) return .{ .sealed = unit_ty };
        if (carries.len == 1) return carries[0].ty;

        const nodes = try self.graph.arena().alloc(NodeId, carries.len);
        for (carries, 0..) |carry, i| nodes[i] = try carry.ty.toGraphNode(self.graph);
        return DraftTypeCell.fromGraphNode(try self.graph.newNode(.{ .tuple = nodes }));
    }

    fn unitType(self: *BodyContext) Allocator.Error!Type.TypeId {
        return try self.builder.program.types.add(.{ .record = .empty() });
    }

    fn prepareLoopCarries(self: *BodyContext, binders: []const checked.PatternBinderId) Allocator.Error![]LoopCarry {
        var carries = std.ArrayList(LoopCarry).empty;
        errdefer carries.deinit(self.allocator);
        for (binders) |binder| {
            const initial = self.binders.get(binder) orelse continue;
            const ty = self.localTypeCell(initial);
            // The loop parameter is an ordinary version of the binder's local:
            // it must carry the binder so closures in the loop body that
            // capture it declare the binder's CaptureId.
            const param_local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), ty, binder);
            try self.bindLocalName(param_local, binder);
            try carries.append(self.allocator, .{
                .binder = binder,
                .initial_local = initial,
                .param_local = param_local,
                .ty = ty,
            });
        }
        return try carries.toOwnedSlice(self.allocator);
    }

    fn finalCarryPattern(self: *BodyContext, carries: []const LoopCarry, result_cell: DraftTypeCell) Allocator.Error!DraftPatId {
        if (carries.len == 0) Common.invariant("empty loop carry pattern requested");
        if (carries.len == 1) {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), carries[0].ty, carries[0].binder);
            try self.bindLocalName(local, carries[0].binder);
            try self.binders.put(carries[0].binder, local);
            return try self.addPatWithTypeCell(result_cell, .{ .bind = local });
        }

        const items = try self.allocator.alloc(DraftPatId, carries.len);
        defer self.allocator.free(items);
        for (carries, 0..) |carry, i| {
            const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), carry.ty, carry.binder);
            try self.bindLocalName(local, carry.binder);
            try self.binders.put(carry.binder, local);
            items[i] = try self.addPatWithTypeCell(carry.ty, .{ .bind = local });
        }
        return try self.addPatWithTypeCell(result_cell, .{ .tuple = try self.addPatSpan(items) });
    }

    fn collectReassignedBindersInExpr(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        out: *std.ArrayList(checked.PatternBinderId),
    ) Allocator.Error!void {
        const expr = self.view.bodies.expr(expr_id);
        switch (expr.data) {
            .str => |segments| for (segments) |segment| try self.collectReassignedBindersInExpr(segment, out),
            .list => |items| for (items) |item| try self.collectReassignedBindersInExpr(item, out),
            .tuple => |items| for (items) |item| try self.collectReassignedBindersInExpr(item, out),
            .match_ => |match| {
                try self.collectReassignedBindersInExpr(match.cond, out);
                for (match.branches) |branch| {
                    if (branch.guard) |guard| try self.collectReassignedBindersInExpr(guard, out);
                    try self.collectReassignedBindersInExpr(branch.value, out);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch| {
                    try self.collectReassignedBindersInExpr(branch.cond, out);
                    try self.collectReassignedBindersInExpr(branch.body, out);
                }
                try self.collectReassignedBindersInExpr(if_.final_else, out);
            },
            .call => |call| {
                try self.collectReassignedBindersInExpr(call.func, out);
                for (call.args) |arg| try self.collectReassignedBindersInExpr(arg, out);
            },
            .record => |record| {
                if (record.ext) |ext| try self.collectReassignedBindersInExpr(ext, out);
                for (record.fields) |field| try self.collectReassignedBindersInExpr(field.value, out);
            },
            .block => |block| {
                for (block.statements) |statement| try self.collectReassignedBindersInStatement(statement, out);
                try self.collectReassignedBindersInExpr(block.final_expr, out);
            },
            .tag => |tag| for (tag.args) |arg| try self.collectReassignedBindersInExpr(arg, out),
            .nominal => |nominal| try self.collectReassignedBindersInExpr(nominal.backing_expr, out),
            .binop => |binop| {
                try self.collectReassignedBindersInExpr(binop.lhs, out);
                try self.collectReassignedBindersInExpr(binop.rhs, out);
            },
            .unary_minus,
            .unary_not,
            .dbg,
            => |child| try self.collectReassignedBindersInExpr(child, out),
            .expect => |child| if (self.builder.inline_expects == .run) {
                try self.collectReassignedBindersInExpr(child, out);
            },
            .expect_err => |expect_err| try self.collectReassignedBindersInExpr(expect_err.expr, out),
            .field_access => |field| try self.collectReassignedBindersInExpr(field.receiver, out),
            .structural_eq => |eq| {
                try self.collectReassignedBindersInExpr(eq.lhs, out);
                try self.collectReassignedBindersInExpr(eq.rhs, out);
            },
            .structural_hash => |h| {
                try self.collectReassignedBindersInExpr(h.value, out);
                try self.collectReassignedBindersInExpr(h.hasher, out);
            },
            .tuple_access => |access| try self.collectReassignedBindersInExpr(access.tuple, out),
            .return_ => |ret| try self.collectReassignedBindersInExpr(ret.expr, out),
            .for_ => |for_| {
                try self.collectReassignedBindersInExpr(for_.expr, out);
                try self.collectReassignedBindersInExpr(for_.body, out);
            },
            .run_low_level => |low_level| for (low_level.args) |arg| try self.collectReassignedBindersInExpr(arg, out),
            .lambda,
            .closure,
            .hosted_lambda,
            .pending,
            .numeral,
            .str_from_quote,
            .str_segment,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .dispatch_call,
            .interpolation,
            .method_eq,
            .type_dispatch_call,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            .break_,
            => {},
        }
    }

    fn collectReassignedBindersInStatement(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        out: *std.ArrayList(checked.PatternBinderId),
    ) Allocator.Error!void {
        const statement = self.view.bodies.statement(statement_id);
        switch (statement.data) {
            .decl => |decl| try self.collectReassignedBindersInExpr(decl.expr, out),
            .var_ => |var_| try self.collectReassignedBindersInExpr(var_.expr, out),
            .var_uninitialized => {},
            .reassign => |reassign| {
                for (reassign.reassigned_binders) |binder| try self.appendUniqueBinder(out, binder);
                try self.collectReassignedBindersInExpr(reassign.expr, out);
            },
            .dbg,
            .expr,
            => |expr| try self.collectReassignedBindersInExpr(expr, out),
            .expect => |expr| if (self.builder.inline_expects == .run) {
                try self.collectReassignedBindersInExpr(expr, out);
            },
            .for_ => |for_| {
                try self.collectReassignedBindersInExpr(for_.expr, out);
                try self.collectReassignedBindersInExpr(for_.body, out);
            },
            .while_ => |while_| {
                try self.collectReassignedBindersInExpr(while_.cond, out);
                try self.collectReassignedBindersInExpr(while_.body, out);
            },
            .infinite_loop => |loop| {
                try self.collectReassignedBindersInExpr(loop.cond, out);
                try self.collectReassignedBindersInExpr(loop.body, out);
            },
            .breakable_loop => |loop| {
                try self.collectReassignedBindersInExpr(loop.cond, out);
                try self.collectReassignedBindersInExpr(loop.body, out);
            },
            .return_ => |ret| try self.collectReassignedBindersInExpr(ret.expr, out),
            .pending,
            .crash,
            .break_,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }

    fn appendUniqueBinder(
        self: *BodyContext,
        out: *std.ArrayList(checked.PatternBinderId),
        binder: checked.PatternBinderId,
    ) Allocator.Error!void {
        for (out.items) |existing| {
            if (existing == binder) return;
        }
        try out.append(self.allocator, binder);
    }

    const IterStepShape = struct {
        step_node: NodeId,
        done_tag: names.TagNameId,
        one_tag: names.TagNameId,
        skip_tag: names.TagNameId,
        one_payload_node: NodeId,
        skip_payload_node: NodeId,
        one_item: IterStepField,
        one_rest: IterStepField,
        skip_rest: IterStepField,
    };

    const IterStepField = struct {
        name: names.RecordFieldNameId,
        node: NodeId,
    };

    fn iteratorStepShape(
        self: *BodyContext,
        plan: static_dispatch.IteratorForPlan,
        iterator_cell: DraftTypeCell,
    ) Allocator.Error!IterStepShape {
        const topology = plan.step_topology;
        const iterator_node = try iterator_cell.toGraphNode(self.graph);
        const step_node = if (self.isGeneratedIteratorEvidenceNode(iterator_node))
            try self.generatedIteratorStepReturnNode(iterator_node)
        else
            try self.lowerTypeNode(plan.step_ty);
        const done_tag_name = try self.builder.tagName(self.view, topology.done_tag);
        const one_tag_name = try self.builder.tagName(self.view, topology.one_tag);
        const skip_tag_name = try self.builder.tagName(self.view, topology.skip_tag);
        try self.requireIteratorStepTagArity(step_node, done_tag_name, 0);
        try self.requireIteratorStepTagArity(step_node, one_tag_name, 1);
        try self.requireIteratorStepTagArity(step_node, skip_tag_name, 1);
        const one_payload_node = try self.graph.tagPayloadNode(step_node, one_tag_name, 0);
        const skip_payload_node = try self.graph.tagPayloadNode(step_node, skip_tag_name, 0);
        try self.constrainCheckedInterfaceToCell(topology.one_payload_ty, DraftTypeCell.fromGraphNode(one_payload_node));
        try self.constrainCheckedInterfaceToCell(topology.skip_payload_ty, DraftTypeCell.fromGraphNode(skip_payload_node));
        const item_field = try self.builder.recordFieldName(self.view, topology.item_field);
        const rest_field = try self.builder.recordFieldName(self.view, topology.rest_field);

        return .{
            .step_node = step_node,
            .done_tag = topology.done_tag,
            .one_tag = topology.one_tag,
            .skip_tag = topology.skip_tag,
            .one_payload_node = one_payload_node,
            .skip_payload_node = skip_payload_node,
            .one_item = .{ .name = item_field, .node = try self.graph.recordFieldNode(one_payload_node, item_field) },
            .one_rest = .{ .name = rest_field, .node = try self.graph.recordFieldNode(one_payload_node, rest_field) },
            .skip_rest = .{ .name = rest_field, .node = try self.graph.recordFieldNode(skip_payload_node, rest_field) },
        };
    }

    fn requireIteratorStepTagArity(
        self: *BodyContext,
        step_node: NodeId,
        tag_name: names.TagNameId,
        expected_arity: usize,
    ) Allocator.Error!void {
        for ((try self.graph.tagRowNodes(step_node)).tags) |tag| {
            if (tag.name != tag_name) continue;
            if (tag.payloads.len != expected_arity) {
                Common.invariant("iterator step tag differed from its checker-recorded payload arity");
            }
            return;
        }
        Common.invariant("iterator step type omitted a checker-recorded tag");
    }

    const LoweredStatement = struct {
        stmt: ?DraftStmtId,
        termination: StatementTermination,
    };

    const LoweredPatternStatement = struct {
        stmt: ?DraftStmt,
        termination: StatementTermination,
    };

    fn lowerStatement(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
        statement_diverges: bool,
    ) Allocator.Error!LoweredStatement {
        const statement = self.view.bodies.statement(statement_id);
        const saved_loc = self.builder.program.current_loc;
        defer self.builder.program.current_loc = saved_loc;
        const saved_region = self.builder.program.current_region;
        defer self.builder.program.current_region = saved_region;
        self.builder.program.current_loc = try self.sourceLocFor(statement.source_region);
        self.builder.program.current_region = statement.source_region;
        var termination: StatementTermination = .none;
        const stmt: DraftStmt = switch (statement.data) {
            .pending,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            => Common.invariant("non-runtime checked statement reached Monotype lowering"),
            .runtime_error => .{ .crash = try self.addStringLiteral("runtime error") },
            .decl => |decl| blk: {
                if (self.statementDeclIsLocalProc(decl.pattern, decl.expr)) {
                    try self.registerLocalProc(decl.pattern, decl.expr, statement_id);
                    const unit_ty = try self.unitType();
                    break :blk .{ .expr = try self.addExpr(.{ .ty = unit_ty, .data = .unit }) };
                }
                const lowered = try self.lowerPatternStatement(decl.pattern, decl.expr, statement.source_region, statement_diverges);
                termination = lowered.termination;
                break :blk lowered.stmt orelse return .{ .stmt = null, .termination = termination };
            },
            .var_ => |decl| blk: {
                const lowered = try self.lowerPatternStatement(decl.pattern, decl.expr, statement.source_region, statement_diverges);
                termination = lowered.termination;
                break :blk lowered.stmt orelse return .{ .stmt = null, .termination = termination };
            },
            .var_uninitialized => |decl| .{ .uninitialized = try self.lowerUninitializedPatternStatement(decl.pattern) },
            .reassign => |decl| blk: {
                const lowered = try self.lowerPatternStatement(decl.pattern, decl.expr, statement.source_region, statement_diverges);
                termination = lowered.termination;
                break :blk lowered.stmt orelse return .{ .stmt = null, .termination = termination };
            },
            .crash => |msg| .{ .crash = try self.lowerStringLiteral(msg) },
            .dbg => |child| .{ .dbg = try self.lowerDbgMessage(child) },
            .expr => |child| try self.lowerExprStatement(child),
            .expect => |child| if (self.builder.inline_expects == .omit) blk: {
                const unit_ty = try self.unitType();
                break :blk .{ .expr = try self.addExpr(.{ .ty = unit_ty, .data = .unit }) };
            } else .{ .expect = try self.lowerExpr(child) },
            .for_ => |for_| blk: {
                var reassigned = std.ArrayList(checked.PatternBinderId).empty;
                defer reassigned.deinit(self.allocator);
                try self.collectReassignedBindersInExpr(for_.body, &reassigned);

                const carries = try self.prepareLoopCarries(reassigned.items);
                defer self.allocator.free(carries);

                const unit_ty = try self.unitType();
                const loop_cell = try self.loopStateTypeCell(unit_ty, carries);
                const expr = try self.addExprWithTypeCell(loop_cell, try self.lowerIteratorFor(for_, loop_cell, carries));
                if (carries.len == 0) break :blk .{ .expr = expr };

                break :blk .{ .let_ = .{
                    .pat = try self.finalCarryPattern(carries, loop_cell),
                    .value = expr,
                } };
            },
            .while_ => |while_| blk: {
                var reassigned = std.ArrayList(checked.PatternBinderId).empty;
                defer reassigned.deinit(self.allocator);
                try self.collectReassignedBindersInExpr(while_.cond, &reassigned);
                try self.collectReassignedBindersInExpr(while_.body, &reassigned);

                const carries = try self.prepareLoopCarries(reassigned.items);
                defer self.allocator.free(carries);

                const unit_ty = try self.unitType();
                const loop_cell = try self.loopStateTypeCell(unit_ty, carries);
                const expr = try self.addExprWithTypeCell(loop_cell, try self.lowerWhile(while_, loop_cell, carries, .checked));
                if (carries.len == 0) break :blk .{ .expr = expr };

                break :blk .{ .let_ = .{
                    .pat = try self.finalCarryPattern(carries, loop_cell),
                    .value = expr,
                } };
            },
            .infinite_loop => |loop| blk: {
                var reassigned = std.ArrayList(checked.PatternBinderId).empty;
                defer reassigned.deinit(self.allocator);
                try self.collectReassignedBindersInExpr(loop.cond, &reassigned);
                try self.collectReassignedBindersInExpr(loop.body, &reassigned);

                const carries = try self.prepareLoopCarries(reassigned.items);
                defer self.allocator.free(carries);

                const unit_ty = try self.unitType();
                const loop_cell = try self.loopStateTypeCell(unit_ty, carries);
                const expr = try self.addExprWithTypeCell(loop_cell, try self.lowerWhile(loop, loop_cell, carries, .always_true));
                if (carries.len == 0) break :blk .{ .expr = expr };

                break :blk .{ .let_ = .{
                    .pat = try self.finalCarryPattern(carries, loop_cell),
                    .value = expr,
                } };
            },
            .breakable_loop => |loop| blk: {
                var reassigned = std.ArrayList(checked.PatternBinderId).empty;
                defer reassigned.deinit(self.allocator);
                try self.collectReassignedBindersInExpr(loop.cond, &reassigned);
                try self.collectReassignedBindersInExpr(loop.body, &reassigned);

                const carries = try self.prepareLoopCarries(reassigned.items);
                defer self.allocator.free(carries);

                const unit_ty = try self.unitType();
                const loop_cell = try self.loopStateTypeCell(unit_ty, carries);
                const expr = try self.addExprWithTypeCell(loop_cell, try self.lowerWhile(loop, loop_cell, carries, .always_true));
                if (carries.len == 0) break :blk .{ .expr = expr };

                break :blk .{ .let_ = .{
                    .pat = try self.finalCarryPattern(carries, loop_cell),
                    .value = expr,
                } };
            },
            .break_ => .{ .expr = try self.breakCurrentLoopExpr() },
            .return_ => |ret| .{ .return_ = try self.lowerReturn(ret) },
        };
        return .{
            .stmt = try self.addStmt(stmt),
            .termination = switch (termination) {
                .none => if (statement_diverges) .checked_control_transfer else .none,
                .checked_control_transfer, .uninhabited => termination,
            },
        };
    }

    fn lowerUninitializedPatternStatement(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
    ) Allocator.Error!DraftPatId {
        const checked_pattern = self.view.bodies.pattern(pattern);
        if (checked_pattern.data != .assign) {
            Common.invariant("checked uninitialized variable pattern was not a binder");
        }
        const node = try self.lowerTypeNode(checked_pattern.ty);
        return try self.lowerShapeFreePatternAtCell(pattern, DraftTypeCell.fromGraphNode(node));
    }

    fn lowerPatternStatement(
        self: *BodyContext,
        pattern: checked.CheckedPatternId,
        expr: checked.CheckedExprId,
        source_region: base.Region,
        statement_diverges: bool,
    ) Allocator.Error!LoweredPatternStatement {
        // A divergent initializer never produces a value to bind, so emitting a
        // pattern or reading the initializer's dead checked type would invent a
        // relation for a value that cannot exist.
        if (statement_diverges) {
            const unit_ty = try self.unitType();
            return .{
                .stmt = .{ .expr = try self.lowerDivergentExprAtType(expr, unit_ty) },
                .termination = .none,
            };
        }
        const requested_cell: DraftTypeCell = if (try self.graphFreeResultTypeForExpr(expr)) |ty|
            .{ .sealed = ty }
        else
            DraftTypeCell.fromGraphNode(try self.lowerExprTypeNode(expr));
        // The checked pattern is explicit evidence for the value's shape.
        // Apply that relation before either the value or a shape-dependent
        // pattern asks for a concrete view of the graph-backed value type.
        switch (requested_cell) {
            .sealed => |ty| try self.requireClosedCheckedType(self.view.bodies.pattern(pattern).ty, ty),
            .graph_node => try self.constrainCheckedInterfaceToCell(self.view.bodies.pattern(pattern).ty, requested_cell),
        }
        const value = try self.lowerExprAtTypeCellWithKnownDivergence(
            expr,
            requested_cell,
            .runtime_value,
            false,
        );
        const produced_cell = self.exprTypeCell(value);
        const value_cell = switch (requested_cell) {
            .sealed => |requested_ty| blk: {
                const produced_ty = switch (produced_cell) {
                    .sealed => |ty| ty,
                    .graph_node => Common.invariant("graph-free closed dispatch produced a graph-backed result"),
                };
                if (!self.sameType(requested_ty, produced_ty)) {
                    Common.invariant("graph-free closed dispatch produced a different sealed result type");
                }
                break :blk produced_cell;
            },
            .graph_node => |requested_node| blk: {
                const produced_node = try produced_cell.toGraphNode(self.graph);
                const completes_request = try self.resultCompletesRequest(requested_node, produced_node);
                const contains_generated_private = try self.graph.containsGeneratedPrivate(produced_node);
                break :blk if (completes_request or contains_generated_private)
                    produced_cell
                else
                    requested_cell;
            },
        };
        const comptime_site = if (self.shouldRecordComptimeSite(.destructure) and self.patternCanMiss(pattern))
            try self.addComptimeSite(.destructure, source_region, self.view.exhaustiveness_sites.lookupByDestructurePattern(pattern), &.{})
        else
            null;
        if (!try self.patternNeedsExplicitBinding(pattern)) {
            const pat = if (self.patternIsShapeFree(pattern))
                try self.lowerShapeFreePatternAtCell(pattern, value_cell)
            else
                try self.lowerPatternAtNode(pattern, try value_cell.toGraphNode(self.graph));
            return .{ .stmt = .{ .let_ = .{
                .pat = pat,
                .value = value,
                .comptime_site = comptime_site,
            } }, .termination = .none };
        }

        const unit_ty = try self.unitType();
        var unit = try self.addExpr(.{ .ty = unit_ty, .data = .unit });
        unit = try self.wrapComptimeBranch(comptime_site, 0, unit);
        const miss = if (comptime_site) |site|
            try self.comptimeExhaustivenessFailedExpr(unit_ty, site)
        else
            try self.runtimeCrashExpr(unit_ty, "pattern match failed");
        return .{
            .stmt = .{ .expr = try self.lowerMaterializedPatternValueThen(
                pattern,
                value,
                value_cell,
                .{ .sealed = unit_ty },
                .{ .expr = unit },
                miss,
                null,
            ) },
            .termination = .none,
        };
    }

    fn patternIsShapeFree(self: *BodyContext, pattern_id: checked.CheckedPatternId) bool {
        return switch (self.view.bodies.pattern(pattern_id).data) {
            .assign, .underscore => true,
            .as => |as| self.patternIsShapeFree(as.pattern),
            .pending, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => false,
        };
    }

    fn lowerShapeFreePatternAtCell(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty_cell: DraftTypeCell,
    ) Allocator.Error!DraftPatId {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (ty_cell) {
            .sealed => |ty| try self.requireClosedCheckedType(pattern.ty, ty),
            .graph_node => |value_node| {
                const pattern_node = try self.instNode(pattern.ty);
                if (!try self.resultCompletesRequest(pattern_node, value_node) or
                    try self.graph.containsGeneratedPrivate(value_node))
                {
                    try self.constrainCheckedInterfaceToCell(pattern.ty, ty_cell);
                }
            },
        }
        const data: BodyPatData = switch (pattern.data) {
            .assign => |binder| .{ .bind = try self.materializePatternBinderAtCell(binder, ty_cell) },
            .as => |as| blk: {
                const local = try self.materializePatternBinderAtCell(as.binder, ty_cell);
                break :blk .{ .as = .{
                    .pattern = try self.lowerShapeFreePatternAtCell(as.pattern, ty_cell),
                    .local = local,
                } };
            },
            .underscore => .wildcard,
            .pending, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => Common.invariant("shape-dependent pattern reached shape-free graph-cell lowering"),
        };
        return try self.addPatWithTypeCell(ty_cell, data);
    }

    fn currentOwnerPatternBinderLocal(
        self: *BodyContext,
        binder: checked.PatternBinderId,
    ) ?DraftLocalId {
        const local = self.binders.get(binder) orelse return null;
        return if (self.draft.currentOwnerOwnsCore(.locals, @intFromEnum(local))) local else null;
    }

    fn materializePatternBinderAtCell(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftLocalId {
        if (self.reuse_pre_registered_pattern_binders) {
            const local = self.currentOwnerPatternBinderLocal(binder) orelse
                Common.invariant("pattern binder was not pre-registered before materialization");
            self.draft.setLocalType(local, cell);
            return local;
        }
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, binder);
        try self.bindLocalName(local, binder);
        try self.binders.put(binder, local);
        return local;
    }

    fn lowerUninhabitedScrutinee(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeWithDemand(expr_id, ty, .uninhabited_result);
    }

    fn lowerUninhabitedScrutineeAtTypeCell(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.lowerExprAtTypeCellWithDemand(expr_id, cell, .uninhabited_result);
    }

    fn lowerExplicitUninhabitedInvocation(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        return try self.zeroBranchMatch(try self.lowerUninhabitedScrutinee(expr_id, ty), ty);
    }

    fn lowerExplicitUninhabitedInvocationAtTypeCell(
        self: *BodyContext,
        expr_id: checked.CheckedExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.zeroBranchMatchAtTypeCell(
            try self.lowerUninhabitedScrutineeAtTypeCell(expr_id, cell),
            cell,
        );
    }

    fn zeroBranchMatch(self: *BodyContext, scrutinee: DraftExprId, ty: Type.TypeId) Allocator.Error!DraftExprId {
        return try self.zeroBranchMatchAtTypeCell(scrutinee, .{ .sealed = ty });
    }

    fn zeroBranchMatchAtTypeCell(
        self: *BodyContext,
        scrutinee: DraftExprId,
        cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        return try self.addExprWithTypeCell(cell, .{ .match_ = .{
            .scrutinee = scrutinee,
            .branches = try self.addBranchSpan(&.{}),
            .comptime_site = null,
        } });
    }

    fn registerLocalProc(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        expr: checked.CheckedExprId,
        context_anchor: checked.CheckedStatementId,
    ) Allocator.Error!void {
        try self.registerLocalProcDeclaration(.{
            .module = self.view.key.bytes,
            .binder = self.localProcBinder(pattern_id),
            .expr = expr,
            .context_anchor = context_anchor,
        });
    }

    fn registerLocalAssociatedProcedures(
        self: *BodyContext,
        statement_id: checked.CheckedStatementId,
    ) Allocator.Error!void {
        var timing_scope = BodyWorkTimingScope.begin(self.builder.timing, .local_proc_context);
        defer timing_scope.end();
        for (self.view.method_registry.entries) |entry| switch (entry.target.kind) {
            .local_proc => |local| {
                if (local.context_anchor == statement_id) {
                    try self.registerLocalProcDeclaration(.{
                        .module = self.view.key.bytes,
                        .binder = local.binder,
                        .expr = local.expr,
                        .context_anchor = local.context_anchor,
                    });
                }
            },
            .procedure, .structural => {},
        };
    }

    fn registerLocalProcDeclaration(
        self: *BodyContext,
        declaration: DraftLocalProcDeclaration,
    ) Allocator.Error!void {
        const address = declaration.address();
        const current = try self.captureLocalProcContext(declaration);
        defer self.releaseLocalProcContext(current);

        if (self.local_proc_contexts.get(address)) |existing_id| {
            const raw_existing = @intFromEnum(existing_id);
            if (raw_existing >= self.draft.local_proc_contexts.items.len) {
                Common.invariant("local procedure binder referenced an unknown declaration context");
            }
            const existing = self.draft.local_proc_contexts.items[raw_existing];
            if (!moduleBytesEqual(existing.declaration.module, declaration.module) or
                existing.declaration.binder != declaration.binder or
                existing.declaration.expr != declaration.expr)
            {
                Common.invariant("local procedure binder named two checked declarations");
            }
            if (!localProcContextEql(existing, current)) {
                Common.invariant("local procedure binder had two declaration contexts");
            }
        } else {
            const context_id: DraftLocalProcContextId = @enumFromInt(@as(u32, @intCast(self.draft.local_proc_contexts.items.len)));
            try self.draft.local_proc_contexts.append(self.allocator, try self.cloneLocalProcContext(current));
            try self.local_proc_contexts.put(address, context_id);
        }
    }

    fn localProcContextId(
        self: *BodyContext,
        view: ModuleView,
        binder: checked.PatternBinderId,
        expr: checked.CheckedExprId,
    ) Allocator.Error!DraftLocalProcContextId {
        const address = DraftLocalProcAddress{ .module = view.key.bytes, .binder = binder, .expr = expr };
        if (self.local_proc_contexts.get(address)) |context| return context;

        const restored = self.restored_local_proc_scope orelse
            Common.invariant("local procedure use reached Monotype before its declaration context");
        var context_anchor: ?checked.CheckedStatementId = null;
        for (view.method_registry.entries) |entry| switch (entry.target.kind) {
            .local_proc => |local| {
                if (local.binder != binder or local.expr != expr) continue;
                if (context_anchor) |existing| {
                    if (existing != local.context_anchor) {
                        Common.invariant("restored local procedure had conflicting checked declaration anchors");
                    }
                } else context_anchor = local.context_anchor;
            },
            .procedure, .structural => {},
        };

        const declaration = DraftLocalProcDeclaration{
            .module = view.key.bytes,
            .binder = binder,
            .expr = expr,
            .context_anchor = context_anchor,
        };
        const context_id: DraftLocalProcContextId = @enumFromInt(@as(u32, @intCast(self.draft.local_proc_contexts.items.len)));
        const entries = try self.allocator.dupe(LexicalBinderEntry, restored.entries);
        self.draft.local_proc_contexts.append(self.allocator, .{
            .declaration = declaration,
            .lexical_owner = self.draft.current_owner,
            .owner_template = self.owner_template,
            .base_key = restored.base_key,
            .restored_specialization_key = restoredLocalProcUseContextKey(restored.base_key, restored.source_context_digest, binder),
            .entries = entries,
            .evidence = self.restoredLocalProcDeclarationEvidence(view, expr),
        }) catch |err| {
            self.allocator.free(entries);
            return err;
        };
        try self.local_proc_contexts.put(address, context_id);
        return context_id;
    }

    fn restoredLocalProcDeclarationEvidence(
        self: *BodyContext,
        view: ModuleView,
        expr: checked.CheckedExprId,
    ) EvidenceChain {
        var site: ?checked.NestedProcSite = null;
        for (view.nested_proc_sites.sites) |candidate| {
            if (candidate.checked_expr == null or candidate.checked_expr.? != expr) continue;
            if (!names.procedureTemplateRefEql(candidate.owner_template, self.owner_template)) continue;
            if (site != null) Common.invariant("restored local procedure matched multiple checked nested sites");
            site = candidate;
        }
        const nested_site = site orelse
            Common.invariant("restored local procedure had no checked nested site");
        const wanted: LexicalDispatchScope = switch (nested_site.lexical_scope) {
            .root => .root,
            .generalized => |scope_id| blk: {
                const raw_scope = @intFromEnum(scope_id);
                if (raw_scope >= view.templates.dispatch_scopes.len) {
                    Common.invariant("restored local procedure nested site named an unknown evidence scope");
                }
                const scope = view.templates.dispatch_scopes[raw_scope];
                break :blk if (scope.checked_expr == expr)
                    (if (scope.parent) |parent| .{ .generalized = parent } else .root)
                else
                    .{ .generalized = scope_id };
            },
        };

        return self.evidence.atScope(.{
            .owner = self.owner_template,
            .lexical = wanted,
        }) orelse Common.invariant("restored local procedure evidence omitted its checked lexical parent");
    }

    fn localProcBinder(self: *BodyContext, pattern_id: checked.CheckedPatternId) checked.PatternBinderId {
        const pattern = self.view.bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .assign => |binder| binder,
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("local procedure declaration pattern was not a binder"),
        };
    }

    fn lowerExprStatement(self: *BodyContext, expr_id: checked.CheckedExprId) Allocator.Error!DraftStmt {
        const merge_binders = try self.stateMergeBinders(expr_id);
        defer self.allocator.free(merge_binders);
        if (merge_binders.len == 0) return .{ .expr = try self.lowerExpr(expr_id) };

        const state_cell = try self.stateOnlyTypeCell(merge_binders);
        const checked_expr = self.view.bodies.expr(expr_id);
        const state_expr = switch (checked_expr.data) {
            .if_ => |if_| try self.addExprWithTypeCell(
                state_cell,
                try self.lowerIfStateOnlyAtTypeCell(if_, state_cell, merge_binders, try self.ifComptimeSite(expr_id, if_)),
            ),
            .match_ => |match| try self.lowerMatchExprWithOutput(match, .{ .state_only = .{
                .state_cell = state_cell,
                .merge_binders = merge_binders,
            } }, try self.matchComptimeSite(expr_id, match)),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => try self.lowerBodyThenStateOnlyAtTypeCell(expr_id, state_cell, merge_binders),
        };
        return .{ .let_ = .{
            .pat = try self.stateOnlyPatternAtTypeCell(state_cell, merge_binders),
            .value = state_expr,
        } };
    }

    fn statementDeclIsLocalProc(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
    ) bool {
        // A local procedure declaration has a named binder. A lambda assigned
        // to an ignored or erroneous pattern remains an ordinary value.
        if (self.view.bodies.pattern(pattern_id).data != .assign) return false;
        return switch (self.view.bodies.expr(expr_id).data) {
            .lambda, .closure => true,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => false,
        };
    }

    fn lowerPatternAtType(self: *BodyContext, pattern_id: checked.CheckedPatternId, ty: Type.TypeId) Allocator.Error!DraftPatId {
        return try self.lowerPatternAtTypeCell(pattern_id, try self.draftTypeCell(ty), ty);
    }

    /// Register every user binder before lowering a continuation that may use
    /// it. Each binder keeps the exact graph cell supplied by the checked
    /// pattern node that the materialized pattern will inspect at runtime.
    fn preRegisterPatternBindersAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!void {
        try self.registerPatternBindersAtNodeInMap(pattern_id, node, &self.binders, false);
    }

    fn registerPatternBindersAtNodeInMap(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
    ) Allocator.Error!void {
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        try self.preRegisterPatternBindersAtNodeInner(pattern_id, node, binders, rebind_existing, &active);
    }

    fn preRegisterPatternBinderAtNode(
        self: *BodyContext,
        binder: checked.PatternBinderId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
    ) Allocator.Error!void {
        if (binders.get(binder)) |existing| {
            if (self.draft.currentOwnerOwnsCore(.locals, @intFromEnum(existing))) {
                if (rebind_existing) {
                    self.draft.setLocalType(existing, DraftTypeCell.fromGraphNode(node));
                    return;
                }
                const existing_node = try self.localTypeCell(existing).toGraphNode(self.graph);
                if (!self.graph.sameClass(existing_node, node)) {
                    Common.invariant("materialized pattern binder was pre-registered at a different graph class");
                }
                return;
            }
        }
        if (rebind_existing) {
            Common.invariant("match pattern binder was not pre-registered before exact record-field/tag-payload binding");
        }
        const cell = DraftTypeCell.fromGraphNode(node);
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, binder);
        try self.bindLocalName(local, binder);
        try binders.put(binder, local);
    }

    fn preRegisterPatternBindersAtNodeInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        binders: *BinderMap,
        rebind_existing: bool,
        active: anytype,
    ) Allocator.Error!void {
        const key: PatternNodeVisit = .{ .pattern = pattern_id, .node = node };
        if (active.contains(key)) {
            Common.invariant("materialized pattern binder prepass repeated a pattern/node visit");
        }
        try active.put(key, {});
        defer _ = active.remove(key);
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| try self.preRegisterPatternBinderAtNode(binder, node, binders, rebind_existing),
            .as => |as| {
                try self.preRegisterPatternBinderAtNode(as.binder, node, binders, rebind_existing);
                try self.preRegisterPatternBindersAtNodeInner(as.pattern, node, binders, rebind_existing, active);
            },
            .applied_tag => |tag| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tag pattern backing did not advance");
                    try self.preRegisterPatternBindersAtNodeInner(pattern_id, backing.node, binders, rebind_existing, active);
                } else {
                    const name = try self.builder.tagName(self.view, tag.name);
                    for (tag.args, 0..) |arg, payload_index| {
                        try self.preRegisterPatternBindersAtNodeInner(
                            arg,
                            try self.graph.tagPayloadNode(node, name, payload_index),
                            binders,
                            rebind_existing,
                            active,
                        );
                    }
                }
            },
            .nominal => |nominal| {
                const backing = self.graph.namedNodes(node).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                if (backing.node == node) Common.invariant("nominal pattern backing did not advance");
                try self.preRegisterPatternBindersAtNodeInner(nominal.backing_pattern, backing.node, binders, rebind_existing, active);
            },
            .record_destructure => |destructs| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal record pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal record pattern backing did not advance");
                    try self.preRegisterPatternBindersAtNodeInner(pattern_id, backing.node, binders, rebind_existing, active);
                } else {
                    for (destructs) |destruct| switch (destruct.kind) {
                        .required, .sub_pattern => |child| {
                            // A destructured OPTIONAL field's binders hold the
                            // slot materialized as Try, so they register at
                            // the sub-pattern's own checked-type node, not
                            // the record's tagged slot node (design.md
                            // "Field Kinds").
                            if ((try self.recordDestructFieldKind(pattern.ty, destruct)) == .optional) {
                                try self.preRegisterPatternBindersAtNodeInner(
                                    child,
                                    try self.instNode(self.view.bodies.pattern(child).ty),
                                    binders,
                                    rebind_existing,
                                    active,
                                );
                                continue;
                            }
                            const name = try self.builder.recordFieldName(self.view, destruct.label);
                            try self.preRegisterPatternBindersAtNodeInner(
                                child,
                                try self.graph.recordFieldNode(node, name),
                                binders,
                                rebind_existing,
                                active,
                            );
                        },
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            const rest_node = try self.recordRestNodeForPattern(node, destructs, rest);
                            try self.preRegisterPatternBindersAtNodeInner(rest, rest_node, binders, rebind_existing, active);
                        },
                    };
                }
            },
            .list => |list| {
                const elem_node = try self.graph.listElementNode(node);
                for (list.patterns) |child| try self.preRegisterPatternBindersAtNodeInner(child, elem_node, binders, rebind_existing, active);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| {
                        try self.preRegisterPatternBindersAtNodeInner(rest_pattern, node, binders, rebind_existing, active);
                    }
                }
            },
            .tuple => |items| {
                if (self.graph.content(node) == .named) {
                    const backing = self.graph.namedNodes(node).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    if (backing.node == node) Common.invariant("nominal tuple pattern backing did not advance");
                    try self.preRegisterPatternBindersAtNodeInner(pattern_id, backing.node, binders, rebind_existing, active);
                } else {
                    const item_nodes = try self.graph.tupleItemNodes(node);
                    if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                    for (items, item_nodes) |item, item_node| {
                        try self.preRegisterPatternBindersAtNodeInner(item, item_node, binders, rebind_existing, active);
                    }
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.preRegisterPatternBindersAtNodeInner(capture, node, binders, rebind_existing, active);
                }
            },
            .pending,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    /// Lower the directly representable shell of a recursively materialized
    /// pattern. Descendants needing runtime field, item, or tag-payload reads
    /// become compiler-local binders and explicit pending plans.
    fn lowerPatternShellAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
    ) Allocator.Error!DraftPatId {
        var active = std.AutoHashMap(PatternNodeVisit, void).init(self.allocator);
        defer active.deinit();
        return try self.lowerPatternShellAtNodeInner(pattern_id, node, pending, &active);
    }

    fn lowerPatternShellAtNodeInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
        active: *std.AutoHashMap(PatternNodeVisit, void),
    ) Allocator.Error!DraftPatId {
        const key: PatternNodeVisit = .{ .pattern = pattern_id, .node = node };
        if (active.contains(key)) {
            Common.invariant("materialized pattern shell repeated an active pattern/node visit");
        }
        try active.put(key, {});
        defer _ = active.remove(key);

        const cell = DraftTypeCell.fromGraphNode(node);
        if (try self.patternRequiresOwnMaterialization(pattern_id)) {
            return try self.lowerPatternPlanPlaceholderAtNode(pattern_id, node, pending);
        }

        const pattern = self.view.bodies.pattern(pattern_id);
        const representation_node = self.constructorRepresentationNode(node);
        const data: BodyPatData = switch (pattern.data) {
            .as => |as| .{ .as = .{
                .pattern = try self.lowerPatternPlanPlaceholderAtNode(as.pattern, node, pending),
                .local = self.currentOwnerPatternBinderLocal(as.binder) orelse
                    Common.invariant("materialized as-pattern binder was not pre-registered"),
            } },
            .applied_tag => |tag| blk: {
                if (self.graph.content(representation_node) == .named) {
                    const backing = self.graph.namedNodes(representation_node).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal tag pattern shell backing did not advance");
                    return try self.addPatWithTypeCell(
                        DraftTypeCell.fromGraphNode(representation_node),
                        .{ .nominal = try self.lowerPatternShellAtNodeInner(pattern_id, backing.node, pending, active) },
                    );
                }
                const name = try self.builder.tagName(self.view, tag.name);
                const payloads = try self.allocator.alloc(DraftPatId, tag.args.len);
                defer self.allocator.free(payloads);
                for (tag.args, 0..) |arg, payload_index| {
                    payloads[payload_index] = try self.lowerPatternPlanPlaceholderAtNode(
                        arg,
                        try self.graph.tagPayloadNode(representation_node, name, payload_index),
                        pending,
                    );
                }
                break :blk .{ .tag = .{ .name = name, .payloads = try self.addPatSpan(payloads) } };
            },
            .nominal => |nominal| {
                if (self.graph.content(representation_node) != .named) {
                    Common.invariant("checked nominal pattern had no nominal graph representation");
                }
                const backing = self.graph.namedNodes(representation_node).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                if (backing.node == representation_node) Common.invariant("nominal pattern shell backing did not advance");
                return try self.addPatWithTypeCell(
                    DraftTypeCell.fromGraphNode(representation_node),
                    .{ .nominal = try self.lowerPatternShellAtNodeInner(nominal.backing_pattern, backing.node, pending, active) },
                );
            },
            .record_destructure => |destructs| blk: {
                if (self.graph.content(representation_node) == .named) {
                    const backing = self.graph.namedNodes(representation_node).backing orelse
                        Common.invariant("nominal record pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal record pattern shell backing did not advance");
                    return try self.addPatWithTypeCell(
                        DraftTypeCell.fromGraphNode(representation_node),
                        .{ .nominal = try self.lowerPatternShellAtNodeInner(pattern_id, backing.node, pending, active) },
                    );
                }
                var lowered = std.ArrayList(DraftRecordDestruct).empty;
                defer lowered.deinit(self.allocator);
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required, .sub_pattern => |child| child,
                        .rest => |rest| {
                            if (self.patternIsIgnored(rest)) continue;
                            Common.invariant("record-rest pattern reached directly representable materialization shell");
                        },
                    };
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    try lowered.append(self.allocator, .{
                        .name = name,
                        .pattern = try self.lowerPatternPlanPlaceholderAtNode(
                            child,
                            try self.graph.recordFieldNode(representation_node, name),
                            pending,
                        ),
                    });
                }
                break :blk .{ .record = try self.addRecordDestructSpan(lowered.items) };
            },
            .tuple => |items| blk: {
                if (self.graph.content(representation_node) == .named) {
                    const backing = self.graph.namedNodes(representation_node).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    if (backing.node == representation_node) Common.invariant("nominal tuple pattern shell backing did not advance");
                    return try self.addPatWithTypeCell(
                        DraftTypeCell.fromGraphNode(representation_node),
                        .{ .nominal = try self.lowerPatternShellAtNodeInner(pattern_id, backing.node, pending, active) },
                    );
                }
                const item_nodes = try self.graph.tupleItemNodes(representation_node);
                if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                const lowered = try self.allocator.alloc(DraftPatId, items.len);
                defer self.allocator.free(lowered);
                for (items, item_nodes, 0..) |item, item_node, index| {
                    lowered[index] = try self.lowerPatternPlanPlaceholderAtNode(item, item_node, pending);
                }
                break :blk .{ .tuple = try self.addPatSpan(lowered) };
            },
            .assign,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            => return try self.lowerPatternAtNode(pattern_id, node),
            .list => unreachable,
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached materialization shell lowering"),
        };
        return try self.addPatWithTypeCell(cell, data);
    }

    fn lowerPatternPlanPlaceholderAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        pending: *std.ArrayList(PendingMaterializedPattern),
    ) Allocator.Error!DraftPatId {
        const cell = DraftTypeCell.fromGraphNode(node);
        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null);
        try pending.append(self.allocator, .{ .pattern = pattern_id, .local = local, .cell = cell });
        return try self.addPatWithTypeCell(cell, .{ .bind = local });
    }

    /// Lower a checked pattern directly from the live graph cells that its
    /// checked type has already related to the match scrutinee. Shape-free
    /// patterns retain the outer cell without inspecting it; constructor
    /// patterns project only the children they explicitly mention.
    fn lowerPatternAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!DraftPatId {
        return try self.lowerPatternAtNodeInner(pattern_id, node, null);
    }

    fn lowerMatchPatternAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        guard: ?DraftExprId,
        body: DraftExprId,
        record_rests: *std.ArrayList(PendingMatchRecordRestBinding),
    ) Allocator.Error!DraftPatId {
        var match_lowering = MatchPatternLowering{
            .guard = guard,
            .body = body,
            .record_rests = record_rests,
        };
        return try self.lowerPatternAtNodeInner(pattern_id, node, &match_lowering);
    }

    fn lowerPatternAtNodeInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        match_lowering: ?*MatchPatternLowering,
    ) Allocator.Error!DraftPatId {
        if (try self.patternNeedsExplicitBinding(pattern_id) and
            !self.allow_recursive_pattern_lowering_for_match)
        {
            Common.invariant("recursively materialized pattern reached ordinary graph pattern lowering");
        }
        const pattern = self.view.bodies.pattern(pattern_id);
        const cell = DraftTypeCell.fromGraphNode(node);
        const representation_node = self.constructorRepresentationNode(node);
        const data: BodyPatData = switch (pattern.data) {
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached graph-native Monotype lowering"),
            .assign => |binder| .{ .bind = try self.materializePatternBinderAtCell(binder, cell) },
            .as => |as| blk: {
                const local = try self.materializePatternBinderAtCell(as.binder, cell);
                break :blk .{ .as = .{
                    .pattern = try self.lowerPatternAtNodeInner(as.pattern, node, match_lowering),
                    .local = local,
                } };
            },
            .applied_tag => |tag| blk: {
                if (self.graph.content(representation_node) == .named) {
                    const backing = self.graph.namedNodes(representation_node).backing orelse
                        Common.invariant("nominal tag pattern had no runtime backing");
                    return try self.addPatWithTypeCell(
                        DraftTypeCell.fromGraphNode(representation_node),
                        .{ .nominal = try self.lowerPatternAtNodeInner(pattern_id, backing.node, match_lowering) },
                    );
                }
                const name = try self.builder.tagName(self.view, tag.name);
                const payloads = try self.allocator.alloc(DraftPatId, tag.args.len);
                defer self.allocator.free(payloads);
                for (tag.args, 0..) |arg, payload_index| {
                    payloads[payload_index] = try self.lowerPatternAtNodeInner(
                        arg,
                        try self.graph.tagPayloadNode(representation_node, name, payload_index),
                        match_lowering,
                    );
                }
                break :blk .{ .tag = .{
                    .name = name,
                    .payloads = try self.addPatSpan(payloads),
                } };
            },
            .nominal => |nominal| {
                if (self.graph.content(representation_node) != .named) {
                    Common.invariant("checked nominal pattern had no nominal graph representation");
                }
                const backing = self.graph.namedNodes(representation_node).backing orelse
                    Common.invariant("nominal pattern had no runtime backing");
                return try self.addPatWithTypeCell(
                    DraftTypeCell.fromGraphNode(representation_node),
                    .{ .nominal = try self.lowerPatternAtNodeInner(nominal.backing_pattern, backing.node, match_lowering) },
                );
            },
            .record_destructure => |destructs| return try self.lowerRecordPatternAtNodeInner(
                pattern_id,
                node,
                destructs,
                match_lowering,
            ),
            .list => |list| blk: {
                const elem_node = try self.graph.listElementNode(node);
                const lowered = try self.allocator.alloc(DraftPatId, list.patterns.len);
                defer self.allocator.free(lowered);
                for (list.patterns, 0..) |child, child_index| {
                    lowered[child_index] = try self.lowerPatternAtNodeInner(child, elem_node, match_lowering);
                }
                const rest: ?DraftListRestPattern = if (list.rest) |rest| .{
                    .index = rest.index,
                    .pattern = if (rest.pattern) |rest_pattern| try self.lowerPatternAtNodeInner(rest_pattern, node, match_lowering) else null,
                } else null;
                break :blk .{ .list = .{
                    .patterns = try self.addPatSpan(lowered),
                    .rest = rest,
                } };
            },
            .tuple => |items| blk: {
                if (self.graph.content(representation_node) == .named) {
                    const backing = self.graph.namedNodes(representation_node).backing orelse
                        Common.invariant("nominal tuple pattern had no runtime backing");
                    return try self.addPatWithTypeCell(
                        DraftTypeCell.fromGraphNode(representation_node),
                        .{ .nominal = try self.lowerPatternAtNodeInner(pattern_id, backing.node, match_lowering) },
                    );
                }
                const item_nodes = try self.graph.tupleItemNodes(representation_node);
                if (items.len != item_nodes.len) Common.invariant("tuple pattern arity differed from graph tuple arity");
                const lowered = try self.allocator.alloc(DraftPatId, items.len);
                defer self.allocator.free(lowered);
                for (items, item_nodes, 0..) |item, item_node, item_index| {
                    lowered[item_index] = try self.lowerPatternAtNodeInner(item, item_node, match_lowering);
                }
                break :blk .{ .tuple = try self.addPatSpan(lowered) };
            },
            .numeral_literal => |num| blk: {
                const ty = try self.activeTypeFromNode(node);
                break :blk try self.lowerNumeralLiteralPattern(num, ty);
            },
            .str_literal => |str| blk: {
                const ty = try self.activeTypeFromNode(node);
                break :blk try self.lowerStringLiteralPattern(str, ty);
            },
            .str_interpolation => |str| try self.lowerStrPattern(str, try self.activeTypeFromNode(node)),
            .underscore => .wildcard,
        };
        return try self.addPatWithTypeCell(cell, data);
    }

    fn lowerRecordPatternAtNodeInner(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
        destructs: []const checked.CheckedRecordDestruct,
        match_lowering: ?*MatchPatternLowering,
    ) Allocator.Error!DraftPatId {
        const cell = DraftTypeCell.fromGraphNode(node);
        const representation_node = self.constructorRepresentationNode(node);
        if (self.graph.content(representation_node) == .named) {
            const backing = self.graph.namedNodes(representation_node).backing orelse
                Common.invariant("nominal record pattern had no runtime backing");
            if (backing.node == representation_node) Common.invariant("nominal record pattern backing did not advance");
            return try self.addPatWithTypeCell(DraftTypeCell.fromGraphNode(representation_node), .{ .nominal = try self.lowerRecordPatternAtNodeInner(
                pattern_id,
                backing.node,
                destructs,
                match_lowering,
            ) });
        }

        var lowered = std.ArrayList(DraftRecordDestruct).empty;
        defer lowered.deinit(self.allocator);
        var source_local: ?DraftLocalId = null;
        const record_checked_ty = self.view.bodies.pattern(pattern_id).ty;
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required, .sub_pattern => |child| {
                    const name = try self.builder.recordFieldName(self.view, destruct.label);
                    if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                        // A destructured OPTIONAL field's sub-pattern is typed
                        // at the nominal Try while the slot holds the tagged
                        // `[#Missing, #Present(v)]` union: translate it into
                        // slot space, queueing binder preludes for the
                        // enclosing branch (design.md "Field Kinds").
                        try lowered.append(self.allocator, .{
                            .name = name,
                            .pattern = try self.lowerOptionalDestructChildAtSlotNode(
                                child,
                                try self.graph.recordFieldNode(representation_node, name),
                                try self.instNode(self.view.bodies.pattern(child).ty),
                            ),
                        });
                        continue;
                    }
                    try lowered.append(self.allocator, .{
                        .name = name,
                        .pattern = try self.lowerPatternAtNodeInner(
                            child,
                            try self.graph.recordFieldNode(representation_node, name),
                            match_lowering,
                        ),
                    });
                },
                .rest => |rest| {
                    if (self.patternIsIgnored(rest)) continue;
                    const lowering = match_lowering orelse
                        Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
                    const rest_data = self.view.bodies.pattern(rest).data;
                    if (rest_data != .assign) Common.invariant("named record rest was not an assignment pattern");
                    const rest_binder = rest_data.assign;
                    const rest_local = self.currentOwnerPatternBinderLocal(rest_binder) orelse
                        Common.invariant("record rest binder was not pre-registered at its exact graph node");
                    const needed_by_guard = if (lowering.guard) |guard|
                        try self.exprDependsOnFreeLocal(guard, rest_local)
                    else
                        false;
                    const needed_by_body = try self.exprDependsOnFreeLocal(lowering.body, rest_local);
                    if (!needed_by_guard and !needed_by_body) continue;

                    const captured = source_local orelse blk: {
                        const local = try self.addLocalWithBinderCell(self.builder.symbols.fresh(), cell, null);
                        source_local = local;
                        break :blk local;
                    };
                    const rest_cell = self.localTypeCell(rest_local);
                    try lowering.record_rests.append(self.allocator, .{
                        .source_local = captured,
                        .source_node = node,
                        .rest_local = rest_local,
                        .rest_node = try rest_cell.toGraphNode(self.graph),
                        .rest_cell = rest_cell,
                        .before_guard = needed_by_guard,
                    });
                },
            }
        }

        const record_pattern = try self.addPatWithTypeCell(cell, .{
            .record = try self.addRecordDestructSpan(lowered.items),
        });
        const captured = source_local orelse return record_pattern;
        return try self.addPatWithTypeCell(cell, .{ .as = .{
            .pattern = record_pattern,
            .local = captured,
        } });
    }

    fn lowerMatchRecordRestBindings(
        self: *BodyContext,
        pending: []const PendingMatchRecordRestBinding,
        original_body: DraftExprId,
    ) Allocator.Error!LoweredMatchRecordRestBindings {
        var guard_bindings = std.ArrayList(DraftStmtId).empty;
        defer guard_bindings.deinit(self.allocator);
        var body_bindings = std.ArrayList(DraftStmtId).empty;
        defer body_bindings.deinit(self.allocator);

        for (pending) |binding| {
            const source_cell = DraftTypeCell.fromGraphNode(binding.source_node);
            const source = try self.addExprWithTypeCell(source_cell, .{ .local = binding.source_local });
            const value = try self.lowerRecordRestValueWithTypeCell(
                source,
                binding.source_node,
                binding.rest_cell,
                binding.rest_node,
            );
            const stmt = try self.addStmt(.{ .let_ = .{
                .pat = try self.addPatWithTypeCell(binding.rest_cell, .{ .bind = binding.rest_local }),
                .value = value,
            } });
            if (binding.before_guard) {
                try guard_bindings.append(self.allocator, stmt);
            } else {
                try body_bindings.append(self.allocator, stmt);
            }
        }

        const body = if (body_bindings.items.len == 0)
            original_body
        else
            try self.addExprWithTypeCell(self.exprTypeCell(original_body), .{ .block = .{
                .statements = try self.addStmtSpan(body_bindings.items),
                .final_expr = original_body,
            } });
        return .{
            .guard_bindings = try self.addStmtSpan(guard_bindings.items),
            .body = body,
        };
    }

    fn lowerConstructorPatternAtNode(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        node: NodeId,
    ) Allocator.Error!DraftPatId {
        const representation_node = self.constructorRepresentationNode(node);
        if (self.graph.content(representation_node) == .named) {
            const backing = self.graph.namedNodes(representation_node).backing orelse
                Common.invariant("nested nominal constructor pattern had no runtime backing");
            return try self.addPatWithTypeCell(
                DraftTypeCell.fromGraphNode(representation_node),
                .{ .nominal = try self.lowerConstructorPatternAtNode(pattern_id, backing.node) },
            );
        }
        return try self.lowerPatternAtNode(pattern_id, node);
    }

    fn lowerPatternAtTypeCell(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty_cell: DraftTypeCell,
        ty: Type.TypeId,
    ) Allocator.Error!DraftPatId {
        const pattern = self.view.bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => {},
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => try self.constrainCheckedInterfaceToCell(pattern.ty, ty_cell),
        }
        const data: BodyPatData = switch (pattern.data) {
            .pending,
            .runtime_error,
            => Common.invariant("non-runtime checked pattern reached Monotype lowering"),
            .assign => |binder| blk: {
                const local = try self.materializePatternBinderAtCell(binder, ty_cell);
                break :blk .{ .bind = local };
            },
            .as => |as| blk: {
                const local = try self.materializePatternBinderAtCell(as.binder, ty_cell);
                break :blk .{ .as = .{
                    .pattern = try self.lowerPatternAtTypeCell(as.pattern, ty_cell, ty),
                    .local = local,
                } };
            },
            .applied_tag => |tag| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, null) };
                }
                break :blk try self.lowerTagPattern(tag, ty);
            },
            .nominal => |nominal| blk: {
                const backing_ty = if (self.builder.nominalConstructionLayer(ty)) |layer|
                    layer.backing
                else
                    self.builder.namedBackingType(ty) orelse ty;
                break :blk .{ .nominal = try self.lowerPatternAtTypeCell(
                    nominal.backing_pattern,
                    try self.draftTypeCell(backing_ty),
                    backing_ty,
                ) };
            },
            .record_destructure => |destructs| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, null) };
                }
                break :blk try self.lowerRecordPattern(pattern.ty, destructs, ty);
            },
            .list => |list| try self.lowerListPattern(list, ty),
            .tuple => |items| blk: {
                if (self.builder.nominalConstructionLayer(ty)) |layer| {
                    break :blk .{ .nominal = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, null) };
                }
                break :blk .{ .tuple = try self.lowerTuplePattern(items, ty) };
            },
            .numeral_literal => |num| try self.lowerNumeralLiteralPattern(num, ty),
            .str_literal => |str| try self.lowerStringLiteralPattern(str, ty),
            .str_interpolation => |str| try self.lowerStrPattern(str, ty),
            .underscore => .wildcard,
        };
        return try self.addPatWithTypeCell(ty_cell, data);
    }

    fn lowerStrPattern(
        self: *BodyContext,
        str: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        const steps = try self.allocator.alloc(DraftStrPatternStep, str.steps.len);
        defer self.allocator.free(steps);

        for (str.steps, 0..) |step, i| {
            steps[i] = .{
                .capture = if (step.capture) |capture| try self.lowerPatternAtType(capture, ty) else null,
                .delimiter = try self.lowerStringLiteral(step.delimiter),
            };
        }

        return .{ .str_pattern = .{
            .prefix = try self.lowerStringLiteral(str.prefix),
            .steps = try self.addStrPatternStepSpan(steps),
            .end = switch (str.end) {
                .exact => .exact,
                .tail => .tail,
            },
        } };
    }

    fn lowerPatternSpanAtTypes(
        self: *BodyContext,
        checked_patterns: []const checked.CheckedPatternId,
        tys: anytype,
    ) Allocator.Error!DraftSpan(DraftPatId) {
        if (checked_patterns.len != GuardedList.borrowLen(tys)) Common.invariant("pattern arity differs from concrete checked type");
        const stable_tys = try GuardedList.dupe(self.allocator, Type.TypeId, tys);
        defer self.allocator.free(stable_tys);
        const lowered = try self.allocator.alloc(DraftPatId, checked_patterns.len);
        defer self.allocator.free(lowered);
        for (checked_patterns, stable_tys, 0..) |child, child_ty, i| {
            lowered[i] = try self.lowerPatternAtType(child, child_ty);
        }
        return try self.addPatSpan(lowered);
    }

    fn lowerTuplePattern(self: *BodyContext, items: []const checked.CheckedPatternId, ty: Type.TypeId) Allocator.Error!DraftSpan(DraftPatId) {
        return try self.lowerPatternSpanAtTypes(items, self.builder.tupleItemTypes(ty));
    }

    fn lowerListPattern(self: *BodyContext, list: anytype, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const elem_ty = self.constListElemType(ty);
        const lowered = try self.allocator.alloc(DraftPatId, list.patterns.len);
        defer self.allocator.free(lowered);
        for (list.patterns, 0..) |child, i| {
            lowered[i] = try self.lowerPatternAtType(child, elem_ty);
        }
        const rest: ?DraftListRestPattern = if (list.rest) |r| .{
            .index = r.index,
            // A captured rest binds the remaining slice, which has the same
            // list type as the scrutinee.
            .pattern = if (r.pattern) |rest_pattern| try self.lowerPatternAtType(rest_pattern, ty) else null,
        } else null;
        return .{ .list = .{
            .patterns = try self.addPatSpan(lowered),
            .rest = rest,
        } };
    }

    fn lowerTagPattern(self: *BodyContext, tag: anytype, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const name = try self.builder.tagName(self.view, tag.name);
        return .{ .tag = .{
            .name = name,
            .payloads = try self.lowerPatternSpanAtTypes(tag.args, self.builder.tagPayloadTypes(ty, name)),
        } };
    }

    /// Lower a structural constructor pattern (tag, record destructure, or
    /// tuple) whose type is nominal: the structural pattern is typed at the
    /// nominal construction backing and wrapped in one explicit `.nominal`
    /// pattern per nominal layer of the type, mirroring constructor
    /// expression lowering so pattern and value representations always
    /// align.
    fn lowerConstructorPatWrapped(
        self: *BodyContext,
        pattern_id: checked.CheckedPatternId,
        ty: Type.TypeId,
        checks_out: ?*std.ArrayList(CollectedListPattern),
    ) Allocator.Error!DraftPatId {
        if (self.builder.nominalConstructionLayer(ty)) |layer| {
            const backing_pat = try self.lowerConstructorPatWrapped(pattern_id, layer.backing, checks_out);
            return try self.addPat(.{ .ty = layer.named, .data = .{ .nominal = backing_pat } });
        }
        const pattern = self.view.bodies.pattern(pattern_id);
        const data: BodyPatData = switch (pattern.data) {
            .applied_tag => |tag| if (checks_out) |checks|
                try self.lowerTagPatternCollectingLists(tag, ty, checks)
            else
                try self.lowerTagPattern(tag, ty),
            .record_destructure => |destructs| if (checks_out) |checks|
                try self.lowerRecordPatternCollectingLists(pattern.ty, destructs, ty, checks)
            else
                try self.lowerRecordPattern(pattern.ty, destructs, ty),
            .tuple => |items| if (checks_out) |checks|
                BodyPatData{ .tuple = try self.lowerPatternSpanAtTypesCollectingLists(items, self.builder.tupleItemTypes(ty), checks) }
            else
                BodyPatData{ .tuple = try self.lowerTuplePattern(items, ty) },
            .pending, .assign, .as, .nominal, .list, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => Common.invariant("nominal constructor pattern lowering reached a non-constructor checked pattern"),
        };
        return try self.addPat(.{ .ty = ty, .data = data });
    }

    fn lowerRecordPattern(self: *BodyContext, record_checked_ty: checked.CheckedTypeId, destructs: []const checked.CheckedRecordDestruct, ty: Type.TypeId) Allocator.Error!BodyPatData {
        var lowered = std.ArrayList(DraftRecordDestruct).empty;
        defer lowered.deinit(self.allocator);
        for (destructs) |destruct| {
            const child = switch (destruct.kind) {
                .required => |pattern| pattern,
                .sub_pattern => |pattern| pattern,
                .rest => |pattern| {
                    if (self.patternIsIgnored(pattern)) continue;
                    Common.invariant("record rest pattern must be lowered to explicit rest-record construction before Monotype output");
                },
            };
            // Optional-field destructs never reach the typed pattern family:
            // the explicit-binding routes and match translation own them
            // (design.md "Field Kinds").
            if ((try self.recordDestructFieldKind(record_checked_ty, destruct)) == .optional) {
                Common.invariant("optional-field record destructure reached typed pattern lowering");
            }
            const name = try self.builder.recordFieldName(self.view, destruct.label);
            const child_ty = switch (destruct.kind) {
                .required, .sub_pattern => self.builder.recordFieldType(ty, name),
                .rest => unreachable,
            };
            try lowered.append(self.allocator, .{
                .name = name,
                .pattern = try self.lowerPatternAtType(child, child_ty),
            });
        }
        return .{ .record = try self.addRecordDestructSpan(lowered.items) };
    }

    fn patternIsIgnored(self: *BodyContext, pattern_id: checked.CheckedPatternId) bool {
        return switch (self.view.bodies.pattern(pattern_id).data) {
            .underscore => true,
            .pending, .assign, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => false,
        };
    }

    /// Specialize a checker-retained generalized numeral pattern at its
    /// concrete Monotype. Builtin numeric primitives consume the parser-owned
    /// exact digits directly; only a genuinely custom target executes the
    /// checker-selected conversion and equality guard.
    fn lowerNumeralLiteralPattern(
        self: *BodyContext,
        numeral: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        return switch (self.builder.shapeContent(ty)) {
            .primitive => try self.numeralPatBits(numeral.literal, ty),
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => if (numeral.conversion) |conversion|
                try self.bindLiteralGuardPattern(conversion, ty)
            else
                Common.invariant("custom numeral pattern had no checked conversion"),
        };
    }

    /// Specialize a checker-retained generalized quote pattern at its concrete
    /// Monotype. Primitive Str uses the literal directly; another primitive
    /// can never match, and a custom target uses the checked conversion guard.
    fn lowerStringLiteralPattern(
        self: *BodyContext,
        str: anytype,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        return switch (self.builder.shapeContent(ty)) {
            .primitive => |primitive| if (primitive == .str)
                .{ .str_lit = try self.lowerStringLiteral(str.literal) }
            else
                try self.bindNeverMatchPattern(ty),
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => if (str.conversion) |conversion|
                try self.bindLiteralGuardPattern(conversion, ty)
            else
                Common.invariant("custom string pattern had no checked conversion"),
        };
    }

    /// Lower a literal pattern on a non-builtin number type to a fresh bind,
    /// recording an equality condition for the enclosing match branch.
    fn bindLiteralGuardPattern(
        self: *BodyContext,
        conversion: checked.CheckedExprId,
        ty: Type.TypeId,
    ) Allocator.Error!BodyPatData {
        const local = try self.addLocal(self.builder.symbols.fresh(), ty);
        try self.pattern_literal_guards.append(self.allocator, .{
            .local = local,
            .ty = ty,
            .check = .{ .conversion = conversion },
        });
        return .{ .bind = local };
    }

    /// Lower a literal pattern whose value its concrete type cannot represent
    /// to a fresh bind guarded by a constant-false condition: the branch
    /// falls through to the next one, exactly as if the scrutinee had been
    /// compared against the unrepresentable value.
    fn bindNeverMatchPattern(self: *BodyContext, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const local = try self.addLocal(self.builder.symbols.fresh(), ty);
        try self.pattern_literal_guards.append(self.allocator, .{
            .local = local,
            .ty = ty,
            .check = .never,
        });
        return .{ .bind = local };
    }

    /// Compare a bound match value against a literal's converted constant,
    /// dispatching to the type's `is_eq` method when it has one and falling
    /// back to structural equality otherwise, mirroring `==`. A never-match
    /// guard is the constant `false` instead.
    fn lowerPatternLiteralEq(self: *BodyContext, entry: PatternLiteralGuard) Allocator.Error!DraftExprId {
        const conversion = switch (entry.check) {
            .conversion => |conversion| conversion,
            .never => return try self.boolLiteral(false, try self.builder.primitiveType(.bool)),
        };
        const scrutinee = try self.localExpr(entry.local, entry.ty);
        const expected = try self.lowerExpr(conversion);
        if (methodOwnerFromType(&self.builder.program.types, entry.ty)) |owner| {
            if (try self.builder.lookupMethodTargetByName(self.method_scope, owner, "is_eq")) |raw_lookup| {
                const lookup = try self.withLocalProcContext(raw_lookup);
                var target_ctx = try self.methodTargetContext(lookup);
                defer target_ctx.deinit();
                const target_fn = target_ctx.checkedFunctionType(lookup.target.callable_ty);
                const bool_ty = try self.builder.lowerType(lookup.view, target_fn.ret);
                const arg_tys = [_]Type.TypeId{ entry.ty, entry.ty };
                const callable_mono_ty = try self.methodTargetMonoTypeFromArgs(lookup, &arg_tys, bool_ty);
                const callee = try self.methodTargetCalleeWithMono(lookup, callable_mono_ty, .synthesize);
                return try self.addExpr(.{ .ty = bool_ty, .data = .{ .call_proc = .{
                    .callee = draftProcCalleeForSlot(callee),
                    .args = try self.addExprSpan(&.{ scrutinee, expected }),
                    .captures = try self.methodTargetCaptureSpan(lookup),
                } } });
            }
        }
        return try self.lowerEqualityExpr(entry.ty, scrutinee, expected, "is_eq", try self.builder.primitiveType(.bool));
    }

    /// Take ownership of the literal-equality conditions collected since
    /// `start`, restoring the collection to that length.
    fn drainPatternLiteralGuards(self: *BodyContext, start: usize) Allocator.Error![]PatternLiteralGuard {
        const drained = try self.allocator.dupe(PatternLiteralGuard, self.pattern_literal_guards.items[start..]);
        self.pattern_literal_guards.shrinkRetainingCapacity(start);
        return drained;
    }

    /// Wrap a match-branch body so it only runs when every collected literal
    /// equality holds, jumping to the branch's miss target otherwise.
    fn applyPatternLiteralGuards(
        self: *BodyContext,
        guards: []const PatternLiteralGuard,
        body: DraftExprId,
        fallback: DraftExprId,
        output_ty: Type.TypeId,
    ) Allocator.Error!DraftExprId {
        var result = body;
        var i = guards.len;
        while (i > 0) {
            i -= 1;
            const eq = try self.lowerPatternLiteralEq(guards[i]);
            result = try self.ifExpr(eq, result, fallback, output_ty);
        }
        return result;
    }

    fn applyPatternLiteralGuardsAtCell(
        self: *BodyContext,
        guards: []const PatternLiteralGuard,
        body: DraftExprId,
        fallback: DraftExprId,
        result_cell: DraftTypeCell,
    ) Allocator.Error!DraftExprId {
        var result = body;
        var index = guards.len;
        while (index > 0) {
            index -= 1;
            const branches = [_]DraftIfBranch{.{
                .cond = try self.lowerPatternLiteralEq(guards[index]),
                .body = result,
            }};
            result = try self.addExprWithTypeCell(result_cell, .{ .if_ = .{
                .branches = try self.addIfBranchSpan(&branches),
                .final_else = fallback,
            } });
        }
        return result;
    }

    /// Conjoin the branch's collected literal-equality conditions with its
    /// (optional) user guard, literal conditions first.
    fn conjoinPatternLiteralGuards(self: *BodyContext, user_guard: ?DraftExprId) Allocator.Error!?DraftExprId {
        if (self.pattern_literal_guards.items.len == 0) return user_guard;
        const bool_ty = try self.builder.primitiveType(.bool);
        var cond = user_guard;
        var i = self.pattern_literal_guards.items.len;
        while (i > 0) {
            i -= 1;
            const eq = try self.lowerPatternLiteralEq(self.pattern_literal_guards.items[i]);
            cond = if (cond) |inner|
                try self.ifExpr(eq, inner, try self.boolLiteral(false, bool_ty), bool_ty)
            else
                eq;
        }
        self.pattern_literal_guards.clearRetainingCapacity();
        return cond;
    }

    /// The pattern flavor of `numeralScalarBits`: an unrepresentable value
    /// lowers to a never-matching branch instead of an expression crash node
    /// (checking reports it; the arm falls through, since e.g. an I8 can
    /// never equal 300).
    fn numeralPatBits(self: *BodyContext, literal: can.ModuleEnv.NumeralLiteral, ty: Type.TypeId) Allocator.Error!BodyPatData {
        const primitive = switch (self.builder.shapeContent(ty)) {
            .primitive => |p| p,
            .named, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => Common.invariant("numeric literal pattern at a non-primitive Monotype type without a conversion"),
        };
        const bits = (try self.numeralScalarBits(literal, primitive)) orelse
            return try self.bindNeverMatchPattern(ty);
        return switch (bits) {
            .int => |value| .{ .int_lit = value },
            .f32 => |value| .{ .frac_f32_lit = value },
            .f64 => |value| .{ .frac_f64_lit = value },
            .dec => |value| .{ .dec_lit = value },
        };
    }
};

/// The exact-numeral target for a numeric Monotype primitive.
fn numeralTargetFromPrimitive(primitive: Type.Primitive) exact_numeral.Target {
    return switch (primitive) {
        .bool, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => Common.invariant("non-numeric Monotype primitive has no numeral target"),
        inline .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => |p| @field(exact_numeral.Target, @tagName(p)),
    };
}

test "sealed record omission takes its default identity from the monotype field" {
    const expected: Type.FieldDefault = .{
        .module = @enumFromInt(17),
        .expr_node = 23,
    };
    const field: Type.Field = .{
        .name = @enumFromInt(5),
        .ty = @enumFromInt(11),
        .default = expected,
    };

    try std.testing.expectEqual(expected, BodyContext.sealedDefaultedFieldIdentity(field));
}

test "record destructure treats a scheme-interior field as required" {
    try std.testing.expectEqual(
        @as(?checked.CheckedFieldKind.Tag, .required),
        BodyContext.recordDestructKindFromResolution(.scheme_interior),
    );
    try std.testing.expectEqual(
        @as(?checked.CheckedFieldKind.Tag, null),
        BodyContext.recordDestructKindFromResolution(.absent),
    );
}

test "open draft recursive provenance joins fresh interface cells only while lowering" {
    const gpa = std.testing.allocator;

    var type_store = Type.Store.init(gpa);
    defer type_store.deinit();
    var name_store = names.NameStore.init(gpa);
    defer name_store.deinit();
    const graph = try InstGraph.create(gpa, &type_store, &name_store);
    defer graph.destroy();
    var draft = BodyDraftStore.init(gpa);
    defer draft.deinit();

    const shared_ret = try graph.newNode(.{ .primitive = .bool });
    const active_arg = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const recursive_ret = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const active_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{active_arg}),
        .ret = shared_ret,
    } });
    const recursive_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{active_arg}),
        .ret = recursive_ret,
    } });
    const shared_frame = RuntimeDemandGuardFrameAddress{
        .module = [_]u8{1} ** 32,
        .owner_module = [_]u8{2} ** 32,
        .owner_proc_base = 3,
        .owner_template = 4,
        .pattern = 5,
        .kind = .match_branch,
    };
    const active_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .never);
    const recursive_proof = try appendRuntimeImpossibilityProof(&draft, gpa, .always);
    var frames = RuntimeDemandGuardFrameStack{};
    frames = try addRuntimeDemandGuardFrame(&draft, frames, shared_frame, active_proof);
    const recursive_frames = try addRuntimeDemandGuardFrame(&draft, frames, shared_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 1), recursive_frames.depth);
    const recursive_head = runtimeDemandGuardFrame(&draft, recursive_frames.head.?);
    try std.testing.expectEqual(active_proof, recursive_head.proof);
    var success_frame = shared_frame;
    success_frame.kind = .pattern_success;
    const success_frames = try addRuntimeDemandGuardFrame(&draft, recursive_frames, success_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 2), success_frames.depth);
    const success_head = runtimeDemandGuardFrame(&draft, success_frames.head.?);
    try std.testing.expectEqual(recursive_proof, success_head.proof);
    try std.testing.expectEqual(recursive_frames.head, success_head.parent);
    var nested_frame = shared_frame;
    nested_frame.pattern += 1;
    frames = try addRuntimeDemandGuardFrame(&draft, recursive_frames, nested_frame, recursive_proof);
    try std.testing.expectEqual(@as(u32, 2), frames.depth);

    try std.testing.expect(!graph.sameFunctionInterface(active_fn, recursive_fn));
    const initial_arg_classes = try graph.snapshotFunctionArgumentClasses(active_fn);
    try std.testing.expect(try draftRequestOverlapsInitialArgumentClass(graph, initial_arg_classes, recursive_fn));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowering, false, false, false));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowering, false, true, false));
    try std.testing.expect(draftOpenCandidateQualifies(.lowering, false, true, true));
    try graph.unify(active_fn, recursive_fn);
    try std.testing.expect(graph.sameFunctionInterface(active_fn, recursive_fn));
    try std.testing.expect(graph.sameClass(shared_ret, recursive_ret));

    const independent_arg = try graph.newNode(.{ .unresolved = InstVariable.checkedVariable(null, .empty_tag_union) });
    const independent_fn = try graph.newNode(.{ .func = .{
        .args = try graph.arena().dupe(NodeId, &.{independent_arg}),
        .ret = shared_ret,
    } });
    try std.testing.expect(!graph.sameFunctionInterface(active_fn, independent_fn));
    try std.testing.expect(!try draftRequestOverlapsInitialArgumentClass(graph, initial_arg_classes, independent_fn));
    try std.testing.expect(!draftOpenCandidateQualifies(.lowered, false, true, true));
    try std.testing.expect(!graph.sameClass(active_arg, independent_arg));

    // An exact request reuses a completed specialization regardless of the
    // requesting guard context; reuses under a different context are recorded
    // and re-verified against the specialization's demands at seal.
    try std.testing.expect(draftOpenCandidateQualifies(.lowered, true, false, false));
}

