    try graph.freezeRelations();
    var finals = GraphTypeFinals.init(graph);
    defer finals.deinit();

    const sealed = try DraftTypeCell.fromGraphNode(node).seal(graph, &finals);
    try std.testing.expect(!try graph.typeHasActiveSnapshots(sealed));
